    try std.testing.expect(!normalized.is_quick);
    try std.testing.expectEqual(false, normalized.chrome_minimal); // 기본 full(0)
    try std.testing.expectEqual(false, normalized.minimal_tabs); // 기본 스크래치(0)
}

