    }
    try expectDropEquivalent(session, 0, .none); // 실제 move 없음 — identity 등가

    // 자기 subtree 안으로의 형제 이동(insert_before∈[m,j]) → moveGroupRange no-op와 등가(제자리·depth 무변).
    try expectDropEquivalent(session, 0, .{ .group_sibling = .{ .insert_before = 2 } });
}

/// SG8c 테스트 헬퍼 — rows에 그 **원본 tab 인덱스**의 카드 row가 있으면 그 depth를 돌려준다(없으면 null). "고스트 존재/사라짐"
/// (원본 tab이 카드 row로 방출됐는가)과 depth 정확성을 함께 본다(카드 .tab=원본 인덱스, 프리뷰 가상순서도 동일).
fn sg8cFindCardDepth(rows: []const chrome.components.sidebar.Row, tab: usize) ?u8 {
    for (rows) |row| switch (row) {
        .agent_toggle, .agent => {},
        .card => |c| if (c.tab == tab) return c.depth,
        .group_header => {},
    };
    return null;
}

/// SG8c 테스트 헬퍼 — rows에서 그 **원본 마커 tab 인덱스**의 group_header row를 돌려준다(없으면 null). collapsed flip·
/// member_count·depth 단언용(헤더 .tab=마커 원본 인덱스).
fn sg8cFindHeader(rows: []const chrome.components.sidebar.Row, tab: usize) ?chrome.components.sidebar.Row {
    for (rows) |row| switch (row) {
        .agent_toggle, .agent => {},
        .group_header => |h| if (h.tab == tab) return row,
        .card => {},
    };
    return null;
}

// SG8c 1급 헤드리스(docs/sidebar-groups.md §9 SG8c): 카드를 **접힌 그룹**에 드롭하는 plan을 프리뷰 투영하면 그 카드
// 고스트가 sidebar_preview_rows에 **강제 방출**된다(원본=커밋 레이아웃 투영에선 접힘 게이트로 사라짐 = SG8이 없애려는
// 증상). 또 타겟 헤더가 collapsed=false로 flip되고(▸ 삼각 아래 카드 보임 모순 방지), member_count가 고스트를 반영하며
// (order-aware), self.tabs는 불변이고, move(순열) 모델이라 preview_rows.len == 원본 rows.len(접힘으로 빠질 행 되메움).
test "SG8c: 카드를 접힌 그룹에 드롭 → preview 고스트 존재(원본은 사라짐)·헤더 flip·member_count 반영·길이 동일·self.tabs 불변" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
    // t0 최상위, A=[t1,t2](마커 t1, depth1) 접힘(§2.1 연속 파티션: 최상위 카드는 첫 마커 이전만).
    try setGroupMarker(session, 1, "A", 1);
    session.tabs.items[1].group_collapsed = true;

    // 라이브(원본) 투영 — t0는 최상위 카드로 보이고(존재), A 헤더는 접힘(t2 숨김). 길이 비교의 기준(move 모델).
    session.recomputeVisibleTabs();
    const live_len = session.sidebar_rows.items.len;
    try std.testing.expect(sg8cFindCardDepth(session.sidebar_rows.items, 0) != null);

    // self.tabs 불변 스냅샷(포인터·순서).
    const n = session.tabs.items.len;
    var before: [8]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    // plan: t0(index0)를 A 안(t2 자리 index2)으로 = 접힌 그룹 안 드롭.
    const plan = AppSession.DropPlan{ .card = .{ .target_tab = 2 } };
    const vl = try session.simulateDrop(0, plan, arena.allocator());

    // (원본=커밋 레이아웃) 프리뷰 예외 없이 가상 order를 그대로 투영하면 t0가 접힘 게이트로 **사라진다**(라이브 확정 시 증상).
    session.projectRowsFrom(vl.order, vl.group_depth);
    try std.testing.expect(sg8cFindCardDepth(session.sidebar_rows.items, 0) == null); // 고스트 예외 없으면 사라짐
    try std.testing.expect(sg8cFindHeader(session.sidebar_rows.items, 1).?.group_header.collapsed); // flip 없음(접힘 그대로)

    // (프리뷰) 고스트 강제 방출 + 헤더 flip + order-aware member_count.
    try session.refreshDragPreview(0, plan, 0, arena.allocator());
    const prows = session.sidebar_preview_rows.items;
    try std.testing.expectEqual(@as(?u8, 1), sg8cFindCardDepth(prows, 0)); // (a) 고스트 존재 + depth 정확(A 안=depth 1)
    const phdr = sg8cFindHeader(prows, 1).?.group_header;
    try std.testing.expect(!phdr.collapsed); // 타겟 헤더 collapsed=false(flip)
    try std.testing.expectEqual(@as(u16, 3), phdr.member_count); // 고스트 반영(t1·t2·t0 = 3, 라이브는 2였음)
    try std.testing.expectEqual(live_len, prows.len); // (d) move(순열) 모델 — 길이 동일

    // 고스트 range(표시-row 도메인)가 실제 고스트 카드 row를 가리킨다(order 위치가 아니라 방출 row 인덱스).
    const dp = session.sidebar_drag_preview.?;
    try std.testing.expect(dp.ghost_lo < dp.ghost_hi);
    try std.testing.expect(prows[dp.ghost_lo] == .card);
    try std.testing.expectEqual(@as(usize, 0), prows[dp.ghost_lo].card.tab);

    // (e) self.tabs 불변(순서·포인터).
    try std.testing.expectEqual(n, session.tabs.items.len);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t);
}

// SG8c 케이스 (b): 펼친 그룹을 다른 펼친 그룹 헤더에 드롭(중첩)하는 plan을 프리뷰 투영하면 옮겨진 subtree 전체가
// 고스트로 방출되고 **상대 depth**가 유지된다(A→B 자식=depth2, A의 자식 C=depth3). 접힘 없음이라 강제 방출은 없지만
// 순열/depth 재투영과 표시-row 고스트 range·길이 동일(move 모델)을 함께 고정한다.
test "SG8c: 펼친 그룹 nest 프리뷰 → subtree 고스트 상대 depth(A=2·C=3)·길이 동일·range" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    // A=[t0,t1] 직접 + C 중첩=[t2,t3](depth2, A 안), B=[t4,t5](depth1, A 형제). (SG8b nest 테스트와 동형 배치)
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "C", 2);
    try setGroupMarker(session, 4, "B", 1);

    session.recomputeVisibleTabs();
    const live_len = session.sidebar_rows.items.len;
    const n = session.tabs.items.len;
    var before: [8]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    // A(m=0)를 B 헤더에 드롭 → B 자식으로 중첩(target_depth=B eff1+1=2, insert_before=groupSubtreeEnd(B)=6).
    const plan = AppSession.DropPlan{ .group_nest = .{ .insert_before = 6, .target_depth = 2 } };
    try session.refreshDragPreview(0, plan, 0, arena.allocator());
    const prows = session.sidebar_preview_rows.items;

    // 상대 depth 유지: A(마커 tab0)=2(B 자식), C(마커 tab2)=3(A 자식). 헤더·카드 모두.
    try std.testing.expectEqual(@as(u8, 2), sg8cFindHeader(prows, 0).?.group_header.depth);
    try std.testing.expectEqual(@as(?u8, 2), sg8cFindCardDepth(prows, 0));
    try std.testing.expectEqual(@as(u8, 3), sg8cFindHeader(prows, 2).?.group_header.depth);
    try std.testing.expectEqual(@as(?u8, 3), sg8cFindCardDepth(prows, 2));
    // B(마커 tab4)는 부모라 depth1 불변.
    try std.testing.expectEqual(@as(u8, 1), sg8cFindHeader(prows, 4).?.group_header.depth);
    try std.testing.expectEqual(live_len, prows.len); // move 모델 — 길이 동일(접힘 없어 순열만)

    // 고스트 range: subtree(A·A직접카드·C) 전체가 표시-row 연속 구간으로 방출됐다(비어있지 않음).
    const dp = session.sidebar_drag_preview.?;
    try std.testing.expect(dp.ghost_lo < dp.ghost_hi);
    try std.testing.expect(sg8cFindHeader(prows[dp.ghost_lo..dp.ghost_hi], 0) != null); // A 헤더가 고스트 구간 안

    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변
    try std.testing.expectEqual(n, session.tabs.items.len);
}

// SG8c 케이스 (c): none plan(제자리·무효)은 고스트가 없다 — preview_rows가 라이브 sidebar_rows와 byte-identical하고
// 프리뷰 ghost range가 비어있다(lo==hi). 프리뷰가 "아무것도 안 옮김"을 정직하게 표시함을 고정한다.
test "SG8c: none plan 프리뷰 → preview_rows == 원본 rows·ghost range 비어있음" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    try setGroupMarker(session, 0, "A", 1); // A=[t0,t1,t2] 전부 한 그룹(펼침)

    session.recomputeVisibleTabs();
    var live: [16]chrome.components.sidebar.Row = undefined;
    const live_len = session.sidebar_rows.items.len;
    try std.testing.expect(live_len > 0 and live_len <= live.len);
    for (session.sidebar_rows.items, 0..) |row, i| live[i] = row;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    try session.refreshDragPreview(0, .none, 0, arena.allocator());
    const prows = session.sidebar_preview_rows.items;

    // preview == 라이브(byte-identical) — 태그·핵심 필드.
    try std.testing.expectEqual(live_len, prows.len);
    for (prows, 0..) |got, i| {
        const want = live[i];
        try std.testing.expectEqual(std.meta.activeTag(want), std.meta.activeTag(got));
        switch (want) {
            .agent_toggle, .agent => {},
            .card => |wc| {
                try std.testing.expectEqual(wc.tab, got.card.tab);
                try std.testing.expectEqual(wc.depth, got.card.depth);
            },
            .group_header => |wh| {
                try std.testing.expectEqual(wh.tab, got.group_header.tab);
                try std.testing.expectEqual(wh.collapsed, got.group_header.collapsed);
                try std.testing.expectEqual(wh.member_count, got.group_header.member_count);
                try std.testing.expectEqual(wh.depth, got.group_header.depth);
            },
        }
    }
    const dp = session.sidebar_drag_preview.?;
    try std.testing.expectEqual(dp.ghost_lo, dp.ghost_hi); // 고스트 없음(range 비어있음)
}

test "code-review #6: 검색 중 접힌 그룹은 헤더도 펼침 표시(collapsed=false) — 강제 펼친 카드와 정합" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
    session.createGroupAbsorbForTab(session.tabs.items[0]); // 전부 한 그룹(연속 파티션)
    session.tabs.items[0].group_collapsed = true; // 그룹 접힘(영속 의도)
    session.tabs.items[1].custom_name = try allocator.dupe(u8, "findme"); // 그룹 안 카드 하나에 매치용 이름

    // 검색 활성 + 매치 쿼리 → 접힘을 일시 무시하고 매치 카드를 펼쳐 보여야 하고(docs §1), 헤더도 펼침 표시(collapsed=false).
    session.sidebar_search_active = true;
    try session.sidebar_search_input.query.appendSlice(allocator, "findme");
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header);
    try std.testing.expect(!session.sidebar_rows.items[0].group_header.collapsed); // 검색 중 = 펼침 표시(삼각 ▾·배지 없음)
    // 매치 카드(t1)가 접힘 무시하고 펼쳐 보인다.
    var saw_t1_card = false;
    for (session.sidebar_rows.items) |row| switch (row) {
        .agent_toggle, .agent => {},
        .card => |c| if (c.tab == 1) {
            saw_t1_card = true;
        },
        .group_header => {},
    };
    try std.testing.expect(saw_t1_card);

    // 검색을 지우면 원래 접힘 상태로 복귀(헤더 collapsed=true, 카드 숨김).
    session.sidebar_search_active = false;
    session.sidebar_search_input.clear();
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed); // 영속 접힘 복원
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len); // 헤더만(카드 접힘)
}

test "SG3c: create_group·헤더 클릭 접기 토글·ungroup·closeTab 마커 승계 (세션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // 탭 3개: [t0, t1, t2]

    // create_group(t0) → group_start 세팅 + projectRows에 group_header(소스 tab=0) 삽입, 아래 카드 depth 1(연속 파티션으로 t0~t2 한 그룹).
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    try std.testing.expect(session.tabs.items[0].group_start != null);
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[0].group_header.tab); // 소스 탭 인덱스(#8·토글 대상)
    try std.testing.expectEqual(@as(u16, 3), session.sidebar_rows.items[0].group_header.member_count);
    try std.testing.expect(session.sidebar_rows.items[1] == .card);
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[1].card.depth); // 그룹 안 들여쓰기

    // 중복 create_group은 no-op(이름 보존).
    const marker_ptr = session.tabs.items[0].group_start.?.ptr;
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    try std.testing.expectEqual(marker_ptr, session.tabs.items[0].group_start.?.ptr);

    // 헤더 클릭(slot 0) → group_collapsed 토글 → 카드 skip(헤더만).
    session.toggleGroupCollapsedAt(0);
    try std.testing.expect(session.tabs.items[0].group_collapsed);
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len); // 헤더만(카드 접힘)
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed);
    session.toggleGroupCollapsedAt(0); // 다시 → 펼침
    try std.testing.expect(!session.tabs.items[0].group_collapsed);

    // closeTab(0): 그룹 시작 탭이 닫히면 마커·접힘·그룹 색이 다음 탭(t1)으로 승계 → 그룹 유지.
    session.tabs.items[0].group_collapsed = true;
    session.tabs.items[0].group_color = 0x4A7BC4; // SG5-2: 그룹 색도 마커 따라 승계돼야 한다
    session.closeTab(0); // [t1, t2]
    try std.testing.expect(session.tabs.items[0].group_start != null); // t1이 마커 승계
    try std.testing.expect(session.tabs.items[0].group_collapsed); // 접힘도 승계
    try std.testing.expectEqual(@as(u32, 0x4A7BC4), session.tabs.items[0].group_color); // 그룹 색 승계(SG5-2)
    try std.testing.expectEqualStrings("그룹 1", session.tabs.items[0].group_start.?);

    // ungroup(t2, 그룹 소속) → 그 위 시작 마커(t1) 제거 → 그룹 소멸.
    session.ungroupTab(session.tabs.items[1]);
    try std.testing.expect(session.tabs.items[0].group_start == null);
}

test "code-review #1: 그룹 헤더 우클릭(context_menu_target=.group) 중 마커 탭 destroy → 대상 클리어(UAF 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    // std.testing.allocator는 leak/UAF 검출 allocator라, teardown 후 dangling *Tab을 남기면 후속 접근이 잡힌다.
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
    const marker_tab = session.tabs.items[0];
    session.createGroupAbsorbForTab(marker_tab); // t0=그룹 시작 마커

    // 그룹 헤더 우클릭 시뮬레이션 — context_menu_target을 마커 탭으로 잡는다(renameTargetAt/8154 경로).
    session.context_menu_target = .{ .group = marker_tab };

    // 마커 탭 destroy: closeTab(0)은 group_start를 t1로 승계하고 marker_tab(*Tab)을 통째 free한다. 옛 코드는
    // .workspace 대상만 클리어해 .group 대상이 dangling으로 남았다(메뉴 accept 시 startRename UAF).
    session.closeTab(0);
    try std.testing.expect(session.context_menu_target == null); // .group 대상이 클리어돼 dangling 없음

    // 메뉴 accept 경로가 stale 대상을 안 건드리는지(null이면 no-op) 확인 — 여기서 UAF면 leak-check가 잡는다.
    session.acceptContextMenu();
    try std.testing.expect(session.context_menu_target == null);
}

test "rename caret 폭은 방출자와 같은 cluster 단위다(NFD 이름에서 IME 후보창이 안 뜬다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    // 회귀(code-review max): CG1이 방출을 cluster 단위로 바꿨는데 caret 폭 산출만 코드포인트 단위
    // (`overlay_input.displayCols`)로 남아 있었다. macOS FS가 주는 NFD '한'(U+1112 U+1161 U+11AB)은
    // **렌더 2칸 / 옛 폭 계산 4칸**이라, 한글 파일을 rename하면 caret과 IME 후보창이 글자에서 ~2배
    // 오른쪽으로 떠 버렸다(5음절이면 10칸). 두 모델이 같은 단위인지를 여기서 고정한다.
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const nfd = "\u{1112}\u{1161}\u{11AB}\u{1100}\u{1173}\u{11AF}"; // NFD "한글"
    session.rename_input.query.clearRetainingCapacity();
    try session.rename_input.query.appendSlice(allocator, nfd);

    // 방출자(appendEllipsizedTitle)가 쓰는 폭 = 음절당 2칸.
    const emitted_cols = chrome.text_layout.displayCols(nfd, null);
    try std.testing.expectEqual(@as(usize, 4), emitted_cols); // 한(2) + 글(2)
    try std.testing.expectEqual(@as(u32, @intCast(emitted_cols)), session.renameQueryCols()); // ★ 같은 단위
    // 완성형과도 같아야 한다(같은 글자니까) — NFD/NFC가 caret 좌표에서 동치.
    try std.testing.expectEqual(
        chrome.text_layout.displayCols("한글", null),
        @as(usize, session.renameQueryCols()),
    );
    // ★ 옛 코드(코드포인트 단위)는 **8칸**을 냈다 — 자모 6개 각각 max(1,cellWidth)로 (2+1+1)+(2+1+1). 실측 확인.
    try std.testing.expect(chrome.components.overlay_input.displayCols(nfd) != session.renameQueryCols());
}

test "code-review #5: 그룹 rename 캐럿이 사이드바 indent_cols를 반영(헤더 삼각/이름과 정렬)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.newTab(); // [t0, t1]
    const marker = session.tabs.items[0];
    session.createGroupAbsorbForTab(marker); // t0 그룹 시작(depth1, 기본 이름 "그룹 1")
    session.startRename(.{ .group = marker }); // 그룹 이름 편집 시작(query=group_start 시드)
    session.recomputeVisibleTabs();

    const cw = session.cell_width_px;
    try std.testing.expect(cw > 0);
    const sp = session.buildChromeTokens().space;
    const indent_cols: u32 = (sp.card_gap_px + sp.accent_bar_width_px + cw - 1) / cw;
    try std.testing.expect(indent_cols > 0); // rich = accent_bar+card_gap>0 — 0이면 이 회귀를 못 잡으므로 전제 확인
    const qcols: u32 = session.renameQueryCols();
    const rect = session.renameCaretRect() orelse return error.NoCaret;
    // depth1(hindent=0): caret_col = indent_cols + 2(삼각+공백) + qcols. 옛 코드는 indent_cols가 빠져(=2+qcols)
    // 캐럿·IME 후보창이 indent_cols칸 왼쪽으로 어긋났다(code-review #5). buildSidebarTitleDrawList의 전역 shift와 정합.
    try std.testing.expectEqual(@as(i32, @intCast((indent_cols + 2 + qcols) * cw)), rect.x);
}

test "remove_from_group: 그룹 소속 카드→최상위(depth0·첫 그룹 앞)·최상위 no-op·마커 카드 승계·마지막 멤버 소멸(주입 조건)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3] 4개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // t1에 그룹 시작 → 연속 파티션으로 group=[t1,t2,t3], t0=최상위.
    session.createGroupAbsorbForTab(t1);
    try std.testing.expect(t1.group_start != null);

    // 주입 조건(tabIsInGroup): 최상위 t0=false, 그룹 소속 t1/t2/t3=true(마커 카드 t1 포함).
    try std.testing.expect(!session.tabIsInGroup(t0));
    try std.testing.expect(session.tabIsInGroup(t1));
    try std.testing.expect(session.tabIsInGroup(t2));
    try std.testing.expect(session.tabIsInGroup(t3));

    // (A) 최상위 카드 no-op: t0에 빼기 → 순서·그룹 불변.
    session.removeFromGroupForTab(t0);
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 제자리
    try std.testing.expect(t1.group_start != null); // 그룹 그대로

    // (B) 그룹 소속 **멤버** 카드 t2 빼기 → 첫 마커(t1) 직전으로 이동 = 최상위(depth 0). 그룹은 [t1,t3]로 유지.
    session.removeFromGroupForTab(t2);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t2)); // 완전 최상위
    try std.testing.expect(t1.group_start != null); // 그룹 유지(멤버 하나만 빠짐)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1)); // t1 여전히 그룹 안
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // t3 여전히 그룹 안
    // t2는 첫 마커(t1)보다 앞: tabs 순서 [t0, t2, t1, t3].
    try std.testing.expect(!session.tabIsInGroup(t2));

    // (C) 그룹 **시작 마커** 카드 t1 빼기 → 마커를 다음 소속 카드(t3)로 승계해 그룹 유지, t1은 최상위.
    session.removeFromGroupForTab(t1);
    try std.testing.expect(t1.group_start == null); // 마커 뗐다
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // t1 최상위
    try std.testing.expect(t3.group_start != null); // t3이 마커 승계 → 그룹 유지
    try std.testing.expectEqualStrings("그룹 1", t3.group_start.?); // 이름 승계(소유권 이전, 누수 없음)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // t3 그룹 시작 카드

    // (D) 마지막 멤버(=마커) t3 빼기 → 승계 대상 없어 그룹 소멸(마커 free — testing allocator 누수 감시). 전부 최상위.
    session.removeFromGroupForTab(t3);
    try std.testing.expect(t3.group_start == null);
    try std.testing.expect(session.firstGroupStartIndex() == null); // 그룹 전무
    try std.testing.expect(!session.tabIsInGroup(t3));
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t3));
}

test "SG5-3: 2단계 중첩(A>B) — projectRows depth 0/1/2·헤더 depth·member_count·부모 직접카드가 자식 앞 제약" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4] 5개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];

    // 구조: t0=최상위, A=t1(depth1)·직접카드 t1,t2, B=t3(depth2, A 안 중첩)·직접카드 t3,t4.
    // create_group 위치 파생: t1은 최상위 카드 → A depth 1. t3은 A 안 카드(depth1) → B depth 2(중첩).
    session.createGroupAbsorbForTab(t1);
    session.createGroupAbsorbForTab(t3);
    try std.testing.expectEqual(@as(u8, 2), t3.group_depth); // t3 create가 중첩 depth 2

    session.recomputeVisibleTabs();
    // 기대 rows: [card t0(d0), header A(d1), card t1(d1), card t2(d1), header B(d2), card t3(d2), card t4(d2)]
    const rows = session.sidebar_rows.items;
    try std.testing.expectEqual(@as(usize, 7), rows.len);
    try std.testing.expect(rows[0] == .card and rows[0].card.tab == 0 and rows[0].card.depth == 0); // 최상위
    try std.testing.expect(rows[1] == .group_header and rows[1].group_header.tab == 1 and rows[1].group_header.depth == 1); // A 헤더 depth1
    try std.testing.expectEqual(@as(u16, 2), rows[1].group_header.member_count); // A 직접카드 = t1,t2 (자식 B 카드 제외)
    try std.testing.expect(rows[2].card.depth == 1 and rows[2].card.tab == 1); // A 마커 카드
    try std.testing.expect(rows[3].card.depth == 1 and rows[3].card.tab == 2); // A 직접카드
    try std.testing.expect(rows[4] == .group_header and rows[4].group_header.tab == 3 and rows[4].group_header.depth == 2); // B 헤더 depth2(중첩)
    try std.testing.expectEqual(@as(u16, 2), rows[4].group_header.member_count); // B 직접카드 = t3,t4
    try std.testing.expect(rows[5].card.depth == 2 and rows[5].card.tab == 3); // B 마커 카드 depth2
    try std.testing.expect(rows[6].card.depth == 2 and rows[6].card.tab == 4); // B 직접카드 depth2

    // 부모 직접카드가 자식 앞 제약(§2.1 다단계): A의 depth1 카드(row2,3)가 B 헤더(row4)보다 앞. 자식 뒤 부모 복귀 없음.
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0));
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1));
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t3));
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t4));
}

test "SG5-3: 다단계 접기 — 부모 A 접으면 자식 B와 그 카드 통째 숨김·자식 B만 접으면 B 카드만 숨김" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 4개
    // A=t0(depth1)·카드 t0,t1, B=t2(depth2 중첩)·카드 t2,t3.
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    session.createGroupAbsorbForTab(session.tabs.items[2]);
    try std.testing.expectEqual(@as(u8, 2), session.tabs.items[2].group_depth);

    // 펼침 전체: [hA, c t0, c t1, hB, c t2, c t3] = 6 rows.
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 6), session.sidebar_rows.items.len);

    // ── 자식 B만 접기: B 카드(t2,t3)만 숨김, B 헤더는 남고 A는 그대로. [hA, c t0, c t1, hB(collapsed)] = 4 rows.
    session.tabs.items[2].group_collapsed = true;
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 4), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header); // A 헤더
    try std.testing.expect(session.sidebar_rows.items[3] == .group_header and session.sidebar_rows.items[3].group_header.collapsed); // B 접힘 헤더 남음
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[3].group_header.member_count); // (N)=B 직접카드 2
    session.tabs.items[2].group_collapsed = false;

    // ── 부모 A 접기: 자식 B 헤더까지 통째 숨김(부모 접기=자식 그룹 통째 숨김). [hA(collapsed)] = 1 row.
    session.tabs.items[0].group_collapsed = true;
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header and session.sidebar_rows.items[0].group_header.collapsed);
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[0].group_header.member_count); // A 직접카드 2(자식 그룹 카드 제외)

    // ── 둘 다 접힘: 여전히 A 헤더 하나만(부모 접힘이 자식 헤더를 가림 — B 접힘 무관).
    session.tabs.items[2].group_collapsed = true;
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);
}

test "SG5-3: ungroup 중첩 — 자식 ungroup은 부모로 재소속·부모 ungroup은 자식이 최상위로 승격(gap 클램프)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    // A=t0(depth1)·t0,t1, B=t2(depth2 중첩)·t2,t3.
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    session.createGroupAbsorbForTab(t2);

    // ── 자식 B ungroup(t3 소속=B) → 가장 가까운 마커 B 제거 → t2,t3가 부모 A로 재소속(depth 1).
    session.ungroupTab(t3);
    try std.testing.expect(session.tabs.items[2].group_start == null); // B 마커 제거
    try std.testing.expect(session.tabs.items[0].group_start != null); // A 유지
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // A로 재소속(depth 1)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3));

    // 다시 B를 중첩 생성한 뒤, 부모 A ungroup → A 마커 제거 → t0,t1 최상위·B는 부모 없어 gap 클램프로 depth 1(최상위 그룹) 승격.
    session.createGroupAbsorbForTab(t2); // B 재생성(depth 2)
    try std.testing.expectEqual(@as(u8, 2), t2.group_depth);
    session.ungroupTab(session.tabs.items[0]); // A(t0) 마커 제거
    try std.testing.expect(session.tabs.items[0].group_start == null); // A 제거
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, session.tabs.items[1])); // 옛 A 카드 t1 → 최상위
    // B는 저장 depth 2지만 부모가 없어 projectRows가 depth 1로 정규화(gap 클램프) → 최상위 그룹.
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));
}

test "SG5-3: create_sibling_group(형제 같은 depth) vs create_group(중첩 depth+1) — 명시적 분리" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 4개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // ── 최상위 카드에서 두 액션은 결과 동일(depth 1). t0에 create_sibling_group → depth 1(create_group과 동일).
    session.createSiblingGroupAbsorbForTab(t0);
    try std.testing.expectEqual(@as(u8, 1), t0.group_depth);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 최상위 그룹 A

    // 이제 t0=그룹 A(depth1, [t0..t3] 전부). 그룹 안 카드 t2에서 두 액션을 대비한다.
    // ── create_group(t2) = **중첩**: t2 현재 depth 1 → B depth 2(A 자식). t3도 B(depth 2).
    session.createGroupAbsorbForTab(t2);
    try std.testing.expectEqual(@as(u8, 2), t2.group_depth); // 중첩 = depth+1
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t2)); // 중첩 자식
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t3)); // B 몸통(중첩)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1)); // A 직접카드는 그대로 depth 1

    // t2 그룹을 풀고(원복) 이번엔 create_sibling_group으로 대비.
    session.ungroupTab(t2); // B 마커 제거 → t2,t3 다시 A(depth1)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));

    // ── create_sibling_group(t2) = **형제**: t2 현재 depth 1 → C depth 1(A와 같은 depth 형제, 중첩 아님). t3도 C(depth 1).
    session.createSiblingGroupAbsorbForTab(t2);
    try std.testing.expectEqual(@as(u8, 1), t2.group_depth); // 형제 = 같은 depth
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // 형제 그룹 C(최상위, 중첩 아님)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // C 몸통(depth 1, 중첩 아님)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // A 유지

    // 연속 파티션: [A: t0,t1][C: t2,t3] 두 형제 최상위 그룹. 헤더 depth로 확인(둘 다 depth 1 = 중첩 아님).
    session.recomputeVisibleTabs();
    var header_depths: [4]u8 = undefined;
    var hc: usize = 0;
    for (session.sidebar_rows.items) |row| switch (row) {
        .agent_toggle, .agent => {},
        .group_header => |gh| {
            if (hc < header_depths.len) header_depths[hc] = gh.depth;
            hc += 1;
        },
        .card => {},
    };
    try std.testing.expectEqual(@as(usize, 2), hc); // 그룹 헤더 2개(A·C)
    try std.testing.expectEqual(@as(u8, 1), header_depths[0]); // A 최상위
    try std.testing.expectEqual(@as(u8, 1), header_depths[1]); // C 최상위 형제(중첩 아님 — 이게 tension 해소)
}

test "SG4: 카드 드래그 넣기/빼기 — drop row→탭 매핑 + 위치 파생 소속 + 연속 파티션 (moveTab 직접)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // 탭 4개: [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 그룹 A를 t2에서 시작 → t2·t3가 그룹 A(연속), t0·t1은 최상위(§2.1 첫 마커 이전 구간).
    session.createGroupAbsorbForTab(t2);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // 그룹 A 마커 카드
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // 그룹 A 몸통

    // rows(펼침): [card t0(d0), card t1(d0), header A(tab2), card t2(d1), card t3(d1)].
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 5), session.sidebar_rows.items.len);

    // ── ① 넣기(그룹 A 몸통 카드에 드롭): t0(최상위)를 t3(=row4, tab index 3)에 드롭 → moveTab이 t3 자리로.
    //    핸들러와 동형: sidebarGroupDropTargetTab(raw_row, from) → moveTab(from, target).
    {
        const from: usize = 0; // t0
        const target = session.sidebarGroupDropTargetTab(4, from).?; // 카드 row → 그 카드 탭(3)
        try std.testing.expectEqual(@as(usize, 3), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t1, t2(mk A), t3, t0] — t0가 그룹 A 안으로(위치 파생). 연속 파티션: 최상위=[t1], A=[t2,t3,t0].
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    try std.testing.expectEqual(t2, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t0, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 넣기 성공 = depth 1
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // t1 여전히 최상위

    // ── ② 빼기(최상위 카드에 드롭): t0(그룹 A, index 3)를 t1(최상위, row0=tab index 0)에 드롭 → 최상위 구간으로.
    {
        const from: usize = 3; // t0 현재 인덱스
        const target = session.sidebarGroupDropTargetTab(0, from).?; // 최상위 카드 row → tab 0
        try std.testing.expectEqual(@as(usize, 0), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t0, t1, t2(mk A), t3] — t0가 첫 마커(t2@2) 이전으로 빠져 최상위. A=[t2,t3].
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 빼기 성공 = depth 0

    // ── ③ 넣기(펼친 그룹 헤더에 드롭, from<M): t1(최상위, index1)을 그룹 A 헤더(row2)에 → 그룹 최상단(마커 직후).
    session.recomputeVisibleTabs(); // rows: [card t0(d0), card t1(d0), header A(tab2), card t2(d1), card t3(d1)]
    {
        const from: usize = 1; // t1
        const target = session.sidebarGroupDropTargetTab(2, from).?; // 펼친 헤더 m=2, from<m → to=m=2
        try std.testing.expectEqual(@as(usize, 2), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t0, t2(mk A), t1, t3] — t1이 마커 직후(A 최상단). A=[t2,t1,t3], 최상위=[t0].
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t2, session.tabs.items[1]);
    try std.testing.expectEqual(t1, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1)); // 그룹 안

    // ── ④ 접힌 그룹 헤더에 드롭 → 그룹 끝에 추가(§10, 드롭 위치가 안 보이니 끝). t0를 접힌 A 헤더에.
    session.tabs.items[1].group_collapsed = true; // t2가 마커(index1) — 접기
    session.recomputeVisibleTabs(); // rows: [card t0(d0), header A(tab1, collapsed)]
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[1].group_header.collapsed);
    {
        const from: usize = 0; // t0
        const target = session.sidebarGroupDropTargetTab(1, from).?; // 접힌 헤더 → 그룹 끝(연속 파티션 [1,4)의 j-1=3)
        try std.testing.expectEqual(@as(usize, 3), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t2(mk A), t1, t3, t0] — t0가 그룹 A 끝. A=[t2,t1,t3,t0] 전부(최상위 없음).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[3]); // 그룹 끝
    // 펼쳐서 확인: t0는 그룹 안(depth 1)·마지막 카드.
    session.tabs.items[0].group_collapsed = false;
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0));
    // 연속 파티션 불변식: 마커는 index 0 하나뿐, 나머지 전부 그 그룹(중간에 최상위로 안 쪼개짐).
    var marker_count: usize = 0;
    for (session.tabs.items) |t| if (t.group_start != null) {
        marker_count += 1;
    };
    try std.testing.expectEqual(@as(usize, 1), marker_count);
}

test "code-review #2: 접힌 marker-only 그룹에 아래 카드 드롭(from>m) → 그룹 안(마커 뒤)에 들어간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // A=t1(그룹 시작), B=t2(형제 그룹 시작 같은 depth) → A는 marker-only([1,2))·B=[2,4)(t2,t3). A를 접는다.
    session.createGroupAbsorbForTab(t1); // A depth1, 연속상 [1,4)
    session.createSiblingGroupAbsorbForTab(t2); // t2 형제 마커(depth1) → A=[1,2) marker-only, B=[2,4)
    t1.group_collapsed = true;
    session.recomputeVisibleTabs();
    // rows: [card t0, header A(tab1,collapsed), header B(tab2), card t2(d1), card t3(d1)]
    try std.testing.expect(session.sidebar_rows.items[1].group_header.collapsed);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items[1].group_header.tab); // A 마커=t1

    // 아래 카드 t3(index 3, from>m=1)을 접힌 A 헤더(row1)에 드롭. 옛 코드는 j-1=1=m → moveTab(3,1)로 마커 앞에
    // 떨궈 t3가 최상위로 샜다. 수정 후 to=@min(j=2,len-1)=2 → 마커(t1@1) 뒤로.
    const from: usize = 3;
    const target = session.sidebarGroupDropTargetTab(1, from).?;
    try std.testing.expectEqual(@as(usize, 2), target);
    _ = session.moveTab(from, target);

    // 결과 [t0, t1(A), t3, t2(B)] — t3가 마커 A 바로 뒤(그룹 안). A=[1,3)=(t1,t3), B=[3,4)=(t2).
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    // t3는 그룹 A 안(depth1) — 펼쳐서 확인(접힌 상태론 숨겨져 null).
    t1.group_collapsed = false;
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // 밖으로 안 샘 = 그룹 안
}

test "code-review #3: pane grip을 그룹 헤더에 드롭 → 새 워크스페이스 안 생김(no-op)·카드=merge·빈 영역=new_workspace" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2], 활성=t2(마지막 생성)
    session.createGroupAbsorbForTab(session.tabs.items[1]); // t1=그룹 시작 → rows: [card t0, header(t1), card t1, card t2]
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[1] == .group_header);

    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const header_row_h = session.sidebar_header_row_h_px;
    const slot_h = session.sidebar_slot_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 그룹 헤더 row(index 1) 중앙 y에 pane grip 드롭 → **null(no-op)**. 옛 코드는 new_workspace로 falls through했다.
    const hdr_top = sb.rowTop(session.sidebar_rows.items, 1, header_h, session.sidebarMetrics(), 0);
    const hdr_y: f64 = @floatFromInt(hdr_top + @as(i64, @intCast(header_row_h / 2)));
    try std.testing.expect(session.computePaneDropDest(x, hdr_y) == null); // 헤더 드롭 = 무동작

    // 비활성 카드 row(index 0 = t0) → merge(그 워크스페이스에 합치기).
    const card_top = sb.rowTop(session.sidebar_rows.items, 0, header_h, session.sidebarMetrics(), 0);
    const card_y: f64 = @floatFromInt(card_top + @as(i64, @intCast(sb.rowHeight(session.sidebar_rows.items[0], session.sidebarMetrics()) / 2)));
    const dest = session.computePaneDropDest(x, card_y);
    try std.testing.expect(dest != null and dest.? == .merge);

    // 리스트 아래 빈 영역(past-end) → new_workspace(자연스러운 "빈 영역=새 워크스페이스" 보존).
    const past_end = sb.rowTop(session.sidebar_rows.items, session.sidebar_rows.items.len, header_h, session.sidebarMetrics(), 0);
    const below_y: f64 = @floatFromInt(past_end + @as(i64, @intCast(slot_h)));
    const dest2 = session.computePaneDropDest(x, below_y);
    try std.testing.expect(dest2 != null and dest2.? == .new_workspace);
}

test "드래그앤드롭 pane 라우팅: routeDropAtPoint가 떨어뜨린 pane을 활성으로 (활성 pane 고정 회귀)" {
    // 이 테스트가 증명하는 것: 파일/이미지 드롭이 **활성 pane이 아니라 떨어뜨린 pane**으로 들어간다는 계약.
    // 실제 회귀: 어느 pane에 떨어뜨려도 항상 활성 pane에만 삽입됐다(Swift performDragOperation이 드롭 좌표를
    // 버리고 pasteboard만 넘겼다). 삽입 자체는 기존 paste 경로(활성 surface 대상)를 그대로 쓰므로, 라우팅은
    // "삽입 전에 그 pane을 활성으로 만든다"로 표현된다 — 이 함수가 그 유일한 진입점이다(ABI v115).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // split은 backing이 잡혀야 의미 있다(termRect 입력) — resized 창을 흉내(위 split 테스트와 같은 규율).
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    try session.splitActivePane(.horizontal); // 좌우 2 pane, 활성 = 새로 생긴 pane
    const tab = session.activeTab();
    try std.testing.expectEqual(@as(usize, 2), tab.panes.items.len);

    var leaf_rects: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaf_rects.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaf_rects);
    try std.testing.expectEqual(@as(usize, 2), leaf_rects.items.len);

    // 각 pane의 중앙에 "드롭"하면 그 pane이 활성이 된다 — 활성이 아니던 pane도 포함(핵심 회귀).
    for (leaf_rects.items) |lr| {
        const cx: f64 = @floatFromInt(lr.rect.x + @as(i64, @intCast(lr.rect.w / 2)));
        const cy: f64 = @floatFromInt(lr.rect.y + @as(i64, @intCast(lr.rect.h / 2)));
        try std.testing.expectEqual(AppSession.DropRoute.routed, session.routeDropAtPoint(cx, cy));
        try std.testing.expectEqual(lr.leaf, session.activePane()); // 떨어뜨린 pane이 활성
    }

    // 사이드바 위 드롭 → not_applicable = 활성 pane 폴백(기존 동작 보존, 이번 범위 밖). **거부가 아니다** —
    // 호스트는 그대로 활성 pane에 삽입한다(거부와 섞으면 사이드바 드롭이 통째로 무시된다).
    const before = session.activePane();
    const sidebar_x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    try std.testing.expectEqual(AppSession.DropRoute.not_applicable, session.routeDropAtPoint(sidebar_x, 100));
    try std.testing.expectEqual(before, session.activePane()); // 활성 pane 불변
}

test "드롭 라우팅: Term 탭 위 드롭은 **그 Term**까지 활성으로 (pane까지만 라우팅하면 엉뚱한 Term에 들어간다)" {
    // 탭 바는 Term 단위인데 pane까지만 라우팅하면, 특정 Term 탭에 떨어뜨려도 그 pane의 *현재* 활성 Term에
    // 들어간다(code-review). dropTermIndexAt이 클릭 경로(renameTargetAt)와 같은 기하로 그 Term을 집는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 60,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 900;
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // 한 pane에 Term 3개(탭 3개). 활성은 마지막에 만든 것.
    session.dispatchAppAction(.new_term);
    session.dispatchAppAction(.new_term);
    const pane = session.activePane();
    try std.testing.expectEqual(@as(usize, 3), pane.terms.items.len);
    session.focusTerm(2);
    try std.testing.expectEqual(@as(usize, 2), pane.active_term);

    var leaf_rects: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaf_rects.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaf_rects);
    const rect = leaf_rects.items[0].rect;
    const pb = session.paneBar(rect, pane) orelse return error.SkipZigTest;
    const bar_y: f64 = @floatFromInt(pb.tabs.y + pb.tabs.h / 2);

    // 탭 바를 훑어 각 Term 탭의 한 지점을 찾는다(내부 기하에 의존하지 않고 hit-test 자체로 — 클릭 경로와 같은 함수).
    var x0: ?f64 = null;
    var x1: ?f64 = null;
    var px: u32 = pb.tabs.x;
    while (px < pb.tabs.x + pb.tabs.w) : (px += 2) {
        const fx: f64 = @floatFromInt(px);
        const hit = session.dropTermIndexAt(pane, leaf_rects.items, fx, bar_y) orelse continue;
        if (hit == 0 and x0 == null) x0 = fx;
        if (hit == 1 and x1 == null) x1 = fx;
    }
    const tab0_x = x0 orelse return error.SkipZigTest; // 바가 너무 좁으면(탭 미표시) 스킵
    const tab1_x = x1 orelse return error.SkipZigTest;

    // **0번 Term 탭**에 드롭 → 활성 Term이 0이 된다(활성이던 2가 아니라).
    try std.testing.expectEqual(AppSession.DropRoute.routed, session.routeDropAtPoint(tab0_x, bar_y));
    try std.testing.expectEqual(@as(usize, 0), pane.active_term); // ★ 떨어뜨린 Term이 활성

    // 1번 Term 탭 → 1번이 활성.
    try std.testing.expectEqual(AppSession.DropRoute.routed, session.routeDropAtPoint(tab1_x, bar_y));
    try std.testing.expectEqual(@as(usize, 1), pane.active_term);

    // pane **본문**(탭 바 아래) 드롭 → Term은 안 바뀐다(그 pane의 현재 활성 Term이 대상).
    const body_y: f64 = @floatFromInt(rect.y + rect.h - 10);
    const body_x: f64 = @floatFromInt(rect.x + rect.w / 2);
    try std.testing.expect(session.dropTermIndexAt(pane, leaf_rects.items, body_x, body_y) == null);
    try std.testing.expectEqual(AppSession.DropRoute.routed, session.routeDropAtPoint(body_x, body_y));
    try std.testing.expectEqual(@as(usize, 1), pane.active_term); // 불변
}

test "드롭 라우팅 거부: 오버레이/모달 중 + web pane은 refused — 호스트가 삽입도 못 하게 한다" {
    // 이 테스트가 증명하는 것: routeDropAtPoint가 **거부(.refused)와 해당 없음(.not_applicable)을 구분**한다는 계약.
    // 둘 다 0으로 접으면 호스트(Swift)가 "라우팅 안 됐네" 하고 **그냥 활성 pane에 삽입**해, 애초에 막으려던
    // 오삽입이 그대로 일어난다(code-review 확정). 거부해야 하는 상태:
    //   ① chrome 오버레이/모달이 열림 — 마우스 클릭이 모달에 삼켜지는 것과 같은 규율(anyOverlayOpen 단일 판정).
    //      예전엔 confirm만 손으로 베껴, 설정 화면(⌘,)이 열린 채 드롭하면 뒤 pane의 포커스를 훔쳤다.
    //   ② 대상 Term이 web — 붙일 PTY가 없어 내용이 조용히 사라진다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    try session.splitActivePane(.horizontal); // 2 pane

    var leaf_rects: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaf_rects.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaf_rects);
    // 활성이 **아닌** pane을 대상으로 삼는다(라우팅이 실제로 일어나야 의미 있는 자리).
    const active_pane = session.activePane();
    const target = for (leaf_rects.items) |lr| {
        if (lr.leaf != active_pane) break lr;
    } else return error.SkipZigTest;
    const tx: f64 = @floatFromInt(target.rect.x + @as(i64, @intCast(target.rect.w / 2)));
    const ty: f64 = @floatFromInt(target.rect.y + @as(i64, @intCast(target.rect.h / 2)));

    // 기준선: 가드가 없으면 정상 라우팅(가드가 "항상 막는" 게 아님을 함께 증명).
    try std.testing.expectEqual(AppSession.DropRoute.routed, session.routeDropAtPoint(tx, ty));
    try std.testing.expectEqual(target.leaf, session.activePane());
    _ = session.focusPaneByPtr(active_pane); // 원복
    try std.testing.expectEqual(active_pane, session.activePane());

    // ① 오버레이/모달 — confirm 말고 **설정 화면**으로 검증한다(예전 가드는 confirm만 봐서 이걸 놓쳤다).
    session.chrome_host.settings.open = true;
    try std.testing.expect(session.anyOverlayOpen());
    try std.testing.expectEqual(AppSession.DropRoute.refused, session.routeDropAtPoint(tx, ty));
    try std.testing.expectEqual(active_pane, session.activePane()); // 포커스 안 뺏김
    session.chrome_host.settings.open = false;

    // 확인 모달도 같은 판정(anyOverlayOpen에 포함).
    session.showConfirmButtons(.{ .paste = session.activeSurface().id }, AppSession.paste_confirm_message, .{ .confirm = "붙여넣기", .cancel = "취소" });
    try std.testing.expectEqual(AppSession.DropRoute.refused, session.routeDropAtPoint(tx, ty));
    try std.testing.expectEqual(active_pane, session.activePane());
    session.chrome_host.confirm.dismiss();
    try std.testing.expect(!session.anyOverlayOpen());

    // ② 대상 Term이 web → refused(활성 pane으로 폴백해 삽입하면 web pane 포커스를 훔치고 내용은 사라진다).
    target.leaf.terms.items[target.leaf.active_term].kind = .web;
    try std.testing.expectEqual(AppSession.DropRoute.refused, session.routeDropAtPoint(tx, ty));
    try std.testing.expectEqual(active_pane, session.activePane()); // 포커스 안 뺏김
    target.leaf.terms.items[target.leaf.active_term].kind = .terminal; // deinit 전 원복(teardown 경로 보호)
}

test "비동기 paste 대상 고정: 확인 모달 중 pane을 옮겨도 확정 payload는 원래 pane으로 간다" {
    // 이 테스트가 증명하는 것: paste 대상이 **enqueue(또는 모달을 띄운) 시점**에 고정된다는 계약.
    // 예전엔 confirmPendingPaste가 activeSurface를 **그때 다시 읽어서**, 확인하는 동안 사용자가 탭/pane을
    // 옮기면 위험한 payload가 엉뚱한 pane에 주입됐다(code-review). 원격(ssh) 업로드도 같은 구조의 비동기
    // 구간이라(드롭 → 백그라운드 업로드 → 완료 후 paste) 같은 고정이 필요하다 — 여기선 모달 경로로 증명한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    try session.splitActivePane(.horizontal); // 2 pane

    const origin_id = session.activeSurface().id; // 붙여넣기를 시작한(=대상이어야 할) surface
    // 위험한 payload(개행) → 확인 모달로 보류. 이때 대상이 고정된다.
    session.pasteText("danger\nrm -rf /", false);
    try std.testing.expect(session.chrome_host.confirm.open);
    try std.testing.expect(session.pending_paste_confirm.items.len > 0);
    try std.testing.expect(session.pending_confirm == .paste);
    try std.testing.expectEqual(origin_id, session.pending_confirm.paste); // ★ 대상 고정

    // 확인하는 동안 사용자가 다른 pane으로 이동(탭/pane 전환·다른 pane 클릭 등).
    session.focusPaneRelative(1);
    const other_id = session.activeSurface().id;
    try std.testing.expect(other_id != origin_id);

    // 확정 → **원래 pane**으로 간다(활성이 바뀌었어도).
    session.chrome_host.confirm.dismiss();
    session.dispatchChromeAction(.confirm_accept);
    // ★ 관측: paste 큐 **엔트리는 flush 뒤에도 남는다**(비워질 뿐 — destroyTerm이 회수한다). 그래서 "바이트가
    //   어느 surface 큐로 들어갔었나"가 엔트리 존재로 드러난다. origin에는 엔트리가 생기고, 활성이던 other에는
    //   **엔트리 자체가 없어야** 한다(옛 코드는 activeSurface를 다시 읽어 other로 보냈다).
    try std.testing.expect(session.pending_pastes.get(origin_id) != null); // origin으로 갔다
    try std.testing.expect(session.pending_pastes.get(other_id) == null); // 활성(other)으로는 안 갔다
    try std.testing.expectEqual(@as(usize, 0), session.pending_paste_confirm.items.len); // 소비됨
    try std.testing.expect(session.pending_confirm == .none); // 대상도 리셋

    // 대상 Term이 사라진 뒤의 확정은 **아무 데도 안 간다**(활성 pane으로 새지 않는다) — 고정 대상이 없으면 no-op.
    const gone: u64 = origin_id +% 1000; // 존재하지 않는 surface id
    session.pending_paste_confirm.clearRetainingCapacity();
    try session.pending_paste_confirm.appendSlice(allocator, "orphan\n");
    session.pending_confirm = .{ .paste = gone };
    const before_count = session.pending_pastes.count();
    session.confirmPendingPaste(gone);
    try std.testing.expectEqual(before_count, session.pending_pastes.count()); // 새 큐가 안 생겼다 = 아무 데도 안 붙였다
}

test "SG4/SG5-1: 두 그룹 사이 이동(펼친 헤더 from>M) + 마커 탭 카드 드래그=그룹 통째 이동 + 드롭 하이라이트 (mouse 시뮬레이션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 두 **형제**(sibling) 최상위 그룹: A=t0에서 시작(t0,t1), B=t2에서 시작(t2,t3). 연속 파티션 [A][B], 최상위 없음.
    // 주의(SG5-3): create_group은 이제 "그룹 안 카드에서 실행 → depth+1 중첩"이라(§9), A가 끝까지 뻗은 상태에서
    // t2에 create_group을 부르면 B가 A의 자식(depth 2)이 된다. 이 테스트는 **형제 그룹 통째 드래그**를 검증하므로
    // B의 group_depth를 1로 명시해 형제로 만든다(위치 파생 모델에서 첫 그룹 뒤 형제 최상위 그룹은 depth 힌트로 표현).
    session.createGroupAbsorbForTab(t0);
    session.createGroupAbsorbForTab(t2);
    t2.group_depth = 1; // B를 최상위 형제로(create_group 중첩 기본을 이 테스트 목적에 맞게 오버라이드)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // B 몸통

    // ── from>M 펼친 헤더 넣기: t3(그룹 B, index3)를 그룹 A 헤더(m=0)에 드롭 → A 최상단(마커 직후, to=m+1).
    {
        const from: usize = 3; // t3
        const target = session.sidebarGroupDropTargetTab(0, from).?; // 펼친 A 헤더 row0, m=0, from>m → to=m+1=1
        try std.testing.expectEqual(@as(usize, 1), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t0(mk A), t3, t1, t2(mk B)] — t3가 A로. A=[t0,t3,t1], B=[t2].
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t3, session.tabs.items[1]);
    try std.testing.expectEqual(t1, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // A로 넣기 성공

    // ── SG5-1: 마커 탭 카드 드래그 = **그룹 통째 이동**(옛 SG4 no-op을 대체). mouse로 t0(마커 A) 카드를 잡아 그룹 B
    //    카드(row 5) 위로 끌면 그룹 A 구간 전체가 B 뒤로 옮겨간다(연속 파티션 유지).
    session.recomputeVisibleTabs(); // rows: [header A(0), card t0(1), card t3(2), card t1(3), header B(4), card t2(5)]
    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    // t0(마커 A) 카드 = row 1. row 상단 y = rowTop(rows,1,...). 그 중앙을 클릭해 드래그 arm.
    const marker_card_top = sb.rowTop(session.sidebar_rows.items, 1, header_h, session.sidebarMetrics(), 0);
    const marker_card_y: f64 = @floatFromInt(marker_card_top + @as(i64, @intCast(sb.rowHeight(session.sidebar_rows.items[1], session.sidebarMetrics()) / 2)));
    session.mouse(1, x, marker_card_y, 0, 0); // down → 마커 카드에서 드래그 arm
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    try std.testing.expectEqual(@as(usize, 0), session.pointer_gesture_owner.sidebar_tab.index); // t0(마커 A) 잡음
    // 그룹 B 카드(row 5) 위로 드래그 → **SG8e 비커밋 프리뷰**(self.tabs 불변, subtree 고스트). 옛 라이브 재배치 대신
    // up이 마지막 plan(group_sibling)을 1회 커밋한다. 드롭 하이라이트(drop_slot)는 고스트+삽입선이 대체하므로 null.
    const groupb_card_top = sb.rowTop(session.sidebar_rows.items, 5, header_h, session.sidebarMetrics(), 0);
    const groupb_card_y: f64 = @floatFromInt(groupb_card_top + @as(i64, @intCast(sb.rowHeight(session.sidebar_rows.items[5], session.sidebarMetrics()) / 2)));
    var pre_grp: [8]*Tab = undefined; // 드래그 전 스냅샷(드래그 중 self.tabs 불변 확인)
    for (session.tabs.items, 0..) |t, i| pre_grp[i] = t;
    session.mouse(2, x, groupb_card_y, 0, 0);
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰 활성(subtree 고스트)
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(pre_grp[i], t); // 드래그 중 self.tabs 불변
    session.mouse(3, x, groupb_card_y, 0, 0); // up → 마지막 plan(group_sibling) 1회 커밋
    // 결과 [t2(mk B), t0(mk A), t3, t1] — 그룹 A 구간 전체가 B 뒤로. B=[t2], A=[t0,t3,t1](라이브 시절과 동일 = 등가).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t1, session.tabs.items[3]);
    try std.testing.expect(session.tabs.items[0].group_start != null); // B 마커(연속 파티션 유지)
    try std.testing.expect(session.tabs.items[1].group_start != null); // A 마커
    try std.testing.expect(session.tabs.items[2].group_start == null); // A 몸통
    try std.testing.expect(!session.pointerGestureIs(.sidebar_tab));
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨(원본 복귀)

    // ── SG8d 카드 드래그 고스트 프리뷰: 마커 없는 카드(t1, A 몸통)를 잡아 끌면 라이브 moveTab 대신 **비커밋 프리뷰**가
    // 뜬다(self.tabs 불변 + sidebar_drag_preview 존재 + preview_rows 고스트). up이 마지막 plan을 1회 커밋하고 프리뷰를 정리한다.
    // 현재 [t2(mk B), t0(mk A), t3, t1] → rows: [header B(0), card t2(1), header A(2), card t0(3), card t3(4), card t1(5)].
    // t1 카드 = row 5. 그 중앙을 down.
    session.recomputeVisibleTabs();
    const t1_card_top = sb.rowTop(session.sidebar_rows.items, 5, header_h, session.sidebarMetrics(), 0);
    const t1_card_y: f64 = @floatFromInt(t1_card_top + @as(i64, @intCast(sb.rowHeight(session.sidebar_rows.items[5], session.sidebarMetrics()) / 2)));
    // 드래그 전 self.tabs 스냅샷(드래그 중 불변 확인용).
    var pre_drag: [8]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| pre_drag[i] = t;
    session.mouse(1, x, t1_card_y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    try std.testing.expect(session.tabs.items[session.pointer_gesture_owner.sidebar_tab.index].group_start == null); // 마커 아님(t1)
    // drag to some row → 프리뷰 활성(고스트) + 원본-도메인 drop_slot은 세팅 안 함(고스트+삽입선이 대체) + self.tabs 불변.
    session.mouse(2, x, session.testSidebarRowCenterY(1), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰 활성
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(pre_drag[i], t); // 드래그 중 self.tabs 불변
    session.mouse(3, x, session.testSidebarRowCenterY(1), 0, 0); // up → 마지막 plan 1회 커밋 + 프리뷰 정리
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨(원본 복귀)
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_preview_rows.items.len);
    try std.testing.expect(!session.pointerGestureIs(.sidebar_tab));
}

test "GL1: stablePartitionSubtree — 로컬 pin 직접 멤버가 마커 직후로 float·자식 subgroup 통째 skip·경계 보존·드래그 게이트·no-op byte-identical" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // 최상위 그룹 A(마커 t0, depth1)와 그 **자식 subgroup** B(마커 t3, depth2). 위치 파생:
    //   [t0(mk A d1), t1(A 직접), t2(A 직접), t3(mk B d2), t4(B 멤버), t5(B 멤버)].
    // createGroupForTab(t3)는 t3가 A 멤버(depth1)라 자동 중첩 depth2 → B는 A의 자식. A subtree=[0,6), B subtree=[3,6).
    session.createGroupAbsorbForTab(t0);
    session.createGroupAbsorbForTab(t3);
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(0, null, null)); // A 전체
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B는 중첩 depth2
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6)

    // ── (a) no-op byte-identical: 로컬 pin 0개 → 재배열 없음(순서·active_tab 불변). GL1 회귀 0 안전망.
    var snap0: [6]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap0[i] = t;
    const active0 = session.app_window.active_tab;
    session.stablePartitionSubtree(0);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap0[i], t); // 순서 불변(byte-identical)
    try std.testing.expectEqual(active0, session.app_window.active_tab);

    // ── (b) 직접 멤버 로컬 pin float + 자식 subgroup 통째 skip. t2(A 직접 멤버, 첫째 아님)=로컬 pin,
    //    t5(B 멤버)=로컬 pin이지만 A의 직접 단위가 아니라(자식 subgroup 안) stablePartitionSubtree(0)에선 **안 뜬다**.
    t2.local_pinned = true;
    t5.local_pinned = true;
    session.stablePartitionSubtree(0);
    // 기대: [t0, t2(float), t1, t3(mk B), t4, t5] — t2가 마커 직후로, t1은 밀림, B subtree는 통째 유지(t5 제자리).
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 마커 A 앵커(제자리)
    try std.testing.expectEqual(t2, session.tabs.items[1]); // 로컬 pin 직접 멤버 → 마커 직후
    try std.testing.expectEqual(t1, session.tabs.items[2]); // 비-pin 직접 멤버 → 뒤로
    try std.testing.expectEqual(t3, session.tabs.items[3]); // B 마커(통째 skip — 자리 유지)
    try std.testing.expectEqual(t4, session.tabs.items[4]); // B 멤버
    try std.testing.expectEqual(t5, session.tabs.items[5]); // ★ B 멤버 로컬 pin은 A subtree float 대상 아님(자식 통째)
    // 경계·depth 보존(재배열이 subtree 안에서만 — I2/I3): A subtree·B subtree·B eff depth 불변.
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(0, null, null)); // A=[0,6) 유지
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B eff depth 2 유지
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6) 유지

    // ── (c) 자식 subtree 안 float은 그 자식 마커에 대해 **재귀** 호출(GL2 배선의 결) — heap-pin *Tab 재탐색으로 B 인덱스 얻음.
    var b_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == t3) {
        b_idx = i;
        break;
    };
    try std.testing.expectEqual(@as(usize, 3), b_idx); // B 마커 새 인덱스(재배열로 안 밀림 — A 직접 float만 있었음)
    session.stablePartitionSubtree(b_idx);
    // 기대: [t0, t2, t1, t3, t5(float), t4] — B subtree 안에서 t5가 B 마커 직후로.
    try std.testing.expectEqual(t3, session.tabs.items[3]); // B 마커 앵커
    try std.testing.expectEqual(t5, session.tabs.items[4]); // B 로컬 pin → B 마커 직후
    try std.testing.expectEqual(t4, session.tabs.items[5]); // B 비-pin 멤버 → 뒤로
    // A subtree 경계 여전히 [0,6) — 자식 재배열이 부모 밖으로 안 샘.
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(0, null, null));

    // ── (d) 드래그 게이트: sidebar_drag_preview 활성이면 float 안 함(SG8 self.tabs 불변). t1도 로컬 pin으로 만들지만 무시돼야.
    var snap_d: [6]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap_d[i] = t;
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = .none, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    t1.local_pinned = true; // 게이트가 없으면 t1이 float해 순서가 바뀔 상황
    session.stablePartitionSubtree(0);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap_d[i], t); // ★ 게이트로 순서 불변(드래그 중 float 금지)
    session.sidebar_drag_preview = null; // teardown
}

test "GL2(a): toggleLocalPin — 멤버가 마커 직후로 float·그룹 연속·활성 포인터 보존·재토글 원위치(인접 byte-identical)·최상위 no-op" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    session.createGroupAbsorbForTab(t0); // 그룹 [t0(마커), t1, t2, t3]
    session.app_window.active_tab = 3; // 활성 = t3(포인터 보존 검증용)

    // ── float: **마지막** 멤버 t3 로컬 pin → 마커 직후(index 1)로 stable float. 비-pin 멤버는 상대순서로 뒤에.
    session.toggleLocalPin(t3);
    try std.testing.expect(t3.local_pinned);
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 마커 앵커(제자리)
    try std.testing.expectEqual(t3, session.tabs.items[1]); // ★ 로컬 pin 멤버 = 마커 직후
    try std.testing.expectEqual(t1, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(0, null, null)); // ★ 그룹 연속 [0,4) 유지
    try std.testing.expectEqual(t3, session.tabs.items[session.app_window.active_tab]); // ★ 활성 *Tab 포인터 보존(인덱스 보정)

    // ── 재토글(off): 로컬 pin 해제. 전역 pinned는 직교(안 건드림) — 여전히 그룹 안(연속 유지).
    session.toggleLocalPin(t3);
    try std.testing.expect(!t3.local_pinned);
    try std.testing.expect(!t3.pinned); // ★ 전역 pin과 직교
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(0, null, null));

    // ── 원위치(byte-identical round-trip): **마커 직후 인접 멤버**는 pin→unpin이 순서를 안 바꾼다(float 대상이 이미 그 자리).
    var snap: [4]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap[i] = t;
    const adj = session.tabs.items[1]; // 현재 마커 직후 멤버
    session.toggleLocalPin(adj); // pin → 이미 마커 직후라 float no-op
    session.toggleLocalPin(adj); // unpin → no-op
    try std.testing.expect(!adj.local_pinned);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap[i], t); // ★ 원위치(byte-identical)

    // ── 최상위 카드 no-op: ungroup 후 그룹 미소속 카드는 enclosingGroupMarkerIndex=null → toggleLocalPin 무동작.
    session.ungroupTab(t0); // 전부 최상위
    session.toggleLocalPin(t1); // 최상위 → no-op(플래그도 안 세팅)
    try std.testing.expect(!t1.local_pinned);
}

test "GL2(c): 드래그 clamp — 로컬 pin 멤버가 subtree-로컬 프리픽스 밖으로 못 감(simulateDrop clamp = 프리뷰=확정, 비-pin은 무변경)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    session.createGroupAbsorbForTab(t0); // 그룹 [t0(마커), t1, t2, t3, t4]
    t1.local_pinned = true;
    t2.local_pinned = true;
    session.floatLocalPinsAllGroups(); // canonical: t1·t2 = 프리픽스 [1,3)(이미 그 자리라 no-op)

    // 프리픽스 경계 단위 단언: 로컬 pin leaf = [mi+1, mi+count] inclusive, 비-pin/마커 = null(clamp 무변경).
    try std.testing.expectEqual(@as(usize, 1), session.localPinPrefixBounds(1).?.lo);
    try std.testing.expectEqual(@as(usize, 2), session.localPinPrefixBounds(1).?.hi); // 프리픽스 [1,3) → 인덱스 1·2
    try std.testing.expect(session.localPinPrefixBounds(3) == null); // ★ 비-로컬-pin 멤버 → clamp 무변경
    try std.testing.expect(session.localPinPrefixBounds(0) == null); // 마커 → null

    // ── 프리뷰(simulateDrop): 로컬 pin t1(index 1)을 프리픽스 **밖(index 4)** 으로 드래그 → 프리픽스 끝(index 2)에 clamp.
    var before: [5]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const vl = try session.simulateDrop(1, .{ .card = .{ .target_tab = 4 } }, arena.allocator());
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변(SG8)
    try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 2, 1, 3, 4 }, vl.order); // ★ t1이 프리픽스 밖 못 가고 index 2에 clamp

    // ── 확정(commitSidebarDragPreview 재현: moveTab RAW target + normalize + floatLocalPins) == 프리뷰(re-partition-on-commit).
    _ = session.moveTab(1, 4); // RAW 프리픽스 밖 target — moveTab엔 로컬 clamp 없음(이동 함수 아님)
    session.normalizePinnedFromGroups();
    session.floatLocalPinsAllGroups(); // §13.5 snap-back
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[vl.order[i]], t); // ★ 프리뷰=확정
    try std.testing.expectEqual(t1, session.tabs.items[2]); // t1이 프리픽스 [1,3) 안(밖으로 못 감)
    try std.testing.expect(t1.local_pinned);
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(0, null, null)); // 그룹 연속 유지

    // ── 대조(비-로컬-pin 무변경): t3(비-pin, index 3)을 t4(index 4)로 드래그 = 자유 swap(프리픽스 밖이라 float 무간섭).
    var before2: [5]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before2[i] = t; // 현재 [t0,t2,t1,t3,t4]
    var arena2 = std.heap.ArenaAllocator.init(allocator);
    defer arena2.deinit();
    const vl2 = try session.simulateDrop(3, .{ .card = .{ .target_tab = 4 } }, arena2.allocator());
    try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 1, 2, 4, 3 }, vl2.order); // clamp 무적용 — t3↔t4 자유 swap
    _ = session.moveTab(3, 4);
    session.normalizePinnedFromGroups();
    session.floatLocalPinsAllGroups();
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before2[vl2.order[i]], t); // 프리뷰=확정(비-pin도 프리픽스 밖이라 일치)
}

// GL3(그룹-로컬 pin 렌더 📌 + 위생 + 드래그 프리뷰=확정 엣지 — docs/sidebar-groups.md §13.6·§13.7). 문서 §13.10은 render+
// 위생을 GL4로 라벨하지만, 이 작업은 GL3로 통합해 구현한다. 스크린샷(MARU_FORCE_GROUP_LOCALPIN)은 시각 마감 1급 검증으로 별도.
test "GL3(a): 렌더 📌 — 로컬 pin 멤버 sidebarRowShowsPin=true·비pin 멤버 억제(pin_derived 직교)·마커/최상위 억제(§13.6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t3 = session.tabs.items[3];

    session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3, t4] — t0는 최상위 카드
    session.toggleLocalPin(t3); // t3 로컬 pin → 마커 t1 직후(그룹 내 상단)로 float
    try std.testing.expectEqual(t3, session.tabs.items[2]); // ★ float: 마커(index1) 직후 index2로

    session.recomputeVisibleTabs();
    // 표시 rows(GL §13.6.1 — 로컬 pin이 그룹 **절대 최상단**, 마커 자기 카드는 그 **아래**):
    //   [card t0, header A, card t3(로컬 pin), card t1(마커카드), card t2, card t4]
    const rows = session.sidebar_rows.items;
    try std.testing.expectEqual(@as(usize, 6), rows.len);

    // ── ★ row 순서(§13.6.1): 로컬 pin 멤버 t3 카드가 마커 자기 카드(t1)보다 **앞**. 각 row.tab은 실제 tab index 그대로 ──
    try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // t3(로컬 pin) = self.tabs index 2 — 마커 직후로 float
    try std.testing.expectEqual(@as(usize, 1), rows[3].card.tab); // t1(마커 자기 카드) = index 1 — 로컬 pin **뒤**로 재배치

    // ── local_pinned 힌트(§13.6): 로컬 pin 멤버 카드만 true. 마커 카드·최상위 카드·비pin 멤버=false ──
    try std.testing.expect(!rows[0].card.local_pinned); // t0 최상위 카드
    try std.testing.expect(rows[2].card.local_pinned); // ★ t3 로컬 pin 멤버(절대 최상단)
    try std.testing.expect(!rows[3].card.local_pinned); // A 마커 자기 카드(§13.8 — 마커 로컬 pin은 GL5, 이제 로컬 pin 뒤)
    try std.testing.expect(!rows[4].card.local_pinned); // t2 비pin 멤버
    try std.testing.expect(!rows[5].card.local_pinned); // t4 비pin 멤버
    // pin_derived와 **직교**: 로컬 pin 멤버(t3)도 depth>0이라 pin_derived=true지만 local_pinned가 선두 분기로 우선한다.
    try std.testing.expect(rows[2].card.pin_derived); // t3도 멤버 파생 캐시 힌트 = true
    try std.testing.expect(rows[4].card.pin_derived); // t2 멤버(비pin) = true

    // ── sidebarRowShowsPin(§13.6 선두 분기): 로컬 pin 멤버만 📌. 비pin 멤버·마커·헤더·최상위(비고정)는 억제 ──
    try std.testing.expect(session.sidebarRowShowsPin(rows[2])); // ★ 로컬 pin 멤버 t3 → 📌(pin_derived 억제 우회)
    // (d) GP4(a) 회귀: pin_derived=true여도 local_pinned=false면 여전히 억제(멤버 📌 노이즈 0). 조건부화 검증.
    try std.testing.expect(!session.sidebarRowShowsPin(rows[4])); // t2 비pin 멤버 → 억제(pin_derived)
    try std.testing.expect(!session.sidebarRowShowsPin(rows[5])); // t4 비pin 멤버 → 억제
    try std.testing.expect(!session.sidebarRowShowsPin(rows[3])); // A 마커 카드 → 억제(헤더가 인디케이터)
    try std.testing.expect(!session.sidebarRowShowsPin(rows[1])); // A 헤더(그룹째 고정 아님) → 인디케이터 없음
    try std.testing.expect(!session.sidebarRowShowsPin(rows[0])); // t0 최상위(비고정) → 없음

    // 종합: 카드 📌는 로컬 pin 멤버(t3) 하나뿐, 헤더 📌는 0(그룹째 고정 없음).
    var card_pins: usize = 0;
    var header_pins: usize = 0;
    for (rows) |r| switch (r) {
        .agent_toggle, .agent => {},
        .card => if (session.sidebarRowShowsPin(r)) {
            card_pins += 1;
        },
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 1), card_pins); // 로컬 pin 멤버 t3만
    try std.testing.expectEqual(@as(usize, 0), header_pins);
    _ = t0;
}

test "GL3(a2): 공존 렌더 — 그룹째 고정 그룹 안 로컬 pin 멤버 = 헤더 그룹📌 + 멤버 로컬📌(단일 글리프 U+1F4CC 수용, §13.6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t1 = session.tabs.items[1];
    const t3 = session.tabs.items[3];

    session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3, t4]
    session.toggleLocalPin(t3); // t3 로컬 pin → 마커 직후
    session.toggleGroupPin(t1); // A를 그룹째 고정(전역 프리픽스 안착 — keystone §13.1로 subtree 내 float 순서 보존)
    // t3은 여전히 마커 직후(그룹 내 상단)이고 local_pinned 유지(그룹째 고정과 직교).
    try std.testing.expect(t3.local_pinned);
    try std.testing.expect(t1.pinned); // 그룹째 고정 = 마커 pinned

    session.recomputeVisibleTabs();
    // A가 프리픽스로 이동(t0 비고정보다 앞). GL §13.6.1로 로컬 pin이 마커 카드 위:
    //   rows: [header A, card t3(로컬 pin), card t1(마커), card t2, card t4, card t0]
    const rows = session.sidebar_rows.items;
    var header_pins: usize = 0;
    var member_pins: usize = 0;
    for (rows) |r| switch (r) {
        .agent_toggle, .agent => {},
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
        .card => |c| if (session.sidebarRowShowsPin(r)) {
            if (c.local_pinned) member_pins += 1; // 로컬 pin 멤버 카드 📌
        },
    };
    try std.testing.expectEqual(@as(usize, 1), header_pins); // ★ 그룹째 고정 헤더 인디케이터 📌
    try std.testing.expectEqual(@as(usize, 1), member_pins); // ★ 그 안 로컬 pin 멤버 카드 📌(공존 — 위치로 구별)
}

// GL §13.6.1 — 마커 자기 카드를 그룹의 로컬 pin 직접 멤버 **뒤**로 렌더(로컬 pin = 그룹 절대 최상단). projectRowsCore가
// 마커 카드 row를 버퍼링했다 로컬 pin run 뒤에 방출한다. 검증: (1) sidebar_rows 순서·row.tab·hit-test, (2) 로컬 pin 0개면
// byte-identical(마커 첫 카드), (3) 로컬 pin 멤버 드래그 프리뷰=확정, (4) 그룹 통째 드래그 프리뷰=확정 + 고스트 range가
// 재배치된 마커 카드까지 이어짐.
test "GL3(d): 마커 카드 로컬 pin 뒤 렌더(§13.6.1) — 순서·hit-test·byte-identical(0개)·프리뷰=확정" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const init_opts = SessionConfig{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    };

    // ── (1) 순서 + hit-test: 로컬 pin 멤버 카드가 마커 자기 카드보다 앞. 각 row.tab은 실제 tab index 그대로 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커=idx1), t2, t3, t4]
        session.toggleLocalPin(t3); // t3 → idx2(마커 직후로 float)
        try std.testing.expectEqual(t3, session.tabs.items[2]);
        session.recomputeVisibleTabs();
        const rows = session.sidebar_rows.items;
        // rows: [card t0, header A, card t3(로컬 pin, idx2), card t1(마커, idx1), card t2(idx3), card t4(idx4)]
        try std.testing.expectEqual(@as(usize, 6), rows.len);
        try std.testing.expect(rows[1] == .group_header);
        try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // ★ 로컬 pin t3 — 그룹 절대 최상단(헤더 직후)
        try std.testing.expectEqual(@as(usize, 1), rows[3].card.tab); // ★ 마커 자기 카드 — 로컬 pin 뒤
        // hit-test 정합: 마커 카드 row(slot 3) 클릭 → 마커 tab(1)이라 마커 워크스페이스 활성. 로컬 pin row(slot 2) → t3.
        try std.testing.expectEqual(@as(usize, 1), session.visibleTab(3).?); // ★ 마커 카드 slot → 마커 tab(클릭 정합)
        try std.testing.expectEqual(@as(usize, 2), session.visibleTab(2).?); // 로컬 pin slot → t3
        try std.testing.expectEqual(@as(?usize, 3), session.displaySlotOf(1)); // 마커 tab → slot 3(역방향 정합)
        try std.testing.expectEqual(@as(?usize, 2), session.displaySlotOf(2)); // t3 → slot 2
    }

    // ── (2) 로컬 pin 0개면 byte-identical — 마커 카드가 여전히 헤더 직후(첫 카드) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t1 = session.tabs.items[1];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3] — 로컬 pin 0개
        session.recomputeVisibleTabs();
        const rows = session.sidebar_rows.items;
        // rows: [card t0, header A, card t1(마커=첫 카드), card t2, card t3]
        try std.testing.expectEqual(@as(usize, 5), rows.len);
        try std.testing.expect(rows[1] == .group_header);
        try std.testing.expectEqual(@as(usize, 1), rows[2].card.tab); // ★ 마커 카드 = 헤더 직후 첫 카드(byte-identical)
        try std.testing.expectEqual(@as(usize, 2), rows[3].card.tab);
        try std.testing.expectEqual(@as(usize, 3), rows[4].card.tab);
    }

    // ── (3) 로컬 pin 멤버 드래그: 프리뷰=확정. `Row.card.tab`은 self.tabs **인덱스**(id 아님)라, 프리뷰(self.tabs 불변)와
    //    확정(self.tabs 재배열) 인덱스는 좌표계가 다르다 → 각 카드 row가 가리키는 **실제 *Tab 포인터**로 순서를 비교한다. ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
        const t1 = session.tabs.items[1];
        const t2 = session.tabs.items[2];
        const t3 = session.tabs.items[3];
        const t0 = session.tabs.items[0];
        const t4 = session.tabs.items[4];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커=idx1), t2, t3, t4]
        t2.local_pinned = true;
        t3.local_pinned = true;
        session.floatLocalPinsAllGroups(); // canonical: t2·t3 = 프리픽스 [2,4)(이미 그 자리)
        var pre: [8]*Tab = undefined; // 드래그 중 불변인 pre-move self.tabs 스냅샷(프리뷰 .tab 역참조용)
        for (session.tabs.items, 0..) |t, i| pre[i] = t;
        // 로컬 pin t2(origin idx2)를 t4(idx4) 위로 드래그 → 프리픽스 끝(idx3)에 clamp(프리픽스 밖 못 감).
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        try session.refreshDragPreview(2, .{ .card = .{ .target_tab = 4 } }, 0, arena.allocator());
        var preview_ptrs: [8]*Tab = undefined;
        var pn: usize = 0;
        for (session.sidebar_preview_rows.items) |r| switch (r) {
            .agent_toggle, .agent => {},
            .card => |c| {
                preview_ptrs[pn] = pre[c.tab]; // 프리뷰 .tab = pre-move self.tabs 인덱스
                pn += 1;
            },
            .group_header => {},
        };
        // preview 시각 순서: [t0, header, t3(lp), t2(lp, 드래그), 마커, t4] — 마커 카드가 두 로컬 pin **뒤**.
        try std.testing.expectEqual(@as(usize, 5), pn);
        try std.testing.expectEqual(t0, preview_ptrs[0]);
        try std.testing.expectEqual(t3, preview_ptrs[1]); // 로컬 pin(t2와 swap됐지만 여전히 마커 앞)
        try std.testing.expectEqual(t2, preview_ptrs[2]); // 로컬 pin(드래그된 것)
        try std.testing.expectEqual(t1, preview_ptrs[3]); // ★ 마커 자기 카드 — 로컬 pin 뒤
        try std.testing.expectEqual(t4, preview_ptrs[4]);
        session.commitSidebarDragPreview(); // 확정(clamp→moveTab→float→sweep→rebuild)
        var commit_ptrs: [8]*Tab = undefined;
        var cn: usize = 0;
        for (session.sidebar_rows.items) |r| switch (r) {
            .agent_toggle, .agent => {},
            .card => |c| {
                commit_ptrs[cn] = session.tabs.items[c.tab]; // 확정 .tab = post-move self.tabs 인덱스
                cn += 1;
            },
            .group_header => {},
        };
        try std.testing.expectEqual(pn, cn);
        try std.testing.expectEqualSlices(*Tab, preview_ptrs[0..pn], commit_ptrs[0..cn]); // ★ 프리뷰=확정(같은 Tab 순서)
    }

    // ── (4) 그룹 통째 드래그(마커 카드=그룹 이동): 프리뷰=확정 + 고스트 range가 재배치된 마커 카드까지 이어짐 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t0 = session.tabs.items[0];
        const t1 = session.tabs.items[1];
        const t2 = session.tabs.items[2];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커=idx1), t2, t3] — t0 최상위
        t2.local_pinned = true;
        session.floatLocalPinsAllGroups(); // A = [마커, t2(lp), t3]
        var pre: [8]*Tab = undefined;
        for (session.tabs.items, 0..) |t, i| pre[i] = t;
        // 그룹 A(마커 idx1)를 **최상위(insert_before=0)** 로 통째 이동 — 마커 카드 드래그(SG5)와 같은 코어.
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        try session.refreshDragPreview(1, .{ .group_sibling = .{ .insert_before = 0 } }, 0, arena.allocator());
        var preview_ptrs: [8]*Tab = undefined;
        var pn: usize = 0;
        for (session.sidebar_preview_rows.items) |r| switch (r) {
            .agent_toggle, .agent => {},
            .card => |c| {
                preview_ptrs[pn] = pre[c.tab];
                pn += 1;
            },
            .group_header => {},
        };
        // preview 시각 순서: [header, t2(lp), 마커, t3, t0] — A가 앞으로, 그 안 t2(lp)가 마커 위.
        try std.testing.expectEqual(@as(usize, 4), pn);
        try std.testing.expectEqual(t2, preview_ptrs[0]); // 로컬 pin
        try std.testing.expectEqual(t1, preview_ptrs[1]); // ★ 마커 자기 카드 — 로컬 pin 뒤
        try std.testing.expectEqual(t3, preview_ptrs[2]); // 비pin 멤버
        try std.testing.expectEqual(t0, preview_ptrs[3]); // 최상위(그룹 밖)
        // 고스트 range(표시-row 도메인)는 옮겨진 A 전체 = header(0)·t2(1)·마커카드(2)·t3(3) → [0,4). 재배치된 마커 카드
        // (row 2)가 range 안이라 그룹 통째 고스트에 마커 카드가 빠지지 않는다(flushMarkerCard의 ghost range 확장 검증).
        try std.testing.expectEqual(@as(usize, 0), session.sidebar_drag_preview.?.ghost_lo);
        try std.testing.expectEqual(@as(usize, 4), session.sidebar_drag_preview.?.ghost_hi);
        session.commitSidebarDragPreview();
        var commit_ptrs: [8]*Tab = undefined;
        var cn: usize = 0;
        for (session.sidebar_rows.items) |r| switch (r) {
            .agent_toggle, .agent => {},
            .card => |c| {
                commit_ptrs[cn] = session.tabs.items[c.tab];
                cn += 1;
            },
            .group_header => {},
        };
        try std.testing.expectEqual(pn, cn);
        try std.testing.expectEqualSlices(*Tab, preview_ptrs[0..pn], commit_ptrs[0..cn]); // ★ 프리뷰=확정(그룹 드래그)
    }
}

// GL3(b) 위생(§13.7) — 멤버→top-level 전이 3경로에서 local_pinned:=false(고아 📌 방지). 각 전이를 독립 세션으로 검증한다
// (closeTab은 마지막 탭에서 창 닫기 latch라 재사용 teardown이 불가 — 세션 분리가 정직).
test "GL3(b1): 위생 ungroup — 로컬 pin 멤버가 그룹 해제로 top-level 전이 시 local_pinned:=false(§13.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    session.createGroupAbsorbForTab(t0); // A = [t0(마커), t1, t2]
    session.toggleLocalPin(t1);
    try std.testing.expect(t1.local_pinned);
    session.ungroupTab(t1); // A 해제 → t0·t1·t2 전부 top-level
    try std.testing.expect(!t1.local_pinned); // ★ 위생: top-level 전이 → 클리어
    try std.testing.expect(!session.tabIsInGroup(t1));
}

test "GL3(b2): 위생 removeFromGroup — 빠진 로컬 pin 멤버만 클리어·남은 그룹 멤버는 로컬 pin 유지(§13.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    session.createGroupAbsorbForTab(t0); // A = [t0(마커), t1, t2]
    session.toggleLocalPin(t1);
    session.toggleLocalPin(t2); // t1·t2 둘 다 로컬 pin
    try std.testing.expect(t1.local_pinned and t2.local_pinned);
    session.removeFromGroupForTab(t1); // t1만 빼기 → top-level
    try std.testing.expect(!t1.local_pinned); // ★ 빠진 카드 = 클리어
    try std.testing.expect(!session.tabIsInGroup(t1));
    try std.testing.expect(t2.local_pinned); // ★ 남은 그룹 멤버 t2는 로컬 pin 유지(밖으로 안 나감)
    try std.testing.expect(session.tabIsInGroup(t2));
}

test "GL3(b3): 위생 드래그 out — commitSidebarDragPreview 스윕이 top-level 카드 stale local_pinned 클리어·멤버 보존(§13.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // commit clamp가 로컬 pin **멤버**의 실제 그룹 밖 eject를 막으므로(§13.5, GL3(c)), 이 스윕은 top-level 전이한 카드의
    // desync/잔재 local_pinned를 지우는 **불변식 net**이다(§13.7 "그룹 밖으로 나가면"의 commit 지점). 그룹 멤버 로컬 pin은 보존.
    inline for (0..3) |_| _ = try session.newTab(); // [c0, c1, t2, t3]
    const c0 = session.tabs.items[0];
    session.createGroupAbsorbForTab(session.tabs.items[2]); // A = [t2(마커), t3] — c0·c1 최상위 카드
    const t3 = session.tabs.items[3];
    session.toggleLocalPin(t3); // 진짜 그룹 멤버 로컬 pin(보존 대상)
    c0.local_pinned = true; // stale: top-level 카드에 남은 로컬 pin(전이 잔재 시뮬레이션)
    // c0(top-level, origin=0)을 c1(index1)로 드래그 = top-level↔top-level. commit이 위생 스윕으로 c0 stale 클리어.
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = .{ .card = .{ .target_tab = 1 } }, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    try std.testing.expect(!c0.local_pinned); // ★ top-level 카드 stale local_pinned 스윕(고아 📌 방지)
    try std.testing.expect(t3.local_pinned); // ★ 진짜 그룹 멤버 로컬 pin은 보존
}

test "GL3(b4): 위생 create group — 로컬 pin 멤버로 그룹 생성 시 마커 local_pinned=0 + break_next top카드도 스윕(§13.7·leaf-only)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[Gm=t0, m1=t1, m2=t2]
    const m1 = session.tabs.items[1];
    const m2 = session.tabs.items[2];
    session.toggleLocalPin(m1); // m1 로컬 pin(leaf 멤버 — float은 이미 마커 직후라 제자리)
    session.toggleLocalPin(m2); // m2 로컬 pin
    try std.testing.expect(m1.local_pinned and m2.local_pinned); // 사전: 둘 다 leaf 로컬 pin

    // m1로 (중첩) 그룹 생성 → m1은 마커(leaf 아님), break_next가 다음 카드 m2에 top_level write(그룹 밖 leaf 아님).
    session.createGroupForTab(m1);
    try std.testing.expect(m1.group_start != null); // m1이 새 마커
    try std.testing.expect(!m1.local_pinned); // ★ 마커 전이 → local_pinned 클리어(leaf-only §13.8, revert하면 true로 실패)
    try std.testing.expect(m2.top_level); // break_next로 m2 = 그룹 밖 top카드
    try std.testing.expect(!m2.local_pinned); // ★ top-level 전이 카드 stale local_pinned 스윕(clearStaleLocalPins)
}

test "GL3(c): 드래그 엣지 — 로컬 pin 멤버를 마커 자기 카드 위로 드래그해도 프리뷰=확정(commit clamp, eject 없음, §13.5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    session.createGroupAbsorbForTab(t1); // A = [t1(마커, index1), t2, t3, t4] — t0 최상위
    t2.local_pinned = true;
    const t3 = session.tabs.items[3];
    t3.local_pinned = true;
    session.floatLocalPinsAllGroups(); // canonical: t2·t3 = 프리픽스 [2,4)(이미 그 자리라 no-op)
    // 프리픽스 경계: 로컬 pin leaf t2(index2) → [mi+1, mi+count] = [2,3].
    try std.testing.expectEqual(@as(usize, 2), session.localPinPrefixBounds(2).?.lo);
    try std.testing.expectEqual(@as(usize, 3), session.localPinPrefixBounds(2).?.hi);

    // ── 마커 자기 카드(index1) 위로 t2(origin=2, 로컬 pin) 드래그 → 프리픽스 시작(index2)에 clamp(마커 앞 eject 금지).
    var before: [5]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const plan: AppSession.DropPlan = .{ .card = .{ .target_tab = 1 } }; // 마커 카드 = index1
    const vl = try session.simulateDrop(2, plan, arena.allocator());
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변(SG8)
    try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 1, 2, 3, 4 }, vl.order); // 프리뷰: t2가 마커 앞 못 가고 index2 유지

    // ── 확정: **실제 commitSidebarDragPreview 경로**(commit clamp 포함). raw moveTab이면 t2가 마커(index1) 앞으로 eject됐을 것.
    session.sidebar_drag_preview = .{ .origin = 2, .origin_len = 1, .plan = plan, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[vl.order[i]], t); // ★ 프리뷰=확정(eject 없음)
    try std.testing.expectEqual(t2, session.tabs.items[2]); // t2가 그룹 안(마커 직후) 유지 — top-level로 안 샘
    try std.testing.expect(t2.local_pinned); // 로컬 pin 유지(그룹 안 이동은 해제 아님)
    try std.testing.expect(session.tabIsInGroup(t2));
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(1, null, null)); // 그룹 A=[1,5) 연속 유지
}

// GL4(a) — 공존(그룹째 고정 C2 × 그룹-로컬 pin GL)의 keystone 보조정리 실증(docs/sidebar-groups.md §13.1·§13.4). 그룹째
// 고정은 그룹 subtree를 **전역 [고정][비고정] 프리픽스**로 통째 옮기고(stablePartitionPinned), 그 안 로컬 pin float는
// **마커 직후**를 유지해야 한다. keystone: stablePartitionPinned는 pin-uniform 블록의 **내부 상대순서를 보존**(stable)하므로
// subtree 축 위에서 무연산 → 로컬 float가 살아남는다. 배선 순서(§13.4): (1)normalize→(2)stablePartitionPinned→(3)float가
// 항상 이 순서라, 전역 프리픽스 안착과 subtree float가 서로를 안 흩뜨린다. 비고정 최상위 카드 t0를 둬 **전역 partition이
// 실제로 그룹을 옮기게**(t0가 뒤로 밀림) 만들어 keystone을 눈에 보이게 검증한다.
test "GL4(a): 공존 keystone — 그룹째 고정이 로컬 pin 그룹을 전역 프리픽스로 옮겨도 subtree 로컬 float 보존·배선 순서·재토글·idempotent·렌더" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    session.createGroupAbsorbForTab(t1); // A = [t1(마커 d1), t2, t3, t4, t5] — t0는 **비고정 최상위 카드**(전역 partition의 대조)
    // 두 멤버(t4·t5)를 로컬 pin → 마커 직후로 float(상대순서 t4,t5 유지). 그룹 안 상단 프리픽스 [1,3) = t4·t5.
    session.toggleLocalPin(t4);
    session.toggleLocalPin(t5);
    try std.testing.expectEqual(t4, session.tabs.items[2]); // t4 = 마커 직후
    try std.testing.expectEqual(t5, session.tabs.items[3]); // t5 = 그 다음(로컬 float 상대순서)

    // ── ★ keystone: A를 그룹째 고정. stablePartitionPinned가 pinned 블록[t1,t4,t5,t2,t3]을 프리픽스로 옮기고 t0(비고정)를
    //    뒤로 민다. 블록 **내부 순서 보존**이라 t4·t5가 여전히 마커 직후. float((3)단계)는 이미 그 자리라 no-op.
    session.toggleGroupPin(t1);
    try std.testing.expectEqual(t1, session.tabs.items[0]); // 그룹 마커 = 전역 프리픽스 선두(그룹이 앞으로 이동)
    try std.testing.expectEqual(t4, session.tabs.items[1]); // ★ 로컬 pin float 보존(마커 직후) — keystone
    try std.testing.expectEqual(t5, session.tabs.items[2]); // ★ 로컬 pin float 상대순서 보존
    try std.testing.expectEqual(t2, session.tabs.items[3]); // 비-로컬-pin 멤버
    try std.testing.expectEqual(t3, session.tabs.items[4]);
    try std.testing.expectEqual(t0, session.tabs.items[5]); // ★ 비고정 최상위 카드 = 뒤로 밀림(전역 partition이 실제로 옮김)
    // 축 직교: 그룹째 고정(마커 pinned)과 로컬 pin(local_pinned)이 **다른 비트**로 공존.
    try std.testing.expect(t1.pinned); // 그룹째 고정 = 마커 pinned(권위)
    try std.testing.expect(t4.pinned and t4.local_pinned); // 멤버 = 파생 pinned 캐시 + 로컬 pin(둘 다)
    try std.testing.expect(t5.pinned and t5.local_pinned);
    try std.testing.expect(!t0.pinned); // 비고정 카드
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(0, null, null)); // A=[0,5) 통째 고정 프리픽스

    // ── idempotent(배선 표준 순서 재실행이 안정): normalize→partition→float를 한 번 더 돌려도 순서 불변.
    var snap: [6]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap[i] = t;
    session.normalizePinnedFromGroups();
    session.stablePartitionPinned();
    session.floatLocalPinsAllGroups();
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap[i], t); // ★ idempotent(공존 canonical 고정점)

    // ── 렌더(§13.6): 헤더 그룹📌 + 로컬 pin 멤버 카드 📌(마커 카드 위). 위치로 구별(단일 글리프 U+1F4CC 수용).
    session.recomputeVisibleTabs();
    const rows = session.sidebar_rows.items;
    // rows: [header A(📌), card t4(lp,📌), card t5(lp,📌), card t1(마커카드), card t2, card t3, card t0]
    try std.testing.expectEqual(@as(usize, 7), rows.len);
    try std.testing.expect(rows[0] == .group_header);
    try std.testing.expectEqual(@as(usize, 1), rows[1].card.tab); // t4 = self.tabs index1(마커 직후)
    try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // t5
    try std.testing.expectEqual(@as(usize, 0), rows[3].card.tab); // ★ A 마커 자기 카드(index0) = 로컬 pin **뒤**
    try std.testing.expect(session.sidebarRowShowsPin(rows[0])); // ★ 그룹째 고정 헤더 인디케이터 📌
    try std.testing.expect(session.sidebarRowShowsPin(rows[1])); // ★ 로컬 pin 멤버 t4 📌
    try std.testing.expect(session.sidebarRowShowsPin(rows[2])); // ★ 로컬 pin 멤버 t5 📌
    try std.testing.expect(!session.sidebarRowShowsPin(rows[3])); // 마커 카드 억제(헤더가 인디케이터)
    var header_pins: usize = 0;
    var member_pins: usize = 0;
    for (rows) |r| switch (r) {
        .agent_toggle, .agent => {},
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
        .card => |c| if (session.sidebarRowShowsPin(r)) {
            if (c.local_pinned) member_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 1), header_pins); // 그룹째 고정 헤더 하나
    try std.testing.expectEqual(@as(usize, 2), member_pins); // 로컬 pin 멤버 둘

    // ── 재토글(그룹째 고정 해제 = 그룹 리셋): 멤버의 로컬 pin도 **함께 클리어**된다(사용자 리포트 버그2 — §13.1 리셋
    //    시맨틱). 로컬 pin은 그룹째 고정과 직교라 **고정 켜는 동안엔 보존**(위 keystone)하되, **끄는 순간** 그룹을 깨끗한
    //    멤버 상태로 되돌려 자식이 개별 📌로 남지 않게 한다. self.tabs 위치는 float된 자리(마커 직후)에 그대로 남되(재배열
    //    안 함) local_pinned=false·📌 억제로 "그냥 그룹 멤버"가 된다.
    session.toggleGroupPin(t1);
    try std.testing.expect(!t1.pinned); // 그룹째 고정 해제
    try std.testing.expect(!t4.pinned and !t5.pinned); // 멤버 파생 캐시도 해제
    try std.testing.expect(!t4.local_pinned and !t5.local_pinned); // ★ 그룹 해제 = 로컬 pin 리셋(개별 📌 제거, 버그2)
    try std.testing.expectEqual(t4, session.tabs.items[1]); // 위치는 float된 자리에 남음(재배열 없음 — 데이터만 클리어)
    try std.testing.expectEqual(t5, session.tabs.items[2]);
    // C2 그룹째 고정/해제는 top-card 위치의 완전 round-trip이 **아니다**(GL과 직교): 고정 때 프리픽스로 옮기며 비고정 t0를
    // 뒤로 밀었고(위), 해제하면 t0가 그룹 A 꼬리에 남아 위치 파생상 A로 흡수된다(A=[0,6)). 이는 C2(§12) 성질이다.
    // 로컬 pin 멤버(였던 t4·t5)는 여전히 A 소속(위치 파생)이고, 이제 📌 없는 평범한 멤버다.
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(1).?); // t4의 enclosing 마커 = t1(index0)
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(2).?); // t5의 enclosing 마커 = t1
    // ★ 렌더 확인: 해제 후 어떤 멤버 카드도 📌를 안 그린다(개별 📌 0 — 버그2 desired outcome).
    session.recomputeVisibleTabs();
    var member_pins_after: usize = 0;
    for (session.sidebar_rows.items) |r| switch (r) {
        .agent_toggle, .agent => {},
        .card => if (session.sidebarRowShowsPin(r)) {
            member_pins_after += 1;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(usize, 0), member_pins_after); // 해제 후 카드 📌 0(그냥 그룹 멤버)
}

// GL4(b) — 중첩(자식 subgroup 안 leaf 멤버 로컬 pin)의 하드닝(docs/sidebar-groups.md §13.3·§13.6.1·§13.8). `floatLocalPinsAllGroups`
// 가 부모→자식 **순차 스캔**(= 포인터 재탐색 동형, §13.4)으로 부모 A·자식 B 두 subtree를 각자 float하고, 마커 위 배치가
// 자식 그룹서도 성립(자식 마커 카드 위로 자식 로컬 pin)하며 I3(중첩 depth)이 보존됨을 검증한다. **subgroup-as-member는 범위
// 밖(GL5)** — 여기선 leaf 멤버만.
test "GL4(b): 중첩 — 자식 subgroup 안 leaf 로컬 pin float(부모→자식 순차)·자식 마커 카드 위 배치·I3 depth 보존" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // 2단계 중첩: A(마커 t1, d1) ⊃ [t2(A 직접), B(마커 t3, d2) ⊃ [t4, t5]]. t0는 최상위 카드.
    session.createGroupAbsorbForTab(t1); // A = [t1, t2, t3, t4, t5]
    session.createGroupAbsorbForTab(t3); // t3은 A 안 카드(d1) → 자식 B(d2) 흡수 t4·t5. A 직접 = t2.
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(1, null, null)); // A=[1,6)
    try std.testing.expectEqual(@as(u8, 1), session.effectiveDepthAt(1, null, null)); // A d1
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B d2(중첩)
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6)

    // A 직접 멤버 t2·자식 B leaf 멤버 t5를 로컬 pin(직접 필드 세팅 후 **floatLocalPinsAllGroups 한 번**으로 순차 스캔 검증).
    t2.local_pinned = true;
    t5.local_pinned = true;
    session.floatLocalPinsAllGroups(); // i=1(A)→A subtree float(t2 이미 마커 직후=no-op), i=3(B)→B subtree float(t5→B 마커 직후)
    // 기대 물리 순서: [t0, t1(A마커), t2(A lp), t3(B마커), t5(B lp), t4] — 부모·자식 둘 다 각자 마커 직후로 float.
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 최상위 카드
    try std.testing.expectEqual(t1, session.tabs.items[1]); // A 마커 앵커
    try std.testing.expectEqual(t2, session.tabs.items[2]); // ★ A 직접 로컬 pin = A 마커 직후
    try std.testing.expectEqual(t3, session.tabs.items[3]); // B 마커(자식 subgroup 통째 — 부모 float서 안 쪼개짐)
    try std.testing.expectEqual(t5, session.tabs.items[4]); // ★ 자식 B leaf 로컬 pin = B 마커 직후(자식 subtree 안 float)
    try std.testing.expectEqual(t4, session.tabs.items[5]); // B 비-pin 멤버 → 뒤로
    // ── I3 보존: 자식 float이 부모 밖으로 안 새고 중첩 depth·subtree 경계 불변 ──
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(1, null, null)); // A=[1,6) 유지
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6) 유지
    try std.testing.expectEqual(@as(u8, 1), session.effectiveDepthAt(1, null, null)); // A d1
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B d2

    // ── 렌더(§13.6.1 재귀 동형): 각 마커 카드가 **자기 그룹의 로컬 pin 뒤**. 부모 A 카드·자식 B 카드 모두 로컬 pin 아래 ──
    session.recomputeVisibleTabs();
    const rows = session.sidebar_rows.items;
    // rows: [card t0, header A, card t2(A lp), card t1(A마커카드), header B, card t5(B lp), card t3(B마커카드), card t4]
    try std.testing.expectEqual(@as(usize, 8), rows.len);
    try std.testing.expectEqual(@as(usize, 0), rows[0].card.tab); // t0 최상위(d0)
    try std.testing.expect(rows[1] == .group_header); // A 헤더(d1)
    try std.testing.expectEqual(@as(u8, 1), rows[1].group_header.depth);
    try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // ★ A 직접 로컬 pin t2(마커 카드 위)
    try std.testing.expect(rows[2].card.local_pinned);
    try std.testing.expectEqual(@as(u8, 1), rows[2].card.depth); // A depth
    try std.testing.expectEqual(@as(usize, 1), rows[3].card.tab); // A 마커 자기 카드(로컬 pin 뒤)
    try std.testing.expect(!rows[3].card.local_pinned);
    try std.testing.expect(rows[4] == .group_header); // B 헤더(§2.1 부모 직접 카드 뒤·자식 그룹)
    try std.testing.expectEqual(@as(u8, 2), rows[4].group_header.depth); // ★ I3: B 중첩 depth2
    try std.testing.expectEqual(@as(usize, 4), rows[5].card.tab); // ★ 자식 B 로컬 pin t5(B 마커 카드 위 — 자식서도 성립)
    try std.testing.expect(rows[5].card.local_pinned);
    try std.testing.expectEqual(@as(u8, 2), rows[5].card.depth); // ★ I3: B 멤버 depth2
    try std.testing.expectEqual(@as(usize, 3), rows[6].card.tab); // B 마커 자기 카드(자식 로컬 pin 뒤)
    try std.testing.expect(!rows[6].card.local_pinned);
    try std.testing.expectEqual(@as(usize, 5), rows[7].card.tab); // B 비-pin 멤버 t4
    // 로컬 pin 📌: A 직접(t2)·자식 B(t5) 둘. 마커 카드·최상위·헤더는 억제.
    var member_pins: usize = 0;
    for (rows) |r| switch (r) {
        .agent_toggle, .agent => {},
        .card => |c| if (session.sidebarRowShowsPin(r)) {
            if (c.local_pinned) member_pins += 1;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(usize, 2), member_pins); // 부모·자식 각 1개
}

// GL4(c) — 회귀 매트릭스: 로컬 pin이 기존 기능 전부와 공존(안 부딪힘)함을 독립 블록으로 검증한다. 그룹 색(setGroupColor)·
// rename(startRenameGroup)·검색(sidebar_search)·pane 분리(promotePaneToNewWorkspace) 각각에서 로컬 pin float/플래그가
// 보존되는지 확인한다(그룹째 고정·드래그 프리뷰=확정·ungroup/removeFromGroup 위생은 GL3(a2)·GL3(d)·GL3(b*)가 이미 커버).
test "GL4(c): 회귀 매트릭스 — 로컬 pin이 그룹 색·rename·검색·pane 분리와 공존(float/플래그 보존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const init_opts = SessionConfig{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    };

    // ── (1) 그룹 색 + 로컬 pin: setGroupColorForTab이 색만 얹고 float·local_pinned를 안 건드린다 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3]
        session.toggleLocalPin(t3); // t3 → 마커 직후(index2)
        try std.testing.expectEqual(t3, session.tabs.items[2]);
        session.setGroupColorForTab(t3, 0x4A7BC4); // 색은 enclosing 마커(t1)에 저장
        try std.testing.expectEqual(@as(u32, 0x4A7BC4), t1.group_color); // ★ 색 얹힘
        try std.testing.expect(t3.local_pinned); // ★ 로컬 pin 보존
        try std.testing.expectEqual(t3, session.tabs.items[2]); // ★ float 순서 보존
    }

    // ── (2) rename + 로컬 pin: startRenameGroupForTab이 편집 상태만 세우고 순서·local_pinned를 안 건드린다 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab();
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1);
        session.toggleLocalPin(t3);
        var snap: [4]*Tab = undefined;
        for (session.tabs.items, 0..) |t, i| snap[i] = t;
        session.startRenameGroupForTab(t3); // 그룹 A 이름 인라인 편집 시작(마커 t1)
        for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap[i], t); // ★ 순서 불변
        try std.testing.expect(t3.local_pinned); // ★ 로컬 pin 보존
        session.rename = null; // 편집 상태 teardown(escape 경로와 동형)
        session.rename_input.clear();
    }

    // ── (3) 검색 + 로컬 pin: 매치되는 로컬 pin 멤버가 검색 중에도 float 위치·📌 유지(검색은 가시성 필터일 뿐 순서·플래그 무변) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3]
        session.toggleLocalPin(t3); // t3 → 마커 직후(index2)
        t3.custom_name = try allocator.dupe(u8, "findlp"); // 검색 매치용 이름(session.deinit이 free)
        session.sidebar_search_active = true;
        try session.sidebar_search_input.query.appendSlice(allocator, "findlp");
        session.recomputeVisibleTabs();
        // 매치 카드 t3(로컬 pin)이 접힘 무시하고 보이며, local_pinned 힌트·📌 유지.
        var saw_lp = false;
        for (session.sidebar_rows.items) |row| switch (row) {
            .agent_toggle, .agent => {},
            .card => |c| if (c.tab == 2) { // t3 = float 후 self.tabs index2
                saw_lp = true;
                try std.testing.expect(c.local_pinned); // ★ 검색 중에도 로컬 pin 힌트
                try std.testing.expect(session.sidebarRowShowsPin(row)); // ★ 📌 유지
            },
            .group_header => {},
        };
        try std.testing.expect(saw_lp);
        try std.testing.expect(t3.local_pinned); // ★ 검색이 플래그·순서 무변
        try std.testing.expectEqual(t3, session.tabs.items[2]);
        session.sidebar_search_active = false;
        session.sidebar_search_input.clear();
    }

    // ── (4) pane 분리 + 로컬 pin: promotePaneToNewWorkspace가 새 비고정 top-level 탭을 첫 마커 앞에 끼워도 그룹 안 로컬 pin
    //    float가 보존된다(새 카드=그룹 밖, local_pinned=false; 기존 그룹 내부 순서 불변). ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        // split은 backing이 잡혀야 의미 있음(termRect 입력) — resized 창을 흉내.
        session.backing_width_px = session.sidebar_width_px + 800;
        session.backing_height_px = 600;
        session.window_padding_px = .{};
        inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
        const t1 = session.tabs.items[1];
        const t2 = session.tabs.items[2];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2] — t0 최상위(분리 소스로 쓴다)
        session.toggleLocalPin(t2); // t2 로컬 pin → 마커 직후(index2, 이미 그 자리)
        try std.testing.expect(t2.local_pinned);
        // 최상위 t0(index0)을 활성으로 만들고 split → 2 pane → 그 새 pane을 새 워크스페이스로 분리.
        session.app_window.active_tab = 0;
        try session.splitActivePane(.horizontal); // t0 = [p0, p1], 활성 p1
        try std.testing.expectEqual(@as(usize, 2), session.tabs.items[0].panes.items.len);
        const before_len = session.tabs.items.len;
        session.promotePaneToNewWorkspace(session.activePane()); // p1 → 새 비고정 top-level 탭(첫 마커 앞 삽입)
        try std.testing.expectEqual(before_len + 1, session.tabs.items.len); // 새 탭 삽입됨
        // ★ 기존 그룹 A의 로컬 pin 보존: t2가 여전히 그룹 안·로컬 pin·마커 직후(index 이동은 됐어도 상대순서 불변).
        try std.testing.expect(t2.local_pinned); // ★ 로컬 pin 플래그 보존
        try std.testing.expect(session.tabIsInGroup(t2)); // 여전히 그룹 안
        const mi = session.enclosingGroupMarkerIndex(blk: {
            var idx: usize = 0;
            for (session.tabs.items, 0..) |t, i| if (t == t2) {
                idx = i;
                break;
            };
            break :blk idx;
        }).?;
        try std.testing.expectEqual(t1, session.tabs.items[mi]); // enclosing 마커 = t1(그룹 A 무결)
        // t2가 마커 직후(로컬 float 유지) — 삽입이 그룹 앞이라 subtree 내부 순서 불변.
        var t2_idx: usize = 0;
        for (session.tabs.items, 0..) |t, i| if (t == t2) {
            t2_idx = i;
            break;
        };
        try std.testing.expectEqual(mi + 1, t2_idx); // ★ 마커 직후(subtree-로컬 float 보존)
    }
}

// ── pin 회귀 매트릭스(사용자 경로 — cardPinRole 라우팅 + projectRowsCore 실제 row 소속) ─────────────────────────
// **왜 필요한가(그룹핀 리뷰 #9 갭)**: #9는 "self.tabs 인덱스"만 단언했고 **고정 그룹**(toggleGroupPin) 앞 top카드 흡수만
// 다뤘다. 실제 재발 경로는 (1) **비고정 그룹**이 있을 때 새 워크스페이스(Cmd+T)가 끝에 append돼 위치 파생상 마지막 그룹
// 멤버로 **흡수**되고, 그 카드 우클릭 pin이 cardPinRole=.local로 **그룹 안 float**되는 것 — index-only 단언은 이걸 놓친다
// (흡수는 **렌더 소속**=projectRowsCore depth/enclosing로만 잡힌다). 이 매트릭스는 두 축을 **실제 사용자 경로**로 통과한다:
// cardPinRole(우클릭 진입점 라우팅) + projectRowsCore(렌더된 카드가 그룹 밖 최상위인가).

/// 카드 `tab`이 **그룹 밖 최상위 고정 카드로 렌더**되는지 사용자 경로로 단언한다(pin 회귀 매트릭스 공용). self.tabs 인덱스가
/// 아니라 (1) cardPinRole=.individual(우클릭 pin이 개별 전역 pin으로 라우팅), (2) enclosing 마커 null·tabIsInGroup false
/// (소속 파생상 그룹 밖), (3) projectRowsCore가 이 카드를 depth 0·비파생·📌로 방출(렌더 소속=최상위)을 함께 본다.
fn expectCardTopLevelPinned(session: *AppSession, tab: *Tab) !void {
    try std.testing.expect(session.cardPinRole(tab) == .individual); // 우클릭 pin = 개별 전역 pin(그룹 위임/로컬 아님)
    try std.testing.expect(tab.group_start == null); // 마커 아님
    try std.testing.expect(tab.pinned); // 개별 pin 상태
    var idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == tab) {
        idx = i;
        break;
    };
    try std.testing.expect(session.enclosingGroupMarkerIndex(idx) == null); // 어느 그룹에도 안 속함
    try std.testing.expect(!session.tabIsInGroup(tab)); // 그룹 밖(흡수 없음)
    session.recomputeVisibleTabs();
    var found = false;
    for (session.sidebar_rows.items) |r| switch (r) {
        .agent_toggle, .agent => {},
        .card => |c| if (c.tab == idx) {
            found = true;
            try std.testing.expectEqual(@as(u8, 0), c.depth); // ★ 렌더 depth 0 = 최상위(그룹 흡수 없음)
            try std.testing.expect(!c.pin_derived); // 개별 pin(그룹 파생 캐시 아님)
            try std.testing.expect(!c.local_pinned); // 로컬 pin 아님(최상위엔 무의미)
            try std.testing.expect(session.sidebarRowShowsPin(r)); // ★ 📌 표시(개별 pin 카드)
        },
        .group_header => {},
    };
    try std.testing.expect(found); // 카드가 실제로 렌더됨(숨김 아님)
}

/// 우클릭 "위치 고정" 실제 진입점을 태운다(라벨·dispatch 공유 cardPinRole 라우팅) — acceptContextMenu의 ctx_menu_pin 경로.
fn rightClickPin(session: *AppSession, tab: *Tab) void {
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_pin;
    session.acceptContextMenu();
}

/// 워크스페이스 카드 우클릭 메뉴의 pin 라벨(cardPinRole 분기 결과) — context_menu_target 세팅 후 buildContextMenuItems 공유.
fn pinMenuLabel(session: *AppSession, tab: *Tab) []const u8 {
    session.context_menu_target = .{ .workspace = tab };
    return session.buildContextMenuItems()[ctx_menu_pin];
}

test "pin매트릭스 #1(버그1 회귀): 최상위 카드 위치 고정 — 5 배치 모두 그룹 밖 최상위 유지(cardPinRole=.individual·projectRows depth0·enclosing null·📌)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // ── (a) 그룹 없음: 순수 최상위 카드끼리 pin은 위치만.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..1) |_| _ = try session.newTab(); // [t0,t1]
        const x = session.tabs.items[0];
        try std.testing.expectEqualStrings("위치 고정", pinMenuLabel(session, x));
        rightClickPin(session, x);
        try expectCardTopLevelPinned(session, x);
    }

    // ── (b) 비고정 그룹 **앞** 최상위 카드: [X, G(비고정), A, B]. pin X → 그룹 밖 유지.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        session.createGroupAbsorbForTab(session.tabs.items[1]); // G=[t1,t2,t3], t0=최상위
        const x = session.tabs.items[0];
        rightClickPin(session, x);
        try expectCardTopLevelPinned(session, x);
    }

    // ── (c) **비고정 그룹 뒤 = 새 워크스페이스**(버그1 핵심): 비고정 그룹이 있을 때 Cmd+T로 새 탭을 만들면 끝 append로
    //    마지막 그룹에 흡수되던 버그. createTab 삽입점을 첫 그룹 앞으로 고쳐(promotePaneToNewWorkspace 동형) 새 탭이
    //    **최상위**로 뜬다. cardPinRole=.individual(그룹 내 위치 고정 아님)·pin 후 그룹 밖 유지. 옛 버그면 .local→흡수(fail).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..1) |_| _ = try session.newTab(); // [t0,t1]
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1]
        const y = try session.newTab(); // ★ 그룹 존재 시 새 워크스페이스 — 흡수 방지로 그룹 **앞**에 삽입돼야
        try std.testing.expect(session.cardPinRole(y) == .individual); // ★ 흡수 안 됨(옛 버그면 .local)
        try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null); // ★ y가 index0(그룹 앞)·그룹 밖
        try std.testing.expectEqualStrings("위치 고정", pinMenuLabel(session, y)); // "그룹 내 위치 고정" 아님
        rightClickPin(session, y);
        try expectCardTopLevelPinned(session, y);
    }

    // ── (d)/(e) 고정 그룹과 최상위 카드: 고정 그룹 존재 시 새 top카드(비고정 리전)를 pin → 고정 그룹 **앞**으로 안착
    //    (#1195 의도 — subtree 뒤 흡수 방지). "고정 그룹 뒤(비고정 리전)"→pin→"고정 그룹 앞"(둘 다 그룹 밖 최상위).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1,t2]
        session.toggleGroupPin(session.tabs.items[0]); // G 고정 → 프리픽스
        const y = try session.newTab(); // 새 top카드 — 고정 프리픽스 뒤(비고정 리전)
        try std.testing.expect(session.cardPinRole(y) == .individual); // 비고정 리전 top카드(고정 그룹 뒤) = 개별
        rightClickPin(session, y); // pin → 고정 그룹 **앞**으로(흡수 없음)
        try expectCardTopLevelPinned(session, y);
        // y가 고정 그룹 마커보다 **앞**(subtree 밖).
        var yidx: usize = 0;
        var gidx: usize = 0;
        for (session.tabs.items, 0..) |t, i| {
            if (t == y) yidx = i;
            if (t.group_start != null) gidx = i;
        }
        try std.testing.expect(yidx < gidx); // ★ 고정 그룹 앞(subtree 안 아님)
    }

    // ── 재토글(on→off): pin한 최상위 카드를 다시 우클릭 해제 → 개별 pin 풀림(흡수/잔류 없음, 그냥 top카드).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
        session.createGroupAbsorbForTab(session.tabs.items[1]); // G=[t1,t2], t0=최상위
        const x = session.tabs.items[0];
        rightClickPin(session, x);
        try expectCardTopLevelPinned(session, x);
        try std.testing.expectEqualStrings("고정 해제", pinMenuLabel(session, x));
        rightClickPin(session, x); // 해제
        try std.testing.expect(!x.pinned); // 개별 pin 풀림
        try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null); // 여전히 최상위(그룹 흡수 없음)
        try std.testing.expect(x.group_start == null and !x.local_pinned); // 마커 아님·로컬 pin 아님
    }
}

test "pin매트릭스 #2(버그2 회귀): 그룹째 고정/해제 — 고정 멤버 pinned=1·📌억제, 해제 멤버 pinned=0·local_pinned=0·📌 0(그냥 그룹 멤버)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    const countCardPins = struct {
        fn f(s: *AppSession) usize {
            s.recomputeVisibleTabs();
            var n: usize = 0;
            for (s.sidebar_rows.items) |r| switch (r) {
                .agent_toggle, .agent => {},
                .card => if (s.sidebarRowShowsPin(r)) {
                    n += 1;
                },
                .group_header => {},
            };
            return n;
        }
    }.f;

    // ── 기본(로컬 pin 없음): 고정→멤버 pinned=1·📌억제(헤더 인디케이터만)·해제→멤버 pinned=0·📌 0.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab();
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1,t2]
        const g = session.tabs.items[0];
        session.toggleGroupPin(g);
        try std.testing.expect(g.pinned and session.tabs.items[1].pinned and session.tabs.items[2].pinned); // 멤버 pinned=1
        try std.testing.expectEqual(@as(usize, 0), countCardPins(session)); // 카드 📌 0(멤버 억제·헤더 인디케이터가 표시)
        session.toggleGroupPin(g); // 해제
        try std.testing.expect(!g.pinned and !session.tabs.items[1].pinned and !session.tabs.items[2].pinned); // 멤버 pinned=0
        try std.testing.expect(!session.tabs.items[1].local_pinned and !session.tabs.items[2].local_pinned); // local_pinned 오염 없음
        try std.testing.expectEqual(@as(usize, 0), countCardPins(session)); // ★ 해제 후 카드 📌 0(그냥 그룹 멤버)
        try std.testing.expect(session.tabIsInGroup(session.tabs.items[1])); // 여전히 그룹 멤버(그냥 그룹 안)
    }

    // ── ★ 버그2 핵심: 멤버가 **로컬 pin**된 상태로 그룹째 고정 → 해제 시, 로컬 pin(📌)이 잔류하면 자식이 개별 고정으로
    //    남는다. 해제 = 그룹 리셋이라 멤버 local_pinned도 클리어돼 카드 📌 0이어야 한다("그냥 그룹 멤버로 복귀").
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab();
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1,t2]
        const g = session.tabs.items[0];
        const member = session.tabs.items[2];
        session.toggleLocalPin(member); // 멤버 로컬 pin(📌·마커 직후 float)
        try std.testing.expect(member.local_pinned);
        try std.testing.expectEqual(@as(usize, 1), countCardPins(session)); // 로컬 pin 카드 1개 📌(비고정 그룹)
        session.toggleGroupPin(g); // 그룹째 고정(로컬 pin은 켜는 동안 보존 — keystone)
        try std.testing.expect(member.local_pinned); // 고정 중 보존
        session.toggleGroupPin(g); // ★ 해제 = 그룹 리셋
        try std.testing.expect(!member.pinned); // 파생 pin 해제
        try std.testing.expect(!member.local_pinned); // ★ 로컬 pin도 클리어(버그2 fix — 개별 📌 잔류 방지)
        try std.testing.expectEqual(@as(usize, 0), countCardPins(session)); // ★ 해제 후 카드 📌 0(그냥 그룹 멤버)
        try std.testing.expect(session.tabIsInGroup(member)); // 여전히 그룹 멤버(그룹 밖으로 안 나감)
    }
}

test "pin매트릭스 #3(조합): 최상위 개별 pin + 그룹째 고정 + 멤버 로컬 pin 공존 — 렌더 소속·📌 카운트(축 3개 독립)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 12, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    // t0=최상위 개별 pin 카드, A=[t1(마커), t2, t3] 그룹째 고정, t3=로컬 pin 멤버.
    session.createGroupAbsorbForTab(session.tabs.items[1]); // A=[t1,t2,t3]
    const top = session.tabs.items[0];
    const marker = session.tabs.items[1];
    const lp = session.tabs.items[3];
    session.toggleLocalPin(lp); // A 멤버 로컬 pin
    rightClickPin(session, top); // t0 개별 전역 pin(.individual)
    session.toggleGroupPin(marker); // A 그룹째 고정
    // 세 축 독립: 개별 pin(top.pinned)·그룹째(marker.pinned)·로컬(lp.local_pinned) 공존.
    try std.testing.expect(top.pinned and top.group_start == null); // 개별 최상위
    try std.testing.expect(marker.pinned); // 그룹째 고정 권위
    try std.testing.expect(lp.pinned and lp.local_pinned); // 파생 캐시 + 로컬 pin
    try expectCardTopLevelPinned(session, top); // 최상위 카드는 흡수 없이 그룹 밖 최상위 📌
    // 렌더 📌 카운트: 최상위 카드 1(개별) + 헤더 1(그룹째 인디케이터) + 로컬 pin 멤버 1 = 카드 2·헤더 1.
    session.recomputeVisibleTabs();
    var card_pins: usize = 0;
    var header_pins: usize = 0;
    for (session.sidebar_rows.items) |r| switch (r) {
        .agent_toggle, .agent => {},
        .card => if (session.sidebarRowShowsPin(r)) {
            card_pins += 1;
        },
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 2), card_pins); // 최상위 개별 + 로컬 pin 멤버
    try std.testing.expectEqual(@as(usize, 1), header_pins); // 그룹째 고정 헤더 인디케이터
}

test "SG5-1: 그룹 통째 이동(moveGroupRange + sidebarGroupDropBoundary) — 위/아래·최상위·끝 + 자기그룹 no-op + 연속 파티션" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // 최상위 카드 t0·t1 + 두 **형제** 그룹 A=[t2,t3], B=[t4,t5](§2.1: 최상위는 첫 마커 이전 구간에만).
    // SG5-3: create_group은 그룹 안 카드에서 depth+1 중첩이라, A가 끝까지 뻗은 뒤 t4에 부르면 B가 A 자식(depth 2)이 된다.
    // 이 테스트는 형제 그룹 통째 이동을 보므로 B의 depth를 1로 명시해 형제 최상위 그룹으로 둔다(§9 tension 문서화).
    session.createGroupAbsorbForTab(t2); // A(마커 index2)
    session.createGroupAbsorbForTab(t4); // B(마커 index4) — 중첩 기본
    t4.group_depth = 1; // B를 최상위 형제로 오버라이드
    // 마커 수·초기 순서 확인.
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // 최상위
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // A 마커 카드
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B 마커 카드

    const markerCount = struct {
        fn f(s: *AppSession) usize {
            var n: usize = 0;
            for (s.tabs.items) |t| if (t.group_start != null) {
                n += 1;
            };
            return n;
        }
    }.f;
    try std.testing.expectEqual(@as(usize, 2), markerCount(session)); // 항상 마커 2개(그룹 2개)

    // ── ① 그룹 B를 **최상위 카드에 드롭** → 그룹들 최상단(첫 그룹 앞, 최상위 뒤). row0=최상위 카드 t0.
    session.recomputeVisibleTabs(); // [c t0(0), c t1(1), hA(2), c t2(3), c t3(4), hB(5), c t4(6), c t5(7)]
    {
        const m: usize = 4; // 그룹 B 마커(t4)
        const boundary = session.sidebarGroupDropBoundary(0, m).?; // 최상위 카드 row0 → 첫 그룹 앞 = 2
        try std.testing.expectEqual(@as(usize, 2), boundary);
        const nm = session.moveGroupRange(m, boundary, false);
        try std.testing.expectEqual(@as(usize, 2), nm); // 새 마커 인덱스(t4가 index2로)
    }
    // 결과 [t0, t1, t4(B), t5, t2(A), t3] — B가 그룹들 최상단, 최상위 t0·t1는 앞에 그대로.
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t4, session.tabs.items[2]);
    try std.testing.expectEqual(t5, session.tabs.items[3]);
    try std.testing.expectEqual(t2, session.tabs.items[4]);
    try std.testing.expectEqual(t3, session.tabs.items[5]);
    try std.testing.expectEqual(@as(usize, 2), markerCount(session)); // 여전히 그룹 2개(쪼개짐 없음)
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위 보존
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // 최상위 보존
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t5)); // B 몸통(연속)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // A 몸통(연속)

    // ── ② 그룹 A(마커 index4)를 **다른 그룹 헤더(B) 위에 드롭** → 그 그룹 앞으로(위로 이동). rows: [c t0, c t1, hB(2), c t4, c t5, hA(5), c t2, c t3].
    session.recomputeVisibleTabs();
    {
        const m: usize = 4; // 그룹 A 마커(t2)
        const boundary = session.sidebarGroupDropBoundary(2, m).?; // B 헤더 row2, gi=2<m=4 → B 앞(2)
        try std.testing.expectEqual(@as(usize, 2), boundary);
        _ = session.moveGroupRange(m, boundary, false);
    }
    // 결과 [t0, t1, t2(A), t3, t4(B), t5] — A가 B 앞으로(원래 순서 복귀).
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t4, session.tabs.items[4]);
    try std.testing.expectEqual(@as(usize, 2), markerCount(session));

    // ── ③ 그룹 A(마커 index2)를 **다른 그룹(B)의 카드에 드롭** → 그 그룹 뒤(끝)로(아래로 이동). rows: [c t0, c t1, hA(2), c t2, c t3, hB(5), c t4, c t5].
    session.recomputeVisibleTabs();
    {
        const m: usize = 2; // 그룹 A 마커(t2)
        const boundary = session.sidebarGroupDropBoundary(7, m).?; // B 카드 t5(row7), gi=4>m=2 → B 뒤(끝)=6
        try std.testing.expectEqual(@as(usize, 6), boundary);
        const nm = session.moveGroupRange(m, boundary, false);
        try std.testing.expectEqual(@as(usize, 4), nm); // A가 끝(index4)으로
    }
    // 결과 [t0, t1, t4(B), t5, t2(A), t3] — A가 리스트 끝 그룹.
    try std.testing.expectEqual(t4, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[4]);
    try std.testing.expectEqual(t3, session.tabs.items[5]);
    try std.testing.expectEqual(@as(usize, 2), markerCount(session));

    // ── ④ 자기 그룹에 드롭 = no-op(boundary null). A(마커 index4)의 자기 카드(t3, row?)에 드롭. rows: [c t0, c t1, hB(2), c t4, c t5, hA(5), c t2, c t3].
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebarGroupDropBoundary(5, 4) == null); // A 헤더(자기) → null
    try std.testing.expect(session.sidebarGroupDropBoundary(7, 4) == null); // A 몸통 카드(자기) → null
    // moveGroupRange도 자기 자리 boundary(구간 안)면 no-op으로 m을 그대로 돌려준다.
    try std.testing.expectEqual(@as(usize, 4), session.moveGroupRange(4, 4, false)); // insert_before==m → no-op
    try std.testing.expectEqual(@as(usize, 4), session.moveGroupRange(4, 6, false)); // insert_before==j(=len) → no-op(이미 끝)
    // 비-마커 인덱스로 moveGroupRange 호출 방어(가드). t5(index3)는 마커 아님 → m 그대로.
    try std.testing.expectEqual(@as(usize, 3), session.moveGroupRange(3, 0, false));
}

// ── §14.6 SR4 인터리빙 회귀 — 그룹 통째 드래그 ↔ top_level 탭 순서 교환 ──────────────────────────────────────────
// 증상: §2.1 재설계(§14)로 top_level 탭이 그룹 뒤/사이에 오는데, `sidebarGroupDropBoundary`가 최상위 카드를 전부 "리딩
// zone"(첫 그룹 이전)으로만 보고 `first_group`으로 clamp해 **그룹이 top_level 탭 위/사이로 못 갔다**(카드 드래그 SR4는
// 되는데 그룹 드래그만 안 됨). 아래 테스트는 그룹 드래그가 top_level 탭과 자유롭게 순서를 교환하고(그룹↔탭 인터리빙),
// top_level 불변·프리뷰=확정·고정 리전 clamp가 정합함을 고정한다. 리딩 카드(플래그 없음)는 옛 clamp 폴백이라 SG5-1 회귀 0.

/// 표시 카드 row 인덱스를 tab 인덱스로 찾는다(그룹 드래그 경계 테스트가 커서 hit-test 대신 쓰는 헤드리스 헬퍼).
fn cardRowOf(session: *AppSession, tab_idx: usize) usize {
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .agent_toggle, .agent => {},
        .card => |c| if (c.tab == tab_idx) return s,
        .group_header => {},
    };
    return 0;
}

/// 표시 row의 화면 y(backing px)를 그 row 안 frac 위치로 — cardDropPlan 실좌표(y_px) 테스트가 커서 y를 구성한다.
fn sidebarDragScreenY(session: *AppSession, row: usize, frac: f64) f64 {
    const rows = session.sidebar_rows.items;
    const top = chrome.components.sidebar.rowTop(rows, row, session.sidebar_header_height_px, session.sidebarMetrics(), session.sidebar_scroll_offset_px);
    const h = chrome.components.sidebar.rowHeight(rows[row], session.sidebarMetrics());
    return @as(f64, @floatFromInt(top)) + @as(f64, @floatFromInt(h)) * frac;
}

// ── (A) 카드 드래그 실좌표(y_px→cardDropPlan) — 고정 탭을 그룹 꼬리로 끌면 top_level 탈출(흡수 아님) ────────────────
// 증상 A: 실앱에서 고정 탭을 드래그하면 그룹 안 멤버로 **흡수**(top_level=false). 기존 헤드리스는 raw_row·y를 직접 넣어
// (SR5(a)) hit-test **함수**만 봤고, mouse 핸들러의 y_px→raw_row→plan **실경로**(특히 드래그 소스가 프리뷰에서 빠져 그
// 아래가 위로 밀리는 시프트)를 안 탔다. 이 테스트는 cardDropPlan(실 핸들러가 부르는 단일 출처)을 커서 y로 태워 그 갭을
// 메운다: 사용자가 프리뷰의 그룹 꼬리를 겨냥하면 top_level 탈출이 발화하고, 보정 없던 옛 판정은 흡수였음을 대비로 고정한다.
test "(A) 카드 드래그 실좌표: 고정 탭을 그룹 꼬리로 끌면 top_level 탈출 (cardDropPlan y_px 실경로·프리뷰 시프트 보정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2] 고정 리전
    inline for (0..3) |i| session.tabs.items[i].pinned = true;
    // X=t0(고정 leading 탭, top_level=false — createGroup이 남기는 실제 상태), A=[a0=t1(마커), a1=t2(멤버)].
    try setGroupMarker(session, 1, "A", 1);
    session.sidebar_slot_height_px = 40;
    // 카드 높이는 이제 줄 수 기반이라 슬롯 필드만으로는 안 잡힌다 — 1줄 카드 높이가 40이 되는 메트릭을 박아
    // 고정 슬롯 시절 좌표 기대값을 그대로 쓴다(여백 0·스텝=줄높이).
    session.sidebar_metrics = .{ .line_h = 40, .line_step = 40, .card_pad_v = 0, .header_row_h = session.sidebar_header_row_h_px, .content_pad_v = 0, .list_pad_v = 0 };
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.pointer_gesture_owner = .{ .sidebar_tab = .{ .index = 0 } }; // X가 드래그 소스

    // 표시 행(원본): [card X(0), header A(1), card a0(2), card a1(3)]. a1=마지막 멤버(그룹 꼬리).
    const a1_row = cardRowOf(session, 2);
    try std.testing.expectEqual(@as(usize, 3), a1_row);

    // ① 그룹 꼬리(마지막 멤버 a1의 상단 frac 0.15) 겨냥 — 프리뷰에선 X가 빠져 그룹이 위로 밀리므로 사용자가 보는
    //    "그룹 꼬리"는 원본 a1 상단쯤이다. 옛 판정(보정 없이 이 y로 sidebarCardDropAfterGroup)은 하단 40% 밖이라 흡수였다.
    const y_tail = sidebarDragScreenY(session, a1_row, 0.15);
    // 옛 경로(보정 없음) 대비: raw_row=a1, 하단 경계 아님 → 탈출 null(흡수). 이게 헤드리스가 못 잡던 실패다.
    const raw_uncomp = chrome.components.sidebar.dragTargetSlot(y_tail, session.sidebar_header_height_px, session.sidebar_rows.items, session.sidebarMetrics(), session.sidebar_scroll_offset_px);
    try std.testing.expect(session.sidebarCardDropAfterGroup(raw_uncomp, 0, y_tail) == null); // 보정 없으면 탈출 안 함(흡수)
    // 새 경로(cardDropPlan, 프리뷰 시프트 보정) → top_level 탈출.
    const plan_tail = session.cardDropPlan(0, y_tail);
    switch (plan_tail) {
        .card => |c| {
            try std.testing.expect(c.top_level); // ★ 흡수 아님 — 그룹 밖 top_level
            try std.testing.expectEqual(@as(usize, 2), c.target_tab); // a1(그룹 꼬리) 자리
        },
        else => return error.TestUnexpectedResult,
    }

    // ② 실제 commit → X가 그룹 A 뒤 최상위(흡수 안 됨).
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = plan_tail, .cursor_y = y_tail, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    const x = session.tabs.items[2]; // X가 [a0, a1, X]로 밀림
    try std.testing.expect(x.top_level); // ★ top_level 유지(그룹 밖)
    try std.testing.expect(session.enclosingGroupMarkerIndex(2) == null); // 그룹 A에 흡수 안 됨
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(2, null, null));
    try std.testing.expect(session.tabs.items[0].group_start != null); // A 마커(a0)가 index0으로

    // ③ 새 정책(고정 흡수 금지): 같은 **고정** 탭을 그룹 상단(첫 멤버)에 드롭해도 흡수 안 됨 = top_level=true.
    //    옛 동작은 위치가 그룹 안이면 멤버 흡수(false)였으나, 고정 소스는 위치 무관하게 top_level 강제 — "고정된 건 어디에도
    //    흡수 안 됨". 비고정 소스의 멤버 넣기 능력(회귀 0)은 아래 별도 테스트(SR-PIN 비고정 대비)가 지킨다.
    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();
    inline for (0..2) |_| _ = try s2.newTab();
    inline for (0..3) |i| s2.tabs.items[i].pinned = true;
    try setGroupMarker(s2, 1, "A", 1);
    s2.sidebar_slot_height_px = 40;
    // 카드 높이는 이제 줄 수 기반이라 슬롯 필드만으로는 안 잡힌다 — 1줄 카드 높이가 40이 되는 메트릭을 박아
    // 고정 슬롯 시절 좌표 기대값을 그대로 쓴다(여백 0·스텝=줄높이).
    s2.sidebar_metrics = .{ .line_h = 40, .line_step = 40, .card_pad_v = 0, .header_row_h = s2.sidebar_header_row_h_px, .content_pad_v = 0, .list_pad_v = 0 };
    s2.sidebar_header_row_h_px = 20;
    s2.sidebar_header_height_px = 30;
    s2.sidebar_scroll_offset_px = 0;
    s2.recomputeVisibleTabs();
    s2.pointer_gesture_owner = .{ .sidebar_tab = .{ .index = 0 } };
    const a0_row = cardRowOf(s2, 1); // a0(첫 멤버) row
    const y_head = sidebarDragScreenY(s2, a0_row, 0.2); // 첫 멤버 상단 = 그룹 안이지만 고정 소스라 흡수 금지
    const plan_head = s2.cardDropPlan(0, y_head);
    switch (plan_head) {
        .card => |c| try std.testing.expect(c.top_level), // ★ 고정 소스 = 그룹 안 드롭이어도 흡수 금지(top_level 강제)
        else => return error.TestUnexpectedResult,
    }
}

// ── SR-PIN: "고정된 건 어디에도 흡수 안 됨" — 고정 탭/그룹은 고정 리전 안 top_level(그룹 밖)로만 존재(사용자 정책) ──────
// 4개 규율을 헤드리스로 고정한다: (1) 프리뷰=확정 유실 수정(commit이 저장 plan.top_level 그대로 씀), (2) 고정 탭 그룹 흡수
// 금지(위치 무관 top_level 강제), (3) 고정 그룹 nest 흡수 금지(Cmd nest여도 sibling), (4) 고정 리전 clamp(비고정으로 안 넘어감).
// 특히 (1)(2)는 **전체 마우스 경로**(cardDropPlan=mouseMoved 산출 → refreshDragPreview=sidebar_drag_preview.plan 저장 →
// commitSidebarDragPreview=up 확정)를 태워, 헤드리스가 commit을 직접 호출하던 사각(실앱 mouse→preview→commit 체인)을 메운다.

test "SR-PIN1: 고정 탭을 그룹 한복판에 드롭 → 흡수 금지(전체 마우스 경로 cardDropPlan→저장→commit, 프리뷰=확정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 4개, 전부 고정 리전
    inline for (0..4) |i| session.tabs.items[i].pinned = true;
    // X=t0(고정 leading 탭, 드래그 소스), A=[Am=t1(마커), a1=t2, a2=t3]. a1=**한복판 멤버**(꼬리/헤더 아님, gap 미발화).
    try setGroupMarker(session, 1, "A", 1);
    session.sidebar_slot_height_px = 40;
    // 카드 높이는 이제 줄 수 기반이라 슬롯 필드만으로는 안 잡힌다 — 1줄 카드 높이가 40이 되는 메트릭을 박아
    // 고정 슬롯 시절 좌표 기대값을 그대로 쓴다(여백 0·스텝=줄높이).
    session.sidebar_metrics = .{ .line_h = 40, .line_step = 40, .card_pad_v = 0, .header_row_h = session.sidebar_header_row_h_px, .content_pad_v = 0, .list_pad_v = 0 };
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.pointer_gesture_owner = .{ .sidebar_tab = .{ .index = 0 } };
    const x_ptr = session.tabs.items[0];
    const am_ptr = session.tabs.items[1];
    const a1_ptr = session.tabs.items[2];
    const a2_ptr = session.tabs.items[3]; // 한복판 뒤 멤버 — [2] 그룹 무결(안 eject) 검증 대상

    // 표시 행: [card X(0), header A(1), card a1(2), card a2(3)]. a1(=tab2) 한복판을 frac 0.3(상단)로 겨냥 →
    // 하단 경계(gap) 미발화라 sidebarGroupDropTargetTab(멤버 자리)+sidebarCardDropTopLevel(그룹 멤버=false) 경로.
    const a1_row = cardRowOf(session, 2);
    const y_mid = sidebarDragScreenY(session, a1_row, 0.3);
    // ① mouseMoved 산출(cardDropPlan): 고정 소스라 흡수 금지(top_level=true 강제) + **[2] 그룹 안 착지 금지** — target을
    // 그룹 A subtree 밖 경계로 clamp. origin=0(그룹 위)이라 그룹 뒤 끝(ge-1=3)으로 착지(한복판 2가 아니라 경계).
    const plan_mid = session.cardDropPlan(0, y_mid);
    switch (plan_mid) {
        .card => |c| {
            try std.testing.expectEqual(@as(usize, 3), c.target_tab); // ★ [2] 그룹 subtree 밖 경계(뒤 끝)로 clamp(한복판 2 아님)
            try std.testing.expect(c.top_level); // ★ 고정 소스 = 흡수 금지(위치 무관 top_level 강제)
        },
        else => return error.TestUnexpectedResult,
    }
    // ② refreshDragPreview가 그 plan을 sidebar_drag_preview.plan에 **저장**(실 핸들러 mouseMoved의 저장 지점).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try session.refreshDragPreview(0, plan_mid, y_mid, arena_state.allocator());
    try std.testing.expect(session.sidebar_drag_preview != null);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .card);
    try std.testing.expect(session.sidebar_drag_preview.?.plan.card.top_level); // ★ 저장된 plan에 top_level=true 온전

    // ③ up 확정(commitSidebarDragPreview): 저장 plan을 그대로 replay — X가 그룹 경계(뒤)에 착지, 그룹 A는 무결.
    session.commitSidebarDragPreview();
    // 확정 배치 [Am, a1, a2, X] — X는 그룹 A **뒤** 고정 top카드(흡수 아님), 그룹 A=[Am,a1,a2] 온전(a2 안 eject).
    try std.testing.expectEqual(am_ptr, session.tabs.items[0]);
    try std.testing.expectEqual(a1_ptr, session.tabs.items[1]);
    try std.testing.expectEqual(a2_ptr, session.tabs.items[2]);
    try std.testing.expectEqual(x_ptr, session.tabs.items[3]); // X가 그룹 뒤 경계(position 3)
    try std.testing.expect(session.tabs.items[3].top_level); // ★ 흡수 금지(top_level 확정 write)
    try std.testing.expect(session.enclosingGroupMarkerIndex(3) == null); // X는 그룹 A 멤버 아님
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(3, null, null)); // 그룹 밖(depth0)
    try std.testing.expect(session.tabs.items[3].pinned); // 고정 유지(고정 리전 안)
    // ★ [2] 그룹 무결 — 뒤 멤버 a2가 그룹에서 eject되지 않았다(revert하면 X가 한복판에 착지해 a2가 top-level로 튕겨나감).
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(2).?); // a2는 여전히 A(마커 index0) 멤버
    try std.testing.expect(!a2_ptr.top_level); // a2 안 eject
    try std.testing.expectEqual(@as(usize, 3), session.groupSubtreeEnd(0, null, null)); // A=[0,3) 완전 subtree(쪼개짐 없음)
}

test "SR-PIN2: 비고정 탭을 같은 그룹 한복판에 드롭 → 흡수 유지(top_level=false, 비고정 회귀 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3], 전부 **비고정**(기본)
    try setGroupMarker(session, 1, "A", 1); // X=t0(top카드), A=[Am=t1, a1=t2, a2=t3]
    session.sidebar_slot_height_px = 40;
    // 카드 높이는 이제 줄 수 기반이라 슬롯 필드만으로는 안 잡힌다 — 1줄 카드 높이가 40이 되는 메트릭을 박아
    // 고정 슬롯 시절 좌표 기대값을 그대로 쓴다(여백 0·스텝=줄높이).
    session.sidebar_metrics = .{ .line_h = 40, .line_step = 40, .card_pad_v = 0, .header_row_h = session.sidebar_header_row_h_px, .content_pad_v = 0, .list_pad_v = 0 };
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.pointer_gesture_owner = .{ .sidebar_tab = .{ .index = 0 } };
    const a1_row = cardRowOf(session, 2);
    const y_mid = sidebarDragScreenY(session, a1_row, 0.3);
    const plan_mid = session.cardDropPlan(0, y_mid);
    switch (plan_mid) {
        .card => |c| {
            try std.testing.expectEqual(@as(usize, 2), c.target_tab);
            try std.testing.expect(!c.top_level); // ★ 비고정 소스 = 그룹 안 = 멤버 흡수(top_level=false, 기존 동작)
        },
        else => return error.TestUnexpectedResult,
    }
    // 전체 경로 확정 후에도 흡수(그룹 A 멤버).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try session.refreshDragPreview(0, plan_mid, y_mid, arena_state.allocator());
    session.commitSidebarDragPreview();
    try std.testing.expect(!session.tabs.items[2].top_level); // 멤버(흡수)
    try std.testing.expect(session.enclosingGroupMarkerIndex(2) != null); // ★ 그룹 A에 흡수됨(비고정 능력 보존)
}

test "SR-PIN3: 고정 그룹은 다른 그룹에 nest 흡수 금지(Cmd nest여도 sibling) + 비고정 그룹은 nest 유지" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    // ── Part 1: 고정 그룹 A를 고정 그룹 B 헤더에 Cmd 드롭 → sibling(nest 안 됨) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        inline for (0..4) |i| session.tabs.items[i].pinned = true; // 전부 고정
        try setGroupMarker(session, 0, "A", 1); // A=[Am=t0, a1=t1]
        try setGroupMarker(session, 2, "B", 1); // B=[Bm=t2, b1=t3]
        session.recomputeVisibleTabs();
        var b_header_row: usize = 0;
        for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
            .agent_toggle, .agent => {},
            .group_header => |gh| if (gh.tab == 2) {
                b_header_row = s;
            },
            .card => {},
        };
        // groupNestPlan 직접: 드래그 그룹 마커(0)가 고정이라 nest 불가 → null(형제 폴백).
        try std.testing.expect(session.groupNestPlan(b_header_row, 0) == null); // ★ 고정 그룹 nest 금지
        // 전체 프레임(Cmd 눌림): nest 시도해도 sibling으로 폴백.
        const y_b = sidebarDragScreenY(session, b_header_row, 0.5);
        session.groupDragPreviewFrame(0, y_b, true); // cmd_held=true
        try std.testing.expect(session.sidebar_drag_preview != null);
        try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling); // ★ Cmd여도 sibling(중첩 아님)
        session.clearSidebarDragPreview();
    }
    // ── Part 2: 비고정 그룹 A를 비고정 그룹 B 헤더에 Cmd 드롭 → nest(중첩 유지, 회귀 0) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 전부 비고정
        try setGroupMarker(session, 0, "A", 1);
        try setGroupMarker(session, 2, "B", 1);
        session.recomputeVisibleTabs();
        var b_header_row: usize = 0;
        for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
            .agent_toggle, .agent => {},
            .group_header => |gh| if (gh.tab == 2) {
                b_header_row = s;
            },
            .card => {},
        };
        try std.testing.expect(session.groupNestPlan(b_header_row, 0) != null); // 비고정 = nest 가능(기존 동작)
        const y_b = sidebarDragScreenY(session, b_header_row, 0.5);
        session.groupDragPreviewFrame(0, y_b, true); // cmd_held=true
        try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_nest); // ★ 비고정 Cmd = 중첩(회귀 0)
        session.clearSidebarDragPreview();
    }
}

test "SR-PIN4: 고정 탭을 비고정 리전 위치로 드래그 → 고정 리전 끝으로 clamp(비고정 안 넘어감, 전체 경로)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    session.tabs.items[0].pinned = true; // X=t0(고정, 드래그 소스)
    session.tabs.items[1].pinned = true; // P1=t1(고정)
    // u2=t2 비고정. 고정 리전 [0,2), 비고정 [2,3).
    session.sidebar_slot_height_px = 40;
    // 카드 높이는 이제 줄 수 기반이라 슬롯 필드만으로는 안 잡힌다 — 1줄 카드 높이가 40이 되는 메트릭을 박아
    // 고정 슬롯 시절 좌표 기대값을 그대로 쓴다(여백 0·스텝=줄높이).
    session.sidebar_metrics = .{ .line_h = 40, .line_step = 40, .card_pad_v = 0, .header_row_h = session.sidebar_header_row_h_px, .content_pad_v = 0, .list_pad_v = 0 };
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.pointer_gesture_owner = .{ .sidebar_tab = .{ .index = 0 } };
    const x_ptr = session.tabs.items[0];
    const u2_ptr = session.tabs.items[2];
    // X(고정)를 u2(비고정, position 2) 위로 드래그. target=2(비고정 리전)여도 clampMoveToGroup이 고정 리전 끝(1)로 가둔다.
    const u2_row = cardRowOf(session, 2);
    const y_u2 = sidebarDragScreenY(session, u2_row, 0.5);
    const plan = session.cardDropPlan(0, y_u2);
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try session.refreshDragPreview(0, plan, y_u2, arena_state.allocator());
    session.commitSidebarDragPreview();
    // X는 고정 리전 끝(position 1)까지만 — 비고정(position 2)으로 못 넘어간다. u2는 여전히 position 2.
    try std.testing.expectEqual(x_ptr, session.tabs.items[1]); // ★ X가 고정 리전 끝(1)로 clamp
    try std.testing.expect(session.tabs.items[1].pinned); // 고정 유지
    try std.testing.expectEqual(u2_ptr, session.tabs.items[2]); // u2 비고정 자리 불변(X 안 넘어옴)
    try std.testing.expect(!session.tabs.items[2].pinned);
}

test "SR-PIN5: 프리뷰=확정 등가 — 고정 탭 그룹 한복판 drop plan을 simulateDrop vs commitSidebarDragPreview 동일" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    inline for (0..4) |i| session.tabs.items[i].pinned = true; // 전부 고정
    try setGroupMarker(session, 1, "A", 1); // X=t0, A=[Am=t1, a1=t2, a2=t3]
    session.recomputeVisibleTabs();
    // 고정 소스 X를 그룹 경계(뒤 끝 position 3 — [2] cardDropPlan이 그룹 밖으로 clamp할 값)로, top_level=true.
    // simulateDrop 가상 top_level[] == commitSidebarDragPreview 후 실제 top_level[] (프리뷰=확정 게이트 동일).
    try expectCardDropTopLevelEquivalent(session, 0, .{ .card = .{ .target_tab = 3, .top_level = true } });
}

// ── (3) 드래그 중 접힌 그룹은 접힌 헤더로만 — 대상=접힌 그룹이면 subtree force-emit 억제, 타깃=접힌 그룹은 유지 ────────
// SG8은 고스트가 접힌 그룹 subtree에 들어가면 "드롭 시 사라짐" 방지로 force-emit했다. 사용자 요청: 접힌 그룹을 **통째로
// 드래그**하면 고스트도 접힌 헤더 한 줄이어야(펼쳐 보이면 안 됨). 단 접힌 **타깃** 그룹 안으로 카드를 드롭할 때의
// force-emit(사라짐 방지)는 유지한다(대상 vs 타깃 구분).
test "(3) 드래그 대상이 접힌 그룹이면 프리뷰=접힌 헤더만 (타깃 접힌 그룹 드롭의 force-emit는 유지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    // ── Part 1: 접힌 그룹 A를 통째 드래그 → 프리뷰에 A는 접힌 헤더 1줄, 멤버 카드 0 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        try setGroupMarker(session, 0, "A", 1); // A=[a0=t0(접힘), a1=t1]
        session.tabs.items[0].group_collapsed = true;
        try setGroupMarker(session, 2, "B", 1); // B=[b0=t2, b1=t3]
        session.recomputeVisibleTabs();
        var arena_state = std.heap.ArenaAllocator.init(allocator);
        defer arena_state.deinit();
        const insert_before = session.groupSubtreeEnd(2, null, null);
        try session.refreshDragPreview(0, .{ .group_sibling = .{ .insert_before = insert_before } }, 0, arena_state.allocator());
        var a_header_rows: usize = 0;
        var a_card_rows: usize = 0;
        var a_header_collapsed = false;
        for (session.sidebar_preview_rows.items) |row| switch (row) {
            .agent_toggle, .agent => {},
            .group_header => |h| if (h.tab == 0) {
                a_header_rows += 1;
                a_header_collapsed = h.collapsed;
            },
            .card => |c| if (c.tab == 0 or c.tab == 1) {
                a_card_rows += 1;
            },
        };
        try std.testing.expectEqual(@as(usize, 1), a_header_rows); // A 헤더 1줄
        try std.testing.expectEqual(@as(usize, 0), a_card_rows); // ★ 멤버 카드 방출 안 됨(접힌 채)
        try std.testing.expect(a_header_collapsed); // ★ 헤더 접힘 유지(펼침 flip 안 함)
        session.clearSidebarDragPreview();
    }
    // ── Part 2: 접힌 **타깃** 그룹 B 안으로 카드 X를 드롭 → force-emit 유지(카드 고스트 방출·사라짐 방지) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
        // B=[b0=t0(접힘), b1=t1], X=t2(최상위 카드)
        try setGroupMarker(session, 0, "B", 1);
        session.tabs.items[0].group_collapsed = true;
        session.recomputeVisibleTabs();
        var arena_state = std.heap.ArenaAllocator.init(allocator);
        defer arena_state.deinit();
        // X(t2)를 접힌 B 끝으로 드롭(카드 드래그, dragged_collapsed=false).
        const target = session.groupSubtreeEnd(0, null, null) - 1; // 접힌 B subtree 끝
        try session.refreshDragPreview(2, .{ .card = .{ .target_tab = target } }, 0, arena_state.allocator());
        var x_visible = false;
        for (session.sidebar_preview_rows.items) |row| switch (row) {
            .agent_toggle, .agent => {},
            .card => |c| if (c.tab == 2) {
                x_visible = true;
            },
            .group_header => {},
        };
        try std.testing.expect(x_visible); // ★ 접힌 타깃 안 드롭이라도 X 고스트 방출(force-emit 유지 — 사라짐 방지)
        session.clearSidebarDragPreview();
    }
}

test "SR4 그룹드래그(a): [탭X, 그룹A]에서 A를 X 앞으로 → [그룹A, 탭X](순서 교환·X top_level 유지, 실제 commit 경로)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // init 기본 탭 1개 + 2개 = [t0, t1, t2] 3개
    // [X(t0, top_level 탭), A=[a0(t1,마커), a1(t2,멤버)]]. X는 첫 그룹 이전이지만 top_level 플래그가 서 있어 인터리브 대상.
    const x = session.tabs.items[0];
    x.top_level = true;
    try setGroupMarker(session, 1, "A", 1);
    session.recomputeVisibleTabs();
    try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null); // X 그룹 밖 최상위
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(0, null, null));

    // A(마커 index1)를 X row로 드래그 → 인터리빙 경계 = X 앞(0). 옛 코드는 target<first_group=1이라 first_group(1)로 clamp,
    // m==first_group이라 no-op(안 움직임)이었다. 이제 X가 top_level 인터리브 단위라 그 앞(0)을 낸다.
    const boundary = session.sidebarGroupDropBoundary(cardRowOf(session, 0), 1).?;
    try std.testing.expectEqual(@as(usize, 0), boundary);
    const plan: AppSession.DropPlan = .{ .group_sibling = .{ .insert_before = session.clampGroupMoveToRegion(1, boundary) } };

    // 실제 앱 경로로 1회 확정(groupDragPreviewFrame이 굽는 plan을 commitSidebarDragPreview가 재사용 — normalize/float/sweep 포함).
    session.sidebar_drag_preview = .{ .origin = 1, .origin_len = 2, .plan = plan, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();

    // 결과 [A=[a0,a1], X] — 순서 교환. X는 그룹 A 뒤 최상위(top_level 유지·흡수 안 됨).
    try std.testing.expect(session.tabs.items[0].group_start != null); // index0 = A 마커(a0)
    const x_idx = blk: {
        for (session.tabs.items, 0..) |t, i| if (t == x) break :blk i;
        break :blk session.tabs.items.len;
    };
    try std.testing.expectEqual(@as(usize, 2), x_idx); // X가 그룹 뒤(index2)로
    try std.testing.expect(x.top_level); // ★ top_level 유지(그룹 이동은 top_level 불변, §14.6)
    try std.testing.expect(session.enclosingGroupMarkerIndex(x_idx) == null); // 흡수 안 됨(그룹 밖 최상위)
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(x_idx, null, null)); // depth 0
    var markers: usize = 0;
    for (session.tabs.items) |t| if (t.group_start != null) {
        markers += 1;
    };
    try std.testing.expectEqual(@as(usize, 1), markers); // 마커 1개(쪼개짐/유령 마커 없음)
}

test "SR4 그룹드래그(b): [그룹A, 탭X, 그룹B]에서 그룹이 X를 넘나들며 순서 변경(X 사이 유지·top_level 불변)·프리뷰=확정 등가" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // init 기본 탭 1개 + 2개 = [t0, t1, t2] 3개
    // [A=[a0(t0,마커)], X(t1, top_level 탭), B=[b0(t2,마커)]] — 단일 카드 형제 그룹 사이에 top카드.
    try setGroupMarker(session, 0, "A", 1);
    const x = session.tabs.items[1];
    x.top_level = true;
    try setGroupMarker(session, 2, "B", 1);
    session.recomputeVisibleTabs();
    try std.testing.expect(session.enclosingGroupMarkerIndex(1) == null); // X = A·B 사이 최상위

    // ── ① B(마커 index2)를 X 위로 드래그 → B가 X 앞으로 = [A, B, X]. 경계=run_lo(X=1)<m(2) → 1. 프리뷰=확정 등가.
    const b1 = session.sidebarGroupDropBoundary(cardRowOf(session, 1), 2).?;
    try std.testing.expectEqual(@as(usize, 1), b1);
    try expectDropEquivalent(session, 2, .{ .group_sibling = .{ .insert_before = b1 } });
    try std.testing.expectEqual(x, session.tabs.items[2]); // X가 뒤로 밀림
    try std.testing.expect(x.top_level); // top_level 유지
    try std.testing.expect(session.enclosingGroupMarkerIndex(2) == null); // 흡수 안 됨

    // ── ② B(이제 index1)를 X(이제 index2) 아래로 드래그 → B가 X 뒤로 = [A, X, B](복귀, X가 다시 A·B 사이). 경계=run_hi=len=3.
    session.recomputeVisibleTabs();
    const b2 = session.sidebarGroupDropBoundary(cardRowOf(session, 2), 1).?;
    try std.testing.expectEqual(@as(usize, 3), b2);
    try expectDropEquivalent(session, 1, .{ .group_sibling = .{ .insert_before = b2 } });
    try std.testing.expectEqual(x, session.tabs.items[1]); // X가 다시 A·B 사이(index1)
    try std.testing.expect(x.top_level); // top_level 불변
    try std.testing.expect(session.enclosingGroupMarkerIndex(1) == null);
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(1, null, null)); // depth 0
    var markers: usize = 0;
    for (session.tabs.items) |t| if (t.group_start != null) {
        markers += 1;
    };
    try std.testing.expectEqual(@as(usize, 2), markers); // 형제 그룹 2개 유지
}

test "SR4 그룹드래그(d): 고정 리전 인터리빙 clamp — 고정 그룹은 고정 top카드와 순서 교환하되 비고정 리전으로 못 넘어간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4] 5개 사용
    // 고정 리전 [Xp(t0,pin,top_level), A=[a0(t1,pin,마커), a1(t2,pin,멤버)]] + 비고정 [t3, t4].
    inline for (0..3) |i| {
        session.tabs.items[i].pinned = true;
    }
    const xp = session.tabs.items[0];
    xp.top_level = true;
    try setGroupMarker(session, 1, "A", 1);
    session.recomputeVisibleTabs();

    // ① 고정 그룹 A(마커1)를 고정 top카드 Xp 앞으로 → 경계 0, clamp 유지(고정 리전 [0, pinned_count] 안). 프리뷰=확정 등가.
    const b1 = session.sidebarGroupDropBoundary(cardRowOf(session, 0), 1).?;
    try std.testing.expectEqual(@as(usize, 0), b1);
    try std.testing.expectEqual(@as(usize, 0), session.clampGroupMoveToRegion(1, b1)); // 고정 리전 안이라 clamp no-op
    try expectDropEquivalent(session, 1, .{ .group_sibling = .{ .insert_before = session.clampGroupMoveToRegion(1, b1) } });
    // 결과 [A=[a0,a1], Xp, t3, t4] — Xp 고정·top_level 유지, 그룹 A 고정 프리픽스 유지.
    const xp_idx = blk: {
        for (session.tabs.items, 0..) |t, i| if (t == xp) break :blk i;
        break :blk session.tabs.items.len;
    };
    try std.testing.expectEqual(@as(usize, 2), xp_idx);
    try std.testing.expect(xp.pinned); // ★ 고정 유지(비고정 리전으로 안 샘)
    try std.testing.expect(xp.top_level);
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned); // A 고정 프리픽스

    // ② 고정 그룹을 **비고정 타겟**(t3)으로 끌어도 clamp가 고정 경계(pinned_count)로 가둔다(비고정 리전 침범 방지, GP3 정합).
    session.recomputeVisibleTabs();
    const raw = session.sidebarGroupDropBoundary(cardRowOf(session, 3), 0) orelse 0; // A 마커는 이제 index0
    const clamped = session.clampGroupMoveToRegion(0, raw);
    try std.testing.expect(clamped <= session.countPinnedTabs()); // ★ 고정 리전 경계 넘지 않음(프리뷰=확정 공통 clamp)
    _ = session.moveGroupRange(0, clamped, false);
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned and session.tabs.items[2].pinned); // 고정 3개 유지
    try std.testing.expect(!session.tabs.items[3].pinned and !session.tabs.items[4].pinned); // 비고정 2개 유지
}

test "SG5-1: 헤더 클릭(접기 토글) vs 헤더 드래그(그룹 통째 이동)를 threshold로 구분 (mouse 시뮬레이션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 두 **형제** 그룹: A=t0에서 시작(t0,t1), B=t2에서 시작(t2,t3). 연속 파티션 [A][B], 최상위 없음.
    // SG5-3: create_group은 그룹 안 카드에서 depth+1 중첩이라, t2에 부르면 B가 A 자식이 된다. 형제 헤더 드래그/접기
    // 토글을 보는 테스트라 B의 depth를 1로 명시해 형제 최상위 그룹으로 둔다(§9 create_group 중첩 tension 문서화).
    session.createGroupAbsorbForTab(t0); // A(마커 index0)
    session.createGroupAbsorbForTab(t2); // B(마커 index2) — 중첩 기본
    t2.group_depth = 1; // B를 최상위 형제로 오버라이드

    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const rowCenterY = struct {
        fn f(s: *AppSession, row: usize, hh: u32) f64 {
            const top = sb.rowTop(s.sidebar_rows.items, row, hh, s.sidebarMetrics(), 0);
            const rh = sb.rowHeight(s.sidebar_rows.items[row], s.sidebarMetrics());
            return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
        }
    }.f;

    // ── ① 헤더 드래그(threshold 초과) = 그룹 통째 이동. 헤더 A(row0)를 잡아 그룹 B 카드(row4) 위로 끈다.
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]
    const headerA_y = rowCenterY(session, 0, header_h);
    session.mouse(1, x, headerA_y, 0, 0); // down on 헤더 A → 접기 토글 후보로 arm(즉시 토글 아님)
    try std.testing.expect(session.pointerGestureIs(.sidebar_group));
    try std.testing.expect(session.pointer_gesture_owner.sidebar_group.phase != .dragging); // 아직 threshold 전
    try std.testing.expectEqual(@as(usize, 0), session.pointer_gesture_owner.sidebar_group.marker); // 마커 A(t0, index0)
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // 아직 토글 안 됨(down만으론)
    const groupB_card_y = rowCenterY(session, 4, header_h);
    session.mouse(2, x, groupB_card_y, 0, 0); // drag 멀리 → threshold 초과 → 그룹 통째 드래그(SG8e 비커밋 프리뷰)
    try std.testing.expect(session.pointer_gesture_owner.sidebar_group.phase == .dragging); // 승격됨
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰(subtree 고스트)
    // self.tabs는 드래그 중 불변 — 확정은 up. 원래 순서 [t0(A),t1,t2(B),t3] 유지.
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // 드래그는 접기 토글 아님
    session.mouse(3, x, groupB_card_y, 0, 0); // up → 마지막 plan(group_sibling) 1회 커밋
    // 결과 [t2(B), t3, t0(A), t1] — A 그룹 통째가 B 뒤로. 연속 파티션 유지(라이브 시절과 동일 = 등가).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t3, session.tabs.items[1]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    try std.testing.expectEqual(t1, session.tabs.items[3]);
    try std.testing.expect(session.tabs.items[0].group_start != null); // B 마커
    try std.testing.expect(session.tabs.items[2].group_start != null); // A 마커
    try std.testing.expect(!session.pointerGestureIs(.sidebar_group));
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨

    // ── ② 헤더 클릭(threshold 미달 = move 없음) = 접기 토글. 헤더 B(현 row0)를 down→up(움직임 없음).
    session.recomputeVisibleTabs(); // [hB(0), c t2(1), c t3(2), hA(3), c t0(4), c t1(5)]
    const headerB_y = rowCenterY(session, 0, header_h);
    const order_before = [_]*Tab{ session.tabs.items[0], session.tabs.items[1], session.tabs.items[2], session.tabs.items[3] };
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // B(index0) 펼침
    session.mouse(1, x, headerB_y, 0, 0); // down → arm
    try std.testing.expect(session.pointerGestureIs(.sidebar_group));
    session.mouse(3, x, headerB_y, 0, 0); // up(움직임 없음) → 접기 토글
    try std.testing.expect(session.tabs.items[0].group_collapsed); // B 접힘(클릭=토글)
    try std.testing.expect(!session.pointerGestureIs(.sidebar_group));
    for (order_before, 0..) |p, i| try std.testing.expectEqual(p, session.tabs.items[i]); // 순서 불변(이동 없음)

    // ── ③ 헤더 살짝만 움직이고 up(threshold 미달) = 여전히 접기 토글(그룹 이동 아님). B는 접힘 상태 → 펼치기 토글.
    session.recomputeVisibleTabs(); // [hB(0,collapsed), hA(1), c t0(2), c t1(3)]
    const headerB2_y = rowCenterY(session, 0, header_h);
    const order_before2 = [_]*Tab{ session.tabs.items[0], session.tabs.items[1], session.tabs.items[2], session.tabs.items[3] };
    session.mouse(1, x, headerB2_y, 0, 0); // down → arm
    session.mouse(2, x, headerB2_y + 1, 0, 0); // 아주 살짝(dy=1 < threshold) → active 승격 안 됨
    try std.testing.expect(session.pointer_gesture_owner.sidebar_group.phase != .dragging); // threshold 미달
    for (order_before2, 0..) |p, i| try std.testing.expectEqual(p, session.tabs.items[i]); // 순서 불변
    session.mouse(3, x, headerB2_y + 1, 0, 0); // up → 접기 토글(threshold 미달이라 클릭 취급)
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // B 다시 펼침(토글)
    try std.testing.expect(!session.pointerGestureIs(.sidebar_group));
}

/// SG5-4 테스트 헬퍼 — 탭 idx에 그룹 시작 마커(owned dup) + depth를 세팅한다. 위치 파생 구조를 정밀하게 짜기 위해
/// create_group의 위치 의존 depth 계산 대신 직접 마커를 얹는다(session.deinit이 group_start를 free).
fn setGroupMarker(session: *AppSession, idx: usize, name: []const u8, depth: u8) !void {
    session.tabs.items[idx].group_start = try session.allocator.dupe(u8, name);
    session.tabs.items[idx].group_depth = depth;
}

test "SG5-4: 그룹을 다른 그룹 헤더에 드롭 → 중첩(depth+1) + subtree 상대 depth 유지 (moveGroupNesting)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // A=[t0,t1] 직접 + C 중첩=[t2,t3](depth2, A 안), B=[t4,t5](depth1, A 형제). 위치 파생 정밀 구성(마커 직접).
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "C", 2); // A 안 중첩
    try setGroupMarker(session, 4, "B", 1); // A 형제(최상위)
    // 초기 depth 확인.
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // A 마커 카드
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t2)); // C(A 자식)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B(최상위)

    // ── 드래그: A(마커 index0)를 B 헤더에 드롭 → B의 자식으로 중첩. projectRows로 B 헤더 row를 찾아 groupNestPlan에 넘긴다.
    session.recomputeVisibleTabs();
    var b_header_row: usize = 0;
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .agent_toggle, .agent => {},
        .group_header => |gh| if (gh.tab == 4) {
            b_header_row = s;
        },
        .card => {},
    };
    const plan = session.groupNestPlan(b_header_row, 0).?; // B 헤더 → 중첩 계획
    try std.testing.expectEqual(@as(u8, 2), plan.target_depth); // B eff1 + 1
    const r = session.moveGroupNesting(0, plan.insert_before, plan.target_depth);
    try std.testing.expect(r.changed);

    // 결과: A가 B의 자식(depth2), C는 A의 자식(depth3) — **상대 depth 유지**(C는 A보다 1 깊음 유지).
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t0)); // A → B 자식(depth2)
    try std.testing.expectEqual(@as(?u8, 3), sidebarCardDepth(session, t2)); // C → A 자식(depth3, 상대 유지)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B 최상위 유지
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t5)); // B 직접 카드

    // 트리 연속(gap 없음)·연속 파티션: projectRows가 유효 트리를 낸다(부모 직접 카드가 자식 헤더 앞). 헤더 depth로 확인.
    session.recomputeVisibleTabs();
    var depths: [3]u8 = undefined;
    var hc: usize = 0;
    var prev_marker_ok = true;
    for (session.sidebar_rows.items) |row| switch (row) {
        .agent_toggle, .agent => {},
        .group_header => |gh| {
            if (hc < depths.len) depths[hc] = gh.depth;
            hc += 1;
            if (gh.depth > 2 and hc == 1) prev_marker_ok = false; // 첫 헤더가 갑자기 깊으면 gap
        },
        .card => {},
    };
    try std.testing.expectEqual(@as(usize, 3), hc); // B·A·C 세 헤더
    try std.testing.expectEqual(@as(u8, 1), depths[0]); // B 최상위
    try std.testing.expectEqual(@as(u8, 2), depths[1]); // A(B 자식)
    try std.testing.expectEqual(@as(u8, 3), depths[2]); // C(A 자식) — 1,2,3 연속(gap 없음)
}

test "SG5-4: 중첩 그룹을 최상위 카드에 드롭 → 빼기(depth 1) (moveGroupSibling + gap-clamp)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4] 5개
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];

    // t0 최상위, A=[t1,t2](depth1), B 중첩=[t3,t4](depth2, A 안).
    try setGroupMarker(session, 1, "A", 1);
    try setGroupMarker(session, 3, "B", 2); // A 안 중첩
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t3)); // B 중첩(depth2)

    // ── 드래그: B(마커 index3)를 최상위 카드 t0(row0)에 드롭 → 빼기(최상위 depth1로). 카드 드롭이라 형제 경로.
    session.recomputeVisibleTabs(); // [c t0(0), hA(1), c t1(2), c t2(3), hB(4), c t3(5), c t4(6)]
    try std.testing.expect(session.groupNestPlan(0, 3) == null); // row0=카드 → 중첩 아님(형제 경로)
    const boundary = session.sidebarGroupDropBoundary(0, 3).?; // 최상위 카드 → 첫 그룹 앞
    const r = session.moveGroupSibling(3, boundary);
    try std.testing.expect(r.changed);

    // B가 최상위(depth1)로 빠짐. 저장 group_depth도 gap-clamp eff(1)로 맞춰진다(gap 제거).
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // 빼기 성공(depth1)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B 직접 카드
    // B 마커 탭의 저장 depth가 1로 정규화됐는지(releveel).
    var b_stored: ?u8 = null;
    for (session.tabs.items) |t| if (t.group_start != null and std.mem.eql(u8, t.group_start.?, "B")) {
        b_stored = t.group_depth;
    };
    try std.testing.expectEqual(@as(?u8, 1), b_stored); // releveel로 저장 depth도 1
}

test "SG5-4: 카드 드래그 — 중첩 자식 그룹 안(자식 depth)·최상위(depth0)로 depth 파생 (sidebarGroupDropTargetTab)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t0 = session.tabs.items[0];

    // t0 최상위, A=[t1,t2](depth1), B 중첩=[t3,t4](depth2). t0를 B 안으로 / 최상위로 옮겨 depth 파생 확인.
    try setGroupMarker(session, 1, "A", 1);
    try setGroupMarker(session, 3, "B", 2);
    session.recomputeVisibleTabs(); // [c t0(0), hA(1), c t1(2), c t2(3), hB(4), c t3(5), c t4(6)]

    // ── ① t0를 B의 카드(t4, row6)에 드롭 → B 소속(depth2, 중첩 자식). 카드 row → 그 위치로 위치 파생.
    {
        const target = session.sidebarGroupDropTargetTab(6, 0).?; // B 카드 t4(index4)
        _ = session.moveTab(0, target);
    }
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t0)); // 자식 B 안 = depth2

    // ── ② 다시 t0(현재 B 안)를 최상위로 — 재정렬로 첫 그룹 앞으로 빼기. moveTab(현 index → 0)로 최상위 앞.
    var t0_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == t0) {
        t0_idx = i;
    };
    _ = session.moveTab(t0_idx, 0); // 맨 앞(첫 마커 이전 = 최상위)
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위 = depth0
}

test "SG5-4/N2: 그룹 헤더를 다른 그룹 헤더에 Cmd(⌘) 드롭 → 중첩 (mouse 시뮬레이션 — 통합)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];

    // 두 형제 그룹 A=[t0,t1](depth1), B=[t2,t3](depth1).
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "B", 1);
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]

    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const rowCenterY = struct {
        fn f(s: *AppSession, row: usize, hh: u32) f64 {
            const top = sb.rowTop(s.sidebar_rows.items, row, hh, s.sidebarMetrics(), 0);
            const rh = sb.rowHeight(s.sidebar_rows.items[row], s.sidebarMetrics());
            return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
        }
    }.f;

    // 헤더 A(row0)를 잡아 헤더 B(row3) 위로 **Cmd(⌘, mods=32) 드래그** → A가 B의 자식으로 중첩(Cmd=중첩 정책).
    const CMD: i32 = 32;
    const headerA_y = rowCenterY(session, 0, header_h);
    session.mouse(1, x, headerA_y, 0, CMD); // down on 헤더 A → arm
    try std.testing.expect(session.pointerGestureIs(.sidebar_group));
    const headerB_y = rowCenterY(session, 3, header_h);
    session.mouse(2, x, headerB_y, 0, CMD); // Cmd 드래그 → threshold 초과 → 헤더 드롭=중첩 plan의 **비커밋 프리뷰**(SG8e)
    try std.testing.expect(session.pointer_gesture_owner.sidebar_group.phase == .dragging);
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰(subtree 고스트, B 자식 depth로 들여쓰기)
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_nest); // Cmd → 중첩 plan

    // 드래그 중 self.tabs 불변 — sidebar_rows(hit-test 도메인)는 아직 중첩 전(원본 depth). 확정은 up.
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // B 최상위(불변)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // A 아직 최상위(프리뷰만 중첩)
    session.mouse(3, x, headerB_y, 0, CMD); // up → 마지막 plan(group_nest) 1회 커밋
    // 결과: A가 B의 자식(depth2). B는 최상위(depth1). t0(A 카드)=depth2(라이브 시절과 동일 = 등가).
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // B 최상위
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t0)); // A → B 자식(중첩)
    try std.testing.expect(!session.pointerGestureIs(.sidebar_group));
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨
}

// ── 그룹 드래그 "Cmd=중첩 / 없으면 형제" modifier 매트릭스(N/P/R/B) 공용 헬퍼 ─────────────────────────────────────────
// 표시 row의 세로 중앙 y(backing px, scroll=0). 그룹 드래그 mouse 시뮬레이션 테스트가 공유한다(N2와 같은 산식).
fn sbRowCenterY(s: *AppSession, row: usize) f64 {
    const sb = chrome.components.sidebar;
    const top = sb.rowTop(s.sidebar_rows.items, row, s.sidebar_header_height_px, s.sidebarMetrics(), 0);
    const rh = sb.rowHeight(s.sidebar_rows.items[row], s.sidebarMetrics());
    return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
}

// 두 형제 최상위 그룹 A=[t0,t1]·B=[t2,t3]을 만든 4-탭 세션. 호출자가 defer deinit/destroy. cols 넉넉히 잡아 사이드바+본문 확보.
fn makeTwoSiblingGroups(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "B", 1);
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]
    return session;
}

test "N1: 그룹 헤더를 다른 헤더에 Cmd 없이 드롭 → 형제(group_sibling, 중첩 안 됨·depth 불변)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 헤더 A(row0)를 헤더 B(row3)에 **Cmd 없이(mods=0)** 드래그 → 형제(중첩 아님).
    session.mouse(1, x, sbRowCenterY(session, 0), 0, 0); // down → arm
    try std.testing.expect(session.pointerGestureIs(.sidebar_group));
    session.mouse(2, x, sbRowCenterY(session, 3), 0, 0); // drag onto 헤더 B
    try std.testing.expect(session.sidebar_drag_preview != null);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling); // Cmd 없음 → 형제(중첩 절대 안 함)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 드래그 중 depth 불변
    session.mouse(3, x, sbRowCenterY(session, 3), 0, 0); // up → 형제 이동 커밋
    // 결과 [t2(B), t3, t0(A), t1] — A가 B 뒤 형제로. depth 둘 다 1(중첩 없음).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 최상위 유지
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "N3: 그룹 헤더를 카드에 Cmd 없이 드롭 → 형제" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const t0 = session.tabs.items[0];
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 헤더 A(row0)를 그룹 B의 카드 t3(row5)에 Cmd 없이 드래그 → 형제.
    session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
    session.mouse(2, x, sbRowCenterY(session, 5), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling); // 카드 타깃 = 항상 형제
    session.mouse(3, x, sbRowCenterY(session, 5), 0, 0);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 중첩 안 됨
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "N4: 그룹 헤더를 카드에 Cmd 드롭 → 형제 폴백(넣을 헤더 없음, no-op 아님·정책 고정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const t0 = session.tabs.items[0];
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const CMD: i32 = 32;

    // 헤더 A(row0)를 카드 t3(row5)에 **Cmd 눌러** 드래그 → 카드는 nest 대상 아님(groupNestPlan=null) → 형제 폴백.
    session.mouse(1, x, sbRowCenterY(session, 0), 0, CMD);
    session.mouse(2, x, sbRowCenterY(session, 5), 0, CMD);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling); // N4 정책 = 형제 폴백(중첩 아님)
    session.mouse(3, x, sbRowCenterY(session, 5), 0, CMD);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // depth 불변(중첩 아님)
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "N5: 접힌 그룹을 Cmd 없이 지나 드롭 → 형제(현재 불가하던 케이스 개선)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    session.tabs.items[2].group_collapsed = true; // B 접힘
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3, collapsed)] — B 카드 숨김
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 헤더 A(row0)를 접힌 헤더 B(row3)에 Cmd 없이 드래그 → 형제(과거엔 헤더 드롭=중첩이라 이 재정렬이 애매했다).
    session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
    session.mouse(2, x, sbRowCenterY(session, 3), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling);
    session.mouse(3, x, sbRowCenterY(session, 3), 0, 0);
    // A가 접힌 B 뒤 형제로 — [t2(B), t3, t0(A), t1], depth 불변.
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0));
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "N6: 프리뷰=확정 — 드래그 중 캡처한 plan이 up 커밋 결과와 일치(nest·sibling)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const CMD: i32 = 32;

    // (a) nest: Cmd 헤더 드롭 → 드래그 중 plan=.group_nest, up 후 착지 depth=target_depth.
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const t0 = session.tabs.items[0];
        const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
        session.mouse(1, x, sbRowCenterY(session, 0), 0, CMD);
        session.mouse(2, x, sbRowCenterY(session, 3), 0, CMD);
        const captured = session.sidebar_drag_preview.?.plan;
        try std.testing.expect(captured == .group_nest);
        const target_depth = captured.group_nest.target_depth; // 프리뷰가 계획한 착지 depth
        session.mouse(3, x, sbRowCenterY(session, 3), 0, CMD);
        try std.testing.expectEqual(@as(?u8, target_depth), sidebarCardDepth(session, t0)); // 착지 = 프리뷰 plan
    }
    // (b) sibling: Cmd 없는 헤더 드롭 → plan=.group_sibling, up 후 형제 위치 착지.
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const t0 = session.tabs.items[0];
        const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
        session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
        session.mouse(2, x, sbRowCenterY(session, 3), 0, 0);
        try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling);
        session.mouse(3, x, sbRowCenterY(session, 3), 0, 0);
        try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 형제(depth 불변)
    }
}

test "P1: 고정 탭끼리 재정렬 — 둘 다 최상위 유지(enclosing null·depth 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true; // 고정 탭 2개(그룹 아님)
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];

    _ = session.moveTab(1, 0); // t1을 t0 앞으로(고정 리전 [0,2) 안 재정렬)
    try std.testing.expectEqual(@as(usize, 2), session.countPinnedTabs());
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    // 둘 다 그룹 밖 최상위(enclosing null·depth 0).
    try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null);
    try std.testing.expect(session.enclosingGroupMarkerIndex(1) == null);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0));
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1));
}

test "P2: 고정 그룹끼리 재정렬 — 둘 다 고정 유지(연속 파티션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    // A·B 둘 다 고정(마커+멤버 pinned = 정규화 캐시).
    for (0..4) |i| session.tabs.items[i].pinned = true;
    const t0 = session.tabs.items[0]; // A 마커
    const t2 = session.tabs.items[2]; // B 마커

    // B(index2)를 A 앞으로 형제 이동 → [t2,t3,t0,t1]. 리전 clamp(고정)로 파티션 유지.
    const boundary = session.sidebarGroupDropBoundary(0, 2).?; // B를 A 헤더(row... 여기선 raw_row=0)에 = A 앞
    const clamped = session.clampGroupMoveToRegion(2, boundary);
    _ = session.moveGroupSibling(2, clamped);
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    // 둘 다 여전히 고정(재정렬이 고정 리전 안에서만).
    try std.testing.expect(session.tabs.items[0].pinned); // B 마커
    try std.testing.expect(session.tabs.items[2].pinned); // A 마커
    try std.testing.expectEqual(@as(usize, 4), session.countPinnedTabs());
}

test "P3: 그룹이 고정 탭 위로 못 감 — clampGroupMoveToRegion이 비고정 리전에 가둠" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    session.tabs.items[0].pinned = true; // 고정 최상위 탭
    try setGroupMarker(session, 1, "A", 1); // 비고정 그룹 A=[t1,t2]

    // 비고정 그룹 A(마커 index1)를 고정 리전(index0)으로 넣으려 해도 pinned_count=1로 clamp.
    try std.testing.expectEqual(@as(usize, 1), session.countPinnedTabs());
    try std.testing.expectEqual(@as(usize, 1), session.clampGroupMoveToRegion(1, 0)); // insert 0 → max(0, pinned_count=1)=1
}

test "P4(음성): 고정 탭을 그룹 뒤로 드래그해도 그룹에 흡수 안 됨(인터리빙 미지원 — 고정 리전에 clamp)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    session.tabs.items[0].pinned = true; // 고정 최상위 탭
    try setGroupMarker(session, 1, "A", 1); // 비고정 그룹 A=[t1,t2]
    const t0 = session.tabs.items[0];

    // 고정 탭 t0(index0)를 그룹 A 뒤(index2 이후)로 이동 시도 → clampMoveToGroup이 고정 리전 [0,1)에 가둔다(흡수 아님).
    _ = session.moveTab(0, 2);
    // t0는 여전히 index0(고정 최상위), 그룹 A 멤버가 되지 않음(enclosing null).
    var t0_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == t0) {
        t0_idx = i;
    };
    try std.testing.expectEqual(@as(usize, 0), t0_idx); // 고정 리전 앞에 그대로
    try std.testing.expect(session.enclosingGroupMarkerIndex(t0_idx) == null); // 그룹에 인터리빙 안 됨
    try std.testing.expect(session.tabs.items[t0_idx].pinned);
}

test "R1: 터미널 tracking + Cmd 마우스 → report_mouse.mods에 32 없음(마스킹 회귀 가드)" {
    var session: AppSession = undefined;
    session.addr_edit = null; // 슬라이스 3: mouse()가 조기 addr 밴드 캡처에서 읽음(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.tabs = .empty;
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.scrollbar_capture = null;
    session.scrollbar_coalescer = .{};
    session.scrollbar_snapshot_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io();
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 8, .rows = 4 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };

    var capture_buf: std.ArrayList(u8) = .empty;
    defer capture_buf.deinit(std.testing.allocator);
    var cap_ctx = ReportCaptureCtx{ .buf = &capture_buf };
    // M3b: runtime은 앱-전역 공유 포인터라, 이 undefined-session 테스트는 로컬 SurfaceRuntime을 소유해 격리한다.
    var test_rt: app.SurfaceRuntime = undefined;
    test_rt = app.SurfaceRuntime.init(std.testing.allocator);
    session.runtime = &test_rt;
    defer session.runtime.deinit();
    _ = try session.runtime.attach(&tab_surface, tab_surface.id, .{ .ctx = &cap_ctx, .write_input = ReportCaptureCtx.write, .resize_fn = testNoopPtyResize });

    // 리포트 경로가 읽는 상태를 전부 명시(undefined 트랩 회피 — 모든 드래그 캡처 플래그 false).
    session.metal_dirty = false;
    session.chrome_host = .{};
    session.rename = null;
    session.drag_autoscroll = 0;
    session.mouse_drag_selecting = false;
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.scale_milli = 1000;
    session.sidebar_width_px = 0; // inSidebar=false → 본문 리포트 경로
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 64, .h = 64 };
    session.last_drag_col = 0;

    // any-event(1003) tracking + SGR — motion을 리포트한다.
    tab_surface.core.mouse_tracking = .any;
    tab_surface.core.mouse_format = .sgr;

    // Cmd(mods=32) 드래그(motion) → cb = button(0) + mods(0=마스킹) + motion(32) = 32. 32비트가 안 빠졌으면 cb=64로 오염.
    session.mouse(2, 16.0, 16.0, 0, 32);
    try std.testing.expect(std.mem.indexOf(u8, capture_buf.items, "\x1b[<32;") != null); // 정상: cb=32(motion만)
    try std.testing.expect(std.mem.indexOf(u8, capture_buf.items, "\x1b[<64;") == null); // 오염 없음: command 32가 안 섞임
    try std.testing.expect(std.mem.indexOf(u8, capture_buf.items, "\x1b[<96;") == null); // 방어: 32+32+32=96도 없음
}

// B1 헬퍼 — 각 위치의 (그룹 마커 이름 첫 글자<<8 | group_depth) 시그니처. 구조적으로 동일한 두 세션의 착지 비교용.
fn groupSig4(session: *AppSession, out: *[4]u16) void {
    for (session.tabs.items, 0..) |t, i| {
        if (i >= 4) break;
        const nm: u16 = if (t.group_start) |g| (if (g.len > 0) @as(u16, g[0]) else 0) else 0;
        out[i] = (nm << 8) | t.group_depth;
    }
}

test "B1: 고정 그룹 0 + Cmd 미사용 그룹 드래그 = moveGroupSibling과 동일 착지(SG5/SG8 회귀 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // 경로 A: mouse 시뮬레이션(Cmd 없음)으로 헤더 A를 헤더 B에 드롭.
    var sig_mouse: [4]u16 = undefined;
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
        session.mouse(1, x, sbRowCenterY(session, 0), 0, 0);
        session.mouse(2, x, sbRowCenterY(session, 3), 0, 0);
        session.mouse(3, x, sbRowCenterY(session, 3), 0, 0);
        groupSig4(session, &sig_mouse);
    }
    // 경로 B: 직접 moveGroupSibling(A 마커=0, insert_before=B subtree 끝) — 옛 SG5-1 확정 경로.
    var sig_direct: [4]u16 = undefined;
    {
        const session = try makeTwoSiblingGroups(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const boundary = session.sidebarGroupDropBoundary(3, 0).?; // 헤더 B(row3) 드롭 경계
        const clamped = session.clampGroupMoveToRegion(0, boundary);
        _ = session.moveGroupSibling(0, clamped);
        groupSig4(session, &sig_direct);
    }
    try std.testing.expectEqualSlices(u16, &sig_mouse, &sig_direct); // 두 경로 동일(그룹 구조 byte-identical 착지)
}

test "fillSidebarGlyphPyTop: 그룹 헤더가 앞서면 카드 glyph py_top이 rowTop(가변 높이)로 밀린다 (SG3b-2-ii #1·#5·#6)" {
    const sb = chrome.components.sidebar;
    const header_row_h: u32 = 24;
    const ch: u32 = 20;
    // glyph 셀 하나 만들기(슬롯=**표시 row 인덱스**; 헤더도 slot을 차지, line_index/line_count는 sidebarGlyphRow로 인코딩). slot_id≠0=glyph.
    const glyphCell = struct {
        fn make(row_idx: usize, li: u16, lc: u16) metal_frame.NativeMetalCell {
            return .{ .row = coretext_frame_builder.sidebarGlyphRow(row_idx, li, lc), .col = 0, .width = 1, .codepoint = 'x', .slot_id = 7, .atlas_x_px = 0, .atlas_y_px = 0, .atlas_width_px = 0, .atlas_height_px = 0, .u0 = 0, .v0 = 0, .u1 = 0, .v1 = 0 };
        }
    }.make;
    // 밴드 셀(slot_id==0, row=표시 row 인덱스) — 손대지 않아야 한다.
    const bandCell: metal_frame.NativeMetalCell = .{ .row = 1, .col = 0, .width = 1, .codepoint = 0, .slot_id = 0, .atlas_x_px = 0, .atlas_y_px = 0, .atlas_width_px = 0, .atlas_height_px = 0, .u0 = -1, .v0 = -1, .u1 = -1, .v1 = -1 };

    // (A) 가변 높이 + 헤더 glyph: [헤더(24), 카드(100), 카드(100)]. slot=표시 row 인덱스라 헤더도 slot0을 차지한다.
    const rows = [_]sb.Row{
        .{ .group_header = .{ .collapsed = false, .label = "g", .member_count = 2, .tab = 0 } },
        .{ .card = .{ .tab = 0, .label = "", .active = false, .depth = 1 } },
        .{ .card = .{ .tab = 1, .label = "", .active = false, .depth = 1 } },
    };
    // 헤더 glyph(slot0, 1줄), 카드0 glyph(slot1), 카드1 glyph(slot2), 밴드 셀.
    var cells = [_]metal_frame.NativeMetalCell{ glyphCell(0, 0, 1), glyphCell(1, 0, 1), glyphCell(2, 0, 1), bandCell };
    // 카드 높이는 줄 수 기반(cardHeight)이라 기대값도 그 계산에서 파생한다 — 줄 기하 조정 시 자동 정합.
    const m_t = chrome.components.sidebar.Metrics.init(ch, header_row_h);
    const pad_t = m_t.content_pad_v; // 목록 위 여백 — 밴드·글자·클릭이 공유하는 시작 오프셋
    AppSession.fillSidebarGlyphPyTop(std.testing.allocator, &cells, &rows, m_t);
    try std.testing.expectEqual(@as(u32, pad_t + (24 - 20) / 2), cells[0].origin_y); // 여백 + 헤더 slot0: content top0 + 얇은 줄(24) 세로 중앙(24-20)/2=2
    const card_h_t = chrome.components.sidebar.cardHeight(1, m_t); // 이 rows의 카드는 1줄
    const block_off_t = (card_h_t - AppSession.sidebarBlockHeight(1, ch)) / 2;
    try std.testing.expectEqual(@as(u32, pad_t + 24 + block_off_t), cells[1].origin_y); // 카드0 slot1: content top=헤더(24) + 블록중앙
    try std.testing.expectEqual(@as(u32, pad_t + 24 + card_h_t + block_off_t), cells[2].origin_y); // 카드1 slot2: + 카드0 높이
    try std.testing.expectEqual(@as(u32, 0), cells[3].origin_y); // 밴드 셀은 그대로

    // (B) 동작 보존: 헤더 없이 카드만이면 content top = row*slot_h(균일 — 옛 slot_idx*slot_h와 동일).
    const rows_flat = [_]sb.Row{
        .{ .card = .{ .tab = 0, .label = "", .active = false } },
        .{ .card = .{ .tab = 1, .label = "", .active = false } },
    };
    var cells2 = [_]metal_frame.NativeMetalCell{ glyphCell(0, 0, 1), glyphCell(1, 0, 1) };
    AppSession.fillSidebarGlyphPyTop(std.testing.allocator, &cells2, &rows_flat, .init(ch, header_row_h));
    try std.testing.expectEqual(@as(u32, pad_t + 0 * card_h_t + block_off_t), cells2[0].origin_y);
    try std.testing.expectEqual(@as(u32, pad_t + 1 * card_h_t + block_off_t), cells2[1].origin_y);

    // (C) 다줄 카드: 카드0(slot1, 헤더 뒤) line_count=3. 줄 스텝=ch+여유(sidebarLineStep)라 블록 높이=sidebarBlockHeight(3,ch),
    // 블록중앙 오프셋=(slot_h-블록)/2, 2줄째는 +2*step. content top=헤더(24). 값은 헬퍼로 파생해 스텝 조정 시 자동 정합.
    var cells3 = [_]metal_frame.NativeMetalCell{glyphCell(1, 2, 3)};
    AppSession.fillSidebarGlyphPyTop(std.testing.allocator, &cells3, &rows, .init(ch, header_row_h));
    // 이 카드 row의 실제 높이(1줄)로 블록중앙을 잡는다 — 3줄 glyph를 1줄 카드에 넣는 인코딩 검증이라
    // 블록이 카드보다 크면 오프셋 0으로 포화된다(-|). 옛 고정 슬롯(100) 하드코딩을 대체.
    const block_off_c: u32 = (card_h_t -| AppSession.sidebarBlockHeight(3, ch)) / 2;
    try std.testing.expectEqual(@as(u32, pad_t + 24 + block_off_c + 2 * AppSession.sidebarLineStep(ch)), cells3[0].origin_y); // 헤더24 + block_off + 2줄*step(여유)
}

// 카드 줄 수는 **행 높이(hit-test·밴드·glyph)와 렌더가 공유하는 단일 출처**다(sidebarCardLines). 두 곳이 갈리면
// 카드가 그리는 줄 수와 그 카드가 차지하는 높이가 어긋나 "보이는 곳과 눌리는 곳이 다른" 회귀가 난다. 이 테스트는
// 상태 변화가 줄 수 → 카드 높이 → 다음 row의 시작 y까지 실제로 전파되는지 못박는다.
// 목록의 **조작**을 못박는다: 토글 클릭은 접기만, 에이전트 행 클릭은 그 자리로 이동한다(§5 3단계).
// 터미널에서 왜 중요한가: 3단계(Term 탭 활성화)가 빠지면 Pane까지만 가고 사용자가 지목한 에이전트는 여전히
// 가려진 탭에 있다 — 목록이 "보여주기"만 하고 "데려다주기"를 못 하면 이 기능의 절반이 없는 것이다.
// code-review(max) 회귀: 에이전트 행 ✕가 `closeTermAt`을 직접 불러 (1) 실행 중 에이전트를 확인 없이 죽이고
// (2) 마지막 워크스페이스의 마지막 Term에서 해제된 surface에 쓰는 UAF + 빈 pane 인덱싱 패닉으로 이어졌다.
// 터미널에서 왜 중요한가: 사이드바 ✕ 한 번이 되돌릴 수 없는 종료인데, 다른 모든 닫기 경로가 거치는 확인 규율만
// 이 자리에서 빠져 있었다. 이제 requestClose가 캐스케이드 범위(Term→pane→탭→세션)를 풀고 그 범위로 확인한다.
// 4단계(§7): 세션 기록에서 읽은 마지막 대화가 **행 라벨·줄 수·알림 본문** 셋에 실제로 도달하는지 고정한다.
// 캐시(Term.agent_transcript)까지는 폴링이 채우고, 여기서 검증하는 건 그 아래 소비 경로다 — 파일→캐시 구간은
// 실제 FS·provider 포맷에 의존해 단위 테스트가 못 덮으므로 앱 실행으로 확인한다(§10).
// 활동 시각의 **우선순위**를 고정한다: 관측된 출력 > 세션 기록 mtime > 빈칸. mtime 폴백이 없으면 앱을 새로 켠
// 직후(= 사이드바를 보는 바로 그 순간) 모든 행이 빈칸이 된다.
test "에이전트 행 활동 시각: 출력이 mtime보다 우선하고, 둘 다 없으면 빈칸이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const term = session.tabs.items[0].panes.items[0].terms.items[0];
    term.agent_kind = .claude;
    // 두 경로 모두 wall clock 기준이라 호스트 uptime에 의존하지 않는다 — 예전 테스트는 출력 시각을
    // `awakeMs() -| 5분`으로 만들어, uptime이 5분 미만인 호스트(CI 러너)에서 0으로 포화돼 mtime 경로로
    // 조용히 미끄러졌고 우선순위를 전혀 검증하지 못했다(code-review max).
    const now: i96 = @intCast(std.Io.Clock.real.now(session.io).nanoseconds);

    // 관측된 출력도, 기록 mtime도 없다 → 빈칸(그 앱 세션에서 아직 아무 일도 없었다).
    {
        const age = try session.agentAgeOwned(term);
        defer a.free(age);
        try std.testing.expectEqualStrings("", age);
    }

    // mtime만 있다 → 폴백이 값을 낸다. 앱을 새로 켠 직후가 정확히 이 상태다.
    term.agent_transcript.read_mtime_ns = now - 2 * std.time.ns_per_hour;
    {
        const age = try session.agentAgeOwned(term);
        defer a.free(age);
        try std.testing.expectEqualStrings("2h", age);
    }

    // 출력이 관측되면 그쪽이 이긴다 — 값이 확실히 달라야 우선순위가 검증된다(2h ↔ 5m).
    term.agent_last_output_wall_ns = now - 5 * std.time.ns_per_min;
    {
        const age = try session.agentAgeOwned(term);
        defer a.free(age);
        try std.testing.expectEqualStrings("5m", age);
    }

    // 방금 출력한 에이전트는 경과가 0에 가깝다 — 빈칸이 아니라 `now`여야 한다(이 칼럼이 가장 보여줘야 할 행이다).
    term.agent_last_output_wall_ns = now;
    {
        const age = try session.agentAgeOwned(term);
        defer a.free(age);
        try std.testing.expectEqualStrings("now", age);
    }

    // Term이 없는 행(그룹 헤더·편집 중 카드)은 빈칸이다.
    {
        const age = try session.agentAgeOwned(null);
        defer a.free(age);
        try std.testing.expectEqualStrings("", age);
    }
}

test "에이전트 행: 마지막 대화가 라벨·줄 수·알림 본문에 실린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const term = tab.panes.items[0].terms.items[0];
    term.agent_kind = .claude;
    term.agent_state = .idle;

    // 대화가 없을 때(계약 1: 기록을 못 읽은 상태) — 기존 표시가 그대로다.
    {
        const label = try session.agentRowLabelOwned(term);
        defer a.free(label);
        try std.testing.expect(std.mem.indexOf(u8, label, "Claude Code") != null);
    }
    const lines_before = session.sidebarAgentRowLines(tab, .{ .pane = 0, .term = 0 });

    term.agent_transcript.owned.setPrompt("배포 스크립트 고쳐줘");
    term.agent_transcript.owned.setReply("네, 수정했습니다");

    // 라벨: 종류 이름 대신 **프롬프트**가 오고, 상태 마커(✓)는 남는다 — 진행 여부를 잃지 않는다.
    {
        const label = try session.agentRowLabelOwned(term);
        defer a.free(label);
        try std.testing.expect(std.mem.indexOf(u8, label, "배포 스크립트 고쳐줘") != null);
        try std.testing.expect(std.mem.indexOf(u8, label, "Claude Code") == null);
        try std.testing.expect(std.mem.indexOf(u8, label, "\u{2713}") != null);
    }

    // 줄 수: 응답 줄이 하나 늘어야 한다. 늘지 않으면 응답이 행 높이 밖에 그려져 아래 행을 침범한다.
    const lines_after = session.sidebarAgentRowLines(tab, .{ .pane = 0, .term = 0 });
    try std.testing.expectEqual(lines_before + 1, lines_after);
    try std.testing.expect(lines_after <= 4); // sidebarGlyphRow의 line_index는 2비트다

    // 알림 본문: provider 문구 뒤에 대화가 붙는다. 프롬프트가 먼저다 — OS 배너는 뒷줄을 자른다.
    {
        const body = try session.notificationBodyOwned(term, "Claude is waiting for your input");
        defer a.free(body);
        const pi = std.mem.indexOf(u8, body, "배포 스크립트 고쳐줘") orelse return error.PromptMissing;
        const ri = std.mem.indexOf(u8, body, "네, 수정했습니다") orelse return error.ReplyMissing;
        try std.testing.expect(std.mem.indexOf(u8, body, "Claude is waiting") != null);
        try std.testing.expect(pi < ri);
    }

    // 대화가 없으면 알림은 provider 문구 그대로 — 기존 동작과 byte-identical이어야 한다.
    term.agent_transcript.reset();
    {
        const body = try session.notificationBodyOwned(term, "Claude is waiting for your input");
        defer a.free(body);
        try std.testing.expectEqualStrings("Claude is waiting for your input", body);
    }
}

test "에이전트 행 ✕: 실행 중이면 확인 모달을 거치고, 마지막 Term에서도 크래시하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    const t0 = tab.panes.items[0].terms.items[0];
    t0.agent_kind = .claude;
    t0.agent_state = .running;
    session.rebuildSidebar() catch {};

    // 단일 워크스페이스·단일 pane·단일 Term = 캐스케이드가 세션 종료까지 가는 최악 경로. 예전엔 여기서
    // closeTab→latchSessionClose가 해제된 surface에 쓰고 이어지는 rebuild가 빈 pane을 인덱싱했다.
    session.closeAgentRow(0, 0, 0);

    // 확인 모달이 열렸고(실행 중 명령) 아직 아무것도 파괴되지 않았다 — 즉시 종료가 아니다.
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), tab.panes.items[0].terms.items.len);

    // 투영은 teardown 중간 상태에서도 안전해야 한다(빈 pane 방어) — 강제로 비운 뒤 재투영해도 패닉하지 않는다.
    const doomed = tab.panes.items[0].terms.orderedRemove(0);
    session.destroyTerm(doomed);
    session.rebuildSidebar() catch {};
}

test "사이드바 에이전트 목록: 행 클릭이 워크스페이스·Pane·Term까지 데려간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tab = session.tabs.items[0];
    // pane 2개, 각 pane에 Term 2개 → 그 중 **가려진 탭**(pane0의 term1)에 에이전트를 둔다.
    try session.splitActivePane(.horizontal);
    _ = session.focusPaneByPtr(tab.panes.items[0]);
    try session.newTermInActivePane();
    const target_pane: usize = 0;
    const target_term: usize = 1;
    const t = tab.panes.items[target_pane].terms.items[target_term];
    t.agent_kind = .claude;
    t.agent_state = .idle;
    // 다른 pane을 활성으로 만들어 "가려진 자리"를 재현한다.
    _ = session.focusPaneByPtr(tab.panes.items[1]);
    tab.panes.items[target_pane].active_term = 0; // 그 pane의 활성 탭도 0(에이전트는 1에 있다)
    session.rebuildSidebar() catch {};

    // 목록에 그 에이전트 행이 있고, 인덱스 경로가 실제 자리를 가리킨다.
    const rows = session.sidebar_rows.items;
    var agent_row: ?usize = null;
    for (rows, 0..) |r, i| if (r == .agent) {
        agent_row = i;
    };
    const ar = agent_row orelse return error.NoAgentRow;
    try std.testing.expectEqual(target_pane, rows[ar].agent.pane);
    try std.testing.expectEqual(target_term, rows[ar].agent.term);

    // 클릭 → 세 단계가 모두 수행된다.
    session.focusAgentRow(rows[ar].agent.tab, rows[ar].agent.pane, rows[ar].agent.term);
    try std.testing.expectEqual(tab.panes.items[target_pane], session.activePane()); // 2) Pane
    try std.testing.expectEqual(target_term, tab.panes.items[target_pane].active_term); // 3) Term 탭

    // 사라진 Term을 가리키는 행은 무동작(stale 인덱스 방어).
    session.focusAgentRow(0, target_pane, 999);
    try std.testing.expectEqual(target_term, tab.panes.items[target_pane].active_term);
}

test "사이드바 에이전트 목록: Term 전수 나열·개수와 무관하게 접기 토글" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const sb = chrome.components.sidebar;
    const tab = session.tabs.items[0];

    // (0) 에이전트가 없으면 카드만 — 목록 행이 붙지 않는다.
    session.rebuildSidebar() catch {};
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);

    // (1) 에이전트가 **1개여도 토글**이 붙는다 — 접기는 개수가 아니라 "이 카드를 얼마나 펼쳐 둘 것인가"의
    // 문제라서다(사용자 요청으로 초기 정책을 바꿨다). 카드 + 토글 + 행 1.
    const t0 = tab.panes.items[0].terms.items[0];
    t0.agent_kind = .claude;
    t0.agent_state = .idle;
    session.rebuildSidebar() catch {};
    try std.testing.expectEqual(@as(usize, 3), session.sidebar_rows.items.len);
    try std.testing.expect(sb.onAgentToggle(session.sidebar_rows.items, 1));
    try std.testing.expectEqual(@as(u16, 1), session.sidebar_rows.items[1].agent_toggle.count);
    try std.testing.expect(session.sidebar_rows.items[2] == .agent);

    // 1개짜리도 실제로 접힌다 — 토글만 남는다.
    tab.agents_collapsed = true;
    session.rebuildSidebar() catch {};
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[1] == .agent_toggle);
    tab.agents_collapsed = false;

    // (2) 같은 pane에 Term을 하나 더 띄워 에이전트 2개 → `N agents` 토글 + 행 2개.
    try session.newTermInActivePane();
    const t1 = tab.panes.items[0].terms.items[1];
    t1.agent_kind = .claude;
    t1.agent_state = .idle;
    session.rebuildSidebar() catch {};
    try std.testing.expectEqual(@as(usize, 4), session.sidebar_rows.items.len); // 카드 + 토글 + 행 2
    try std.testing.expect(sb.onAgentToggle(session.sidebar_rows.items, 1));
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[1].agent_toggle.count);

    // 행은 **Term 단위 전수**다 — 같은 pane의 두 Term이 각각 행을 갖는다(가려진 탭도 포함, §2).
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[2].agent.term);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items[3].agent.term);

    // (3) 접으면 행이 사라지고 토글만 남는다(§4).
    tab.agents_collapsed = true;
    session.rebuildSidebar() catch {};
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len); // 카드 + 토글
    try std.testing.expect(session.sidebar_rows.items[1] == .agent_toggle);
}

test "workspaceStatusLine: running=파형, blocked=입력 대기, idle=대기중, unknown=상태 확인" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const tab = session.activeTab();
    const term = tab.activePane().activeTerm();

    // running: 파형 바로 시작 + "진행중"으로 끝. 대표 종류=claude.
    term.agent_kind = .claude;
    term.agent_state = .running;
    {
        const s = try session.workspaceStatusLine(tab);
        defer allocator.free(s);
        try std.testing.expect(std.mem.endsWith(u8, s, "진행중"));
        const first_len = std.unicode.utf8ByteSequenceLength(s[0]) catch 1;
        const first_cp = std.unicode.utf8Decode(s[0..first_len]) catch 0;
        try std.testing.expect(isAgentSpinnerCp(first_cp)); // 선두가 이퀄라이저 바
    }
    try std.testing.expectEqual(AgentKind.claude, AppSession.tabAgentKind(tab));

    // blocked는 running보다 높은 대표 상태다.
    term.agent_state = .blocked;
    {
        const s = try session.workspaceStatusLine(tab);
        defer allocator.free(s);
        try std.testing.expectEqualStrings("? 입력 대기", s);
    }

    // idle은 완료로 단정하지 않고 입력 가능한 대기 상태로 표시한다.
    term.agent_state = .idle;
    {
        const s = try session.workspaceStatusLine(tab);
        defer allocator.free(s);
        try std.testing.expectEqualStrings("\u{2713} 대기중", s);
    }

    term.agent_state = .unknown;
    {
        const s = try session.workspaceStatusLine(tab);
        defer allocator.free(s);
        try std.testing.expectEqualStrings("\u{00b7} 상태 확인 중", s);
    }

    // none: 상태줄 빈 문자열(그 줄 생략). tabAgentKind 폴백도 none.
    term.agent_kind = .none;
    term.agent_state = .idle;
    {
        const s = try session.workspaceStatusLine(tab);
        defer allocator.free(s);
        try std.testing.expectEqual(@as(usize, 0), s.len);
    }
    try std.testing.expectEqual(AgentKind.none, AppSession.tabAgentKind(tab));
}

// 상단 탭 바 running 표시는 파형(5칸)이 아니라 **정적 1칸 플래그 ●**(U+25CF) — tmux 창-플래그 관례로 이름 폭을 거의 안
// 먹는다(code-review max #1). flagPrefixedLabel이 running이면 "● {이름}", 아니면 이름만 돌려준다.
test "flagPrefixedLabel: running=●+이름, 아니면 이름만" {
    const allocator = std.testing.allocator;
    const run = try AppSession.flagPrefixedLabel(allocator, "svc", true);
    defer allocator.free(run);
    var flag: [4]u8 = undefined;
    const n = std.unicode.utf8Encode(agent_running_flag, &flag) catch 0;
    try std.testing.expect(std.mem.startsWith(u8, run, flag[0..n])); // 선두가 ●
    try std.testing.expect(std.mem.endsWith(u8, run, "svc"));
    const off = try AppSession.flagPrefixedLabel(allocator, "svc", false);
    defer allocator.free(off);
    try std.testing.expectEqualStrings("svc", off); // 아니면 이름만(플래그 없음)
}

// agentDisplayVisible(pollAgentKinds/State의 metal_dirty 게이트)은 **화면에 running 표시가 보이는 탭**만 true —
// 접힘/최소크롬 + 비활성 탭이면 진짜 안 보여 false(백그라운드 Term churn으로 헛 재렌더 방지). 여기선 단일 탭이라
// (탭0=활성) 탭바(paneBarHeightPx>0)만으로도 true이고, 접힘+비활성으로 만들면 false가 되는 걸 고정한다.
test "도크 뷰 스위처: 호버는 슬롯 위에서만 포인터가 바뀐다" {
    // 슬롯 위=클릭 가능(pointingHand), 바 안 여백=화살표. 렌더 강조와 커서가 같은 판정을 쓰는지 함께 본다.
    const bar = chrome.components.dock_view_bar.Rect{ .x = 100, .y = 40, .w = 200, .h = 24 };
    const cw: u32 = 10;
    try std.testing.expectEqual(@as(usize, 0), chrome.components.dock_view_bar.slotAtPoint(bar, cw, 110, 50).?);
    try std.testing.expectEqual(@as(usize, 2), chrome.components.dock_view_bar.slotAtPoint(bar, cw, 190, 50).?);
    // 슬롯 3개 × 4셀 × 10px = 120px → 그 뒤는 여백이라 null(커서도 default가 된다).
    try std.testing.expect(chrome.components.dock_view_bar.slotAtPoint(bar, cw, 230, 50) == null);
}

test "도크 뷰 스위처: 슬롯 index 대응과 포커스 되돌림" {
    // chrome 컴포넌트는 도메인 enum을 모르므로(레이어 경계) 뷰↔슬롯 대응은 session이 소유한다. 두 곳에
    // 흩어지면 그린 자리와 눌리는 자리가 어긋나므로 왕복을 여기서 못박는다.
    try std.testing.expectEqual(dock_panel.View.explorer, AppSession.dockViewForSlot(0).?);
    try std.testing.expectEqual(dock_panel.View.source_control, AppSession.dockViewForSlot(1).?);
    try std.testing.expect(AppSession.dockViewForSlot(chrome.components.dock_view_bar.slot_count) == null);
}

test "agentDisplayVisible: 카드·탭바 안 보이면 false (재렌더 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.recomputeVisibleTabs();
    session.cell_height_px = 20; // paneBarHeightPx()>0 되게(탭 바 분기 검증용) — 0이면 바 없음 취급

    session.sidebar_collapsed = false;
    try std.testing.expect(session.agentDisplayVisible(0)); // 펼침 → 카드 보임 → true

    // 카드도 없고(접힘) 탭바도 없게(chrome_minimal → paneBarHeightPx=0) 만들면 false.
    session.sidebar_collapsed = true;
    session.chrome_minimal = true;
    try std.testing.expect(!session.agentDisplayVisible(0)); // 카드·탭바 둘 다 없음 → false

    // 접힘이어도 활성 탭(0)의 탭 바가 있으면 true(탭바 플래그 갱신 필요).
    session.chrome_minimal = false;
    try std.testing.expect(session.agentDisplayVisible(0)); // 접힘이지만 활성 탭 탭바 → true

    // 활성 탭이 아니고(idx 99) 접힘이면 카드·탭바 둘 다 없음 → false.
    try std.testing.expect(!session.agentDisplayVisible(99));
}

// anyAgentRunning은 **사이드바 카드의 애니메이션 파형**이 실제로 보일 때만 true여야 한다(매 130ms full-grid 재투영 낭비
// 회피, code-review high #1). 탭 바 running 표시는 **정적 플래그(●)**라 이 위상 게이트와 무관하다(상태 변화 시에만 dirty).
// 따라서: 펼침 + 보이는 running 탭 → true; 접힘·chrome_minimal → false(사이드바 없음); 검색 필터아웃 → false(카드 없음).
// running 판정은 **어느 pane/Term이든**(tabHasRunningAgent)이라 활성 Term을 running으로 두면 그 탭이 running으로 잡힌다.
test "anyAgentRunning: 펼침+보이는 running=true, 접힘·필터아웃=false (사이드바 파형 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    session.activeTab().activePane().activeTerm().agent_state = .running; // 이 워크스페이스가 running(어느 Term이든)
    session.recomputeVisibleTabs(); // 검색 없음 → visible_tabs = 전체(1개)
    try std.testing.expect(session.sidebar_rows.items.len >= 1);

    session.sidebar_collapsed = false;
    try std.testing.expect(session.anyAgentRunning()); // 펼침 + 보이는 running → true

    session.sidebar_collapsed = true;
    try std.testing.expect(!session.anyAgentRunning()); // 접힘 → 카드 파형 안 보임 → false(탭바 플래그는 정적이라 무관)

    session.sidebar_collapsed = false;
    session.sidebar_rows.clearRetainingCapacity(); // 검색 필터로 카드 숨김
    try std.testing.expect(!session.anyAgentRunning()); // 필터아웃 → 카드 없음 → false
}

test "advanceAgentSpinner: 출력 독립 + wall-clock 경과 기반 위상 진행(굶김·cadence 회귀)" {
    // primary(§10.5): 스피너 advance가 updateCursorBlink(출력 없는 tick에만 호출)에 있어 연속 출력이 굶겨 멈췄다 →
    // advanceAgentSpinner를 출력 게이트 밖에서 호출(출력 인자 없음 = 출력 독립). secondary(§10.5): 위상 진행을 tick
    // 카운트가 아니라 **wall-clock 경과**로 → tick rate가 떨어져도 실시간을 따라가고 stall 후 여러 프레임 catch-up.
    // 이 테스트는 baseline(agent_spin_last_ns)을 과거로 밀어 경과분만큼 위상이 진행되는지 결정적으로 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const term = session.tabs.items[0].activePane().activeTerm();
    const interval_ns: i128 = @as(i128, agent_spin_interval_ms) * std.time.ns_per_ms;
    const wave_len: u8 = @intCast(spinner_wave.len);

    // 에이전트 없음 → 여러 번 돌려도 위상 불변 + chrome_dirty 안 세움 + baseline 0 유지(idle 재투영 없음).
    session.chrome_dirty = false;
    const f0 = session.agent_spin_frame;
    for (0..5) |_| session.advanceAgentSpinner();
    try std.testing.expectEqual(f0, session.agent_spin_frame);
    try std.testing.expect(!session.chrome_dirty);
    try std.testing.expectEqual(@as(i128, 0), session.agent_spin_last_ns);

    // running 에이전트 + 사이드바에 그 탭 보임. 첫 호출은 baseline만 세팅(위상 불변) — 이후 wall-clock 경과로 진행.
    term.agent_state = .running;
    term.agent_kind = .claude;
    try session.sidebar_rows.append(allocator, .{ .card = .{ .tab = 0, .active = true, .label = "", .depth = 0 } }); // 사이드바에 탭0 카드 보임(collapsed/minimal 기본 false)
    session.chrome_dirty = false;
    session.advanceAgentSpinner(); // baseline 설정
    try std.testing.expectEqual(f0, session.agent_spin_frame); // 아직 경과 0 → 불변
    try std.testing.expect(!session.chrome_dirty);
    try std.testing.expect(session.agent_spin_last_ns != 0);

    // baseline을 2 interval 과거로 밀어 2프레임 경과를 모사 → 한 번 호출에 위상 +2(tick 카운트 아님) + chrome_dirty.
    session.agent_spin_last_ns = std.Io.Clock.awake.now(session.io).nanoseconds - 2 * interval_ns;
    session.chrome_dirty = false;
    session.advanceAgentSpinner();
    try std.testing.expectEqual(@as(u8, (f0 + 2) % wave_len), session.agent_spin_frame); // catch-up 2프레임
    try std.testing.expect(session.chrome_dirty);

    // 방금 진행해 baseline이 ~현재라, 곧바로 다시 불러도 한 주기 안 지나 위상 불변(경과 기반 정확).
    session.chrome_dirty = false;
    session.advanceAgentSpinner();
    try std.testing.expectEqual(@as(u8, (f0 + 2) % wave_len), session.agent_spin_frame);
    try std.testing.expect(!session.chrome_dirty);
}

test "activateSurfaceById: surface.id로 (탭·split panel·가로탭)을 역조회해 그 자리로 활성화한다" {
    // OSC 9/777 데스크톱 알림 클릭이 발신 터미널로 점프하는 경로의 핵심이다. Swift는 창 토큰으로
    // '어느 창(세션)'까지만 고르고, 그 세션 안에서 surface_id로 '어느 탭/split panel/가로탭'인지 찾아 포커스하는 건
    // Zig가 소유한다. 순서(switchTab→focusPaneByPtr→focusTerm)가 틀리면 비활성 탭의 panel/term을 못 찾으므로,
    // 비활성 탭의 둘째 panel 둘째 가로탭을 표적으로 삼아 세 단계 모두 정확히 들어가는지 검증한다. 터미널에서
    // 중요한 이유: 알림은 "지금 안 보는 터미널"이 보내므로, 클릭이 정확히 그 화면을 되살리지 못하면 기능이 무의미하다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane/newTab/newTermInActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800; // split/resize가 의미 있으려면 backing 필요
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    // 표적: 비활성 탭(t1)의 둘째 panel(우측 split)의 둘째 가로탭. 만든 직후 활성이라 activeSurface로 id를 잡는다.
    _ = try session.newTab(); // tabs [t0, t1], 활성 t1
    try session.splitActivePane(.horizontal); // t1: pane [p0, p1], 활성 p1
    try session.newTermInActivePane(); // p1: term [tm0, tm1], 활성 tm1
    const target_id = session.activeSurface().id;
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);

    // 활성을 다른 워크스페이스(t0)로 옮겨, 활성화가 탭 경계를 넘는지(단순 no-op이 아닌지) 본다.
    try std.testing.expect(session.switchTab(0));
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);

    // 알림 클릭 모사: id로 끝까지(탭→panel→가로탭) 정확히 점프.
    try std.testing.expect(session.activateSurfaceById(target_id));
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
    try std.testing.expectEqual(target_id, session.activeSurface().id);

    // 없는 id(알림 후 그 Term이 닫힌 경우 모사)는 false + 활성 상태 불변 — stale 알림이 엉뚱한 surface를 깨우지 않는다.
    try std.testing.expect(!session.activateSurfaceById(0xFFFF_FFFF));
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
}

test "pendingNotification: 비활성 pane/Term의 OSC 9 알림도 그 surface_id로 drain한다" {
    // 예전엔 activeSurface().core만 drain해 background split pane·가로탭이 보낸 OSC 9/777 알림이 영영 안 나왔다 —
    // 클릭이 발신 Term으로 점프하려면(activateSurfaceById) 발신 Term의 surface_id가 알림에 실려야 하는데, 활성
    // surface의 id만 실려 "탭은 맞는데 pane/Term이 어긋나는" 증상이 났다. 이제 모든 Term의 코어를 훑어 발신 Term의
    // surface_id를 싣는다. 비활성 pane Term에 OSC 9를 먹이고(활성 surface엔 알림 없음), 그 비활성 Term의 알림을
    // surface_id까지 정확히 돌려주는지 + 그 id로 점프가 비활성 pane을 포커스하는지 본다(알림→점프 전제 폐곡선).
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane/newTermInActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800; // split이 의미 있으려면 backing 필요
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    session.loaded_config.config.notifications.osc = true; // OSC 게이트 명시(기본값 의존 안 함)
    session.window_focused = true; // 포커스 창 — 활성 Term이 "지금 보는" Term이 되게(전면 배너 억제 대상)

    // 활성 탭에 split을 만들어 비활성 pane을 둔다: panes [p0, p1], 활성 p1. 발신원 = 비활성 p0의 Term.
    try session.splitActivePane(.horizontal);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane); // p1 활성
    const bg_term = session.activeTab().panes.items[0].terms.items[0]; // 비활성 p0의 Term(*Term)
    const bg_id = bg_term.surface.id;
    const active_id = session.activeSurface().id; // 활성 p1의 Term(지금 보는 Term)
    try std.testing.expect(bg_id != active_id); // 활성과 다른 surface여야 의미 있음
    // 라벨을 rename으로 명시해 제목 위치 접두를 결정적으로 검증한다(탭 custom_name 없음 → workspaceLabel은 활성 p1
    // Term 라벨로 폴백). deinit이 surface.custom_name을 free.
    bg_term.surface.custom_name = try allocator.dupe(u8, "빌드");
    session.activeSurface().custom_name = try allocator.dupe(u8, "활성작업");

    // 두 Term 모두 OSC 9(iTerm2: ESC ] 9 ; <body> BEL)를 먹인다 — title 없음, body=메시지.
    try bg_term.surface.core.write("\x1b]9;배경 pane 빌드 완료\x07");
    try session.activeSurface().core.write("\x1b]9;활성 pane 알림\x07");

    // 루프는 p0(배경)→p1(활성) 순. 첫 drain = 배경 Term: surface_id=bg_id, 안 보는 곳이라 **전면 배너 뜸**(=1).
    const n1 = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings("배경 pane 빌드 완료", n1.body);
    try std.testing.expectEqual(bg_id, n1.surface_id);
    try std.testing.expect(n1.foreground_banner); // 배경 pane OSC → 전면에서도 배너(사용자가 안 보는 곳)
    // OSC 9은 title 없음 → 제목=위치만. 탭 라벨(=활성 p1 폴백 "활성작업") ≠ 팬 라벨("빌드")이라 `탭 › 팬`.
    try std.testing.expectEqualStrings("활성작업 › 빌드", n1.title);

    // 둘째 drain = 활성(지금 보는) Term: 자기 화면 노이즈라 전면 배너 억제(=0, 목록만).
    const n2 = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqual(active_id, n2.surface_id);
    try std.testing.expect(!n2.foreground_banner); // 지금 보는 Term OSC → 전면 배너 억제
    // 활성 Term은 탭 라벨(활성 Term 폴백)==팬 라벨이라 dedup — 위치가 "활성작업" 하나만(중복 억제).
    try std.testing.expectEqualStrings("활성작업", n2.title);

    // OSC 777(title 있음)은 위치를 **접두**하고 앱 title을 보존한다 — `위치 · 앱 title`, body도 앱 그대로.
    try bg_term.surface.core.write("\x1b]777;notify;Build finished;42개 컴파일\x07");
    const n3 = session.pendingNotification() orelse return error.TestExpectedNotification;
    try std.testing.expectEqualStrings("활성작업 › 빌드 · Build finished", n3.title);
    try std.testing.expectEqualStrings("42개 컴파일", n3.body);

    // 모두 소비됐으니 다음 호출은 null(clearNotification으로 코어 pending 비움 — 다음 tick 재발화 방지).
    try std.testing.expect(session.pendingNotification() == null);

    // 배경 Term의 surface_id로 점프하면 비활성 p0로 정확히 활성화된다(알림→점프 전제가 닫힌다).
    try std.testing.expect(session.activateSurfaceById(bg_id));
    try std.testing.expectEqual(@as(usize, 0), session.activeTab().active_pane);
}

test "알림 히스토리: push 상한 ring + unread 증감 + markRead + formatRelativeTime 경계" {
    // 인앱 알림 센터의 토대 — 드레인되면 사라지는 OS 배너와 달리 히스토리는 보관·열람된다. 상한(ring) 초과 시 가장
    // 오래된 걸 버리고, unread 캐시는 push/markRead/cap-drop 3곳에서만 정확히 증감해야 종 배지 수가 맞는다.
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // push 2건 → len 2, unread 2, owned dupe.
    _ = session.pushNotificationHistory("ws1", "done", 1);
    _ = session.pushNotificationHistory("ws2", "fail", 2);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.notification_unread);
    try std.testing.expectEqual(@as(u64, 2), session.notification_history.items[1].surface_id);

    // markRead(0) → unread 1, 다시 호출은 무동작(이미 읽음).
    session.markNotificationRead(0);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
    session.markNotificationRead(0);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
    session.markNotificationRead(999); // 범위 밖 — 무동작
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);

    // 상한 초과: cap+5건 더 push → len은 cap(config notifications.history-limit) 유지(ring), 누수 없이 오래된 것 free.
    const cap: usize = @intCast(session.loaded_config.config.notifications.history_limit);
    var i: usize = 0;
    while (i < cap + 5) : (i += 1) _ = session.pushNotificationHistory("x", "y", 100);
    try std.testing.expectEqual(cap, session.notification_history.items.len);

    // formatRelativeTime 경계(arena).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const a = arena_state.allocator();
    try std.testing.expectEqualStrings("방금", try session.formatRelativeTime(a, 30 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("5분 전", try session.formatRelativeTime(a, 5 * 60 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("2시간 전", try session.formatRelativeTime(a, 2 * 3600 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("3일 전", try session.formatRelativeTime(a, 3 * 86400 * std.time.ns_per_s));
    try std.testing.expectEqualStrings("방금", try session.formatRelativeTime(a, -100)); // 시계 역행 → 0
}

test "acceptNotification: 목록 역순 매핑(0=최신) + 클릭 surface 전체 읽음(배너와 통일) + 패널 닫기" {
    // 목록은 최신이 위(역순)라 selected 0 = 히스토리 끝. accept는 그 카드의 surface를 봤다는 의미라 같은 surface의
    // 안읽음을 모두 읽음 처리하고(데스크톱 배너 클릭과 동일 정책 — markNotificationsReadBySurface) 패널을 닫는다.
    // 다른 surface 알림은 안읽음 점을 유지한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = session.pushNotificationHistory("old-A", "1", 11); // history 0: surface 11
    _ = session.pushNotificationHistory("other", "2", 22); // history 1: surface 22(다른 터미널)
    _ = session.pushNotificationHistory("new-A", "3", 11); // history 2(최신): surface 11(또 한 번)
    session.chrome_host.notifications.show(0, 0, 3);
    session.chrome_host.notifications.selected = 0; // 목록 0 = 최신("new-A") = surface 11
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    session.acceptNotification();
    try std.testing.expect(!session.chrome_host.notifications.open); // 패널 닫힘
    // 클릭 카드의 surface(11) 안읽음(old-A·new-A) 모두 읽음, 다른 surface(22, "other")는 유지.
    try std.testing.expect(session.notification_history.items[0].is_read); // old-A (surface 11)
    try std.testing.expect(!session.notification_history.items[1].is_read); // other (surface 22)
    try std.testing.expect(session.notification_history.items[2].is_read); // new-A (surface 11)
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread); // other만 안읽음
}

test "알림 액션: deleteNotification(역순) + markAllNotificationsRead + clearNotifications + unread 보정" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = session.pushNotificationHistory("a", "1", 11); // 히스토리 idx 0(가장 오래됨)
    _ = session.pushNotificationHistory("b", "2", 22); // idx 1
    _ = session.pushNotificationHistory("c", "3", 33); // idx 2(최신) — 목록 역순 [c, b, a]
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    // 목록 list_index 0 = 최신("c") = 히스토리 끝. 삭제 → "c" 제거, unread 1 감소.
    session.deleteNotification(0);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.notification_unread);
    try std.testing.expectEqualStrings("b", session.notification_history.items[1].title); // 최신이 이제 "b"

    // 모두 읽음 → unread 0, 항목 유지(목록엔 남음).
    session.markAllNotificationsRead();
    try std.testing.expectEqual(@as(usize, 0), session.notification_unread);
    try std.testing.expectEqual(@as(usize, 2), session.notification_history.items.len);

    // 모두 지우기 → 히스토리 비움(누수 없이 owned free).
    session.clearNotifications();
    try std.testing.expectEqual(@as(usize, 0), session.notification_history.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.notification_unread);
}

test "markNotificationsReadBySurface: 배너 클릭→그 surface 안읽음 모두 읽음(센터 동기화)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    _ = session.pushNotificationHistory("a", "1", 11); // surface 11
    _ = session.pushNotificationHistory("b", "2", 22); // surface 22
    _ = session.pushNotificationHistory("c", "3", 11); // surface 11 (또 한 번)
    try std.testing.expectEqual(@as(usize, 3), session.notification_unread);

    // surface 11 배너 클릭 → surface 11의 안읽음(a·c) 모두 읽음, surface 22(b)는 유지.
    session.markNotificationsReadBySurface(11);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread); // b만 안읽음
    try std.testing.expect(session.notification_history.items[0].is_read); // a (surface 11)
    try std.testing.expect(!session.notification_history.items[1].is_read); // b (surface 22)
    try std.testing.expect(session.notification_history.items[2].is_read); // c (surface 11)

    // 없는 surface → 무동작.
    session.markNotificationsReadBySurface(999);
    try std.testing.expectEqual(@as(usize, 1), session.notification_unread);
}

test "parseGitHead: ref branch / nested ref / detached SHA / empty ref / junk" {
    try std.testing.expectEqualStrings("main", parseGitHead("ref: refs/heads/main\n").?);
    try std.testing.expectEqualStrings("feature/x", parseGitHead("ref: refs/heads/feature/x").?); // 슬래시 포함 브랜치
    try std.testing.expectEqualStrings("0123456", parseGitHead("0123456789abcdef0123456789abcdef01234567\n").?); // detached → short
    try std.testing.expect(parseGitHead("ref: refs/heads/\n") == null); // 빈 브랜치
    try std.testing.expect(parseGitHead("garbage here") == null); // hex 아님·ref 아님
    try std.testing.expect(parseGitHead("ref: refs/tags/v1") == null); // heads 아님(태그) → 미지원
    try std.testing.expect(parseGitHead("") == null);
    try std.testing.expect(parseGitHead("abc") == null); // 7자 미만 hex
}

test "window padding insets only the cell grid, not chrome (termRect/paneBarRect to edge, paneTermRect inset)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 결정적 padding(scale 1000 기본이라 appearance 8/4가 그대로 8/4px이지만 명시 고정).
    session.window_padding_px = .{ .left = 8, .right = 8, .top = 4, .bottom = 4 };
    session.cell_height_px = 18; // 탭 바 높이 결정적(bar_h = cell_height + 2·tab_bar_pad_y)
    session.titlebar_strip_px = 0; // 상단 타이틀바 띠는 별도 테스트 — 여기선 window padding/grid 수학만 격리
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;

    // termRect: 사이드바만 뺀다 — window padding 없음(chrome이 사이드바 경계/창 가장자리까지).
    const r = session.termRect();
    try std.testing.expectEqual(session.sidebar_width_px, r.x);
    try std.testing.expectEqual(@as(u32, 0), r.y);
    try std.testing.expectEqual(@as(u32, 800), r.w);
    try std.testing.expectEqual(@as(u32, 600), r.h);

    // 탭 바: leaf rect 상단·사이드바 경계에 붙는다(padding inset 없음 — chrome은 가장자리까지).
    const bar = session.paneBarRect(r).?;
    try std.testing.expectEqual(session.sidebar_width_px, bar.x);
    try std.testing.expectEqual(@as(u32, 0), bar.y);
    try std.testing.expectEqual(@as(u32, 800), bar.w);

    // 셀 그리드: 탭 바 아래 + window padding inset(여기만 여백).
    const bar_h = session.paneBarHeightPx();
    const g = session.paneTermRect(r);
    try std.testing.expectEqual(session.sidebar_width_px + 8, g.x); // 좌 = 사이드바 + pad_x
    try std.testing.expectEqual(bar_h + 4, g.y); // 상 = 탭 바 + pad_y
    try std.testing.expectEqual(@as(u32, 800 - 16), g.w); // 폭 = backing − 사이드바 − 2·pad_x
    try std.testing.expectEqual(@as(u32, 600) -| bar_h -| 8, g.h); // 높이 = backing − 바 − 2·pad_y

    // padding 0이면 grid도 inset 없음(탭 바만 뺀 영역).
    session.window_padding_px = .{};
    const g0 = session.paneTermRect(r);
    try std.testing.expectEqual(session.sidebar_width_px, g0.x);
    try std.testing.expectEqual(bar_h, g0.y);
    try std.testing.expectEqual(@as(u32, 800), g0.w);
    try std.testing.expectEqual(@as(u32, 600) -| bar_h, g0.h);
}

// 비대칭 window padding(left≠right, top≠bottom) 회귀: paneTermRect가 좌상으로 left/top만큼만 들이고 폭/높이를
// (left+right)/(top+bottom)만큼 줄이며, gridFromBacking이 같은 비대칭 합을 grid에서 빼는지 고정한다. 대칭 합산
// (2×)으로 회귀하면 left≠right일 때 origin·폭이 어긋나므로 이 단언이 잡는다.
test "asymmetric window padding insets paneTermRect by left/top and grid by left+right/top+bottom" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 비대칭: 좌 10·우 20·상 4·하 8.
    session.window_padding_px = .{ .left = 10, .right = 20, .top = 4, .bottom = 8 };
    session.cell_height_px = 18; // 탭 바 높이 결정적
    session.titlebar_strip_px = 0; // 상단 타이틀바 띠는 별도 테스트 — 여기선 비대칭 padding/grid 수학만 격리
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;

    const r = session.termRect();
    const bar_h = session.paneBarHeightPx();
    const g = session.paneTermRect(r);
    // x는 left(10)만큼만, y는 top(4) + 바만큼 들어간다(우/하는 origin에 영향 없음).
    try std.testing.expectEqual(session.sidebar_width_px + 10, g.x);
    try std.testing.expectEqual(bar_h + 4, g.y);
    // 폭은 left+right(30), 높이는 바 + top+bottom(12)만큼 줄어든다.
    try std.testing.expectEqual(@as(u32, 800 - 30), g.w);
    try std.testing.expectEqual(@as(u32, 600) -| bar_h -| 12, g.h);

    // gridFromBacking도 비대칭 합(left+right=30, top+bottom=12)을 grid에서 뺀다(좌우·상하 대칭 가정 없이).
    // 800px term 폭(사이드바 뺀) 기준 cell 8px: (800−30)/8=96 cols, (600−12)/18=32 rows.
    const grid = layout_math.gridFromBacking(session.sidebar_width_px + 800, 600, 8, 18, session.sidebar_width_px, session.window_padding_px);
    try std.testing.expectEqual(@as(u16, 96), grid.cols);
    try std.testing.expectEqual(@as(u16, 32), grid.rows);
}

test "takeBell respects bell.audible; createTerm injects config scrollback" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // createTerm이 config 스크롤백(is_test 빈 config → 기본 1000)을 활성 surface core에 주입했다.
    try std.testing.expectEqual(@as(usize, 1000), session.activeSurface().core.maxScrollback());

    // audible(기본 true): BEL → dispatchBell이 분배 → takeBell true, 한 번 drain(두 번째는 false). (F2-4: takeBell은
    // 코어가 아니라 dispatchBell이 세운 bell_audible_pending을 본다 — 코어 단일 drain.)
    session.audible_bell = true;
    try session.activeSurface().core.write("\x07");
    session.dispatchBell();
    try std.testing.expect(session.takeBell());
    try std.testing.expect(!session.takeBell());

    // 음소거: BEL → dispatchBell이 코어를 drain하되 audible_pending은 안 켬 → takeBell false(소리 억제, stale 안 쌓임).
    session.audible_bell = false;
    try session.activeSurface().core.write("\x07");
    session.dispatchBell();
    try std.testing.expect(!session.takeBell());

    // 시각 벨(bell.visual): on이면 BEL이 bell_flash_ticks를 켠다(audible과 독립). (F2-4)
    session.bell_visual = true;
    try session.activeSurface().core.write("\x07");
    session.dispatchBell();
    try std.testing.expect(session.bell_flash_ticks > 0);
    session.bell_visual = false;
    session.bell_flash_ticks = 0;

    // Dock 배지(bell.dock-badge): **언포커스 시에만** bell_badge_pending. 포커스 중엔 안 켠다. take_bell_badge는 1회성.
    session.bell_dock_badge = true;
    session.window_focused = true;
    try session.activeSurface().core.write("\x07");
    session.dispatchBell();
    try std.testing.expect(!session.takeBellBadge()); // 포커스 중 → 배지 없음
    session.window_focused = false;
    try session.activeSurface().core.write("\x07");
    session.dispatchBell();
    try std.testing.expect(session.takeBellBadge()); // 언포커스 → 배지
    try std.testing.expect(!session.takeBellBadge()); // 1회성
}

// M0a SurfaceIdAllocator — surface_id는 앱 인스턴스 전역 opaque u64로 발급되며, 서로 다른 창(AppSession)이
// 같은 allocator 인스턴스를 공유한다(docs/window-surface-mobility.md §8). per-session next_id로 발급하면 두 창의
// 첫 surface가 둘 다 1이라 충돌하는데(멀티 창 MARU_PANE_ID 충돌 포함), 이 테스트가 그 회귀를 잡는다.
test "setWebNavState: upsert + 옛 url free + 조회 + 없는 surface null (7e-1a)" {
    // setWebNavState/webNavState는 self.allocator·self.web_nav_states만 만지므로 minimal init로 충분하다
    // (undefined session의 나머지 필드는 안 읽음 — [[devsession-undefined-test-field-trap]] 범위 밖). testing.allocator가
    // upsert의 옛 url free 누락(누수)·이중 free(UAF)를 검출한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.web_nav_states = .empty;
    defer {
        var it = session.web_nav_states.valueIterator();
        while (it.next()) |v| session.allocator.free(v.url);
        session.web_nav_states.deinit(session.allocator);
    }
    session.setWebNavState(42, true, false, "https://a/");
    try std.testing.expectEqualStrings("https://a/", session.webNavState(42).?.url);
    try std.testing.expect(session.webNavState(42).?.can_go_back);
    try std.testing.expect(!session.webNavState(42).?.can_go_forward);
    // upsert: 옛 url을 free하고 새 url(다른 길이)로 교체 — 누수/UAF 없어야 통과.
    session.setWebNavState(42, false, true, "https://b/longer");
    try std.testing.expectEqualStrings("https://b/longer", session.webNavState(42).?.url);
    try std.testing.expect(session.webNavState(42).?.can_go_forward);
    try std.testing.expect(!session.webNavState(42).?.can_go_back);
    // 빈 url(url_ptr null ABI 경로) 저장.
    session.setWebNavState(7, false, false, "");
    try std.testing.expectEqualStrings("", session.webNavState(7).?.url);
    // 없는 surface → null.
    try std.testing.expect(session.webNavState(999) == null);
}

test "AddrEdit 흐름: enter→append→commit(navigate)·cancel·teardown 정리 (7e-2a 헤드리스)" {
    // enter/append/backspace/commit/cancel + take 3종은 addr_edit·pending 필드만 만지므로 minimal init로 충분하다
    // ([[devsession-undefined-test-field-trap]]). **dropAddrEditIfSurface(step 6)가 읽는 pending 필드 전부**를 초기화한다 —
    // web_nav_action_pending도 그중 하나라 초기화하지 않으면 undefined read(UB)다(리뷰 [6]; 옛 주석 "나머지 필드 안 읽음"은
    // 틀렸음). 시각(metal_dirty·blink)은 순수 코어 밖(handleKeyEvent 래퍼/클릭 핸들러)이라 여기서 안 탄다 = 헤드리스 검증 가능.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator; // TextField(addr_field)가 self.allocator를 쓴다(text/preedit 동적)
    session.addr_field = .{};
    defer session.addr_field.deinit(std.testing.allocator);
    session.addr_edit = null;
    session.addr_focus_pull_pending = null;
    session.addr_navigate_pending = null;
    session.addr_navigate_url_len = 0;
    session.addr_focus_restore_pending = null;
    session.web_nav_action_pending = null; // dropAddrEditIfSurface가 읽음(teardown 정리 대상 일치 검사) — undefined read 방지
    // WP-P: takeWebAddrNavigate가 commit 슬롯이 비면 복원 브라우저 pending_url을 찾아 **탭 트리를 walk**한다 —
    // 이 최소 init에서 tabs/web_panel_prev를 안 채우면 undefined read(0xaa deref)다. 빈 목록으로 명시 초기화한다
    // (같은 계열 함정을 이미 겪은 자리라 주석으로 남긴다 — [[devsession-undefined-test-field-trap]]).
    session.tabs = .empty;
    session.web_panel_prev = .empty;

    // 1) 편집 진입: 현재 URL 시드 + focus-pull pending(1회성).
    session.enterAddrEdit(42, "https://old.example/");
    try std.testing.expect(session.addr_edit != null);
    try std.testing.expectEqualStrings("https://old.example/", session.addrEditText());
    try std.testing.expectEqual(@as(?u64, 42), session.takeWebAddrFocusPull());
    try std.testing.expectEqual(@as(?u64, null), session.takeWebAddrFocusPull()); // 1회성 drain

    // 2) 백스페이스로 비우고 새 bare 도메인 타이핑 → commit이 resolveNavUrl로 https:// 프리픽스.
    while (session.addrEditText().len > 0) session.addrEditBackspace();
    try std.testing.expectEqualStrings("", session.addrEditText());
    for ("example.com") |c| session.addrEditAppend(c);
    try std.testing.expectEqualStrings("example.com", session.addrEditText());

    // 3) commit: navigate pending(surface_id + resolved url) + 편집 종료 + focus-restore. navigate url은 세션 버퍼라 유효.
    session.commitAddrEdit();
    try std.testing.expect(session.addr_edit == null); // 편집 종료
    const nav = session.takeWebAddrNavigate() orelse return error.TestUnexpectedNull;
    try std.testing.expectEqual(@as(u64, 42), nav.surface_id);
    try std.testing.expectEqualStrings("https://example.com", nav.url); // bare → https:// 프리픽스
    try std.testing.expect(session.takeWebAddrNavigate() == null); // 1회성 drain
    try std.testing.expectEqual(@as(?u64, 42), session.takeWebAddrFocusRestore());
    try std.testing.expect(session.takeWebAddrFocusRestore() == null); // 1회성

    // 4) 위험 스킴(허용 안 되는 스킴)은 commit해도 navigate 안 세우고 **편집을 유지**한다 — 입력을 지우고 조용히 종료하지
    //    않아(제보 "그냥 무시 당함") 사용자가 고치거나 Esc로 취소하게 한다(이슈2).
    session.enterAddrEdit(7, "");
    _ = session.takeWebAddrFocusPull();
    for ("javascript://evil") |c| session.addrEditAppend(c);
    session.commitAddrEdit();
    try std.testing.expect(session.addr_edit != null); // 무효 → 편집 유지(조용히 종료 안 함)
    try std.testing.expectEqualStrings("javascript://evil", session.addrEditText()); // 입력 보존
    try std.testing.expect(session.takeWebAddrNavigate() == null); // 무효 스킴 → navigate 없음
    try std.testing.expect(session.takeWebAddrFocusRestore() == null); // 편집 유지 = focus-restore 안 세움
    session.cancelAddrEdit(true); // 다음 step 위해 편집 정리(Esc 의미)
    _ = session.takeWebAddrFocusRestore(); // drain

    // 5) cancel(Esc): 편집만 종료, navigate 없음, focus-restore만.
    session.enterAddrEdit(9, "https://x/");
    _ = session.takeWebAddrFocusPull();
    for ("abc") |c| session.addrEditAppend(c);
    session.cancelAddrEdit(true); // Esc 의미 — focus-restore 세움
    try std.testing.expect(session.addr_edit == null);
    try std.testing.expect(session.takeWebAddrNavigate() == null); // cancel은 로드 안 함
    try std.testing.expectEqual(@as(?u64, 9), session.takeWebAddrFocusRestore());

    // 6) teardown 정리: 편집 중 그 surface가 닫히면 addr_edit·관련 pending을 비운다(stale surface_id 방지).
    session.enterAddrEdit(11, "https://y/");
    try std.testing.expect(session.addr_edit != null);
    session.dropAddrEditIfSurface(999); // 다른 surface → 무동작
    try std.testing.expect(session.addr_edit != null);
    try std.testing.expectEqual(@as(?u64, 11), session.addrEditSurfaceId());
    session.dropAddrEditIfSurface(11); // 대상 surface → 정리
    try std.testing.expect(session.addr_edit == null);
    try std.testing.expect(session.addr_focus_pull_pending == null); // enter가 세운 pull도 대상 일치라 정리
}

test "슬라이스 4: 주소창 키보드 편집 — 화살표·shift 선택·단어·⌘A (handleAddrEditKey 배선)" {
    // handleAddrEditKey는 addr_field(TextField)만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_field = .{};
    defer session.addr_field.deinit(std.testing.allocator);
    session.addr_edit = 1; // 편집 활성(addrEditAppend/Backspace가 읽음)
    try session.addr_field.setText(std.testing.allocator, "abc/def"); // caret=끝(7)

    const key = struct {
        fn ev(k: chrome.input.Key, mods: chrome.input.Mods) chrome.input.InputEvent {
            return .{ .key = .{ .key = k, .mods = mods } };
        }
    }.ev;

    // ← : 그래핌 이동(7→6). 선택 없음.
    session.handleAddrEditKey(key(.left, .{}));
    try std.testing.expectEqual(@as(usize, 6), session.addr_field.caret);
    try std.testing.expect(session.addr_field.selection == null);

    // ⇧← : 선택 확장(anchor=6, focus=5).
    session.handleAddrEditKey(key(.left, .{ .shift = true }));
    try std.testing.expectEqual(@as(usize, 5), session.addr_field.caret);
    try std.testing.expectEqual(@as(usize, 5), session.addr_field.selection.?.lo());
    try std.testing.expectEqual(@as(usize, 6), session.addr_field.selection.?.hi());

    // → (no shift, 선택 있음): 선택 끝으로 collapse(6).
    session.handleAddrEditKey(key(.right, .{}));
    try std.testing.expectEqual(@as(usize, 6), session.addr_field.caret);
    try std.testing.expect(session.addr_field.selection == null);

    // ⌥← : 단어 시작으로("def" 시작=byte 4). URL 구분자 '/'가 경계.
    session.handleAddrEditKey(key(.left, .{ .option = true }));
    try std.testing.expectEqual(@as(usize, 4), session.addr_field.caret);

    // ⌘A : 전체 선택.
    session.handleAddrEditKey(.{ .key = .{ .key = .char, .codepoint = 'a', .mods = .{ .command = true } } });
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.selection.?.lo());
    try std.testing.expectEqual(@as(usize, 7), session.addr_field.selection.?.hi());

    // 타이핑(선택 대체): 'X' → 선택 전체가 "X"로.
    session.handleAddrEditKey(.{ .key = .{ .key = .char, .codepoint = 'X' } });
    try std.testing.expectEqualStrings("X", session.addr_field.text.items);
}

test "리뷰: 주소창 편집 중 ⌘A(select_all 액션)는 터미널이 아니라 주소 필드를 전체 선택한다" {
    // ⌘A는 Edit 메뉴 "Select All" 카탈로그 항목의 keyEquivalent라 keyDown이 아니라 runCatalogAction→run_action→
    // dispatchAppAction으로 온다(제보: 주소창서 ⌘A 안 먹음 — 옛 코드가 addr_edit 무시하고 터미널만 선택). addr_edit
    // 활성이면 터미널 코어(enqueueCoreCommand·activeSurface)로 안 새고 addr_field.selectAll만 만지므로 runtime/
    // activeSurface/chrome_host 없이 minimal init로 충분하다([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.metal_dirty = false;
    session.addr_edit = 1; // 편집 활성 → select_all이 필드 분기(터미널 경로 안 탐)
    session.addr_field = .{};
    defer session.addr_field.deinit(std.testing.allocator);

    try session.addr_field.setText(std.testing.allocator, "example.com"); // caret=끝, 선택 없음
    try std.testing.expect(session.addr_field.selection == null);
    session.dispatchAppAction(.select_all);
    // 필드 전체 [0, len)가 선택됨(터미널 select_all이 아니라). metal_dirty=하이라이트 재빌드 신호.
    try std.testing.expect(session.addr_field.selection != null);
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.selection.?.anchor);
    try std.testing.expectEqual(@as(usize, "example.com".len), session.addr_field.selection.?.focus);
    try std.testing.expect(session.metal_dirty);
}

test "슬라이스 4: 주소창 클립보드 — copyText는 필드 선택(⌘C), pasteText는 caret 삽입·개행 strip(⌘V)" {
    // copyText/pasteText는 addr_edit 분기에서 addr_field만 만진다(터미널 경로 안 탐). minimal init로 충분하되
    // surface_initialized·copy_buffer는 명시 초기화([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.surface_initialized = true;
    session.copy_buffer = &.{};
    session.clipboard_out_buffer = &.{}; // pendingClipboard가 drain 시 free(undefined면 UB) — [[devsession-undefined-test-field-trap]]
    session.metal_dirty = false;
    session.addr_edit = 1; // 편집 활성 → copy/paste가 필드 분기
    session.addr_field = .{};
    session.chrome_clipboard_write = &.{};
    defer session.addr_field.deinit(std.testing.allocator);
    defer if (session.copy_buffer.len > 0) std.testing.allocator.free(session.copy_buffer);
    defer if (session.clipboard_out_buffer.len > 0) std.testing.allocator.free(session.clipboard_out_buffer);
    defer if (session.chrome_clipboard_write.len > 0) std.testing.allocator.free(session.chrome_clipboard_write);

    try session.addr_field.setText(std.testing.allocator, "abcdef"); // caret=끝(6)
    // ⌘C: 선택 [1,4)="bcd"를 복사(필드 선택).
    session.addr_field.selection = .{ .anchor = 1, .focus = 4 };
    try std.testing.expectEqualStrings("bcd", session.copyText());
    // 선택 없으면 빈(터미널 선택으로 안 샘 — 편집 컨텍스트는 주소창이 클립보드 주체).
    session.addr_field.selection = null;
    try std.testing.expectEqualStrings("", session.copyText());

    // ⌘V: 클립보드 텍스트를 caret에 삽입(개행·NUL strip → 단일행). caret=끝 → "abcdef"+"XYZ".
    session.pasteText("X\nY\r\nZ", false);
    try std.testing.expectEqualStrings("abcdefXYZ", session.addr_field.text.items);
    // 선택 대체 붙여넣기: 전체 선택 후 → 선택이 붙여넣기로 대체.
    session.addr_field.selectAll();
    session.pasteText("hello", false);
    try std.testing.expectEqualStrings("hello", session.addr_field.text.items);

    // 리뷰 #3: 모든 C0 제어문자(ESC 0x1B·FF 0x0C·VT 0x0B·BS 0x08)·DEL(0x7F) 제거(옛 코드는 \r\n\0\t만 걸렀다).
    session.addr_field.selectAll();
    session.pasteText("a\x1bb\x0cc\x0bd\x08e\x7ff", false);
    try std.testing.expectEqualStrings("abcdef", session.addr_field.text.items);
    // 리뷰 #7: 손상 UTF-8 바이트는 건너뛰고 유효 UTF-8만 삽입(text가 항상 유효 UTF-8 — 폭 드리프트 방지).
    session.addr_field.selectAll();
    session.pasteText("가\xffab", false); // 0xFF는 유효 UTF-8 아님 → 건너뜀
    try std.testing.expectEqualStrings("가ab", session.addr_field.text.items);
    try std.testing.expect(std.unicode.utf8ValidateSlice(session.addr_field.text.items));
    try session.addr_field.setText(std.testing.allocator, "hello"); // 아래 ⌘X 테스트 상태 복원

    // ⌘X: 전체 선택 잘라내기 → text에서 제거 + 클립보드-쓰기 큐에 **먼저 캡처**(삭제와 순서 무관). pendingClipboard가
    // 그 바이트를 반환(Swift가 NSPasteboard에 씀 — OSC52 write와 같은 drain). chrome_clipboard_write set이라 터미널 경로 안 탐.
    session.addr_field.selectAll();
    session.handleAddrEditKey(.{ .key = .{ .key = .char, .codepoint = 'x', .mods = .{ .command = true } } });
    try std.testing.expectEqualStrings("", session.addr_field.text.items); // 잘려서 비었음
    try std.testing.expect(session.addr_field.selection == null);
    try std.testing.expectEqualStrings("hello", session.pendingClipboard()); // 잘라낸 바이트가 클립보드로

    // ⌘X 선택 없으면 무동작(클립보드 큐 안 채움).
    try session.addr_field.setText(std.testing.allocator, "abc");
    session.handleAddrEditKey(.{ .key = .{ .key = .char, .codepoint = 'x', .mods = .{ .command = true } } });
    try std.testing.expectEqualStrings("abc", session.addr_field.text.items); // 선택 없어 그대로
    try std.testing.expectEqual(@as(usize, 0), session.chrome_clipboard_write.len);
}

test "navButtonAt: 밴드 좌측 존을 back/forward/reload로 가르고 URL 존은 null (7e-3 hit-test)" {
    // 순수 함수 — nav_button_w=3, nav_button_count=3(단일 소스). band_x=100px, cw=10px 기준.
    // 존: [100,130)=back·[130,160)=forward·[160,190)=reload·[190,∞)=URL(null). 렌더 글리프 col(1·4·7 = 존 가운데)와 정합.
    const band_x: u32 = 100;
    const cw: u32 = 10;
    // back 존(cell 0~2 = px 100~129). 렌더 글리프는 col 1(px 110~119)에 — 존 안.
    try std.testing.expectEqual(@as(?NavButton, .back), navButtonAt(100, band_x, cw)); // 존 좌단
    try std.testing.expectEqual(@as(?NavButton, .back), navButtonAt(115, band_x, cw)); // 글리프 칸(col 1)
    try std.testing.expectEqual(@as(?NavButton, .back), navButtonAt(129, band_x, cw)); // 존 우단
    // forward 존(cell 3~5). 글리프 col 4.
    try std.testing.expectEqual(@as(?NavButton, .forward), navButtonAt(130, band_x, cw));
    try std.testing.expectEqual(@as(?NavButton, .forward), navButtonAt(145, band_x, cw)); // 글리프 칸(col 4)
    try std.testing.expectEqual(@as(?NavButton, .forward), navButtonAt(159, band_x, cw));
    // reload 존(cell 6~8). 글리프 col 7.
    try std.testing.expectEqual(@as(?NavButton, .reload), navButtonAt(160, band_x, cw));
    try std.testing.expectEqual(@as(?NavButton, .reload), navButtonAt(175, band_x, cw)); // 글리프 칸(col 7)
    try std.testing.expectEqual(@as(?NavButton, .reload), navButtonAt(189, band_x, cw));
    // URL 존(cell >= 9 = px >= 190) → null(밴드 클릭이 편집 진입으로).
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(190, band_x, cw));
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(500, band_x, cw));
    // 밴드 좌측 밖·cw==0·비유한 → null(방어).
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(99, band_x, cw)); // band_x 왼쪽
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(150, band_x, 0)); // cw==0
    try std.testing.expectEqual(@as(?NavButton, null), navButtonAt(std.math.inf(f64), band_x, cw));
}

test "takeWebNavAction: 활성 버튼 클릭이 세운 pending을 1회 drain + teardown 정리 (7e-3 헤드리스)" {
    // web_nav_action_pending/code만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null;
    session.addr_focus_pull_pending = null;
    session.addr_navigate_pending = null;
    session.addr_focus_restore_pending = null;
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 0;

    // 초기: 없음(-1 상당 = null).
    try std.testing.expect(session.takeWebNavAction() == null);

    // back(code 0) 세움 → 1회 drain으로 (surface_id, code) 반환, 두 번째는 null(1회성).
    session.web_nav_action_pending = 42;
    session.web_nav_action_code = 0;
    const act = session.takeWebNavAction() orelse return error.TestUnexpectedNull;
    try std.testing.expectEqual(@as(u64, 42), act.surface_id);
    try std.testing.expectEqual(@as(u8, 0), act.code);
    try std.testing.expect(session.takeWebNavAction() == null); // 1회성 drain

    // reload(code 2) 세움 → 반환 code=2.
    session.web_nav_action_pending = 7;
    session.web_nav_action_code = 2;
    const act2 = session.takeWebNavAction() orelse return error.TestUnexpectedNull;
    try std.testing.expectEqual(@as(u8, 2), act2.code);

    // teardown: pending을 세운 채 그 surface가 닫히면 dropAddrEditIfSurface가 비운다(stale 방지). addr_field은 이 경로가
    // 안 만지므로(대상 addr_edit=null) init 불요 — web_nav_action_pending 정리만 검증.
    session.web_nav_action_pending = 11;
    session.web_nav_action_code = 1;
    session.dropAddrEditIfSurface(999); // 다른 surface → 무동작
    try std.testing.expectEqual(@as(?u64, 11), session.web_nav_action_pending);
    session.dropAddrEditIfSurface(11); // 대상 → 정리
    try std.testing.expect(session.web_nav_action_pending == null);
}

test "setBrowserNavAction: 활성 버튼만 pending을 세운다 (7e-3 클릭·7e-4 키보드 공유 정책, 헤드리스)" {
    // web_nav_states(활성 판정) + web_nav_action_pending/code/metal_dirty만 만지므로 minimal init로 충분
    // ([[devsession-undefined-test-field-trap]]). testing.allocator가 url 누수를 검출한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.web_nav_states = .empty;
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 0;
    session.metal_dirty = false;
    defer {
        var it = session.web_nav_states.valueIterator();
        while (it.next()) |v| session.allocator.free(v.url);
        session.web_nav_states.deinit(session.allocator);
    }

    // 42: can_go_back=true, can_go_forward=false.
    session.setWebNavState(42, true, false, "https://a/");

    // reload는 nav 상태 무관 항상 활성 → pending=42·code=2·metal_dirty.
    session.setBrowserNavAction(42, .reload);
    try std.testing.expectEqual(@as(?u64, 42), session.web_nav_action_pending);
    try std.testing.expectEqual(@as(u8, 2), session.web_nav_action_code);
    try std.testing.expect(session.metal_dirty);

    // back: can_go_back=true → 활성 → code=0.
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 9;
    session.setBrowserNavAction(42, .back);
    try std.testing.expectEqual(@as(?u64, 42), session.web_nav_action_pending);
    try std.testing.expectEqual(@as(u8, 0), session.web_nav_action_code);

    // forward: can_go_forward=false → 비활성 → no-op(pending·code 불변, 클릭도 소비만).
    session.web_nav_action_pending = null;
    session.web_nav_action_code = 9;
    session.setBrowserNavAction(42, .forward);
    try std.testing.expect(session.web_nav_action_pending == null);
    try std.testing.expectEqual(@as(u8, 9), session.web_nav_action_code);

    // nav 상태 없는 surface: back(비활성) no-op, reload(항상 활성)만 세운다.
    session.web_nav_action_pending = null;
    session.setBrowserNavAction(999, .back);
    try std.testing.expect(session.web_nav_action_pending == null);
    session.setBrowserNavAction(999, .reload);
    try std.testing.expectEqual(@as(?u64, 999), session.web_nav_action_pending);
    try std.testing.expectEqual(@as(u8, 2), session.web_nav_action_code);
}

test "setWebNavState: 값이 바뀔 때만 metal_dirty (링크 이동 주소창 재렌더, 7e-4 후속 헤드리스)" {
    // web_nav_states + metal_dirty만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    // testing.allocator가 url 누수를 검출한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.web_nav_states = .empty;
    session.metal_dirty = false;
    defer {
        var it = session.web_nav_states.valueIterator();
        while (it.next()) |v| session.allocator.free(v.url);
        session.web_nav_states.deinit(session.allocator);
    }

    // 첫 상태 = 새 항목 → metal_dirty(첫 주소 표시).
    session.setWebNavState(7, false, false, "https://a/");
    try std.testing.expect(session.metal_dirty);

    // 같은 값 재push(무변화 KVO 재관측) → metal_dirty 안 세움(불필요 재렌더 방지).
    session.metal_dirty = false;
    session.setWebNavState(7, false, false, "https://a/");
    try std.testing.expect(!session.metal_dirty);

    // url 변경(링크 이동) → metal_dirty(주소창 갱신 — 이 슬라이스의 핵심 수정).
    session.setWebNavState(7, true, false, "https://b/");
    try std.testing.expect(session.metal_dirty);

    // can_go_back만 변경 → metal_dirty(nav 버튼 활성색 갱신).
    session.metal_dirty = false;
    session.setWebNavState(7, false, false, "https://b/");
    try std.testing.expect(session.metal_dirty);
}

test "setHoveredNavButton: surface_id·버튼이 바뀔 때만 metal_dirty (dedup, 7e-4 헤드리스)" {
    // hovered_nav_button/metal_dirty만 만지므로 minimal init로 충분([[devsession-undefined-test-field-trap]]).
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.hovered_nav_button = null;
    session.metal_dirty = false;

    // null → {42, back}: 변화 → dirty.
    session.setHoveredNavButton(.{ .surface_id = 42, .button = .back });
    try std.testing.expect(session.metal_dirty);
    try std.testing.expect(session.hovered_nav_button != null);

    // 같은 값 재설정: 무동작(dedup — dirty 안 세워짐).
    session.metal_dirty = false;
    session.setHoveredNavButton(.{ .surface_id = 42, .button = .back });
    try std.testing.expect(!session.metal_dirty);

    // 다른 버튼(같은 surface): 변화 → dirty.
    session.setHoveredNavButton(.{ .surface_id = 42, .button = .forward });
    try std.testing.expect(session.metal_dirty);

    // 다른 surface(같은 버튼): 변화 → dirty.
    session.metal_dirty = false;
    session.setHoveredNavButton(.{ .surface_id = 7, .button = .forward });
    try std.testing.expect(session.metal_dirty);

    // → null: 변화 → dirty.
    session.metal_dirty = false;
    session.setHoveredNavButton(null);
    try std.testing.expect(session.metal_dirty);
    try std.testing.expect(session.hovered_nav_button == null);
}

test "M0a: surface_id는 앱 전역 allocator에서 발급 — 두 창이 id를 공유해 충돌하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText
    const allocator = std.testing.allocator;

    const s1 = try allocator.create(AppSession);
    defer allocator.destroy(s1);
    try s1.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s1.deinit();

    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();

    // 두 세션은 앱 인스턴스에 하나뿐인 allocator를 공유한다(창마다 별도 카운터가 아님).
    try std.testing.expectEqual(s1.surface_ids, s2.surface_ids);
    try std.testing.expectEqual(&app_runtime.surface_ids, s1.surface_ids);

    // createTerm이 per-session 카운터가 아니라 앱 전역 SurfaceIdAllocator에서 발급하므로, 서로 다른 창의 첫
    // surface조차 id가 겹치지 않는다(per-session이면 둘 다 1이라 충돌 — 이 단언이 그 회귀를 잡는다).
    try std.testing.expect(s1.activeSurface().id != s2.activeSurface().id);
}

// M3a LiveSurfaceRegistry 배선 — surface + live PTY 런타임의 **소유**가 Term-inline이 아니라 앱 전역
// `app_runtime.live_registry`의 `LiveSurface` 번들 슬롯으로 이전됐고, 모든 창(AppSession)이 그 한 registry를 공유한다
// (docs/window-surface-mobility.md §8A.1). createTerm이 `create`로 번들을 registry에 소유시키고 Term은 슬롯의
// surface·live_pty를 포인터로 참조만 한다. 이 테스트는 (1) 창 간 registry 공유, (2) Term이 든 두 포인터 == 번들
// 슬롯의 두 필드(소유는 registry), (3) 두 창 번들의 앱 전역 공존을 못박는다.
test "M3a: 앱 전역 live registry를 모든 창(AppSession)이 공유 — surface·런타임 소유는 창 밖 번들 슬롯" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const before = app_runtime.live_registry.count();

    const s1 = try allocator.create(AppSession);
    defer allocator.destroy(s1);
    try s1.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s1.deinit();

    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();

    // 두 세션이 앱 인스턴스에 하나뿐인 registry를 공유한다(창별 소유가 아님, surface_ids와 동형).
    try std.testing.expectEqual(s1.live_registry, s2.live_registry);
    try std.testing.expectEqual(&app_runtime.live_registry, s1.live_registry);

    // 각 창의 첫 Term의 surface·런타임이 그 창의 surface_id로 registry 번들에 소유돼 있고, Term은 surface 포인터(참조)와
    // opaque runtime handle(P2 seam — live_pty 포인터 대신)을 든다. handle이 surface_id와 같아 registry 번들 슬롯을
    // 찾는 키가 된다(소유는 registry, Term은 참조·handle — 이 단언이 M3a 배선 + P2 seam을 못박는다).
    const sid1 = s1.activeSurface().id;
    const sid2 = s2.activeSurface().id;
    try std.testing.expect(sid1 != sid2); // M0a: 앱 전역 유일
    const b1 = s1.live_registry.findBySurface(sid1).?; // *LiveSurface 번들 슬롯
    const b2 = s2.live_registry.findBySurface(sid2).?;
    try std.testing.expectEqual(s1.activePane().activeTerm().rt.handle, sid1);
    try std.testing.expectEqual(s2.activePane().activeTerm().rt.handle, sid2);
    // M3a 핵심: Term.surface가 이제 번들 슬롯의 surface를 가리킨다(Term-inline이 아니라 registry 소유).
    try std.testing.expectEqual(s1.activePane().activeTerm().surface, &b1.terminal.surface);
    try std.testing.expectEqual(s2.activePane().activeTerm().surface, &b2.terminal.surface);
    // 두 창의 번들이 한 registry에 공존한다(앱 전역 소유 — 창이 달라도 같은 owner).
    try std.testing.expectEqual(before + 2, app_runtime.live_registry.count());
}

// M3b 라우팅 앱-전역화 — 입력/resize/명령/PTY 이벤트 라우팅 표(`SurfaceRuntime`)가 per-window가 아니라 **앱 전역**
// (`app_runtime.routing`)이고, 모든 창(AppSession)이 그 한 표를 공유한다(docs/window-surface-mobility.md §8A.2). 이
// 테스트는 세 가지를 못박는다: (1) 두 창이 같은 라우팅 표를 가리킨다(공유), (2) **한 표가 두 창 surface를 모두**
// surface_id로 keyed 보유한다(격리는 값 분리가 아니라 유일 키로 — 이게 cross-window 이동(M3d)이 라우팅을 안 건드려도
// 되는 근거), (3) **창 격리 불변식**: 한 창(s1)을 닫으면 그 창 링크만 표에서 빠지고 다른 창(s2) surface는 그대로
// 라우팅된다 — 창 close가 `self.runtime.deinit()`으로 공유 표를 파괴하면 s2가 죽는다(그 회귀를 이 단언이 잡는다).
// 실 init(실 PTY/CoreText)이라 macOS 게이트 — 프로덕션 배선 검증(모듈-로컬 var·필드 기본값 포함).
test "M3b: 앱-전역 SurfaceRuntime — 두 창이 한 라우팅 표 공유 + 창 격리(s1 닫아도 s2 라우팅 생존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText

    const allocator = std.testing.allocator;

    const s1 = try allocator.create(AppSession);
    defer allocator.destroy(s1);
    try s1.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    // s1.deinit()은 아래에서 **명시** 호출한다(창 격리 검증: s1 close 후 s2가 살아 있는지).

    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();

    // (1) 두 창이 앱 전역 라우팅 표 하나를 공유한다(per-window 값 필드가 아니라 공유 coordinator 필드 포인터).
    try std.testing.expectEqual(s1.runtime, s2.runtime);
    try std.testing.expectEqual(&app_runtime.routing, s1.runtime);

    const sid1 = s1.activeSurface().id;
    const sid2 = s2.activeSurface().id;
    try std.testing.expect(sid1 != sid2); // M0a: 앱 전역 유일

    // (2) 한 표가 두 창 surface를 모두 surface_id로 보유한다 — 공유 표를 통해 어느 창 surface든 라우팅된다(빈 바이트
    // write는 무해한 라우팅 probe: 링크 없으면 UnknownSurface, 있으면 attach된 pty_io로 0바이트 write). per-window 표라면
    // s1의 표엔 sid2가 없어 UnknownSurface가 났을 것 — 앱-전역이라 둘 다 성공한다.
    try s1.runtime.writeInput(sid1, .{ .bytes = "" });
    try s1.runtime.writeInput(sid2, .{ .bytes = "" }); // s1을 통해서도 s2 surface가 조회된다(한 표)
    try s2.runtime.writeInput(sid1, .{ .bytes = "" }); // 대칭

    // (3) 창 격리 불변식: s1을 닫으면 s1 링크만 표에서 빠지고 s2 surface는 그대로 라우팅된다. s1.deinit()이 공유 표를
    // deinit하면(옛 per-window 규율) s2가 UnknownSurface/UB로 죽는다 — 그 회귀를 잡는다. s2.runtime(==공유 표)로 probe.
    s1.deinit();
    try std.testing.expectError(error.UnknownSurface, s2.runtime.writeInput(sid1, .{ .bytes = "" })); // s1 링크 제거됨
    try s2.runtime.writeInput(sid2, .{ .bytes = "" }); // s2는 생존 — 공유 표가 s1 close에 파괴되지 않았다
}

fn appendTrackedRemoteTermForTest(session: *AppSession) !*Term {
    app_keep_alive_after_quit = true;
    session.loaded_config.config.session.keep_alive_after_quit = true;
    const term = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
    errdefer session.destroyTerm(term);
    try session.tabs.items[0].panes.items[0].terms.append(session.allocator, term);
    return term;
}

// P3-e3 통합 스모크 — keep-alive AppSession가 새 Term을 **host-backed backend**로 실제 spawn하고, 입력이 host를 거쳐
// 화면에 반영되며, teardown이 in-process/원격 Term과 원격 backend/연결을 누수·크래시 없이 회수하는지 고정한다. 이 경로
// (createTerm→backendForNew→원격 spawn, backendFor(term) 라우팅, deinit 원격 회수)는 부품 스모크(remote_term_backend·
// host_connect)가 못 잡던 **AppSession 통합**이다. 실 fork host + 실 AppSession(PTY/CoreText)이라 macOS 게이트.
// (session_host.* 심볼은 non-macOS에서 barrel이 struct {}로 제외하므로 본문 전체를 `if (is_macos)` comptime 가지치기에 둔다.)
test "P3-e3 통합: keep-alive AppSession가 새 Term을 host-backed backend로 spawn하고 clean teardown한다" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        // 격리된 cache base + 소켓(사용자 실 host와 무관). host는 <base>/session-host/control.sock에 bind.
        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-e3-app-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700); // host는 <base>/session-host만 mkdir하므로 base를 먼저 만든다.
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        // host가 bind할 때까지 대기(connect 성공). 그래야 아래 connectOrLaunch가 connect-first로 붙어 spawn을 시도하지 않는다.
        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var probe = cl;
                probe.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        // AppSession 구성(첫 탭 = in-process — 테스트 config는 keep-alive off라 원격 세팅 전 spawn된다).
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();

        // 격리된 host로 **앱 전역** 원격 backend를 세운다(ensureRemoteBackend와 같은 배선이되 base를 명시해 XDG env 의존 없이).
        // testing.allocator로 세워 leak 검출을 받고, 아래에서 명시 reset한다(앱 전역이라 창 deinit이 안 닫으므로).
        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused-maru-helper", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, session.runtime);
        defer { // 앱 전역이라 창 deinit이 안 닫는다 — 테스트 격리를 위해 명시 reset(runtimes는 destroyTerm이 이미 비운다).
            host_connect_failed = false;
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        // 첫 탭 term은 in-process다(원격 backend 세팅 전에 spawn됨 → surface.remote == null).
        const first = session.tabs.items[0].panes.items[0].terms.items[0];
        try std.testing.expect(first.surface.remote == null);
        app_keep_alive_after_quit = true;
        session.loaded_config.config.ambiguous_width = .wide; // 기본값 반대로 두어 host bootstrap 누락의 가짜 green을 막는다.

        // createTerm으로 /bin/cat을 띄운다 — backendForNew가 이제 원격 backend를 고른다. 반환 Term은 tab에 안 들어가므로
        // 아래 destroyTerm으로 회수한다(원격 라우팅 backendFor(term)을 탄다).
        const term = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        try std.testing.expect(term.surface.remote != null); // **host-backed!**(surface.remote 세팅 = 원격 조립 화면)

        // 입력 hot path(self.runtime.writeInput)가 원격 PtyIo→host로 라우팅되고, host echo delta가 pump→화면에 반영되는지.
        try session.runtime.writeInput(term.surface.id, .{ .bytes = "hello\n" });
        var found = false;
        var it: usize = 0;
        while (it < 100 and !found) : (it += 1) {
            _ = term.rt.pump.drainAvailable() catch break; // 원격 pump = delta stream 소비.
            term.surface.lockCore(io);
            const c0 = term.surface.renderSnapshot().cells[0].codepoint;
            term.surface.unlockCore(io);
            if (c0 == 'h') found = true else _ = usleep(20 * 1000);
        }
        try std.testing.expect(found); // 원격 Term 입력이 host를 거쳐 Surface에 반영됐다(end-to-end).
        term.surface.lockCore(io);
        const remote_ambiguous_wide = term.surface.renderSnapshot().ambiguous_wide;
        term.surface.unlockCore(io);
        try std.testing.expect(remote_ambiguous_wide); // createTerm attach 뒤 config snapshot이 host core에 적용돼 다시 투영됐다.

        // 멀티 윈도우(전역화 핵심): 두 번째 AppSession(창)이 `ensureRemoteBackend`로 **이미 세워진 앱 전역 backend를 재사용**
        // 한다(새 연결 안 만듦 — early-return). 그 창의 createTerm도 같은 공유 backend로 가, 두 창의 원격 Term이 **한 backend·
        // 한 연결**을 공유한다. 이게 "단일 앱 + 여러 창/workspace가 serial daemon과 충돌 없이 동작"을 참으로 만든다.
        const s2 = try allocator.create(AppSession);
        defer allocator.destroy(s2);
        try s2.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer s2.deinit();
        // production과 같은 resolver를 타므로 Window A에서 이미 켠 앱 전역 policy가 B의 stale 빈 test config보다
        // 우선한다. 따라서 B의 **첫 Term부터** 같은 공유 connection/backend의 remote여야 한다.
        try std.testing.expect(s2.activePane().activeTerm().surface.remote != null);
        try std.testing.expectEqual(@as(usize, 2), app_remote_backend.?.runtimes.count());

        // 제품 복사 경로 회귀: 두 번째 창의 활성 host-backed Term에서 보이는 "Maru"를 선택한 뒤 AppSession.copyText를
        // 호출한다. RemoteRuntime.selectedText 부품 테스트만으로는 활성 Term/surface id/앱 전역 backend 라우팅이 어긋나
        // 실제 Cmd+C가 빈 문자열이 되는 회귀를 잡지 못하므로, 실제 AppSession 경계까지 고정한다.
        const s2_active = s2.activePane().activeTerm();
        var s2_ready = false;
        var s2_it: usize = 0;
        while (s2_it < 100 and !s2_ready) : (s2_it += 1) {
            _ = s2_active.rt.pump.drainAvailable() catch break;
            s2_active.surface.lockCore(io);
            const c0 = s2_active.surface.renderSnapshot().cells[0].codepoint;
            s2_active.surface.unlockCore(io);
            if (c0 == 'M') s2_ready = true else _ = usleep(20 * 1000);
        }
        try std.testing.expect(s2_ready);
        try s2.runtime.enqueueCoreCommand(s2_active.surface.id, .{ .select_start = .{ .row = 0, .col = 0, .block = false } }, io);
        try s2.runtime.enqueueCoreCommand(s2_active.surface.id, .{ .select_extend = .{ .row = 0, .col = 3 } }, io);
        // 앱보다 먼저 떠 있던 같은-major host의 hello_ack에는 selected-text capability가 없다. 실제 AppSession
        // 경계에서도 remote projection fallback을 타게 해, placeholder core를 잘못 읽는 회귀를 막는다.
        app_remote_client.?.runtime_selected_text_v1 = false;
        try std.testing.expectEqualStrings("Maru", s2.copyText());
        app_remote_client.?.runtime_selected_text_v1 = true;

        const term2 = try s2.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        try std.testing.expect(term2.surface.remote != null); // 두 번째 창의 Term도 host-backed.
        try std.testing.expectEqual(@as(usize, 3), app_remote_backend.?.runtimes.count()); // B 첫 Term과 추가 Term까지 한 backend.

        s2.destroyTerm(term2);
        session.destroyTerm(term); // 원격 term 회수(backendFor→remote: remove + SurfaceRuntime detach + rr free).

        // 앱 업데이트 전에 떠 있던 구 v2 host는 runtime.spawn_full 이름을 알더라도 새 runtime_config를 조용히
        // 무시할 수 있다. capability 부재를 재현해 RemoteRuntime의 UnsupportedSpawnContract가 AppSession에서
        // 실제 in-process fallback으로 이어지고 잘못된 host runtime을 만들지 않는지 고정한다.
        app_remote_client.?.runtime_core_command_v1 = false;
        const legacy_fallback = try session.createTerm(
            .{ .command = "/bin/cat" },
            .{ .cols = 40, .rows = 10 },
            16,
            "cat",
            "/bin/cat",
        );
        try std.testing.expect(legacy_fallback.surface.remote == null);
        try std.testing.expect(host_connect_failed);
        session.destroyTerm(legacy_fallback);

        // 블록 끝 defer(LIFO): s2.deinit → destroy(s2) → reset(공유 backend/client) → session.deinit → destroy(session) → host
        // kill. 첫 창 local + 둘째 창 remote 첫 탭과 공유 backend를 누수·크래시 없이 회수한다.
    } else {
        return error.SkipZigTest;
    }
}

// R3 #3(code-review) — keep-alive로 host-backed 터미널을 쓰다 **host 프로세스가 죽으면**, 예전엔 backendForNew가 죽은 원격
// backend를 계속 골라 createTerm의 be.spawn이 ConnectionClosed로 전파돼 **새 터미널을 못 열었다**(앱 재시작 전까지). 이제
// createTerm이 연결사를 감지해 in-process로 폴백하고 host_connect_failed를 세워 이후 createTerm도 로컬로 뜬다. 실 fork host를
// 죽여 왕복 검증한다(macOS 게이트).
test "R3 #3: host가 죽으면 createTerm이 in-process로 폴백한다(새 터미널을 못 여는 대신)" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-r3-hd-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        var host_reaped = false; // 본문에서 host를 죽이므로 defer가 중복 reap 안 하게.
        defer {
            if (!host_reaped) {
                _ = std.c.kill(child, std.posix.SIG.KILL);
                var status: c_int = undefined;
                _ = std.c.waitpid(child, &status, 0);
            }
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        session.loaded_config.config.session.keep_alive_after_quit = true;
        app_keep_alive_after_quit = true;

        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, session.runtime);
        defer {
            host_connect_failed = false; // 모듈-var 테스트 격리(내 fix가 death 시 세운다).
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        // host 살아 있을 때: createTerm은 host-backed.
        const t_live = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        try std.testing.expect(t_live.surface.remote != null);
        try std.testing.expect(!host_connect_failed);

        // **host를 죽인다**(SIGKILL + reap → 소켓이 확실히 닫힘). 이제 원격 spawn RPC는 ConnectionClosed/WriteFailed.
        _ = std.c.kill(child, std.posix.SIG.KILL);
        var st: c_int = undefined;
        _ = std.c.waitpid(child, &st, 0);
        host_reaped = true;

        // host 죽은 뒤 createTerm: **실패 대신 in-process 폴백**. surface.remote == null + host_connect_failed 세워짐.
        const t_fb = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        try std.testing.expect(t_fb.surface.remote == null); // in-process로 떴다(폴백).
        try std.testing.expect(host_connect_failed); // 이후 createTerm도 원격 안 탐.

        // 세 번째도 바로 in-process(backendForNew가 host_connect_failed로 원격을 건너뜀 — 죽은 RPC 재시도 없음).
        const t3 = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        try std.testing.expect(t3.surface.remote == null);

        session.destroyTerm(t3);
        session.destroyTerm(t_fb);
        session.destroyTerm(t_live); // 원격(죽은 host) — remove의 terminate RPC는 조용히 실패, client-side만 회수.
    } else {
        return error.SkipZigTest;
    }
}

// §7 묘비의 **화면 안내와 ⏎ 되살리기**를 못박는다. notice는 아무 키에나 닫히므로 그것만으로는 사용자가 빈 pane을
// 보고 이유를 다시 확인할 방법이 없다 — 화면 콘텐츠로 남아야 복구 방법이 계속 보인다(writeHeldGuidance와 같은 규율).
// 되살리기는 **제자리 교체**여야 한다: append하면 묘비가 좀비 탭으로 남고 사용자가 만든 탭 순서가 밀린다.
// 그리고 "자동 fresh spawn 금지"가 비어 있는 계약이 아님을 증명해야 한다 — 아무 키·수식자 조합으로는 되살아나지
// 않고 ⏎만 승격시키는지 대조군으로 확인한다. 터미널에서 왜 중요한가: 사용자가 의도하지 않은 셸이 조용히 뜨면
// "이어진 세션"으로 오인해 없는 이력을 신뢰하게 된다.
test "종료 placeholder: 화면 안내가 남고 ⏎만 같은 슬롯을 새 셸로 되살린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const pane = session.activePane();
    const tomb = try session.createEndedPlaceholderTerm(
        "배포 감시",
        "/tmp",
        "/bin/zsh",
        .{ .cols = 80, .rows = 24 },
        "1234567890abcdef1234567890abcdef",
        "fedcba0987654321fedcba0987654321",
    );
    try pane.terms.append(a, tomb);
    session.focusTerm(pane.terms.items.len - 1);
    const tomb_index = pane.active_term;

    // 안내가 core에 남는다(멱등 — 두 번 불러도 덧쓰지 않는다).
    session.writeEndedPlaceholderGuidance(tomb);
    session.writeEndedPlaceholderGuidance(tomb);
    {
        tomb.surface.lockCore(session.io);
        defer tomb.surface.unlockCore(session.io);
        var found_cwd = false;
        var found_hint = false;
        var occurrences: usize = 0;
        var row: u16 = 0;
        while (row < tomb.surface.core.size.rows) : (row += 1) {
            var line_buf: [1024]u8 = undefined;
            var n: usize = 0;
            for (tomb.surface.core.viewportRow(row)) |cell| {
                if (cell.continuation or n + 4 > line_buf.len) continue;
                n += std.unicode.utf8Encode(cell.codepoint, line_buf[n..]) catch continue;
            }
            const line = line_buf[0..n];
            if (std.mem.indexOf(u8, line, "종료됐습니다") != null) occurrences += 1;
            if (std.mem.indexOf(u8, line, "/tmp") != null) found_cwd = true;
            if (std.mem.indexOf(u8, line, "새 셸 시작") != null) found_hint = true;
        }
        try std.testing.expectEqual(@as(usize, 1), occurrences); // 멱등 래치 — 안내로 화면이 도배되지 않는다
        try std.testing.expect(found_cwd); // 마지막 위치가 보여야 사용자가 어디였는지 안다
        try std.testing.expect(found_hint);
    }

    // 대조군: ⏎가 아닌 키와 수식자 조합으로는 되살아나지 않는다("자동 spawn 금지"의 non-vacuous 증명).
    _ = session.handleKeyEvent(.{ .key = .{ .char = 'a' } }) catch {};
    try std.testing.expect(pane.terms.items[tomb_index].rt.ended_placeholder);
    _ = session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .command = true } }) catch {};
    try std.testing.expect(pane.terms.items[tomb_index].rt.ended_placeholder);

    // ⏎: 같은 슬롯이 라이브 Term으로 바뀌고 탭 수·활성 인덱스는 그대로다(append가 아니라 제자리 교체).
    const before_terms = pane.terms.items.len;
    _ = try session.handleKeyEvent(.{ .key = .enter });
    try std.testing.expectEqual(before_terms, pane.terms.items.len);
    try std.testing.expectEqual(tomb_index, pane.active_term);
    const fresh = pane.terms.items[tomb_index];
    try std.testing.expect(!fresh.rt.ended_placeholder);
    try std.testing.expect(fresh.rt.live_initialized);
    try std.testing.expectEqual(@as(usize, 0), fresh.rt.ended_runtime_host_id.len);
    try std.testing.expectEqual(@as(usize, 0), fresh.rt.ended_runtime_id.len);
    // 대표 surface가 새 Term으로 재바인딩됐다(탭바·렌더가 이걸 읽는다 — 안 하면 해제된 묘비 surface를 가리킨다).
    try std.testing.expectEqual(fresh.surface, session.surface_ptrs.items[session.app_window.active_tab]);
}

// code-review(max) 회귀: 묘비의 ⏎ 게이트와 드롭 가드가 **구조 input owner 라우팅보다 위**에 놓여 있었다. 그 순서에서는
// 탐색기에서 파일을 여는 Enter(isFileTreeDefaultKey → .activate)가 파일을 열지 못한 채 **보고 있지도 않은** 묘비를
// 되살렸고, 이미지 붙여넣기는 구조 게이트가 먼저 반환하던 자리에서 activePane()을 deref했다. 터미널에서 왜 중요한가:
// 되살리기는 사용자가 그 pane을 보며 명시적으로 요청했을 때만 일어나야 하고("자동 fresh spawn 금지"의 실질), 입력
// 소유권은 paste·키 두 경로가 같은 판정(structuralInputOwner)을 공유해야 한쪽만 고쳐지는 일이 없다.
test "종료 placeholder: 파일 트리가 입력을 가지면 ⏎·드롭이 묘비를 건드리지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const pane = session.activePane();
    const tomb = try session.createEndedPlaceholderTerm("배포 감시", "/tmp", "/bin/zsh", .{ .cols = 80, .rows = 24 }, "", "");
    try pane.terms.append(a, tomb);
    session.focusTerm(pane.terms.items.len - 1);
    const tomb_index = pane.active_term;

    session.focus_owner = .{ .file_tree = .{ .restore_surface = null } };
    _ = session.handleKeyEvent(.{ .key = .enter }) catch {};
    try std.testing.expect(pane.terms.items[tomb_index].rt.ended_placeholder); // 트리의 Enter를 뺏지 않았다
    // 이미지 붙여넣기는 구조 owner에서 consumed(true)지만 묘비를 만지지 않는다(순서가 지켜졌다는 뜻).
    try std.testing.expect(session.handleDroppedImage("\x89PNG"));
    try std.testing.expect(pane.terms.items[tomb_index].rt.ended_placeholder);

    // 대조군: 워크스페이스가 입력을 되찾으면 같은 ⏎가 되살린다(게이트가 vacuous하지 않다).
    session.focus_owner = .workspace;
    _ = try session.handleKeyEvent(.{ .key = .enter });
    try std.testing.expect(!pane.terms.items[tomb_index].rt.ended_placeholder);
}

// code-review(max) 회귀: 되살리기가 사용자 rename(`surface.custom_name`)을 승계하지 않았다. `createTerm`은 custom_name을
// 만들지 않고 `destroyTerm(tomb)`이 묘비의 문자열을 해제하므로, ⏎ 한 번에 탭 이름이 자동 제목으로 되돌아가고 다음
// checkpoint가 빈 값을 저장해 rename이 **영구히** 사라졌다. 터미널에서 왜 중요한가: 복원 직후 탭바에 보이던 이름이
// 되살리는 순간 사라지면 사용자는 어느 탭이 무엇이었는지 잃는다(다른 restore-and-continue 경로는 모두 보존한다).
test "종료 placeholder: 되살리기가 사용자 rename을 승계한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const pane = session.activePane();
    const tomb = try session.createEndedPlaceholderTerm("끝난 세션", "/tmp", "/bin/zsh", .{ .cols = 80, .rows = 24 }, "", "");
    try pane.terms.append(a, tomb);
    session.focusTerm(pane.terms.items.len - 1);
    const tomb_index = pane.active_term;
    tomb.surface.custom_name = try session.dupeCustomName("배포 감시");

    _ = try session.handleKeyEvent(.{ .key = .enter });
    const fresh = pane.terms.items[tomb_index];
    try std.testing.expect(!fresh.rt.ended_placeholder);
    try std.testing.expectEqualStrings("배포 감시", fresh.surface.custom_name.?);
}

// code-review(max) 회귀: 제목·cwd는 길이 상한이 없는 사용자 데이터인데(OSC 제목·깊은 경로, 한글은 3B/자) 고정 버퍼에
// 그대로 담아, 넘치면 마지막 줄의 `catch return`이 안내를 **통째로** 버렸다. 멱등 래치는 이미 서 있어 재시도도 없어
// 사용자는 아무 설명도 힌트도 없는 빈 pane을 봤다. 터미널에서 왜 중요한가: ⏎ 힌트는 이 화면의 유일한 복구 affordance다.
test "종료 placeholder: 제목·경로가 버퍼를 넘겨도 ⏎ 힌트가 화면에 남는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    // 고정 버퍼(768B)를 확실히 넘기는 길이 — 한글 제목 480B + 깊은 경로 598B.
    const long_title = "한글제목" ** 40;
    const long_cwd = "/very/deep/project/path" ** 26;
    const tomb = try session.createEndedPlaceholderTerm(long_title, long_cwd, "/bin/zsh", .{ .cols = 80, .rows = 24 }, "", "");
    try session.activePane().terms.append(a, tomb);

    session.writeEndedPlaceholderGuidance(tomb);
    tomb.surface.lockCore(session.io);
    defer tomb.surface.unlockCore(session.io);
    var found_hint = false;
    var row: u16 = 0;
    while (row < tomb.surface.core.size.rows) : (row += 1) {
        var line_buf: [1024]u8 = undefined;
        var n: usize = 0;
        for (tomb.surface.core.viewportRow(row)) |cell| {
            if (cell.continuation or n + 4 > line_buf.len) continue;
            n += std.unicode.utf8Encode(cell.codepoint, line_buf[n..]) catch continue;
        }
        if (std.mem.indexOf(u8, line_buf[0..n], "새 셸 시작") != null) found_hint = true;
    }
    try std.testing.expect(found_hint);
}

// code-review(max) 회귀: 레이아웃 resize가 묘비 core만 바꾸고 관측 grid를 그대로 뒀다. `refreshTermObservation`은
// `live_initialized == false`에서 즉시 반환하므로 그 값은 생성 시 심은 저장 grid에 영원히 갇히는데,
// `captureWorkspaceTab`은 core.size보다 observation.size를 **우선**한다. 터미널에서 왜 중요한가: 창을 키운 채 종료하면
// 다음 실행의 새 셸이 창과 다른 winsize로 떠, 시작과 동시에 실행되는 TUI가 잘못된 기하로 레이아웃한다.
test "종료 placeholder: 레이아웃 resize가 저장될 grid까지 옮긴다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    const tomb = try session.createEndedPlaceholderTerm("끝난 세션", "/tmp", "/bin/zsh", .{ .cols = 80, .rows = 24 }, "", "");
    try session.activePane().terms.append(a, tomb);
    try session.resizeTermForLayout(tomb, .{ .cols = 120, .rows = 40 });
    try std.testing.expectEqual(@as(u16, 120), tomb.rt.observation.size.cols);
    try std.testing.expectEqual(@as(u16, 40), tomb.rt.observation.size.rows);
}

// code-review(max) 회귀: 드롭 라우팅의 "붙일 PTY 없음" 게이트가 `kind != .terminal`만 봐서 묘비를 `.routed`로 돌려줬다.
// 그러면 호스트는 포커스를 죽은 pane으로 옮긴 뒤 삽입을 시도하고, handleDroppedFiles의 묘비 가드가 경로를 버린다 —
// 사용자는 **살아 있는 셸에서 포커스를 뺏기고 드롭한 내용도 잃는다**. `.refused`는 포커스를 건드리지 않는다.
test "드롭 라우팅: 묘비 pane은 refused (포커스도 뺏지 않는다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;
    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    try session.splitActivePane(.horizontal); // 좌우 2 pane, 활성 = 새 pane(살아 있는 셸)
    const tab = session.activeTab();
    try std.testing.expectEqual(@as(usize, 2), tab.panes.items.len);
    const live_pane = session.activePane();
    const tomb_pane = if (tab.panes.items[0] == live_pane) tab.panes.items[1] else tab.panes.items[0];

    // 대상 pane의 활성 Term을 묘비로 바꾼다(제자리 교체 — 슬롯 수·트리 불변).
    const dead = tomb_pane.terms.items[tomb_pane.active_term];
    const tomb = try session.createEndedPlaceholderTerm("끝난 세션", "/tmp", "/bin/zsh", .{ .cols = 80, .rows = 24 }, "", "");
    tomb_pane.terms.items[tomb_pane.active_term] = tomb;
    session.destroyTerm(dead);
    session.surface_ptrs.items[session.app_window.active_tab] = session.activePane().activeTerm().surface;
    session.app_window.tabs = session.surface_ptrs.items;

    var leaf_rects: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaf_rects.deinit(a);
    try session.activeTabLeafRects(a, session.termRect(), &leaf_rects);
    const rect = for (leaf_rects.items) |lr| {
        if (lr.leaf == tomb_pane) break lr.rect;
    } else return error.SkipZigTest;

    const cx: f64 = @floatFromInt(rect.x + @as(i64, @intCast(rect.w / 2)));
    const cy: f64 = @floatFromInt(rect.y + @as(i64, @intCast(rect.h / 2)));
    try std.testing.expectEqual(AppSession.DropRoute.refused, session.routeDropAtPoint(cx, cy));
    try std.testing.expectEqual(live_pane, session.activePane()); // 포커스는 살아 있는 pane에 그대로
}

// §7 복원 배선을 못박는다: runtime이 영구히 없는 Term **하나만** 묘비가 되고 같은 pane의 다른 surface·split 트리·탭
// 이름은 정상 복원돼야 한다. 이 배선 전에는 그 Term 하나가 창 apply 전체를 실패시켜 **탭·split·창 frame까지 잃었다**
// (실측 사고: host runtime 12개가 사라지자 탭 9개가 통째로 날아갔다). 터미널에서 왜 중요한가 — 세션 이어하기는 못
// 해도 사용자가 손으로 만든 작업 공간 구조는 남아야 하고, 그게 이 기능의 전부다.
// 격리: `sessionCacheBase`가 `XDG_CACHE_HOME`을 먼저 읽으므로 빈 디렉터리로 박아 "그 host_id는 어디에도 없다"를
// 결정적으로 만든다. 실 캐시를 보게 두면 개발 머신에 살아 있는 host 유무로 결과가 갈려 flaky해진다. 그 격리 경로는
// **짧아야 한다**: 이 base 아래로 유닉스 소켓 경로가 만들어지고 `Client.connectMajor`가 sun_path(104B) 초과를
// syscall 전에 `EndpointDenied`로 거부하므로(socketPathFits), `std.testing.tmpDir`(=`<cwd>/.zig-cache/tmp/<hash>`)를
// 쓰면 **체크아웃 경로 길이에 따라** host_gone 대신 endpoint_denied가 나 이 테스트가 red가 된다(로컬 macOS 실측).
// host_connect의 host_gone 테스트와 같은 `/tmp/<이름>-<pid>` 규율을 쓴다.
test "종료 placeholder 복원: runtime 없는 Term만 묘비가 되고 탭·split 구조는 살아남는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const a = std.testing.allocator;

    var xdg_buf: [64]u8 = undefined;
    const xdg = std.fmt.bufPrintZ(&xdg_buf, "/tmp/maru-tomb-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
    _ = std.c.mkdir(xdg.ptr, 0o700);
    defer _ = std.c.rmdir(xdg.ptr); // 이 경로 아래엔 아무것도 안 만든다(복원은 조회만 한다) — 빈 디렉터리 정리.
    // 이전 값 보존(고정 버퍼 — defer에서 할당하지 않으려고). 다른 테스트의 캐시 경로를 오염시키지 않는다.
    var prev_buf: [std.fs.max_path_bytes]u8 = undefined;
    var prev_len: usize = 0;
    var had_prev = false;
    if (std.c.getenv("XDG_CACHE_HOME")) |p| {
        const s = std.mem.span(p);
        if (s.len < prev_buf.len) {
            @memcpy(prev_buf[0..s.len], s);
            prev_buf[s.len] = 0;
            prev_len = s.len;
            had_prev = true;
        }
    }
    try std.testing.expectEqual(@as(c_int, 0), setenv("XDG_CACHE_HOME", xdg.ptr, 1));
    defer if (had_prev) {
        _ = setenv("XDG_CACHE_HOME", prev_buf[0..prev_len :0].ptr, 1);
    } else {
        _ = unsetenv("XDG_CACHE_HOME");
    };

    const session = try initSmokeSessionSized(a);
    defer a.destroy(session);
    defer session.deinit();

    // 재접속 게이트는 keep-alive가 켜져 있을 때만 열린다 — 꺼져 있으면 identity를 무시하고 평범히 spawn한다.
    const prev_keep = app_keep_alive_after_quit;
    app_keep_alive_after_quit = true;
    defer app_keep_alive_after_quit = prev_keep;
    const prev_host_connect_failed = host_connect_failed;
    defer host_connect_failed = prev_host_connect_failed;

    var arena = std.heap.ArenaAllocator.init(a);
    defer arena.deinit();
    var win = try session.captureWorkspaceWindow(arena.allocator(), false, null);
    // 한 pane에 두 surface: handle 없는 것(선언적 restore → 평범한 spawn)과 사라진 host handle(→ 묘비).
    const surfaces = [_]maru.session.workspace.Surface{
        .{ .title = "살아있는", .cwd = "/tmp", .command = "/bin/zsh", .cols = 80, .rows = 24 },
        .{
            .title = "끝난 세션",
            .cwd = "/tmp",
            .command = "/bin/zsh",
            .runtime_host_id = "1234567890abcdef1234567890abcdef", // 어느 registry에도 없는 host
            .runtime_id = "fedcba0987654321fedcba0987654321",
            .cols = 100,
            .rows = 30,
        },
    };
    const panes = [_]maru.session.workspace.Pane{.{ .surfaces = &surfaces }};
    const tree = [_]maru.session.workspace.TreeNode{.{ .leaf = 0 }};
    const tabs = [_]maru.session.workspace.Tab{.{ .tree = &tree, .panes = &panes, .custom_name = "복원됨" }};
    win.tabs = &tabs;

    // 핵심: apply가 **성공**한다(이전에는 여기서 error가 나 창이 teardown됐다).
    try session.applyWorkspaceWindow(win);

    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqualStrings("복원됨", session.tabs.items[0].custom_name.?);
    const pane = session.tabs.items[0].panes.items[0];
    try std.testing.expectEqual(@as(usize, 2), pane.terms.items.len); // 두 surface 다 살아남았다

    // handle 없는 surface는 평범한 라이브 Term이다(묘비로 오염되지 않았다).
    try std.testing.expect(!pane.terms.items[0].rt.ended_placeholder);
    try std.testing.expect(pane.terms.items[0].rt.live_initialized);
    // 사라진 host를 가리킨 surface만 묘비이고, 마지막 제목이 라벨 출처로 남았다.
    try std.testing.expect(pane.terms.items[1].rt.ended_placeholder);
    try std.testing.expect(!pane.terms.items[1].rt.live_initialized);
    try std.testing.expectEqualStrings("끝난 세션", pane.terms.items[1].auto_title.items);
    try std.testing.expectEqualStrings("/tmp", pane.terms.items[1].rt.observation.cwd.items);

    // 사용자에게 한 번 알린다 — 알리지 않으면 탭은 돌아왔는데 일부 pane이 빈 이유를 알 수 없다.
    try std.testing.expectEqual(@as(u32, 1), session.ended_placeholder_notice_pending);
    session.showPendingEndedPlaceholderNotice();
    try std.testing.expectEqual(@as(u32, 0), session.ended_placeholder_notice_pending); // self-gate: 두 번 안 띄운다

    // code-review(max): durable wire가 exact handle을 보존해도 첫 영구 부재 판정이 오분류일 수 있다. Recovered Sessions
    // UI 전에는 되돌릴 경로가 없으므로 첫 live→ended 전이만 마지막 완전본 .bak 신호를 세운다.
    try std.testing.expectEqual(@as(u32, 1), session.takeWorkspaceRestoreDropped());
    // 같은 죽은 host를 가리키는 다음 surface는 blocking backoff(10×20ms)를 되풀이하지 않는다 — negative memo가 남는다.
    try std.testing.expectEqual(@as(u128, 0x1234_5678_90ab_cdef_1234_5678_90ab_cdef), session.restore_gone_host_id);
}

// §7 종료 placeholder(묘비) **객체가 통과하는 모든 관문**을 못박는다. 묘비는 지금까지 없던 조합이다 —
// `kind == .terminal`(렌더는 해야 하므로)이면서 `live_initialized == false`, `handle == 0`, `remote == null`,
// registry 슬롯은 web arm sentinel. 기존 분기들은 "PTY 없음"을 `kind == .web`으로만 표현했기 때문에, 이 조합은
// 조건에 명시하지 않으면 **어느 분기도 타지 않는다**. 터미널에서 왜 중요한가: 각 관문의 누락은 조용한 손실로
// 나타난다 — teardown 누락은 registry 슬롯 누수, `allTabsTerminated` 누락은 **묘비만 남은 창이 자동으로 닫혀 복원한
// 탭·split·frame이 다음 checkpoint에서 영구 소멸**, resize 누락은 창 크기 조정 전체 실패(half-state), reap 누락은
// 사용자 확인 없는 탭 닫힘. 그래서 복원 배선(후속) 전에 이 관문들을 먼저 고정한다.
test "종료 placeholder: teardown·세션 종료 판정·resize·reap 관문을 모두 통과한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const pane = session.activePane();
    const live_term = pane.activeTerm();
    const before_slots = session.live_registry.count();

    const tomb = try session.createEndedPlaceholderTerm("빌드 로그", "/tmp", "/bin/zsh", .{ .cols = 80, .rows = 24 }, "", "");
    try pane.terms.append(allocator, tomb);

    // 정체성: kind는 .terminal이라 렌더 경로가 그대로 돌고, PTY 계열은 전부 미할당이다.
    try std.testing.expectEqual(maru.session.control_surface.SurfaceKind.terminal, tomb.kind);
    try std.testing.expect(tomb.rt.ended_placeholder);
    try std.testing.expect(!tomb.rt.live_initialized);
    try std.testing.expectEqual(@as(app.TermRuntimeHandle, 0), tomb.rt.handle);
    try std.testing.expect(tomb.surface.remote == null);
    // 마지막 알려진 값이 owned로 심겼다(파싱 arena가 해제돼도 유효해야 한다).
    try std.testing.expectEqualStrings("빌드 로그", tomb.auto_title.items);
    try std.testing.expectEqualStrings("/tmp", tomb.rt.observation.cwd.items);
    try std.testing.expectEqualStrings("/bin/zsh", tomb.rt.ended_command);

    // 관문 1: 살아 있는 Term이 죽어도 묘비가 있으면 세션을 끝내지 않는다. 이게 없으면 창이 닫히고 레이아웃이 사라진다.
    live_term.rt.terminated = true;
    try std.testing.expect(!session.allTabsTerminated());
    // 관문 2: 자동 reap 후보가 아니다(사용자 확인 없이 닫히면 안 된다).
    live_term.rt.terminated = false;
    tomb.rt.terminated = true; // 방어적 이중화 검증 — terminated로 표시돼도 reap 대상이 아니어야 한다
    try std.testing.expect(session.findTerminatedTerm() == null);
    tomb.rt.terminated = false;

    // 관문 3: 활성 묘비에서 resize()가 실패하지 않고 sentinel core가 실제로 커진다(1×1에 갇히면 안내가 한 칸만 보이고
    // 그 크기가 checkpoint에 저장돼 복원마다 열화된다).
    session.focusTerm(pane.terms.items.len - 1);
    _ = try session.resize(1200, 800, 1000);
    try std.testing.expect(tomb.surface.core.size.cols > 2);
    try std.testing.expect(tomb.surface.core.size.rows > 1);

    // 관문 4: 읽기 전용 — 드롭은 무동작이고 이미지는 consumed로 삼켜 Swift 텍스트 fallback이 PTY로 새지 않게 한다.
    session.handleDroppedFiles("/tmp/x.txt\x00");
    try std.testing.expect(session.handleDroppedImage("\x89PNG"));

    // 관문 5: teardown이 registry 슬롯을 회수한다(누락하면 testing.allocator가 누수로 잡는다). 슬롯 수가 생성 전으로
    // 돌아오는지까지 본다 — remove가 아니라 destroy만 됐으면 여기서 어긋난다.
    session.focusTerm(0);
    _ = pane.terms.pop();
    session.destroyTerm(tomb);
    try std.testing.expectEqual(before_slots, session.live_registry.count());
}

// 이미 durable tombstone으로 저장된 surface는 host의 생사와 keep-alive 설정을 다시 묻지 않는다. 이 테스트의 handle은
// 어떤 registry에도 없으므로 일반 live 복원 경로에 들어가면 attach/spawn 결과가 달라진다. 직접 placeholder가 되고
// dropped 신호가 0인 사실이 두 번째 이후 relaunch의 side-effect 0 계약을 고정한다.
test "durable tombstone restore는 attach와 spawn 없이 placeholder를 직접 복원한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    var win = try session.captureWorkspaceWindow(arena.allocator(), false, null);
    const surfaces = [_]maru.session.workspace.Surface{.{
        .title = "이미 끝난 세션",
        .cwd = "/tmp",
        .command = "/bin/zsh",
        .runtime_host_id = "1234567890abcdef1234567890abcdef",
        .runtime_id = "fedcba0987654321fedcba0987654321",
        .runtime_state = .ended,
        .cols = 100,
        .rows = 30,
    }};
    const panes = [_]maru.session.workspace.Pane{.{ .surfaces = &surfaces }};
    const tree = [_]maru.session.workspace.TreeNode{.{ .leaf = 0 }};
    const tabs = [_]maru.session.workspace.Tab{.{ .tree = &tree, .panes = &panes }};
    win.tabs = &tabs;

    session.restore_runtime_host_id = "restore-spawn-sentinel";
    session.restore_runtime_id = "restore-spawn-sentinel";
    try session.applyWorkspaceWindow(win);
    const tomb = session.tabs.items[0].panes.items[0].terms.items[0];
    try std.testing.expect(tomb.rt.ended_placeholder);
    try std.testing.expect(!tomb.rt.live_initialized);
    try std.testing.expectEqualStrings(surfaces[0].runtime_host_id, tomb.rt.ended_runtime_host_id);
    try std.testing.expectEqualStrings(surfaces[0].runtime_id, tomb.rt.ended_runtime_id);
    try std.testing.expectEqual(@as(u32, 0), session.takeWorkspaceRestoreDropped());
    // restoreSpawn이 호출되면 이 임시 채널은 surface handle로 덮였다가 clear된다. sentinel 유지가 tombstone branch가
    // attach/probe/spawn 공통 진입점보다 앞에서 끝났음을 직접 증명한다.
    try std.testing.expectEqualStrings("restore-spawn-sentinel", session.restore_runtime_host_id);
    try std.testing.expectEqualStrings("restore-spawn-sentinel", session.restore_runtime_id);

    var captured_arena = std.heap.ArenaAllocator.init(allocator);
    defer captured_arena.deinit();
    const captured = try session.captureWorkspaceWindow(captured_arena.allocator(), false, null);
    const saved = captured.tabs[0].panes[0].surfaces[0];
    try std.testing.expectEqual(maru.session.workspace.RuntimeState.ended, saved.runtime_state);
    try std.testing.expectEqualStrings(surfaces[0].runtime_host_id, saved.runtime_host_id);
    try std.testing.expectEqualStrings(surfaces[0].runtime_id, saved.runtime_id);

    // capture→wire→parse→새 AppSession restore를 한 번 더 반복한다. 두 번째 cycle도 exact identity, spawn 경계 0,
    // dropped 0이어야 durable이라는 이름이 성립한다.
    const text = try maru.session.workspace.serialize(captured_arena.allocator(), .{ .windows = &.{captured} });
    var parsed = try maru.session.workspace.parse(captured_arena.allocator(), text);
    defer parsed.deinit();
    const second = try initSmokeSessionSized(allocator);
    defer allocator.destroy(second);
    defer second.deinit();
    second.restore_runtime_host_id = "second-cycle-sentinel";
    second.restore_runtime_id = "second-cycle-sentinel";
    try second.applyWorkspaceWindow(parsed.workspace.windows[0]);
    const second_tomb = second.tabs.items[0].panes.items[0].terms.items[0];
    try std.testing.expect(second_tomb.rt.ended_placeholder);
    try std.testing.expectEqualStrings(surfaces[0].runtime_host_id, second_tomb.rt.ended_runtime_host_id);
    try std.testing.expectEqualStrings(surfaces[0].runtime_id, second_tomb.rt.ended_runtime_id);
    try std.testing.expectEqualStrings("second-cycle-sentinel", second.restore_runtime_host_id);
    try std.testing.expectEqualStrings("second-cycle-sentinel", second.restore_runtime_id);
    try std.testing.expectEqual(@as(u32, 0), second.takeWorkspaceRestoreDropped());
}

test "legacy bare runtime-id Gone은 host 없는 tombstone으로 승격하지 않는다" {
    try std.testing.expectError(
        error.PersistentRuntimeUnavailable,
        AppSession.restoreFailureDisposition(error.PersistentRuntimeGone, false),
    );
    try std.testing.expectEqual(
        AppSession.RestoreFailureDisposition.ended,
        try AppSession.restoreFailureDisposition(error.PersistentRuntimeGone, true),
    );
    try std.testing.expectError(
        error.PersistentRuntimeUnavailable,
        AppSession.restoreFailureDisposition(error.PersistentRuntimeUnavailable, true),
    );

    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // production apply가 쓰는 동일 snapshot/record/restore 조합으로 newly-Gone의 두 counter가 함께 rollback되는지 고정한다.
    const accounting = AppSession.RestoreAccountingSnapshot.capture(session);
    session.recordEndedPlaceholder(true);
    try std.testing.expectEqual(@as(u32, 1), session.ended_placeholder_notice_pending);
    try std.testing.expectEqual(@as(u32, 1), session.ended_placeholder_dropped_pending);
    accounting.restore(session);
    try std.testing.expectEqual(@as(u32, 0), session.ended_placeholder_notice_pending);
    try std.testing.expectEqual(@as(u32, 0), session.ended_placeholder_dropped_pending);

    const prev_keep = app_keep_alive_after_quit;
    app_keep_alive_after_quit = true;
    defer app_keep_alive_after_quit = prev_keep;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    var win = try session.captureWorkspaceWindow(arena.allocator(), false, null);
    const surfaces = [_]maru.session.workspace.Surface{.{
        .runtime_id = "fedcba0987654321fedcba0987654321",
        .cols = 80,
        .rows = 24,
    }};
    const panes = [_]maru.session.workspace.Pane{.{ .surfaces = &surfaces }};
    const tree = [_]maru.session.workspace.TreeNode{.{ .leaf = 0 }};
    const tabs = [_]maru.session.workspace.Tab{.{ .tree = &tree, .panes = &panes }};
    win.tabs = &tabs;

    try std.testing.expectError(error.PersistentRuntimeUnavailable, session.applyWorkspaceWindow(win));
    try std.testing.expectEqual(@as(u32, 0), session.ended_placeholder_notice_pending);
    try std.testing.expectEqual(@as(u32, 0), session.ended_placeholder_dropped_pending);
}

// 묘비가 **다시 저장될 때** 마지막 title·cwd·grid와 exact runtime-handle을 함께 보존하는지 못박는다.
// 순진한 구현은 두 곳에서 조용히 망가진다. (1) capture는 title/cwd를 `rt.observation`에서만 읽는데
// `refreshTermObservation`이 `!live_initialized`에 즉시 반환하므로, seed가 없으면 observation이 기본 `.unavailable`로
// 남아 **빈 문자열로 저장**된다 — 묘비의 존재 이유(마지막 제목·위치)가 첫 Quit에 사라진다. (2) core가 sentinel
// 1×1이면 그 크기가 저장돼 다음 복원에서 `clampGridSize`가 2×1 셸을 만든다(사이클마다 레이아웃 열화).
// handle을 버리면 다음 실행이 선언적 surface로 오인해 사용자가 Enter를 누르지 않았는데도 새 셸을 spawn한다.
test "종료 placeholder: capture가 metadata와 durable runtime tombstone을 보존한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const pane = session.activePane();
    const tomb = try session.createEndedPlaceholderTerm(
        "배포 감시",
        "/tmp",
        "/bin/zsh",
        .{ .cols = 100, .rows = 30 },
        "1234567890abcdef1234567890abcdef",
        "fedcba0987654321fedcba0987654321",
    );
    try pane.terms.append(allocator, tomb);
    defer {
        _ = pane.terms.pop();
        session.destroyTerm(tomb);
    }

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const win = try session.captureWorkspaceWindow(arena.allocator(), false, null);
    const surfaces = win.tabs[0].panes[0].surfaces;
    try std.testing.expectEqual(@as(usize, 2), surfaces.len); // 살아 있는 Term + 묘비 — 묘비는 스킵되지 않는다
    const saved = surfaces[1];

    try std.testing.expectEqualStrings("배포 감시", saved.title);
    try std.testing.expectEqualStrings("/tmp", saved.cwd);
    try std.testing.expectEqualStrings("/bin/zsh", saved.command);
    try std.testing.expect(saved.cols > 2 and saved.rows > 1); // sentinel 1×1이 그대로 새어 나오지 않는다
    try std.testing.expectEqualStrings("1234567890abcdef1234567890abcdef", saved.runtime_host_id);
    try std.testing.expectEqualStrings("fedcba0987654321fedcba0987654321", saved.runtime_id);
    try std.testing.expectEqual(maru.session.workspace.RuntimeState.ended, saved.runtime_state);

    // 직렬화 왕복까지 exact handle/state가 함께 남아야 두 번째 이후 relaunch도 side effect 없이 묘비로 복원된다.
    const text = try maru.session.workspace.serialize(arena.allocator(), .{ .windows = &.{win} });
    try std.testing.expect(std.mem.indexOf(
        u8,
        text,
        "runtime-handle=\"1234567890abcdef1234567890abcdef:fedcba0987654321fedcba0987654321\" runtime-state=\"ended\"",
    ) != null);
    var parsed = try maru.session.workspace.parse(arena.allocator(), text);
    defer parsed.deinit();
    const round = parsed.workspace.windows[0].tabs[0].panes[0].surfaces[1];
    try std.testing.expectEqualStrings("배포 감시", round.title);
    try std.testing.expectEqualStrings("/tmp", round.cwd);
    try std.testing.expectEqual(maru.session.workspace.RuntimeState.ended, round.runtime_state);
}

// attach 실패의 **영구/일시 분류표**를 순수 함수 수준에서 못박는다. 이 분류 하나가 "저장된 세션을 종료 placeholder로
// 버릴지, 창 복원을 실패시켜 다시 시도할 여지를 남길지"를 가르므로, 오분류 비용이 심하게 비대칭이다: 영구를 일시로
// 보면 창 복원이 한 번 실패할 뿐이지만, **일시를 영구로 보면 살아 있는 셸·빌드·SSH가 placeholder로 굳어** 사용자가
// 되찾을 길이 사라진다(§7 접속 실패 행렬). 그래서 영구 승격은 "다시는 붙을 수 없다는 증거가 있는 셋"으로 못박고,
// 나머지는 전부 fail-closed로 남는지 대조군까지 검사한다(전부 Gone인 구현이 통과하지 못하게).
test "classifyAttachError: 영구 없음만 Gone으로 올리고 일시 실패는 fail-closed로 남긴다" {
    // 다시는 붙을 수 없다는 증거 — host가 그 runtime을 모른다 / stale handle이라고 응답 / pool 슬롯이 다른 host로 교체.
    try std.testing.expectEqual(error.PersistentRuntimeGone, AppSession.classifyAttachError(error.RuntimeNotFound));
    try std.testing.expectEqual(error.PersistentRuntimeGone, AppSession.classifyAttachError(error.StaleHostHandle));
    try std.testing.expectEqual(error.PersistentRuntimeGone, AppSession.classifyAttachError(error.HostIdentityMismatch));

    // host나 runtime이 살아 있을 수 있는 것들 — 영구로 승격하면 안 된다.
    try std.testing.expectEqual(error.PersistentRuntimeUnavailable, AppSession.classifyAttachError(error.ConnectionClosed));
    try std.testing.expectEqual(error.PersistentRuntimeUnavailable, AppSession.classifyAttachError(error.WriteFailed));
    try std.testing.expectEqual(error.PersistentRuntimeUnavailable, AppSession.classifyAttachError(error.AttachFailed));
    try std.testing.expectEqual(error.PersistentRuntimeUnavailable, AppSession.classifyAttachError(error.HostNotFound));
    try std.testing.expectEqual(error.PersistentRuntimeUnavailable, AppSession.classifyAttachError(error.SpawnHostUnavailable));
    try std.testing.expectEqual(error.PersistentRuntimeUnavailable, AppSession.classifyAttachError(error.RuntimeAlreadyRegistered));

    // OOM은 host에 대한 증거가 아니라 우리 쪽 사정이라 그대로 전파한다(원인을 host 상태로 오해하지 않게).
    try std.testing.expectEqual(error.OutOfMemory, AppSession.classifyAttachError(error.OutOfMemory));
}

// P3-e3-5 재접속 통합 스모크 — restore가 저장한 runtime_id로 createTerm이 **spawn 대신 attach**해 기존 host runtime에
// 재접속하는지 고정한다(§7). "이전 실행"을 raw runtime.spawn(controller 없는 runtime)으로 흉내 내고, 그 runtime_id를
// restore_runtime_id에 실어 createTerm을 부르면 새 Term이 그 runtime에 붙어야 한다(fresh spawn이면 다른 runtime_id).
// 실 fork host + 실 AppSession이라 macOS 게이트. 실제 "껐다 켜서 재접속" full E2E는 e3-6(종료 후 생존) 후 OS E2E.
test "P3-e3-5 재접속: restore_runtime_id로 createTerm이 기존 host runtime에 attach한다" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-e3-rc-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        session.loaded_config.config.session.keep_alive_after_quit = true;
        app_keep_alive_after_quit = true;

        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, session.runtime);
        defer {
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        // "이전 실행"이 남긴 host runtime 하나(controller 없이 raw spawn) — workspace가 이 runtime_id를 저장했다고 본다.
        const spawn_resp = try app_remote_client.?.call("runtime.spawn", "{\"argv\":[\"/bin/cat\"],\"cols\":40,\"rows\":10}");
        defer allocator.free(spawn_resp);
        const prev_rid = session_host.client.extractRuntimeId(spawn_resp) orelse {
            try std.testing.expect(false);
            return;
        };

        var current_host_buf: [32]u8 = undefined;
        const current_host = std.fmt.bufPrint(&current_host_buf, "{x:0>32}", .{app_remote_client.?.host_id}) catch unreachable;

        // 다른 host namespace의 handle은 같은 runtime_id가 우연히 있어도 fresh spawn으로 위장하지 않고 실패한다.
        // host_id=0은 손상 입력이므로 **일시 실패(Unavailable)로 남는다** — 영구로 승격하면 손상 파일 하나가 살아 있는
        // 세션을 종료 placeholder로 버리게 된다.
        session.restore_runtime_host_id = "00000000000000000000000000000000";
        session.restore_runtime_id = &prev_rid;
        try std.testing.expectError(
            error.PersistentRuntimeUnavailable,
            session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat"),
        );

        // 살아 있는 host가 "그 runtime을 모른다"고 응답하면(runtime_not_found) 그 handle은 다시는 붙을 수 없다 →
        // PersistentRuntimeGone. 위 Unavailable과 갈라야 caller가 **그 Term만** 종료 placeholder로 두고 나머지 레이아웃을
        // 살릴 수 있다(§7 접속 실패 행렬). 둘을 한 에러로 뭉개면 일시 장애에도 살아 있는 세션을 버리게 된다.
        // 이 경로는 host RPC 응답의 error envelope까지 실제로 왕복한다(legacy attach → attachExisting → runtime.attach).
        var absent_rid: [32]u8 = "0123456789abcdef0123456789abcdef".*; // 유효 hex지만 이 host에 spawn된 적 없다
        session.restore_runtime_host_id = current_host;
        session.restore_runtime_id = &absent_rid;
        try std.testing.expectError(
            error.PersistentRuntimeGone,
            session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat"),
        );

        // restore가 identity 쌍을 세우고 createTerm을 부른다 → spawn 대신 그 runtime에 **attach**(재접속).
        // current host 연결 실패 상태에서는 createTerm 초입의 backendForNew가 local을 고른다. 복원 중 발견한 remote
        // owner로 후속 attach/config/pump가 다시 결합돼야 하며, stale local backend면 UnknownSurface로 rollback된다.
        host_connect_failed = true;
        defer host_connect_failed = false;
        session.restore_runtime_host_id = current_host;
        session.restore_runtime_id = &prev_rid;
        const term = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        host_connect_failed = false;
        try std.testing.expect(term.surface.remote != null); // host-backed
        // **재접속 확인**: 새 Term이 저장된 runtime_id에 붙었다(fresh spawn이면 다른 id였을 것).
        const attached_rid = app_remote_backend.?.runtimeIdFor(term.rt.handle) orelse {
            try std.testing.expect(false);
            return;
        };
        try std.testing.expectEqual(prev_rid, attached_rid);
        // restore identity는 읽고 즉시 클리어됐다(다음 createTerm은 일반 spawn).
        try std.testing.expectEqualStrings("", session.restore_runtime_host_id);
        try std.testing.expectEqualStrings("", session.restore_runtime_id);

        // workspace staging rollback을 흉내 낸다. 아직 commit 전(restored_existing=true) destroy는 기존 runtime을
        // terminate하지 않고 detach만 해야 한다. 같은 runtime에 다시 붙으면 실제 host 생존이 증명된다.
        session.destroyTerm(term);
        var rollback_probe: session_host.remote_runtime.RemoteRuntime = undefined;
        try rollback_probe.attachExisting(&app_remote_client.?, allocator, io, 99, prev_rid, .{ .cols = 40, .rows = 10 });
        rollback_probe.deinit(); // 검증 끝 — 이제 terminate로 host runtime 정리.
    } else {
        return error.SkipZigTest;
    }
}

// P3-e3-6 앱-quit 생존 통합 스모크 — **앱 종료(app_quitting)** 시 deinit이 host-backed Term을 terminate 대신 detach해 host
// runtime이 살아남고, 연결을 닫았다(프로세스 종료 흉내) 다시 붙으면 그 runtime에 재접속되는지 고정한다(§6 app-quit=detach,
// §9 EOF=runtime 유지). "GUI를 강제종료해도 터미널 생존 + 재접속"의 최종 검증. 실 fork host + 실 AppSession이라 macOS 게이트.
test "P3-e3-6 app-quit: host-backed Term을 detach해 host runtime이 생존하고 재접속된다" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-e3-q-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        // 앱 전역 원격 backend를 **session.init 전에** 세운다 → session.init의 첫 탭이 host-backed로 뜬다(controlled_smoke의
        // /bin/sh는 `read`로 블록해 살아 있다). surface_runtime은 앱 전역 routing(session.runtime과 같다).
        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, &app_runtime.routing);
        defer { // 테스트 격리: 앱 전역 상태 리셋(명시 close 뒤엔 null이라 skip).
            app_quitting = false;
            app_quit_keep_alive = false;
            app_quit_end_all = false;
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        const first = try appendTrackedRemoteTermForTest(session);
        try std.testing.expect(first.surface.remote != null); // 첫 탭이 host-backed(backend가 init 전에 세워짐)
        const rid = app_remote_backend.?.runtimeIdFor(first.rt.handle) orelse {
            try std.testing.expect(false);
            return;
        };

        // **앱 quit**: deinit이 host-backed Term을 terminate 대신 detach한다(runtime 생존).
        app_quit_keep_alive = true;
        app_quitting = true;
        session.deinit();

        // 연결을 닫아 프로세스 종료를 흉내 낸다 → host가 이 connection subscription을 detach하고 **runtime은 유지**한다(§9).
        // (명시 close라 아래 defer의 reset은 null 확인으로 skip.)
        if (app_remote_backend) |*rb| {
            rb.deinit();
            app_remote_backend = null;
        }
        if (app_remote_client) |*cl| {
            cl.deinit();
            app_remote_client = null;
        }

        // **재실행 흉내**: 새 연결로 그 runtime_id에 재접속되면 = 생존 증명(terminate였으면 host RuntimeNotFound → AttachFailed).
        var client2 = session_host.client.Client.connect(allocator, socket, .gui) catch {
            try std.testing.expect(false);
            return;
        };
        defer client2.deinit();
        var rr: session_host.remote_runtime.RemoteRuntime = undefined;
        try rr.attachExisting(&client2, allocator, io, 1, rid, .{ .cols = 40, .rows = 10 }); // 생존한 runtime에 재접속 성공!
        rr.deinit(); // 검증 끝 — 이제 terminate로 정리.
    } else {
        return error.SkipZigTest;
    }
}

// R1 회귀(code-review #2) — 앱 quit(detach) 시 **창 teardown 진입점 `close()`가 deinit보다 먼저** 돈다. e3-6 스모크는 quit을
// deinit 직접 호출로만 모델링해 close() 경로를 안 탔고, close()엔 detach 게이트가 없어 host-backed runtime을 terminate했다
// (생존 계약 조용히 실패). 이 스모크는 quit 중 close()→deinit 순서를 그대로 태워 runtime이 그래도 생존·재접속되는지 고정한다.
test "R1: app-quit 중 close()가 먼저 돌아도 host-backed runtime이 생존한다(재접속 성공)" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-r1-cl-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, &app_runtime.routing);
        defer {
            app_quitting = false;
            app_quit_keep_alive = false;
            app_quit_end_all = false;
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        const first = try appendTrackedRemoteTermForTest(session);
        try std.testing.expect(first.surface.remote != null);
        const rid = app_remote_backend.?.runtimeIdFor(first.rt.handle) orelse {
            try std.testing.expect(false);
            return;
        };

        // **앱 quit** 순서를 실제대로: 먼저 창 teardown(close), 그다음 struct deinit. close()에 게이트가 없으면 여기서 이미
        // terminate돼 아래 재접속이 AttachFailed로 깨진다.
        app_quit_keep_alive = true;
        app_quitting = true;
        _ = session.close();
        session.deinit();

        // 연결을 닫아 프로세스 종료 흉내 → host는 runtime 유지(§9).
        if (app_remote_backend) |*rb| {
            rb.deinit();
            app_remote_backend = null;
        }
        if (app_remote_client) |*cl| {
            cl.deinit();
            app_remote_client = null;
        }

        // 재실행 흉내: 새 연결로 그 runtime_id에 재접속 → 성공하면 close()가 terminate 안 했다는 증명.
        var client2 = session_host.client.Client.connect(allocator, socket, .gui) catch {
            try std.testing.expect(false);
            return;
        };
        defer client2.deinit();
        var rr: session_host.remote_runtime.RemoteRuntime = undefined;
        try rr.attachExisting(&client2, allocator, io, 1, rid, .{ .cols = 40, .rows = 10 }); // close()를 태워도 생존!
        rr.deinit();
    } else {
        return error.SkipZigTest;
    }
}

// ① 재접속 직후 스크롤 회귀(host-alive robustness) — host-backed 터미널은 재접속 직후 첫 `runtime.observation` metadata가
// 도착하기 전 ~0.5s 동안 `observation.availability == .unavailable`이다. 예전 scrollSurfaceLines는 이 창에서 hard-return이라
// **평범한 스크롤백(host view_offset — 관측이 필요 없음)까지 죽어** 재접속 직후 스크롤이 완전히 먹통이었다. 이 스모크는
// 관측 미가용 상태에서도 스크롤이 core `.scroll`을 enqueue(→ metal_dirty)하는지 고정한다 — alt-screen 판정만 스킵하고
// scrollback은 진행하는 게 계약이다. 실 fork host + 실 AppSession(host-backed createTerm)이라 macOS 게이트.
test "① host-backed 스크롤은 observation 미가용(재접속 직후)에도 scrollback을 enqueue한다" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-scr-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, &app_runtime.routing);
        const previous_keep_alive = app_keep_alive_after_quit;
        defer {
            app_keep_alive_after_quit = previous_keep_alive;
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();

        const term = try appendTrackedRemoteTermForTest(session);
        try std.testing.expect(term.surface.remote != null); // host-backed

        // **재접속 직후 창 재현**: 첫 metadata 도착 전이라 관측 미가용. (createTerm의 attach barrier가 채웠을 수 있어 명시 강제.)
        term.rt.observation.availability = .unavailable;

        // scrollback은 관측이 필요 없다 → 미가용이어도 core `.scroll`을 enqueue하고 metal_dirty를 세워야 한다.
        // pre-fix는 여기서 hard-return이라 metal_dirty가 false로 남아 red. post-fix는 alt 판정만 스킵하고 fall-through해 green.
        session.metal_dirty = false;
        session.scrollSurfaceLines(term.surface, 3);
        try std.testing.expect(session.metal_dirty);
    } else {
        return error.SkipZigTest;
    }
}

test "persistent session quit policy: setting off terminates instead of detaching remote runtime" {
    if (!is_macos) return error.SkipZigTest;

    const previous_quitting = app_quitting;
    const previous_keep_alive = app_quit_keep_alive;
    const previous_end_all = app_quit_end_all;
    defer {
        app_quitting = previous_quitting;
        app_quit_keep_alive = previous_keep_alive;
        app_quit_end_all = previous_end_all;
    }

    var session: AppSession = undefined;
    // 이 순수 정책 테스트가 읽는 AppSession 필드는 is_quick 하나다. ReleaseFast에서 undefined
    // 값을 읽으면 UB 최적화로 분기가 비결정적이므로 필요한 projection을 명시적으로 초기화한다.
    session.is_quick = false;
    var surface: maru.session.Surface = undefined;
    surface.remote = .{ .ctx = @ptrFromInt(1), .vtable = @ptrFromInt(@alignOf(maru.session.surface.ScreenSource.VTable)) };
    var term: Term = .{};
    term.surface = &surface;

    app_quitting = true;
    app_quit_end_all = false;
    app_quit_keep_alive = true;
    try std.testing.expect(session.shouldDetachRemoteOnAppQuit(&term));

    app_quit_keep_alive = false;
    try std.testing.expect(!session.shouldDetachRemoteOnAppQuit(&term));

    app_quit_keep_alive = true;
    app_quit_end_all = true;
    try std.testing.expect(!session.shouldDetachRemoteOnAppQuit(&term));

    app_quit_end_all = false;
    session.is_quick = true;
    try std.testing.expect(!session.shouldDetachRemoteOnAppQuit(&term));
}

test "persistent session policy: a stale second-window config cannot overwrite the app-wide toggle" {
    const previous_value = app_keep_alive_after_quit;
    const previous_initialized = app_keep_alive_policy_initialized;
    defer {
        app_keep_alive_after_quit = previous_value;
        app_keep_alive_policy_initialized = previous_initialized;
    }

    app_keep_alive_after_quit = false;
    app_keep_alive_policy_initialized = false;
    try std.testing.expect(!keepAlivePolicyForNewSession(false)); // 첫 Window가 디스크 config를 초기화한다.

    setAppKeepAlivePolicy(true); // Window A에서 토글했지만 아직 파일 write-back 전.
    try std.testing.expect(keepAlivePolicyForNewSession(false)); // stale false를 읽은 Window B가 전역 값을 되돌리지 못한다.
}

test "persistent session quit policy: cancelled late preflight clears accepted lifecycle latches" {
    const previous_quitting = app_quitting;
    const previous_keep_alive = app_quit_keep_alive;
    const previous_end_all = app_quit_end_all;
    defer {
        app_quitting = previous_quitting;
        app_quit_keep_alive = previous_keep_alive;
        app_quit_end_all = previous_end_all;
    }

    var session: AppSession = undefined;
    app_quitting = true;
    app_quit_keep_alive = true;
    app_quit_end_all = true;
    session.cancelAcceptedAppQuit();
    try std.testing.expect(!app_quitting);
    try std.testing.expect(!app_quit_keep_alive);
    try std.testing.expect(!app_quit_end_all);
}

// P4 "Quit and End All Sessions"(§6 종료 매트릭스 row 3) 통합 스모크 — 종료 확인의 **alternate**("종료 및 세션 끝내기")를
// 누르면 e3-6의 detach(생존)와 **반대로** host-backed runtime을 terminate한다(생존 안 함). 같은 셋업에서 detach 스모크는
// attachExisting 성공(생존), 이 end-all 스모크는 AttachFailed(종료)로 갈려 종료 gate의 두 분기를 함께 고정한다.
test "P4 Quit-End-All: alternate가 host-backed runtime을 terminate한다(재접속 실패)" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-p4-ea-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, &app_runtime.routing);
        defer {
            app_quitting = false;
            app_quit_end_all = false;
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        const first = try appendTrackedRemoteTermForTest(session);
        try std.testing.expect(first.surface.remote != null);
        const rid = app_remote_backend.?.runtimeIdFor(first.rt.handle) orelse {
            try std.testing.expect(false);
            return;
        };

        // 종료 확인 → **alternate**("종료 및 세션 끝내기"). host-backed가 살아 있어 3버튼 confirm이 뜬다(pending_confirm=.quit).
        session.requestAppQuit();
        session.dispatchChromeAction(.confirm_alternate);
        try std.testing.expect(app_quitting);
        try std.testing.expect(app_quit_end_all); // end-all 분기 선택됨.

        // deinit이 host-backed Term을 **terminate**한다(detach 아님).
        session.deinit();

        // 검증: 그 runtime_id에 재접속 시도 → **RuntimeNotFound**(host가 종료를 긍정적으로 응답). e3-6(detach) 생존과
        // 정반대다. 명시적으로 끝낸 세션이라 이 신호는 "영구 없음"이 맞다 — 복원이 그 Term을 종료 placeholder로 두는
        // 근거가 되고, 일시 장애(Unavailable)와 뭉개면 안 된다(§7 접속 실패 행렬).
        var rr2: session_host.remote_runtime.RemoteRuntime = undefined;
        try std.testing.expectError(error.RuntimeNotFound, rr2.attachExisting(&app_remote_client.?, allocator, io, 99, rid, .{ .cols = 40, .rows = 10 }));
    } else {
        return error.SkipZigTest;
    }
}

// 이 테스트가 증명하는 것(그리고 터미널에서 왜 중요한가): host 연결이 실패하면 그 세션의 터미널은 앱을 끄는 순간
// 함께 죽는다 — 사용자가 잃는 것은 작업 중이던 셸 전부다. 그런데 GUI 프로세스의 stdout/stderr는 `/dev/null`이라
// (Dock·Finder 실행) `std.log`가 어디에도 남지 않고, 통합 로그로도 가지 않는다. 실제로 이 실패를 추적할 때
// `log show`도 stderr도 전부 비어 있어 "왜 유지가 안 되는가"를 사후에 알 방법이 없었다. 그래서 실패 단계와 사유를
// 한 줄 문자열로 조립해 **화면 notice에 싣는 것**이 유일한 관측 경로다. 아래는 그 문자열이 단계 단독일 때와
// 단계+사유일 때 각각 어떤 모양인지, 버퍼가 모자라도 크래시 없이 식별 가능한 값으로 접히는지를 고정한다.
// 순수 함수라 실 PTY/CoreText 없이 non-macOS에서도 회귀를 잡는다.
test "host connect 실패 detail: 단계 단독과 단계+사유를 한 줄로 조립한다" {
    var buf: [96]u8 = undefined;
    try std.testing.expectEqualStrings("stage=exe_path", hostConnectFailureDetail(&buf, .exe_path, null, null));
    try std.testing.expectEqualStrings("stage=cache_base", hostConnectFailureDetail(&buf, .cache_base, null, null));
    // stage를 잃어도 "reason=null"로 세 가지 실패를 뭉개지 않고 unknown으로 구분해 남긴다.
    try std.testing.expectEqualStrings("stage=unknown", hostConnectFailureDetail(&buf, null, null, null));

    const reason: HostConnectFailureReason = if (is_macos) .launch_failed else .unavailable;
    var expected_buf: [96]u8 = undefined;
    const expected = try std.fmt.bufPrint(&expected_buf, "stage=connect reason={s}", .{@tagName(reason)});
    try std.testing.expectEqualStrings(expected, hostConnectFailureDetail(&buf, .connect, reason, null));
}

// 이 테스트가 증명하는 것(그리고 터미널에서 왜 중요한가): `runtime_death`는 **서로 완전히 다른 세 실패**를 한
// 단계로 묶는다 — host가 연결을 끊었거나(ConnectionClosed), 쓰기가 실패했거나(WriteFailed), host가 요청 계약을
// 모르거나(UnsupportedSpawnContract). 원인이 갈리는데 표시가 같으면 진단이 그 지점에서 멈춘다. 실제로 build_id가
// **완전히 일치하는** host에서도 이 단계가 재현됐고, 셋 중 무엇인지 몰라 더 좁힐 수 없었다. 그래서 error 이름을
// 함께 싣는다. reason과 error는 동시에 오지 않으므로(연결 단계냐 그 이후냐) 우선순위도 함께 고정한다.
test "session host 런타임 base는 캐시 경로 밖이며 socket과 같은 디렉터리다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    const runtime_base = AppSession.sessionHostRuntimeBase(a) orelse return error.SkipZigTest;

    // manifest/lock이 캐시 아래 있으면 **사용자가 캐시를 비우는 정상적인 행동만으로 살아 있는 세션을 전부 잃는다**.
    // host 프로세스는 남아 있어도 자기를 가리키는 manifest가 없으면 discovery가 발견하지 못하기 때문이다.
    if (AppSession.sessionCacheBase(a)) |cache_base| {
        try std.testing.expect(!std.mem.startsWith(u8, runtime_base, cache_base));
    }

    // 열쇠(manifest)와 자물쇠(socket)가 같은 디렉터리에 있어야 "한쪽만 사라지는" 실패 모드가 성립하지 않는다.
    var socket_buf: [128]u8 = undefined;
    const socket_dir = try session_host.short_endpoint.socketDirPathIn(&socket_buf, std.c.getuid());
    try std.testing.expect(std.mem.startsWith(u8, socket_dir, runtime_base));
}

test "host connect 실패 detail: runtime_death는 어떤 error였는지까지 남긴다" {
    var buf: [96]u8 = undefined;
    try std.testing.expectEqualStrings(
        "stage=runtime_death error=ConnectionClosed",
        hostConnectFailureDetail(&buf, .runtime_death, null, @errorName(error.ConnectionClosed)),
    );
    try std.testing.expectEqualStrings(
        "stage=runtime_death error=UnsupportedSpawnContract",
        hostConnectFailureDetail(&buf, .runtime_death, null, @errorName(error.UnsupportedSpawnContract)),
    );
    // error 없이 단계만 있으면 기존 형식 그대로다(회귀 방지).
    try std.testing.expectEqualStrings(
        "stage=runtime_death",
        hostConnectFailureDetail(&buf, .runtime_death, null, null),
    );
    // reason이 있으면 그쪽이 우선한다 — 연결 단계의 실패는 FailureReason이 더 구체적이다.
    const reason: HostConnectFailureReason = if (is_macos) .launch_failed else .unavailable;
    var expected_buf: [96]u8 = undefined;
    const expected = try std.fmt.bufPrint(&expected_buf, "stage=connect reason={s}", .{@tagName(reason)});
    try std.testing.expectEqualStrings(
        expected,
        hostConnectFailureDetail(&buf, .connect, reason, @errorName(error.WriteFailed)),
    );
}

// 진단 문자열 때문에 앱이 죽으면 본말전도다. 버퍼가 모자라면 panic·부분 출력 대신 식별 가능한 고정 값으로 접힌다.
test "host connect 실패 detail: 버퍼가 모자라면 크래시 대신 식별 가능한 값으로 접힌다" {
    var tiny: [4]u8 = undefined;
    try std.testing.expectEqualStrings("stage=unknown", hostConnectFailureDetail(&tiny, .connect, null, null));
    // error 이름이 붙어 더 길어지는 경로도 같은 규율로 접힌다.
    try std.testing.expectEqualStrings(
        "stage=unknown",
        hostConnectFailureDetail(&tiny, .runtime_death, null, @errorName(error.ConnectionClosed)),
    );
}

// P4 §6 L291 — keep-alive인데 host 연결이 실패하면 **조용히 in-process로 폴백하지 않고** 사용자에게 notice로 알린다("유지된다"
// 오인 방지). ensureRemoteBackend가 실패 시 세우는 host_connect_notice_pending을 흉내 내고, tick이 부르는
// showPendingHostConnectNotice가 notice를 한 번 띄우고 끄는지 고정한다. host 없이 순수 세션 상태만 검증(실 PTY/CoreText라
// macOS 게이트, 단 session_host.* 심볼은 안 써서 runtime skip으로 충분).
test "P4 keep-alive host 실패: notice pending이 사용자 notice로 표시되고 클리어된다(§6 L291)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // AppSession.init = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // ensureRemoteBackend가 host 연결 실패로 세우는 상태를 흉내 낸다.
    session.host_connect_notice_pending = true;
    try std.testing.expect(!session.chrome_host.notice.open); // 아직 안 뜸

    session.showPendingHostConnectNotice(); // tick이 부르는 것과 동일.
    try std.testing.expect(session.chrome_host.notice.open); // 사용자에게 "유지 안 됨" notice가 떴다(조용한 폴백 아님).
    try std.testing.expect(!session.host_connect_notice_pending); // 한 번 표시 후 클리어(매 tick 반복 안 함).
}

// P4 §6.32 GUI surfacing(code-review #10) — host-backed 터미널의 OSC 9/777 알림은 **host core**가 파싱하므로 client
// placeholder 코어엔 없다(#1523이 host→client 전달 RPC를 놓았다). 이 테스트는 pendingNotification이 그 host 알림을
// takeNotificationFor로 pull해 in-process와 **같은 GUI 알림 경로**(위치 접두·인앱 히스토리·PendingNotification)에 태우는지
// 고정한다 — takeNotification이 죽은 코드가 아니게 된다. 실 fork host에 /bin/cat 원격 Term을 탭에 넣고 OSC 777을 echo시킨다.
test "P4 §6.32: host-backed Term의 OSC 9/777 알림이 GUI 알림 경로로 surfacing된다(#10)" {
    if (is_macos) {
        const allocator = std.testing.allocator;
        const io = std.Io.Threaded.global_single_threaded.io();

        var base_buf: [96]u8 = undefined;
        const base = std.fmt.bufPrintZ(&base_buf, "/tmp/maru-p4-osc-{d}", .{std.c.getpid()}) catch return error.SkipZigTest;
        _ = std.c.mkdir(base.ptr, 0o700);
        var dir_buf: [160]u8 = undefined;
        const dir = session_host.discovery.sessionHostDirPath(&dir_buf, base) catch return error.SkipZigTest;
        var sock_buf: [224]u8 = undefined;
        const socket = session_host.discovery.socketPathIn(&sock_buf, dir) catch return error.SkipZigTest;

        const child = std.c.fork();
        if (child < 0) return error.SkipZigTest;
        if (child == 0) {
            _ = std.c.setsid();
            session_host.daemon.runSessionHost(std.heap.page_allocator, io, dir, socket) catch {};
            std.c._exit(0);
        }
        defer {
            _ = std.c.kill(child, std.posix.SIG.TERM);
            var status: c_int = undefined;
            _ = std.c.waitpid(child, &status, 0);
            _ = std.c.unlink(socket.ptr);
            var lpb: [224]u8 = undefined;
            if (session_host.discovery.lockPathIn(&lpb, dir)) |p| _ = std.c.unlink(p.ptr) else |_| {}
            _ = std.c.rmdir(dir.ptr);
            _ = std.c.rmdir(base.ptr);
        }

        var up = false;
        var w: usize = 0;
        while (w < 250) : (w += 1) {
            if (session_host.client.Client.connect(allocator, socket, .gui)) |cl| {
                var p = cl;
                p.deinit();
                up = true;
                break;
            } else |_| _ = usleep(20 * 1000);
        }
        try std.testing.expect(up);

        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(io, allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();

        // backend를 init **뒤**에 세워 첫 탭은 in-process로 두고(원격 Term은 아래 cat 하나만 — round-robin 단순화), cat을 host-backed로.
        const client = session_host.host_connect.connectOrLaunch(allocator, "/unused", base, .{ .connect_attempts = 30, .connect_delay_ms = 10 }) orelse {
            try std.testing.expect(false);
            return;
        };
        app_remote_client = client;
        app_remote_backend = session_host.remote_term_backend.RemoteTermBackend.init(allocator, io, &app_remote_client.?, session.runtime);
        defer {
            host_connect_failed = false;
            app_keep_alive_after_quit = false;
            if (app_remote_backend) |*rb| {
                rb.deinit();
                app_remote_backend = null;
            }
            if (app_remote_client) |*cl| {
                cl.deinit();
                app_remote_client = null;
            }
        }

        app_keep_alive_after_quit = true;
        const cat = try session.createTerm(.{ .command = "/bin/cat" }, .{ .cols = 40, .rows = 10 }, 16, "cat", "/bin/cat");
        try std.testing.expect(cat.surface.remote != null); // host-backed
        // pendingNotification이 훑도록 첫 탭 첫 pane에 임시 삽입(cleanup에서 pop 후 destroyTerm).
        try session.tabs.items[0].panes.items[0].terms.append(allocator, cat);

        // OSC 777을 cat에 입력 → host PTY가 cat으로, cat이 raw echo → **host core**가 파싱 → host 알림 pending.
        try session.runtime.writeInput(cat.surface.id, .{ .bytes = "\x1b]777;notify;BuildDone;ok\x1b\\\n" });

        // pendingNotification이 host에서 pull해 GUI 경로로 surfacing한다(host tick·echo 대기 폴링).
        var got: ?AppSession.PendingNotification = null;
        var attempts: usize = 0;
        while (attempts < 150 and got == null) : (attempts += 1) {
            got = session.pendingNotification();
            if (got == null) _ = usleep(20 * 1000);
        }
        const n = got orelse {
            _ = session.tabs.items[0].panes.items[0].terms.pop();
            session.destroyTerm(cat);
            try std.testing.expect(false);
            return;
        };
        try std.testing.expectEqualStrings("ok", n.body); // body는 그대로
        try std.testing.expect(std.mem.indexOf(u8, n.title, "BuildDone") != null); // 위치 접두 + OSC title
        try std.testing.expectEqual(cat.surface.id, n.surface_id); // 클릭 점프용 발신 surface
        // 인앱 히스토리에도 보관됐다(in-process와 같은 경로).
        try std.testing.expect(session.notification_history.items.len >= 1);

        _ = session.tabs.items[0].panes.items[0].terms.pop(); // destroyTerm 전 탭에서 뗀다(dangling 방지).
        session.destroyTerm(cat);
    } else {
        return error.SkipZigTest;
    }
}

// M3a 핵심 불변식(주소 안정성) — surface·런타임 소유를 registry 번들로 옮겨도 reader thread가 잡는 두 embedded
// 주소(`&live_pty.reader`·`&surface.core`)가 등록(realloc)·타 번들 해제에도 **불변**이어야 하고, 그 사이 스크롤백
// (TerminalCore 상태)이 보존돼야 한다(Term-inline heap-pin과 같은 메커니즘 = registry 개별 heap 슬롯). 이 단언이
// 실패하면 소유 이전이 reader 계약을 깬 것이다. 실 PTY(실 reader thread)라 macOS 게이트 — 프로덕션 배선 검증.
test "M3a: 번들 이전 후에도 reader의 &live_pty.reader·&surface.core 주소가 등록/해제에 불변 + 스크롤백 보존" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const before = app_runtime.live_registry.count();

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 첫 Term(T0)의 번들 포인터·reader/surface embedded 주소·surface_id를 잡는다. P2 seam: Term은 live_pty 포인터
    // 대신 opaque handle(= surface_id)을 들므로, 번들 슬롯 live_pty 주소는 registry 조회로 얻는다.
    const t0 = session.tabs.items[0].activePane().activeTerm();
    const surface0 = t0.surface; // 번들 슬롯의 &surface(안정)
    const sid0 = t0.surface.id;
    const handle0 = t0.rt.handle; // opaque runtime handle(= surface_id, in-process)
    const b0 = session.live_registry.findBySurface(sid0).?; // *LiveSurface 번들 슬롯
    const p0 = &b0.terminal.live_pty; // 번들 슬롯의 &live_pty(안정) — registry 조회로 얻음(rt.live_pty 대신)
    const reader_addr0 = &p0.reader; // reader thread가 잡는 embedded 필드 주소 — 절대 이동 금지
    const core_addr0 = &surface0.core; // reader가 잡는 다른 바인딩(&surface.core) — 절대 이동 금지
    try std.testing.expectEqual(handle0, sid0); // P2: handle이 surface_id와 같아 registry 조회 키가 된다
    try std.testing.expectEqual(surface0, &b0.terminal.surface);
    try std.testing.expectEqual(before + 1, session.live_registry.count());

    // 스크롤백(코어 상태)을 몇 줄 넣는다(controlled_smoke=reader 미처리라 메인이 코어를 직접 write — 경합 없음).
    // 이 상태가 realloc/타 번들 해제 뒤에도 보존됨을 아래에서 확인한다(이동=재시작 0의 핵심 증거).
    try surface0.core.write("history line 1\r\nhistory line 2\r\n");
    const scrollback_before = surface0.core.scrollbackLen();

    // 워크스페이스(번들)를 여러 개 더 등록해 registry entries realloc을 유도한다. cat으로 살려 tick 미실행이라
    // reap과 무관하게 등록 상태를 유지한다(멀티-탭 테스트와 같은 셋업).
    const N: usize = 6;
    var k: usize = 0;
    while (k < N) : (k += 1) {
        _ = try session.createTab(
            .{ .command = "/bin/sh", .args = &.{ "-c", "cat" }, .size = .{ .cols = 20, .rows = 5 } },
            .{ .cols = 20, .rows = 5 },
            16,
            "w",
            "sh",
        );
    }
    try std.testing.expectEqual(before + 1 + N, session.live_registry.count());
    // 등록이 늘어도 T0 번들 슬롯은 개별 heap이라 안 움직인다 — 같은 번들·같은 reader/surface 주소·같은 Term 참조·
    // 같은 스크롤백(재시작 0).
    const b0_after = session.live_registry.findBySurface(sid0).?;
    try std.testing.expectEqual(b0, b0_after);
    try std.testing.expectEqual(p0, &b0_after.terminal.live_pty);
    try std.testing.expectEqual(surface0, &b0_after.terminal.surface);
    try std.testing.expectEqual(reader_addr0, &b0_after.terminal.live_pty.reader);
    try std.testing.expectEqual(core_addr0, &b0_after.terminal.surface.core);
    try std.testing.expectEqual(handle0, t0.rt.handle); // P2: handle 불변(등록 realloc에도)
    try std.testing.expectEqual(surface0, t0.surface);
    try std.testing.expectEqual(scrollback_before, b0_after.terminal.surface.core.scrollbackLen());

    // 추가분을 뒤에서부터 닫아(번들 소유 해제) 남은 T0(index 0)가 여전히 불변인지 — orderedRemove가 다른
    // 슬롯을 안 옮긴다(번들 본체는 개별 heap). 마지막 1개(T0)까지 줄인다.
    while (session.tabs.items.len > 1) session.closeTab(session.tabs.items.len - 1);
    try std.testing.expectEqual(before + 1, session.live_registry.count());
    const b0_final = session.live_registry.findBySurface(sid0).?;
    try std.testing.expectEqual(b0, b0_final);
    try std.testing.expectEqual(reader_addr0, &b0_final.terminal.live_pty.reader);
    try std.testing.expectEqual(core_addr0, &b0_final.terminal.surface.core);
    try std.testing.expectEqual(scrollback_before, b0_final.terminal.surface.core.scrollbackLen());
}

// M3a close/teardown 배선 — Term을 닫으면 그 번들 소유(surface + live_pty)가 registry에서 **제거**되고
// (findBySurface→null), 남은 번들은 온전해야 한다. destroyTerm이 `remove`로 번들 teardown하는 경로를 못박는다
// (누수·이중해제는 testing.allocator가 잡음 — surface.deinit·custom_name 해제가 번들 deinit으로 이관됐으므로 특히 중요).
test "M3a: Term close가 registry 번들을 제거하고 남은 번들은 불변" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const before = app_runtime.live_registry.count();

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const CloseRecorder = struct {
        count: usize = 0,
        last_surface_id: u64 = 0,

        fn record(context: ?*anyopaque, surface_id: u64) void {
            const self: *@This() = @ptrCast(@alignCast(context.?));
            self.count += 1;
            self.last_surface_id = surface_id;
        }
    };
    var close_recorder: CloseRecorder = .{};
    session.setSurfaceClosedCallback(&close_recorder, CloseRecorder.record);

    const keep = session.tabs.items[0].activePane().activeTerm();
    const keep_surface = keep.surface; // 번들 슬롯의 &surface
    const keep_sid = keep.surface.id;
    const keep_handle = keep.rt.handle; // P2: opaque runtime handle(= surface_id) — live_pty 포인터 대신
    const keep_ptr = &session.live_registry.findBySurface(keep_sid).?.terminal.live_pty; // 번들 슬롯 &live_pty(registry 조회)

    // 두 번째 워크스페이스(런타임)를 추가 → registry 소유 2개.
    _ = try session.createTab(
        .{ .command = "/bin/sh", .args = &.{ "-c", "cat" }, .size = .{ .cols = 20, .rows = 5 } },
        .{ .cols = 20, .rows = 5 },
        16,
        "w2",
        "sh",
    );
    const closing_sid = session.tabs.items[1].activePane().activeTerm().surface.id;
    try std.testing.expectEqual(before + 2, session.live_registry.count());
    try std.testing.expect(session.live_registry.findBySurface(closing_sid) != null);

    // 두 번째 워크스페이스를 닫는다 → 그 런타임 소유가 registry에서 사라진다(destroyTerm → remove).
    session.closeTab(1);
    try std.testing.expect(session.live_registry.findBySurface(closing_sid) == null);
    try std.testing.expectEqual(@as(usize, 1), close_recorder.count);
    try std.testing.expectEqual(closing_sid, close_recorder.last_surface_id);
    try std.testing.expectEqual(before + 1, session.live_registry.count());
    // 남은 번들(keep)은 포인터·소유가 온전(orderedRemove가 keep 슬롯을 안 건드림).
    const keep_bundle = session.live_registry.findBySurface(keep_sid).?;
    try std.testing.expectEqual(keep_ptr, &keep_bundle.terminal.live_pty);
    try std.testing.expectEqual(keep_surface, &keep_bundle.terminal.surface);
    try std.testing.expectEqual(keep_handle, keep.rt.handle); // P2: handle 불변(다른 워크스페이스 close에도)
    try std.testing.expectEqual(keep_surface, keep.surface);
}

test "dispatchBell: 배경(비활성) pane의 BEL도 잡는다 — Dock 배지/소리 (리뷰 D)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // splitActivePane = 실 PTY/CoreText
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};

    try session.splitActivePane(.horizontal); // pane [p0, p1], 활성 p1
    try std.testing.expectEqual(@as(usize, 2), session.activeTab().panes.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().active_pane); // 활성 = p1

    // **배경** pane(p0)의 term core에 BEL을 쓴다(활성 p1이 아니다). active-surface만 보던 옛 dispatchBell은 못 잡았다.
    const bg_core = &session.activeTab().panes.items[0].terms.items[0].surface.core;
    try bg_core.write("\x07");

    session.bell_dock_badge = true;
    session.window_focused = false;
    session.dispatchBell();
    try std.testing.expect(session.takeBellBadge()); // 배경 pane BEL도 배지로(D 수정)
    try std.testing.expect(!session.takeBellBadge()); // 1회성 — 배경 core도 drain됨(다음 tick 재트리거 없음)

    // 다시 BEL 없이 dispatch → 배지 없음(stale 안 쌓임 확인).
    session.dispatchBell();
    try std.testing.expect(!session.takeBellBadge());
}

test "setSystemAppearance: follow-system on이면 light/dark 프리셋으로 교체, off면 무시 (F2-9)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const light_bg = config_mod.theme.presetColors(.solarized_light).background;
    const dark_bg = config_mod.theme.presetColors(.gruvbox_dark).background;

    // follow-system OFF(기본): setSystemAppearance가 테마를 안 바꾼다.
    session.loaded_config.config.theme_follow_system = false;
    session.loaded_config.config.theme = config_mod.theme.presetColors(.maru);
    session.setSystemAppearance(false); // 라이트라고 알려도
    try std.testing.expectEqualStrings(config_mod.theme.presetColors(.maru).background, session.loaded_config.config.theme.background); // maru 유지

    // follow-system ON: preset-light/dark로 교체.
    session.loaded_config.config.theme_follow_system = true;
    session.loaded_config.config.theme_preset_light = .solarized_light;
    session.loaded_config.config.theme_preset_dark = .gruvbox_dark;
    session.setSystemAppearance(false); // 라이트 → solarized-light
    try std.testing.expectEqualStrings(light_bg, session.loaded_config.config.theme.background);
    session.setSystemAppearance(true); // 다크 → gruvbox-dark
    try std.testing.expectEqualStrings(dark_bg, session.loaded_config.config.theme.background);
    // appearance도 재resolve돼 라이브 색이 갱신된다(reapplyLoadedConfig — gruvbox 배경 #282828 = {0x28,0x28,0x28}).
    try std.testing.expectEqual(@as(u8, 0x28), session.appearance.theme.background.r);
}

test "follow-system 토글 ON 즉시 적용·OFF 사용자 테마 복귀 + 같은 외관 재적용 게이트 (F2-9 리뷰)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const user_bg = config_mod.theme.presetColors(.dracula).background; // 사용자(파일) 테마
    const dark_bg = config_mod.theme.presetColors(.gruvbox_dark).background;
    session.loaded_config.config.theme = config_mod.theme.presetColors(.dracula);
    session.loaded_config.config.theme_preset_light = .solarized_light;
    session.loaded_config.config.theme_preset_dark = .gruvbox_dark;
    session.system_is_dark = true;

    // 토글 ON: setSystemAppearance(외관 변화) 없이 즉시 시스템 프리셋이 적용돼야 한다(버그: 예전엔 무효였음).
    session.loaded_config.config.theme_follow_system = true;
    session.applyFollowSystemTheme(); // 토글 경로가 부르는 것
    try std.testing.expectEqualStrings(dark_bg, session.loaded_config.config.theme.background); // 즉시 gruvbox-dark
    try std.testing.expect(session.theme_pre_follow != null); // 사용자 테마 스냅샷됨

    // 같은 외관 재통지는 재적용 게이트로 무시(theme 그대로) — 관측은 색 동일.
    session.applyFollowSystemTheme();
    try std.testing.expectEqualStrings(dark_bg, session.loaded_config.config.theme.background);

    // 토글 OFF: 덮기 전 사용자(dracula) 테마로 라이브 복귀해야 한다(버그: 예전엔 시스템색 잔류).
    session.loaded_config.config.theme_follow_system = false;
    session.disableFollowSystemTheme();
    try std.testing.expectEqualStrings(user_bg, session.loaded_config.config.theme.background); // dracula 복귀
    try std.testing.expect(session.theme_pre_follow == null); // 스냅샷 소비됨
    try std.testing.expect(session.follow_applied_dark == null); // 외관 게이트 리셋
}

test "follow-system 중 preset-dark 변경은 라이브 재적용 + user_custom 잠금 복원 (F2-9 리뷰 라운드2)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 사용자가 "사용자 지정"으로 색 잠금을 풀어둔 상태에서 follow-system을 켠다.
    session.loaded_config.config.theme = config_mod.theme.presetColors(.dracula);
    session.loaded_config.config.theme_preset_dark = .gruvbox_dark;
    session.theme_user_custom = true; // 잠금 해제 상태
    session.system_is_dark = true;
    session.loaded_config.config.theme_follow_system = true;
    session.applyFollowSystemTheme();
    try std.testing.expectEqualStrings(config_mod.theme.presetColors(.gruvbox_dark).background, session.loaded_config.config.theme.background);
    try std.testing.expectEqual(false, session.theme_user_custom); // 프리셋 적용 중엔 잠금

    // follow-system 켜진 채 preset-dark를 dracula로 바꾸면(세팅 cycleEnum 경로) 라이브 색도 즉시 dracula여야 한다
    // (버그: 게이트가 같은 외관이라 막아 옛 gruvbox 잔류). cycleEnum 분기가 하는 것: 게이트 열기 + applyFollowSystemTheme.
    session.loaded_config.config.theme_preset_dark = .dracula;
    session.follow_applied_dark = null;
    session.applyFollowSystemTheme();
    try std.testing.expectEqualStrings(config_mod.theme.presetColors(.dracula).background, session.loaded_config.config.theme.background); // 새 프리셋 라이브

    // 끄면 색뿐 아니라 user_custom 잠금 상태(true)도 복원돼야 한다(버그: false 잔류로 잠김).
    session.loaded_config.config.theme_follow_system = false;
    session.disableFollowSystemTheme();
    try std.testing.expectEqual(true, session.theme_user_custom); // 잠금 해제 복원
}

// wheelDeltaToLines 단위 테스트는 함수와 함께 src/session/input_math.zig로 이동.

test "commitComposition is a safe no-op when there is no active preedit" {
    // 조합이 없으면(preedit==null) 아무것도 안 보내고 무해해야 한다 — IME 우회 특수키(PageUp)마다
    // 호출되므로 일반 타이핑 경로를 망가뜨리면 안 된다. 실제 preedit commit 경로는 아래의
    // initialized AppSession 테스트가 non-blocking/exactly-once 불변식으로 고정한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.addr_edit = null; // 7e-2: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.focus_owner = .workspace;
    session.pending_dock_focus = null;
    session.chrome_host = .{}; // inputFocus가 notice/find/palette.open을 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null; // inputFocus가 rename을 읽음(undefined면 garbage가 .rename 분기 → rename_input crash)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.metal_dirty = false;
    session.ime_terminal_target_id = null;
    try std.testing.expect(!tab_surface.preedit.active());
    session.commitComposition(); // 무동작이어야(no preedit)
    try std.testing.expect(!tab_surface.preedit.active());
    try std.testing.expect(!session.metal_dirty); // 보낼 게 없으니 다시 그릴 것도 없다
}

test "sidebarSearchLine: 넘치면 tail 창(선두 …)으로 caret을 입력 영역 안에 유지한다" {
    // 사이드바 검색바도 긴 검색어면 head 정렬은 앞부분만 보이고 caret('|')이 우측 아이콘 영역으로 잘려 안 보였다.
    // sidebarSearchLine이 넘침 시 선두 "…" + 뒤쪽으로 오른쪽 정렬해 caret을 max_col 안에 둔다(find·palette와 같은 규칙).
    // sidebarSearchLine은 self.sidebar_search_input만 읽으므로([[devsession-undefined-test-field-trap]]) 그 필드만 초기화한다.
    var session: AppSession = undefined;
    session.sidebar_search_input = .{};
    defer session.sidebar_search_input.deinit(std.testing.allocator);

    // 비넘침: 짧은 검색어 → 잘림 없음, caret = text_col + content 폭.
    for ("abc") |c| try session.sidebar_search_input.appendChar(std.testing.allocator, c);
    {
        const line = session.sidebarSearchLine(30); // 넉넉한 max_col
        try std.testing.expect(!line.truncated);
        try std.testing.expectEqual(sidebar_search_text_col + @as(u16, 3), line.caret_col);
    }

    // 넘침: 좁은 max_col → tail 창 + caret이 max_col 안 + 뒤쪽(방금 친 'j')이 보인다.
    session.sidebar_search_input.clear();
    for ("abcdefghij") |c| try session.sidebar_search_input.appendChar(std.testing.allocator, c); // 10칸
    {
        const max_col: u16 = sidebar_search_text_col + 6; // 입력 영역 6칸
        const line = session.sidebarSearchLine(max_col);
        try std.testing.expect(line.truncated);
        try std.testing.expect(line.caret_col < max_col); // caret이 잘려 숨지 않음
        try std.testing.expect(line.query.len > 0 and line.query[line.query.len - 1] == 'j'); // caret 쪽(방금 친 글자)이 보임
    }
}

// renameCaretRect는 셀·사이드바 픽셀 메트릭과 tabs/sidebar_rows가 필요해 실제 session.init로 세션을 만든 뒤(비-undefined,
// UB 없음) headless라 0인 메트릭만 채워 호출한다. 검증 대상은 code-review high finding 1·2 수정: 워크스페이스/그룹 이름이
// 사이드바 폭을 넘치면 렌더가 tail 앵커로 caret을 이름영역 우경계에 두므로, caret rect의 x도 거기로 clamp돼야 IME
// 후보창이 사이드바 밖 터미널 위로 안 뜬다(head-anchored·unclamped 회귀 고정).
fn initRenameCaretTestSession(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    // headless init은 셀·사이드바 픽셀 메트릭이 0이라 renameCaretRect가 조기 null → 테스트용으로 채운다.
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.sidebar_width_px = 80; // full_cols = 80/8 = 10 → 우경계 clamp = full_cols-2 = 8칸(x=64)
    session.sidebar_slot_height_px = 32;
    // 카드 높이는 이제 줄 수 기반이라 슬롯 필드만으로는 안 잡힌다 — 1줄 카드 높이가 32이 되는 메트릭을 박아
    // 고정 슬롯 시절 좌표 기대값을 그대로 쓴다(여백 0·스텝=줄높이).
    session.sidebar_metrics = .{ .line_h = 32, .line_step = 32, .card_pad_v = 0, .header_row_h = session.sidebar_header_row_h_px, .content_pad_v = 0, .list_pad_v = 0 };
    session.sidebar_header_height_px = 0;
    session.sidebar_header_row_h_px = 16;
    return session;
}

test "renameCaretRect(.workspace): 이름이 사이드바 폭을 넘치면 caret x를 우경계로 clamp(넘침 아니면 head)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.recomputeVisibleTabs(); // sidebar_rows 채움(displaySlotOf/rowTop이 읽음)

    const tab = session.tabs.items[0];
    session.rename = .{ .workspace = tab };

    const cw = session.cell_width_px;
    const full_cols = session.sidebar_width_px / cw; // 10
    const clamp_x: i32 = @intCast((full_cols - 2) * cw); // 8*8 = 64 (이름영역 우경계)

    // 넘침: 긴 이름(20칸) → head(indent+20) > 우경계 → x는 clamp(64)로 잘려 사이드바 안에 머문다.
    for (0..20) |_| try session.rename_input.appendChar(allocator, 'a');
    {
        const r = session.renameCaretRect() orelse return error.NoCaret;
        try std.testing.expectEqual(clamp_x, r.x);
    }

    // 비넘침: 짧은 이름 → clamp 안 하고 head 위치(indent + qcols). (clamp 회귀가 짧은 이름까지 당기지 않음을 확인.)
    session.rename_input.clear();
    for ("ab") |c| try session.rename_input.appendChar(allocator, c);
    {
        const sp = session.buildChromeTokens().space;
        const indent_cols = (sp.card_gap_px + sp.accent_bar_width_px + cw - 1) / cw;
        const head_x: i32 = @intCast((indent_cols + 2) * cw);
        try std.testing.expect(head_x < clamp_x); // 이 셋업에선 head가 우경계보다 왼쪽(=비넘침 케이스 성립)
        const r = session.renameCaretRect() orelse return error.NoCaret;
        try std.testing.expectEqual(head_x, r.x);
    }
}

test "renameCaretRect(.group): 헤더 이름이 넘치면 caret x를 사이드바 우경계로 clamp" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 탭0을 그룹 시작으로(헤더 row 생성). group_start는 owned(deinit이 free).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "g");
    session.recomputeVisibleTabs(); // [group_header{tab0}, card{tab0}]
    const tab = session.tabs.items[0];
    session.rename = .{ .group = tab };

    const cw = session.cell_width_px;
    const full_cols = session.sidebar_width_px / cw;
    const clamp_x: i32 = @intCast((full_cols - 2) * cw); // 64

    // 넘침: 긴 헤더 이름 → x clamp(우경계).
    for (0..20) |_| try session.rename_input.appendChar(allocator, 'a');
    const r = session.renameCaretRect() orelse return error.NoCaret;
    try std.testing.expectEqual(clamp_x, r.x);
}

// (P3-4) 위임 핸들러(scroll/선택/reportMouse)를 호출하는 단위 테스트용 헬퍼. 메인 mutate가 runtime을 거쳐
// reader로 가므로, 테스트는 surface를 빈 runtime에 attach해 **non-interactive 폴백(직접 적용)**으로 동기 검증한다
// (enqueue_command=null → enqueueCoreCommand가 코어 락 아래 즉시 apply). io도 세워 폴백의 lockCore에 넘긴다.
fn testNoopPtyWrite(_: *anyopaque, _: []const u8) anyerror!void {}
fn testNoopPtyResize(_: *anyopaque, _: terminal.Size) anyerror!void {}

// R1(마우스 리포트 무오염 회귀 가드) 전용 — writeInput으로 흘러나온 터미널 리포트 바이트를 버퍼에 모은다(non-interactive
// 폴백이 pendingResponse를 이 콜백으로 드레인한다). ctx로 캡처 버퍼를 넘겨 전역 가변 상태 없이 단일 테스트에서 검증한다.
const ReportCaptureCtx = struct {
    buf: *std.ArrayList(u8),
    fn write(ctx: *anyopaque, bytes: []const u8) anyerror!void {
        const self: *ReportCaptureCtx = @ptrCast(@alignCast(ctx));
        try self.buf.appendSlice(std.testing.allocator, bytes);
    }
};
// M3b: `runtime`이 앱-전역 공유 포인터가 됐으므로(app_runtime.routing), `var session = undefined` 테스트는 공유 표를
// 쓰지 않고 **테스트-로컬** SurfaceRuntime을 소유해야 한다(테스트 격리 + testing.allocator leak 검출). 호출자가
// `var test_rt: app.SurfaceRuntime = undefined`를 스택에 두고 그 주소를 넘긴다 — session.runtime이 그 로컬을 가리킨다.
//
// **함정(P2 seam)**: 이 helper는 scroll/mouse/ime처럼 `session.runtime`만 직접 쓰는 테스트용이다. `session.term_backend`는
// 배선하지 않으므로(undefined 유지), 이 helper로 세팅한 세션에서 `termBackend()`를 타는 경로(createTerm/destroyTerm/
// close/pollAgentKinds)를 부르면 안 된다 — 그런 경로가 필요하면 `session.init`을 쓰는 실 세션 테스트를 만든다.
fn attachTestRuntime(session: *AppSession, rt: *app.SurfaceRuntime, surface: *maru.session.Surface) !void {
    session.io = std.testing.io;
    rt.* = app.SurfaceRuntime.init(std.testing.allocator);
    session.runtime = rt;
    _ = try session.runtime.attach(surface, surface.id, .{ .ctx = undefined, .write_input = testNoopPtyWrite, .resize_fn = testNoopPtyResize });
}

test "addrEditCaretRect: 주소창 편집 caret이 밴드 안(y) + nav_end 뒤(x) non-null (7e-2a 리뷰 [4])" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 pane 트리/web Term/셀 메트릭 필요(session.init)
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    // termRect가 유효 폭·높이를 갖게 backing 픽셀을 채운다(rename 테스트는 사이드바 기하만 써 안 채웠다). titlebar 띠 0으로.
    session.backing_width_px = 800;
    session.backing_height_px = 400;
    session.titlebar_strip_px = 0;

    // 활성 pane에 browser web 탭을 만들어 활성 term으로(surface_id 반환). 편집 진입 후 caret rect 조회.
    const sid = try session.createAdoptedWebTermInActivePane();
    session.enterAddrEdit(sid, "https://x");
    const r = session.addrEditCaretRect() orelse return error.NoCaret;

    const pb = session.addrEditPaneBar() orelse return error.NoBar;
    const cw = session.cell_width_px;
    const nav_end: u32 = @as(u32, nav_button_count) * nav_button_w; // 버튼 존(렌더·hit-test 단일 소스)
    const cols: u32 = pb.full.w / cw;
    const edit_w = chrome.components.text_field.displayCols(session.addr_field.text.items); // 편집 표시폭(EAW)
    const expect_col = @min(nav_end + edit_w, cols -| 1); // caret = nav_end + 편집폭(끝-caret·밴드 안이면 안 넘침)
    try std.testing.expectEqual(@as(i32, @intCast(pb.full.x + expect_col * cw)), r.x); // x = 밴드 origin + caret col
    // y는 주소창 밴드([full.y+bar_h, +2·bar_h]) 안 — 탭 바 아래 URL 밴드에 후보창이 뜬다(터미널 본문 origin 폴백 아님).
    const band_y = pb.full.y + pb.full.h;
    try std.testing.expect(r.y >= @as(i32, @intCast(band_y)) and r.y < @as(i32, @intCast(band_y + pb.full.h)));
    try std.testing.expectEqual(cw, r.w);
    try std.testing.expectEqual(session.cell_height_px, r.h);
}

test "슬라이스 3: 주소창 밴드 마우스 — 클릭 caret 배치·더블클릭 단어 선택 (mouse 배선)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 pane 트리/web Term/셀 메트릭 필요(session.init)
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.backing_width_px = 800;
    session.backing_height_px = 400;
    session.titlebar_strip_px = 0;

    const sid = try session.createAdoptedWebTermInActivePane();
    // 편집 진입 후 URL을 알기 쉬운 값으로 교체(구분자 있는 8글자 ASCII — 컬럼=바이트).
    session.enterAddrEdit(sid, "aa/bb/cc");
    try std.testing.expectEqual(@as(usize, 8), session.addr_field.caret); // 시드 후 끝-caret

    const pb = session.addrEditPaneBar() orelse return error.NoBar;
    const cw = session.cell_width_px;
    const bar_h = pb.full.h;
    const nav_end: u32 = @as(u32, nav_button_count) * nav_button_w;
    const band_x: f64 = @floatFromInt(pb.full.x);
    const band_y: f64 = @floatFromInt(pb.full.y + bar_h + bar_h / 2); // 밴드 세로 중앙
    const colX = struct {
        fn at(bx: f64, col: u32, cwp: u32) f64 {
            return bx + @as(f64, @floatFromInt(col * cwp)) + 1.0; // 셀 좌측 근처(round→그 열)
        }
    }.at;

    // 클릭(down) col nav_end+3('b' 앞) → caret=byte 3(중간, 끝 아님). 마우스 배선이 caretAtColumn을 관통.
    session.mouse(1, colX(band_x, nav_end + 3, cw), band_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 3), session.addr_field.caret);
    try std.testing.expect(session.addr_field.selection == null);
    try std.testing.expect(session.pointerGestureIs(.address_selection)); // down이 드래그 arm
    session.mouse(3, colX(band_x, nav_end + 3, cw), band_y, 0, 0); // up → 드래그 종료
    try std.testing.expect(!session.pointerGestureIs(.address_selection));

    // 더블클릭(kind 4) col nav_end+4('b' 중) → 단어 "bb"(byte 3..5) 선택. URL 구분자 '/'가 단어 경계.
    session.mouse(4, colX(band_x, nav_end + 4, cw), band_y, 0, 0);
    const sel = session.addr_field.selection orelse return error.NoSelection;
    try std.testing.expectEqual(@as(usize, 3), sel.lo());
    try std.testing.expectEqual(@as(usize, 5), sel.hi());
    try std.testing.expectEqualStrings("bb", session.addr_field.text.items[sel.lo()..sel.hi()]);

    // 트리플클릭(kind 5) URL 존 → 전체 선택.
    session.mouse(5, colX(band_x, nav_end + 2, cw), band_y, 0, 0);
    const all = session.addr_field.selection orelse return error.NoSelectionAll;
    try std.testing.expectEqual(@as(usize, 0), all.lo());
    try std.testing.expectEqual(@as(usize, 8), all.hi());

    // 리뷰 #4: 트리플클릭이 **nav 버튼 존**(URL 존 밖, col < nav_end)이면 전체선택 안 함(더블클릭과 같은 in_url_zone 게이트).
    session.addr_field.clearSelection();
    session.mouse(5, @floatFromInt(pb.full.x + 1 * cw), band_y, 0, 0); // 버튼 존(col 1 = back 버튼)
    try std.testing.expect(session.addr_field.selection == null);
}

test "리뷰 #1: ⌘←/⌘→가 편집을 취소하지 않고 caret을 이동한다 (is_shortcut_chord 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 pane 트리/web Term 필요(session.init)
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.backing_width_px = 800;
    session.backing_height_px = 400;
    session.titlebar_strip_px = 0;

    const sid = try session.createAdoptedWebTermInActivePane();
    session.enterAddrEdit(sid, "https://example.com"); // caret=끝(19)
    try std.testing.expectEqual(@as(usize, 19), session.addr_field.caret);

    // ⌘← : handleKeyEvent 게이트가 편집을 취소하던 버그(리뷰 #1) — 이제 handleAddrEditKey로 흘러 moveHome. 편집 유지.
    _ = session.handleKeyEvent(.{ .key = .arrow_left, .modifiers = .{ .command = true } }) catch return error.KeyFailed;
    try std.testing.expect(session.addr_edit != null); // 편집 취소 안 됨(옛 버그면 null)
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.caret); // 줄 시작으로

    // ⌘→ : 줄 끝으로.
    _ = session.handleKeyEvent(.{ .key = .arrow_right, .modifiers = .{ .command = true } }) catch return error.KeyFailed;
    try std.testing.expect(session.addr_edit != null);
    try std.testing.expectEqual(@as(usize, 19), session.addr_field.caret);

    // ⌘⇧← : 줄 시작까지 선택 확장(편집 유지).
    _ = session.handleKeyEvent(.{ .key = .arrow_left, .modifiers = .{ .command = true, .shift = true } }) catch return error.KeyFailed;
    try std.testing.expect(session.addr_edit != null);
    try std.testing.expect(session.addr_field.selection != null);
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.selection.?.lo());
    try std.testing.expectEqual(@as(usize, 19), session.addr_field.selection.?.hi());
}

test "제보: ⌘⌫가 편집을 취소하거나 웹 포커스로 튕기지 않고 줄 시작까지 삭제한다 (is_shortcut_chord 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 pane 트리/web Term 필요(session.init)
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.backing_width_px = 800;
    session.backing_height_px = 400;
    session.titlebar_strip_px = 0;

    const sid = try session.createAdoptedWebTermInActivePane();
    session.enterAddrEdit(sid, "https://example.com"); // caret=끝(19)

    // caret을 'c'(16) 앞으로 이동(← 3회 = "com" 앞). 화살표는 command/control 없어 게이트서 chord 아님 → moveLeft.
    _ = session.handleKeyEvent(.{ .key = .arrow_left, .modifiers = .{} }) catch return error.KeyFailed;
    _ = session.handleKeyEvent(.{ .key = .arrow_left, .modifiers = .{} }) catch return error.KeyFailed;
    _ = session.handleKeyEvent(.{ .key = .arrow_left, .modifiers = .{} }) catch return error.KeyFailed;
    try std.testing.expectEqual(@as(usize, 16), session.addr_field.caret);

    // ⌘⌫ : 옛 버그면 게이트가 .backspace를 chord로 보고 cancelAddrEdit → 웹 포커스로 튕김(addr_edit=null). 이제
    // 편집기가 줄 시작까지 삭제(deleteToLineStart) — 편집 유지.
    _ = session.handleKeyEvent(.{ .key = .backspace, .modifiers = .{ .command = true } }) catch return error.KeyFailed;
    try std.testing.expect(session.addr_edit != null); // 편집 유지(포커스 안 튕김 — 제보 수정)
    try std.testing.expectEqualStrings("com", session.addr_field.text.items); // [0,16) 삭제
    try std.testing.expectEqual(@as(usize, 0), session.addr_field.caret);
}

test "제보: 주소창 IME 한글 — conjoining 자모 마크드/커밋이 완성형(NFC)으로 조합된다 (end-to-end)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 pane 트리/web Term·IME 트랜잭션 필요
    const allocator = std.testing.allocator;
    const session = try initRenameCaretTestSession(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.backing_width_px = 800;
    session.backing_height_px = 400;
    session.titlebar_strip_px = 0;

    const sid = try session.createAdoptedWebTermInActivePane();
    session.enterAddrEdit(sid, ""); // 빈 주소창 편집 시작

    // macOS IME는 NFD conjoining 자모(초성 U+1100.. + 중성 U+1161..)를 준다(터미널 클러스터가 증명). 주소창은 셀당
    // codepoint라 저장 경계서 완성형으로 합쳐야 한다. 이 테스트는 imeMarked(preedit)·imeInsert/imeEnd(commit) 두
    // composeHangul 호출처를 실제 IME 진입점으로 구동해 완성형이 나오는지 고정한다(제보: ㄱㅏㄴㅏㄷㅏ 분해 표시).

    // 조합 중 마크드 "가"(U+1100 U+1161) → preedit에 완성형 "가"(U+AC00, 3바이트) 저장.
    session.imeMarked("\u{1100}\u{1161}");
    try std.testing.expectEqualStrings("가", session.addr_field.preedit.items);

    // 확정 커밋(imeBegin→imeInsert(conjoining)→imeEnd) → routeCommittedText → composeHangul → text에 완성형 "가".
    session.imeBegin();
    session.imeInsert("\u{1100}\u{1161}");
    session.imeEnd(null);
    try std.testing.expectEqualStrings("가", session.addr_field.text.items);

    // LVT(받침) 음절도: "한"(ㅎ U+1112 + ㅏ U+1161 + ㄴ U+11AB) 커밋 → 완성형 "한"(U+D55C).
    session.imeBegin();
    session.imeInsert("\u{1112}\u{1161}\u{11AB}");
    session.imeEnd(null);
    try std.testing.expectEqualStrings("가한", session.addr_field.text.items);
}

test "scrollPage scrolls one screen (rows-1) per page using the core's authoritative rows" {
    var session: AppSession = undefined;
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 5 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.metal_dirty = false;
    session.tabs = .empty; // [4e-2] scrollPage 게이트 activeTermIsTerminal이 tabs를 읽음 — 빈 트리=terminal 취급(byte-identical)
    // 9줄 출력 -> 5행 화면 위로 4줄이 스크롤백에 쌓인다.
    try tab_surface.core.write("1\r\n2\r\n3\r\n4\r\n5\r\n6\r\n7\r\n8\r\n9");
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.scrollbackLen());

    session.scrollPage(1); // 위로 한 화면 = rows-1 = 4줄
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset);
    try std.testing.expect(session.metal_dirty);

    session.scrollPage(-1); // 아래로 한 화면 -> 바닥
    try std.testing.expectEqual(@as(usize, 0), tab_surface.core.view_offset);
}

test "mouse reporting 진입은 진행 중이던 드래그 autoscroll을 멈춘다 (audit MEDIUM)" {
    var session: AppSession = undefined;
    session.addr_edit = null; // 슬라이스 3: mouse()가 조기 addr 밴드 캡처에서 읽음(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.tabs = .empty; // legacy surface-only fixture: archive detail pointer routing has no structured Tab
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.scrollbar_capture = null;
    session.scrollbar_coalescer = .{};
    session.scrollbar_snapshot_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io(); // updateCursorBlink→readActiveSnapshot이 lockCore(self.io)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.metal_dirty = false;
    session.chrome_host = .{}; // mouse()가 context_menu.open을 kind 무관하게 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null;
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.scrollbar_capture = null;
    session.scrollbar_coalescer = .{};
    session.scrollbar_snapshot_generation = 0;
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.scale_milli = 1000;
    session.sidebar_width_px = 0;
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 32, .h = 32 };
    session.last_drag_col = 1;

    // 셀렉션 드래그 autoscroll이 걸린 상태에서 앱이 mouse tracking(.normal)을 켰다.
    session.drag_autoscroll = 1;
    session.mouse_drag_selecting = true;
    tab_surface.core.mouse_tracking = .normal;

    // 다음 drag(kind 2) 이벤트가 reporting 분기로 간다 — autoscroll/selecting을 멈춰야 한다(예전엔 조기
    // return하며 안 꺼서 frame-loop로 stuck). .normal은 motion을 리포트하지 않아 PTY write-back은 없다.
    session.mouse(2, 8.0, 8.0, 0, 0);
    try std.testing.expectEqual(@as(i8, 0), session.drag_autoscroll);
    try std.testing.expect(!session.mouse_drag_selecting);
}

test "drag autoscroll scrolls one line per tick and extends the selection to the edge row" {
    var session: AppSession = undefined;
    session.addr_edit = null; // 슬라이스 3: mouse()가 조기 addr 밴드 캡처에서 읽음(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.tabs = .empty; // legacy surface-only fixture: archive detail pointer routing has no structured Tab
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
