    // ③ 터미널 본문(바 아래) 우클릭 → 대상 없음 → 메뉴 안 열림.
    session.mouse(1, @floatFromInt(pb.full.x + 4), @floatFromInt(pb.full.y + pb.full.h + 5), 2, 0);
    try std.testing.expect(!session.chrome_host.context_menu.open);
}

// rename caret 깜빡임(blink_visible로 '|'↔공백, 폭 고정)과 IME 후보창 caret rect(편집기 위치 추적)를 고정한다.
test "rename caret blinks (width-stable) and IME caret rect tracks the editor, not the terminal cursor" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const term0 = session.activePane().activeTerm();
    session.startRename(.{ .term = term0 });
    session.handleRenameKey(.{ .key = .{ .key = .char, .codepoint = 'h' } });
    session.handleRenameKey(.{ .key = .{ .key = .char, .codepoint = 'i' } });

    // 깜빡임: blink_visible면 '|', 아니면 공백으로 끝난다 — 두 표시폭이 같아야(폭 흔들림 없음).
    session.blink_visible = true;
    const on = try session.renameEditText(allocator);
    defer allocator.free(on);
    session.blink_visible = false;
    const off = try session.renameEditText(allocator);
    defer allocator.free(off);
    try std.testing.expect(std.mem.endsWith(u8, on, "hi|"));
    try std.testing.expect(std.mem.endsWith(u8, off, "hi ")); // 공백 caret
    try std.testing.expectEqual(on.len, off.len); // 폭 고정

    // IME caret rect: rename 활성이면 imeCursorRect가 편집기 caret(탭 바 영역, 화면 상단)에서 난다 — 터미널 본문
    // (바 아래)이 아니다. renameCaretRect와 일치.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const bar = session.paneBarRect(lr.items[0].rect).?;
    const term_body = session.paneTermRect(lr.items[0].rect);
    const cr = session.renameCaretRect() orelse return error.NoCaret;
    try std.testing.expectEqual(@as(u32, session.cell_width_px), cr.w);
    try std.testing.expect(@as(u32, @intCast(cr.y)) >= bar.y and @as(u32, @intCast(cr.y)) < term_body.y); // 탭 바 안(본문 위)
    const ime = session.imeCursorRect();
    try std.testing.expectEqual(@as(f64, @floatFromInt(cr.y)), ime.y); // imeCursorRect가 rename caret을 씀
    session.closeRename();
}

// F1 회귀 가드(코드리뷰 high CONFIRMED): 워크스페이스 리네임 중 상태줄(running 파형·idle ✓)이 붙어 카드가 2줄이 되면
// 렌더러(maru_metal_renderer.m)가 2줄 블록을 슬롯 세로 중앙 정렬해 이름줄(line 0)이 위로 (ch/2) 밀린다 —
// renameCaretRect도 같은 line_count로 caret y를 올려야 IME 후보창이 이름 caret 아래(파형 상태줄과 겹치지 않게)에 온다.
// non-agent 워크스페이스는 상태줄이 없어 1줄이라 슬롯 중앙 그대로. buildSidebarDrawList의 line_count 인코딩(빈 보조줄
// skip)과 caret 정렬을 묶는다 — 상태줄이 이름줄 아래에 늘 붙던 회귀(커밋 8c4c969)에서 캐럿만 1줄 기준으로 남던 것을 고정.
// 겸해서 caret y가 view 절대 좌표 규약(사이드바 header 더하고 scroll 뺌 — Swift firstRect가 origin 보정 없이 변환만)을
// 지키는지도 고정한다(케이스 3: scroll offset 반영). 예전엔 idx*slot_h만 써서 header만큼 위·scroll만큼 아래로 어긋났다.
test "F1: workspace rename caret y follows card line count + sidebar header/scroll offset" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const tab = session.tabs.items[0];
    const term = tab.activeTerm();
    const ch: u32 = session.cell_height_px;
    const header: u32 = session.sidebar_header_height_px;
    // 카드 높이가 **줄 수 기반**이 되면서 블록중앙 오프셋은 항상 카드 상하 여백(card_pad_v)이다
    // (카드 높이 = 줄 블록 + 2×여백이므로 (카드-블록)/2 = 여백). 즉 이름줄은 줄 수와 무관하게 카드 상단
    // 같은 자리에 온다 — 옛 고정 슬롯에서 줄이 늘 때마다 이름줄이 위로 올라가던 것과 달라진 점이다.
    const pad_v: u32 = session.sidebarMetrics().card_pad_v + session.sidebarMetrics().content_pad_v; // 카드 여백 + 목록 위 여백
    try std.testing.expect(header > 0); // 헤더(검색바·아이콘)가 있다는 전제 — caret y가 그만큼 내려가야 렌더러와 정합

    // 1) non-agent 워크스페이스(scroll 0): 카드 1줄(이름만) → caret = header + 슬롯 세로 중앙(1줄 블록).
    term.agent_kind = .none;
    session.rebuildSidebar() catch {}; // Row.lines(줄 수)는 투영 때 굳는다 — 상태를 바꿨으면 다시 투영해야 정합
    session.startRename(.{ .workspace = tab });
    const cr1 = session.renameCaretRect() orelse return error.NoCaret;
    try std.testing.expectEqual(@as(i32, @intCast(header + pad_v)), cr1.y);
    session.closeRename();

    // 2) 에이전트가 있으면 **rename 중에도 상태줄이 그려지므로**(편집 화면에서 파형을 보여달라는 사용자 요청)
    // 카드는 2줄 블록이고 이름줄은 그만큼 위로 올라간다. caret은 렌더와 **같은 줄 수**를 봐야 IME 후보창이
    // 상태줄을 덮지 않는다(code-review max: 이 계산을 1로 고정했다가 반 줄 어긋났다).
    term.agent_kind = .claude;
    term.agent_state = .idle;
    session.rebuildSidebar() catch {};
    session.startRename(.{ .workspace = tab });
    const cr2 = session.renameCaretRect() orelse return error.NoCaret;
    const m2 = session.sidebarMetrics();
    const row_h2 = chrome.components.sidebar.rowHeight(session.sidebar_rows.items[0], m2);
    const off2 = (row_h2 -| AppSession.sidebarBlockHeight(2, ch)) / 2;
    try std.testing.expectEqual(@as(i32, @intCast(header + m2.content_pad_v + off2)), cr2.y);
    session.closeRename();
    try std.testing.expect(cr2.y < cr1.y); // 상태줄이 붙으면 이름줄(=caret)이 위로 올라간다

    // 3) scroll offset 반영: 콘텐츠가 offset만큼 위로 밀리면 caret도 따라 올라간다(slotTop이 scroll을 뺌). idx 0,
    // 작은 offset(블록중앙 (slot_h−ch)/2 보다 작아 헤더 clamp 전)이라 caret = header + block_off − offset.
    term.agent_kind = .none;
    session.rebuildSidebar() catch {};
    const offset: u32 = @min(ch / 2, pad_v); // pad_v 이하라 헤더 clamp(@max header)에 안 걸린다
    session.sidebar_scroll_offset_px = offset;
    session.startRename(.{ .workspace = tab });
    const cr3 = session.renameCaretRect() orelse return error.NoCaret;
    try std.testing.expectEqual(@as(i32, @intCast(header + pad_v - offset)), cr3.y);
    session.closeRename();
    session.sidebar_scroll_offset_px = 0; // 복원
}

// 코드리뷰 수정 고정: (#7) 포커스 상실 시 rename 확정, (#2) 터미널 본문 우클릭은 consume 안 하고 mouse-reporting으로
// 흘림(트래킹 앱 보존), (#8) 사이드바 ✕(close) zone은 rename 대상 아님.
test "review fixes: focus-loss commits rename, body right-click reports, close-zone excluded" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    const term0 = session.activePane().activeTerm();

    // (#7) rename 중 setFocused(false) → 확정(custom_name 기록, 편집기 닫힘).
    session.startRename(.{ .term = term0 });
    session.handleRenameKey(.{ .key = .{ .key = .char, .codepoint = 'z' } });
    session.setFocused(false);
    try std.testing.expect(session.rename == null);
    try std.testing.expectEqualStrings("z", term0.surface.custom_name.?);

    // (#8) 사이드바 슬롯 ✕(close) zone은 renameTargetAt가 null(닫기 자리에서 rename 방지), 좌측은 워크스페이스.
    const slot_y = session.testSidebarRowCenterY(0); // 슬롯 0 중앙(상단 헤더 아래)
    const close_x = @as(f64, @floatFromInt(session.sidebar_width_px - session.cell_width_px)); // 우측 ✕ 영역
    try std.testing.expect(session.renameTargetAt(close_x, slot_y) == null);
    try std.testing.expect(session.renameTargetAt(@floatFromInt(session.cell_width_px), slot_y) != null); // 좌측=워크스페이스

    // (#2) mouse_tracking 켠 상태에서 터미널 본문 우클릭(button==2) → 메뉴 안 열림 + reporting 경로 도달
    //      (drag_autoscroll/selecting 리셋이 그 증거). 가드가 본문을 consume하면(회귀) 리셋 안 됨.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const body = session.paneTermRect(lr.items[0].rect);
    session.activeSurface().core.mouse_tracking = .normal;
    session.drag_autoscroll = 1;
    session.mouse_drag_selecting = true;
    session.mouse(1, @floatFromInt(body.x + 10), @floatFromInt(body.y + 10), 2, 0); // 본문 우클릭
    try std.testing.expect(!session.chrome_host.context_menu.open); // 메뉴 안 열림(본문엔 대상 없음)
    try std.testing.expectEqual(@as(i8, 0), session.drag_autoscroll); // reporting 경로 도달(=consume 안 함)
    try std.testing.expect(!session.mouse_drag_selecting);
}

test "synchronized output(2026) hold: ESU 누락 시 sync timeout을 넘으면 강제 투영(freeze 복구)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText frame builder 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // controlled 출력이 멎을 때까지 tick한다 — 이후 output_events=0이라 우리가 세팅한 metal_dirty가 유지된다.
    var i: usize = 0;
    while (i < 150) : (i += 1) _ = try session.tick();

    // BSU 상황 모사: 활성 surface가 sync로 진입하고 누적 출력(metal_dirty)이 한 프레임 대기 중.
    session.activeSurface().core.sync_output = true;
    session.metal_dirty = true;
    session.sync_hold_ticks = 0;
    const timeout = session.syncTimeoutTicks();
    // timeout 직전까지는 sync가 투영을 막아 metal_dirty가 false로 안 풀리고 누적된다(투영 판정엔
    // metal_dirty를 본다 — generation은 blink 토글로 따로 올라 투영 여부의 지표가 못 된다).
    var k: usize = 0;
    while (k + 1 < @as(usize, @intCast(timeout))) : (k += 1) _ = try session.tick();
    try std.testing.expect(session.metal_dirty); // 아직 hold(투영 skip)
    try std.testing.expectEqual(timeout - 1, session.sync_hold_ticks);

    // timeout 도달 tick에서 sync_active여도 강제 투영 → metal_dirty가 풀린다(ESU 없이 freeze 해제).
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty);

    // ESU 모사: sync가 꺼지면 다음 tick에 hold 카운터가 0으로 리셋된다.
    session.activeSurface().core.sync_output = false;
    _ = try session.tick();
    try std.testing.expectEqual(@as(u32, 0), session.sync_hold_ticks);
}

test "shouldProjectFrame: sync(2026) hold는 라이브 투영만 막고 스크롤 리페인트는 막지 않는다" {
    const timeout: u32 = ticksForMsAtRate(sync_timeout_ms, config_mod.theme.render_frame_rate_default);
    // 라이브(스크롤 안 함, view_offset==직전 렌더, esu_advanced=false, force_reproject=false): sync hold 중엔 metal_dirty여도 투영 보류.
    try std.testing.expect(!shouldProjectFrame(true, true, 0, timeout, 0, 0, false, false));
    // hold가 timeout 도달 → ESU 없이 강제 투영(freeze 복구) — 기존 동작 보존.
    try std.testing.expect(shouldProjectFrame(true, true, timeout, timeout, 0, 0, false, false));
    // ── 버그 재현: 스크롤백을 위로 본 채(view_offset 3 ≠ 직전 렌더 0) sync hold면, 예전 게이트
    //    (metal_dirty and !(sync and hold<timeout))는 false라 스크롤 리페인트를 막아 viewport가 stale로 멈췄다.
    //    이제 스크롤 변화는 라이브 출력 배칭과 무관하게 투영한다(이 버그의 수정점). ──
    try std.testing.expect(shouldProjectFrame(true, true, 0, timeout, 3, 0, false, false));
    // view_offset 변화는 metal_dirty 누락(스크롤 reader 위임이 build 락-읽기보다 늦는 race)에도 투영을 강제한다.
    try std.testing.expect(shouldProjectFrame(false, false, 0, timeout, 3, 0, false, false));
    // 변화 없음 + dirty 없음 → 투영 안 함(idle tick 비용 절감 보존).
    try std.testing.expect(!shouldProjectFrame(false, false, 0, timeout, 5, 5, false, false));
    // sync 아님 + dirty → 평소대로 투영.
    try std.testing.expect(shouldProjectFrame(true, false, 0, timeout, 0, 0, false, false));
    // ── [B] ESU edge: sync hold 중(sync_active, hold<timeout, 스크롤 없음)이라도 직전 투영 이후 리더가 ESU를
    //    처리했으면(esu_advanced=true) 완성 프레임을 flush한다 — 폴링이 다음 BSU만 관측해 완성 프레임을 놓치던 MISS 수정. ──
    //    **SSH 트레이드오프(docs/io-render-threading.md §11.6 esu_edge)**: 이 case에서 sync_active=true는 "리더가 이미
    //    **다음** 프레임 BSU를 시작"했다는 뜻일 수 있다(연속 조각 프레임). 그러면 flush가 그 진행 중 next 프레임을
    //    half-drawn으로 투영한다 — 로컬은 곧 다음 ESU가 교정하지만 bubbletea diff는 그 셀을 다시 안 보내 영구 stale.
    //    `.sync` 로거의 `active=1 gproj=1`(esu_edge)로 관측되는 maru ssh desync 유력 원인.
    try std.testing.expect(shouldProjectFrame(true, true, 0, timeout, 0, 0, true, false));
    // esu_advanced=false면 여전히 hold가 막는다(진행 중 프레임 tearing 방지 — 정당한 막힘 보존).
    try std.testing.expect(!shouldProjectFrame(true, true, 0, timeout, 0, 0, false, false));
    // esu advanced면 metal_dirty가 누락돼도(reader race) 투영을 강제한다(view_offset 안전판과 동형).
    try std.testing.expect(shouldProjectFrame(false, true, 0, timeout, 0, 0, true, false));
    // ── [A: code-review 0] force_reproject: sync hold 중(hold<timeout)이라도 사이드바 전용 place가 atlas를 repack한 뒤
    //    GPU 정합을 위해 강제 full 투영한다 — metal_dirty 없이도(reader race) 투영, sync hold 우회. ──
    try std.testing.expect(shouldProjectFrame(false, true, 0, timeout, 0, 0, false, true));
    // force_reproject=false면 위와 동일 상황에서 hold가 막는다(대조).
    try std.testing.expect(!shouldProjectFrame(false, true, 0, timeout, 0, 0, false, false));
}

test "synchronized output(2026) hold가 스크롤백 탐색 리페인트는 막지 않는다(rapid 스크롤 stale 수정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText frame builder 경로(tick 투영)
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // controlled 출력이 멎을 때까지 tick한다 — 이후 output_events=0이라 우리가 세팅한 상태(view_offset·sync)가 유지된다.
    var i: usize = 0;
    while (i < 150) : (i += 1) _ = try session.tick();

    // 사용자가 스크롤백을 위로 본 상태(view_offset>0)에서 직전 렌더보다 더 스크롤했고(2≠1), 활성 surface가
    // 동기 출력(2026) hold에 들어간 상황을 모사한다(scroll-lock으로 라이브 출력 중에도 스크롤 위치 유지).
    session.activeSurface().core.view_offset = 2;
    session.last_rendered_view_offset = 1;
    session.activeSurface().core.sync_output = true;
    session.sync_hold_ticks = 0;
    session.metal_dirty = true;

    // 예전 게이트는 sync hold가 metal_dirty 투영을 막아 스크롤이 stale로 멈췄다. 이제 view_offset 변화는 sync와
    // 무관하게 투영한다 — tick 한 번에 metal_dirty가 풀리고(투영됨) 방금 본 위치를 last_rendered_view_offset에 기록한다.
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty); // 투영됨(예전엔 sync hold로 막혀 metal_dirty가 true로 남았다)
    try std.testing.expectEqual(@as(usize, 2), session.last_rendered_view_offset);
}

// 탭 전환 sync-게이트 회귀 테스트 공용 스캐폴딩: controlled_smoke 세션을 만들어 tab0을 정착시키고(출력 소진),
// 둘째 탭을 만들어(→tab1 활성) 정착시킨 뒤 세션을 돌려준다(호출자가 deinit+destroy). tab0 surface는
// session.tabs.items[0].panes.items[0].terms.items[0].surface로 얻는다. [code-review 5] 네 테스트의 중복 제거.
fn setupTwoTabsSettled(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    var i: usize = 0;
    while (i < 150) : (i += 1) _ = try session.tick(); // tab0 정착(controlled 출력 소진 → output_events=0)
    _ = try session.newTab(); // 둘째 탭 → tab1 활성(createTab이 새 탭을 활성으로)
    std.debug.assert(session.tabs.items.len == 2);
    i = 0;
    while (i < 150) : (i += 1) _ = try session.tick(); // tab1 정착
    return session;
}

// ── 회귀: 백그라운드 Term의 출력이 활성 커서 blink 위상을 굶기지 않는다 ─────────────────────────────
// tick의 blink 게이트가 `drain_summary.output_events`(**모든** 탭/pane/Term의 합)를 보던 탓에, 백그라운드에서
// 계속 출력하는 Term이 하나라도 있으면(에이전트·로그 tail·dev 서버) 활성 커서가 매 tick resetCursorBlink로
// 위상 0에 묶여 **영영 깜빡이지 않았다**. 사용자 제보 "커서가 안 깜빡인다"의 실제 원인이고, 스피너가 같은 이유로
// 출력 게이트 밖으로 나갔던 §10.5 primary와 같은 계열이다. 게이트를 활성 surface 출력으로 좁혀 고쳤다.
//
// 기존 blink 단위 테스트가 못 잡은 이유: 전부 `updateCursorBlink`를 **직접** 불러 tick의 게이트를 건너뛴다.
// 그래서 이 테스트는 반드시 `session.tick()`을 돈다.
test "cursor blink: 백그라운드 Term이 계속 출력해도 활성 커서 위상은 진행한다(전역 output 게이트 회귀)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 PTY + CoreText tick 경로
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator); // tab1 활성, 둘 다 출력 소진 상태
    defer {
        session.deinit();
        allocator.destroy(session);
    }
    // 실 config 파일 값에 의존하지 않게 고정(다른 머신에서 cursor.blink=false면 무의미해진다).
    session.appearance.cursor.blink = true;
    session.appearance.cursor.blink_fade_ms = 0; // 하드 토글 — 위상 판정을 blink_visible로 단순화

    const bg_id = session.tabs.items[0].panes.items[0].terms.items[0].surface.id; // tab0 = 백그라운드
    const active_id = session.activeSurface().id;
    try std.testing.expect(bg_id != active_id);

    session.blink_visible = true;
    session.blink_phase_ns = 0;
    // 매 tick 백그라운드에 개행 없는 paste를 밀어 넣어 **그쪽 PTY만** 계속 에코(출력)하게 한다. 개행이 없어야
    // 자식이 `read`에서 살아남아 reap/UAF가 없다([[controlled-smoke-child-exit-reap-uaf]] 규율).
    // 위상은 wall-clock 기준이라 tick 수로는 안 넘어간다 — baseline을 매번 한 반주기 과거로 밀어, 백그라운드 출력이
    // 흐르는 **동안에도** 위상이 진행되는지(=리셋에 굶지 않는지) 본다. 수정 전이면 매 tick resetCursorBlink가
    // baseline을 0으로 되돌리고 blink_visible을 true로 고정해 아래 토글이 한 번도 안 일어난다.
    var toggles: u32 = 0;
    var last = session.blink_visible;
    var i: u32 = 0;
    while (i < 3) : (i += 1) {
        session.pasteTextTo(bg_id, "x", false);
        testAdvanceBlinkHalves(session, 1);
        _ = try session.tick();
        if (session.blink_visible != last) {
            toggles += 1;
            last = session.blink_visible;
        }
    }
    // ★ 활성 커서 위상은 백그라운드 출력과 무관하게 세 번 다 진행했어야 한다.
    try std.testing.expectEqual(@as(u32, 3), toggles);
}

// ── 회귀: 탭 전환 시 mid-sync·완성 프레임 없는(esu==0) surface는 미완성 프레임을 안 그리고 hold한다 ──────
// 대상 탭이 2026 sync 중이고 ESU로 프레임을 완성한 적이 없으면(sync_esu_count==0), 전환 tick은 공유 buffer의
// 직전 완성 프레임을 유지한 채 hold한다(미완성/빈 프레임 안 그림 = 화면 소멸 방지). 완성 프레임이 없으니
// esu-edge로는 못 풀고, sync 게이트를 우회하는 스크롤(view_offset 변화)이나 1초 timeout으로 복구된다.
// 전환 시 baseline 3개를 새 surface 기준으로 리셋하는 수정에서 esu==0이면 이 hold는 불변이라 수정 전후 모두 통과.
test "탭 전환: mid-sync·완성없음(esu==0) surface는 미완성 프레임을 안 그리고 hold하며 스크롤/timeout으로 복구된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 CoreText tick 투영 경로
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    // tab0을 "2026 sync 진입 + ESU 완성 이력 없음(esu==0)" 상태로: BSU를 열었지만 아직 ESU로 완성하지 않은 순간.
    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 0;
    tab0_surface.core.view_offset = 0;
    session.sync_hold_ticks = 0;

    try std.testing.expect(session.switchTab(0));
    try std.testing.expect(session.metal_dirty); // 전환이 재그림을 요청함

    // ★ 전환 후 첫 tick: 새 surface(tab0) 현재 esu=0으로 baseline 리셋 → esu_advanced=(0!=0)=false → sync_blocks=true
    //   → will_project=false. 완성 프레임이 없어 hold(직전 완성 프레임 유지, 미완성 안 그림). metal_dirty 유지.
    _ = try session.tick();
    try std.testing.expect(session.metal_dirty); // ★ held(미완성 프레임 안 그림)

    // timeout 전까지 계속 hold — 완성 프레임이 없어 esu-edge로 자가복구가 안 됨(스크롤 전까진 유지).
    var k: usize = 0;
    while (k < 5) : (k += 1) {
        _ = try session.tick();
        try std.testing.expect(session.metal_dirty);
    }

    // 스크롤(view_offset 변경) → view_scrolled가 sync_blocks를 우회 → 투영 → metal_dirty 해제.
    tab0_surface.core.view_offset = 1; // 스크롤백을 한 줄 위로 본 것 모사
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty); // ★ 스크롤로 복구(전환은 못 풀던 것을 스크롤이 푼다)
    try std.testing.expectEqual(@as(usize, 1), session.last_rendered_view_offset);
}

// ── 회귀: 탭 전환 시 mid-sync(esu>0) surface의 진행 중 프레임을 조기 투영하지 않는다(hold 후 ESU에 투영) ──
// 실제 Claude류 TUI는 완성 프레임 이력이 있어 sync_esu_count>0. 탭 전환의 resizeTabPanes→SIGWINCH가 전체
// clear+repaint(2026 블록)를 유발하는데, "clear됐고 리페인트 전"인 순간에 전환해도 baseline을 새 surface 현재
// esu로 리셋(=core_snap.esu)해 esu_advanced=(N!=N)=false → 전환 tick은 hold(진행 중 빈 프레임 안 그림 = 소멸 방지).
// 새 surface가 ESU로 완성하는 순간 비로소 투영. ⚠️ 예전(=0)엔 esu_advanced=(N!=0)=true로 위조돼 전환 tick에 빈
// 프레임을 강제 투영했다(소멸 버그) — 그 회귀가 재발하면 아래 "전환 tick=hold" 단언이 깨진다.
test "탭 전환: mid-sync(esu>0) surface의 진행 중 프레임을 조기 투영하지 않는다(hold 후 ESU 완성 시 투영)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    // tab0 = SIGWINCH 후 2026 블록 안에서 화면을 지우고 리페인트 전: ?2J로 grid 비우고 sync 진입, 완성 이력 있음(esu=5).
    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.write("\x1b[2J\x1b[H") catch {};
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 5; // 실제 Claude 조건: 이미 완성 프레임 이력 있음(핵심 — esu>0)
    session.sync_hold_ticks = 0;

    try std.testing.expect(session.switchTab(0));
    try std.testing.expect(session.metal_dirty);

    // ★ 전환 후 첫 tick: baseline이 tab0 현재 esu(5)라 esu_advanced=(5!=5)=false → sync_blocks=true → hold.
    //   (예전 =0이면 강제 투영돼 metal_dirty=false = 소멸. 그 회귀를 이 단언이 잡는다.)
    _ = try session.tick();
    try std.testing.expect(session.metal_dirty); // ★ hold — 미완성 프레임을 안 그림

    var k: usize = 0;
    while (k < 5) : (k += 1) {
        _ = try session.tick();
        try std.testing.expect(session.metal_dirty);
    }

    // Claude가 리페인트를 끝내고 ESU로 프레임 완성(sync 해제 + esu 증가) → 이때 비로소 완성 프레임 투영.
    tab0_surface.core.write("repainted content after the resize redraw") catch {};
    tab0_surface.core.sync_output = false;
    tab0_surface.core.sync_esu_count = 6;
    _ = try session.tick();
    try std.testing.expect(!session.metal_dirty); // ★ 완성 프레임이 투영됨 — 소멸 없이 새 탭이 뜬다
}

// ── 회귀: 스크롤된 이전 탭이 있어도 mid-sync surface로 전환 시 view_scrolled로 오투영하지 않는다 [code-review 0/1] ──
// last_rendered_view_offset은 단일 필드다. 이전 탭을 스크롤백 위로 본 채(offset>0) mid-sync·완성 이력 있는(esu>0)
// 탭으로 전환하면, view_offset 리셋이 없으면 view_scrolled=(0 != 이전offset)=true가 sync_blocks를 우회해 진행 중
// (비워진) 프레임을 강제 투영 = 소멸. 수정은 전환 시 last_rendered_view_offset도 새 surface view_offset(0)으로
// 리셋해 view_scrolled=false로 만든다. 이 vector만 격리하려 esu·hold는 안 걸리게(esu_advanced=false·hold=0) 세팅.
test "탭 전환: 스크롤된 이전 탭이 있어도 mid-sync surface로 전환 시 view_scrolled로 오투영하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    // 이전 활성 탭이 스크롤백 위로 본 채 렌더된 상태 모사(마지막 렌더 offset이 0이 아님).
    session.last_rendered_view_offset = 5;

    // tab0 = mid-sync(esu>0), 현재 뷰포트는 라이브(view_offset=0).
    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.write("\x1b[2J\x1b[H") catch {};
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 5; // esu vector 차단(esu_advanced=false가 되게)
    tab0_surface.core.view_offset = 0;
    session.sync_hold_ticks = 0; // hold vector 차단

    try std.testing.expect(session.switchTab(0));
    _ = try session.tick();
    // 수정: last_rendered_view_offset을 tab0 view_offset(0)으로 리셋 → view_scrolled=(0!=0)=false → hold.
    // (리셋 없으면 view_scrolled=(0!=5)=true → 진행 중 프레임 강제 투영 = 소멸.)
    try std.testing.expect(session.metal_dirty); // ★ hold — 스크롤된 이전 탭 때문에 오투영하지 않음
}

// ── 회귀: 이월된 sync_hold_ticks가 timeout을 넘겨도 mid-sync surface로 전환 시 오투영하지 않는다 [code-review 2] ──
// sync_hold_ticks는 단일 필드다. 이전 탭이 mid-sync로 멈춰 hold가 timeout(≈60틱/1초)을 넘긴 채 전환하면, hold
// 리셋이 없으면 새 탭이 그 만료 예산을 이월받아 sync_blocks=false(hold>=timeout)로 진행 중 프레임을 강제 투영
// = 소멸. 수정은 전환 시 sync_hold_ticks=0으로 리셋해 새 surface freeze 예산을 0부터 시작한다.
test "탭 전환: 이월된 sync_hold_ticks가 timeout을 넘겨도 mid-sync surface로 전환 시 오투영하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try setupTwoTabsSettled(allocator);
    defer {
        session.deinit();
        allocator.destroy(session);
    }

    const tab0_surface = session.tabs.items[0].panes.items[0].terms.items[0].surface;
    tab0_surface.core.write("\x1b[2J\x1b[H") catch {};
    tab0_surface.core.sync_output = true;
    tab0_surface.core.sync_esu_count = 5; // esu vector 차단
    tab0_surface.core.view_offset = 0;

    // 이전 탭이 mid-sync로 멈춰 hold가 timeout을 넘긴 상황 모사 — 전환이 이 만료 예산을 이월하면 안 된다.
    session.sync_hold_ticks = session.syncTimeoutTicks() + 5;

    try std.testing.expect(session.switchTab(0));
    _ = try session.tick();
    // 수정: 전환 시 sync_hold_ticks=0 리셋 → hold=1 < timeout → sync_blocks=true → hold.
    // (리셋 없으면 이월된 hold>=timeout이라 sync_blocks=false → 진행 중 프레임 강제 투영 = 소멸.)
    try std.testing.expect(session.metal_dirty); // ★ hold — 이월된 hold 예산으로 오투영하지 않음
}

test "chrome_minimal session suppresses the pane tab bar and the sidebar" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // refreshCellMetrics가 CoreText 메트릭 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        .chrome_minimal = 1,
    });
    defer session.deinit();

    // minimal: 사이드바 폭 0(refreshCellMetrics 게이트), 탭 바 높이 0(paneBarHeightPx 게이트) →
    // paneBarRect가 null, paneTermRect는 바를 빼지 않는다. window padding은 0으로 격리해 바 기하만 본다
    // (paneTermRect가 이제 padding도 inset — minimal grid의 padding 동작은 별도 테스트가 커버).
    session.window_padding_px = .{};
    try std.testing.expectEqual(@as(u32, 0), session.sidebar_width_px);
    try std.testing.expectEqual(@as(u32, 0), session.paneBarHeightPx());
    const rect: maru.session.SplitRect = .{ .x = 0, .y = 0, .w = 800, .h = 600 };
    try std.testing.expect(session.paneBarRect(rect) == null);
    const term = session.paneTermRect(rect);
    try std.testing.expectEqual(@as(u32, 0), term.y);
    try std.testing.expectEqual(@as(u32, 600), term.h);
}

test "minimal scratch session blocks new_tab/new_term; minimal_tabs re-enables them" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY spawn(newTab/newTermInActivePane)
    const allocator = std.testing.allocator;

    // ① chrome_minimal + minimal_tabs=0(기본 스크래치): 탭/Term 생성 액션이 무동작.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 0,
        });
        defer session.deinit();
        try std.testing.expect(session.tabsBlocked());
        try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
        try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);
        session.dispatchAppAction(.new_tab);
        session.dispatchAppAction(.new_term);
        try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len); // 새 워크스페이스 안 생김
        try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len); // 새 Term 안 생김
    }

    // ② chrome_minimal + minimal_tabs=1: 탭/Term 생성이 다시 동작.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 1,
        });
        defer session.deinit();
        try std.testing.expect(!session.tabsBlocked());
        session.dispatchAppAction(.new_term); // 활성 pane에 Term 추가
        try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
        session.dispatchAppAction(.new_tab); // 새 워크스페이스
        try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    }
}

test "minimal tab indicator: adaptive dots appear only in minimal with >1 tab" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // refreshCellMetrics(cell_width_px) + 실 PTY
    const allocator = std.testing.allocator;
    var out: std.ArrayList(metal_frame.NativeMetalCell) = .empty;
    defer out.deinit(allocator);

    // ① minimal + minimal_tabs: 단일이면 무동작, Term 2개면 strip+점2개(활성=마지막에 그려진 셀).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 1,
        });
        defer session.deinit();
        _ = try session.resize(800, 600, 1000); // backing 폭을 잡아야 termRect.w>0(인디케이터 폭 계산)

        out.clearRetainingCapacity();
        session.appendMinimalTabIndicator(&out);
        try std.testing.expectEqual(@as(usize, 0), out.items.len); // 탭 1개 → 점 없음

        session.dispatchAppAction(.new_term); // Term 2개(새 Term이 활성 = index 1)
        out.clearRetainingCapacity();
        session.appendMinimalTabIndicator(&out);
        try std.testing.expectEqual(@as(usize, 3), out.items.len); // strip + 점 2개
        try std.testing.expectEqual(session.sidebarBg(), out.items[0].background); // strip
        try std.testing.expectEqual(session.sidebarHoverBg(), out.items[1].background); // 비활성 점(i=0)
        try std.testing.expectEqual(session.sidebarActiveBg(), out.items[2].background); // 활성 점(i=1)
        // 점은 strip 안에서 우상단(row 0), 활성 점이 비활성보다 오른쪽(+2칸).
        try std.testing.expectEqual(@as(u16, 0), out.items[2].row);
        try std.testing.expectEqual(out.items[1].col + 2, out.items[2].col);

        // 워크스페이스가 여러 개면 그쪽을 우선 표시(차원 전환). 새 워크스페이스 = 활성 index 1.
        session.dispatchAppAction(.new_tab);
        out.clearRetainingCapacity();
        session.appendMinimalTabIndicator(&out);
        try std.testing.expectEqual(@as(usize, 3), out.items.len); // 워크스페이스 2개 → strip + 점 2개
        try std.testing.expectEqual(session.sidebarActiveBg(), out.items[2].background); // 활성 워크스페이스(index 1)

        // band가 화면보다 넓으면(아주 좁은 패널) 아예 안 그린다 — 좌상단 relocate 방지(우상단에 안 들어가면 skip).
        _ = try session.resize(16, 200, 1000); // 폭 16px → cols ≤ 2, band(2 워크스페이스=5)+margin > cols
        out.clearRetainingCapacity();
        session.appendMinimalTabIndicator(&out);
        try std.testing.expectEqual(@as(usize, 0), out.items.len);
    }

    // ② full(chrome_minimal=0): 탭이 여러 개여도 인디케이터 없음(사이드바·탭 바가 보여줌).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 0,
        });
        defer session.deinit();
        session.dispatchAppAction(.new_term); // Term 2개(full은 게이트 없음)
        try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
        out.clearRetainingCapacity();
        session.appendMinimalTabIndicator(&out);
        try std.testing.expectEqual(@as(usize, 0), out.items.len); // full → 무동작
    }
}

test "command catalog: 엔트리·바인딩 표시 + runAction 디스패치" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 init(loaded_config resolver) + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const catalog = session.commandCatalog();
    try std.testing.expectEqual(command_catalog.entries.len, catalog.len);
    // new_term 엔트리: 제목 + 빌트인 Cmd+T 바인딩 표시. close_tab: 기본 바인딩 없어 빈 표시.
    var saw_new_term = false;
    var saw_close_tab = false;
    for (catalog) |e| {
        const key = std.mem.span(e.action_key);
        if (std.mem.eql(u8, key, "new_term")) {
            try std.testing.expectEqualStrings("New Terminal", std.mem.span(e.title));
            try std.testing.expectEqualStrings("⌘T", std.mem.span(e.key_display));
            try std.testing.expectEqualStrings("t", std.mem.span(e.key_equivalent)); // NSMenuItem keyEquivalent
            try std.testing.expectEqual(command_catalog.mod_command, e.key_modifiers);
            saw_new_term = true;
        } else if (std.mem.eql(u8, key, "close_tab")) {
            try std.testing.expectEqualStrings("", std.mem.span(e.key_display)); // 기본 바인딩 없음
            try std.testing.expectEqualStrings("", std.mem.span(e.key_equivalent));
            try std.testing.expectEqual(@as(u32, 0), e.key_modifiers);
            saw_close_tab = true;
        }
    }
    try std.testing.expect(saw_new_term and saw_close_tab);

    // runAction: new_term → 활성 pane Term +1(full 세션이라 tabsBlocked=false). 모르는 키는 false·무동작.
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);
    try std.testing.expect(session.runAction("new_term"));
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expect(!session.runAction("bogus_action"));
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
}

test "command palette(chrome): 토글 열림 → 타이핑 필터 → IME 조합 표시 → Enter 디스패치+닫힘 → 프레임 빌드" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 메트릭·backing(palette.view가 chrome props로 씀)

    // 토글로 열린다(chrome palette 컴포넌트) — 빈 쿼리라 전체 카탈로그가 필터에(platform palette_filtered).
    try std.testing.expect(!session.chrome_host.palette.open);
    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(session.chrome_host.palette.open);
    try std.testing.expectEqual(command_catalog.entries.len, session.palette_filtered.items.len);
    try std.testing.expectEqual(command_catalog.entries.len, session.chrome_host.palette.result_count); // 컴포넌트 동기화

    // IME 조합 회귀(C1b 버그 수정): 팝업 열린 동안 marked text가 팝업 preedit에 들어간다(뒤의 터미널 core가 아니라).
    // 레거시 팝업은 IME 조합 배선이 없어 한글 조합이 숨은 터미널로 샜다.
    session.imeMarked("\xea\xb0\x80"); // 조합 중 "가"
    try std.testing.expectEqualStrings("\xea\xb0\x80", session.chrome_host.palette.input.preedit.items);
    try std.testing.expect(!session.activeSurface().preedit.active()); // 터미널 Surface overlay로 안 샌다
    session.imeMarked(""); // 조합 해제(확정 직전)

    // "new t" 타이핑(chrome 라우팅 → palette.handle → query_changed → recomputePalette) → "New Terminal"만 남는다.
    for ("new t") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.palette_filtered.items.len);
    try std.testing.expect(command_palette.actionAt(session.palette_filtered.items, session.chrome_host.palette.selected).? == .new_term);

    // Enter → accept → acceptPalette가 new_term 실행(full이라 게이트 없음) 후 닫힘. 활성 pane Term +1.
    const before = session.activePane().terms.items.len;
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.palette.open);
    try std.testing.expectEqual(before + 1, session.activePane().terms.items.len);

    // 다시 열고 Esc로 닫힌다.
    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(session.chrome_host.palette.open);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.palette.open);

    // 열린 상태에서 chrome 오버레이 프레임 빌드가 크래시 없이 셀을 낸다(palette.view → 일반 rasterizer).
    session.dispatchAppAction(.toggle_command_palette);
    var pf = try testBuildChromeOverlayFrame(session);
    defer pf.frame.deinit(allocator);
    try std.testing.expect(pf.frame.draw_list.cells.len > 0);

    // 회귀(메뉴 모달 우회): 팝업이 열린 동안 메뉴바 keyEquivalent 경로(runAction)는 무시된다 — 모달 뒤 터미널이
    // 조작되면 안 된다. (팝업 자신의 Enter는 chrome_host.handleInput → dispatchChromeAction이 처리하므로 별개.)
    try std.testing.expect(session.chrome_host.palette.open);
    const terms_before_runaction = session.activePane().terms.items.len;
    try std.testing.expect(!session.runAction("new_term"));
    try std.testing.expectEqual(terms_before_runaction, session.activePane().terms.items.len);

    // caret 깜빡임: 팝업이 열린 프레임을 tick으로 빌드하면 cursor_cells=1(팝업 입력 caret이 맨 끝 suffix) — 이제
    // caret이 터미널 커서와 같은 suffix-trim 깜빡임을 탄다. (예전엔 0으로 고정해 정적이었음 — caret 깜빡임 추가로 변경.)
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 1), session.metal_buffer.cursor_cells);
}

test "scrollback find(chrome): 토글 열림 → 증분 검색 → 매치 네비게이션 → 하이라이트·오버레이 프레임" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 메트릭·backing(find.view가 chrome props로 씀)

    // 검색 대상 텍스트를 코어에 직접 쓴다(유니크 토큰 2곳 — 셸 출력과 충돌 없게).
    try session.activeSurface().core.write("MARUFIND one\r\ntwo MARUFIND three");

    // 토글로 열린다(chrome find 컴포넌트) — 빈 검색어라 매치 0. 매치 리스트는 session(find_matches) 소유.
    try std.testing.expect(!session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);

    // "MARUFIND" 타이핑(chrome 라우팅 → find.handle → query_changed → recomputeFind) → 2곳 매치, 현재는 첫 매치.
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 2), session.find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.match_count); // 컴포넌트 카운트 동기화
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // Enter=다음 매치, Shift+Enter=이전(wrap). 모디파이어가 chrome.input으로 매핑돼 Shift가 prev로 간다.
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{ .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // Backspace로 한 글자 지워도("MARUFIN") 부분일치라 두 곳 다 매치 유지.
    _ = try session.handleKeyEvent(.{ .key = .backspace, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 2), session.find_matches.items.len);

    // chrome 오버레이 프레임 빌드가 크래시 없이 셀을 낸다(find.view → 일반 rasterizer: "Find: …" + 카운터).
    var ff = try testBuildChromeOverlayFrame(session);
    defer ff.frame.deinit(allocator);
    try std.testing.expect(ff.frame.draw_list.cells.len > 0);

    // 회귀: Find 열린 동안 메뉴 keyEquivalent(runAction)는 무시된다(모달 뒤 터미널 조작 차단).
    try std.testing.expect(!session.runAction("new_term"));

    // tick으로 Find 열린 프레임을 빌드하면 cursor_cells=1(Find 입력 caret이 맨 끝 suffix) — caret이 터미널 커서와
    // 같은 suffix-trim 깜빡임을 탄다(예전엔 0 고정으로 정적이었음 — caret 깜빡임 추가로 변경).
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 1), session.metal_buffer.cursor_cells);

    // ⌘+글자는 검색어에 안 쌓고 닫는다(평문만 입력) — 위 흐름에서 find가 아직 열려 있다.
    try std.testing.expect(session.chrome_host.find.open);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true } });
    try std.testing.expect(!session.chrome_host.find.open);

    // 다시 열고 Esc로 닫힌다.
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
}

test "find ⌘G/⌘⇧G: 오버레이 닫힌 채 다음/이전 매치 네비(보존 검색어 재검색·타이핑이 종료)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY(controlled_smoke)
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);
    try session.activeSurface().core.write("MARUFIND one\r\ntwo MARUFIND three\r\nMARUFIND four"); // 3곳 매치

    // 검색: 열고 타이핑 → 3곳 매치, 현재 0.
    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 3), session.find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // Esc로 닫기 — 매치 정리, 검색어 보존, find_nav false.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.find.open);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);
    try std.testing.expect(!session.find_nav);
    try std.testing.expect(session.chrome_host.find.input.query.items.len > 0); // 검색어 보존(hide는 안 비움)

    // ⌘G(닫힌 채): 보존 검색어로 재검색 + 다음 매치(0→1) + find_nav 세움.
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav);
    try std.testing.expectEqual(@as(usize, 3), session.find_matches.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.find.current);
    try std.testing.expect(!session.chrome_host.find.open); // 오버레이는 여전히 닫힘

    // ⌘G 두 번 더 → 2 → 0(wrap).
    session.dispatchAppAction(.find_next);
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.current);
    session.dispatchAppAction(.find_next);
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.find.current);

    // ⌘⇧G(이전) → 2(뒤로 wrap).
    session.dispatchAppAction(.find_previous);
    try std.testing.expectEqual(@as(usize, 2), session.chrome_host.find.current);

    // 닫힌 채 네비 중 tick 프레임 빌드가 크래시 없이 동작(현재 매치만 하이라이트 — cell_colors 경로).
    _ = try session.tick();

    // 셸에 타이핑 재개 = 검색 종료 → find_nav 해제 + 매치 정리.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'x' }, .modifiers = .{} });
    try std.testing.expect(!session.find_nav);
    try std.testing.expectEqual(@as(usize, 0), session.find_matches.items.len);

    // 빈 검색어면 ⌘G 무동작(새로 열어 show가 검색어를 비우고, 닫은 뒤 find_next).
    session.dispatchAppAction(.toggle_find); // show → query clear
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    session.dispatchAppAction(.find_next);
    try std.testing.expect(!session.find_nav); // 검색어 없음 — 무동작
}

test "alt screen에서도 maru Find가 열린다(⌘F 동작·진입해도 tick이 안 닫음 — 현재 화면 검색)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // 메인 화면: ⌘F가 Find를 연다(정상).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find); // 닫기
    try std.testing.expect(!session.chrome_host.find.open);

    // alt screen 진입(DECSET 1049 — vim/less/Claude/Codex).
    try session.activeSurface().core.write("\x1b[?1049h");
    try std.testing.expect(session.activeSurface().core.alt_active);

    // alt에서도 ⌘F가 Find를 연다 — alt에선 findMatches가 현재 화면만 검색한다(과거엔 iTerm2 관례로 막았음).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    session.dispatchAppAction(.toggle_find); // 닫기
    try std.testing.expect(!session.chrome_host.find.open);

    // 엣지: 메인에서 Find를 연 뒤 앱이 출력으로 alt에 들어가도 tick이 Find를 닫지 않는다(현재 화면 검색 유지).
    try session.activeSurface().core.write("\x1b[?1049l"); // 메인 복귀
    try std.testing.expect(!session.activeSurface().core.alt_active);
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open); // 메인에선 열림
    try session.activeSurface().core.write("\x1b[?1049h"); // 앱이 alt 진입
    _ = try session.tick();
    try std.testing.expect(session.chrome_host.find.open); // tick이 닫지 않음(유지)
}

test "alt screen Find: 실제 쿼리가 현재 화면만 매치하고 ⌘G가 동작한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY(controlled_smoke)
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // primary 스크롤백에 needle "MARUHIT"를 출력한 뒤 화면(6행) 밖으로 밀어낸다(대조군 — alt에선 제외돼야).
    try session.activeSurface().core.write("MARUHIT primary\r\n");
    var i: usize = 0;
    while (i < 10) : (i += 1) try session.activeSurface().core.write("pad\r\n");

    // alt 진입 + alt 화면에 needle 한 곳.
    try session.activeSurface().core.write("\x1b[?1049h");
    try std.testing.expect(session.activeSurface().core.alt_active);
    try session.activeSurface().core.write("MARUHIT alt line");

    // Find 열고 "MARUHIT" 타이핑 → recompute가 현재 화면(alt)만 스캔해 1곳 매치(primary 스크롤백 제외).
    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    for ("MARUHIT") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqual(@as(usize, 1), session.find_matches.items.len); // alt 화면 1곳만(스크롤백 제외)

    // ⌘G(오버레이 닫힌 채): alt에서도 findNavigate가 동작한다(과거엔 무동작이었음) — 보존 검색어 재검색 + find_nav.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} }); // 닫기(검색어 보존)
    try std.testing.expect(!session.chrome_host.find.open);
    session.dispatchAppAction(.find_next);
    try std.testing.expect(session.find_nav); // alt에서 ⌘G 동작(억제 안 됨)
    try std.testing.expectEqual(@as(usize, 1), session.find_matches.items.len);
}

test "find IME 멀티-문자: 커밋이 다음 조합 preedit를 안 지운다(조합 안 보임 회귀)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // handleKeyEvent → chrome 라우팅, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);

    // 실제 IME 흐름(라이브 로그와 동일): setMarkedText "나" → insertText "나"(커밋) → setMarkedText "다"(다음 조합).
    // 한 keyDown 트랜잭션 안에서 일어난다.
    session.imeBegin();
    session.imeMarked("\xeb\x82\x98"); // 조합 "나"
    session.imeInsert("\xeb\x82\x98"); // "나" 커밋 누적
    session.imeMarked("\xeb\x8b\xa4"); // 다음 조합 "다"
    session.imeEnd(null);

    // 커밋 "나"는 검색어로, 조합 "다"는 preedit로 **유지**돼야 한다. 예전엔 imeEnd의 커밋(appendChar)이 방금 set된
    // "다"를 지워 조합이 화면에서 사라졌다(사용자 제보 "입력중 상태 안 보임"). 단일 출처·core 모델 통일로 수정.
    try std.testing.expectEqualStrings("\xeb\x82\x98", session.chrome_host.find.input.query.items); // "나" 확정
    try std.testing.expectEqualStrings("\xeb\x8b\xa4", session.chrome_host.find.input.preedit.items); // "다" 조합 유지
}

test "오버레이 배타 + IME 단일 출처: showNotice가 find/palette를 닫고 notice가 최우선(IME 무시)·toggle이 notice를 닫음" {
    // 경량 — show/toggle·inputFocus·IME 헬퍼만 탄다(CoreText/PTY 불필요). undefined 세션은 이들이 읽는 필드만 초기화.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.chrome_host = .{}; // inputFocus가 notice/find/palette.open을 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null; // inputFocus가 rename을 읽음([[devsession-undefined-test-field-trap]])
    session.addr_edit = null; // 7e-2b: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false;
    session.focus_owner = .workspace; // inputFocus가 file-tree owner를 읽음([[devsession-undefined-test-field-trap]])
    session.find_matches = .empty; // toggleFind/showNotice가 clearRetainingCapacity 호출
    session.palette_filtered = .empty; // togglePalette→recomputePalette가 채운다
    session.pending_confirm = .none; // showNotice→cancelPendingClose가 읽음([[devsession-undefined-test-field-trap]])
    session.metal_dirty = false;
    session.ime_terminal_target_id = null; // IME 라우팅이 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])
    session.file_content_menu = null; // showNotice→closeContextMenu가 읽음([[devsession-undefined-test-field-trap]])
    defer {
        session.chrome_host.deinit(std.testing.allocator);
        session.find_matches.deinit(std.testing.allocator);
        session.palette_filtered.deinit(std.testing.allocator);
    }

    // 오버레이 없음 → terminal
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // find 열림 → .find
    session.toggleFind();
    try std.testing.expect(session.chrome_host.find.open);
    try std.testing.expectEqual(AppSession.InputFocus.find, session.inputFocus());

    // showNotice가 find를 닫는다(#2 배타) — notice가 최우선 포커스(#3)
    session.showNotice("corrupt");
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expect(!session.chrome_host.find.open); // #2: 두 박스가 합쳐진 frame으로 안 깨짐
    try std.testing.expectEqual(AppSession.InputFocus.notice, session.inputFocus()); // #3: 최우선
    // #3: notice 중 IME 연산은 무시 — 조합이 뒤(find/터미널)로 새지 않는다
    session.imeSetPreedit("\xea\xb0\x80"); // "가"
    try std.testing.expect(!session.imeComposingActive());

    // toggleFind가 notice를 닫는다(#2)
    session.toggleFind();
    try std.testing.expect(!session.chrome_host.notice.open); // #2
    try std.testing.expect(session.chrome_host.find.open);

    // togglePalette가 notice·find를 닫는다(#2) → palette 포커스
    session.showNotice("corrupt2");
    try std.testing.expect(!session.chrome_host.find.open); // showNotice가 find도 닫음
    session.togglePalette();
    try std.testing.expect(!session.chrome_host.notice.open); // #2
    try std.testing.expect(session.chrome_host.palette.open);
    try std.testing.expectEqual(AppSession.InputFocus.palette, session.inputFocus());
}

test "IME 라우팅: 세팅 모달 열림이면 inputFocus=.settings이라 조합/확정 텍스트가 검색줄로(터미널로 안 샘)" {
    // 경량 — inputFocus/IME preedit·compose만 탄다(CoreText/PTY 불필요). undefined 세션은 이들이 읽는 필드만 초기화.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.chrome_host = .{}; // inputFocus가 settings/notice/find/palette.open을 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null; // inputFocus가 rename을 읽음
    session.addr_edit = null; // 7e-2b: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false; // inputFocus가 읽음(설정 안 하면 UB로 .sidebar_search 오판)
    session.focus_owner = .workspace; // inputFocus가 file-tree owner를 읽음([[devsession-undefined-test-field-trap]])
    session.find_matches = .empty;
    session.palette_filtered = .empty;
    session.metal_dirty = false;
    session.ime_terminal_target_id = null; // IME 라우팅이 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])
    defer {
        session.chrome_host.deinit(std.testing.allocator);
        session.find_matches.deinit(std.testing.allocator);
        session.palette_filtered.deinit(std.testing.allocator);
    }

    // 세팅 안 열림 → terminal.
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // 세팅 모달 열림 → .settings. 이게 핵심 — 예전엔 inputFocus에 settings가 없어 macOS 확정 텍스트가 .terminal로
    // 라우팅돼 검색어가 뒤 터미널로 샜다(검색 입력이 안 되던 근본 원인). 회귀 가드.
    session.chrome_host.settings.show();
    session.chrome_host.settings.startSearch();
    try std.testing.expectEqual(AppSession.InputFocus.settings, session.inputFocus());

    // IME 조합(marked)이 세팅 검색 preedit로 들어간다(뒤 터미널/find로 안 샘) — imeComposingActive도 반영.
    session.imeSetPreedit("\xea\xb0\x80"); // "가"
    try std.testing.expect(session.imeComposingActive());
    try std.testing.expectEqualStrings("\xea\xb0\x80", session.chrome_host.settings.searchPreedit());
    // 조합 해제(빈 bytes) → 조합 없음.
    session.imeSetPreedit("");
    try std.testing.expect(!session.imeComposingActive());
}

test "imeBegin: 터미널 포커스만 바닥으로 스냅 — find 조합은 뒤 터미널 스크롤백을 보존(#4)" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 5 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.metal_dirty = false;
    session.chrome_host = .{}; // inputFocus가 읽음
    session.rename = null; // inputFocus가 rename을 읽음([[devsession-undefined-test-field-trap]])
    session.addr_edit = null; // 7e-2b: inputFocus가 addr_edit을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false;
    session.focus_owner = .workspace; // inputFocus가 file-tree owner를 읽음([[devsession-undefined-test-field-trap]])
    session.tabs = .empty; // [4e-2] scrollPage 게이트 activeTermIsTerminal이 tabs를 읽음 — 빈 트리=terminal 취급(byte-identical)
    session.ime_inserted = .empty; // imeBegin이 clearRetainingCapacity 호출
    session.ime_terminal_target_id = null; // imeBegin이 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])
    session.ime_terminal_target_tombstoned = false;
    defer session.chrome_host.deinit(std.testing.allocator);
    defer session.ime_inserted.deinit(std.testing.allocator);

    // 9줄 출력 → 5행 화면 위로 4줄 스크롤백
    try tab_surface.core.write("1\r\n2\r\n3\r\n4\r\n5\r\n6\r\n7\r\n8\r\n9");
    session.scrollPage(1); // 위로 한 화면
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset);

    // (a) 터미널 포커스: imeBegin이 바닥으로 스냅한다(조합도 타이핑 — preedit이 보이게)
    session.imeBegin();
    try std.testing.expectEqual(@as(usize, 0), tab_surface.core.view_offset);
    session.imeEnd(null); // 실제 keyDown처럼 트랜잭션을 닫아 terminal pin을 해제한다.

    // 다시 위로 스크롤
    session.scrollPage(1);
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset);

    // (b) find 포커스: imeBegin은 뒤 터미널을 건드리지 않는다(#4 — 조합은 find 입력칸으로 간다)
    session.chrome_host.find.open = true;
    session.imeBegin();
    try std.testing.expectEqual(@as(usize, 4), tab_surface.core.view_offset); // 보존
}

test "find overlay: 한글(wide)은 atlas slot이 2칸 — ㄱㄴㄷ 잘림 회귀 실측(실 CoreText)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    session.dispatchAppAction(.toggle_find);
    try std.testing.expect(session.chrome_host.find.open);
    // 'A'(ASCII, span 1)와 '가'(U+AC00, EAW-Wide span 2)를 같은 오버레이 frame에 그린다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'A' }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '가' }, .modifiers = .{} });

    // scale 1.0과 Retina 2.0 둘 다 검증 — 실제 맥 화면은 2.0이라 1.0만으론 라이브 경로(오버레이 셀 × scale)를
    // 못 잡는다. 같은 세션에서 resize를 반복해 공유 atlas가 두 메트릭을 함께 들었을 때도 잘림이 없는지 본다.
    for ([_]u32{ 1000, 2000 }) |scale_milli| {
        _ = try session.resize(800, 600, scale_milli);
        var ff = try testBuildChromeOverlayFrame(session);
        defer ff.frame.deinit(allocator);

        // caret 재활용: cursor-role fill이 **cursor 오버레이**(glyph_quad_frame.overlays의 .cursor, visible)로 lower돼야
        // 한다 — buildNativeCellsSplit이 이걸 반전-블록으로 그리고 suffix-trim으로 깜빡인다. draw_list.cursor 필드만으론
        // 안 그려진다(렌더는 overlays를 본다). 회귀: caret이 안 보이던 버그(overlays 누락) 고정.
        var has_caret = false;
        for (ff.frame.glyph_quad_frame.overlays) |ov| {
            if (ov == .cursor and ov.cursor.visible) has_caret = true;
        }
        try std.testing.expect(has_caret);

        // 실측: 결과 글리프에서 '가'와 'A'의 cell_width(span)와 atlas slot 픽셀 폭을 뽑는다.
        var ga_span: ?u2 = null;
        var ga_slot_w: u32 = 0;
        var a_slot_w: u32 = 0;
        for (ff.frame.glyph_quad_frame.glyphs) |q| {
            if (q.run.codepoint == '가') {
                ga_span = q.run.cell_width;
                ga_slot_w = q.slot.width_px;
            } else if (q.run.codepoint == 'A') {
                a_slot_w = q.slot.width_px;
            }
        }
        // 핵심: '가'는 span=2여야 하고, atlas slot이 ASCII(span 1)의 2배 폭이어야 wide 글리프가 안 잘린다.
        // slot이 1칸이면 rasterizer가 글자를 1칸에 가운데정렬+우측 클립해 왼쪽 절반(ㄱ)만 남는다.
        try std.testing.expectEqual(@as(?u2, 2), ga_span);
        try std.testing.expect(a_slot_w > 0);
        try std.testing.expectEqual(a_slot_w * 2, ga_slot_w);
    }
}

test "command palette(chrome): 한글(wide) query는 atlas slot이 2칸 — ㄱㄴㄷ 잘림 회귀 실측(실 CoreText)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildChromeOverlayFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    session.dispatchAppAction(.toggle_command_palette);
    try std.testing.expect(session.chrome_host.palette.open);
    // 'A'(ASCII, span 1)와 '가'(U+AC00, span 2)를 팝업 쿼리에 입력 — row0 프롬프트 "> A가"로 그려진다(필터 결과는
    // 0이어도 쿼리 글리프는 frame에 있다). C1b 전 팝업(putUtf8 span=1)이면 '가'가 1칸 slot에 잘렸다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'A' }, .modifiers = .{} });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '가' }, .modifiers = .{} });

    // scale 1.0·Retina 2.0 둘 다(실제 맥은 2.0).
    for ([_]u32{ 1000, 2000 }) |scale_milli| {
        _ = try session.resize(800, 600, scale_milli);
        var ff = try testBuildChromeOverlayFrame(session);
        defer ff.frame.deinit(allocator);

        // caret 재활용: cursor-role fill이 cursor 오버레이(glyph_quad_frame.overlays의 .cursor, visible)로 lower돼 터미널
        // 커서와 같은 반전-블록 경로로 그려지고 깜빡인다(draw_list.cursor 필드만으론 안 그려짐 — 회귀 고정).
        var has_caret = false;
        for (ff.frame.glyph_quad_frame.overlays) |ov| {
            if (ov == .cursor and ov.cursor.visible) has_caret = true;
        }
        try std.testing.expect(has_caret);

        var ga_span: ?u2 = null;
        var ga_slot_w: u32 = 0;
        var a_slot_w: u32 = 0;
        for (ff.frame.glyph_quad_frame.glyphs) |q| {
            if (q.run.codepoint == '가') {
                ga_span = q.run.cell_width;
                ga_slot_w = q.slot.width_px;
            } else if (q.run.codepoint == 'A') {
                a_slot_w = q.slot.width_px;
            }
        }
        try std.testing.expectEqual(@as(?u2, 2), ga_span); // 팝업 '가'도 span=2(find와 같은 경로)
        try std.testing.expect(a_slot_w > 0);
        try std.testing.expectEqual(a_slot_w * 2, ga_slot_w); // 2칸 slot — 안 잘림
    }
}

test "rasterizeOverlayCells: 다중 fill(painter order) + 다중 행 text → 셀 그리드(헤드리스)" {
    const allocator = std.testing.allocator;
    const c = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    // 2색이 구분되게 토큰을 만든다: surface_bg=(2,2,2), selection=(7,7,7).
    const tk = chrome.tokens.Tokens.tui(.{
        .foreground = c.rgb(1, 1, 1),
        .sidebar_background = c.rgb(2, 2, 2),
        .sidebar_foreground = c.rgb(3, 3, 3),
        .sidebar_active = c.rgb(4, 4, 4),
        .search_match = c.rgb(5, 5, 5),
        .search_match_current = c.rgb(6, 6, 6),
        .selection = c.rgb(7, 7, 7),
        .cursor = c.rgb(8, 8, 8),
        .accent = c.rgb(9, 9, 9),
    });
    // cw=10, ch=20. 패널 2칸×2행(0,0,20,40). row1만 selection으로 덮고(painter order), 각 행에 텍스트.
    const run_ab = [_]chrome.draw.Run{.{ .text = "ab" }};
    const run_cd = [_]chrome.draw.Run{.{ .text = "cd" }};
    const ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 20, .h = 40 }, .role = .surface_bg } },
        .{ .fill = .{ .rect = .{ .x = 0, .y = 20, .w = 20, .h = 20 }, .role = .selection } },
        .{ .text = .{ .origin = .{ .x = 0, .y = 0 }, .runs = &run_ab, .role = .surface_fg } },
        .{ .text = .{ .origin = .{ .x = 0, .y = 20 }, .runs = &run_cd, .role = .surface_fg } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};

    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);

    try std.testing.expectEqual(@as(u16, 2), raster.cols);
    try std.testing.expectEqual(@as(u16, 2), raster.rows);
    try std.testing.expectEqual(@as(u32, 0), raster.origin_x);
    try std.testing.expectEqual(@as(u32, 0), raster.origin_y);
    try std.testing.expectEqual(@as(usize, 4), raster.cells.items.len);
    // 행 0: "ab" + surface_bg, 행 1: "cd" + selection(나중 fill이 이김).
    try std.testing.expectEqual(@as(u21, 'a'), raster.cells.items[0].codepoint);
    try std.testing.expectEqual(@as(u21, 'b'), raster.cells.items[1].codepoint);
    try std.testing.expectEqual(@as(u21, 'c'), raster.cells.items[2].codepoint);
    try std.testing.expectEqual(@as(u21, 'd'), raster.cells.items[3].codepoint);
    try std.testing.expectEqual(c.rgb(2, 2, 2), raster.cells.items[0].style.background.rgb); // row0 surface_bg
    try std.testing.expectEqual(c.rgb(7, 7, 7), raster.cells.items[2].style.background.rgb); // row1 selection(painter order)
}

test "rasterizeOverlayCells: draw.Op.clip → OverlayRaster.clip_rect(렌더러 scissor 인프라, 안 그림)" {
    const allocator = std.testing.allocator;
    const cc = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    const tk = chrome.tokens.Tokens.tui(.{
        .foreground = cc.rgb(1, 1, 1),
        .sidebar_background = cc.rgb(2, 2, 2),
        .sidebar_foreground = cc.rgb(3, 3, 3),
        .sidebar_active = cc.rgb(4, 4, 4),
        .search_match = cc.rgb(5, 5, 5),
        .search_match_current = cc.rgb(6, 6, 6),
        .selection = cc.rgb(7, 7, 7),
        .cursor = cc.rgb(8, 8, 8),
        .accent = cc.rgb(9, 9, 9),
    });
    // clip op은 그리지 않고(셀·bounding-box 무영향) OverlayRaster.clip_rect로만 모인다 — 렌더러가 모달 셀 draw에 scissor.
    var ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 10, .h = 20 }, .role = .surface_bg } },
        .{ .clip = .{ .x = 5, .y = 10, .w = 100, .h = 50 } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};
    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);
    try std.testing.expect(raster.clip_rect != null);
    try std.testing.expectEqual(@as(i32, 5), raster.clip_rect.?.x);
    try std.testing.expectEqual(@as(i32, 10), raster.clip_rect.?.y);
    try std.testing.expectEqual(@as(u32, 100), raster.clip_rect.?.w);
    try std.testing.expectEqual(@as(u32, 50), raster.clip_rect.?.h);

    // clip op이 없으면 null = 클리핑 없음(기존 동작 무변).
    var ops2 = [_]chrome.draw.Op{.{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 10, .h = 20 }, .role = .surface_bg } }};
    const draws2 = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops2 }};
    var raster2 = try AppSession.rasterizeOverlayCells(allocator, &draws2, &tk, 10, 20, false);
    defer raster2.cells.deinit(allocator);
    defer raster2.gpu_quads.deinit(allocator);
    defer raster2.gpu_shadows.deinit(allocator);
    try std.testing.expect(raster2.clip_rect == null);
}

test "rasterizeOverlayCells: wide 글리프 뒤 continuation 칸은 emit 안 함(배경이 글리프 안 덮게 — ㄱ 잘림 회귀)" {
    const allocator = std.testing.allocator;
    const cc = struct {
        fn rgb(r: u8, g: u8, b: u8) maru.color.Rgb {
            return .{ .r = r, .g = g, .b = b };
        }
    };
    const tk = chrome.tokens.Tokens.tui(.{
        .foreground = cc.rgb(1, 1, 1),
        .sidebar_background = cc.rgb(2, 2, 2),
        .sidebar_foreground = cc.rgb(3, 3, 3),
        .sidebar_active = cc.rgb(4, 4, 4),
        .search_match = cc.rgb(5, 5, 5),
        .search_match_current = cc.rgb(6, 6, 6),
        .selection = cc.rgb(7, 7, 7),
        .cursor = cc.rgb(8, 8, 8),
        .accent = cc.rgb(9, 9, 9),
    });
    // cw=10, ch=20. 패널 4칸×1행. "가b" — '가'(wide=2칸) col0, 'b' col2. continuation 칸(col1)은 emit 안 돼야 한다.
    const run = [_]chrome.draw.Run{.{ .text = "가b" }};
    const ops = [_]chrome.draw.Op{
        .{ .fill = .{ .rect = .{ .x = 0, .y = 0, .w = 40, .h = 20 }, .role = .surface_bg } },
        .{ .text = .{ .origin = .{ .x = 0, .y = 0 }, .runs = &run, .role = .surface_fg } },
    };
    const draws = [_]chrome.ChromeDraw{.{ .layer = .modal, .ops = &ops }};

    var raster = try AppSession.rasterizeOverlayCells(allocator, &draws, &tk, 10, 20, false);
    defer raster.cells.deinit(allocator);
    defer raster.gpu_quads.deinit(allocator);
    defer raster.gpu_shadows.deinit(allocator);

    try std.testing.expectEqual(@as(u16, 4), raster.cols);
    // 셀: 가@col0(w2) + b@col2 + space@col3 = 3개. continuation col1은 스킵(emit하면 그 배경이 '가' 오른쪽 절반을 덮음).
    try std.testing.expectEqual(@as(usize, 3), raster.cells.items.len);
    try std.testing.expectEqual(@as(u21, '가'), raster.cells.items[0].codepoint);
    try std.testing.expectEqual(@as(u16, 0), raster.cells.items[0].col);
    try std.testing.expectEqual(@as(u2, 2), raster.cells.items[0].width); // wide
    try std.testing.expectEqual(@as(u21, 'b'), raster.cells.items[1].codepoint);
    try std.testing.expectEqual(@as(u16, 2), raster.cells.items[1].col); // 가가 2칸 차지 → b는 col2
    // col1(가의 continuation)을 가진 셀이 없어야 한다.
    for (raster.cells.items) |cell| try std.testing.expect(cell.col != 1);
}

test "chrome Notice 모달: showNotice → 메시지 소유 복사·오버레이 프레임·입력 라우팅·메뉴 차단·Esc 닫기" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // buildNoticeFrame=CoreText, 실 PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000); // 메트릭·backing(buildNoticeFrame이 chrome props로 씀)

    // 닫힘이면 buildNoticeFrame은 NotOpen(오버레이 없음 — 호출자가 무시).
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expectError(error.NotOpen, testBuildChromeOverlayFrame(session));

    // showNotice는 메시지를 세션 소유 버퍼로 복사하고 연다 — 호출자의 transient 버퍼를 지워도 모달 메시지는 산다.
    {
        var transient = [_]u8{ 'c', 'o', 'r', 'r', 'u', 'p', 't' };
        session.showNotice(&transient);
        @memset(&transient, 0);
    }
    try std.testing.expect(session.chrome_host.notice.open);
    try std.testing.expectEqualStrings("corrupt", session.chrome_host.notice.message);

    // 오버레이 프레임이 크래시 없이 셀을 낸다(박스 bg + 메시지 glyph — 컴포넌트 view→ChromeDraw→lower 경로).
    var nf = try testBuildChromeOverlayFrame(session);
    defer nf.frame.deinit(allocator);
    try std.testing.expect(nf.frame.draw_list.cells.len > 0);

    // 회귀: Notice 열린 동안 메뉴 keyEquivalent(runAction)는 무시된다(모달 뒤 터미널 조작 차단).
    try std.testing.expect(!session.runAction("new_term"));

    // 평문 키는 토스트를 **닫고 소비한다** — notice는 비-인터랙티브 정보 토스트라 아무 키로나 닫히되, 그 닫는 키는
    // 셸로 안 흘린다(옛날엔 Enter/Esc 외 키는 소비만 하고 안 닫혀 입력이 막힌 것처럼 보이던 회귀를 수정). 'a'는 토스트만
    // 닫고 터미널 입력 카운터는 그대로다(닫기 제스처라 소비).
    const ti_before = session.total_terminal_input_events;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'a' }, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expectEqual(ti_before, session.total_terminal_input_events); // 닫는 키는 소비 — 터미널로 안 감

    // Esc도 토스트를 닫고 소비한다(셸로 esc를 안 흘린다). 다시 띄워 확인.
    session.showNotice("corrupt");
    try std.testing.expect(session.chrome_host.notice.open);
    const ti_before_esc = session.total_terminal_input_events;
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.notice.open);
    try std.testing.expectEqual(ti_before_esc, session.total_terminal_input_events); // 셸로 안 흘림
}

test "runtime font size: ⌘+/−/0 cell 메트릭·grid 재계산 + 하한·상한 클램프" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000); // backing px 확정 → grid 산출

    const base = session.base_font_size;
    try std.testing.expectEqual(base, session.appearance.font.size);
    const cw0 = session.cell_width_px;
    const cols0 = session.activeSurface().core.snapshot().size.cols;

    // 폰트 변경 전 baseline: init·resize는 이 플래그를 세우지 않는다(applyMetricsPipeline만 세우고 resize는 그걸
    // 안 탄다) → 이미 false여야 아래 폰트 변경이 세우는 신호를 격리 관측할 수 있다. 이 단언이 깨지면 폰트-무관 경로가
    // dirty를 세운 것.
    try std.testing.expect(!session.file_panel_zoom_dirty);
    // 기본(⌘0 기준)에서 파일 패널 줌 배율은 정확히 1.0(=1000milli)이라 프리뷰가 평소 크기를 유지한다(§2.3).
    try std.testing.expectEqual(@as(u32, 1000), session.filePanelZoomMilli());

    // ⌘+ : 폰트 +보폭(고정 1pt, font_size_step 상수) → cell 픽셀이 커지고(메트릭) grid는 줄거나 같다(같은 backing px).
    session.dispatchAppAction(.increase_font_size);
    try std.testing.expectEqual(base + font_size_step, session.appearance.font.size);
    try std.testing.expect(session.cell_width_px > cw0);
    const cols1 = session.activeSurface().core.snapshot().size.cols;
    try std.testing.expect(cols1 <= cols0);

    // **atlas를 비웠으니 sync hold를 우회하는 강제 재투영이 예약돼야 한다.** 이게 없으면 hold 중(BSU 후 ESU 지연)에
    // 사이드바 전용 부분 투영이 커밋되고, 유지된 셀의 UV가 비워진 atlas의 옛 좌표를 가리켜 본문이 다른 글리프로
    // 오염된다(hold timeout ≈1초까지 지속). `shouldProjectFrame`이 이 플래그로 sync 게이트를 우회한다.
    try std.testing.expect(session.force_reproject);
    try std.testing.expect(shouldProjectFrame(false, true, 0, 60, 0, 0, false, session.force_reproject)); // hold여도 투영

    // 폰트가 바뀌면 파일 패널 줌 dirty가 서고(Swift tick이 drain해 webview 재적용), 배율은 (base+1)/base로 1.0 초과다.
    try std.testing.expect(session.file_panel_zoom_dirty);
    try std.testing.expect(session.takeFilePanelZoomDirty()); // 1회성: 읽으면 비워진다
    try std.testing.expect(!session.file_panel_zoom_dirty);
    try std.testing.expect(session.filePanelZoomMilli() > 1000);
    const expected_milli: u32 = @intFromFloat(@round((base + font_size_step) / base * 1000.0));
    try std.testing.expectEqual(expected_milli, session.filePanelZoomMilli());

    // ⌘0 : config 기본값 복원 → 폰트·cell 픽셀 원래대로(refreshCellMetrics 재계산은 결정적) + 배율도 1.0 복귀.
    session.dispatchAppAction(.reset_font_size);
    try std.testing.expectEqual(base, session.appearance.font.size);
    try std.testing.expectEqual(cw0, session.cell_width_px);
    try std.testing.expectEqual(@as(u32, 1000), session.filePanelZoomMilli());

    // set_font_size:N — 절대 지정(config 바인딩). 그 크기로 바로 설정, [6,72]로 클램프.
    session.dispatchAppAction(.{ .set_font_size = 24 });
    try std.testing.expectEqual(@as(f32, 24), session.appearance.font.size);
    session.dispatchAppAction(.{ .set_font_size = 1000 }); // 상한 클램프
    try std.testing.expectEqual(font_size_max, session.appearance.font.size);
    session.dispatchAppAction(.{ .set_font_size = 1 }); // 하한 클램프
    try std.testing.expectEqual(font_size_min, session.appearance.font.size);
    session.dispatchAppAction(.reset_font_size); // base로 복원(아래 경계 반복 기준)

    // ⌘- 반복 : 하한(font_size_min) 아래로 안 내려간다(경계에서 무동작).
    var i: usize = 0;
    while (i < 100) : (i += 1) session.dispatchAppAction(.decrease_font_size);
    try std.testing.expectEqual(font_size_min, session.appearance.font.size);

    // ⌘+ 반복 : 상한(font_size_max) 위로 안 올라간다.
    i = 0;
    while (i < 200) : (i += 1) session.dispatchAppAction(.increase_font_size);
    try std.testing.expectEqual(font_size_max, session.appearance.font.size);
}

test "Session Dock Cmd zoom grows and shrinks one resolved layout/text/scroll scale" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    const base_scale = session.agentSessionDockScaleMilli();
    const base_card_h_px = session.agentSessionDockScrollItems().card_h_px;
    try std.testing.expectEqual(@as(u32, 1000), session.agentSessionDockUiZoomMilli());
    try std.testing.expectEqual(@as(u32, 1000), base_scale);

    session.dispatchAppAction(.increase_font_size);
    const larger_scale = session.agentSessionDockScaleMilli();
    const larger_card_h_px = session.agentSessionDockScrollItems().card_h_px;
    try std.testing.expect(larger_scale > base_scale);
    try std.testing.expect(larger_card_h_px > base_card_h_px);

    session.dispatchAppAction(.reset_font_size);
    session.dispatchAppAction(.decrease_font_size);
    const smaller_scale = session.agentSessionDockScaleMilli();
    const smaller_card_h_px = session.agentSessionDockScrollItems().card_h_px;
    try std.testing.expect(smaller_scale < base_scale);
    try std.testing.expect(smaller_card_h_px < base_card_h_px);

    session.setFontSize(font_size_min);
    try std.testing.expectEqual(session_dock_ui_zoom_min_milli, session.agentSessionDockUiZoomMilli());
    session.setFontSize(font_size_max);
    try std.testing.expectEqual(session_dock_ui_zoom_max_milli, session.agentSessionDockUiZoomMilli());
    session.dispatchAppAction(.reset_font_size);
    try std.testing.expectEqual(@as(u32, 1000), session.agentSessionDockUiZoomMilli());
}

test "Session Dock search owns committed text and IME preedit instead of leaking to the terminal" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    // Keep this input-routing test synchronous: archive scanning owns a detached worker and is
    // separately covered by the AppKit fixture.  The visible dock is enough to establish the
    // exact `InputFocus.agent_session_search` owner.
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    session.agent_session_archive_initialized = false;
    session.setDockView(.agent_sessions);
    session.agent_session_archive_initialized = true;
    session.agent_session_archive_search_active = true;
    try std.testing.expectEqual(AppSession.InputFocus.agent_session_search, session.inputFocus());

    const before_terminal_input = session.total_terminal_input_events;
    session.routeCommittedText("codex");
    try std.testing.expectEqualStrings("codex", session.agent_session_archive_search.query.items);
    try std.testing.expectEqual(before_terminal_input, session.total_terminal_input_events);

    // Marked text is visible immediately but must not filter until composition commits.
    session.imeMarked("한");
    try std.testing.expectEqualStrings("한", session.agent_session_archive_search.preedit.items);
    try std.testing.expectEqualStrings("codex", session.agent_session_archive_search.query.items);
    try std.testing.expect(session.imeComposingActive());
    session.commitComposition();
    try std.testing.expectEqualStrings("codex한", session.agent_session_archive_search.query.items);
    try std.testing.expectEqual(@as(usize, 0), session.agent_session_archive_search.preedit.items.len);
    try std.testing.expectEqual(before_terminal_input, session.total_terminal_input_events);
}

// reapplyLoadedConfig(세팅 GUI 라이브 재적용 — 커서 깜빡임 토글 등)가 런타임 ⌘+/− 줌을 날리지 않는지(버그 회귀
// 가드: 확대 상태에서 폰트 무관 설정을 토글하면 확대가 리셋되던 문제). config 폰트 크기가 바뀌면 줌이 그 위에
// 상대로 얹히는지(base_font_size=⌘0 기준은 줌 제외 config 값)도 함께 본다.
test "reapplyLoadedConfig: GUI 토글이 런타임 줌(⌘+/−)을 보존한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000); // backing px 확정 → grid 산출

    const factory = try config_mod.resolveAppearance(.{});
    const cw0 = session.cell_width_px;
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);
    try std.testing.expectEqual(factory.font.size, session.base_font_size);

    // ⌘+ 로 6pt 확대 — appearance만 바뀌고 loaded_config.config.font.size는 파일 기본 그대로.
    session.setFontSize(factory.font.size + 6);
    const zoomed_cw = session.cell_width_px;
    try std.testing.expect(zoomed_cw > cw0);
    try std.testing.expectEqual(factory.font.size + 6, session.appearance.font.size);

    // 폰트와 무관한 설정 토글(예: cursor.blink) → loaded_config in-place flip 후 reapplyLoadedConfig.
    _ = config_mod.schema.setBool(&session.loaded_config.config, "cursor.blink", false);
    session.reapplyLoadedConfig();
    try std.testing.expectEqual(factory.font.size + 6, session.appearance.font.size); // 줌 보존(버그였다면 factory로 리셋)
    try std.testing.expectEqual(factory.font.size, session.base_font_size); // ⌘0 기준은 줌 제외 config 값
    try std.testing.expectEqual(zoomed_cw, session.cell_width_px); // cell 메트릭도 확대 그대로

    // ⌘0 reset은 여전히 config 기본으로 복귀(base 보존 확인).
    session.resetFontSize();
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);
    try std.testing.expectEqual(cw0, session.cell_width_px);

    // config 폰트 크기 자체를 GUI(슬라이더/스텝)로 바꾸면, 그 값이 사용자가 의도한 절대 크기다 — 줌을 얹지 않고
    // 그 값으로 간다(슬라이더 표시 == 렌더 크기, code-review high #1). 확대 상태에서 슬라이더를 끌어도 줌이 흡수돼
    // base=appearance=새 config 값이 된다(안 그러면 슬라이더는 14를 가리키는데 렌더는 20이 되는 불일치).
    session.setFontSize(factory.font.size + 6); // 다시 +6 확대(appearance=base+6, base=base)
    session.loaded_config.config.font.size = factory.font.size + 2; // 슬라이더로 config 폰트 크기 변경
    session.reapplyLoadedConfig();
    try std.testing.expectEqual(factory.font.size + 2, session.base_font_size); // ⌘0 기준 = 새 config 값
    try std.testing.expectEqual(factory.font.size + 2, session.appearance.font.size); // 줌 안 얹힘 — 슬라이더 값 그대로
}

// resetAllSettings(통합 리셋 — 메뉴 Reset to Defaults·커맨드 팝업 공용 단일 함수)가 런타임 줌·config 변경을 공장
// 기본값으로 되돌리는지. 파일 덮어쓰기·테마 프리셋은 별도 통합 테스트가 다루므로, 여기선 런타임 상태
// (appearance·cell 메트릭·behavior 캐시·loaded_config)가 기본값이 되는지 + 완료 notice가 뜨는지(회귀 가드) 본다.
test "resetAllSettings: 런타임 줌·config 변경을 공장 기본값으로 복원한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000); // backing px 확정 → grid 산출

    const factory = try config_mod.resolveAppearance(.{});
    const cw0 = session.cell_width_px;
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);

    // 런타임 줌 + config behavior 변경.
    session.setFontSize(factory.font.size + 6);
    session.loaded_config.config.font.size = factory.font.size + 6;
    session.loaded_config.config.bell.audible = false;
    session.audible_bell = false;
    try std.testing.expect(session.appearance.font.size != factory.font.size);
    try std.testing.expect(session.cell_width_px > cw0); // 폰트 키우면 cell 픽셀이 커진다(메트릭)

    // 안전 가드: resetAllSettings가 configPath()에 파일을 쓰므로, 실제 사용자 config(~/.config/maru/config)가 아니라
    // tmp 파일을 덮어쓰도록 config_path_buffer를 박는다(없으면 macOS에서 zig build test가 실 config를 헤더만 남기고 지운다).
    var reset_tmp = std.testing.tmpDir(.{});
    defer reset_tmp.cleanup();
    var reset_path_buf: [4096]u8 = undefined;
    const reset_cfg_path = try std.fmt.bufPrint(&reset_path_buf, ".zig-cache/tmp/{s}/config", .{reset_tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, reset_cfg_path);
    // keybind 초기화(#2-b) 검증용: unbind 1개를 arena에 심어 reset이 비우는지 본다(빈 슬라이스에서 시작하면 약한 검증이라).
    session.loaded_config.unbinds = try session.loaded_config.arena.allocator().dupe(config_mod.KeyChord, &.{try config_mod.KeyChord.parse("Cmd+J")});

    session.resetAllSettings();

    // 런타임·loaded_config가 공장 기본값으로(resetAllSettings: loaded_config=Config{} + reapplyLoadedConfig).
    try std.testing.expectEqual(factory.font.size, session.appearance.font.size);
    try std.testing.expectEqual(cw0, session.cell_width_px);
    try std.testing.expectEqual(factory.font.size, session.base_font_size); // ⌘0 기준도 기본으로
    try std.testing.expectEqual(true, session.audible_bell); // 기본 bell.audible로 복원
    try std.testing.expectEqual(factory.font.size, session.loaded_config.config.font.size);
    try std.testing.expectEqual(true, session.loaded_config.config.bell.audible);
    try std.testing.expect(session.chrome_host.notice.open); // 완료 notice가 떴는지(showNotice)
    // keybind 바인딩 4종이 빈 슬라이스(빌트인만)로 초기화됐는지(#2-b — reset은 keybind도 기본값으로).
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.unbinds.len);
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.keybindings.len);
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.terminal_bindings.len);
    try std.testing.expectEqual(@as(usize, 0), session.loaded_config.global_bindings.len);
}

// applyAppearance: 새 appearance를 통째로 갈아끼우면 appearance·base_font_size·cell 메트릭이 따라 바뀌는지.
// reloadConfig가 파일 새 값으로 부르는 일반 적용 경로 — 파일 I/O 없이 직접 호출로 핵심(appearance/메트릭 갱신)을 고정한다.
test "applyAppearance: 새 appearance로 appearance·base_font_size·메트릭을 갱신한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 CoreText 메트릭 + PTY
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1000, 700, 1000);

    const cw0 = session.cell_width_px;
    // 폰트가 더 큰 appearance를 만든다(기본 resolve에서 size만 키움).
    var bigger = try config_mod.resolveAppearance(.{});
    bigger.font = session.appearance.font; // family 슬라이스는 살아있는 loaded_config 빌림(undefined family 회피)
    bigger.font.size = session.appearance.font.size + 8;

    session.applyAppearance(bigger);
    try std.testing.expectEqual(bigger.font.size, session.appearance.font.size);
    try std.testing.expectEqual(bigger.font.size, session.base_font_size); // base_font_size도 새 크기로(⌘0 기준)
    try std.testing.expect(session.cell_width_px > cw0); // 메트릭 재계산(큰 폰트 → 큰 cell)
}

test "captureWorkspaceWindow: 라이브 탭/split/Term을 workspace 모델로 캡처" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY + split/탭 생성
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    // 활성 surface에 cwd(OSC 7) 심기 + split으로 pane 2개 + 새 탭(탭 2개).
    try session.activeSurface().core.write("\x1b]7;file://h/tmp/proj\x07");
    session.dispatchAppAction(.split_horizontal);
    session.dispatchAppAction(.new_tab);

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const win = try session.captureWorkspaceWindow(arena.allocator(), false, null);

    // 탭 2개, 활성 탭 = 1(방금 만든 새 탭).
    try std.testing.expectEqual(@as(usize, 2), win.tabs.len);
    try std.testing.expectEqual(@as(usize, 1), win.active_tab);
    // 탭0: split → pane 2개 + tree preorder(split, leaf, leaf).
    const tab0 = win.tabs[0];
    try std.testing.expectEqual(@as(usize, 2), tab0.panes.len);
    try std.testing.expectEqual(@as(usize, 3), tab0.tree.len);
    try std.testing.expect(std.meta.activeTag(tab0.tree[0]) == .split);
    try std.testing.expect(std.meta.activeTag(tab0.tree[1]) == .leaf);
    // cwd /tmp/proj가 어떤 surface에 잡혔고, 모든 surface가 유효 크기를 가진다.
    var saw_cwd = false;
    for (tab0.panes) |pane| {
        for (pane.surfaces) |s| {
            if (std.mem.eql(u8, s.cwd, "/tmp/proj")) saw_cwd = true;
            try std.testing.expect(s.cols > 0 and s.rows > 0);
        }
    }
    try std.testing.expect(saw_cwd);

    // capture → serialize가 크래시 없이 기대 라인을 낸다(R1 writer와 결합).
    const wins = [_]maru.session.workspace.Window{win};
    const text = try maru.session.workspace.serialize(allocator, .{ .windows = &wins });
    defer allocator.free(text);
    try std.testing.expect(std.mem.indexOf(u8, text, "maru.workspace.v1\n") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "tree-node split horizontal") != null);
    try std.testing.expect(std.mem.indexOf(u8, text, "cwd=\"/tmp/proj\"") != null);
}

test "dock toggle visual bottom covers 1.7x glyph when titlebar is below equal or above cell height" {
    // strip < cell: renderer starts the cell at y=0, so visible bottom is 1.35ch.
    try std.testing.expectEqual(@as(u32, 27), dockToggleVisualBottomPx(20, 10));
    // strip == cell: 같은 경계이며 큰 글꼴에서도 glyph 아래쪽까지 hit rect가 포함한다.
    try std.testing.expectEqual(@as(u32, 27), dockToggleVisualBottomPx(20, 20));
    // strip > 1.7ch: glyph가 strip 안에 완전히 들어가므로 호출부의 max(strip, bottom)가 strip을 유지한다.
    try std.testing.expectEqual(@as(u32, 37), dockToggleVisualBottomPx(20, 40));
    // 제품 기본 근사(ch=18, strip=28)는 1.7x quad의 1px 남짓한 아래 돌출까지 포함한다.
    try std.testing.expectEqual(@as(u32, 29), dockToggleVisualBottomPx(18, 28));
}

test "empty file dock launcher presents explorer and empty content requests the shared file picker" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    try std.testing.expect(!session.dockHasContent());
    try std.testing.expect(!session.dockVisible());
    try std.testing.expectEqual(AppSession.FilePanelDockControlAction.open, session.filePanelDockControlAction().?);
    const launcher = session.filePanelDockControlRect() orelse return error.MissingDockLauncher;
    try std.testing.expect(!session.isWindowDragRegion(
        @floatFromInt(launcher.x + 1),
        @floatFromInt(launcher.y + 1),
    ));

    session.metal_dirty = true;
    _ = try session.tick();
    var saw_launcher = false;
    for (session.metal_buffer.cells) |cell| {
        if (cell.codepoint == icons.codepoint(.sidebar_collapse) and cell.reserved == metal_frame.native_cell_role_dock_toggle and
            cell.origin_x >= launcher.x and cell.origin_x < launcher.x + launcher.w and
            cell.origin_y < session.titlebar_strip_px)
        {
            saw_launcher = true;
            break;
        }
    }
    try std.testing.expect(saw_launcher);

    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    try std.testing.expect(!session.takeFilePanelPickRequest());
    try std.testing.expect(session.dockVisible());
    const tree_content = session.dockGeometry().tree_content;
    // FP16: 트리가 도크 전체라 좌측 가장자리는 outer divider의 grab band와 겹친다 — 밴드 밖(가운데)을 누른다.
    session.mouse(1, @floatFromInt(tree_content.x + tree_content.w / 2), @floatFromInt(tree_content.y + 1), 0, 0);
    try std.testing.expect(session.takeFilePanelPickRequest());
    try std.testing.expect(!session.takeFilePanelPickRequest());

    _ = 0; // FP16: 도크 그룹 개념 제거
    _ = try session.openFileTermInActivePane("/tmp/launcher-transition.md", .markdown);
    try std.testing.expectEqual(AppSession.FilePanelDockControlAction.collapse, session.filePanelDockControlAction().?);
    session.activateFilePanelDockControl();
    try std.testing.expect(session.dock.collapsed);
    try std.testing.expectEqual(AppSession.FilePanelDockControlAction.expand, session.filePanelDockControlAction().?);
    session.activateFilePanelDockControl();
    try std.testing.expect(!session.dock.collapsed);

    session.chrome_minimal = true;
    try std.testing.expect(session.filePanelDockControlRect() == null);
}

test "file tree root picker is a typed one-shot and cancel or invalid path preserves roots" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    try session.file_tree.replaceExplicitRoots(&.{"/before"});
    const generation = session.file_tree.rootGeneration();

    session.requestFileTreeRootPick(.replace);
    try std.testing.expectEqual(FileTreeRootOutcome.picker_requested, session.fileTreeRootOutcome());
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    try std.testing.expectEqual(FileTreeRootOperation.none, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(&.{}); // AppKit cancel
    try std.testing.expectEqual(FileTreeRootOutcome.picker_canceled, session.fileTreeRootOutcome());
    try std.testing.expectEqual(generation, session.file_tree.rootGeneration());
    try std.testing.expectEqualStrings("/before", session.file_tree.rootAt(0).?);

    session.requestFileTreeRootPick(.add);
    try std.testing.expectEqual(FileTreeRootOperation.add, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick("relative");
    try std.testing.expectEqual(FileTreeRootOutcome.invalid_path, session.fileTreeRootOutcome());
    try std.testing.expectEqual(generation, session.file_tree.rootGeneration());
    try std.testing.expectEqualStrings("/before", session.file_tree.rootAt(0).?);
}

fn testWriteActiveTermCwd(session: *AppSession, cwd: []const u8) !void {
    // 실제 OSC 7→core observation 경로를 쓴다. cache를 직접 바꾸면 updateFileTree가 renderer보다 먼저
    // observation을 refresh해야 한다는 제품 불변을 증명하지 못한다.
    var osc: [std.fs.max_path_bytes + 32]u8 = undefined;
    const bytes = try std.fmt.bufPrint(&osc, "\x1b]7;file://localhost{s}\x07", .{cwd});
    try session.activePane().activeTerm().surface.core.write(bytes);
}

test "file tree ET-CWD follows the active pane observation and keeps an old reveal inert for an outside cwd" {
    // 활성 pane의 OSC 7 관측만 소비하고, root 밖 CWD는 root/watch/persistence를 바꾸지 않으며 이전
    // file-open/reveal intent를 새 CWD의 scroll 대상으로 오인하지 않는 제품 경로 회귀다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "project", .default_dir);
    try tmp.dir.createDir(session.io, "project/one", .default_dir);
    try tmp.dir.createDir(session.io, "project/two", .default_dir);
    try tmp.dir.createDir(session.io, "outside", .default_dir);
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const project = try std.fs.path.join(allocator, &.{ tmp_root, "project" });
    defer allocator.free(project);
    const one = try std.fs.path.join(allocator, &.{ project, "one" });
    defer allocator.free(one);
    const two = try std.fs.path.join(allocator, &.{ project, "two" });
    defer allocator.free(two);
    const outside = try std.fs.path.join(allocator, &.{ tmp_root, "outside" });
    defer allocator.free(outside);

    session.activateFilePanelDockControl();
    try session.file_tree.replaceExplicitRoots(&.{project});
    const root_generation = session.file_tree.rootGeneration();
    const root_count = session.file_tree.rootCount();
    const initial_scan = session.file_tree.takeScanRequest().?;
    allocator.free(initial_scan);
    try session.file_tree.applySnapshotWithIdentity(project, try testFileTreeIdentity(project), &.{
        .{ .name = "one", .kind = .directory, .identity = try testFileTreeIdentity(one) },
        .{ .name = "two", .kind = .directory, .identity = try testFileTreeIdentity(two) },
    });
    session.file_tree_rows_dirty = true;
    session.file_tree_watch_reset_pending = false;

    // updateFileTree는 renderer보다 먼저 run한다. 따라서 내부에서 observation을 refresh하지 않으면 OSC 7이
    // 아직 Term cache에 안 들어와 이 첫 reveal을 놓친다.
    try testWriteActiveTermCwd(session, one);
    try session.updateFileTree();
    try std.testing.expectEqualStrings(one, session.file_tree_followed_cwd.?);
    try std.testing.expectEqualStrings(one, session.file_tree.revealTarget().?);
    // one은 초기 viewport 안의 행이다. follow가 보이는 대상을 다시 위로 당기면 사용자의 탐색 위치를
    // 빼앗으므로 pending을 끝내고 scroll=0을 보존해야 한다.
    try std.testing.expect(!session.file_tree_follow_scroll_pending);
    try std.testing.expectEqual(@as(usize, 0), session.file_tree_scroll_rows);
    try std.testing.expectEqual(root_generation, session.file_tree.rootGeneration());
    try std.testing.expectEqual(root_count, session.file_tree.rootCount());
    try std.testing.expect(!session.file_tree_watch_reset_pending);

    // 관측은 tick마다 같은 CWD를 되풀이한다. 같은 값에서 rows 재투영이나 scroll을 다시 걸면 사용자가
    // 탐색 중인 위치를 빼앗으므로, raw scroll과 dirty/pending 상태가 그대로여야 한다.
    session.file_tree_scroll_rows = 2;
    try session.updateFileTree();
    try std.testing.expect(!session.file_tree_rows_dirty);
    try std.testing.expect(!session.file_tree_follow_scroll_pending);
    try std.testing.expectEqual(@as(usize, 2), session.file_tree_scroll_rows);
    try std.testing.expect(!session.file_tree_watch_reset_pending);

    // root 밖 CWD는 Tree의 기존 one reveal을 보존하지만, 그것을 outside의 scroll pending으로 바꾸면 안 된다.
    try testWriteActiveTermCwd(session, outside);
    try session.updateFileTree();
    try std.testing.expectEqualStrings(outside, session.file_tree_followed_cwd.?);
    try std.testing.expect(!session.file_tree_follow_scroll_pending);
    try std.testing.expectEqualStrings(one, session.file_tree.revealTarget().?);
    try std.testing.expectEqual(root_generation, session.file_tree.rootGeneration());
    try std.testing.expectEqual(root_count, session.file_tree.rootCount());
    try std.testing.expect(!session.file_tree_watch_reset_pending);

    // 기존 file-open intent와 같은 CWD로 돌아와도 root 밖 거부와 혼동하면 안 된다. offscreen scroll 위치를
    // 강제로 만들어, `already_target`이 실제 viewport 보정을 다시 요청하는지 증명한다. fixture의 행은
    // root+자식 둘뿐이므로 실제 도크 높이를 그대로 쓰면 raw scroll이 먼저 0으로 clamp되어 offscreen
    // 전제가 성립하지 않는다. 이 구간만 한 행 viewport로 고정해 제품의 clamp→follow 순서를 검증한다.
    const saved_backing_height_px = session.backing_height_px;
    // 고정 chrome 높이를 공식으로 다시 쓰지 않고 **실제 기하에서 읽는다**. 예전에는
    // `titlebar_strip_px + paneBarHeightPx()`로 적어 뒀는데, 그 둘은 도크 기하의 입력이 아니게 됐다
    // (도크 시작선과 view bar는 이제 terminal cell이 아니라 Chrome metric에서 나온다).
    session.backing_height_px = session.dockGeometry().tree.y + session.cell_height_px;
    try std.testing.expectEqual(session.cell_height_px, session.dockGeometry().tree_content.h);
    session.file_tree_scroll_rows = 6;
    try testWriteActiveTermCwd(session, one);
    try session.updateFileTree();
    try std.testing.expectEqualStrings(one, session.file_tree_followed_cwd.?);
    try std.testing.expect(!session.file_tree_follow_scroll_pending);
    try std.testing.expectEqual(@as(usize, 1), session.file_tree_scroll_rows);
    session.backing_height_px = saved_backing_height_px;

    // 새 split pane을 active로 바꾸면 이전 pane의 outside cache가 아니라 새 active Term의 CWD만 따라간다.
    try session.splitActivePane(.horizontal);
    try testWriteActiveTermCwd(session, two);
    try session.updateFileTree();
    try std.testing.expectEqualStrings(two, session.file_tree_followed_cwd.?);

    // 파일/브라우저 Term은 CWD가 없으므로 직전 local CWD와 Tree 상태를 지우지 않는다.
    session.dispatchAppAction(.new_web_tab);
    try std.testing.expect(session.activePane().activeTerm().kind == .web);
    try session.updateFileTree();
    try std.testing.expectEqualStrings(two, session.file_tree_followed_cwd.?);
}

fn testWaitForFileTreeRootCompletion(session: *AppSession) !void {
    var attempts: usize = 0;
    while (session.file_tree_root_validation != null and attempts < 2_000) : (attempts += 1) {
        try session.updateFileTree();
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    if (session.file_tree_root_validation != null) return error.TestUnexpectedResult;
    try session.updateFileTree();
}

test "file tree root picker replaces adds repeats and rejects stale completion without touching dirty dock entries" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "root-a", .default_dir);
    try tmp.dir.createDir(session.io, "root-b", .default_dir);
    try tmp.dir.createDir(session.io, "root-c", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "outside.md", .data = "# dirty" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const root_a = try std.fs.path.join(allocator, &.{ tmp_root, "root-a" });
    defer allocator.free(root_a);
    const root_b = try std.fs.path.join(allocator, &.{ tmp_root, "root-b" });
    defer allocator.free(root_b);
    const root_c = try std.fs.path.join(allocator, &.{ tmp_root, "root-c" });
    defer allocator.free(root_c);
    const outside = try std.fs.path.join(allocator, &.{ tmp_root, "outside.md" });
    defer allocator.free(outside);

    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, session.openFilePanelPath(outside));
    const entry = session.fileEntryForPath(outside).?;
    entry.dirty = true;
    entry.external_change = true;
    const entry_id = entry.id;
    const surface_id = entry.surface_id;

    session.requestFileTreeRootPick(.replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(root_a);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, session.fileTreeRootOutcome());
    try std.testing.expectEqual(file_tree.RootMode.explicit, session.file_tree.rootMode());
    try std.testing.expectEqualStrings(root_a, session.file_tree.rootAt(0).?);

    session.requestFileTreeRootPick(.add);
    try std.testing.expectEqual(FileTreeRootOperation.add, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(root_b);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_add, session.fileTreeRootOutcome());
    try std.testing.expectEqual(@as(usize, 2), session.file_tree.rootCount());

    session.requestFileTreeRootPick(.replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(root_c);
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, session.fileTreeRootOutcome());
    try std.testing.expectEqual(@as(usize, 1), session.file_tree.rootCount());
    try std.testing.expectEqualStrings(root_c, session.file_tree.rootAt(0).?);

    // A completion issued against C must not publish after an intervening root generation change.
    session.requestFileTreeRootPick(.replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(root_a);
    try session.file_tree.replaceExplicitRoots(&.{root_b});
    try testWaitForFileTreeRootCompletion(session);
    try std.testing.expectEqual(FileTreeRootOutcome.stale_generation, session.fileTreeRootOutcome());
    try std.testing.expectEqualStrings(root_b, session.file_tree.rootAt(0).?);

    const preserved = session.fileEntryForPath(outside).?.*;
    try std.testing.expectEqual(entry_id, preserved.id);
    try std.testing.expectEqual(surface_id, preserved.surface_id);
    try std.testing.expect(preserved.dirty and preserved.external_change);
    var saw_outside_safety_root = false;
    while (session.file_tree.takeWatchRequest()) |watch| {
        defer allocator.free(watch);
        if (std.mem.eql(u8, watch, tmp_root)) saw_outside_safety_root = true;
    }
    try std.testing.expect(saw_outside_safety_root);
}

test "file tree root validation completion projects live dock open close state and watcher safety roots" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "initial-root", .default_dir);
    try tmp.dir.createDir(session.io, "selected-root", .default_dir);
    try tmp.dir.createDir(session.io, "closed-parent", .default_dir);
    try tmp.dir.createDir(session.io, "live-parent", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "closed-parent/closed.md", .data = "# closed" });
    try tmp.dir.writeFile(session.io, .{ .sub_path = "live-parent/live.md", .data = "# live" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const initial_root = try std.fs.path.join(allocator, &.{ tmp_root, "initial-root" });
    defer allocator.free(initial_root);
    const selected_root = try std.fs.path.join(allocator, &.{ tmp_root, "selected-root" });
    defer allocator.free(selected_root);
    const closed_parent = try std.fs.path.join(allocator, &.{ tmp_root, "closed-parent" });
    defer allocator.free(closed_parent);
    const live_parent = try std.fs.path.join(allocator, &.{ tmp_root, "live-parent" });
    defer allocator.free(live_parent);
    const closed_path = try std.fs.path.join(allocator, &.{ closed_parent, "closed.md" });
    defer allocator.free(closed_path);
    const live_path = try std.fs.path.join(allocator, &.{ live_parent, "live.md" });
    defer allocator.free(live_path);

    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, session.openFilePanelPath(closed_path));
    const closed_surface = session.fileEntryForPath(closed_path).?.surface_id;
    // Keep the namespace explicit so opening an outside file during validation does not itself change
    // root_generation and turn this freshness case into the separate stale-generation case.
    try session.file_tree.replaceExplicitRoots(&.{initial_root});
    const validation_generation = session.file_tree.rootGeneration();
    session.requestFileTreeRootPick(.replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(selected_root);
    try std.testing.expect(session.file_tree_root_validation != null);

    try std.testing.expect(session.closeFilePanelSurfaceNow(closed_surface));
    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, session.openFilePanelPath(live_path));
    try std.testing.expectEqual(validation_generation, session.file_tree.rootGeneration());
    try testWaitForFileTreeRootCompletion(session);

    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, session.fileTreeRootOutcome());
    try std.testing.expectEqual(@as(usize, 1), session.fileEntryCount());
    try std.testing.expect(session.fileEntryForPath(closed_path) == null);
    try std.testing.expect(session.fileEntryForPath(live_path) != null);
    var saw_closed_row = false;
    var saw_live_row = false;
    for (session.file_tree_rows.items) |row| switch (row) {
        .recent_file => |recent| {
            if (std.mem.eql(u8, recent.path, closed_path)) {
                saw_closed_row = true;
                try std.testing.expect(!recent.open);
            } else if (std.mem.eql(u8, recent.path, live_path)) {
                saw_live_row = true;
                try std.testing.expect(recent.open and recent.active);
            }
        },
        else => {},
    };
    try std.testing.expect(saw_closed_row and saw_live_row);

    var saw_selected_root = false;
    var saw_live_safety_root = false;
    var saw_closed_safety_root = false;
    while (session.file_tree.takeWatchRequest()) |watch| {
        defer allocator.free(watch);
        saw_selected_root = saw_selected_root or std.mem.eql(u8, watch, selected_root);
        saw_live_safety_root = saw_live_safety_root or std.mem.eql(u8, watch, live_parent);
        saw_closed_safety_root = saw_closed_safety_root or std.mem.eql(u8, watch, closed_parent);
    }
    try std.testing.expect(saw_selected_root);
    try std.testing.expect(saw_live_safety_root);
    try std.testing.expect(!saw_closed_safety_root);
}

test "file tree retained first scan is published but stale namespace row activation is rejected" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "selected", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "selected/same.md", .data = "# original" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const selected = try std.fs.path.join(allocator, &.{ tmp_root, "selected" });
    defer allocator.free(selected);

    session.requestFileTreeRootPick(.replace);
    try std.testing.expectEqual(FileTreeRootOperation.replace, session.takeFileTreeRootPickRequest());
    session.provideFileTreeRootPick(selected);

    var attempts: usize = 0;
    while ((session.file_tree_root_validation == null or session.file_tree_root_validation.?.round == 0) and attempts < 2_000) : (attempts += 1) {
        try session.updateFileTree();
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.file_tree_root_validation != null);
    try std.testing.expectEqual(@as(u8, 1), session.file_tree_root_validation.?.round);
    attempts = 0;
    while (session.file_tree_backend.resultCountForTest() == 0 and attempts < 2_000) : (attempts += 1) {
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.file_tree_backend.resultCountForTest() > 0);

    // Round 2 has captured selected's descriptor. Replace the same pathname before AppSession consumes it.
    try tmp.dir.rename("selected", tmp.dir, "moved", session.io);
    try tmp.dir.createDir(session.io, "selected", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "selected/same.md", .data = "# replacement" });
    try session.updateFileTree();
    try std.testing.expectEqual(FileTreeRootOutcome.committed_replace, session.fileTreeRootOutcome());

    attempts = 0;
    while (session.file_tree_backend.resultCountForTest() == 0 and attempts < 2_000) : (attempts += 1) {
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.file_tree_backend.resultCountForTest() > 0);
    try session.updateFileTree();

    var row_index: ?usize = null;
    for (session.file_tree_rows.items, 0..) |row, index| switch (row) {
        .file => |file| if (std.mem.eql(u8, file.label, "same.md")) {
            row_index = index;
        },
        else => {},
    };
    try std.testing.expect(row_index != null); // exact first scan came from the retained old descriptor.
    session.activateFileTreeRow(row_index.?);
    try std.testing.expectEqual(@as(usize, 0), session.fileEntryCount());
    try std.testing.expect(session.peekFileTreeExternalOpen() == null);
}

test "file tree markdown activation pins first hydration identity across leaf replacement" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
