test "wheel·track click·keyboard가 하나의 스크롤 상태를 이어받고 발행이 그 값을 따른다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.activateFilePanelDockControl();
    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    session.refreshFileTreeScrollbarGeometry();
    const geometry = session.fileTreeScrollbarGeometry() orelse return error.SkipZigTest;
    if (geometry.max_scroll == 0) return error.SkipZigTest;
    const content = session.dockGeometry().tree_content;
    const inside_x: f64 = @floatFromInt(content.x + content.w / 2);
    const inside_y: f64 = @floatFromInt(content.y + content.h / 2);

    // ① wheel — 트리 위에서 굴리면 스크롤 상태가 움직인다. 이 셋은 서로 다른 입구지만 **같은
    //    상태**를 움직여야 한다. 각자 자기 스크롤 위치를 들면 thumb과 내용이 어긋난다.
    try std.testing.expectEqual(@as(usize, 0), session.fileTreeEffectiveScroll());
    session.scrollWheel(-5, 0, false, inside_x, inside_y);
    const after_wheel = session.fileTreeEffectiveScroll();
    try std.testing.expect(after_wheel > 0);

    // ② track click — thumb **밖**을 누르면 그 지점으로 점프한다(드래그가 아니다).
    const track_bottom = geometry.track_y + geometry.track_h - 1;
    try std.testing.expect(session.beginFileTreeScrollbarGesture(
        geometry.track_x + geometry.track_w / 2,
        track_bottom,
    ));
    const after_track = session.fileTreeEffectiveScroll();
    try std.testing.expect(after_track > after_wheel);
    session.endScrollbarCapture();

    // ③ **상태 공유** — 앞 두 입구가 올려놓은 값을 keyboard anchor가 이어받는가. 단조 증가만
    //    보면 각 입구가 자기 변수를 들고 있어도 통과한다(마지막에 쓴 쪽이 게터에 반영되므로).
    //    그래서 "이미 보이는 행을 겨냥하면 아무 것도 움직이지 않는다"를 본다 — anchor가 현재
    //    스크롤을 실제로 읽고 있어야만 성립하는 성질이다.
    const visible_index = after_track + session.fileTreeVisibleRows() / 2;
    session.scrollFileTreeSelectionIntoView(visible_index);
    try std.testing.expectEqual(after_track, session.fileTreeEffectiveScroll());

    // ④ keyboard — 선택이 화면 밖으로 나가면 anchor가 그것을 따라 들어온다.
    session.scrollFileTreeSelectionIntoView(0);
    try std.testing.expectEqual(@as(usize, 0), session.fileTreeEffectiveScroll());
    session.scrollFileTreeSelectionIntoView(500);
    const after_anchor = session.fileTreeEffectiveScroll();
    try std.testing.expect(after_anchor > 0);

    // ⑤ 그리고 그 상태가 곧 thumb 위치다 — 발행된 tree가 같은 값에서 나온다.
    session.refreshFileTreeScrollbarGeometry();
    const moved = session.fileTreeScrollbarGeometry().?;
    try std.testing.expectEqual(after_anchor, moved.scroll_rows);
    var storage: [2]chrome.ui.tree.RectEntry = undefined;
    const published = try file_tree_scrollbar.publish(moved, 1, &storage);
    try std.testing.expectEqual(@as(usize, 2), published.entries.len);
    // thumb이 track 시작보다 아래에 있다 — 스크롤 상태가 발행에 반영됐다는 뜻이다.
    try std.testing.expect(published.entries[1].rect.y > moved.track_y);
}

test "두 세대가 그대로여도 track/thumb 기하가 바뀌면 스크롤 드래그를 놓는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    _ = try session.resize(1400, 900, 1000);
    session.activateFilePanelDockControl();
    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    session.refreshFileTreeScrollbarGeometry();
    const geometry = session.fileTreeScrollbarGeometry() orelse return error.SkipZigTest;
    if (geometry.max_scroll == 0) return error.SkipZigTest;

    try std.testing.expect(session.beginFileTreeScrollbarGesture(geometry.track_x, geometry.thumb_y));
    try std.testing.expect(session.scrollbarCaptureActive());

    // 세대는 둘 다 그대로 두고 기하만 바꾼다. carry key는 host가 주입한 값의 동등성만 보므로
    // 이 축은 key로 표현되지 않는다 — down 시점 기하로 계산한 스크롤이 손가락과 어긋나기 전에
    // domain 검증이 놓아야 한다.
    const root_before = session.file_tree.rootGeneration();
    const projection_before = session.file_tree_projection_generation;
    session.scrollbar_capture.?.geometry.track_h += 40;
    session.scrollbar_capture.?.geometry.thumb_h += 8;
    try std.testing.expectEqual(root_before, session.file_tree.rootGeneration());
    try std.testing.expectEqual(projection_before, session.file_tree_projection_generation);

    _ = session.routeScrollbarCapture(2, geometry.track_y + geometry.track_h - 1);
    try std.testing.expect(!session.scrollbarCaptureActive());
}

// 계약 §4.3의 coalescing은 "move를 모아 **tick이** 적용한다"이지 "up에서 한 번 적용한다"가 아니다.
// `tick`이 scrollbar coalescer를 소비하지 않아, thumb을 끄는 동안에는 화면이 그대로이고 손을 떼야
// 한 번에 움직였다(제보) — 같은 패턴을 쓰는 divider는 매 tick 반영되는데 스크롤만 달랐다.
// 이 fixture는 `applyPendingScrollbarScroll`을 **손으로 부르지 않는다**. 그 호출이 기존 테스트를
// 통과시키면서 제품 경로의 누락을 가리고 있었다 — tick만 돌려 제품이 실제로 소비하는지를 본다.
test "파일 트리 스크롤바 드래그는 손을 떼기 전에 tick이 적용한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.activateFilePanelDockControl();

    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    session.refreshFileTreeScrollbarGeometry();
    const top = session.fileTreeScrollbarGeometry().?;

    // 트랙 하단을 눌러 아래로 스크롤한 상태에서 드래그를 시작한다(down 자체는 즉시 적용).
    try std.testing.expect(session.beginFileTreeScrollbarGesture(
        top.track_x + top.track_w / 2,
        top.track_y + top.track_h - 1,
    ));
    try std.testing.expect(session.scrollbarCaptureActive());
    try std.testing.expect(session.fileTreeEffectiveScroll() > 0);

    // thumb을 맨 위로 끈다. move는 좌표만 모으므로 이 시점엔 아직 그대로다.
    _ = session.routeScrollbarCapture(2, top.track_y);
    try std.testing.expect(session.fileTreeEffectiveScroll() > 0);

    // **손을 떼지 않은 채**(up=kind 3을 보내지 않고) tick 한 번 — 여기서 적용돼야 한다. 이 fixture의 축은
    // "up 없이도 적용되는가"이지 capture 수명이 아니다(그쪽은 stale-snapshot cancel 테스트가 소유한다).
    _ = try session.tick();
    try std.testing.expectEqual(@as(usize, 0), session.fileTreeEffectiveScroll());
    session.endScrollbarCapture();
}

test "file tree scrollbar is overflow-only and stale drag snapshots cancel" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.activateFilePanelDockControl();

    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, 512);
    for (0..512) |_| session.file_tree_rows.appendAssumeCapacity(.empty);
    session.refreshFileTreeScrollbarGeometry();
    const top = session.fileTreeScrollbarGeometry().?;
    try std.testing.expectEqual(@as(usize, 0), top.scroll_rows);
    const tree_content = session.dockGeometry().tree_content;
    const total_cols = tree_content.w / session.cell_width_px;
    const reserved_cols = file_tree_scrollbar.reservedColumns(tree_content.w, session.cell_width_px);
    const last_content_right = tree_content.x + (total_cols -| reserved_cols) * session.cell_width_px;
    try std.testing.expect(@as(f32, @floatFromInt(last_content_right)) <= top.track_x);
    try std.testing.expect(session.beginFileTreeScrollbarGesture(
        top.track_x + top.track_w / 2,
        top.track_y + top.track_h - 1,
    ));
    try std.testing.expect(session.scrollbarCaptureActive());
    try std.testing.expect(session.fileTreeEffectiveScroll() > 0);
    // move는 좌표만 모으고 tick이 적용한다(계약 §4.3) — 옛 경로는 move가 곧 재투영이었다.
    _ = session.routeScrollbarCapture(2, top.track_y);
    session.applyPendingScrollbarScroll();
    try std.testing.expectEqual(@as(usize, 0), session.fileTreeEffectiveScroll());
    _ = session.routeScrollbarCapture(2, std.math.nan(f64));
    session.applyPendingScrollbarScroll();
    try std.testing.expectEqual(@as(usize, 0), session.fileTreeEffectiveScroll());

    // Root authority is part of the drag snapshot. A late move after replacement must not commit.
    const restarted = session.fileTreeScrollbarGeometry().?;
    try std.testing.expect(session.beginFileTreeScrollbarGesture(restarted.track_x, restarted.thumb_y));
    try session.file_tree.replaceExplicitRoots(&.{"/different"});
    _ = session.routeScrollbarCapture(2, top.track_y + top.track_h);
    try std.testing.expect(!session.scrollbarCaptureActive());
    try std.testing.expectEqual(@as(usize, 0), session.fileTreeEffectiveScroll());

    session.refreshFileTreeScrollbarGeometry();
    const current = session.fileTreeScrollbarGeometry().?;
    try std.testing.expect(session.beginFileTreeScrollbarGesture(current.track_x, current.thumb_y));
    session.advanceFileTreeProjectionGeneration();
    try std.testing.expect(session.pointerGestureIs(.none));

    session.file_tree_rows.clearRetainingCapacity();
    session.file_tree_rows.appendAssumeCapacity(.empty);
    session.refreshFileTreeScrollbarGeometry();
    try std.testing.expect(session.fileTreeScrollbarGeometry() == null);
}

test "file tree production hot paths emit bounded counter artifact" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.activateFilePanelDockControl();

    session.file_tree_rows.clearRetainingCapacity();
    try session.file_tree_rows.ensureTotalCapacity(allocator, file_tree.max_materialized_nodes);
    for (0..file_tree.max_materialized_nodes) |_| session.file_tree_rows.appendAssumeCapacity(.{ .file = .{
        .path = "/repo/src/main.zig",
        .label = "main.zig",
        .depth = 1,
        .supported = true,
        .open = false,
        .active = false,
        .dirty = false,
        .external_change = false,
        .symlink = false,
    } });

    var counters: FileTreePerfCounters = .{};
    AppSession.classifyFileTreeRowsCounted(session.file_tree_rows.items, &counters);
    try std.testing.expectEqual(file_tree.max_materialized_nodes, counters.row_visits);
    try std.testing.expectEqual(counters.row_visits, counters.classifier_calls);
    for (session.file_tree_rows.items) |row|
        try std.testing.expectEqual(@intFromEnum(file_tree_icon.IconKind.code), file_tree.rowIconKind(row));

    session.refreshFileTreeScrollbarGeometry();
    const geometry = session.fileTreeScrollbarGeometry().?;
    try session.gpu_quads.ensureUnusedCapacity(allocator, 1);
    try std.testing.expect(session.beginFileTreeScrollbarGesture(geometry.track_x, geometry.thumb_y));

    var counting = std.testing.FailingAllocator.init(allocator, .{});
    session.allocator = counting.allocator();
    session.file_tree_perf_counters = &counters;
    for (0..1000) |event| {
        const y = geometry.track_y + @as(f32, @floatFromInt(event % @as(usize, @intFromFloat(geometry.track_h))));
        _ = session.routeScrollbarCapture(2, y);
        session.applyPendingScrollbarScroll();
    }
    session.endScrollbarCapture();

    for (0..1000) |_| {
        session.dropQuadsByLayer(3);
        session.refreshFileTreeScrollbarGeometry();
        session.appendFileTreeScrollbar();
    }
    session.file_tree_perf_counters = null;
    session.allocator = allocator;
    counters.allocator_calls = counting.allocations;

    try std.testing.expectEqual(@as(usize, 1000), counters.pointer_events);
    try std.testing.expectEqual(@as(usize, 1000), counters.projected_frames);
    try std.testing.expectEqual(counters.projected_frames, counters.geometry_builds);
    try std.testing.expectEqual(counters.projected_frames, counters.thumb_quads);
    try std.testing.expectEqual(@as(usize, 0), counters.allocator_calls);

    const report = try std.fmt.allocPrint(allocator,
        \\maru.file-explorer-perf.v1
        \\rows={d}
        \\row_visits={d}
        \\classifier_calls={d}
        \\pointer_events={d}
        \\projected_frames={d}
        \\geometry_builds={d}
        \\thumb_quads={d}
        \\allocator_calls={d}
        \\
    , .{
        file_tree.max_materialized_nodes,
        counters.row_visits,
        counters.classifier_calls,
        counters.pointer_events,
        counters.projected_frames,
        counters.geometry_builds,
        counters.thumb_quads,
        counters.allocator_calls,
    });
    defer allocator.free(report);
    try std.Io.Dir.cwd().createDirPath(session.io, "tests/artifacts/perf");
    try std.Io.Dir.cwd().writeFile(session.io, .{
        .sub_path = "tests/artifacts/perf/file-explorer.txt",
        .data = report,
    });
}

test "file tree row staging OOM leaves live root rows and watcher authority unchanged" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    try session.file_tree.replaceExplicitRoots(&.{"/before"});
    try session.file_tree.resetWatchRequests(&.{"/safety"});
    session.file_tree_rows_dirty = true;
    try session.updateFileTree();
    const live_generation = session.file_tree.rootGeneration();
    try std.testing.expectEqualStrings("/before", session.file_tree_rows.items[0].root.path);

    var candidate = try session.file_tree.cloneForRootTransaction();
    defer candidate.deinit();
    try candidate.replaceExplicitRoots(&.{"/after"});
    try candidate.resetWatchRequests(&.{"/other-safety"});
    var candidate_rows: std.ArrayList(file_tree.Row) = .empty;
    defer candidate_rows.deinit(allocator);
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    session.allocator = failing.allocator();
    try std.testing.expectError(error.OutOfMemory, session.prepareFileTreeRowStaging(&candidate_rows, 0));
    session.allocator = allocator;

    try std.testing.expectEqual(live_generation, session.file_tree.rootGeneration());
    try std.testing.expectEqualStrings("/before", session.file_tree.rootAt(0).?);
    try std.testing.expectEqualStrings("/before", session.file_tree_rows.items[0].root.path);
    const first_watch = session.file_tree.takeWatchRequest().?;
    defer allocator.free(first_watch);
    try std.testing.expectEqualStrings("/before", first_watch);
    const second_watch = session.file_tree.takeWatchRequest().?;
    defer allocator.free(second_watch);
    try std.testing.expectEqualStrings("/safety", second_watch);
}

test "file tree scan completion is fenced across A to B to A root generations" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.createDir(session.io, "a", .default_dir);
    try tmp.dir.createDir(session.io, "b", .default_dir);
    try tmp.dir.writeFile(session.io, .{ .sub_path = "a/stale.md", .data = "stale" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const root_a = try std.fs.path.join(allocator, &.{ tmp_root, "a" });
    defer allocator.free(root_a);
    const root_b = try std.fs.path.join(allocator, &.{ tmp_root, "b" });
    defer allocator.free(root_b);

    try session.file_tree.replaceExplicitRoots(&.{root_a});
    const old_generation = session.file_tree.rootGeneration();
    try session.updateFileTree(); // submits A at old_generation
    try session.file_tree.replaceExplicitRoots(&.{root_b});
    try session.file_tree.replaceExplicitRoots(&.{root_a});
    try std.testing.expect(session.file_tree.rootGeneration() != old_generation);
    const current_request = session.file_tree.takeScanRequest().?;
    allocator.free(current_request); // isolate the old in-flight completion; do not submit current A.

    var attempts: usize = 0;
    while (!session.file_tree_backend.isIdleForTest() and attempts < 2_000) : (attempts += 1) {
        try session.updateFileTree();
        std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(1), .awake) catch {};
    }
    try std.testing.expect(session.file_tree_backend.isIdleForTest());
    try session.updateFileTree();
    try std.testing.expectEqual(@as(usize, 2), session.file_tree_rows.items.len); // root + recent header, no stale child
    try std.testing.expect(session.file_tree_rows.items[0].root.loading);
}

