// grip 드래그 end-to-end(마우스 경로): pane 탭바 좌측 grip을 잡으면 pane_drag arm(tab_drag 아님), 사이드바
// 빈 영역에 up하면 새 워크스페이스로 분리, 다른 워크스페이스 카드에 up하면 합치기. 실 init/split/spawn이라 macOS 게이트.
test "grip 드래그: 사이드바 빈 영역 드롭 → 새 워크스페이스 분리(pane_drag arm 포함)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try session.splitActivePane(.horizontal); // ws0: pane 2개, 활성 = 우(b)
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const pane_b = session.activePane();
    try std.testing.expect(lr.items[1].leaf == pane_b);
    const pb = session.paneBar(lr.items[1].rect, lr.items[1].leaf).?;
    try std.testing.expect(pb.grip_cols > 0); // grip 항상 예약

    // grip(좌측, tabs.x 앞) down → pane_drag arm(tab_drag 아님).
    const grip_x: f64 = @floatFromInt(pb.full.x + 1);
    const grip_y: f64 = @floatFromInt(pb.full.y + 1);
    session.mouse(1, grip_x, grip_y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.pane));
    try std.testing.expect(session.pointer_gesture_owner.pane.pane == pane_b);
    try std.testing.expect(!session.pointerGestureIs(.terminal_tab));

    // 사이드바 빈 영역(카드 한참 아래)으로 drag + up → 새 워크스페이스 분리.
    const sx: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const empty_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px + chrome.components.sidebar.contentHeight(session.sidebar_rows.items, session.sidebarMetrics()) + 10));
    session.mouse(2, sx, empty_y, 0, 0);
    session.mouse(3, sx, empty_y, 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.pane)); // 드래그 종료
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len); // 새 워크스페이스 생김
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab); // 새 탭 활성
    try std.testing.expectEqual(pane_b, session.tabs.items[1].panes.items[0]); // 분리된 pane이 새 탭에
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items[0].panes.items.len); // 소스 collapse
}

test "grip 드래그: 단독 pane을 다른 워크스페이스 카드에 드롭 → 합치고 빈 소스 제거" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    _ = try session.newTab(); // tabs [ws0, ws1]
    try std.testing.expect(session.switchTab(0)); // 활성 ws0
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const moved_pane = session.activePane();
    const pb = session.paneBar(lr.items[0].rect, lr.items[0].leaf).?;
    try std.testing.expect(pb.grip_cols > 0);

    const grip_x: f64 = @floatFromInt(pb.full.x + pb.grip_cols * session.cell_width_px / 2);
    const grip_y: f64 = @floatFromInt(pb.full.y + pb.full.h / 2);
    session.mouse(1, grip_x, grip_y, 0, 0); // grip down → arm
    try std.testing.expect(session.pointerGestureIs(.pane));

    // ws1 카드(slot 1) 중앙에 up → 합치기. visible_tabs=[0,1]이라 slot 1 = ws1.
    const sx: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const card_y: f64 = session.testSidebarRowCenterY(1);
    session.mouse(2, sx, card_y, 0, 0);
    session.mouse(3, sx, card_y, 0, 0);

    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len); // 빈 소스 ws0 제거, target만 남음
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items[0].panes.items.len); // target에 단독 pane 합쳐짐
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab); // 당겨진 target 활성
    try std.testing.expectEqual(moved_pane, session.tabs.items[0].activePane()); // 합쳐진 pane이 활성(우측)
}

test "grip 드래그: 드래그 중 드롭 타겟 하이라이트 슬롯 추적(카드/빈 영역/밖/자기)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    _ = try session.newTab(); // [ws0, ws1]
    try std.testing.expect(session.switchTab(0)); // 활성 ws0
    try session.splitActivePane(.horizontal); // ws0 2 pane, 활성 = b
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const pb = session.paneBar(lr.items[1].rect, lr.items[1].leaf).?;
    session.mouse(1, @floatFromInt(pb.full.x + 1), @floatFromInt(pb.full.y + 1), 0, 0); // grip arm
    try std.testing.expect(session.pointerGestureIs(.pane));

    const sx: f64 = @floatFromInt(session.sidebar_width_px / 2);
    // ① ws1 카드(slot 1) 위 → 하이라이트 슬롯 = 1(merge 타겟).
    const card_y: f64 = session.testSidebarRowCenterY(1);
    session.mouse(2, sx, card_y, 0, 0);
    try std.testing.expectEqual(@as(?usize, 1), session.pointer_gesture_owner.pane.drop_slot);
    // ② 빈 영역(카드 아래) → 하이라이트 슬롯 = 표시 카드 수(새 워크스페이스 행).
    const empty_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px + chrome.components.sidebar.contentHeight(session.sidebar_rows.items, session.sidebarMetrics()) + 10));
    session.mouse(2, sx, empty_y, 0, 0);
    try std.testing.expectEqual(@as(?usize, session.sidebar_rows.items.len), session.pointer_gesture_owner.pane.drop_slot);
    // ③ 사이드바 밖(터미널) → 하이라이트 없음.
    session.mouse(2, @floatFromInt(pb.full.x + 20), @floatFromInt(pb.full.y + 1), 0, 0);
    try std.testing.expect(session.pointer_gesture_owner.pane.drop_slot == null);
    // ④ 자기 워크스페이스(ws0 = slot 0) 위 → 하이라이트 없음(merge 무의미).
    const own_y: f64 = session.testSidebarRowCenterY(0);
    session.mouse(2, sx, own_y, 0, 0);
    try std.testing.expect(session.pointer_gesture_owner.pane.drop_slot == null);
    // ⑤ 헤더(검색바·아이콘) 위 → 하이라이트 없음·드롭 불가(검색바에서 새 워크스페이스 오생성 방지).
    const header_y: f64 = @floatFromInt(session.sidebar_header_height_px / 2);
    session.mouse(2, sx, header_y, 0, 0);
    try std.testing.expect(session.pointer_gesture_owner.pane.drop_slot == null);
    try std.testing.expect(session.computePaneDropDest(sx, header_y) == null); // 드롭도 no-op
    // up → 하이라이트·드래그 정리.
    session.mouse(3, @floatFromInt(pb.full.x + 20), @floatFromInt(pb.full.y + 1), 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.pane));
}

test "move_pane_to_new_workspace 액션: 활성 pane을 새 워크스페이스로 분리(dispatch 경로) + 단독이면 no-op" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try session.splitActivePane(.horizontal); // ws0: 2 pane, 활성 b
    const pane_b = session.activePane();
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);

    session.dispatchAppAction(.move_pane_to_new_workspace); // 활성 pane → 새 워크스페이스
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab); // 새 탭 활성
    try std.testing.expectEqual(pane_b, session.tabs.items[1].panes.items[0]);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items[0].panes.items.len); // 소스 collapse

    // 새 탭은 단독 pane → 액션 다시 호출해도 no-op(빈 워크스페이스를 안 만든다).
    session.dispatchAppAction(.move_pane_to_new_workspace);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
}

test "move_pane_to_workspace:N 액션: 활성 pane을 N번 워크스페이스에 합치기(dispatch 경로) + 자기/범위 밖 no-op" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    _ = try session.newTab(); // [ws0, ws1]
    try std.testing.expect(session.switchTab(0)); // 활성 ws0
    try session.splitActivePane(.horizontal); // ws0: 2 pane, 활성 b
    const pane_b = session.activePane();

    // 자기 워크스페이스(0)로 merge → no-op.
    session.dispatchAppAction(.{ .move_pane_to_workspace = 0 });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items[0].panes.items.len); // 무변

    // 범위 밖(9)으로 merge → no-op.
    session.dispatchAppAction(.{ .move_pane_to_workspace = 9 });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items[0].panes.items.len); // 무변

    // ws1(index 1)로 merge → ws0은 1 pane, ws1은 2 pane, 활성 = ws1, 합쳐진 pane이 활성.
    session.dispatchAppAction(.{ .move_pane_to_workspace = 1 });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items[0].panes.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items[1].panes.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(pane_b, session.tabs.items[1].activePane());

    // ws1은 이제 2 pane(활성 b). b를 다시 ws0(index 0)로 merge → 단독 아님이라 동작(왕복).
    session.dispatchAppAction(.{ .move_pane_to_workspace = 0 });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items[0].panes.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items[1].panes.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
}

// paneAtPoint·paneInDirection 단위 테스트는 session core로 이동(Model 기반 헤드리스) — src/session/session_model.zig.

// paneBarBgCell이 바 rect를 sentinel-UV 배경 셀(origin 박힌, 폭=cols)로 만들고, 너무 작으면 null인지 — pane
// 탭 바 배경의 코어라 헤드리스 단위로 고정한다(순수 함수, OS 무관).
test "paneBarBgCell builds a bar-width background cell at the bar origin" {
    // 바 rect (x=180, y=0, w=96, h=12), cell 12 → 8칸. origin 박히고 sentinel UV(배경만), bg 지정색.
    const cell = paneBarBgCell(.{ .x = 180, .y = 0, .w = 96, .h = 12 }, 12, 0xFF112233).?;
    try std.testing.expectEqual(@as(u16, 8), cell.width); // 96/12 = 8칸(아래 터미널과 정렬)
    try std.testing.expectEqual(@as(u32, 180), cell.origin_x);
    try std.testing.expectEqual(@as(u32, 0), cell.origin_y);
    try std.testing.expectEqual(@as(u16, 0), cell.row);
    try std.testing.expectEqual(@as(u32, 0), cell.slot_id); // 배경 셀(밴드) — glyph 아님
    try std.testing.expectEqual(@as(f32, -1.0), cell.u0); // sentinel UV = 배경만
    try std.testing.expectEqual(@as(u32, 0xFF112233), cell.background);
    // 폭/높이/cell 0이면 null.
    try std.testing.expect(paneBarBgCell(.{ .x = 0, .y = 0, .w = 0, .h = 12 }, 12, 0xFF000000) == null);
    try std.testing.expect(paneBarBgCell(.{ .x = 0, .y = 0, .w = 96, .h = 12 }, 0, 0xFF000000) == null);
    try std.testing.expect(paneBarBgCell(.{ .x = 0, .y = 0, .w = 8, .h = 12 }, 12, 0xFF000000) == null); // 1칸 미만
}

// 탭 바 컬럼 분할 hit-test(tabIndex/inCloseZone/inPlusZone/hasPlusZone)는 chrome `tabbar.Metrics` 메서드로 이주(C3b) —
// 단위 테스트는 src/chrome/components/tabbar.zig. 여기선 platform이 그 hit-test와 공유하는 pointInRect 경계만 고정한다.
// barMetrics가 바를 [탭 영역 | "+" zone]으로 나누고 극단(셀·바·탭 0)에 null을 주는지, tabbarHighlightCell이 활성 탭
// 세그먼트 강조 셀(col=start·width·origin=bar)을 만드는지 — 탭 바 hit-test/렌더의 platform 측(메서드는 chrome tabbar.zig가
// 테스트). 옛 BarMetrics 단위 테스트의 init-null·highlightCell 케이스를 이리로 보존한다(C3b 리뷰 반영 — 이주로 빠졌던 커버리지).
test "barMetrics splits bar + tabbarHighlightCell active-tab band" {
    const bar: maru.session.SplitRect = .{ .x = 180, .y = 0, .w = 240, .h = 12 }; // cell 12 → 20칸, "+" zone 3 제외 탭 영역 17, 2탭 → tab_w=8
    const m = barMetrics(bar, 12, 2, 0, 0).?;
    try std.testing.expectEqual(@as(u32, 20), m.cols);
    try std.testing.expectEqual(@as(u32, 17), m.tab_cols);
    try std.testing.expectEqual(@as(u32, 8), m.tab_w);
    try std.testing.expectEqual(@as(u32, 180), m.bar_x);
    // 극단(셀 0·바 폭 0·탭 0)이면 null — 호출자가 탭 처리를 건너뛴다.
    try std.testing.expect(barMetrics(bar, 0, 2, 0, 0) == null);
    try std.testing.expect(barMetrics(.{ .x = 0, .y = 0, .w = 0, .h = 12 }, 12, 2, 0, 0) == null);
    try std.testing.expect(barMetrics(bar, 12, 0, 0, 0) == null);
    // tabbarHighlightCell: 탭 1 = col [8,16), origin=bar.x, sentinel-bg(slot_id 0).
    const cell = tabbarHighlightCell(m, 1, 0xFF445566).?;
    try std.testing.expectEqual(@as(u16, 8), cell.col); // 1*tab_w
    try std.testing.expectEqual(@as(u16, 8), cell.width);
    try std.testing.expectEqual(@as(u32, 180), cell.origin_x);
    try std.testing.expectEqual(@as(u32, 0xFF445566), cell.background);
    try std.testing.expectEqual(@as(u32, 0), cell.slot_id);
    try std.testing.expect(tabbarHighlightCell(m, 3, 0xFF000000) == null); // start(24) >= tab_cols(17) → 세그먼트 없음
}

// pane 라벨 세그먼트(PR2)의 폭 산출·탭 영역 offset 단일 출처 — custom_name 유무·좁은 바·max cap을 헤드리스로 고정한다.
// 이 두 함수가 render(라벨/탭 origin)와 hit-test(barMetrics 입력)에서 같은 결과를 줘 "보이는 == 클릭되는"을 유지한다.
test "paneLabelCols/paneTabBarRect: 라벨 없으면 0(전체 바), 있으면 폭 예약·탭 우측 offset" {
    const full: maru.session.SplitRect = .{ .x = 100, .y = 0, .w = 320, .h = 24 }; // cell 8 → 40칸

    // custom_name 없음 → label_cols 0, 탭 sub-rect == 전체 바(기존 동작).
    var bare: Pane = .{ .custom_name = null };
    try std.testing.expectEqual(@as(u32, 0), AppSession.paneLabelCols(&bare, 40));
    const t0 = AppSession.paneTabBarRect(full, 0, 8);
    try std.testing.expectEqual(@as(u32, 100), t0.x);
    try std.testing.expectEqual(@as(u32, 320), t0.w);

    // "build"(5칸) → want = 5 + 2(좌패딩·간격) = 7. bar_cols 40이라 cap 충분 → 7칸 예약, 탭이 그만큼 우측으로.
    var named: Pane = .{ .custom_name = "build" };
    const lc = AppSession.paneLabelCols(&named, 40);
    try std.testing.expectEqual(@as(u32, 7), lc);
    const t1 = AppSession.paneTabBarRect(full, lc, 8);
    try std.testing.expectEqual(@as(u32, 100 + 7 * 8), t1.x); // 라벨만큼 우측 offset
    try std.testing.expectEqual(@as(u32, 320 - 7 * 8), t1.w);

    // 좁은 바(bar_cols ≤ min_tab_cols=6)면 라벨 생략(탭 우선).
    try std.testing.expectEqual(@as(u32, 0), AppSession.paneLabelCols(&named, 6));

    // 긴 이름은 max_label(20)로 cap.
    var long: Pane = .{ .custom_name = "this-is-a-very-long-pane-name-indeed" };
    try std.testing.expectEqual(@as(u32, 20), AppSession.paneLabelCols(&long, 100));

    // 빈 custom_name("")도 없음으로 본다(app.pickLabel 규칙).
    var empty: Pane = .{ .custom_name = "" };
    try std.testing.expectEqual(@as(u32, 0), AppSession.paneLabelCols(&empty, 40));
}

// premultipliedRgba가 alpha로 rgb를 미리 곱하는지(④b 하이라이트 블렌딩). 순수. (pointInRect·paneDropZone·
// halfRect 단위 test는 함수와 함께 session/layout_math.zig로 이동 — b1.)
test "premultipliedRgba premultiplies rgb by alpha" {
    // 0xFFFFFFFF를 alpha 0x80(=128)으로 → rgb 각 255*128/255=128, a=0x80. premultiplied.
    try std.testing.expectEqual(@as(u32, 0x80_80_80_80), premultipliedRgba(0x00FF_FFFF, 0x80));
    try std.testing.expectEqual(@as(u32, 0x00_00_00_00), premultipliedRgba(0x00FF_FFFF, 0)); // alpha 0 → 전부 0
}

// PaneGeometry가 leaf 하나에서 bar/body/grid를 한 번만 투영하는지 — focus border(body)와 terminal 좌표(grid)가
// 같은 원본을 쓰고, tiny/minimal/과대 padding에서도 보수 관계와 body containment를 잃지 않는 SSOT 회귀다.
test "paneGeometry owns bar body and contained grid for normal tiny minimal and oversized padding" {
    var session: AppSession = undefined;
    // paneBarHeightPx → buildChromeTokens가 appearance(theme·chrome_theme)를 읽으므로 undefined 세션에 명시 초기화한다
    // (chrome_theme=.tui → tab_bar_pad_y_px=3 → 바=cell+6). 이 테스트는 tui 셀 기하를 검증하므로 기본값(rich)과
    // 무관하게 tui로 고정한다(rich면 pad_y=6 → 바=cell+12). undefined 필드 읽기 UB(0xaa 우연 green) 회피.
    session.appearance = config_mod.resolveAppearance(.{ .chrome_theme = .tui }) catch unreachable;
    session.chrome_minimal = false; // paneBarHeightPx가 읽는다(false=바 있음)
    session.cell_width_px = 12;
    session.cell_height_px = 12; // paneBarHeightPx = cell_height + 2*pad_y(tui 3) = 18
    session.window_padding_px = .{}; // paneTermRect가 이제 padding을 읽는다 — 바 기하만 격리(undefined UB 회피)

    const rect: maru.session.SplitRect = .{ .x = 180, .y = 0, .w = 800, .h = 600 };
    var geometry = session.paneGeometry(rect);
    const term = geometry.grid;
    try std.testing.expectEqual(maru.session.SplitRect{ .x = 180, .y = 18, .w = 800, .h = 582 }, geometry.body); // 바 18(=cell 12 + pad 3*2) 아래
    try std.testing.expectEqual(geometry.body, term); // padding 0이면 body=grid
    const bar = geometry.bar.?;
    try std.testing.expectEqual(maru.session.SplitRect{ .x = 180, .y = 0, .w = 800, .h = 18 }, bar);
    // 바 + 터미널 = leaf rect(틈 없음).
    try std.testing.expectEqual(rect.h, bar.h + term.h);

    // 바 높이 이하의 작은 rect는 바 없음 — 터미널이 leaf rect 전체, paneBarRect는 null.
    const tiny: maru.session.SplitRect = .{ .x = 0, .y = 0, .w = 100, .h = 12 };
    geometry = session.paneGeometry(tiny);
    try std.testing.expectEqual(tiny, geometry.body);
    try std.testing.expectEqual(tiny, geometry.grid);
    try std.testing.expect(geometry.bar == null);

    // 비대칭 padding은 body를 움직이지 않고 grid만 inset한다.
    session.window_padding_px = .{ .left = 10, .right = 20, .top = 4, .bottom = 8 };
    geometry = session.paneGeometry(rect);
    try std.testing.expectEqual(maru.session.SplitRect{ .x = 180, .y = 18, .w = 800, .h = 582 }, geometry.body);
    try std.testing.expectEqual(maru.session.SplitRect{ .x = 190, .y = 22, .w = 770, .h = 570 }, geometry.grid);

    // 과대 padding은 grid를 body 끝의 zero rect로 clamp한다. origin/end 어느 쪽도 body 밖으로 나가지 않는다.
    session.window_padding_px = .{ .left = 2000, .right = 3000, .top = 4000, .bottom = 5000 };
    geometry = session.paneGeometry(rect);
    const body_right = geometry.body.x + geometry.body.w;
    const body_bottom = geometry.body.y + geometry.body.h;
    try std.testing.expectEqual(body_right, geometry.grid.x);
    try std.testing.expectEqual(body_bottom, geometry.grid.y);
    try std.testing.expectEqual(@as(u32, 0), geometry.grid.w);
    try std.testing.expectEqual(@as(u32, 0), geometry.grid.h);
    try std.testing.expect(geometry.grid.x + geometry.grid.w <= body_right);
    try std.testing.expect(geometry.grid.y + geometry.grid.h <= body_bottom);

    // rich는 tab bar padding이 더 크지만 같은 보수 관계를 유지한다.
    session.appearance = config_mod.resolveAppearance(.{ .chrome_theme = .rich }) catch unreachable;
    session.window_padding_px = .{};
    geometry = session.paneGeometry(rect);
    const rich_bar = geometry.bar.?;
    try std.testing.expectEqual(rect.x, rich_bar.x);
    try std.testing.expectEqual(rect.y, rich_bar.y);
    try std.testing.expectEqual(rect.w, rich_bar.w);
    try std.testing.expectEqual(rect.h, rich_bar.h + geometry.body.h);
    try std.testing.expectEqual(rect.y + rich_bar.h, geometry.body.y);
    try std.testing.expectEqual(geometry.body, geometry.grid);

    // minimal은 tab bar 정책 자체가 꺼져 body=leaf다. padding은 여전히 grid에만 적용된다.
    session.chrome_minimal = true;
    session.window_padding_px = .{ .left = 3, .right = 5, .top = 7, .bottom = 11 };
    geometry = session.paneGeometry(rect);
    try std.testing.expect(geometry.bar == null);
    try std.testing.expectEqual(rect, geometry.body);
    try std.testing.expectEqual(maru.session.SplitRect{ .x = 183, .y = 7, .w = 792, .h = 582 }, geometry.grid);
}

test "FP9 active-pane projection rejects partial layout OOM and recovers" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);
    session.window_focused = true;
    session.focus_owner = .workspace;

    // 실제 SplitTree.layout이 append 뒤 후속 grow에서 실패하는 partial-prefix를 만든다. leaf는 트리 소유가 아니므로
    // 같은 유효 pane pointer를 반복한 synthetic tree로 PTY 32개를 만들지 않고 allocator failure만 격리한다.
    const active = session.activePane();
    var tree: PaneTree.Node = .{ .leaf = active };
    for (1..32) |_| {
        const split = try allocator.create(PaneTree.Split);
        split.* = .{
            .direction = .horizontal,
            .ratio = 0.5,
            .a = .{ .leaf = active },
            .b = tree,
        };
        tree = .{ .split = split };
    }
    defer PaneTree.deinit(allocator, tree);

    var saw_partial_oom = false;
    for (0..16) |fail_index| {
        var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = fail_index });
        var partial: std.ArrayList(PaneTree.LeafRect) = .empty;
        defer partial.deinit(failing.allocator());
        if (PaneTree.layout(failing.allocator(), tree, session.termRect(), &partial)) |_| {} else |err| {
            if (err == error.OutOfMemory and partial.items.len > 0) {
                saw_partial_oom = true;
                var rejected: ?AppSession.PaneGeometry = null;
                for (partial.items) |leaf| session.captureActivePaneGeometry(false, active, leaf, &rejected);
                try std.testing.expect(rejected == null);
                session.dropQuadsByLayer(1);
                session.drag_overlay_cells_scratch.clearRetainingCapacity();
                session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, if (rejected) |g| g.body else null);
                var failed_border_quads: usize = 0;
                for (session.gpu_quads.items) |quad| failed_border_quads += @intFromBool(quad.layer == 1);
                try std.testing.expectEqual(@as(usize, 0), failed_border_quads);
                try std.testing.expectEqual(@as(usize, 0), session.drag_overlay_cells_scratch.items.len);
                break;
            }
        }
    }
    try std.testing.expect(saw_partial_oom);

    // layout 자체는 완료됐어도 active identity가 slice에 없으면 같은 fail-close를 적용하고 stale body를 재사용하지 않는다.
    var foreign_pane: Pane = undefined;
    var identity_rejected: ?AppSession.PaneGeometry = null;
    session.captureActivePaneGeometry(true, active, .{
        .leaf = &foreign_pane,
        .rect = session.termRect(),
    }, &identity_rejected);
    try std.testing.expect(identity_rejected == null);
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, if (identity_rejected) |g| g.body else null);
    var identity_border_quads: usize = 0;
    for (session.gpu_quads.items) |quad| identity_border_quads += @intFromBool(quad.layer == 1);
    try std.testing.expectEqual(@as(usize, 0), identity_border_quads);
    try std.testing.expectEqual(@as(usize, 0), session.drag_overlay_cells_scratch.items.len);

    // 다음 정상 projection은 같은 tree를 완주한 뒤 body를 복원하고 정확히 border 4 + sentinel 1을 만든다.
    var complete: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer complete.deinit(allocator);
    try PaneTree.layout(allocator, tree, session.termRect(), &complete);
    var recovered: ?AppSession.PaneGeometry = null;
    for (complete.items) |leaf| session.captureActivePaneGeometry(true, active, leaf, &recovered);
    try std.testing.expect(recovered != null);
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, recovered.?.body);
    var border_quads: usize = 0;
    for (session.gpu_quads.items) |quad| border_quads += @intFromBool(quad.layer == 1);
    try std.testing.expectEqual(@as(usize, 4), border_quads);
    try std.testing.expectEqual(@as(usize, 1), session.drag_overlay_cells_scratch.items.len);
}

test "FP9 active-pane projection adds no layout scan or allocation at workspace pane cap" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const active = session.activePane();
    var counting = std.testing.FailingAllocator.init(allocator, .{});
    session.allocator = counting.allocator();
    var existing_chrome_leaf_visits: usize = 0;
    for (0..1000) |frame| {
        var projection: ?AppSession.PaneGeometry = null;
        // production처럼 기존 chrome leaf 방문 안에서 capture를 호출한다. capture API에는 tree/layout/allocator가 없어
        // 별도 layout call이나 내부 leaf scan을 만들 수 없고, 첫 active match 뒤에는 고정 비교 한 번뿐이다.
        for (0..maru.session.workspace.max_panes_per_tab) |leaf_index| {
            existing_chrome_leaf_visits += 1;
            session.captureActivePaneGeometry(true, active, .{
                .leaf = active,
                .rect = .{
                    .x = @intCast(leaf_index),
                    .y = @intCast(frame % 64),
                    .w = 800,
                    .h = 600,
                },
            }, &projection);
        }
        try std.testing.expect(projection != null);
    }
    session.allocator = allocator;
    try std.testing.expectEqual(@as(usize, 1000) * maru.session.workspace.max_panes_per_tab, existing_chrome_leaf_visits);
    try std.testing.expectEqual(@as(usize, 0), counting.allocations);
    try std.testing.expect(!counting.has_induced_failure);
}

test "FP9 workspace focus border uses pane body and fails closed for non-key or unknown leaf" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.window_padding_px = .{ .left = 10, .right = 20, .top = 4, .bottom = 8 };
    _ = try session.resize(1400, 900, 1000);

    var leaves: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaves.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaves);
    const active = session.activePane();
    var active_geometry: ?AppSession.PaneGeometry = null;
    for (leaves.items) |leaf| {
        if (leaf.leaf == active) active_geometry = session.paneGeometry(leaf.rect);
    }
    const geometry = active_geometry orelse return error.MissingActivePaneGeometry;
    try std.testing.expect(geometry.body.x < geometry.grid.x);
    try std.testing.expect(geometry.body.y < geometry.grid.y);
    const thickness = session.buildChromeTokens().border.line_thickness_px;
    session.appearance.split_divider_thickness = 0; // focus border 두께/표시는 divider 설정과 독립이다.

    // 실제 frame path가 같은 active leaf의 body를 넘기는지 고정한다. direct helper test만으로는 caller가 다시 grid를
    // 넘기는 회귀를 잡지 못하므로 tick 결과의 layer-1 quad를 먼저 확인한다.
    session.metal_dirty = true;
    _ = try session.tick();
    var frame_border_quads: usize = 0;
    var frame_saw_body_top = false;
    var frame_saw_body_bottom = false;
    var frame_saw_body_left = false;
    var frame_saw_body_right = false;
    var frame_saw_grid_top = false;
    for (session.gpu_quads.items) |quad| if (quad.layer == 1) {
        frame_border_quads += 1;
        frame_saw_body_top = frame_saw_body_top or (quad.x == @as(f32, @floatFromInt(geometry.body.x)) and
            quad.y == @as(f32, @floatFromInt(geometry.body.y)) and
            quad.w == @as(f32, @floatFromInt(geometry.body.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
        frame_saw_body_bottom = frame_saw_body_bottom or (quad.x == @as(f32, @floatFromInt(geometry.body.x)) and
            quad.y == @as(f32, @floatFromInt(geometry.body.y + geometry.body.h - thickness)) and
            quad.w == @as(f32, @floatFromInt(geometry.body.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
        frame_saw_body_left = frame_saw_body_left or (quad.x == @as(f32, @floatFromInt(geometry.body.x)) and
            quad.y == @as(f32, @floatFromInt(geometry.body.y + thickness)) and
            quad.w == @as(f32, @floatFromInt(thickness)) and
            quad.h == @as(f32, @floatFromInt(geometry.body.h - 2 * thickness)));
        frame_saw_body_right = frame_saw_body_right or (quad.x == @as(f32, @floatFromInt(geometry.body.x + geometry.body.w - thickness)) and
            quad.y == @as(f32, @floatFromInt(geometry.body.y + thickness)) and
            quad.w == @as(f32, @floatFromInt(thickness)) and
            quad.h == @as(f32, @floatFromInt(geometry.body.h - 2 * thickness)));
        frame_saw_grid_top = frame_saw_grid_top or (quad.x == @as(f32, @floatFromInt(geometry.grid.x)) and
            quad.y == @as(f32, @floatFromInt(geometry.grid.y)) and
            quad.w == @as(f32, @floatFromInt(geometry.grid.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
    };
    try std.testing.expectEqual(@as(usize, 4), frame_border_quads);
    try std.testing.expect(frame_saw_body_top);
    try std.testing.expect(frame_saw_body_bottom);
    try std.testing.expect(frame_saw_body_left);
    try std.testing.expect(frame_saw_body_right);
    try std.testing.expect(!frame_saw_grid_top);

    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, geometry.body);
    var saw_body_top = false;
    var saw_grid_top = false;
    var border_quads: usize = 0;
    for (session.gpu_quads.items) |quad| if (quad.layer == 1) {
        border_quads += 1;
        saw_body_top = saw_body_top or (quad.x == @as(f32, @floatFromInt(geometry.body.x)) and
            quad.y == @as(f32, @floatFromInt(geometry.body.y)) and
            quad.w == @as(f32, @floatFromInt(geometry.body.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
        saw_grid_top = saw_grid_top or (quad.x == @as(f32, @floatFromInt(geometry.grid.x)) and
            quad.y == @as(f32, @floatFromInt(geometry.grid.y)) and
            quad.w == @as(f32, @floatFromInt(geometry.grid.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
    };
    try std.testing.expectEqual(@as(usize, 4), border_quads);
    try std.testing.expect(saw_body_top);
    try std.testing.expect(!saw_grid_top);
    try std.testing.expectEqual(@as(usize, 1), session.drag_overlay_cells_scratch.items.len); // overlay presence sentinel

    // 비-key window와 active-leaf lookup 실패(null)는 잘못된 전체-domain focus cue를 만들지 않는다.
    session.window_focused = false;
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, geometry.body);
    var non_key_border_quads: usize = 0;
    for (session.gpu_quads.items) |quad| non_key_border_quads += @intFromBool(quad.layer == 1);
    try std.testing.expectEqual(@as(usize, 0), non_key_border_quads);
    try std.testing.expectEqual(@as(usize, 0), session.drag_overlay_cells_scratch.items.len);
    session.window_focused = true;
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, null);
    var unknown_leaf_border_quads: usize = 0;
    for (session.gpu_quads.items) |quad| unknown_leaf_border_quads += @intFromBool(quad.layer == 1);
    try std.testing.expectEqual(@as(usize, 0), unknown_leaf_border_quads);
    try std.testing.expectEqual(@as(usize, 0), session.drag_overlay_cells_scratch.items.len);
}

test "focus border suppressed while notification panel or context menu is open" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.window_padding_px = .{ .left = 10, .right = 20, .top = 4, .bottom = 8 };
    _ = try session.resize(1400, 900, 1000);
    session.window_focused = true;
    session.focus_owner = .workspace;

    var leaves: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaves.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaves);
    var active_geometry: ?AppSession.PaneGeometry = null;
    for (leaves.items) |leaf| {
        if (leaf.leaf == session.activePane()) active_geometry = session.paneGeometry(leaf.rect);
    }
    const geometry = active_geometry orelse return error.MissingActivePaneGeometry;

    const countLayerOne = struct {
        fn f(s: *AppSession) usize {
            var n: usize = 0;
            for (s.gpu_quads.items) |quad| n += @intFromBool(quad.layer == 1);
            return n;
        }
    }.f;

    // 기준선: 오버레이 없음 → inputFocus()==.terminal라 4개 테두리 quad.
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, geometry.body);
    try std.testing.expectEqual(@as(usize, 4), countLayerOne(session));

    // 알림 패널 열림 → 테두리 0개 + overlay presence sentinel도 안 남긴다(모달 위로 뜨던 보더라인 제거). context_menu·
    // notifications는 InputFocus enum 밖이라 inputFocus()만으론 못 걸렀던 gap — anyOverlayOpen 가드가 닫는다.
    session.chrome_host.notifications.open = true;
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, geometry.body);
    try std.testing.expectEqual(@as(usize, 0), countLayerOne(session));
    try std.testing.expectEqual(@as(usize, 0), session.drag_overlay_cells_scratch.items.len);
    session.chrome_host.notifications.open = false;

    // context_menu도 같은 gap이라 함께 억제된다(커서 unfocus와 동일 판정).
    session.chrome_host.context_menu.open = true;
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, geometry.body);
    try std.testing.expectEqual(@as(usize, 0), countLayerOne(session));
    session.chrome_host.context_menu.open = false;

    // 오버레이 닫으면 다시 4개(회귀 방지 — 가드가 영구 억제가 아님).
    session.dropQuadsByLayer(1);
    session.drag_overlay_cells_scratch.clearRetainingCapacity();
    session.appendFocusOwnerBorder(&session.drag_overlay_cells_scratch, geometry.body);
    try std.testing.expectEqual(@as(usize, 4), countLayerOne(session));
}

test "FP9 production frame follows active pane body across horizontal and vertical split" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    session.appearance.chrome_theme = .rich;
    session.window_padding_px = .{ .left = 11, .right = 17, .top = 5, .bottom = 9 };
    _ = try session.resize(1400, 900, 1000);
    try session.splitActivePane(.horizontal);
    session.window_focused = true;
    session.focus_owner = .workspace;

    var leaves: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaves.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaves);
    var horizontal_geometry: ?AppSession.PaneGeometry = null;
    for (leaves.items) |leaf| {
        if (leaf.leaf == session.activePane()) horizontal_geometry = session.paneGeometry(leaf.rect);
    }
    const horizontal = horizontal_geometry orelse return error.MissingHorizontalActivePaneGeometry;
    try std.testing.expect(horizontal.body.x < horizontal.grid.x);
    session.metal_dirty = true;
    _ = try session.tick();
    const thickness = session.buildChromeTokens().border.line_thickness_px;
    var horizontal_quads: usize = 0;
    var horizontal_top = false;
    for (session.gpu_quads.items) |quad| if (quad.layer == 1) {
        horizontal_quads += 1;
        horizontal_top = horizontal_top or (quad.x == @as(f32, @floatFromInt(horizontal.body.x)) and
            quad.y == @as(f32, @floatFromInt(horizontal.body.y)) and
            quad.w == @as(f32, @floatFromInt(horizontal.body.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
    };
    try std.testing.expectEqual(@as(usize, 4), horizontal_quads);
    try std.testing.expect(horizontal_top);

    const root_split = switch (session.activeTab().tree) {
        .split => |split| split,
        .leaf => return error.MissingSplitRoot,
    };
    root_split.direction = .vertical;
    try session.resizeActiveTabPanes();
    session.recomputeActivePaneRect();
    leaves.clearRetainingCapacity();
    try session.activeTabLeafRects(allocator, session.termRect(), &leaves);
    var vertical_geometry: ?AppSession.PaneGeometry = null;
    for (leaves.items) |leaf| {
        if (leaf.leaf == session.activePane()) vertical_geometry = session.paneGeometry(leaf.rect);
    }
    const vertical = vertical_geometry orelse return error.MissingVerticalActivePaneGeometry;
    try std.testing.expect(vertical.body.y > horizontal.body.y);
    try std.testing.expect(vertical.body.x < horizontal.body.x);
    try std.testing.expect(vertical.body.y < vertical.grid.y);
    session.metal_dirty = true;
    _ = try session.tick();
    var vertical_quads: usize = 0;
    var vertical_top = false;
    for (session.gpu_quads.items) |quad| if (quad.layer == 1) {
        vertical_quads += 1;
        vertical_top = vertical_top or (quad.x == @as(f32, @floatFromInt(vertical.body.x)) and
            quad.y == @as(f32, @floatFromInt(vertical.body.y)) and
            quad.w == @as(f32, @floatFromInt(vertical.body.w)) and
            quad.h == @as(f32, @floatFromInt(thickness)));
    };
    try std.testing.expectEqual(@as(usize, 4), vertical_quads);
    try std.testing.expect(vertical_top);
}

// per-pane 탭 바가 실제로 예약·렌더되는지 — 실 init/resize/tick이 도는 macOS 경로라 게이트. 터미널 영역이
// 바 아래에서 시작하고(active_pane_rect.y = 바 높이), tick이 cells 맨 앞에 바 배경 chrome 셀을 낸다.
test "pane reserves a top tab-bar strip and renders a bar chrome cell" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .tui; // tui 셀 바 기하 검증(기본값 rich는 tab_bar_pad_y_px·바 배경 quad가 달라짐) — resize 전에 고정

    // 창 크기를 잡는다(resize가 backing 보관 + 모든 panel을 바 아래 grid로 + active_pane_rect 재계산).
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 단일 panel: 터미널 영역(active_pane_rect)은 사이드바 옆·상단 타이틀바 띠 + 바 아래(y = 띠 + 바 높이)에서 시작.
    try std.testing.expectEqual(session.sidebar_width_px, session.active_pane_rect.x);
    try std.testing.expectEqual(session.titlebar_strip_px + session.paneBarHeightPx(), session.active_pane_rect.y);
    try std.testing.expect(session.active_pane_rect.h < session.backing_height_px);

    // tick이 바 chrome 셀을 포함해 크래시 없이 돈다. chrome(바 배경)은 cells 맨 앞에 prepend된다 —
    // 첫 셀은 바 top(origin_y = leaf rect top = 상단 띠)·sentinel UV(slot_id 0)·불투명 bg.
    _ = try session.tick();
    const frame = session.metalFrame();
    try std.testing.expect(frame.cell_count >= 1);
    const first = frame.cells.?[0];
    try std.testing.expectEqual(session.titlebar_strip_px, first.origin_y);
    try std.testing.expectEqual(@as(u32, 0), first.slot_id);
    try std.testing.expectEqual(@as(u32, 0xFF), first.background >> 24); // 불투명 바 배경
}

// Phase 4e-3: computeWebSurfaceTransitions가 활성 워크스페이스 탭 pane 트리를 walk해 **web Term마다** 전이를 낸다 —
// 자기 pane 본문 rect(탭 바 아래) + visible(자기 pane 활성 탭인가)을 계산하고 prev를 전진시켜 무변경 tick은 batch를
// 비운다(§6·§10 4e-3). 실 init/resize가 도는 macOS 경로라 게이트(sentinel surface·registry가 필요).
test "web surface transitions: per-Term batch carries visibility and advances prev" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // web Term이 없으면 batch가 빈다(터미널만 있는 평시).
    try std.testing.expectEqual(@as(usize, 0), session.webSurfaceTransitionsCount());

    // 활성 pane에 web Term 하나를 만들어 활성화(디버그 훅과 같은 경로).
    const w1 = try session.createWebTerm(.browser);
    const pane = session.activePane();
    try pane.terms.append(allocator, w1);
    session.focusTerm(pane.terms.items.len - 1);

    // 첫 계산: web1 create(자기 pane 활성 탭이라 visible), 자기 pane 본문 rect는 탭 바 아래라 유한·양수 폭/높이.
    try std.testing.expectEqual(@as(usize, 1), session.webSurfaceTransitionsCount());
    const t1 = session.webSurfaceTransitionAt(0);
    try std.testing.expectEqual(WebSurfaceOp.create, t1.op);
    try std.testing.expectEqual(w1.surfaceId(), t1.surface_id);
    try std.testing.expect(t1.visible);
    try std.testing.expectEqual(web_panel_layout.PanelKind.browser, t1.panel_kind);
    try std.testing.expect(t1.frame_pt.w > 0 and t1.frame_pt.h > 0);

    // 무변경 tick: prev가 전진했으므로 batch가 빈다(§10 "diff 있을 때만 sync").
    try std.testing.expectEqual(@as(usize, 0), session.webSurfaceTransitionsCount());

    // 같은 pane에 web Term 하나 더(비활성 탭 — 활성은 web1 유지) → create + visible=false(hidden 생성해 상태만 유지).
    const w2 = try session.createWebTerm(.markdown);
    try pane.terms.append(allocator, w2);
    try std.testing.expectEqual(@as(usize, 1), session.webSurfaceTransitionsCount());
    const t2 = session.webSurfaceTransitionAt(0);
    try std.testing.expectEqual(WebSurfaceOp.create, t2.op);
    try std.testing.expectEqual(w2.surfaceId(), t2.surface_id);
    try std.testing.expect(!t2.visible); // 자기 pane 활성 탭이 아니므로 hidden 생성(§6)
    try std.testing.expectEqual(web_panel_layout.PanelKind.markdown, t2.panel_kind);

    // 범위 밖 조회는 op=none(무동작 폴백).
    try std.testing.expectEqual(WebSurfaceOp.none, session.webSurfaceTransitionAt(5).op);
}

test "createAdoptedWebTermInActivePane: 활성 pane에 browser web Term 새 탭 + surface_id 반환 (7f-0 헤드리스)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = session.activePane();
    const terms_before = pane.terms.items.len;

    // 팝업 adopt term 생성 → 유효 surface_id 반환(1부터 발급, 0=sentinel).
    const sid = try session.createAdoptedWebTermInActivePane();
    try std.testing.expect(sid != 0);

    // 활성 pane에 새 탭이 하나 늘고, 마지막 Term이 browser web이며 focusTerm으로 활성이다.
    try std.testing.expectEqual(terms_before + 1, pane.terms.items.len);
    const term = pane.terms.items[pane.terms.items.len - 1];
    try std.testing.expect(term.kind == .web);
    try std.testing.expect(term.web_panel_kind == .browser); // 팝업=untrusted browser 고정
    try std.testing.expectEqual(sid, term.surfaceId());
    try std.testing.expectEqual(pane.terms.items.len - 1, pane.active_term);

    // 반환 id == activeWebSurfaceId(7e-4 nav 단축키 게이트가 소비) — 새 팝업 탭이 활성 browser.
    try std.testing.expectEqual(sid, session.activeWebSurfaceId());

    // create 전이가 이 surface에 emit(활성 탭이라 visible) — Swift drain이 소비하며 7f-1이 중복 WKWebView 생성을 스킵.
    try std.testing.expectEqual(@as(usize, 1), session.webSurfaceTransitionsCount());
    const t = session.webSurfaceTransitionAt(0);
    try std.testing.expectEqual(WebSurfaceOp.create, t.op);
    try std.testing.expectEqual(sid, t.surface_id);
    try std.testing.expect(t.visible);
    try std.testing.expect(t.panel_kind == .browser);
}

test "activeWebSurfaceIdAnyKind: web term(browser·markdown)이면 id, terminal이면 0 (4g-0 헤드리스)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const pane = session.activePane();

    // 초기: 활성 term = terminal → any_kind 0(browser 전용 activeWebSurfaceId도 0).
    try std.testing.expectEqual(@as(u64, 0), session.activeWebSurfaceIdAnyKind());
    try std.testing.expectEqual(@as(u64, 0), session.activeWebSurfaceId());

    // markdown web term 새 탭 + 활성 → any_kind = id, 하지만 browser 전용은 0(markdown이라 — 이게 4g-0의 핵심 구분).
    const md = try session.createWebTerm(.markdown);
    try pane.terms.append(allocator, md);
    session.focusTerm(pane.terms.items.len - 1);
    try std.testing.expectEqual(md.surfaceId(), session.activeWebSurfaceIdAnyKind());
    try std.testing.expectEqual(@as(u64, 0), session.activeWebSurfaceId());

    // browser web term 새 탭 + 활성 → 둘 다 id.
    const br = try session.createWebTerm(.browser);
    try pane.terms.append(allocator, br);
    session.focusTerm(pane.terms.items.len - 1);
    try std.testing.expectEqual(br.surfaceId(), session.activeWebSurfaceIdAnyKind());
    try std.testing.expectEqual(br.surfaceId(), session.activeWebSurfaceId());
}

// 4e-5: new_web_tab dispatch가 활성 pane에 web Term을 append+활성화(4e-1/2/3 경로 재사용)하고, tick epilogue가
// FrameSummary.web_surfaces_present를 세우는지 + minimal(tabsBlocked)에선 무동작인지. 실 init/spawn/tick 경로라 게이트.
test "new_web_tab dispatch: 활성 pane에 web Term append+활성 + web_surfaces_present 신호 (minimal=no-op)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // ① full 세션(tabsBlocked=false): new_web_tab이 web Term을 append+활성화한다.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

        const pane = session.activePane();
        const before = pane.terms.items.len; // 첫 터미널 Term 하나
        try std.testing.expect(!session.windowHasWebTerm());

        session.dispatchAppAction(.new_web_tab);

        // 활성 pane의 마지막 Term이 web이고 활성(active_term)인지.
        try std.testing.expectEqual(before + 1, pane.terms.items.len);
        const last = pane.terms.items[pane.terms.items.len - 1];
        try std.testing.expect(last.kind == .web);
        try std.testing.expectEqual(pane.terms.items.len - 1, pane.active_term);
        try std.testing.expectEqual(web_panel_layout.PanelKind.browser, last.web_panel_kind);
        try std.testing.expect(session.windowHasWebTerm());

        // tick epilogue가 web_surfaces_present=1을 실는다(비-vacuous — 대입 없으면 기본 0). 활성 web Term은 4e-2가 렌더 skip → 크래시 0.
        const summary = try session.tick();
        try std.testing.expectEqual(@as(u32, 1), summary.web_surfaces_present);
    }

    // ② minimal 스크래치(chrome_minimal=1·minimal_tabs=0 → tabsBlocked): new_web_tab이 무동작(new_term/new_tab과 동일 가드).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            .chrome_minimal = 1,
            .minimal_tabs = 0,
        });
        defer session.deinit();
        try std.testing.expect(session.tabsBlocked());
        session.dispatchAppAction(.new_web_tab);
        try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len); // web Term 안 생김
        try std.testing.expect(!session.windowHasWebTerm());
    }
}

// 4e-5/FP16c: web_surfaces_present는 **유지 카운터가 아니라 창 전체 pane 트리에서 매 tick 파생**된 신호다(windowHasWebTerm).
// 그래서 web Term이 **비활성 탭**으로 가면(다른 워크스페이스로 전환) 신호가 off된다 — 유지 카운터로는 불가능했던, collectWebSurfaces와
// 같은 활성-탭 범위의 핵심(창 간 이동에서 카운터가 드리프트하던 버그를 이 범위 정합이 근본 해소). 실 init/spawn/tick 경로라 게이트.
test "web_surfaces_present는 창 전체 트리에서 매 tick 파생된다(유지 카운터 드리프트 없음)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 처음(터미널만): 신호 off.
    try std.testing.expect(!session.windowHasWebTerm());

    // 활성 탭(워크스페이스 0)에 web Term 생성+활성화 → 신호 on, tick summary=1.
    session.dispatchAppAction(.new_web_tab);
    try std.testing.expect(session.windowHasWebTerm());
    try std.testing.expectEqual(@as(u32, 1), (try session.tick()).web_surfaces_present);

    // 터미널 전용 새 워크스페이스 탭으로 전환해도 신호는 on이다 — FP16c에서 수집 범위가 창 전체가 됐고
    // presence 신호도 같은 범위여야 비활성 워크스페이스의 첫 web surface 전이가 적용된다.
    _ = try session.newTab();
    try std.testing.expect(session.windowHasWebTerm());
    try std.testing.expectEqual(@as(u32, 1), (try session.tick()).web_surfaces_present);

    // 원래 탭(0)으로 돌아와도 같다(유지 카운터가 아니라 매 tick 트리에서 파생 — 드리프트 없음).
    _ = session.switchTab(0);
    try std.testing.expect(session.windowHasWebTerm());
    try std.testing.expectEqual(@as(u32, 1), (try session.tick()).web_surfaces_present);

    // 그 web Term을 닫으면(closeActiveTerm=terms에서 제거+destroyTerm+재바인딩 — 트리 신호가 정확히 반영되려면 트리에서도
    // 빠져야 하므로 raw destroyTerm이 아닌 close 경로) 신호 off. tick summary=0.
    session.closeActiveTerm(); // 활성 pane의 활성 Term(web)을 닫는다(pane에 terminal+web 2개라 동작).
    try std.testing.expect(!session.windowHasWebTerm());
    try std.testing.expectEqual(@as(u32, 0), (try session.tick()).web_surfaces_present);
}

// [4e review 1] allTabsTerminated: 살아 있는 web Term(sentinel core라 live_initialized=false)이 남으면 세션을 종료로
// 판정하지 않는다 — 터미널만 다 죽고 web만 남은 창이 통째로 닫히던 회귀 방지. 실 init/spawn 경로라 게이트(수정 전엔 true).
test "allTabsTerminated: web-only 잔여는 세션을 살려 둔다(web-only 창 종료 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.dispatchAppAction(.new_web_tab); // pane=[terminal, web], web 활성
    const pane = session.activePane();
    try std.testing.expectEqual(@as(usize, 2), pane.terms.items.len);

    // 터미널(인덱스 0)을 활성으로 만들어 닫아 web만 남긴다.
    session.focusTerm(0);
    try std.testing.expect(pane.terms.items[pane.active_term].kind == .terminal);
    session.closeActiveTerm();
    try std.testing.expectEqual(@as(usize, 1), pane.terms.items.len);
    try std.testing.expect(pane.terms.items[0].kind == .web);

    // 살아 있는 web Term이 남았으니 종료로 판정되면 안 된다(수정 전: web는 live_initialized=false라 true=창 닫힘).
    try std.testing.expect(!session.allTabsTerminated());
}

// [4e review 2] cwdSourceTerm/focusedTermCwd: 활성 Term이 web이면 sentinel core(빈 cwd)가 아니라 pane 내 terminal
// 형제에서 cwd를 상속한다 — 새 surface spawn cwd가 루트로 폴백하던 회귀 방지. 실 init/OSC7 경로라 게이트(수정 전: null).
test "cwdSourceTerm: web 활성이면 terminal 형제로 cwd 상속(sentinel→루트 폴백 아님)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    try session.activeSurface().core.write("\x1b]7;file://h/tmp/proj\x07"); // 터미널에 OSC 7 cwd
    const term_sibling = session.activePane().activeTerm();

    session.dispatchAppAction(.new_web_tab); // pane=[terminal, web], web 활성
    const pane = session.activePane();
    try std.testing.expect(pane.activeTerm().kind == .web);

    // cwdSourceTerm은 sentinel(web)이 아니라 terminal 형제를 골라야 한다.
    try std.testing.expectEqual(term_sibling, session.cwdSourceTerm().?);

    // focusedTermCwd도 web sentinel(빈 cwd) 대신 terminal 형제 cwd를 복사해 돌려준다(수정 전: sentinel→null).
    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd = session.focusedTermCwd(&buf);
    try std.testing.expect(cwd != null);
    try std.testing.expectEqualStrings("/tmp/proj", cwd.?);
}

// [4e review 6] windowTitle: 활성 web Term은 sentinel core의 빈 제목이 아니라 kind 파생 라벨("Browser")을 반환한다.
// 실 init/spawn 경로라 게이트(수정 전엔 빈 슬라이스).
test "windowTitle: 활성 web Term은 kind 라벨(Browser)을 반환(sentinel 빈 제목 아님)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.dispatchAppAction(.new_web_tab); // web(browser) Term 활성화
    try std.testing.expect(session.activePane().activeTerm().kind == .web);
