// [4e review 0] collectWebSurfaces seam inset 검증 헬퍼 — 각 web 본문 rect가 seam(형제 pane 경계) 가장자리서 `seam`만큼,
// 바깥 경계는 0, top은 탭 바(bar_h) + (7e-1b) browser면 주소창 밴드(addr_h=bar_h)까지 들어갔는지 확인하고 어느 seam을
// 실제로 밟았는지 [left,right,bottom]로 돌려준다. markdown web은 top=bar_h(주소창 없음), browser web은 top=2·bar_h.
fn checkWebSeamInsets(session: *AppSession, seam: u32, allocator: std.mem.Allocator) ![3]bool {
    var leaves: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer leaves.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &leaves);
    var cur: std.ArrayList(web_panel_layout.SurfaceLayout) = .empty;
    defer cur.deinit(allocator);
    try session.collectWebSurfaces(&cur);
    const tr = session.termRect();
    const bar_h = session.paneBarHeightPx();
    var saw = [3]bool{ false, false, false }; // left, right, bottom seam을 실제 밟았는지(non-vacuous)
    for (cur.items) |s| {
        var lr: ?maru.session.SplitRect = null;
        for (leaves.items) |lf| for (lf.leaf.terms.items) |t| {
            if (t.kind == .web and t.surfaceId() == s.surface_id) lr = lf.rect;
        };
        const rect = lr.?;
        const cr = s.content_rect;
        const el: u32 = if (rect.x > tr.x) seam else 0;
        const er: u32 = if (rect.x + rect.w < tr.x + tr.w) seam else 0;
        const eb: u32 = if (rect.y + rect.h < tr.y + tr.h) seam else 0;
        if (el > 0) saw[0] = true;
        if (er > 0) saw[1] = true;
        if (eb > 0) saw[2] = true;
        // 7e-1b: browser web은 탭 바 아래 읽기전용 주소창 밴드(addr_h=bar_h)만큼 top inset이 더 들어간다(markdown은 0).
        const addr_h: u32 = if (s.panel_kind == .browser) bar_h else 0;
        try std.testing.expectEqual(rect.x + el, cr.x);
        try std.testing.expectEqual(rect.y + bar_h + addr_h, cr.y); // top = 탭 바 + (browser면) 주소창 밴드(seam 추가 inset 없음)
        try std.testing.expectEqual(rect.w - el - er, cr.w);
        try std.testing.expectEqual(rect.h - bar_h - addr_h - eb, cr.h);
        // seam_edges 비트마스크(L=1·R=2·B=4)는 inset이 걸린 가장자리와 정확히 일치해야 한다(Swift hitTest 통과의 단일 출처).
        var expected_mask: u8 = 0;
        if (el > 0) expected_mask |= 1;
        if (er > 0) expected_mask |= 2;
        if (eb > 0) expected_mask |= 4;
        try std.testing.expectEqual(expected_mask, s.seam_edges);
    }
    return saw;
}

// [4e review 0 재수정] collectWebSurfaces: split에서 각 web 본문 rect는 seam 가장자리를 `dt + 클릭여유`만큼 들여 WKWebView가
// divider를 덮지 않게 한다(예전 `dt/2`는 기본 dt=1에서 0이라 무효과 — 세로·가로 divider가 안 잡히던 회귀). 세로 divider
// (split_horizontal=좌우)와 **가로 divider(split_vertical=상하, 원래 테스트가 놓친 bottom seam)** 둘 다 헤드리스 검증.
test "웹 패널 옆 divider는 padding이 노출하든 webview가 통과시키든 반드시 잡힌다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // (scale, window padding) 두 축을 함께 돈다. 기존 seam 검증은 padding 0 · 1x에서만 돌아
    // `half > padding` 구성과 Retina를 한 번도 밟지 않았다.
    const Case = struct { scale: u32, pad: u32, expect_band: bool };
    for ([_]Case{
        // 제품 기본: padding(2x에서 16px)이 grab 반폭(10.5px)보다 커서 divider가 padding 틈에
        // 그대로 드러난다 → 통과시킬 것이 없고 밴드는 0이 맞다.
        .{ .scale = 2000, .pad = 8, .expect_band = false },
        // padding 0: 웹뷰가 seam까지 차올라 grab 밴드를 덮는다 → 이때만 pass-through가 일한다.
        .{ .scale = 2000, .pad = 0, .expect_band = true },
    }) |case| {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        _ = try session.resize(session.sidebar_width_px + 1600, 1200, case.scale);
        session.window_padding_px = .{ .left = case.pad, .right = case.pad, .top = case.pad, .bottom = case.pad };
        session.dispatchAppAction(.split_horizontal);
        session.dispatchAppAction(.new_web_tab);

        var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
        defer segs.deinit(allocator);
        try session.layoutActiveTabDividers(&segs);
        try std.testing.expect(segs.items.len > 0);
        const seg = segs.items[0];
        const div_x: f64 = @floatFromInt(seg.pos);
        const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

        var cur: std.ArrayList(web_panel_layout.SurfaceLayout) = .empty;
        defer cur.deinit(allocator);
        try session.collectWebSurfaces(&cur);
        var seam_surface: ?web_panel_layout.SurfaceLayout = null;
        for (cur.items) |s| {
            if (s.seam_edges != 0) seam_surface = s;
        }
        const web = seam_surface orelse return error.TestExpectedSeamSurface;

        // ① 밴드 유무는 구성의 결과지 계약이 아니다. padding이 grab 반폭보다 크면 0이 맞다.
        const has_band = web.divider_grab_bands_pt.left > 0 or web.divider_grab_bands_pt.right > 0 or
            web.divider_grab_bands_pt.bottom > 0;
        try std.testing.expectEqual(case.expect_band, has_band);

        // ② 밴드가 0인 구성에서는 divider 선이 웹뷰 **밖**에 있어야 한다 — 그래야 클릭이 웹뷰를
        //    거치지 않고 아래 터미널 뷰에 닿는다. 이 둘 중 하나는 반드시 성립해야 하며, 둘 다
        //    아니면 그 divider는 사용자가 영영 잡을 수 없다.
        const cr = web.content_rect;
        const inside_web = div_x >= @as(f64, @floatFromInt(cr.x)) and
            div_x < @as(f64, @floatFromInt(cr.x + cr.w)) and
            div_y >= @as(f64, @floatFromInt(cr.y)) and
            div_y < @as(f64, @floatFromInt(cr.y + cr.h));
        try std.testing.expect(has_band or !inside_web);

        // ③ 그리고 실제로 잡힌다. 이것이 사용자가 겪는 결과이고, 위 두 경로 중 어느 쪽으로
        //    성립하든 답은 같아야 한다.
        session.mouse(1, div_x, div_y, 0, 0);
        try std.testing.expect(session.dividerCaptureActive());
        session.mouse(3, div_x, div_y, 0, 0);
    }
}

test "collectWebSurfaces: split seam(세로·가로 divider 둘 다)은 dt+클릭여유 inset, 바깥 경계 0" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    const expected_seam = struct {
        fn v(session: *AppSession) u32 {
            const dt = session.dividerThicknessPx();
            return if (dt == 0) 0 else dt + @max(@as(u32, 1), session.scale_milli / 1000);
        }
    }.v;

    // ① split_horizontal = 세로 divider(좌우 pane) → left/right seam.
    {
        const session = try initSmokeSessionSized(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const seam = expected_seam(session);
        try std.testing.expect(seam > 0);
        session.dispatchAppAction(.split_horizontal);
        session.dispatchAppAction(.new_web_tab);
        session.focusPaneRelative(-1);
        session.dispatchAppAction(.new_web_tab);
        const saw = try checkWebSeamInsets(session, seam, allocator);
        try std.testing.expect(saw[0] or saw[1]); // 세로 divider의 좌/우 seam을 실제 밟음
    }

    // ② split_vertical = 가로 divider(상/하 pane) → bottom seam(원래 테스트가 안 밟던 경로 — 사용자 제보 버그).
    {
        const session = try initSmokeSessionSized(allocator);
        defer allocator.destroy(session);
        defer session.deinit();
        const seam = expected_seam(session);
        session.dispatchAppAction(.split_vertical);
        session.dispatchAppAction(.new_web_tab);
        session.focusPaneRelative(-1);
        session.dispatchAppAction(.new_web_tab);
        const saw = try checkWebSeamInsets(session, seam, allocator);
        try std.testing.expect(saw[2]); // ★ 위 pane의 아래(가로 divider) seam을 실제 밟음 — bottom inset 잠금
    }
}

// [4e review 8] web scratch: web Term 있는 세션을 여러 tick 돌려도 영속 scratch(swap 후 옛 prev 버퍼 보유)가 누수/
// double-free 없이 정확히 해제된다. testing.allocator가 감시. 실 init/spawn/tick 경로.
test "web scratch: 다중 tick 누수/크래시 0(영속 scratch swap 소유 흐름)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.dispatchAppAction(.new_web_tab);
    var i: usize = 0;
    while (i < 5) : (i += 1) {
        _ = session.webSurfaceTransitionsCount(); // computeWebSurfaceTransitions(collect+diff+swap) 반복
        _ = try session.tick();
    }
    try std.testing.expect(session.windowHasWebTerm());
}

// pane에 Term이 여럿이면 탭 바가 제목 탭들 + 활성 Term 하이라이트를 그리는지(PR-C2) — 실 init/spawn/tick이
// 도는 macOS 경로라 게이트. ⌘T로 Term 2개를 만들고 tick이 바 배경 + 활성 탭 하이라이트 chrome을 내는지 본다.
test "pane tab bar draws Term-title tabs with an active-Term highlight" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .tui; // tui 셀 바/탭 하이라이트 검증(기본값 rich는 바 배경·활성 탭이 quad) — resize 전에 고정
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // ⌘T → 활성 pane에 Term 2개(활성 = 1).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);

    // tick이 크래시 없이 돈다(탭 바 제목 frame + 비활성 Term은 안 그림 — 활성 Term surface만). chrome은 cells
    // 맨 앞에 바 배경(전체) + 활성 Term 탭 하이라이트(세그먼트) 두 종류가 prepend된다. 첫 둘은 origin_y 0·slot 0.
    _ = try session.tick();
    const frame = session.metalFrame();
    try std.testing.expect(frame.cell_count >= 2);
    const c0 = frame.cells.?[0]; // 바 배경(전체 폭)
    const c1 = frame.cells.?[1]; // 활성 Term 탭 하이라이트(세그먼트)
    try std.testing.expectEqual(session.titlebar_strip_px, c0.origin_y); // 바 top = 상단 타이틀바 띠
    try std.testing.expectEqual(@as(u32, 0), c0.slot_id);
    try std.testing.expectEqual(session.titlebar_strip_px, c1.origin_y);
    try std.testing.expectEqual(@as(u32, 0), c1.slot_id);
    // 하이라이트(c1)는 활성 Term(1) 세그먼트 = col tab_w(2탭이라 cols/2)에서 시작 — 바 배경(col 0)과 다르다.
    try std.testing.expect(c1.col > 0);
    try std.testing.expect(c1.width < c0.width); // 세그먼트는 바 전체보다 좁다
}

// U-tab2 rich: 활성 탭이 **본문색 cutout**(strip에서 도려낸 듯)이고, 포커스 구분은 배경이 아니라 **언더바 색**
// (포커스 pane=테마 accent, 비포커스=muted)이라는 새 시각 계약을 layer-2 gpu_quads로 고정한다. 세로 분할로
// 포커스(아래)·비포커스(위) 두 pane을 만들어 cutout·앰버·muted quad가 모두 방출되는지 본다(옛 sidebarActiveBg 평평 배경 회귀 방지).
test "U-tab2 rich: active tab is a body-color cutout; focus pane gets amber underbar, non-focus muted" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .rich; // 본문색 cutout·언더바 quad는 rich 경로(tab_corner>0)에서만 — resize 전에 고정
    session.appearance.chrome_tab_style = .connected; // cutout은 connected 스타일만(기본은 이제 underline이라 명시) — resize 전에 고정
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try session.splitActivePane(.vertical); // 상(비활성)/하(활성·포커스) 두 pane
    try std.testing.expectEqual(@as(usize, 2), session.activeTab().panes.items.len);
    _ = try session.tick();

    const tk = session.buildChromeTokens();
    const cutout = packOpaqueRgb(session.appearance.theme.background); // 활성 탭 = 본문색
    const amber = packOpaqueRgb(tk.palette.get(.accent_bar)); // 포커스 pane 언더바(테마 accent)
    const muted = packOpaqueRgb(tk.palette.get(.muted_fg)); // 비포커스 pane 언더바
    const old_weak = session.sidebarActiveBg(); // 옛(U-tab2 전) 활성 탭 평평 배경 — 이제 탭 cutout엔 안 씀
    // 색이 서로 구분돼야 단언이 의미 있다(테마가 우연히 겹치면 무력) + cutout이 옛 약한 배경이 아님을 고정.
    try std.testing.expect(cutout != amber and cutout != muted and amber != muted);
    try std.testing.expect(cutout != old_weak);

    var found_cutout = false;
    var found_amber_underbar = false;
    var found_muted_underbar = false;
    for (session.gpu_quads.items) |q| {
        if (q.layer != 2) continue; // 탭 밴드 레이어(사이드바 accent 막대는 layer 0이라 제외)
        if (q.fill_color0 == cutout) found_cutout = true;
        if (q.fill_color0 == amber) found_amber_underbar = true;
        if (q.fill_color0 == muted) found_muted_underbar = true;
    }
    try std.testing.expect(found_cutout); // 활성 탭 본문색 cutout
    try std.testing.expect(found_amber_underbar); // 포커스 pane = 테마 accent 언더바
    try std.testing.expect(found_muted_underbar); // 비포커스 pane = muted 언더바
}

// TS1 탭 스타일 축(chrome.tab-style=underline): 활성 탭에 **본문색 cutout 배경이 없고** 앰버 언더바만 방출되는지
// 고정한다(connected와 같은 세그먼트 기하, fill만 다름 — §7). config enum → appearance → 토큰 → 렌더 분기 전 경로 검증.
test "TS1 chrome.tab-style=underline: no cutout bg quad, only the amber underbar" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .rich;
    session.appearance.chrome_tab_style = .underline; // 축: 언더바만(배경 박스 없음) — resize 전에 고정
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    _ = try session.tick();

    const tk = session.buildChromeTokens();
    try std.testing.expectEqual(chrome.tokens.TabActiveStyle.underline, tk.space.tab_active_style); // config→토큰 매핑 확인
    const cutout = packOpaqueRgb(session.appearance.theme.background); // connected였다면 활성 탭 배경에 떴을 색
    const amber = packOpaqueRgb(tk.palette.get(.accent_bar)); // 포커스(단일 pane) 언더바

    var found_cutout = false;
    var found_amber_underbar = false;
    for (session.gpu_quads.items) |q| {
        if (q.layer != 2) continue;
        if (q.fill_color0 == cutout) found_cutout = true;
        if (q.fill_color0 == amber) found_amber_underbar = true;
    }
    try std.testing.expect(!found_cutout); // underline은 본문색 배경 fill을 안 그린다(connected만 cutout)
    try std.testing.expect(found_amber_underbar); // 언더바는 두 스타일 공통
}

// TS2 탭 스타일 축(chrome.tab-style=pill): 활성 탭이 **둥근 inset 캡슐(corner_radii>0)을 strip보다 밝은 lifted 회색
// (sidebarActiveBg)으로 채워** 방출되는지 고정한다(실제 Warp 벤치마킹 — 밝은 fill로 띄움, 포커스=fill 밝기). connected/
// underline과 같은 세그먼트 기하, fill만 다름. cutout(본문색)·언더바(앰버) quad는 pill에서 안 나온다.
test "TS2 chrome.tab-style=pill: rounded inset capsule with lifted fill (Warp benchmark)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .rich;
    session.appearance.chrome_tab_style = .pill; // 축: 둥근 inset pill + 테두리 — resize 전에 고정
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    _ = try session.tick();

    const tk = session.buildChromeTokens();
    try std.testing.expectEqual(chrome.tokens.TabActiveStyle.pill, tk.space.tab_active_style); // config→토큰 매핑
    const lifted = session.sidebarActiveBg(); // 단일 pane=포커스 → 밝은 lifted fill(strip sidebarBg보다 밝음)
    const cutout = packOpaqueRgb(session.appearance.theme.background); // connected였다면 떴을 본문색

    var found_pill = false;
    var found_cutout = false;
    for (session.gpu_quads.items) |q| {
        if (q.layer != 2) continue;
        // pill = 유일한 둥근(corner_radii>0) + lifted fill quad(바 배경·스크롤 버튼은 직각, 언더바는 직각·앰버).
        if (q.corner_radii[0] > 0 and q.fill_color0 == lifted) found_pill = true;
        if (q.fill_color0 == cutout) found_cutout = true;
    }
    try std.testing.expect(lifted != cutout); // lifted fill이 본문색과 다름(테스트 유의미)
    try std.testing.expect(found_pill); // 둥근 inset 캡슐 + lifted 회색 fill(Warp식)
    try std.testing.expect(!found_cutout); // pill은 본문색 cutout을 안 그린다(connected만)
}

// U-tab2: pane Term 탭 제목에서 "{n} " 번호 prefix를 제거했음을 rename in-place caret 위치로 고정한다. 단일
// Term(tab_index 0, seg.start_col=0)을 rename하면 caret은 좌패딩 1칸 뒤(tabs.x + cw)여야 한다 — 번호 prefix가
// 남아 있었다면 numberPrefixCols(0)=2칸 더 밀려 tabs.x + 3·cw였을 것이다(회귀 방지).
test "U-tab2: pane Term tab title has no number prefix (rename caret sits right after the left pad)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    _ = try session.tick();

    const term = session.activePane().activeTerm();
    session.startRename(.{ .term = term }); // custom_name 없는 새 Term → 편집기 비어 qcols=0
    const caret = session.renameCaretRect() orelse return error.TestUnexpectedResult;
    const loc = session.termBarLocation(term) orelse return error.TestUnexpectedResult;
    // 단일 Term이라 tab 0 = 탭 영역 좌단(seg.start_col=0). 번호 prefix 제거 → caret_col=1(좌패딩만).
    const expected_x: i32 = @intCast(loc.pb.tabs.x + session.cell_width_px);
    try std.testing.expectEqual(expected_x, caret.x);
}

// 세로(상하) 분할에서 '아래' pane의 탭 바가 자기 y(≈ 화면 절반)에 그려지는지 — 사용자 제보(세로 분할 시
// 탭 활성화 UI가 안 갱신됨) 회귀. 가로 분할은 두 바 모두 y=0(top)이라 안 드러나지만, 세로면 아래 바가
// origin_y>0에 있어야 한다. tick chrome 셀에 origin_y>0인 바 배경 셀이 있는지로 본다.
test "vertical split renders the bottom pane tab bar at its own y (not overlapping top at 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .tui; // tui 셀 바 기하 검증(기본값 rich는 바 배경 quad·pad_y가 달라짐) — resize 전에 고정
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try session.splitActivePane(.vertical); // 상/하 — 아래(새) pane 활성
    try std.testing.expectEqual(@as(usize, 2), session.activeTab().panes.items.len);
    _ = try session.tick();

    const frame = session.metalFrame();
    // 위 pane 바(origin_y=0)와 아래 pane 바(origin_y>0, ≈ 화면 절반)가 둘 다 chrome으로 그려져야 한다. 그리고
    // 활성 pane(아래) 탭은 밝은 sidebarActiveBg, 비활성 pane(위) 탭은 dim sidebarHoverBg로 — 포커스 구분.
    var found_top_bar = false;
    var found_bottom_bar = false;
    var found_active_hl = false; // 활성 pane(아래)의 밝은 강조색
    var found_inactive_hl = false; // 비활성 pane(위)의 dim 강조색
    const active_bg = session.sidebarActiveBg();
    const inactive_bg = session.sidebarHoverBg();
    var i: usize = 0;
    while (i < frame.cell_count) : (i += 1) {
        const c = frame.cells.?[i];
        // chrome 바 셀: slot_id 0(배경) + row 0 + sentinel UV(u0=-1) + 불투명 bg.
        if (c.slot_id == 0 and c.row == 0 and c.u0 == -1.0 and (c.background >> 24) == 0xFF) {
            // 위 pane 바 = 상단 타이틀바 띠(strip), 아래 pane 바 = 그보다 아래(strip + 위 pane 높이).
            if (c.origin_y == session.titlebar_strip_px) found_top_bar = true;
            if (c.origin_y > session.titlebar_strip_px) found_bottom_bar = true;
            if (c.origin_y > session.titlebar_strip_px and c.background == active_bg) found_active_hl = true; // 아래(활성) = 밝게
            if (c.origin_y == session.titlebar_strip_px and c.background == inactive_bg) found_inactive_hl = true; // 위(비활성) = dim
        }
    }
    try std.testing.expect(found_top_bar);
    try std.testing.expect(found_bottom_bar); // 아래 pane 바가 자기 y(>0)에 있어야 함 — 0에 안 겹침
    try std.testing.expect(active_bg != inactive_bg); // 두 색이 달라야 구분된다
    try std.testing.expect(found_active_hl); // 활성 pane 탭 = 밝은 강조
    try std.testing.expect(found_inactive_hl); // 비활성 pane 탭 = dim 강조

    // 아래 pane(활성)에 Term 2개를 만들고, 아래 바의 탭 0을 클릭해 전환되는지(세로 분할 hit-test) 본다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
    // 아래 pane 바 y = 위 pane 높이(termRect.h/2 ≈ 300) + 1, 탭 0 = 바 좌단.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const bottom_rect = lr.items[1].rect; // tree 순서: [0]=위, [1]=아래
    const bottom_bar_y: f64 = @floatFromInt(bottom_rect.y + 1);
    // 사이드바 우측 리사이즈 밴드보다 안쪽(+30) — 아래 pane은 full-width라 x가 사이드바 경계에서 시작한다.
    session.mouse(1, @floatFromInt(bottom_rect.x + 30), bottom_bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 0), session.activePane().active_term); // 아래 바 탭 0으로 전환
}

// 탭 바의 탭을 클릭하면 그 Term으로 전환하는지(PR-D1) — 실 init/spawn이라 macOS 게이트. ⌘T로 Term 2개(활성
// =1)를 만들고 탭 0 영역(바 좌단)을 클릭하면 활성 Term이 0으로, 다시 탭 1을 클릭하면 1로 돌아온다.
test "clicking a tab in the pane bar switches to that Term" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // ⌘T → Term 2개, 활성 = 1.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);

    // 탭 바는 단일 panel이라 터미널 영역(상단 타이틀바 띠 아래) 전체 폭의 상단 strip. 탭 0 = 바 좌단, 탭 1 = 바 우반.
    const bar_y: f64 = @as(f64, @floatFromInt(session.titlebar_strip_px)) + 1; // 띠 아래 바 안(y in [띠, 띠+바높이))
    const left_tab_x: f64 = @floatFromInt(session.sidebar_width_px + 30); // 탭 0 세그먼트(사이드바 우측 리사이즈 밴드보다 안쪽)
    session.mouse(1, left_tab_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 0), session.activePane().active_term); // 탭 0으로 전환

    // 탭 1(바 우반, 2탭이라 폭의 절반 이후) 클릭 → 다시 Term 1.
    const right_tab_x: f64 = @floatFromInt(session.sidebar_width_px + 600); // 바 폭(800)의 우반
    session.mouse(1, right_tab_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);

    // 탭 바 클릭은 터미널 선택을 시작하지 않는다(소비). 선택 드래그 플래그가 안 켜진다.
    try std.testing.expect(!session.mouse_drag_selecting);
}

// 탭에 호버하면 ✕가 뜨고(hovered_tab 설정), 그 ✕ zone을 클릭하면 그 Term이 닫히는지(PR-D2) — 실 init/spawn/
// teardown이라 macOS 게이트. ⌘T로 Term 3개를 만들고, 탭 1의 ✕ zone에 호버 후 클릭해 Term이 2개로 준다.
test "hovering a tab shows a close X; clicking it closes that Term" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.appearance.chrome_theme = .tui; // tui 등폭 탭 기하로 ✕ zone col 검증(기본값 rich는 고정폭 탭·패딩이라 close_x가 다른 탭에 떨어짐) — resize 전에 고정
    session.window_padding_px = .{}; // 레이아웃 기하만 격리 — window padding(기본 8/4) inset은 gridFromBacking·loader 전용 테스트가 커버
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // ⌘T 두 번 → Term 3개. 단일 panel이라 바 폭 = 터미널 폭(800/cw cols), 3탭 등폭.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 3), session.activePane().terms.items.len);
    markAllTermsAtPrompt(session); // idle 셸 흉내 — ✕ 닫기가 확인 모달 없이 즉시 진행되게

    // 활성 pane의 바 rect를 구해 탭 1의 ✕ zone x를 계산한다.
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const bar = session.paneBarRect(lr.items[0].rect).?;
    const m = barMetrics(bar, session.cell_width_px, 3, 0, 0).?;
    // 탭 1 ✕ zone col = (1+1)*tab_w - 1(우측 안쪽). x = bar.x + (2*tab_w - 1)*cw.
    const close_x: f64 = @floatFromInt(bar.x + (2 * m.tab_w - 1) * session.cell_width_px);
    const bar_y: f64 = @floatFromInt(bar.y + 1);

    // 호버 → hovered_tab이 (활성 pane, 탭 1)로 설정된다(✕가 그려질 대상).
    _ = session.hoverCursor(close_x, bar_y, 0);
    try std.testing.expect(session.hovered_tab != null);
    try std.testing.expectEqual(@as(usize, 1), session.hovered_tab.?.tab);
    try std.testing.expect(m.inCloseZone(1, close_x)); // ✕ zone 안

    // ✕ 클릭 → 탭 1 Term 닫힘 → 2개. 닫은 뒤 호버는 비워진다(stale 방지).
    session.mouse(1, close_x, bar_y, 0, 0);
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expect(session.hovered_tab == null);
    try std.testing.expect(!session.ended_seen); // 아직 Term 남음 — 세션 유지
}

// 닫기 확인(실행 중 명령 보호)의 트리거 판정은 코어의 cursorIsAtPrompt(셸 통합 OSC 133 + alt 화면)로 결정된다.
// 아래 테스트들은 활성 Term 코어의 semantic_state/alt_active를 직접 세팅해 각 경우를 **결정론적**으로 증명한다
// (controlled_smoke는 `/bin/sh -c "printf; read"`라 OSC 133·alt를 안 쏘므로 코어 상태는 세팅한 값 그대로 유지).
// 프로세스/pgid를 안 쓰므로 job-control 셸이 필요 없다.
fn initSmokeSessionTwoTerms(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    // ⌘T → Term 2개(활성 pane). .term_or_pane 닫기는 활성 Term 하나만 teardown한다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    return session;
}

test "관측 tail 상한은 여러 행 composer의 프롬프트 마커를 계속 실어 준다" {
    // 상수 하나가 결함의 두 번째 원인이었다. 실측(codex 0.146.0)에서 composer는 사용자 입력 행 수만큼 자라므로,
    // tail 상한이 짧으면 프롬프트 마커가 tail 밖으로 밀려 **유일한 idle 근거가 사라지고** PTY activity 폴백이 타이핑을
    // running으로 단정한다. 실제 상수 + 실제 코어 직렬화 + 순수 observer를 함께 통과시켜 제품 경로를 못박는다
    // (PTY·GUI 없이 검증 가능한 구간이다).
    // **넓은 창까지 확인한다.** `dumpRecentTextUtf8`이 `max_bytes / (cols*4 + 1)`로 행 수를 다시 계산하므로, byte 상한이
    // 작으면 행 상수가 조용히 무력화된다 — 32KiB일 때 640칸에서 12행으로 되돌아갔다(코드 리뷰에서 재현).
    const allocator = std.testing.allocator;
    const observer = maru.session.agent_observer;
    inline for (.{ 80, 320, 640 }) |cols| {
        var core = try terminal.TerminalCore.init(allocator, .{ .cols = cols, .rows = 30 });
        defer core.deinit();

        try core.write("› line1\r\n");
        var row: usize = 2;
        while (row <= 14) : (row += 1) {
            var buf: [32]u8 = undefined;
            try core.write(try std.fmt.bufPrint(&buf, "  line{d}\r\n", .{row}));
        }
        try core.write("\r\n  Context 4% used · weekly 67% left · gpt-5.6-sol low");

        const tail = try core.dumpRecentTextUtf8(allocator, agent_screen_tail_rows, agent_screen_tail_bytes);
        defer allocator.free(tail);
        try std.testing.expect(std.mem.indexOf(u8, tail, "›") != null);
        try std.testing.expectEqual(observer.State.idle, observer.detect(.codex, .{ .screen = tail, .output_active = true }).state);

        // non-vacuous: 옛 12행 상한으로 같은 화면을 읽으면 마커가 빠지고 폴백이 running을 세운다.
        const short_tail = try core.dumpRecentTextUtf8(allocator, 12, agent_screen_tail_bytes);
        defer allocator.free(short_tail);
        try std.testing.expect(std.mem.indexOf(u8, short_tail, "›") == null);
        try std.testing.expectEqual(observer.State.running, observer.detect(.codex, .{ .screen = short_tail, .output_active = true }).state);
    }
}

test "agent representative prioritizes blocked over running over active idle" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const tab = session.activeTab();
    const background = tab.activePane().terms.items[0];
    const active = tab.activeTerm();
    active.agent_kind = .claude;
    active.agent_state = .idle;
    background.agent_kind = .codex;
    background.agent_state = .running;
    try std.testing.expectEqual(AgentKind.codex, AppSession.tabAgentKind(tab));
    {
        const line = try session.workspaceStatusLine(tab);
        defer allocator.free(line);
        try std.testing.expect(std.mem.endsWith(u8, line, "진행중"));
    }

    background.agent_state = .blocked;
    try std.testing.expectEqual(AgentKind.codex, AppSession.tabAgentKind(tab));
    {
        const line = try session.workspaceStatusLine(tab);
        defer allocator.free(line);
        try std.testing.expectEqualStrings("? 입력 대기", line);
    }
}

/// 테스트 유틸 — 세션의 모든 Term 코어를 "프롬프트에 idle"(OSC 133 input) 상태로 표시한다. controlled_smoke는
/// OSC 133을 안 쏘므로 코어가 unknown이라 닫기 확인이 보수적으로 뜬다(cursorIsAtPrompt=false). 닫기를 **메커니즘**
/// 으로만 쓰는(닫기 확인 자체가 검증 대상이 아닌) 탭/pane/Term 수명 테스트가, 프로덕션의 통합 셸 idle 상태를 흉내 내
/// 즉시 닫히게 한다. 새 Term을 만든 뒤 닫기 직전에 부른다.
fn markAllTermsAtPrompt(session: *AppSession) void {
    for (session.tabs.items) |tab| {
        for (tab.panes.items) |pane| {
            for (pane.terms.items) |t| t.surface.core.semantic_state = .input;
        }
    }
}

test "close-confirm: 셸이 프롬프트(OSC 133 input)면 확인 모달 없이 즉시 닫는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionTwoTerms(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 정착한 idle 프롬프트 = 셸 통합이 입력 대기(B)를 마킹한 상태 → 실행 중 명령 없음.
    session.activePane().activeTerm().surface.core.semantic_state = .input;
    try std.testing.expect(!session.closeTargetHasRunningJob(.term_or_pane));

    // requestClose → 즉시 닫힘(모달 안 뜸, 보류 없음).
    session.requestClose(.term_or_pane);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);
    try std.testing.expect(!session.chrome_host.confirm.open);
    try std.testing.expect(session.pending_confirm == .none);
}

test "close-confirm: 명령 실행 중(OSC 133 command)이면 확인 모달을 띄우고 닫기를 보류한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
