    try std.testing.expect(!hasPreset(try session.currentSectionFields(scratch.allocator())));
}

test "settings window.background-image: 행 활성→파일 선택창 요청, provide→적용, Backspace→지우기 (v81)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    // window 섹션 + background-image text 행 인덱스 찾기.
    const sections = try session.buildSectionList(scratch.allocator());
    var win_si: ?usize = null;
    for (sections, 0..) |s, si| if (s.section == .window) {
        win_si = si;
    };
    try std.testing.expect(win_si != null);
    session.chrome_host.settings.section = win_si.?;
    session.refreshSettingsFieldCount();
    const cf = try session.currentSectionFields(scratch.allocator());
    var tix: ?usize = null;
    for (cf.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, "window.background-image")) {
        tix = i;
    };
    try std.testing.expect(tix != null);
    const after_enums = cf.bools.len + cf.nums.len + cf.enums.len;
    session.chrome_host.settings.selected = after_enums + tix.?;

    // (1) 활성(Enter/클릭) → 인라인 편집이 아니라 파일 선택창 요청(file_pick_pending). 편집 모드는 안 켜진다.
    session.toggleSelectedSetting();
    try std.testing.expect(!session.chrome_host.settings.editing); // 인라인 편집 아님
    try std.testing.expect(session.takeFilePickRequest()); // 요청 대기 → drain
    try std.testing.expect(!session.takeFilePickRequest()); // 1회성

    // (2) Swift NSOpenPanel이 고른 경로를 provide → config에 적용 + 영속 예약.
    session.providePickedFile("/Users/me/Pictures/bg.png");
    try std.testing.expectEqualStrings("/Users/me/Pictures/bg.png", session.loaded_config.config.window_background_image);
    try std.testing.expect(session.takeConfigDirty());

    // (3) 그 행 Backspace → 빈 값(배경 없음)으로 지우기.
    session.resetSelectedSettingRow();
    try std.testing.expectEqualStrings("", session.loaded_config.config.window_background_image);

    // (4) 빈 경로 provide(취소 등)는 무동작 — 직전 빈 값 유지.
    session.providePickedFile("");
    try std.testing.expectEqualStrings("", session.loaded_config.config.window_background_image);
}

test "settings HSV picker 스포이드 ABI: settings_eyedropper→pending, take 1회성, provide→picker 반영 (v83)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // picker 열기(검정 시드).
    session.chrome_host.settings.openPicker(.{ .r = 0, .g = 0, .b = 0 });
    // dispatchChromeAction(.settings_eyedropper) → color_sample_pending.
    session.dispatchChromeAction(.settings_eyedropper);
    try std.testing.expect(session.takeColorSampleRequest()); // Swift가 drain
    try std.testing.expect(!session.takeColorSampleRequest()); // 1회성
    // Swift NSColorSampler 콜백 → provideSampledColor → picker 반영(#ff0080 근사).
    session.provideSampledColor(.{ .r = 0xff, .g = 0, .b = 0x80 });
    try std.testing.expectEqual(@as(u8, 0xff), session.chrome_host.settings.pickerRgb().r);
    try std.testing.expectEqual(@as(u8, 0x80), session.chrome_host.settings.pickerRgb().b);
    // picker 닫힌 뒤 provide는 무시(setPickerRgb 가드).
    session.chrome_host.settings.closePicker();
    session.provideSampledColor(.{ .r = 0x10, .g = 0x20, .b = 0x30 });
    // 닫혔으니 pick 값 안 바뀜(여전히 #ff0080 근사) — picking=false라 setPickerRgb 무동작.
    try std.testing.expectEqual(@as(u8, 0xff), session.chrome_host.settings.pickerRgb().r);
}

test "settings palette grid: theme 섹션 마지막 행에서 셀 hex 편집 → palette[idx] set + theme.palette.idx dirty (CS-4-5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // theme 섹션 선택(네비에서 theme 인덱스 찾기 — 기본 config 기준).
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var theme_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .theme) {
        theme_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = theme_idx;

    // 팔레트 그리드 행은 theme 섹션 마지막(color 뒤). paletteRowIndex로 selected 설정.
    const cf = try session.currentSectionFields(scratch.allocator());
    try std.testing.expect(cf.has_palette);
    const pi = cf.paletteRowIndex().?;
    session.chrome_host.settings.selected = pi;

    // 셀 5 선택 → Enter(toggle) = 편집 시작(기본 미override라 xterm256(5) 시드).
    session.chrome_host.settings.grid_cell = 5;
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.editing);

    // 편집 버퍼를 새 hex로 바꿔 커밋 → palette[5]=#abcdef, dirty=theme.palette.5(write-back이 직렬화).
    session.chrome_host.settings.enterEdit("#abcdef");
    session.config_dirty_keys.clearRetainingCapacity();
    session.commitSelectedText();
    try std.testing.expect(session.loaded_config.config.theme.palette[5] != null);
    try std.testing.expectEqualStrings("#abcdef", session.loaded_config.config.theme.palette[5].?);
    try std.testing.expect(!session.chrome_host.settings.editing); // 커밋 후 편집 종료
    var found = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, "theme.palette.5")) {
        found = true;
    };
    try std.testing.expect(found);

    // ←/→(adjust) = 선택 셀 이동(색 변경 아님, wrap).
    session.chrome_host.settings.grid_cell = 5;
    session.adjustSelectedSetting(1);
    try std.testing.expectEqual(@as(usize, 6), session.chrome_host.settings.grid_cell);
    session.adjustSelectedSetting(-1);
    try std.testing.expectEqual(@as(usize, 5), session.chrome_host.settings.grid_cell);

    // 잘못된 hex는 거부(기존값 유지) — 파일 로드와 같은 검증.
    session.chrome_host.settings.selected = pi;
    session.chrome_host.settings.grid_cell = 5;
    session.chrome_host.settings.enterEdit("#gggggg");
    session.commitSelectedText();
    try std.testing.expectEqualStrings("#abcdef", session.loaded_config.config.theme.palette[5].?); // 거부 — 유지
}

test "settings HSV picker 커밋: theme color 행 Enter→picker 열림, pickerRgb()→#rrggbb setText + dirty (CS-4-6)" {
