// 멀티-탭 핵심 계약: 두 번째 탭을 만들면 자기 셸 PTY가 spawn되고, tick이 '모든' 탭을 drain하므로
// 그 탭 surface가 자기 출력을 받는다(백그라운드여도). 실 PTY라 macOS 게이트 — 약속한 "탭 2개 동시
// 출력" 반-E2E를 결정적으로 고정한다. switchTab이 활성 라우팅을 바꾸는 것도 함께 검증.
test "two tabs: createTab spawns a second shell and tick drains both (multi-tab)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);

    // 2번째 탭: 알려진 마커를 출력하고 cat으로 stdin을 읽으며 살아 있는 controlled 셸. createTab이 Tab을
    // heap-pin하고 같은 runtime에 별개 surface_id로 attach한다. 새 탭이 활성이 된다. (printf만 쓰면 셸이 즉시
    // exit해 PR5b reap이 탭을 닫으므로, 멀티-탭 drain을 관측하려면 탭이 살아 있어야 한다 — cat으로 유지.)
    _ = try session.createTab(
        .{ .command = "/bin/sh", .args = &.{ "-c", "printf 'TAB_TWO_MARK\\n'; cat" }, .size = .{ .cols = 20, .rows = 5 } },
        .{ .cols = 20, .rows = 5 },
        16,
        "tab 2",
        "sh",
    );
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);

    // tick이 모든 탭을 drain → 2번째 탭 surface가 자기 셸 출력을 받는다(멀티-탭 drain).
    var saw = false;
    var i: usize = 0;
    while (i < 400 and !saw) : (i += 1) {
        _ = try session.tick();
        const dump = try session.tabs.items[1].activePane().activeTerm().surface.core.dumpUtf8(allocator);
        defer allocator.free(dump);
        if (std.mem.indexOf(u8, dump, "TAB_TWO_MARK") != null) saw = true;
    }
    try std.testing.expect(saw);

    // switchTab으로 활성 탭을 0으로 — activeSurface가 탭 0 surface를 가리킨다(라우팅 전환).
    try std.testing.expect(session.switchTab(0));
    try std.testing.expectEqual(session.tabs.items[0].activePane().activeTerm().surface.id, session.activeSurface().id);
    try std.testing.expect(!session.switchTab(5)); // 범위 밖이면 false, 활성 불변
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
}

// Cmd+T가 키 경로(handleKeyEvent → resolver → app_action)로 '활성 pane에 새 Term(가로 탭)'을 열고,
// Cmd+Shift+T가 '새 워크스페이스'를 여는지 — 탭 풀 모델. native 최소(Swift는 키만, 판정·실행은 Zig).
// 실 PTY라 macOS 게이트.
test "Cmd+T opens a new Term in the active pane; Cmd+Shift+T opens a workspace" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);

    // Cmd+T → new_term → 활성 pane에 Term 추가(워크스페이스 수 불변), 새 Term이 활성.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
    try std.testing.expect(session.total_app_key_events >= 1); // 앱 액션으로 회계(PTY로 안 샘)

    // Cmd+Shift+T → new_tab → 새 워크스페이스(활성), 그 워크스페이스는 Term 1개로 시작.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);

    // 안 묶인 Cmd 조합(Cmd+S)은 아무것도 안 만들고 무시(ignored).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 's' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
}

// Cmd+1~9가 N번째 워크스페이스(사이드바 탭)로 전환하는지(select_tab) — 사용자 요청. 범위 밖(탭보다 큰 번호)은
// no-op. 실 init/spawn이라 macOS 게이트.
test "Cmd+1..9 switches to the Nth workspace (out-of-range is a no-op)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 워크스페이스 3개(⌘⇧T 두 번). 활성 = 마지막(2).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 3), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.app_window.active_tab);

    // Cmd+1 → 워크스페이스 0.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '1' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    // Cmd+3 → 워크스페이스 2.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '3' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.app_window.active_tab);
    // Cmd+2 → 워크스페이스 1.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '2' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    // Cmd+9 → 9번째 없음(3개뿐) → no-op(활성 불변).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '9' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
}

// handleKeyEvent가 사용자 config의 keybind를 적용하는지(빈 resolver가 아니라 loaded_config.keyBindingResolver())
// — 기본엔 없는 조합(Cmd+E)을 사용자 바인딩으로 new_term에 묶어 실제로 디스패치되는지 본다. 실 PTY라 macOS 게이트.
test "handleKeyEvent applies user config keybindings (resolver wired from loaded_config)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 사용자 keybind 주입: Cmd+E = new_term(기본 바인딩엔 없는 조합). keybindings 슬라이스만 바꾼다(arena·appearance
    // 빌림은 그대로) — handleKeyEvent가 loaded_config.keyBindingResolver()를 읽으므로 이게 곧 사용자 config 효과다.
    var user_binds = [_]config_mod.AppBinding{
        .{ .chord = try config_mod.KeyChord.parse("Cmd+E"), .action = .new_term },
    };
    session.loaded_config.keybindings = &user_binds;

    // Cmd+E는 빈 resolver였다면 ignored지만, 사용자 바인딩이 먹어 활성 pane에 Term이 추가된다.
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'e' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);

    // 사용자 바인딩에 없는 기본 조합(Cmd+T)도 여전히 동작한다(resolver가 default_app_bindings로 폴백).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 3), session.activePane().terms.items.len);
}

test "web app action dispatch bypasses terminal preprocessing and rejects a stale route" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    var user_binds = [_]config_mod.AppBinding{
        .{ .chord = try config_mod.KeyChord.parse("Cmd+C"), .action = .new_tab },
        .{ .chord = try config_mod.KeyChord.parse("Cmd+V"), .action = .new_term },
        .{ .chord = try config_mod.KeyChord.parse("Cmd+Backspace"), .action = .new_term },
    };
    session.loaded_config.keybindings = &user_binds;
    const browser_sid = try session.appendWebTermInActivePane(.browser);
    const copy: terminal.KeyEvent = .{ .key = .{ .char = 'c' }, .modifiers = .{ .command = true } };
    try std.testing.expectEqual(config_mod.keybinding.WebKeyRoute.app_action, session.webKeyRoute(0, copy));
    try std.testing.expect(!session.dispatchWebAppAction(0, copy)); // invalid sentinel은 action provenance가 아니다.
    const tabs_before = session.tabs.items.len;
    try std.testing.expect(session.dispatchWebAppAction(browser_sid, copy));
    try std.testing.expectEqual(tabs_before + 1, session.tabs.items.len);
    try std.testing.expect(session.switchTab(0)); // browser가 active인 원래 workspace로 복귀한다.

    // route 조회 뒤 config가 reload됐다고 가정한다. Swift는 이미 이벤트를 consume하지만 현재 resolver가 더는 app
    // action을 내지 않으므로 stale Action을 실행하지 않는다.
    const paste: terminal.KeyEvent = .{ .key = .{ .char = 'v' }, .modifiers = .{ .command = true } };
    try std.testing.expectEqual(config_mod.keybinding.WebKeyRoute.app_action, session.webKeyRoute(browser_sid, paste));
    session.loaded_config.keybindings = &.{};
    const terms_before_stale = session.activePane().terms.items.len;
    try std.testing.expect(!session.dispatchWebAppAction(browser_sid, paste));
    try std.testing.expectEqual(terms_before_stale, session.activePane().terms.items.len);

    session.loaded_config.keybindings = &user_binds;
    try std.testing.expect(session.dispatchWebAppAction(browser_sid, paste));
    const line_edit: terminal.KeyEvent = .{ .key = .backspace, .modifiers = .{ .command = true } };
    try std.testing.expectEqual(config_mod.keybinding.WebKeyRoute.app_action, session.webKeyRoute(browser_sid, line_edit));
    try std.testing.expect(!session.dispatchWebAppAction(browser_sid, line_edit)); // browser는 이제 background Term이다.
    try std.testing.expectEqual(terms_before_stale + 1, session.activePane().terms.items.len);
    session.focusTerm(1);
    try std.testing.expect(session.dispatchWebAppAction(browser_sid, line_edit));
    try std.testing.expectEqual(terms_before_stale + 2, session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(u64, 3), session.total_app_key_events);
    try std.testing.expectEqual(@as(u64, 0), session.total_terminal_input_events);
}

// Term 생명주기: ⌘T가 활성 pane에 Term을 쌓고, ⌘]/⌘[가 Term을 wrap 순환하고, ⌘W가 Term →(마지막이면)
// pane →(마지막이면) 워크스페이스 순으로 cascade close하는지 — 실 PTY teardown이라 macOS 게이트. 키 경로 전체.
test "Term lifecycle: Cmd+T adds, Cmd+Opt+]/[ cycle, Cmd+W cascades Term to workspace" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const cmd: terminal.ModifierSet = .{ .command = true };

    // ⌘T 두 번 → 활성 pane Term 3개(0,1,2), 활성 Term 2(마지막). 워크스페이스/ pane 수는 불변.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = cmd });
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 't' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().panes.items.len);
    try std.testing.expectEqual(@as(usize, 3), session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.activePane().active_term);
    markAllTermsAtPrompt(session); // idle 셸 흉내 — 이후 ⌘W cascade가 확인 모달 없이 즉시 진행되게(닫힌 뒤 남는 Term도 유지)

    // ⌘⌥] → 다음(wrap): 2→0. ⌘⌥[ → 이전(wrap): 0→2. (⌘[]는 이제 split 순환이라 Term 순환은 ⌘⌥[]로 옮겼다.)
    const cmd_opt: terminal.ModifierSet = .{ .command = true, .option = true };
    _ = try session.handleKeyEvent(.{ .key = .{ .char = ']' }, .modifiers = cmd_opt });
    try std.testing.expectEqual(@as(usize, 0), session.activePane().active_term);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '[' }, .modifiers = cmd_opt });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().active_term);

    // ⌘W → 활성 Term(2) 닫힘 → Term 2개, 활성 1(보정). pane/워크스페이스 수 불변.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 2), session.activePane().terms.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.activePane().active_term);
    try std.testing.expectEqual(@as(usize, 1), session.activeTab().panes.items.len);

    // ⌘W → Term(1) 닫힘 → Term 1개. 아직 pane/워크스페이스 그대로(세션 유지).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);
    try std.testing.expect(!session.ended_seen);

    // ⌘W → 이제 Term 1·pane 1·워크스페이스 1 → 마지막 워크스페이스 close = 세션 종료 latch(cascade 끝).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'w' }, .modifiers = cmd });
    try std.testing.expect(session.ended_seen);
}

// Cmd+]/[ 가 키 경로(handleKeyEvent → resolver → app_action)로 split(pane)을 순환하는지 — 실 PTY라 macOS
// 게이트. ⌘D로 pane 2개 만든 뒤 ⌘]는 활성 pane을 다음으로, ⌘[는 이전(wrap)으로 옮긴다. (⌘[]는 Term이 아니라
// split 순환 — Term은 ⌘⌥[]로 옮겼다, 사용자 요청 배치.)
test "Cmd bracket keys cycle split panes through the key path" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const cmd: terminal.ModifierSet = .{ .command = true };
    // ⌘D=좌우 split → 활성 워크스페이스에 pane 2개(splitActivePane이 새 pane으로 포커스).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'd' }, .modifiers = cmd });
    try std.testing.expectEqual(@as(usize, 2), session.activeTab().panes.items.len);
    const start = session.activeTab().active_pane;
    // ⌘] → 다음 pane(wrap, 2개라 토글), ⌘[ → 다시 원래.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = ']' }, .modifiers = cmd });
    try std.testing.expectEqual((start + 1) % 2, session.activeTab().active_pane);
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '[' }, .modifiers = cmd });
    try std.testing.expectEqual(start, session.activeTab().active_pane);
}

// Cmd+Shift+]/[ 가 키 경로(handleKeyEvent → resolver → app_action)로 다음/이전 탭을 순환하는지 — 실
// PTY라 macOS 게이트. 2탭에서 ]는 활성을 1→0, [는 0→1(wrap)으로 옮긴다.
test "Cmd+Shift bracket keys cycle tabs through the key path" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'T' }, .modifiers = .{ .command = true, .shift = true } }); // ⌘⇧T=새 워크스페이스 → 2탭, 활성 1
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);

    // Cmd+Shift+] → next_tab → (1+1)%2 = 0.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = ']' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    // Cmd+Shift+[ → previous_tab → (0+2-1)%2 = 1(wrap).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '[' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);
    // 닫는 중괄호 변형(}/{)도 같은 액션(OS가 Shift를 적용해 줄 수 있음).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '}' }, .modifiers = .{ .command = true, .shift = true } });
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
}

// closeTab이 탭을 teardown하고 active_tab을 재선택하며, 마지막 탭은 창(세션) 종료로 latch하는지 — 실
// PTY teardown(detach + reader join)이라 macOS 게이트. cat는 PTY가 닫힐 때까지 살아 있어 live 탭 teardown을 본다.
test "closeTab tears down a tab and reselects, last tab closes the session" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 살아있는 탭 2개 더(cat은 PTY 닫힐 때까지 stdin을 읽으며 대기). 활성=2.
    inline for (.{ "tab 2", "tab 3" }) |title| {
        _ = try session.createTab(
            .{ .command = "/bin/sh", .args = &.{ "-c", "cat" }, .size = .{ .cols = 20, .rows = 5 } },
            .{ .cols = 20, .rows = 5 },
            16,
            title,
            "sh",
        );
    }
    try std.testing.expectEqual(@as(usize, 3), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), session.app_window.active_tab);

    // 백그라운드 탭 0 닫기 → 2탭, 인덱스 밀림으로 active 2→1.
    session.closeTab(0);
    try std.testing.expectEqual(@as(usize, 2), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 1), session.app_window.active_tab);

    // 활성 탭(=마지막 인덱스 1) 닫기 → 1탭, active clamp 0.
    session.closeTab(1);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.app_window.active_tab);
    try std.testing.expect(!session.ended_seen);

    // 마지막 탭 닫기 → 창 닫힘(종료 latch). 탭은 헐지 않고(빈 리스트 패닉 회피) deinit이 정리한다.
    session.closeTab(0);
    try std.testing.expectEqual(@as(usize, 1), session.tabs.items.len);
    try std.testing.expect(session.ended_seen);
}

test "drag autoscroll works after a double-click word selection and skips redraw when nothing moves" {
    var session: AppSession = undefined;
    session.addr_edit = null; // 슬라이스 3: mouse()가 조기 addr 밴드 캡처에서 읽음(undefined면 UB — [[devsession-undefined-test-field-trap]])
    session.tabs = .empty; // legacy surface-only fixture: archive detail pointer routing has no structured Tab
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.scrollbar_capture = null;
    session.scrollbar_coalescer = .{};
    session.scrollbar_snapshot_generation = 0;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io(); // updateCursorBlink→readActiveSnapshot이 lockCore(self.io)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 4, .rows = 2 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    var test_rt: app.SurfaceRuntime = undefined;
    try attachTestRuntime(&session, &test_rt, &tab_surface);
    defer session.runtime.deinit();
    session.metal_dirty = false;
    session.metal_buffer = .{};
    session.chrome_host = .{}; // mouse()가 context_menu.open을 kind 무관하게 읽음([[devsession-undefined-test-field-trap]])
    session.rename = null;
    session.mouse_drag_selecting = false; // 더블클릭(kind 4) 후 상태
    session.pointer_gesture_owner = .none;
    // divider capture는 `PointerGestureOwner` 밖의 두 번째 pointer 축이라 여기서 함께 비운다
    // — `undefined` 세션이 mouse()를 타면 이 필드도 읽는다(CIM2).
    session.divider_interaction = .{};
    session.divider_capture_seg = null;
    session.divider_capture_split = null;
    session.divider_coalescer = .{};
    session.divider_entry_scratch = .empty;
    session.divider_split_scratch = .empty;
    session.divider_snapshot_generation = 0;
    session.scrollbar_interaction = .{};
    session.scrollbar_capture = null;
    session.scrollbar_coalescer = .{};
    session.scrollbar_snapshot_generation = 0;
    session.frame_loop_rate_hz = 30; // msPerTick=33=step_ms → 호출(tick)마다 한 줄(아래 "한 줄/호출" 가정과 맞춤)
    session.drag_autoscroll = 0;
    session.drag_autoscroll_accum_ms = 0;
    session.last_drag_col = 0;
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.scale_milli = 1000;
    session.sidebar_width_px = 0; // 사이드바 없음 — 마우스가 터미널 선택 경로를 타게(inSidebar=false)
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 32, .h = 32 }; // 단일 panel 좌표 origin(pxToCell이 읽음)

    const core = &tab_surface.core;
    try core.write("aa\r\nbb\r\ncc"); // 스크롤백 1(aa) + 화면 bb,cc
    core.selectWordAt(1, 0, ""); // 더블클릭 단어 선택(cc)
    try std.testing.expect(core.selection_anchor != null);

    // 더블클릭 직후 드래그가 grid 위 밖으로 — mouse_drag_selecting=false여도 autoscroll이 돈다.
    session.mouse(2, 0.0, -5.0, 0, 0);
    try std.testing.expectEqual(@as(i8, 1), session.drag_autoscroll);
    session.applyDragAutoscroll();
    try std.testing.expectEqual(@as(usize, 1), core.view_offset);
    try std.testing.expect(session.metal_dirty);

    // 더 갈 곳이 없으면(스크롤백 끝 + head 그대로) 재투영을 걸지 않는다 — frame-loop 재투영 루프 방지.
    session.metal_dirty = false;
    session.applyDragAutoscroll();
    try std.testing.expectEqual(@as(usize, 1), core.view_offset);
    try std.testing.expect(!session.metal_dirty);
}

test "shellEscapeJoin escapes shell metacharacters per NUL-separated token (paste/drop helper)" {
    // 드래그/붙여넣기로 파일 경로·URL을 셸 버퍼에 넣을 때, 셸이 공백 등 메타문자에서 단어를 쪼개거나
    // 글롭·치환으로 해석하지 않게 백슬래시를 앞세운다. 이전엔 Swift host(MaruAppHost.shellEscape)에 있던
    // 순수 문자열 로직을 Zig로 옮겨 단위 테스트로 회귀를 고정한다(네이티브 레이어 최소화 정책). 터미널에서
    // 중요한 이유: 공백 든 경로가 그대로 들어가면 셸이 여러 인자로 쪼개 엉뚱한 파일을 가리킨다.
    const allocator = std.testing.allocator;

    // 단일 토큰: 공백·괄호 앞에 백슬래시(NUL 없으면 토큰 1개).
    {
        const out = try AppSession.shellEscapeJoin(allocator, "/tmp/My Photos (2024)");
        defer allocator.free(out);
        try std.testing.expectEqualStrings("/tmp/My\\ Photos\\ \\(2024\\)", out);
    }
    // NUL로 구분된 여러 토큰: 각각 이스케이프 후 한 칸 공백으로 join(토큰 사이 구분 공백은 이스케이프 안 함).
    {
        const out = try AppSession.shellEscapeJoin(allocator, "/a b\x00/c&d");
        defer allocator.free(out);
        try std.testing.expectEqualStrings("/a\\ b /c\\&d", out);
    }
    // 메타문자가 없으면 그대로(중복 백슬래시·재스캔 없음 — 한 번만 순회).
    {
        const out = try AppSession.shellEscapeJoin(allocator, "https://example.com/path");
        defer allocator.free(out);
        try std.testing.expectEqualStrings("https://example.com/path", out);
    }
}

test "large paste drains through the non-blocking queue without freezing ticks" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 PTY 경로
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // PTY 입력 버퍼보다 큰 페이로드 — blocking 단일 write라면 여기서 동결됐을 크기. 개행을
    // 포함한 줄 단위로 만든다: controlled 자식(read -r line)은 canonical 모드라 개행 없는
    // 대용량은 줄을 영영 못 끝내 read에 갇히고, deinit의 자식 reap(wait4)이 hang된다 — 첫
    // 줄이 들어가면 자식이 진행해 정상 종료한다.
    // 이 테스트는 non-blocking drain 경로가 목적이라 paste protection을 끈다 — 안 그러면 개행 포함
    // 페이로드가 확인 모달에 걸려 큐로 안 들어가고, 검증이 무의미(0==0)해진다(paste protection 자체는
    // 별도 테스트가 커버). 실제 사용자 config 기본은 protection ON.
    session.loaded_config.config.input.paste_protection = false;
    const big = try allocator.alloc(u8, 64 * 1024);
    defer allocator.free(big);
    @memset(big, 'x');
    var li: usize = 79;
    while (li < big.len) : (li += 80) big[li] = '\n';
    session.pasteText(big, false);

    // pasteText는 즉시 반환해야 하고(동결 없음), 잔여는 tick들이 흘려보낸다.
    var i: usize = 0;
    while (i < 600 and session.hasPendingPaste()) : (i += 1) {
        _ = try session.tick();
    }
    // 자식(read 대기 중)이 소비하므로 결국 큐가 빈다.
    try std.testing.expect(!session.hasPendingPaste());
}

test "observer input suppression permanently discards paste while transient writes remain retryable" {
    try std.testing.expect(AppSession.discardPendingPasteOnError(error.InputSuppressed));
    try std.testing.expect(AppSession.discardPendingPasteOnError(error.ProcessExited));
    try std.testing.expect(AppSession.discardPendingPasteOnError(error.UnknownSurface));
    try std.testing.expect(!AppSession.discardPendingPasteOnError(error.WriteFailed));
    try std.testing.expect(!AppSession.discardPendingPasteOnError(error.OutOfMemory));
}

test "paste protection: 개행 붙여넣기는 확인 모달로 보류, 확인 시 자식까지 도달·취소는 미도달·off는 즉시 (input.paste-protection)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실제 PTY/모달 경로
    const allocator = std.testing.allocator;

    // controlled_smoke 자식은 `read -r line` 한 줄을 읽어 `Maru app input:<line>`로 에코한다(PTY 라인 규율
    // ICRNL이 CR→NL 변환하므로 encodePaste가 \n을 흘린 \r가 read 종료로 인식된다). 이 에코를 화면에서 찾아
    // "붙여넣기가 실제 자식 PTY까지 도달했는지"를 결정론적으로 본다. 자식이 한 줄만 읽고 종료하므로 각
    // 시나리오(accept/cancel/off)는 **fresh 세션**으로 분리한다(한 세션 재사용 시 첫 줄 뒤 자식이 죽어 취약).
    const H = struct {
        fn make(a: std.mem.Allocator) !*AppSession {
            const s = try a.create(AppSession);
            errdefer a.destroy(s);
            try s.init(std.Io.Threaded.global_single_threaded.io(), a, .{
                .abi_version = abi_version,
                .cols = 40,
                .rows = 10,
                .queue_capacity = 16,
                .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            });
            return s;
        }
        /// bound tick 안에 활성 surface 화면이 needle을 담는지(자식 에코 관측). deinit reap도 여기 tick으로 자식을 진행시킨다.
        fn tickUntil(s: *AppSession, needle: []const u8, a: std.mem.Allocator) !bool {
            var i: usize = 0;
            while (i < 400) : (i += 1) {
                _ = try s.tick();
                const dump = try s.activeSurface().core.dumpUtf8(a);
                defer a.free(dump);
                if (std.mem.indexOf(u8, dump, needle) != null) return true;
            }
            return false;
        }
    };

    // (A) 확인(accept) → 붙여넣기가 자식 PTY까지 도달한다(자식이 "Maru app input:AXK" 에코).
    {
        const s = try H.make(allocator);
        defer {
            s.deinit();
            allocator.destroy(s);
        }
        s.pasteText("AXK\nL2\nL3\nL4\nL5\nL6\nL7\nL8", false); // \n → 위험 → 보류(8줄 → 미리보기 6줄 + 요약)
        try std.testing.expect(s.chrome_host.confirm.open); // 확인 모달 열림
        try std.testing.expect(s.pending_paste_confirm.items.len > 0); // payload 보관
        try std.testing.expect(!s.hasPendingPaste()); // 아직 PTY로 안 감(보류)
        // 미리보기(Ghostty식): 확인창 body가 붙여넣을 내용을 반영한다 — 앞 6줄 + "…N줄 더" 요약 = 7줄.
        try std.testing.expectEqual(@as(usize, AppSession.paste_preview_max_lines + 1), s.chrome_host.confirm.body.len);
        try std.testing.expect(std.mem.indexOf(u8, s.chrome_host.confirm.body[0], "AXK") != null); // 첫 줄
        try std.testing.expect(std.mem.indexOf(u8, s.chrome_host.confirm.body[AppSession.paste_preview_max_lines], "줄 더") != null); // 요약
        // 프로덕션 순서(confirm.handle이 dismiss 후 dispatch)를 흉내: dismiss → dispatch.
        s.chrome_host.confirm.dismiss();
        s.dispatchChromeAction(.confirm_accept);
        try std.testing.expectEqual(@as(usize, 0), s.pending_paste_confirm.items.len); // 보류 소비
        try std.testing.expect(try H.tickUntil(s, "Maru app input:AXK", allocator)); // 자식이 붙여넣은 줄을 받음
    }

    // (B) 취소(cancel) → 붙여넣기가 자식까지 가지 않는다(자식은 read에 대기, "Maru app input:" 안 뜸).
    {
        const s = try H.make(allocator);
        defer {
            s.deinit();
            allocator.destroy(s);
        }
        s.pasteText("CXL\n", false);
        try std.testing.expect(s.chrome_host.confirm.open);
        try std.testing.expect(s.pending_paste_confirm.items.len > 0);
        s.chrome_host.confirm.dismiss();
        s.dispatchChromeAction(.confirm_cancel);
        try std.testing.expectEqual(@as(usize, 0), s.pending_paste_confirm.items.len); // 폐기
        try std.testing.expect(!s.hasPendingPaste()); // PTY 큐에도 안 들어감
        // 취소했으니 자식은 입력을 못 받는다 — 여러 tick 후에도 에코가 없다(붙여넣은 게 없으니 read 미완).
        try std.testing.expect(!(try H.tickUntil(s, "Maru app input:", allocator)));
    }

    // (C) protection off → 모달 없이 바로 자식까지 도달.
    {
        const s = try H.make(allocator);
        defer {
            s.deinit();
            allocator.destroy(s);
        }
        s.loaded_config.config.input.paste_protection = false;
        s.pasteText("OXF\n", false); // 개행 있어도 off라 확인 없음
        try std.testing.expect(!s.chrome_host.confirm.open); // 모달 없음
        try std.testing.expectEqual(@as(usize, 0), s.pending_paste_confirm.items.len); // 보관 안 함
        try std.testing.expect(try H.tickUntil(s, "Maru app input:OXF", allocator)); // 바로 자식까지
    }
}

// imeDecide(이제 ime.decide) 단위 테스트는 함수와 함께 src/session/ime.zig로 이동. imeEnd(부작용 포함)의
// 통합 테스트는 아래에 그대로 둔다(라이브 PTY/트랜잭션 닫힘 검증).

test "imeEnd always closes the transaction even with a null key (no leak) and fails closed on OOM" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // null 키로 닫아도 트랜잭션이 닫히고(ime_active=false), 누적 텍스트는 커밋된다.
    session.imeBegin();
    session.imeInsert("\xec\x95\x88"); // '안'
    const before = session.total_terminal_input_bytes;
    session.imeEnd(null); // 정규화 불가 키
    try std.testing.expect(!session.ime_active);
    try std.testing.expectEqual(before + 3, session.total_terminal_input_bytes);

    // OOM 플래그면 커밋을 통째로 버린다(잘린 문자열 방지).
    session.imeBegin();
    session.imeInsert("ab");
    session.ime_insert_failed = true;
    const before2 = session.total_terminal_input_bytes;
    session.imeEnd(.{ .key = .{ .char = 'x' }, .modifiers = .{} });
    try std.testing.expectEqual(before2, session.total_terminal_input_bytes);
    try std.testing.expect(!session.ime_active);
}

test "shouldReplayAfterCommit: arrows replay after candidate commit (left only when modified)" {
    // 화살표는 enter_newline과 무관하게 동작(둘째 인자 영향 없음).
    try std.testing.expect(AppSession.shouldReplayAfterCommit(.{ .key = .arrow_right, .modifiers = .{} }, false));
    try std.testing.expect(AppSession.shouldReplayAfterCommit(.{ .key = .arrow_down, .modifiers = .{} }, false));
    try std.testing.expect(AppSession.shouldReplayAfterCommit(.{ .key = .arrow_up, .modifiers = .{} }, false));
    try std.testing.expect(!AppSession.shouldReplayAfterCommit(.{ .key = .arrow_left, .modifiers = .{} }, false));
    try std.testing.expect(AppSession.shouldReplayAfterCommit(.{ .key = .arrow_left, .modifiers = .{ .shift = true } }, false));
    // Enter는 enter_newline일 때만 replay(브라우저 동작) — commit-only면 조합만 확정.
    try std.testing.expect(AppSession.shouldReplayAfterCommit(.{ .key = .enter, .modifiers = .{} }, true));
    try std.testing.expect(!AppSession.shouldReplayAfterCommit(.{ .key = .enter, .modifiers = .{} }, false));
    // Shift+Enter도 .enter라 같은 게이트를 따른다(replay 시 handleKeyEvent가 Meta 변형으로 \x1b\r 인코딩).
    try std.testing.expect(AppSession.shouldReplayAfterCommit(.{ .key = .enter, .modifiers = .{ .shift = true } }, true));
}

test "sendTextAsKeys normalizes newlines to CR and imeBegin snaps to bottom" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const surface = session.activeSurface();
    const core = &surface.core;

    // 스크롤백을 만들고 과거를 본 뒤 imeBegin → 바닥으로 스냅(조합이 보이게).
    try core.write("a\r\nb\r\nc\r\nd\r\ne\r\nf");
    core.scrollViewport(3);
    try std.testing.expect(core.viewOffset() != 0);
    session.imeBegin();
    try std.testing.expectEqual(@as(usize, 0), core.viewOffset());
    session.imeEnd(null);

    // 멀티라인 확정 텍스트의 \n이 \r로 정규화돼 PTY에 들어간다(LF 아님).
    // (controlled 셸의 read가 \r에 반응하도록 — 바이트 카운트만 확인: "a\nb" → 'a',\r,'b' = 3바이트)
    const before = session.total_terminal_input_bytes;
    session.imeBegin();
    session.imeInsert("a\nb");
    session.imeEnd(null);
    try std.testing.expectEqual(before + 3, session.total_terminal_input_bytes);
}

test "commitComposition during terminal preedit does not deadlock (회귀: bd5fd14)" {
    // 한글 조합 중(Surface preedit 존재) 창 키포커스를 잃으면 setFocused(false)→commitComposition이
    // 조합을 확정 전송한다. 과거엔 core_mutex를 쥔 채 sendTextAsKeys→handleKeyEvent가 같은 락을
    // 재취득해 메인 스레드가 ulock_wait에 박혀 hang했다(std.Io.Mutex는 비재진입 → self-deadlock;
    // sendCommittedText→sendTextAsKeys 통일 #2/bd5fd14로 "락 보유 중 호출 안전" 가정이 깨진 회귀).
    // 이 테스트가 끝까지 반환한다는 것 자체가 데드락이 사라졌다는 증거다(데드락이면 영영 멈춘다).
    // 더해서, 이제는 같은 클래스 회귀가 들어오면 디버그 빌드의 core_mutex 재진입 안전망
    // (CoreOwner, docs/io-render-threading.md §6-5)이 hang 대신 즉시 panic으로 노출한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const surface = session.activeSurface();

    // 터미널 조합 중 상태를 만든다(inputFocus 기본 .terminal → Surface overlay 세팅).
    session.imeMarked("한");
    try std.testing.expect(surface.preedit.active());

    const before = session.total_terminal_input_bytes;
    session.setFocused(false); // 창 키포커스 상실 → commitComposition(.terminal)

    try std.testing.expect(!surface.preedit.active()); // 조합이 확정되며 비워짐(다시 안 남음)
    try std.testing.expectEqual(before + "한".len, session.total_terminal_input_bytes);
    const after_first_commit = session.total_terminal_input_bytes;
    session.setFocused(false); // AppKit이 중복 resign 콜백을 줘도 이미 take됐으므로 재전송하지 않는다.
    try std.testing.expectEqual(after_first_commit, session.total_terminal_input_bytes);
}

test "terminal IME pin tombstones a reaped target and never retargets the same transaction" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.newTab(); // 두 번째 탭이 active

    const vanished_id = session.activeSurface().id;
    session.imeBegin();
    session.imeMarked("한");
    try std.testing.expectEqual(@as(?u64, vanished_id), session.ime_terminal_target_id);
    session.closeTab(session.app_window.active_tab); // pin target destroy, 첫 탭이 새 active
    const survivor = session.activeSurface();
    try std.testing.expect(survivor.id != vanished_id);

    session.imeMarked("나"); // missing pin을 null로 바꿔 survivor에 재지정하면 안 된다.
    try std.testing.expectEqual(@as(?u64, vanished_id), session.ime_terminal_target_id);
    try std.testing.expect(!survivor.preedit.active());
    const bytes_before = session.total_terminal_input_bytes;
    session.imeInsert("나");
    session.imeEnd(null);
    try std.testing.expectEqual(bytes_before, session.total_terminal_input_bytes);
    try std.testing.expect(session.ime_terminal_target_id == null);
}

test "terminal IME pin tombstone survives across key transactions and suppresses next physical key" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.newTab(); // 두 번째 탭이 active

    const vanished_id = session.activeSurface().id;
    session.imeBegin();
    session.imeMarked("한");
    session.imeEnd(null); // preedit은 계속 active라 terminal pin도 다음 keyDown까지 유지
    try std.testing.expectEqual(@as(?u64, vanished_id), session.ime_terminal_target_id);

    session.closeTab(session.app_window.active_tab); // key transaction 사이에 pinned target reap
    const survivor = session.activeSurface();
    try std.testing.expect(survivor.id != vanished_id);
    const bytes_before = session.total_terminal_input_bytes;
    const keys_before = session.total_key_events;

    // 입력기가 callback을 하나도 만들지 않은 평범한 물리 키. 과거 imeBegin은 missing pin에서
    // ime_active를 세우기 전에 return했고 imeEnd(.encode_key)가 이 키를 survivor로 보냈다.
    session.imeBegin();
    try std.testing.expect(session.ime_active);
    try std.testing.expect(session.ime_terminal_target_tombstoned);
    session.imeEnd(.{ .key = .{ .char = 'x' }, .modifiers = .{} });

    try std.testing.expectEqual(bytes_before, session.total_terminal_input_bytes);
    try std.testing.expectEqual(keys_before, session.total_key_events);
    try std.testing.expect(!survivor.preedit.active());
    try std.testing.expect(!session.ime_active);
    try std.testing.expect(!session.ime_terminal_target_tombstoned);
    try std.testing.expect(session.ime_terminal_target_id == null);
}

test "terminal IME pin wins over a newly opened palette during commit" {
