test "commitComposition sends committed text via non-blocking path, not blocking key path (#10)" {
    // #10: 한글 조합 중 창 포커스 상실 시 commitComposition이 확정 텍스트를 보내는데, 과거엔
    // sendTextAsKeys→handleKeyEvent(write_queue enqueueBlocking)를 탔다. windowLostKey는 AppKit이 메인
    // run loop를 동기 점유한 콜백이라, 그 안에서 enqueueBlocking이 write_queue 포화로 막히면 다음
    // tick(output drain)이 영영 안 와 reader도 멈추는 양방향 backpressure 데드락이 됐다(실측 hang
    // 리포트 2건, 28s·53s). 수정: sendCommittedText가 paste와 같은 non-blocking pending 경로로 보내
    // handleKeyEvent를 경유하지 않는다. backpressure 데드락 자체는 blocking이 본질이라 단위로 hang
    // 없이 재현이 어려워(재현하면 테스트가 멈춘다), 이 경로 불변식(handleKeyEvent 미경유 =
    // total_key_events 불변)으로 회귀를 고정하고, 실제 재현·소멸은 maru 실행으로 확인한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    const surface = session.activeSurface();

    session.imeMarked("한");
    try std.testing.expect(surface.preedit.active());

    const keys_before = session.total_key_events;
    const bytes_before = session.total_terminal_input_bytes;
    session.setFocused(false); // windowLostKey → commitComposition(.terminal)

    try std.testing.expect(!surface.preedit.active()); // 확정됨
    try std.testing.expectEqual(bytes_before + "한".len, session.total_terminal_input_bytes);
    // 핵심 불변식: blocking key 경로(handleKeyEvent)를 경유하지 않는다(non-blocking pending 전송).
    // 수정 전이면 sendTextAsKeys→handleKeyEvent로 total_key_events가 늘어 이 단언이 깨진다(#10 가드).
    try std.testing.expectEqual(keys_before, session.total_key_events);
}

test "imeEnd commit + transaction-less imeInsert send via non-blocking path (#10 follow-up)" {
    // #10은 commitComposition(windowLostKey)만 non-blocking으로 되돌렸으나, 같은 backpressure 데드락
    // 클래스인 두 경로가 남아 있었다: imeEnd(.commit_text)는 keyDown(interpretKeyEvents 직후) 동기
    // 콜백에서, 트랜잭션-밖 imeInsert(!ime_active — 입력기가 keyDown 없이 직접 커밋, 포커스 전환 등)는
    // AppKit 콜백에서 blocking sendTextAsKeys→handleKeyEvent(enqueueBlocking)를 탔다. 둘 다 같은
    // 불변식(handleKeyEvent 미경유 = total_key_events 불변)으로 non-blocking 경로를 고정한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // (1) imeEnd(.commit_text): 조합 시작 → 텍스트 누적 → 키 없이 종료 = 확정 텍스트만 전송.
    session.imeBegin(); // ime_active=true
    session.imeMarked("한"); // 조합 중 표시 → 종료 시 composing 판정 + ime_marked_changed
    session.imeInsert("한"); // 트랜잭션 안 — ime_inserted에 누적만
    const keys1 = session.total_key_events;
    const bytes1 = session.total_terminal_input_bytes;
    session.imeEnd(null); // 정규화 불가 키 없이 종료 → commit_text("한")
    try std.testing.expect(session.total_terminal_input_bytes > bytes1); // PTY로 확정 전송됨
    try std.testing.expectEqual(keys1, session.total_key_events); // 수정 전이면 sendTextAsKeys로 늘어 깨짐

    // (2) imeInsert(!ime_active): 위 imeEnd가 ime_active를 꺼 트랜잭션 밖 직접 커밋 경로.
    const keys2 = session.total_key_events;
    const bytes2 = session.total_terminal_input_bytes;
    session.imeInsert("을");
    try std.testing.expect(session.total_terminal_input_bytes > bytes2);
    try std.testing.expectEqual(keys2, session.total_key_events);
}

test "imeEnd commit and Enter replay remain ordered in one surface FIFO under backpressure" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const surface = session.activeSurface();
    // 자식이 한 번에 소비할 수 없는 선행 입력을 넣어 실제 nonblocking flush 뒤에도 FIFO tail이
    // 남게 한다. 개행이 없어 controlled child는 read에서 살아 있고, suffix로 transaction 순서를 본다.
    var blocked_prefix: [64 * 1024]u8 = undefined;
    @memset(&blocked_prefix, 'x');
    try std.testing.expect(session.queueInputBytes(surface.id, &blocked_prefix, false));
    const keys_before = session.total_key_events;
    session.imeBegin();
    session.imeMarked("한");
    session.imeInsert("한");
    session.imeEnd(.{ .key = .enter, .modifiers = .{} });

    const queued = session.pending_pastes.get(surface.id).?;
    try std.testing.expect(queued.offset < queued.buf.items.len);
    try std.testing.expect(std.mem.endsWith(u8, queued.buf.items, "한\r"));
    try std.testing.expectEqual(keys_before, session.total_key_events); // blocking handleKeyEvent를 우회한다.
}

test "IME commit and replay pair admission is atomic on queue allocation failure" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const target_id = session.activeSurface().id;
    try std.testing.expect(session.queueInputBytes(target_id, "prefix", false));
    const before = session.pending_pastes.get(target_id).?.buf.items.len;
    var large: [512]u8 = undefined;
    @memset(&large, 'x');

    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    session.allocator = failing.allocator();
    const admitted = session.queueInputPair(target_id, &large, true, "\r");
    session.allocator = allocator;

    try std.testing.expect(!admitted);
    const queue = session.pending_pastes.get(target_id).?;
    try std.testing.expectEqual(before, queue.buf.items.len);
    try std.testing.expectEqualStrings("prefix", queue.buf.items);
}

test "focus-loss commit preserves preedit and pin when ordered queue admission is OOM" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const surface = session.activeSurface();
    session.imeMarked("한");
    const target_id = session.ime_terminal_target_id.?;
    try std.testing.expect(surface.preedit.active());

    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    session.allocator = failing.allocator();
    session.commitComposition();
    session.allocator = allocator; // session teardown과 성공 재시도는 원 allocator로 복구.

    try std.testing.expect(surface.preedit.active());
    try std.testing.expectEqual(@as(?u64, target_id), session.ime_terminal_target_id);
    try std.testing.expect(session.pending_pastes.get(target_id) == null);

    session.commitComposition();
    try std.testing.expect(!surface.preedit.active());
    try std.testing.expect(session.ime_terminal_target_id == null);
}

test "surface별 paste 큐: 대상은 enqueue 시점에 고정되고 큐끼리 섞이지 않는다(탭 전환 오라우팅 방지)" {
    // paste/IME 확정 잔여가 다 빠지기 전 탭/pane이 바뀌면, 과거엔 flushPendingPaste가 self.activeSurface()로
    // 써 잔여가 새 surface에 입력됐다(선존 버그, code-review max 발견). 이제 대상을 enqueue 시점에
    // pending_paste_target으로 고정한다: 큐가 비었을 때만 현재 활성으로 다시 잡고, 잔여가 있으면 안 바꾼다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // paste 대상은 **enqueue 시점**에 고정된다 — 큐가 surface별이라 서로 섞이지 않는다(옛 단일 FIFO의 버그).
    // ★ 이 테스트의 핵심은 **각 큐가 자기 surface의 PTY로만 나간다**는 것이다. 가짜 id로는 그걸 못 잡는다
    //   (flush가 entry.key_ptr 대신 activeSurface().id로 써도 통과했다 — 뮤테이션 생존, code-review).
    //   그래서 **실제 surface 둘**(split)에 서로 다른 바이트를 넣고, 각 surface의 grid에 **자기 것만** 나타나는지
    //   본다. 라우팅 증거는 **PTY 라인 디서플린 에코**: 마스터에 쓴 입력 바이트를 슬레이브(ECHO on=기본값)가
    //   그대로 마스터로 되돌리므로, 바이트가 어느 surface의 PTY로 나갔는지가 그 surface grid에 직접 드러난다.
    session.backing_width_px = session.sidebar_width_px + 800;
    session.backing_height_px = 600;
    session.window_padding_px = .{};
    try session.splitActivePane(.horizontal);
    const tab = session.activeTab();
    try std.testing.expectEqual(@as(usize, 2), tab.panes.items.len);
    const sa = tab.panes.items[0].terms.items[tab.panes.items[0].active_term].surface;
    const sb = tab.panes.items[1].terms.items[tab.panes.items[1].active_term].surface;
    try std.testing.expect(sa.id != sb.id);

    // 각 surface에 **다른** 텍스트를 대상 지정해 붙인다(활성은 둘 중 하나뿐이다 — 대상이 활성으로 접히면 실패).
    // **개행을 붙이지 않는다**: 자식의 `read -r line`은 개행을 받아야 완료되는데, 완료되면 자식이 에코 후 곧장
    // **exit**하고 tick의 reapTerminatedTerms가 먼저 죽은 pane의 Term을 destroyTerm으로 회수한다 → 여기서
    // 캡처한 surface 포인터(sa/sb)가 dangling이 되어 아래 dump가 use-after-free다(seed 의존 간헐 crash,
    // code-review 발견 — **테스트 전용** 결함, 프로덕션 렌더는 live 트리만 순회하므로 회수된 surface를 dump
    // 안 함). 개행 없이 붙이면 자식은 `read`에서 계속 블록(생존)해 reap이 안 돌고 sa/sb가 유효하게 남는다.
    // 라우팅 증거는 위에서 말한 라인 디서플린 에코라 자식이 읽어 되쳐주지 않아도 grid에 바이트가 나타난다.
    // 제어문자가 없어 paste protection도 안 걸린다(개행 필요·보호 끄기 둘 다 불요).
    session.pasteTextTo(sa.id, "AAA", false);
    session.pasteTextTo(sb.id, "BBB", false);

    // flush + 에코 왕복까지 tick(자식 생존 → reap 없음). dump는 surface id 재조회로 얻는다 — 방어적으로,
    // 예기치 않게 회수돼도 dangling 접근(UAF) 대신 명확한 오류가 난다. id는 세션-로컬 비재사용이라 stale 매치 없음.
    const sa_id = sa.id;
    const sb_id = sb.id;
    var i: usize = 0;
    while (i < 400) : (i += 1) _ = try session.tick();
    const surf_a = session.terminalSurfaceById(sa_id) orelse return error.SurfaceUnexpectedlyReaped;
    const surf_b = session.terminalSurfaceById(sb_id) orelse return error.SurfaceUnexpectedlyReaped;
    const dump_a = try surf_a.core.dumpUtf8(allocator);
    defer allocator.free(dump_a);
    const dump_b = try surf_b.core.dumpUtf8(allocator);
    defer allocator.free(dump_b);
    // ★ A의 PTY엔 AAA만, B의 PTY엔 BBB만 나갔다 — 큐가 대상 surface의 PTY로만 나간다는 계약(에코가 증거).
    try std.testing.expect(std.mem.indexOf(u8, dump_a, "AAA") != null);
    try std.testing.expect(std.mem.indexOf(u8, dump_a, "BBB") == null);
    try std.testing.expect(std.mem.indexOf(u8, dump_b, "BBB") != null);
    try std.testing.expect(std.mem.indexOf(u8, dump_b, "AAA") == null);
    try std.testing.expect(!session.hasPendingPaste()); // 둘 다 다 나갔다
}

test "sidebarMaxScrollPx: 콘텐츠가 헤더 아래 뷰포트를 넘는 양(스크롤 불필요면 0, overflow 안전)" {
    // content 0이면 항상 0(빈 사이드바). 이제 content_height_px를 직접 받는다(가변 높이라 count*slot_h 대신 contentHeight 누적).
    try std.testing.expectEqual(@as(u32, 0), AppSession.sidebarMaxScrollPx(0, 600, 60));
    // viewport = backing(600) − header(60) = 540. content 400 ≤ 540 → 0(안 넘침).
    try std.testing.expectEqual(@as(u32, 0), AppSession.sidebarMaxScrollPx(400, 600, 60));
    // content 800 > 540 → max = 800 − 540 = 260.
    try std.testing.expectEqual(@as(u32, 260), AppSession.sidebarMaxScrollPx(800, 600, 60));
    // 정확히 뷰포트와 같으면 0(경계). content 540, viewport 540.
    try std.testing.expectEqual(@as(u32, 0), AppSession.sidebarMaxScrollPx(540, 600, 60));
    // 헤더가 backing보다 크면 viewport 0 → content 전부가 스크롤 범위(degenerate but 안전, 음수 언더플로 없음).
    try std.testing.expectEqual(@as(u32, 160), AppSession.sidebarMaxScrollPx(160, 50, 60));
    // content 0이면 0.
    try std.testing.expectEqual(@as(u32, 0), AppSession.sidebarMaxScrollPx(0, 600, 60));
}

test "scrollbarThumbGeom: null without scrollback, thumb size/position track view_offset" {
    // 스크롤백 없으면 안 그림(null).
    try std.testing.expect(AppSession.scrollbarThumbGeom(0, 0, 16, 320) == null);
    try std.testing.expect(AppSession.scrollbarThumbGeom(20, 0, 0, 320) == null); // cell_height 0
    try std.testing.expect(AppSession.scrollbarThumbGeom(20, 0, 16, 0) == null); // view 0

    // sb_count=20(=20행 @16px=320px), view 320px. total 640px → thumb_h = 320*320/640 = 160.
    const bottom = AppSession.scrollbarThumbGeom(20, 0, 16, 320).?; // view_offset 0 = 바닥
    try std.testing.expectApproxEqAbs(@as(f32, 160), bottom.h, 0.5);
    try std.testing.expectApproxEqAbs(@as(f32, 160), bottom.y, 0.5); // 바닥: y = view-thumb = 320-160
    const top = AppSession.scrollbarThumbGeom(20, 20, 16, 320).?; // view_offset 20 = 꼭대기
    try std.testing.expectApproxEqAbs(@as(f32, 0), top.y, 0.5); // 꼭대기: y = 0
    const mid = AppSession.scrollbarThumbGeom(20, 10, 16, 320).?; // 중간(t=0.5)
    try std.testing.expectApproxEqAbs(@as(f32, 80), mid.y, 0.5); // (320-160)*(1-0.5)

    // 스크롤백이 많으면 thumb는 최소 높이(18px)로 clamp.
    const tiny = AppSession.scrollbarThumbGeom(10000, 0, 16, 320).?;
    try std.testing.expectApproxEqAbs(@as(f32, 18), tiny.h, 0.5);
}

test "scrollbarTargetOffset: clamp + round, and round-trips scrollbarThumbGeom" {
    // t(0=바닥, 1=꼭대기)를 view_offset으로. 경계·중간.
    try std.testing.expectEqual(@as(usize, 0), AppSession.scrollbarTargetOffset(0.0, 20)); // 바닥
    try std.testing.expectEqual(@as(usize, 20), AppSession.scrollbarTargetOffset(1.0, 20)); // 꼭대기
    try std.testing.expectEqual(@as(usize, 10), AppSession.scrollbarTargetOffset(0.5, 20)); // 중간
    // [0,1] 밖은 clamp.
    try std.testing.expectEqual(@as(usize, 0), AppSession.scrollbarTargetOffset(-0.3, 20));
    try std.testing.expectEqual(@as(usize, 20), AppSession.scrollbarTargetOffset(1.5, 20));
    // round(0.5*20=10 정수경계 위 1.54→2).
    try std.testing.expectEqual(@as(usize, 2), AppSession.scrollbarTargetOffset(0.077, 20));

    // 역매핑은 scrollbarThumbGeom의 정확한 역이어야 한다 — 각 view_offset에서 thumb_top(geom.y)을 뽑아
    // t로 되돌리면 같은 offset이 나온다(드래그 위치 ↔ scroll 위치가 1:1, drift 없음).
    const sb: usize = 20;
    const ch: u32 = 16;
    const view: u32 = 320;
    inline for (.{ 0, 3, 7, 13, 20 }) |V| {
        const g = AppSession.scrollbarThumbGeom(sb, V, ch, view).?;
        const track: f64 = @as(f64, @floatFromInt(view)) - @as(f64, g.h);
        const t: f64 = 1.0 - @as(f64, g.y) / track;
        try std.testing.expectEqual(@as(usize, V), AppSession.scrollbarTargetOffset(t, sb));
    }
}

test "scrollbarBarWidthPx: cell 비율·최소 px·emphasize 가산" {
    // cell_width 큰 경우 비율(0.5)이 최소(7)를 넘는다.
    try std.testing.expectApproxEqAbs(@as(f32, 10), AppSession.scrollbarBarWidthPx(20, false), 0.01); // 20*0.5
    try std.testing.expectApproxEqAbs(@as(f32, 12), AppSession.scrollbarBarWidthPx(20, true), 0.01); // +2 emphasize
    // 작은 cell이면 최소 px로 clamp.
    try std.testing.expectApproxEqAbs(@as(f32, 7), AppSession.scrollbarBarWidthPx(8, false), 0.01); // 8*0.5=4 < 7
    try std.testing.expectApproxEqAbs(@as(f32, 9), AppSession.scrollbarBarWidthPx(8, true), 0.01); // 7+2
}

test "computeScrollbarAlpha: full→idle 감쇠(visible 유지·fade 후 faint·단조 감소)" {
    const visible = default_scrollbar_visible_ticks;
    const fade = default_scrollbar_fade_ticks;
    // visible_ticks까지 full.
    try std.testing.expectEqual(scrollbar_alpha_full, AppSession.computeScrollbarAlpha(0));
    try std.testing.expectEqual(scrollbar_alpha_full, AppSession.computeScrollbarAlpha(visible));
    // fade 완료 후(visible+fade 이상) faint 정착.
    try std.testing.expectEqual(scrollbar_alpha_idle, AppSession.computeScrollbarAlpha(visible + fade));
    try std.testing.expectEqual(scrollbar_alpha_idle, AppSession.computeScrollbarAlpha(visible + fade + 100));
    // fade 창 안은 full~idle 사이에서 단조 감소(틱이 늘수록 alpha가 줄거나 같다).
    var prev: u8 = scrollbar_alpha_full;
    var k: u32 = visible;
    while (k <= visible + fade) : (k += 1) {
        const a = AppSession.computeScrollbarAlpha(k);
        try std.testing.expect(a <= prev);
        try std.testing.expect(a >= scrollbar_alpha_idle);
        prev = a;
    }
}

