    try std.testing.expectEqual(scrollbar_alpha_idle, session.scrollbarAlpha(session.scrollbarFadeCompleteTicks()));
}

test "appendPaneScrollbars: split 각 pane이 자기 idle_ticks로 독립 fade (per-pane)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest; // 실 PTY + split 생성
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    session.dispatchAppAction(.split_horizontal); // pane 2개(좌우)
    // 두 pane 모두 스크롤백을 만든다 — resize(800x600)가 grid를 backing px로 재계산해 rows가 init값(6)이
    // 아니라 ~33이므로, 그보다 충분히 많은 줄(200)을 각 core에 직접 써서 어느 rows든 스크롤백을 보장한다.
    for (session.activeTab().panes.items) |pane| {
        const core = &pane.activeTerm().surface.core;
        var n: usize = 0;
        while (n < 200) : (n += 1) try core.write("line\r\n");
        try std.testing.expect(core.scrollbackLen() > 0);
    }

    // per-pane fade: 한 pane은 full(idle 0), 다른 pane은 faint(fade 정착)로 둔다 — alpha가 각 pane 자기
    // idle_ticks를 따른다(세션 단일 값이 아님을 증명). hover/드래그 없음.
    session.dropQuadsByLayer(3);
    session.scrollbar_hovered = false;
    const panes = session.activeTab().panes.items;
    panes[0].scrollbar_idle_ticks = 0; // full
    panes[1].scrollbar_idle_ticks = session.scrollbarFadeCompleteTicks(); // faint 정착
    session.appendPaneScrollbars();

    // pane 2개 → layer3 thumb 2개. 각 pane 자기 idle_ticks 반영 — 하나 full, 하나 faint.
    var count: usize = 0;
    var saw_full = false;
    var saw_faint = false;
    for (session.gpu_quads.items) |q| {
        if (q.layer != 3) continue;
        count += 1;
        const a: u8 = @intCast((q.fill_color0 >> 24) & 0xff);
        if (a == scrollbar_alpha_full) saw_full = true;
        if (a == scrollbar_alpha_idle) saw_faint = true;
    }
    try std.testing.expectEqual(@as(usize, 2), count);
    try std.testing.expect(saw_full); // idle_ticks 0 pane
    try std.testing.expect(saw_faint); // fade 정착 pane
}

test "configPath caches the resolved config path (single alloc, freed in deinit)" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.config_path_buffer = null;
    defer if (session.config_path_buffer) |b| std.testing.allocator.free(b);
    const p1 = session.configPath();
    const p2 = session.configPath();
    // 두 번째 호출은 캐시 — 같은 포인터/길이(재할당 없음, 안 그러면 testing.allocator가 leak 잡음).
    try std.testing.expectEqual(p1.ptr, p2.ptr);
    try std.testing.expectEqual(p1.len, p2.len);
}

test "imeCursorRect returns the cursor cell rect in backing px for IME candidate placement" {
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io(); // imeCursorRect가 커서를 lockCore 아래 읽음(P4-3)
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 10, .rows = 5 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.active_pane_rect = .{ .x = 0, .y = 0, .w = 80, .h = 80 }; // 활성 panel origin (0,0): 커서 좌표는 col*cw/row*ch 그대로
    // imeCursorRect는 inputFocus()(chrome_host.*.open)와 buildChromeProps→buildChromeTokens(appearance.chrome_theme
    // enum switch)를 읽는다. `var session = undefined`라 이 둘을 안 채우면 0xaa 쓰레기 → enum switch가 corrupt로
    // 패닉한다(타깃·struct 레이아웃에 따라 우연히 통과 또는 크래시 — devsession-undefined-test-field-trap). 명시
    // 초기화로 결정적 `.terminal`(오버레이 caret 없음) 경로를 타게 한다.
    session.chrome_host = .{};
    session.rename = null; // inputFocus(imeCursorRect)가 rename을 읽음([[devsession-undefined-test-field-trap]])
    session.sidebar_search_active = false; // inputFocus가 rename 다음으로 읽음 — 결정적 .terminal 경로용
    session.addr_edit = null; // inputFocus가 읽고, 이제 .addr_edit 분기가 addrEditCaretRect로 상태를 역참조함(리뷰 [4]) → 명시 init 필수
    session.focus_owner = .workspace;
    session.pending_dock_focus = null;
    session.tabs = .empty; // [4e-2] imeCursorRect 게이트 activeTermIsTerminal이 tabs를 읽음 — 빈 트리=terminal 취급(byte-identical)
    session.appearance = config_mod.resolveAppearance(.{}) catch unreachable;
    session.ime_terminal_target_id = null; // imeCursorRect가 pin 유무를 먼저 읽음([[devsession-undefined-test-field-trap]])

    const core = &tab_surface.core;
    // [P4-3] imeCursorRect는 활성 surface 커서를 lockCore 아래 live로 읽는다(무락 torn read race 정정) — core write가
    // 즉시 반영된다(캐시 없음).
    try core.write("ab"); // 커서가 (0,2)로
    const r = session.imeCursorRect();
    try std.testing.expectEqual(@as(f64, 16), r.x); // col 2 * 8
    try std.testing.expectEqual(@as(f64, 0), r.y); // row 0 * 16
    try std.testing.expectEqual(@as(f64, 8), r.w);
    try std.testing.expectEqual(@as(f64, 16), r.h);

    try core.write("\r\nXY"); // 둘째 줄로
    const r2 = session.imeCursorRect();
    try std.testing.expectEqual(@as(f64, 16), r2.x); // col 2
    try std.testing.expectEqual(@as(f64, 16), r2.y); // row 1 * 16

    // 활성 panel이 서브-rect에 있으면(split/사이드바) 커서 스크린 좌표가 panel origin만큼 이동한다 — 후보창이
    // 실제 커서 아래에 뜬다. origin (24, 32): x는 +24, y는 +32(단일 panel일 땐 origin = (사이드바 폭, 0)).
    session.active_pane_rect = .{ .x = 24, .y = 32, .w = 80, .h = 80 };
    const r3 = session.imeCursorRect();
    try std.testing.expectEqual(@as(f64, 24 + 16), r3.x); // origin_x(24) + col 2 * 8
    try std.testing.expectEqual(@as(f64, 32 + 16), r3.y); // origin_y(32) + row 1 * 16
}

test "readActiveSnapshot: 활성 코어 sync/커서/위치를 단일 lock 값 스냅샷으로(P4-2)" {
    // §12 P4-2: tick당 흩어진 활성 코어 read(sync 게이트 D·커서 blink B·커서 위치)를 한 lock으로 통합한 값 스냅샷.
    // 이 테스트는 그 스냅샷이 코어 상태(sync_output·bsu/esu·커서 row/col)를 정확히 뜨는지, need_blink_scan 게이트로
    // viewportHasBlink 스캔을 조건화하는지 고정한다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    session.io = std.Io.Threaded.global_single_threaded.io();
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 10, .rows = 5 });
    defer tab_surface.deinit();
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.surface_initialized = true; // [4e-2] readActiveSnapshot 게이트 activeTerminalSurface가 읽음
    session.tabs = .empty; // [4e-2] activeTermIsTerminal이 tabs를 읽음 — 빈 트리=terminal 취급(activeSurface 경로, byte-identical)
    const core = &tab_surface.core;

    // sync(2026) BSU + 커서 이동 → sync_output=true, bsu=1, 커서 (0,3).
    try core.write("\x1b[?2026h");
    try core.write("abc");
    const s1 = session.readActiveSnapshot(true);
    try std.testing.expect(s1.sync_output);
    try std.testing.expectEqual(@as(u64, 1), s1.bsu);
    try std.testing.expect(!s1.viewport_has_blink); // 이 화면엔 SGR 5 blink 셀 없음

    // ESU → sync off, esu=1. 커서 visible도 반영.
    try core.write("\x1b[?2026l");
    const s2 = session.readActiveSnapshot(false);
    try std.testing.expect(!s2.sync_output);
    try std.testing.expectEqual(@as(u64, 1), s2.esu);
    try std.testing.expect(s2.cursor_visible);
    try std.testing.expect(!s2.viewport_has_blink); // need_blink_scan=false → 스캔 자체를 안 함
}

test "pxToCell subtracts the active pane origin so clicks map to that pane's columns and rows" {
    // 활성 panel은 자기 rect origin에서 그려지므로, 스크린 픽셀에서 origin(x,y)을 뺀 뒤에야 그 panel의
    // 열/행이 된다(단일 panel이면 origin = (사이드바 폭, 0)이라 기존과 동일). 안 빼면 선택/클릭 블록이
    // origin만큼 어긋난다(라이브 제보 회귀). split이면 origin은 서브-rect의 좌상단이다.
    var session: AppSession = undefined;
    session.allocator = std.testing.allocator;
    var tab_surface = try maru.session.Surface.init(std.testing.allocator, 1, .{ .cols = 10, .rows = 5 });
    defer tab_surface.deinit();
    session.surface_initialized = true;
    var st_ptrs = [_]*maru.session.Surface{&tab_surface};
    session.app_window = .{ .tabs = &st_ptrs };
    session.cell_width_px = 8;
    session.cell_height_px = 16;
    session.active_pane_rect = .{ .x = 24, .y = 0, .w = 80, .h = 80 }; // origin_x 24(=3칸), origin_y 0

    // panel 왼쪽 끝(스크린 x=origin_x=24) → col 0.
    try std.testing.expectEqual(@as(u16, 0), session.pxToCell(24, 0).?.col);
    // origin_x + 2*cw = 24+16=40 → col 2.
    try std.testing.expectEqual(@as(u16, 2), session.pxToCell(40, 0).?.col);
    // origin 왼쪽(x=10 < origin_x) → 음수 clamp → col 0(panel 왼쪽 끝).
    try std.testing.expectEqual(@as(u16, 0), session.pxToCell(10, 0).?.col);

    // y origin도 뺀다(상하 split의 아래 panel): origin (0, 16) → 스크린 y에서 16을 뺀 뒤 행.
    session.active_pane_rect = .{ .x = 0, .y = 16, .w = 80, .h = 80 };
    try std.testing.expectEqual(@as(u16, 2), session.pxToCell(16, 16).?.col); // x=16 → col 2(origin_x 0)
    try std.testing.expectEqual(@as(u16, 0), session.pxToCell(16, 16).?.row); // y=16 - origin_y 16 = 0 → row 0
    try std.testing.expectEqual(@as(u16, 1), session.pxToCell(16, 32).?.row); // y=32 - 16 = 16 → row 1
}

// pageScrollDelta 단위 테스트는 함수와 함께 src/session/input_math.zig로 이동.

// ══ M3d-2a-i: cross-window workspace/window 라이브 이동(docs/window-surface-mobility.md §8A.8) ═══════════════════
// 두 controlled_smoke 세션이 앱-전역 `app_runtime`(surface_ids·live_registry·routing)을 **공유**하므로, fake registry
// 없이 실제 두-창 트리 수술의 **무재시작 불변식**(§9 — 이동 전후 같은 `*LiveSurface`·live_pty·스크롤백, 재시작 0)과
// 양-창 정합·빈 source latch·outcome·trace 재지정을 헤드리스로 못박는다. 실 PTY라 macOS 게이트. 세션은 tick하지
// 않으므로(surface 존재만 필요) controlled_smoke 셸의 exit/reap과 무관하게 결정론적이다.

/// 살아 있는 워크스페이스(탭)를 하나 더 만든다 — cat으로 stdin을 물고 있어 (tick하면) reap이 안 닫는다(여기선 tick 안 함).
fn addMoveTestWorkspace(session: *AppSession, title: []const u8) !void {
    _ = try session.createTab(
        .{ .command = "/bin/sh", .args = &.{ "-c", "cat" }, .size = .{ .cols = 20, .rows = 5 } },
        .{ .cols = 20, .rows = 5 },
        16,
        title,
        "sh",
    );
}

test "M3d-2a-i moveWorkspaceToSession: cross-window 무재시작(동일 *LiveSurface·live_pty·surface·스크롤백·재시작0) + 양창 정합 + outcome" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();

    // src에 두 번째 워크스페이스를 만들어 그걸 옮긴다(첫 워크스페이스는 src에 남아 src가 안 닫히게).
    try addMoveTestWorkspace(src, "moved-ws");
    try std.testing.expectEqual(@as(usize, 2), src.tabs.items.len);

    // 옮길 워크스페이스(idx 1)의 라이브 슬롯 스냅샷.
    const moved_term = src.tabs.items[1].activeTerm();
    const moved_surface = moved_term.surface; // *Surface(번들 슬롯 참조)
    const moved_id = moved_surface.id;
    const slot_before = src.live_registry.findBySurface(moved_id).?; // *LiveSurface(registry 소유 슬롯)
    const moved_handle = moved_term.rt.handle; // P2: opaque runtime handle(= surface_id) — live_pty 포인터 대신
    const live_pty_before = &slot_before.terminal.live_pty; // 슬롯 live_pty 주소(registry 조회)
    const entries_before = src.live_registry.entries.items.len;

    // 코어 스크롤백에 마커를 심어 이동이 터미널 상태를 보존하는지 본다(재생성이면 사라진다).
    moved_surface.lockCore(src.io);
    moved_surface.core.write("MOVE_MARK_42\r\n") catch {};
    moved_surface.unlockCore(src.io);

    // 창 간 reparent 직전 조합은 source attachment에서 원 runtime으로 확정하고, client-local
    // overlay 자체는 destination 창으로 운반하지 않는다.
    src.imeMarked("한");
    try std.testing.expect(moved_surface.preedit.active());
    const input_bytes_before_move = src.total_terminal_input_bytes;

    var buf: [8]u64 = undefined;
    const outcome = try src.moveWorkspaceToSession(dst, 1, &buf);

    // outcome: 창 간 이동, moved={moved_id}, normal↔normal이라 revoke 없음, src에 첫 워크스페이스 남아 안 닫힘.
    try std.testing.expect(outcome.cross_window);
    try std.testing.expect(!outcome.revoke_caps);
    try std.testing.expect(!outcome.source_window_closed);
    try std.testing.expectEqual(@as(usize, 1), outcome.moved_surfaces.len);
    try std.testing.expectEqual(moved_id, outcome.moved_surfaces[0]);

    // 양창 정합: src 1탭·dst 2탭, src 안 닫힘. surface_ptrs가 app_window.tabs와 같은 backing(재바인딩).
    try std.testing.expectEqual(@as(usize, 1), src.tabs.items.len);
    try std.testing.expectEqual(@as(usize, 2), dst.tabs.items.len);
    try std.testing.expect(!src.ended_seen);
    try std.testing.expectEqual(dst.surface_ptrs.items.len, dst.tabs.items.len);
    try std.testing.expectEqual(dst.surface_ptrs.items.ptr, dst.app_window.tabs.ptr);
    try std.testing.expectEqual(src.surface_ptrs.items.ptr, src.app_window.tabs.ptr);

    // **무재시작(§9)**: registry를 안 건드렸으니 dst에서 조회해도 같은 슬롯·같은 live_pty·같은 *Surface·엔트리 수 불변(create/remove 0).
    const adopted_term = dst.tabs.items[1].activeTerm();
    const slot_after = dst.live_registry.findBySurface(moved_id).?;
    try std.testing.expectEqual(slot_before, slot_after);
    try std.testing.expectEqual(live_pty_before, &slot_after.terminal.live_pty); // 슬롯 live_pty 주소 불변(registry 무변경)
    try std.testing.expectEqual(moved_handle, adopted_term.rt.handle); // P2: 창을 옮겨도 handle 불변(무재시작)
    try std.testing.expectEqual(moved_surface, adopted_term.surface);
    try std.testing.expectEqual(entries_before, dst.live_registry.entries.items.len);
    try std.testing.expect(!adopted_term.surface.preedit.active()); // destination attachment에 marked text가 나타나지 않음
    try std.testing.expect(src.ime_terminal_target_id == null);
    try std.testing.expectEqual(input_bytes_before_move + "한".len, src.total_terminal_input_bytes);
    const src_bytes_after_move = src.total_terminal_input_bytes;
    const dst_bytes_after_move = dst.total_terminal_input_bytes;
    src.setFocused(false);
    dst.setFocused(false);
    try std.testing.expectEqual(src_bytes_after_move, src.total_terminal_input_bytes);
    try std.testing.expectEqual(dst_bytes_after_move, dst.total_terminal_input_bytes);
    // dst 대표 surface_ptr가 옮겨온 워크스페이스의 활성 surface(정합).
    try std.testing.expectEqual(moved_surface, dst.surface_ptrs.items[1]);

    // 코어 스크롤백 보존(같은 core, 재생성 아님).
    const dump = try slot_after.terminal.surface.core.dumpUtf8(allocator);
    defer allocator.free(dump);
    try std.testing.expect(std.mem.indexOf(u8, dump, "MOVE_MARK_42") != null);
}

test "moveWorkspaceToSession aborts before detach when active preedit queue admission is OOM" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();

    try addMoveTestWorkspace(src, "preedit-oom");
    const moved = src.tabs.items[1].activeTerm().surface;
    const destination = dst.activeSurface();
    try std.testing.expectEqual(@as(usize, 1), src.app_window.active_tab);
    src.imeMarked("한");
    dst.imeMarked("둘");
    try std.testing.expect(moved.preedit.active());
    try std.testing.expect(destination.preedit.active());
    try src.pending_pastes.put(src.allocator, moved.id, .{}); // map allocation은 미리 끝내고 queue buffer OOM만 주입.

    const src_tabs_before = src.tabs.items.len;
    const dst_tabs_before = dst.tabs.items.len;
    const src_input_before = src.total_terminal_input_bytes;
    const dst_input_before = dst.total_terminal_input_bytes;
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    src.allocator = failing.allocator();
    var moved_buf: [8]u64 = undefined;
    const result = src.moveWorkspaceToSession(dst, 1, &moved_buf);
    src.allocator = allocator;

    try std.testing.expectError(error.OutOfMemory, result);
    try std.testing.expectEqual(src_tabs_before, src.tabs.items.len);
    try std.testing.expectEqual(dst_tabs_before, dst.tabs.items.len);
    try std.testing.expectEqual(moved, src.tabs.items[1].activeTerm().surface);
    try std.testing.expect(moved.preedit.active());
    try std.testing.expect(destination.preedit.active());
    try std.testing.expectEqual(@as(?u64, moved.id), src.ime_terminal_target_id);
    try std.testing.expectEqual(@as(?u64, destination.id), dst.ime_terminal_target_id);
    try std.testing.expectEqual(src_input_before, src.total_terminal_input_bytes);
    try std.testing.expectEqual(dst_input_before, dst.total_terminal_input_bytes);
}

test "moveWorkspaceToSession destination preedit OOM preserves both owners and retry admits each once" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();

    try addMoveTestWorkspace(src, "destination-preedit-oom");
    const moved = src.tabs.items[1].activeTerm().surface;
    const destination = dst.activeSurface();
    src.imeMarked("한");
    dst.imeMarked("둘");
    try std.testing.expect(moved.preedit.active());
    try std.testing.expect(destination.preedit.active());

    // 구조 배열/map allocation은 미리 끝내고 destination queue buffer admission만 실패시킨다.
    try dst.tabs.ensureUnusedCapacity(dst.allocator, 1);
    try dst.surface_ptrs.ensureUnusedCapacity(dst.allocator, 1);
    try dst.pending_pastes.put(dst.allocator, destination.id, .{});
    const src_tabs_before = src.tabs.items.len;
    const dst_tabs_before = dst.tabs.items.len;
    const src_active_before = src.tabs.items[src.app_window.active_tab];
    const dst_active_before = dst.tabs.items[dst.app_window.active_tab];
    const src_input_before = src.total_terminal_input_bytes;
    const dst_input_before = dst.total_terminal_input_bytes;

    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    dst.allocator = failing.allocator();
    var moved_buf: [8]u64 = undefined;
    const failed = src.moveWorkspaceToSession(dst, 1, &moved_buf);
    dst.allocator = allocator;

    try std.testing.expectError(error.OutOfMemory, failed);
    try std.testing.expectEqual(src_tabs_before, src.tabs.items.len);
    try std.testing.expectEqual(dst_tabs_before, dst.tabs.items.len);
    try std.testing.expectEqual(src_active_before, src.tabs.items[src.app_window.active_tab]);
    try std.testing.expectEqual(dst_active_before, dst.tabs.items[dst.app_window.active_tab]);
    try std.testing.expect(moved.preedit.active());
    try std.testing.expect(destination.preedit.active());
    try std.testing.expectEqual(@as(?u64, moved.id), src.ime_terminal_target_id);
    try std.testing.expectEqual(@as(?u64, destination.id), dst.ime_terminal_target_id);
    try std.testing.expectEqual(src_input_before, src.total_terminal_input_bytes);
    try std.testing.expectEqual(dst_input_before, dst.total_terminal_input_bytes);
    try std.testing.expect(src.pending_pastes.get(moved.id) == null); // source preflight의 새 empty entry도 rollback.
    try std.testing.expectEqual(@as(usize, 0), dst.pending_pastes.get(destination.id).?.buf.items.len);

    _ = try src.moveWorkspaceToSession(dst, 1, &moved_buf);
    try std.testing.expect(!moved.preedit.active());
    try std.testing.expect(!destination.preedit.active());
    try std.testing.expect(src.ime_terminal_target_id == null);
    try std.testing.expect(dst.ime_terminal_target_id == null);
    try std.testing.expectEqual(src_input_before + "한".len, src.total_terminal_input_bytes);
    try std.testing.expectEqual(dst_input_before + "둘".len, dst.total_terminal_input_bytes);
}

test "moveWorkspaceToSession transfer preflight OOM occurs before either composition commit" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();

    try addMoveTestWorkspace(src, "transfer-preflight-oom");
    const moved = src.tabs.items[1].activeTerm().surface;
    const destination = dst.activeSurface();
    src.imeMarked("한");
    dst.imeMarked("둘");

    // 양 composition reservation 자체는 무할당으로 통과하게 미리 queue/capacity를 만든다.
    try src.pending_pastes.put(src.allocator, moved.id, .{});
    try src.pending_pastes.getPtr(moved.id).?.buf.ensureUnusedCapacity(src.allocator, "한".len);
    try dst.pending_pastes.put(dst.allocator, destination.id, .{});
    try dst.pending_pastes.getPtr(destination.id).?.buf.ensureUnusedCapacity(dst.allocator, "둘".len);
    try dst.tabs.ensureUnusedCapacity(dst.allocator, 1);
    try dst.surface_ptrs.ensureUnusedCapacity(dst.allocator, 1);

    const src_tab_count = src.tabs.items.len;
    const dst_tab_count = dst.tabs.items.len;
    const src_active = src.tabs.items[src.app_window.active_tab];
    const dst_active = dst.tabs.items[dst.app_window.active_tab];
    const src_input_before = src.total_terminal_input_bytes;
    const dst_input_before = dst.total_terminal_input_bytes;
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    dst.allocator = failing.allocator();
    var moved_buf: [8]u64 = undefined;
    const result = src.moveWorkspaceToSession(dst, 1, &moved_buf);
    dst.allocator = allocator;

    try std.testing.expectError(error.OutOfMemory, result);
    try std.testing.expectEqual(src_tab_count, src.tabs.items.len);
    try std.testing.expectEqual(dst_tab_count, dst.tabs.items.len);
    try std.testing.expectEqual(src_active, src.tabs.items[src.app_window.active_tab]);
    try std.testing.expectEqual(dst_active, dst.tabs.items[dst.app_window.active_tab]);
    try std.testing.expect(moved.preedit.active());
    try std.testing.expect(destination.preedit.active());
    try std.testing.expectEqual(@as(?u64, moved.id), src.ime_terminal_target_id);
    try std.testing.expectEqual(@as(?u64, destination.id), dst.ime_terminal_target_id);
    try std.testing.expectEqual(src_input_before, src.total_terminal_input_bytes);
    try std.testing.expectEqual(dst_input_before, dst.total_terminal_input_bytes);
    try std.testing.expectEqual(@as(usize, 0), src.pending_pastes.get(moved.id).?.buf.items.len);
    try std.testing.expectEqual(@as(usize, 0), dst.pending_pastes.get(destination.id).?.buf.items.len);
}

test "moveWorkspaceToSession same-session commits only when active owner changes" {
