test "FP9 merge remaps destination focus one-shots when dirty source replaces clean duplicate" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const src = try initSmokeSessionSized(allocator);
    defer allocator.destroy(src);
    defer src.deinit();
    const dst = try initSmokeSessionSized(allocator);
    defer allocator.destroy(dst);
    defer dst.deinit();

    const path = "/tmp/fp9-duplicate-focus.md";
    _ = try src.openFileTermInActivePane(path, .markdown);
    _ = try dst.openFileTermInActivePane(path, .markdown);
    _ = try dst.openFileTermInActivePane("/tmp/fp9-newer-native-focus.md", .markdown);
    src.assignDockSurfaceIds();
    dst.assignDockSurfaceIds();
    const source = src.fileEntryAt(0).?;
    const destination = dst.fileEntryAt(0).?;
    const newer_surface = dst.fileEntryAt(1).?.surface_id;
    source.dirty = true;
    source.mode = .source_edit;
    // The scenario is specifically dirty source versus a confirmed clean duplicate. New Markdown entries
    // default to live mode, whose not-yet-snapshotted editor must fail closed, so pin the destination to the
    // persisted read state this merge case is meant to exercise.
    destination.mode = .read;
    const source_id = source.id;
    const source_surface = source.surface_id;
    const retired_surface = destination.surface_id;
    _ = dst.focusFilePanelSurface(retired_surface);
    dst.file_panel_mode_pending = retired_surface;
    dst.file_tree_restore_surface_pending = retired_surface;
    dst.queuePendingDockFocus(destination);

    var moved_buf: [16]u64 = undefined;
    _ = try src.mergeSessionInto(dst, &moved_buf);
    const replacement = dst.fileEntryForPath(path).?;
    try std.testing.expectEqual(source_id, replacement.id);
    try std.testing.expectEqual(source_surface, replacement.surface_id);
    // mode 갱신은 살아남은 쪽으로 재조준된다(one-shot 유실 없음). tree restore는 사라진 surface를 가리키던
    // 것이라 비운다.
    try std.testing.expectEqual(source_surface, dst.file_panel_mode_pending.?);
    try std.testing.expect(dst.file_tree_restore_surface_pending == null);
    try std.testing.expect(dst.fileEntryForSurfaceId(retired_surface) == null);
    // FP16: 살아남은 파일이 **배경 워크스페이스**에 앉으므로(merge는 dst가 보던 워크스페이스를 유지한다)
    // publish 대기 barrier는 버려진다 — 보이지 않는 파일이 화면의 입력을 삼키지 않게 한다.
    try std.testing.expect(dst.pending_dock_focus == null);
    try std.testing.expect(!dst.completePendingDockFocus(retired_surface));
    // 그 워크스페이스로 전환하면 다시 barrier를 걸고 typed ack로 승격할 수 있다.
    for (dst.tabs.items, 0..) |t, ti| {
        for (t.panes.items) |pane| {
            for (pane.terms.items) |term| {
                const e = term.file_entry orelse continue;
                if (e.id == source_id) _ = dst.switchTab(ti);
            }
        }
    }
    dst.requestDockEntryFocus(replacement);
    try std.testing.expectEqual(source_id, dst.pending_dock_focus.?.entry_id);
    try std.testing.expectEqual(source_surface, dst.pending_dock_focus.?.expected_surface_id.?);
    try std.testing.expect(dst.completePendingDockFocus(source_surface));
    try std.testing.expect(dst.focusedDockSurface() == source_surface);
    // A direct click on B supersedes the remapped A focus token. Independent mode-only A refresh
    // remains drainable but cannot move the logical/native focus back from B.
    dst.queuePendingDockFocus(replacement);
    dst.file_panel_mode_pending = source_surface;
    // 실제 클릭은 **보이는** 패널에만 온다 — B가 있는 워크스페이스로 먼저 돌아간다(FP16: focusFilePanelSurface는
    // 워크스페이스를 넘지 않는다). switchTab 자체가 보이지 않게 된 barrier를 버리므로, 클릭이 token을
    // 지운다는 것을 보려면 **전환 뒤에 다시 걸어** 둔다(안 그러면 아래 단언이 공허해진다 — code-review max).
    for (dst.tabs.items, 0..) |t, ti| {
        for (t.panes.items) |pane| {
            for (pane.terms.items) |term| {
                const e = term.file_entry orelse continue;
                if (e.surface_id == newer_surface) _ = dst.switchTab(ti);
            }
        }
    }
    dst.queuePendingDockFocus(replacement);
    try std.testing.expect(dst.pending_dock_focus != null); // 클릭 전에는 살아 있다
    try std.testing.expect(dst.focusFilePanelSurface(newer_surface));
    try std.testing.expect(dst.pending_dock_focus == null); // 클릭이 지운다
    const mode_only = dst.takeFilePanelModeAction().?;
    try std.testing.expectEqual(source_surface, mode_only.surface_id);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, mode_only.mode);
    try std.testing.expect(!dst.completePendingDockFocus(source_surface));
    try std.testing.expect(dst.focusedDockSurface() == newer_surface);
}

// host-backed(원격) Term의 Cmd+hover 회귀 가드. 이전에는 hoverCursor가 `activeSurface().core`를 직접 분류했는데,
// 원격 surface의 그 core는 **빈 placeholder**라(화면은 host가 소유) 어떤 링크도 잡히지 않았다 — 밑줄도 링크 커서도
// 무동작. 이제 host가 해석해 실어 준 RenderSnapshot.links를 조회한다(docs/link-detection.md §원격(host-backed) 세션).
// 이 테스트는 그 조회 경로와 client 정책 필터(`input.link-detection`)를 함께 고정한다.
const FakeLinkScreen = struct {
    snap: terminal.RenderSnapshot,

    fn render(ctx: *anyopaque) terminal.RenderSnapshot {
        const self: *FakeLinkScreen = @ptrCast(@alignCast(ctx));
        return self.snap;
    }
    // 이 fake는 host 연결 없이 화면 소스 계약만 흉내 낸다 — 단일 스레드 테스트라 락은 no-op으로 충분하다.
    fn lockNoop(_: *anyopaque, _: std.Io) void {}
    fn unlockNoop(_: *anyopaque, _: std.Io) void {}

    const vtable: maru.session.surface.ScreenSource.VTable = .{
        .render_snapshot = render,
        .lock = lockNoop,
        .unlock = unlockNoop,
    };
};

test "host-backed hover: host가 실어 준 링크로 밑줄과 링크 커서가 산다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // host가 해석한 링크 3종(자동 감지 web / 자동 감지 경로 / OSC 8 명시). client core는 비어 있는 상태 그대로다.
    var links = [_]terminal.ViewportLink{
        .{ .span = .{ .start = .{ .row = 0, .col = 5 }, .end = .{ .row = 0, .col = 28 }, .block = false }, .kind = .url, .scope = .web },
        .{ .span = .{ .start = .{ .row = 1, .col = 0 }, .end = .{ .row = 1, .col = 9 }, .block = false }, .kind = .file_path, .scope = .bare_relative },
        .{ .span = .{ .start = .{ .row = 2, .col = 0 }, .end = .{ .row = 2, .col = 3 }, .block = false }, .kind = .url, .scope = .osc8 },
    };
    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 40, .rows = 6 }, .links = &links } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null; // Surface.deinit은 remote를 안 건드린다(소유는 주입한 쪽).

    const rect = session.active_pane_rect;
    const cw: f64 = @floatFromInt(session.cell_width_px);
    const ch: f64 = @floatFromInt(session.cell_height_px);
    const pxOf = struct {
        fn run(base: anytype, size: f64, index: f64) f64 {
            return @as(f64, @floatFromInt(base)) + (index + 0.5) * size;
        }
    }.run;

    // 링크 위 + 수식키(Cmd=32) → pointingHand + 밑줄 span. 이게 회귀 전에는 전부 null이었다.
    const on_url_x = pxOf(rect.x, cw, 10);
    const row0_y = pxOf(rect.y, ch, 0);
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(on_url_x, row0_y, 32));
    const span = session.hoverLinkSpanFor(session.activeSurface()) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u16, 5), span.start.col);
    try std.testing.expectEqual(@as(u16, 28), span.end.col);

    // 같은 행이라도 span 밖(col 2)이면 링크가 아니다 — 범위 판정이 실제로 걸리는지.
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(pxOf(rect.x, cw, 2), row0_y, 32));
    try std.testing.expect(session.hoverLinkSpanFor(session.activeSurface()) == null);

    // 수식키가 없으면 밑줄을 띄우지 않는다(로컬과 같은 게이트 — urlModifierHeld 단일 판정).
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(on_url_x, row0_y, 0));
    try std.testing.expect(session.hoverLinkSpanFor(session.activeSurface()) == null);
}

// host는 client config를 모르므로 **최대 집합**으로 계산해 보내고, 무엇을 그릴지는 client가 정한다. 이 필터가
// 없으면 `input.link-detection = web`인 사용자에게 파일 경로 밑줄이 뜬다(로컬과 동작이 갈림).
test "host-backed hover: client가 link-detection 프리셋으로 host 목록을 거른다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    var links = [_]terminal.ViewportLink{
        .{ .span = .{ .start = .{ .row = 0, .col = 0 }, .end = .{ .row = 0, .col = 9 }, .block = false }, .kind = .url, .scope = .web },
        .{ .span = .{ .start = .{ .row = 1, .col = 0 }, .end = .{ .row = 1, .col = 9 }, .block = false }, .kind = .file_path, .scope = .bare_relative },
        .{ .span = .{ .start = .{ .row = 2, .col = 0 }, .end = .{ .row = 2, .col = 3 }, .block = false }, .kind = .url, .scope = .osc8 },
    };
    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 40, .rows = 6 }, .links = &links } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;

    const rect = session.active_pane_rect;
    const cw: f64 = @floatFromInt(session.cell_width_px);
    const ch: f64 = @floatFromInt(session.cell_height_px);
    const x = @as(f64, @floatFromInt(rect.x)) + 1.5 * cw;
    const rowY = struct {
        fn run(base: anytype, size: f64, index: f64) f64 {
            return @as(f64, @floatFromInt(base)) + (index + 0.5) * size;
        }
    }.run;

    // full(기본): 셋 다 링크로 본다.
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(x, rowY(rect.y, ch, 0), 32));
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(x, rowY(rect.y, ch, 1), 32));
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(x, rowY(rect.y, ch, 2), 32));

    // web: http(s)만. 파일 경로는 빠지고, OSC 8 명시 링크는 프리셋과 무관하게 남는다.
    session.loaded_config.config.input.link_detection = .web;
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(x, rowY(rect.y, ch, 0), 32));
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(x, rowY(rect.y, ch, 1), 32));
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(x, rowY(rect.y, ch, 2), 32));

    // osc8-only: 자동 감지는 전부 꺼지고 명시 링크만 남는다.
    session.loaded_config.config.input.link_detection = .osc8_only;
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(x, rowY(rect.y, ch, 0), 32));
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(x, rowY(rect.y, ch, 1), 32));
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(x, rowY(rect.y, ch, 2), 32));
}

// scope 비트는 client(packLinkScopes)와 host(unpackLinkScopes)가 공유하는 **wire 약속**이다. 한쪽이 비트 순서를
// 바꾸면 원격에서 엉뚱한 범위로 링크를 열게 되고(예: web만 켠 사용자에게 파일 경로가 열림), 밑줄 필터(scope 태그)와도
// 어긋난다. LinkScope enum 값이 곧 비트 위치라는 계약을 여기서 고정한다.
test "packLinkScopes: config 프리셋을 wire 비트로 굽는다(LinkScope 값 = 비트 위치)" {
    try std.testing.expectEqual(@as(u8, 0b0011_1111), AppSession.packLinkScopes(terminal.link_scopes_full));
    try std.testing.expectEqual(@as(u8, 0b0000_0001), AppSession.packLinkScopes(terminal.link_scopes_web));
    try std.testing.expectEqual(@as(u8, 0), AppSession.packLinkScopes(terminal.link_scopes_none));
    // 개별 비트 위치가 enum 값과 1:1인지(host unpackLinkScopes의 짝).
    try std.testing.expectEqual(@as(u8, 1) << @intCast(@intFromEnum(terminal.LinkScope.home_path)), AppSession.packLinkScopes(.{ .home_path = true }));
    try std.testing.expectEqual(@as(u8, 1) << @intCast(@intFromEnum(terminal.LinkScope.bare_relative)), AppSession.packLinkScopes(.{ .bare_relative = true }));
}

// 로컬(in-process) Cmd+hover 회귀 가드. host-backed 분기를 넣으면서 hoverCursor가 두 갈래가 됐으므로, 원격을
// 고치다 로컬을 깨뜨리지 않았는지 함께 고정한다. 로컬은 client core가 실제 화면을 가지므로 예전처럼 core를 직접
// 분류하고(절대 좌표 anchor), 원격 목록(RenderSnapshot.links)은 쓰지 않는다.
test "로컬 hover: client core를 직접 분류해 밑줄과 링크 커서가 뜬다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const surface = session.activeSurface();
    try std.testing.expect(surface.remote == null); // 이 세션은 in-process다(원격 분기가 아님).
    {
        surface.lockCore(session.io);
        defer surface.unlockCore(session.io);
        try surface.core.write("\x1b[2J\x1b[Hgo https://example.com/page now");
    }

    const rect = session.active_pane_rect;
    const cw: f64 = @floatFromInt(session.cell_width_px);
    const ch: f64 = @floatFromInt(session.cell_height_px);
    const on_url = @as(f64, @floatFromInt(rect.x)) + 10.5 * cw;
    const row0 = @as(f64, @floatFromInt(rect.y)) + 0.5 * ch;

    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(on_url, row0, 32));
    const span = session.hoverLinkSpanFor(session.activeSurface()) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u16, 3), span.start.col); // "go " 다음 토큰 전체가 밑줄
    try std.testing.expectEqual(@as(u16, 26), span.end.col);

    // 링크 밖·수식키 없음은 밑줄 없음(로컬 게이트도 그대로).
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(@as(f64, @floatFromInt(rect.x)) + 1.5 * cw, row0, 32));
    try std.testing.expect(session.hoverLinkSpanFor(session.activeSurface()) == null);
    try std.testing.expectEqual(CursorKind.text, session.hoverCursor(on_url, row0, 0));
    try std.testing.expect(session.hoverLinkSpanFor(session.activeSurface()) == null);
}

// host-backed(원격) Term의 **버튼 없는 motion 리포팅(DECSET 1003)** 회귀 가드. 클릭 리포팅은 관측(observation)의
// 트래킹 상태를 보도록 이관됐는데 motion 경로만 placeholder core를 읽고 있었다 — placeholder는 항상 `.none`이라
// 원격 세션에서 1003을 켠 앱(vim/tmux hover 등)에 motion이 통째로 안 갔다. 관측 bool이 "켜짐" 여부만 실어
// 1003을 가를 수 없었던 것이 근본 원인이라, 모드(ordinal)를 실어 보내고 두 경로가 그 모드로 판정한다.
test "host-backed motion 리포팅: 관측 모드가 any(1003)면 motion을 보낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 40, .rows = 6 } } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;

    const term = session.activePane().terms.items[session.activePane().active_term];
    term.rt.observation.availability = .current;
    const rect = session.active_pane_rect;
    const x = @as(f64, @floatFromInt(rect.x)) + 5.5 * @as(f64, @floatFromInt(session.cell_width_px));
    const y = @as(f64, @floatFromInt(rect.y)) + 2.5 * @as(f64, @floatFromInt(session.cell_height_px));

    // 트래킹 꺼짐 → motion 무시(dedup 상태도 비운다).
    term.rt.observation.mouse_tracking = false;
    term.rt.observation.mouse_tracking_mode = @intFromEnum(terminal.MouseTracking.none);
    session.mouseMoved(x, y, 0);
    try std.testing.expect(session.last_motion_cell == null);

    // 클릭 트래킹(1000)만 켜짐 → motion은 여전히 안 보낸다(1000만 켠 앱에 motion을 쏟으면 오작동).
    term.rt.observation.mouse_tracking = true;
    term.rt.observation.mouse_tracking_mode = @intFromEnum(terminal.MouseTracking.normal);
    session.mouseMoved(x, y, 0);
    try std.testing.expect(session.last_motion_cell == null);

    // any-event(1003) → motion을 보낸다. 예전에는 placeholder core(.none)를 읽어 여기서도 null이었다.
    term.rt.observation.mouse_tracking_mode = @intFromEnum(terminal.MouseTracking.any);
    session.mouseMoved(x, y, 0);
    const reported = session.last_motion_cell orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u16, 5), reported.col);
    try std.testing.expectEqual(@as(u16, 2), reported.row);
}

// host-backed 스크롤바 회귀 가드. 스크롤바 thumb은 스크롤백 길이와 view offset으로 계산하는데, 예전 호출처들은
// `core.scrollbackLen()`을 직접 읽어 host-backed에서 항상 0이었다(placeholder) — 원격 세션에 스크롤백이 아무리
// 쌓여도 스크롤바가 뜨지 않았다. 이제 host가 ScreenMeta로 실어 준 값이 RenderSnapshot의 같은 필드로 들어와
// 로컬/원격이 한 경로를 쓴다.
test "host-backed 스크롤바: host가 실어 준 스크롤 상태로 thumb이 그려진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 40, .rows = 10 } } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;

    // 스크롤백 없음 → thumb 없음(스크롤바 미표시).
    try std.testing.expect(AppSession.scrollbarThumbGeom(
        AppSession.scrollStateOf(surface).scrollback_len,
        AppSession.scrollStateOf(surface).view_offset,
        session.cell_height_px,
        session.active_pane_rect.h,
    ) == null);

    // host가 스크롤백 500행·offset 120을 실어 주면 그대로 반영된다(예전엔 placeholder라 0이었다).
    fake.snap.scrollback_len = 500;
    fake.snap.view_offset = 120;
    const state = AppSession.scrollStateOf(surface);
    try std.testing.expectEqual(@as(usize, 500), state.scrollback_len);
    try std.testing.expectEqual(@as(usize, 120), state.view_offset);
    const geom = AppSession.scrollbarThumbGeom(state.scrollback_len, state.view_offset, session.cell_height_px, session.active_pane_rect.h) orelse
        return error.TestUnexpectedResult;
    try std.testing.expect(geom.h > 0); // thumb이 실제로 그려질 크기를 가진다
}

// host-backed 벨 회귀 가드. host core가 BEL을 파싱해도 client로 나갈 통로가 없어 원격 세션에서 벨(소리·시각 flash·
// Dock 배지)이 통째로 무동작이었다. 이제 host가 관측에 누적 카운터를 실어 보내고 client가 delta로 판정한다.
// 소비형 bool이 아니라 카운터인 이유와, host live-upgrade로 카운터가 리셋될 때 가짜 벨이 울리지 않아야 한다는
// 계약을 함께 고정한다.
test "host-backed 벨: 관측 카운터 증가로 울리고 리셋은 조용히 재동기화한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 20, .rows = 5 } } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;
    const term = session.activePane().terms.items[session.activePane().active_term];
    term.rt.observation.availability = .current;
    session.audible_bell = true;

    // 카운터 변화 없음 → 안 울린다.
    _ = session.takeBell(); // 이전 상태 비우기
    session.dispatchBell();
    try std.testing.expect(!session.takeBell());

    // host가 벨을 실어 보내면(1회) 울린다 — 예전에는 placeholder core라 통째로 무동작이었다.
    term.rt.observation.bell_count = 1;
    session.dispatchBell();
    try std.testing.expect(session.takeBell());

    // 같은 값이 유지되면 다시 울리지 않는다(full-state 관측이 반복 전송돼도 중복 벨 금지).
    session.dispatchBell();
    try std.testing.expect(!session.takeBell());

    // 여러 번 울린 뒤 한 번에 관측이 오면 1회로 합친다(로컬 bool 합침과 같은 동작).
    term.rt.observation.bell_count = 5;
    session.dispatchBell();
    try std.testing.expect(session.takeBell());

    // host live-upgrade(exec)로 카운터가 0에서 다시 시작 → **가짜 벨을 울리지 않고** 조용히 맞춘다.
    term.rt.observation.bell_count = 0;
    session.dispatchBell();
    try std.testing.expect(!session.takeBell());
    // 재동기화 후 새 벨은 정상 동작한다.
    term.rt.observation.bell_count = 1;
    session.dispatchBell();
    try std.testing.expect(session.takeBell());
}

// host-backed OSC 52 회귀 가드. host core가 클립보드 요청을 파싱해도 client로 나갈 통로가 없어 원격 세션에서
// 클립보드 쓰기/읽기가 통째로 무동작이었다. 이제 host가 관측 seq로 요청을 알리고(write 텍스트만 RPC로 뺀다),
// **정책 판정과 OS 접근은 client가 그대로 소유**한다(§기능 배치 규칙). read 응답은 PTY 바이트라 기존 입력
// 경로를 타므로 추가 왕복이 없다.
test "host-backed OSC 52 read: 관측 seq로 요청을 받고 정책은 client가 판정한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 20, .rows = 5 } } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;
    const term = session.activePane().terms.items[session.activePane().active_term];
    term.rt.observation.availability = .current;

    // 요청 없음 → false.
    try std.testing.expect(!session.takeClipboardReadRequest());

    // host가 read 요청을 알리고 target을 실어 준다. 기본 정책은 deny라 **클립보드를 읽지 않는다**(탈취 방지).
    session.loaded_config.config.osc52.read = .deny;
    term.rt.observation.clipboard_read_seq = 1;
    try term.rt.observation.clipboard_read_target.appendSlice(allocator, "p");
    try std.testing.expect(!session.takeClipboardReadRequest());

    // 같은 seq는 재트리거하지 않는다(full-state 관측이 반복 전송돼도 중복 요청 금지).
    session.loaded_config.config.osc52.read = .allow;
    try std.testing.expect(!session.takeClipboardReadRequest());

    // 새 요청 + allow → true(Swift가 클립보드를 읽어 provideClipboardRead로 응답), target도 캡처된다.
    term.rt.observation.clipboard_read_seq = 2;
    try std.testing.expect(session.takeClipboardReadRequest());
    try std.testing.expectEqualStrings("p", session.clipboard_read_target_buf.items);

    // host live-upgrade(exec)로 seq가 0에서 재시작 → 요청으로 오인하지 않는다.
    term.rt.observation.clipboard_read_seq = 0;
    try std.testing.expect(!session.takeClipboardReadRequest());
}

// 리뷰가 잡은 재접속 결함의 회귀 가드: host의 누적 seq는 client보다 오래 살아서, 재접속하면 이미 지나간 값이
// 곧바로 "증가"로 보인다. 기준선을 안 잡으면 지난 벨이 울리고 **지난 OSC 52 read가 재생돼 사용자 클립보드가
// 복원된 셸에 주입**된다. 첫 관측은 기준선만 잡고 발화하지 않아야 한다.
test "host-backed 재접속: 첫 관측은 기준선만 잡고 지난 요청을 재생하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 20, .rows = 5 } } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;
    const term = session.activePane().terms.items[session.activePane().active_term];
    term.rt.observation.availability = .current;
    session.audible_bell = true;
    session.loaded_config.config.osc52.read = .allow;

    // 재접속 상황: host는 이미 벨 12회·read 5회를 누적한 상태다. 첫 관측이 그대로 들어온다.
    term.rt.observation.bell_count = 12;
    term.rt.observation.clipboard_read_seq = 5;
    term.rt.observation.clipboard_write_seq = 9;

    _ = session.takeBell();
    session.dispatchBell();
    try std.testing.expect(!session.takeBell()); // 지난 벨을 울리지 않는다
    try std.testing.expect(!session.takeClipboardReadRequest()); // 클립보드를 읽지 않는다(유출 금지)
    try std.testing.expectEqual(@as(usize, 0), session.pendingClipboard().len); // 지난 복사를 재생하지 않는다

    // 기준선을 잡은 뒤의 **새** 요청은 정상 동작한다.
    term.rt.observation.bell_count = 13;
    session.dispatchBell();
    try std.testing.expect(session.takeBell());
    term.rt.observation.clipboard_read_seq = 6;
    try std.testing.expect(session.takeClipboardReadRequest());
}

// browser 전용 chrome(주소창 밴드)이 파일/markdown web Term에 걸리지 않는다는 것을 `isBrowserTerm` 한 곳으로
// 고정한다. FP16이 파일 entry를 Term으로 옮기면 `.html`/`.pdf` 파일 Term이 격리 config 때문에
// `web_panel_kind == .browser`를 갖게 되는데, 그때 이 술어에 조건 하나만 더하면 모든 소비처가 함께 고쳐진다
// (docs/file-panel.md §8). 인라인 비교가 흩어져 있으면 그 확장에서 반드시 한 곳을 놓친다.
test "browser 전용 판정은 isBrowserTerm 하나가 소유한다 — markdown web Term은 주소창 밴드가 없다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    const pane = session.activePane();
    try session.newWebTermInActivePane(.markdown);
    const md = pane.activeTerm();
    try std.testing.expect(md.kind == .web and md.web_panel_kind == .markdown);
    try std.testing.expect(!AppSession.isBrowserTerm(md)); // 술어가 갈라낸다

    try session.newWebTermInActivePane(.browser);
    const browser = pane.activeTerm();
    try std.testing.expect(AppSession.isBrowserTerm(browser));

    // 소비처 검증: 주소창 밴드는 browser에만 top inset을 더한다(bar_h vs 2*bar_h).
    const bar_h = session.paneBarHeightPx();
    try std.testing.expect(bar_h > 0);

    var surfaces: std.ArrayList(web_panel_layout.SurfaceLayout) = .empty;
    defer surfaces.deinit(allocator);
    try session.collectWebSurfaces(&surfaces);

    var md_rect: ?web_panel_layout.Rect = null;
    var browser_rect: ?web_panel_layout.Rect = null;
    for (surfaces.items) |s| {
        if (s.surface_id == md.surfaceId()) md_rect = s.content_rect;
        if (s.surface_id == browser.surfaceId()) browser_rect = s.content_rect;
    }
    try std.testing.expect(md_rect != null and browser_rect != null);
    // 같은 pane·같은 leaf라 밴드 유무만 차이 → browser 본문이 정확히 bar_h만큼 더 내려간다.
    try std.testing.expectEqual(md_rect.?.y + bar_h, browser_rect.?.y);
    try std.testing.expectEqual(md_rect.?.h - bar_h, browser_rect.?.h);

    // 활성 browser 판정도 같은 술어를 공유한다(nav 단축키 게이트).
    try std.testing.expectEqual(browser.surfaceId(), session.activeWebSurfaceId());
    session.focusTerm(1); // markdown을 활성으로
    try std.testing.expectEqual(@as(u64, 0), session.activeWebSurfaceId());
}

// FP16b 선행(§10 B-1): 파일 entry 조회 창구가 저장 구조(그룹 트리)를 감추는지 고정한다. FP16b가 소유를 `Term`으로
// 옮길 때 이 테스트는 **그대로 통과해야 한다** — 통과하지 못하면 API가 저장 위치를 새고 있다는 뜻이다.
// 다중 그룹으로 세팅하는 이유: 이터레이터가 그룹 경계를 넘는지(한 그룹만 보고 끝내지 않는지) 잡기 위해서다.
test "FP16b B-1: 파일 entry 조회 API가 그룹 구조를 감춘다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    const a = try session.openFileTermInActivePane("/tmp/b1-a.md", .markdown);
    const a_id = a.term.file_entry.?.id;
    _ = try session.openFileTermInActivePane("/tmp/b1-b.md", .markdown);
    // 두 번째 워크스페이스에 열어 이터레이터가 **탭 경계**를 넘는지 검증한다(FP16에서 그룹 경계를 대신한다).
    _ = try session.newTab();
    const c = try session.openFileTermInActivePane("/tmp/b1-c.md", .markdown);
    const c_id = c.term.file_entry.?.id;

    // ① 이터레이터는 그룹과 무관하게 창의 전 entry를 준다.
    var seen_a = false;
    var seen_b = false;
    var seen_c = false;
    var count: usize = 0;
    var it = session.fileEntries();
    while (it.next()) |entry| {
        count += 1;
        if (std.mem.eql(u8, entry.path, "/tmp/b1-a.md")) seen_a = true;
        if (std.mem.eql(u8, entry.path, "/tmp/b1-b.md")) seen_b = true;
        if (std.mem.eql(u8, entry.path, "/tmp/b1-c.md")) seen_c = true;
    }
    try std.testing.expectEqual(session.fileEntryCount(), count);
    try std.testing.expect(seen_a and seen_b and seen_c);

    // ② const 변형도 같은 집합을 본다(순수 술어용).
    var const_count: usize = 0;
    var cit = session.fileEntriesConst();
    while (cit.next()) |_| const_count += 1;
    try std.testing.expectEqual(count, const_count);

    // ③ 경로·EntryId 조회는 배치를 몰라도 정확한 entry를 준다 — 다른 워크스페이스에 있는 c까지.
    const by_path = session.fileEntryForPath("/tmp/b1-c.md").?;
    try std.testing.expectEqualStrings("/tmp/b1-c.md", by_path.path);
    const by_id = session.fileEntryForId(c_id).?;
    try std.testing.expectEqual(by_path, by_id); // 같은 주소
    const a_entry = session.fileEntryForId(a_id).?;
    try std.testing.expectEqualStrings("/tmp/b1-a.md", a_entry.path);

    // ④ 없는 키는 null(창 전체를 뒤진 뒤).
    try std.testing.expect(session.fileEntryForPath("/tmp/b1-missing.md") == null);
    try std.testing.expect(session.fileEntryForId(0) == null);

    // ⑤ 반환은 포인터라 호출처가 그룹 인덱싱 없이 바로 변경할 수 있다(mutation 예약 경로가 이 형태를 쓴다).
    // 검증도 그룹 인덱싱이 아니라 **같은 API 재조회**로 한다 — 내부 배치를 단언하면 이 테스트가 감추려는 바로 그
    // 구조에 다시 의존하게 되고, FP16b가 소유를 Term으로 옮길 때 통과하지 못한다.
    by_path.mutation_pending_id = 42;
    try std.testing.expectEqual(@as(u64, 42), session.fileEntryForPath("/tmp/b1-c.md").?.mutation_pending_id);
}

// FP16 §5.0 왕복 게이트: 파일 Term이 `pane` 줄의 `file-term` 필드로 나갔다가 **같은 자리**로 돌아온다.
// 브라우저가 섞인 pane에서 persisted 인덱스가 런타임 인덱스와 갈리는 것이 이 포맷의 핵심 제약이라, 그
// 조합을 실제 세션으로 왕복시킨다.
test "FP16 영속: 파일 Term이 pane file-term으로 왕복하고 브라우저는 자리를 비운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // pane: [terminal, browser, alpha.md, beta.html] — persisted 시퀀스는 [terminal, alpha, beta]다.
    _ = try session.newWebTermInActivePane(.browser);
    _ = try session.openFileTermInActivePane("/tmp/fp16-persist-alpha.md", .markdown);
    _ = try session.openFileTermInActivePane("/tmp/fp16-persist-beta.html", .html);
    session.assignDockSurfaceIds();
    session.fileEntryForPath("/tmp/fp16-persist-alpha.md").?.mode = .source_edit;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const win = try session.captureWorkspaceWindow(arena.allocator(), false, null);
    const pane_model = win.tabs[0].panes[0];
    try std.testing.expectEqual(@as(usize, 2), pane_model.file_terms.len);
    try std.testing.expectEqual(@as(usize, 1), pane_model.surfaces.len); // 터미널 하나만 PTY surface
    // 브라우저는 미영속이라 자리를 차지하지 않는다 — alpha가 1, beta가 2다.
    try std.testing.expectEqual(@as(usize, 1), pane_model.file_terms[0].index);
    try std.testing.expectEqual(@as(usize, 2), pane_model.file_terms[1].index);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, pane_model.file_terms[0].mode);
    // 활성(beta, 런타임 3)은 persisted 2로 remap된다.
    try std.testing.expectEqual(@as(usize, 2), pane_model.active_term);

    // 텍스트 왕복까지 태운다 — 필드 문법·self-delimiting 경로가 실제로 되돌아오는지가 요점이다.
    const windows = [_]maru.session.workspace.Window{win};
    const text = try maru.session.workspace.serialize(allocator, .{ .windows = &windows });
    defer allocator.free(text);
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, text, "file-term=\""));
    try std.testing.expect(std.mem.indexOf(u8, text, "dock-entry=\"") == null);
    var parsed = try maru.session.workspace.parse(allocator, text);
    defer parsed.deinit();
    const round = parsed.workspace.windows[0].tabs[0].panes[0];
    try std.testing.expectEqual(@as(usize, 2), round.file_terms.len);
    try std.testing.expectEqualStrings("/tmp/fp16-persist-alpha.md", round.file_terms[0].path);
    try std.testing.expectEqualStrings("/tmp/fp16-persist-beta.html", round.file_terms[1].path);

    // 복원: 파일 Term이 persisted 자리대로 되살아난다(터미널 0, alpha 1, beta 2).
    // 라이브 편집 mode는 복원을 fail-close하므로(§3.2 종료 보호) 적용 전에 읽기로 되돌린다 — 텍스트에는
    // 이미 source_edit이 실려 있어 왕복 검증에는 영향이 없다.
    session.fileEntryForPath("/tmp/fp16-persist-alpha.md").?.mode = .read;
    try session.applyWorkspaceWindow(parsed.workspace.windows[0]);
    const pane = session.activePane();
    try std.testing.expectEqual(@as(usize, 3), pane.terms.items.len);
    try std.testing.expect(pane.terms.items[0].file_entry == null); // 터미널
    try std.testing.expectEqualStrings("/tmp/fp16-persist-alpha.md", pane.terms.items[1].file_entry.?.path);
    try std.testing.expectEqualStrings("/tmp/fp16-persist-beta.html", pane.terms.items[2].file_entry.?.path);
    try std.testing.expectEqual(dock_panel.Mode.source_edit, pane.terms.items[1].file_entry.?.mode);
    try std.testing.expectEqual(@as(usize, 2), pane.active_term);
    try std.testing.expectEqual(@as(usize, 2), session.fileEntryCount());
}

// ── FP16 닫기 계약 회귀 가드 ────────────────────────────────────────────────────────────────────
// 이 세 테스트는 5·6차 code-review max가 잡은 **크래시·영구 차단** 계열의 재발 가드다. 셋 다 그 리뷰
// 전에는 통과했을 코드가 없다(각각 UAF·무한루프·못 닫는 pane을 냈다).

test "FP16 닫기: 창의 마지막 Term인 파일 탭은 구조를 파괴하지 않고 종료 latch만 건다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // pane을 [파일] 하나로 만든다(터미널을 닫아).
    const opened = try session.openFileTermInActivePane("/tmp/fp16-last-term.md", .markdown);
    session.assignDockSurfaceIds();
    const sid = opened.term.file_entry.?.surface_id;
    const pane = session.activePane();
    while (pane.terms.items.len > 1) {
        const victim = for (pane.terms.items, 0..) |t, i| {
            if (t.file_entry == null) break i;
        } else break;
        session.closeTermAt(0, pane, victim);
    }
    try std.testing.expectEqual(@as(usize, 1), pane.terms.items.len);

    try std.testing.expect(session.closeFilePanelSurfaceNow(sid));
    // **구조는 그대로다** — Term을 빼면 pane이 Term 0개가 되어 모델 불변식이 깨지고, latch가 그 직후
    // 해제된 대표 surface에 쓴다(5차 리뷰가 잡은 UAF). 정리는 deinit이 한다.
    try std.testing.expectEqual(@as(usize, 1), session.activePane().terms.items.len);
    try std.testing.expect(session.ended_seen); // 창이 닫힌다
}

test "FP16 닫기: 다른 파일이 종료를 막으면 마지막 Term close는 아무것도 안 바꾸고 거부한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 워크스페이스 둘: 0번에 지킬 파일(dirty), 1번에 닫을 파일.
    const guarded = try session.openFileTermInActivePane("/tmp/fp16-guard.md", .markdown);
    session.assignDockSurfaceIds();
    guarded.term.file_entry.?.dirty = true;
    _ = try session.newTab();
    const victim = try session.openFileTermInActivePane("/tmp/fp16-victim.md", .markdown);
    session.assignDockSurfaceIds();
    const victim_sid = victim.term.file_entry.?.surface_id;

    // 창 전체에 Term이 둘 이상이라 마지막-Term 분기는 안 탄다 — 정상 close.
    try std.testing.expect(session.closeFilePanelSurfaceNow(victim_sid));
    try std.testing.expect(!session.ended_seen);
    try std.testing.expect(session.fileEntryForPath("/tmp/fp16-guard.md") != null);
}

test "FP16 닫기: 파괴 전 스냅샷은 한 번만 요청하고, 답이 없어도 두 번째 시도를 막지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // `.text`의 기본 mode는 source_edit이다 — 손도 안 댄 이 탭 하나가 그 pane을 영영 못 닫게 하면 안 된다.
    const opened = try session.openFileTermInActivePane("/tmp/fp16-clean.py", .text);
    session.assignDockSurfaceIds();
    const entry = opened.term.file_entry.?;
    try std.testing.expectEqual(dock_panel.Mode.source_edit, entry.mode);
    try std.testing.expect(!entry.close_snapshot_requested);

    // 1차: 스냅샷을 실제로 요청하고 close를 보류한다(§3.2 two-phase의 scope판).
    try std.testing.expect(session.syncDirtyBeforeScopeClose(.term_or_pane, .pane));
    try std.testing.expect(entry.close_snapshot_requested);
    try std.testing.expect(entry.dirty_sync_pending);

    // 2차: once-only 래치 때문에 다시 요청하지 않는다.
    try std.testing.expect(!session.syncDirtyBeforeScopeClose(.term_or_pane, .pane));

    // 그리고 답이 안 왔어도 그 파일이 close를 막지 않는다 — 여기서 막으면 브릿지가 죽은 순간
    // 그 pane·워크스페이스가 영원히 안 닫힌다(code-review max).
    try std.testing.expect(!AppSession.termHasProtectedFilePanel(opened.term));

    // 스냅샷이 **돌아와** dirty가 서면 다시 정상적으로 막는다.
    entry.dirty = true;
    try std.testing.expect(AppSession.termHasProtectedFilePanel(opened.term));
}

// §6c host-backed 검색 회귀 가드. 원격에서만 증분 검색(타이핑)이 매치로 스크롤되지 않던 결함 — find.zig의
// recomputeFind가 그룹 내부에서 free 함수 scrollToCurrentMatch를 직접 불러, app_session facade에만 있던 원격
// 분기를 우회했다. 분기를 find.zig 단일 출처로 옮겼으므로 두 경로(타이핑·Enter) 모두 host 스크롤을 요청해야 한다.
test "host-backed find: 증분 검색과 네비가 둘 다 host 스크롤을 요청한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 6,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(800, 600, 1000);

    var fake = FakeLinkScreen{ .snap = .{ .size = .{ .cols = 40, .rows = 6 } } };
    const surface = session.activeSurface();
    surface.remote = .{ .ctx = &fake, .vtable = &FakeLinkScreen.vtable };
    defer surface.remote = null;

    session.dispatchAppAction(.toggle_find);
    for ("MARUFIND") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });

    // 타이핑(증분 검색): 재검색과 "첫 매치로 스크롤"이 둘 다 host에 요청된다 — in-process와 같은 동작.
    try std.testing.expect(session.remote_find_dirty);
    try std.testing.expect(session.remote_find_scroll_pending);

    // Enter(네비)도 같은 단일 출처를 거친다.
    session.remote_find_scroll_pending = false;
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.remote_find_scroll_pending);
}

// host 응답 span을 언제 그려도 되는지의 정책. host는 scroll 직후 **스크롤된 화면 기준**으로 span을 계산해
// 응답하는데(runtime_manager.findOp), client는 그 스크롤 delta를 아직 못 받았을 수 있다. 두 좌표계를 합성하면
// 엉뚱한 줄이 하이라이트된다 — 사용자가 본 "이전 하이라이트가 남는" 증상의 정체다.
test "host-backed find: span은 client 화면과 view_offset이 맞을 때만 적용한다" {
    // 정합 — 적용한다.
    try std.testing.expect(remoteFindSpansApplicable(120, 120));
    // 어긋남(host가 스크롤했고 그 delta가 아직 client에 없다) — 적용하지 않는다(이전 하이라이트 유지).
    try std.testing.expect(!remoteFindSpansApplicable(120, 0));
    try std.testing.expect(!remoteFindSpansApplicable(0, 120));
    // 구 host 데몬은 이 값을 안 보낸다 — 대조 근거가 없으므로 종전대로 즉시 적용한다.
    try std.testing.expect(remoteFindSpansApplicable(null, 120));
}

// 손 확인에서 나온 결함: 소스 컨트롤 뷰에서 행을 클릭하면 **폴더 선택 다이얼로그**가 떴다. 탐색기 전용 클릭 처리가
// `dockVisible()`로만 막혀 있어 좌표가 같은 rect 안이라는 이유로 그대로 탔기 때문이다(뷰가 달라 트리 행은 화면에
// 없는데도). 트리 포커스도 같이 뺏겼는데, 이는 setDockView가 뷰 전환 시 그 포커스를 놓는 것과 모순이다.
test "도크 뷰: 탐색기 아닌 뷰의 클릭은 폴더 선택·트리 포커스로 새지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    const launcher = session.filePanelDockControlRect() orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    try std.testing.expect(session.dockVisible());
    _ = session.takeFilePanelPickRequest();

    const tree_content = session.dockGeometry().tree_content;
    const x: f64 = @floatFromInt(tree_content.x + tree_content.w / 2); // 좌측 divider grab band 밖
    const y: f64 = @floatFromInt(tree_content.y + 1);

    session.setDockView(.source_control);
    session.mouse(1, x, y, 0, 0);
    try std.testing.expect(!session.takeFilePanelPickRequest()); // 폴더 다이얼로그 금지
    try std.testing.expect(!session.fileTreeFocused()); // 트리 포커스도 안 뺏는다
    session.mouse(1, x, y, 0, 2); // 우클릭 배경 메뉴(새 폴더 등)도 탐색기 조작이라 안 뜬다
    try std.testing.expect(!session.chrome_host.context_menu.open);
    try std.testing.expect(!session.file_tree_background_menu);

    // 휠은 탐색기 스크롤 상태를 건드리지 않는다(안 보이는 목록이 움직이면 돌아왔을 때 위치가 어긋난다).
    session.file_tree_scroll_rows = 0;
    session.scrollWheel(-600, 0, false, x, y);
    try std.testing.expectEqual(@as(usize, 0), session.file_tree_scroll_rows);
    // 탐색기 행 수로 만든 스크롤바도 다른 뷰에는 없다(그리기·드래그 양쪽).
    try std.testing.expect(session.computeFileTreeScrollbarGeometry() == null);

    // 같은 좌표라도 탐색기로 돌아오면 원래 동작이 그대로다(게이트가 기능을 죽인 게 아니라 뷰로 가른 것).
    session.setDockView(.explorer);
    session.mouse(1, x, y, 0, 0);
    try std.testing.expect(session.takeFilePanelPickRequest());
}

// [code-review max] diff Term은 persisted 시퀀스에 **자리를 만들지 않는다**. writer에서만 빼면 이미 부여된 index가
// 줄어든 총계와 어긋나 복원 시 `index >= total`로 그 창 전체가 fail-close된다(터미널·파일 탭이 통째로 사라진다).
test "captureWorkspaceTab: diff Term은 index를 차지하지 않는다(복원 fail-close 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();

    // [term0, diff, markdown] — diff가 가운데라 뒤 파일 Term의 index가 밀린다(그게 결함의 조건이었다).
    _ = try session.openFileTermInActivePane("/tmp/diff-capture.zig", .diff);
    _ = try session.openFileTermInActivePane("/tmp/diff-capture.md", .markdown);
    const pane = session.activePane();
    try std.testing.expectEqual(@as(usize, 3), pane.terms.items.len);

    const wtab = try session.captureWorkspaceTab(arena.allocator(), session.activeTab());
    const wpane = wtab.panes[0];
    // diff는 빠지고 markdown만 남는다.
    try std.testing.expectEqual(@as(usize, 1), wpane.file_terms.len);
    try std.testing.expectEqualStrings("/tmp/diff-capture.md", wpane.file_terms[0].path);
    // **핵심**: 남은 index와 active_term이 줄어든 총계 안에 든다(reader의 validatePaneFileTerms 조건).
    const total = wpane.surfaces.len + wpane.file_terms.len;
    try std.testing.expect(wpane.file_terms[0].index < total);
    try std.testing.expect(wpane.active_term < total);
}

// [code-review max] 유일성 키는 `(경로, kind, base)`다(docs/editor-surface.md §3.5). 경로만으로 조회하면 소스 컨트롤
// 행 클릭이 이미 열린 markdown Term을 재사용해 **diff가 영영 안 열리고**, 반대로 탐색기에서 그 파일을 열면 diff Term이
// 활성화된다. 둘 다 사용자가 누른 것과 다른 것을 보여 준다.
test "diff Term과 파일 Term은 같은 경로로 공존한다(유일성 키에 kind가 든다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const path = "/tmp/same-path.md";
    const md = try session.openFileTermInActivePane(path, .markdown);
    const diff = try session.openFileTermInActivePane(path, .diff);
    try std.testing.expect(md.term != diff.term); // 서로를 빼앗지 않는다

    // 탐색기 경로 조회는 diff를 건너뛴다 — 그러지 않으면 파일을 열 때 diff Term이 활성화된다.
    try std.testing.expectEqual(md.term, session.fileTermForPath(path).?);
    // 반대로 diff 조회는 base까지 본다: 같은 경로의 다른 base는 다른 Term이다.
    diff.term.file_entry.?.diff_base = .staged;
    try std.testing.expectEqual(diff.term, session.diffTermFor(path, .staged).?);
    try std.testing.expect(session.diffTermFor(path, .unstaged) == null);
}

// [손 확인] 목록이 뷰를 껐다 켜야만 갱신되던 것을 감시로 바꿨다. 폴링이 아니라 `.git` 감시인 이유: `git add`는
// 작업트리를 안 건드리고 index만 바꿔 작업트리 감시로는 안 잡힌다. 그 경로가 감시 목록에 실제로 실리는지,
// `.git` 이벤트가 목록 갱신 신호로만 쓰이는지를 못박는다.
test "소스 컨트롤: 저장소의 .git을 감시 목록에 올리고 그 이벤트로 목록을 다시 읽는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.ensureGitWatch("/repo/one");
    try std.testing.expectEqualStrings("/repo/one/.git", session.peekFileTreeWatchRoot().?);
    const taken = session.takeFileTreeWatchRoot().?;
    defer allocator.free(taken);
    try std.testing.expectEqualStrings("/repo/one/.git", taken);
    // 같은 저장소는 다시 요청하지 않는다(이벤트마다 stream을 재구성하지 않게).
    session.ensureGitWatch("/repo/one");
    try std.testing.expect(session.peekFileTreeWatchRoot() == null);
    // 저장소가 바뀌면 새로 요청한다.
    session.ensureGitWatch("/repo/two");
    try std.testing.expectEqualStrings("/repo/two/.git", session.peekFileTreeWatchRoot().?);

    // `.git` 안쪽 경로만 git 신호다 — 이름이 비슷한 작업트리 파일(.gitignore)을 신호로 오인하면 안 된다.
    try std.testing.expect(AppSession.isGitInternalPath("/repo/one/.git/index"));
    try std.testing.expect(AppSession.isGitInternalPath("/repo/one/.git"));
    try std.testing.expect(!AppSession.isGitInternalPath("/repo/one/.gitignore"));
    try std.testing.expect(!AppSession.isGitInternalPath("/repo/one/src/main.zig"));
}

// [손 확인] "첫 파일은 열리는데 두 번째가 안 열린다". **좌표 클릭부터** 그대로 태워 재현한다 — 세션 API를 직접
// 부르는 것으로는 히트테스트·라우팅 결함이 안 잡힌다.
test "소스 컨트롤: 두 번째 행 클릭도 diff를 연다(좌표 경로)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    _ = try session.resize(1400, 900, 1000);

    // 도크를 열고 소스 컨트롤 뷰로.
    const launcher = session.filePanelDockControlRect() orelse return error.MissingDockLauncher;
    session.mouse(1, @floatFromInt(launcher.x + 1), @floatFromInt(launcher.y + 1), 0, 0);
    session.setDockView(.source_control);

    // 검증 대상은 좌표→행 매핑과 "두 번째 클릭도 diff Term을 연다"이지 git 실행이 아니다. 그런데 diff Term을
    // 열면 `requestDiffContent`가 백그라운드 `diffWorker`를 띄우고, 그 스레드는 **detach라 테스트가 기다릴 수
    // 없다**. 테스트 함수가 반환할 때 워커가 아직 `git show` 중이면 그 argv 버퍼가 leak으로 판정돼 테스트가
    // ABRT로 죽는다(제품 코드는 refcount라 늦게 끝나도 안전하게 회수된다). 10회 반복에서 3/3 재현했다.
    //
    // backend를 미리 만들고 `shutting_down`을 세워 `submitDiff`가 워커를 **띄우지 않게** 한다. 실제 git
    // 프로세스를 fork하고 기다리는 것보다 빠르고, 환경(git 설치 여부·PATH)에 의존하지 않는다.
    // PATH를 비우는 방법은 통하지 않는다 — `git_locate`가 PATH 뒤에 `fallback_dirs`(/usr/bin 등)를 훑는다.
    session.git_backend = try git_backend_mod.Backend.init(allocator, session.io);
    session.git_backend.?.state.?.shutting_down = true;

    // 실제 git 없이 목록만 채운다(클릭 경로 검증이 목적).
    session.git_result = .{
        .status = try allocator.dupe(u8, "# branch.head main\n1 .M N... 1 2 3 a b one.txt\n1 .M N... 1 2 3 a b two.txt\n"),
        .numstat_staged = try allocator.dupe(u8, ""),
        .numstat_worktree = try allocator.dupe(u8, "1\t0\tone.txt\n2\t0\ttwo.txt\n"),
        .ok = true,
    };

    const rect = session.dockGeometry().tree_content;
    const x: f64 = @floatFromInt(rect.x + rect.w / 2);
    const row_y = struct {
        fn at(s: *AppSession, r: u32, top: u32) f64 {
            return @floatFromInt(top + r * s.cell_height_px + 1);
        }
    }.at;
    // 목록이 읽힌 저장소를 기억시켜 둔다(실제로는 refreshGitStatus가 한다). 이게 없으면 클릭이 조용히 무시된다.
    session.rememberGitRepo("/repo");

    // 0=브랜치 헤더, 1=섹션 헤더, 2=one.txt, 3=two.txt
    var rows_buf: [16]scm_view.Row = undefined;
    var scratch: [std.fs.max_path_bytes]u8 = undefined;
    try std.testing.expect(session.scmRowAt(x, row_y(session, 0, rect.y), &rows_buf, &scratch) == null); // 헤더는 행이 아니다
    try std.testing.expectEqualStrings(
        "one.txt",
        session.scmRowAt(x, row_y(session, 2, rect.y), &rows_buf, &scratch).?.file.path,
    );
    try std.testing.expectEqualStrings(
        "two.txt",
        session.scmRowAt(x, row_y(session, 3, rect.y), &rows_buf, &scratch).?.file.path,
    );

    session.mouse(1, x, row_y(session, 2, rect.y), 0, 0);
    session.mouse(1, x, row_y(session, 3, rect.y), 0, 0);

    var diffs: usize = 0;
    var it = session.fileEntries();
    while (it.next()) |entry| {
        if (entry.kind == .diff) diffs += 1;
    }
    // **두 번째 클릭도 열려야 한다** — 첫 diff가 활성이 된 뒤 저장소를 다시 구하면 여기서 1이 된다.
    try std.testing.expectEqual(@as(usize, 2), diffs);

    // 섹션 헤더 클릭은 접힘을 토글한다(열기가 아니다).
    session.mouse(1, x, row_y(session, 1, rect.y), 0, 0);
    try std.testing.expect(session.scm_collapsed[@intFromEnum(scm_view.Section.unstaged)]);
}

// [손 확인] "첫 파일은 열리는데 두 번째가 안 열린다". 클릭 경로(행 → openDiffForScmRow)를 그대로 태워 재현한다.
test "소스 컨트롤: 여러 행을 연달아 눌러도 각각 diff Term이 열린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 위 테스트와 같은 이유로 backend를 `shutting_down` 상태로 미리 만든다 — diff Term을 열면 detach된
    // `diffWorker`가 뜨는데 테스트가 그 완료를 기다릴 수 없어, 반환 시점에 워커의 argv 버퍼가 leak으로 판정된다.
    session.git_backend = try git_backend_mod.Backend.init(allocator, session.io);
    session.git_backend.?.state.?.shutting_down = true;

    // gitRepoRoot가 이 저장소를 찾도록 탐색기 root 대신 임시 저장소를 흉내 낼 수는 없으므로, 클릭 경로의
    // 앞단(openDiffTerm)을 직접 부른다 — 검증 대상은 "두 번째 열기가 되는가"이지 저장소 탐색이 아니다.
    session.openDiffTerm("/repo", "/repo/a.txt", "a.txt", null, .unstaged);
    session.openDiffTerm("/repo", "/repo/b.txt", "b.txt", null, .unstaged);

    var diffs: usize = 0;
    var it = session.fileEntries();
    while (it.next()) |entry| {
        if (entry.kind == .diff) diffs += 1;
    }
    try std.testing.expectEqual(@as(usize, 2), diffs);
    try std.testing.expect(session.diffTermFor("/repo/a.txt", .unstaged) != null);
    try std.testing.expect(session.diffTermFor("/repo/b.txt", .unstaged) != null);
}

// [E1 종료 조건] 읽는 중에 그 Term을 닫는 경로. 늦게 도착한 결과가 **사라진 entry를 건드리면** 크래시고, 그냥
// 흘려보내면 누수다. 둘 다 아니어야 한다 — testing.allocator가 누수를, drain의 짝 맞추기가 오배정을 잡는다.
test "diff Term을 읽는 중에 닫아도 결과가 안전하게 버려진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initSmokeSessionSized(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    session.openDiffTerm("/repo", "/repo/a.txt", "a.txt", null, .unstaged);
    const term = session.diffTermFor("/repo/a.txt", .unstaged) orelse return error.MissingDiffTerm;
    const entry = term.file_entry orelse return error.MissingEntry;
    const request_id = entry.diff_request_id;

    // 그 Term을 닫는다(백엔드가 실제로 돌고 있었다면 결과는 뒤에 온다).
    const pane = session.activePane();
    var index: usize = 0;
    while (index < pane.terms.items.len) : (index += 1) {
        if (pane.terms.items[index] == term) break;
    }
    session.closeTermAt(session.app_window.active_tab, pane, index);
    try std.testing.expect(session.diffTermFor("/repo/a.txt", .unstaged) == null);

    // 늦게 온 결과를 흉내 낸다: 그 request_id를 가진 결과가 도착해도 짝이 없어 그냥 버려져야 한다(크래시·누수 없음).
    if (session.git_backend) |*backend| {
        _ = backend;
        var late: git_backend_mod.DiffResult = .{
            .original = try allocator.dupe(u8, "old"),
            .modified = try allocator.dupe(u8, "new"),
            .ok = true,
            .request_id = request_id,
        };
        // drainGitStatus가 하는 일과 같은 절차 — 짝이 없으면 해제한다.
        var matched = false;
        var it = session.fileEntries();
        while (it.next()) |candidate| {
            if (candidate.kind == .diff and candidate.diff_request_id == late.request_id) matched = true;
        }
        try std.testing.expect(!matched);
        late.deinit(allocator);
    }

    // 이 테스트는 **워커가 도는 것을 전제**한다("결과는 뒤에 온다"). 그런데 `diffWorker`는 detach라 join할 수
    // 없고, 테스트 함수가 반환할 때 워커가 아직 `git show` 중이면 그 argv 버퍼가 leak으로 판정돼 ABRT로 죽는다
    // (제품 코드는 refcount라 늦게 끝나도 안전하게 회수된다).
    //
    // 그래서 워커가 실제로 끝난 것을 확인하고 반환한다 — 결과가 버려지는 것까지 봐야 "안전하게 버려진다"를
    // 검증한 것이기도 하다. `/repo`는 없는 저장소라 git이 즉시 실패해 대기는 수십 ms 수준이다.
    if (session.git_backend) |*backend| {
        var waited_ms: usize = 0;
        while (waited_ms < 5_000) : (waited_ms += 5) {
            if (backend.takeDiffResult()) |result| {
                var owned = result;
                owned.deinit(allocator);
                break;
            }
            std.Io.sleep(session.io, std.Io.Duration.fromMilliseconds(5), .awake) catch {};
        }
    }
}

// [E1 §6.1] 턴 스냅샷 전 구간을 **실제 git**으로 돌린다: 스냅샷 요청 → 링 적재 → 목록이 그 기준으로 턴 범위를
// 읽어 오기까지. 에이전트 감지 자체는 별도(agent_observer·turn_snapshot 단위 테스트)이고, 여기서는 그 뒤 배관을 본다.
test "턴 스냅샷이 링에 실리고 목록이 그 기준으로 바뀐 파일을 읽어 온다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const git_exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;

    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd_ptr = std.c.getcwd(&cwd_buf, cwd_buf.len) orelse return error.SkipZigTest;
    const cwd = std.mem.span(@as([*:0]u8, @ptrCast(cwd_ptr)));
    var repo_buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = std.fmt.bufPrint(&repo_buf, "{s}/.zig-cache/tmp-session-turn", .{cwd}) catch return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo })) return error.SkipZigTest;
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "config", "user.email", "t@t" })) return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "config", "user.name", "t" })) return error.SkipZigTest;
    git_backend_mod.testWriteFile(repo, "kept.txt", "v1\n") catch return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "add", "kept.txt" })) return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "-C", repo, "commit", "-qm", "base" })) return error.SkipZigTest;

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // 저장소를 목록의 root로 세운다 — 제품에서 파일을 열면 root가 추론되는 그 경로다(gitRepoRoot가 root부터 본다).
    var opened_buf: [std.fs.max_path_bytes]u8 = undefined;
    const opened = try std.fmt.bufPrint(&opened_buf, "{s}/kept.txt", .{repo});
    try session.file_tree.recordOpened(opened, repo);
    session.rememberGitRepo(repo);

    // 턴이 끝났다 — 그 순간의 작업트리를 굳힌다(에이전트 상태 전이가 부르는 바로 그 함수).
    session.captureTurnSnapshot(1);
    var spins: usize = 0;
    while (spins < 500 and session.turn_ring.len == 0) : (spins += 1) {
        session.drainGitStatus();
        var ts: std.c.timespec = .{ .sec = 0, .nsec = 10 * std.time.ns_per_ms };
        _ = std.c.nanosleep(&ts, null);
    }
    try std.testing.expect(session.turn_ring.len == 1);
    try std.testing.expect(session.turn_ring.latest().?.oid().len >= 40); // tree OID

    // 그 뒤 파일을 고치면 목록의 턴 범위에 **그 파일만** 나온다(스냅샷 시점에 이미 있던 것은 안 나온다).
    git_backend_mod.testWriteFile(repo, "kept.txt", "v2\n") catch return error.SkipZigTest;
    git_backend_mod.testWriteFile(repo, "after.txt", "new\n") catch return error.SkipZigTest;
    session.dock.view = .source_control;
    session.refreshGitStatus();
    spins = 0;
    while (spins < 500) : (spins += 1) {
        session.drainGitStatus();
        if (session.git_result) |result| {
            if (result.turn_name_status.len > 0) break;
        }
        var ts: std.c.timespec = .{ .sec = 0, .nsec = 10 * std.time.ns_per_ms };
        _ = std.c.nanosleep(&ts, null);
    }
    const result = session.git_result orelse return error.NoListResult;
    try std.testing.expect(std.mem.indexOf(u8, result.turn_name_status, "kept.txt") != null);
    try std.testing.expect(std.mem.indexOf(u8, result.turn_name_status, "after.txt") != null);
}

// [E1 §6.1] **트리거까지** 제품 경로로 몬다: 실제 claude 화면(실행 중 footer → 프롬프트 상자)을 term 코어에 흘려
// `pollAgentState`가 running → idle을 판정하고, 그 순간 스냅샷이 찍히는지 본다. 위 테스트가 "찍힌 뒤"를 보고
// 이 테스트가 "언제 찍는가"를 봐서, 에이전트 없이 §6.1 전 구간이 닫힌다.
test "에이전트 화면이 running → idle이 되는 순간 작업트리가 굳는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var exe_buf: [std.fs.max_path_bytes]u8 = undefined;
    const git_exe = git_backend_mod.locate(&exe_buf) orelse return error.SkipZigTest;

    var cwd_buf: [std.fs.max_path_bytes]u8 = undefined;
    const cwd_ptr = std.c.getcwd(&cwd_buf, cwd_buf.len) orelse return error.SkipZigTest;
    const cwd = std.mem.span(@as([*:0]u8, @ptrCast(cwd_ptr)));
    var repo_buf: [std.fs.max_path_bytes]u8 = undefined;
    const repo = std.fmt.bufPrint(&repo_buf, "{s}/.zig-cache/tmp-session-turn-trigger", .{cwd}) catch return error.SkipZigTest;
    if (!git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo })) return error.SkipZigTest;
    defer _ = git_backend_mod.testRunQuiet(&.{ "/bin/rm", "-rf", repo });
    if (!git_backend_mod.testRunQuiet(&.{ git_exe, "init", "-q", "-b", "main", repo })) return error.SkipZigTest;
    git_backend_mod.testWriteFile(repo, "a.txt", "v1\n") catch return error.SkipZigTest;

    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    var opened_buf: [std.fs.max_path_bytes]u8 = undefined;
    try session.file_tree.recordOpened(try std.fmt.bufPrint(&opened_buf, "{s}/a.txt", .{repo}), repo);
    session.rememberGitRepo(repo);

    const term = session.activeTab().activeTerm();
    term.agent_kind = .claude;
    const surface = session.term_backend.surfaceFor(term.rt.handle) orelse return error.SkipZigTest;
    // 관측은 화면과 별개 경로(폴링)라 테스트에서 현재 상태로 둔다 — 여기서 보려는 것은 화면 판정이다.
    term.rt.observation.availability = .current;

    // ① 실행 중: 실행 footer가 보인다(실측 규칙 `working_footer`).
    try surface.core.write("\x1b[2J\x1b[H● 파일을 고치는 중\r\n  Working... esc to interrupt\r\n");
    term.rt.observation.observer_generation +%= 1;
    session.pollAgentState(term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.running, term.agent_state);
    try std.testing.expectEqual(@as(usize, 0), session.turn_ring.len); // 아직 턴이 안 끝났다

    // ② 턴 종료: footer가 사라지고 입력 프롬프트만 남는다(실측 규칙 `live_prompt` — 수평선 + `❯ `).
    //    화면 지우기로는 부족하다. 판정은 **스크롤백을 포함한 최근 48행**을 보므로, 실제 에이전트가 그러듯
    //    출력이 흘러 지난 footer가 꼬리 밖으로 밀려나야 한다(안 밀면 지운 화면인데도 옛 footer가 계속 잡힌다).
    try surface.core.write("\r\n" ** 60);
    try surface.core.write("───────────────────────────────────────\r\n❯ \r\n");
    term.rt.observation.observer_generation +%= 1;
    session.pollAgentState(term, false);
    try std.testing.expectEqual(maru.session.agent_observer.State.idle, term.agent_state);

    var spins: usize = 0;
    while (spins < 500 and session.turn_ring.len == 0) : (spins += 1) {
        session.drainGitStatus();
        var ts: std.c.timespec = .{ .sec = 0, .nsec = 10 * std.time.ns_per_ms };
        _ = std.c.nanosleep(&ts, null);
    }
    try std.testing.expectEqual(@as(usize, 1), session.turn_ring.len);
    try std.testing.expectEqual(term.surfaceId(), session.turn_ring.latest().?.surface_id);
}

// [§2.6] 본문 우클릭 메뉴가 **native 경로로** 열리고, 항목마다 실행 주인이 갈리는지 본다. 화면 그리기는 이미 있는
// 메뉴 경로(터미널 본문·파일 트리와 공유)가 하므로 여기서는 항목·좌표·동작만 검증한다.
test "파일 본문 우클릭: 대상별 항목이 서고 실행 주인이 native/web으로 갈린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(session.io, .{ .sub_path = "doc.md", .data = "# 제목\n" });
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp_root = tmp_buf[0..try tmp.dir.realPath(session.io, &tmp_buf)];
    const doc = try std.fs.path.join(allocator, &.{ tmp_root, "doc.md" });
    defer allocator.free(doc);
    try std.testing.expectEqual(AppSession.FilePanelOpenPathResult.opened, session.openFilePanelPath(doc));
    const entry = session.fileEntryForPath(doc).?;
    const surface_id = entry.surface_id;

    // 아직 배치된 적 없는 surface는 좌표를 만들 수 없다 — 열지 않는다(추측한 자리에 띄우지 않는다).
    try std.testing.expectError(error.Unsupported, session.openFileContentMenu(surface_id, .{
        .editor_epoch = 1,
        .x = 10,
        .y = 10,
        .target = .text,
        .has_selection = true,
        .href = "",
    }));

    // 지난 tick 레이아웃을 세워 준다(제품에서는 collectWebSurfaces가 채운다).
    try session.web_panel_prev.append(allocator, .{
        .surface_id = surface_id,
        .panel_kind = .markdown,
        .content_rect = .{ .x = 100, .y = 50, .w = 400, .h = 300 },
        .visible = true,
    });

    // 읽기 모드 + 링크: 링크 열기·주소 복사. 좌표는 rect 원점 + CSS px × backing scale이다.
    try session.openFileContentMenu(surface_id, .{
        .editor_epoch = 1,
        .x = 20,
        .y = 30,
        .target = .link,
        .has_selection = false,
        .href = "./other.md",
    });
    try std.testing.expect(session.file_content_menu != null);
    try std.testing.expectEqual(@as(usize, 2), session.context_menu_items_len);
    try std.testing.expectEqualStrings("링크 열기", session.context_menu_items_buf[0]);
    try std.testing.expectEqualStrings("주소 복사", session.context_menu_items_buf[1]);
    const scale = @max(@as(u32, 1), session.scale_milli);
    try std.testing.expectEqual(@as(i32, @intCast(100 + 20 * scale / 1000)), session.chrome_host.context_menu.anchor_x);
    try std.testing.expectEqual(@as(i32, @intCast(50 + 30 * scale / 1000)), session.chrome_host.context_menu.anchor_y);

    // 주소 복사는 native가 실행한다 — OSC 52 write와 같은 drain 큐에 들어간다(web으로 안 넘어간다).
    session.chrome_host.context_menu.selected = 1;
    session.acceptContextMenu();
    try std.testing.expectEqualStrings("./other.md", session.chrome_clipboard_write);
    try std.testing.expect(session.file_content_menu == null); // 실행 후 메뉴가 닫힌다
    try std.testing.expect(session.takeFileMenuAction() == null);

    // 읽기 모드 + 본문(선택 있음): 복사·전체 선택. 둘 다 선택에 붙어 web이 실행한다.
    try session.openFileContentMenu(surface_id, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .text,
        .has_selection = true,
        .href = "",
    });
    try std.testing.expectEqual(@as(usize, 2), session.context_menu_items_len);
    try std.testing.expectEqualStrings("복사", session.context_menu_items_buf[0]);
    session.chrome_host.context_menu.selected = 0;
    session.acceptContextMenu();
    const action = session.takeFileMenuAction().?;
    try std.testing.expectEqual(surface_id, action.surface_id);
    try std.testing.expectEqual(maru.session.content_menu.Item.copy, action.item);
    try std.testing.expect(session.takeFileMenuAction() == null); // 1회성
    // 포커스를 그 문서로 돌려준다 — 안 그러면 이어지는 ⌘Z·타이핑이 편집기까지 못 간다.
    try std.testing.expectEqual(surface_id, session.takePendingDockFocusAction().?);

    // 읽기 모드 + 여백의 "소스 모드로 열기"는 헤더 선택기와 **같은 경로**로 모드를 옮긴다.
    try session.openFileContentMenu(surface_id, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .empty,
        .has_selection = false,
        .href = "",
    });
    try std.testing.expectEqualStrings("소스 모드로 열기", session.context_menu_items_buf[1]);
    session.chrome_host.context_menu.selected = 1;
    session.acceptContextMenu();
    try std.testing.expectEqual(dock_panel.Mode.source_edit, session.filePanelMode(surface_id).?);

    // 소스 모드가 되면 같은 여백에서 붙여넣기가 생기고 "소스 모드로 열기"는 사라진다(갈 곳이 자기 자신이다).
    try session.openFileContentMenu(surface_id, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .empty,
        .has_selection = false,
        .href = "",
    });
    try std.testing.expectEqual(@as(usize, 2), session.context_menu_items_len);
    try std.testing.expectEqualStrings("붙여넣기", session.context_menu_items_buf[0]);
    try std.testing.expectEqualStrings("전체 선택", session.context_menu_items_buf[1]);
    session.closeContextMenu();

    // 파일 본문이 아닌 surface는 메뉴도 클립보드 쓰기도 못 연다.
    try std.testing.expectError(error.Unsupported, session.openFileContentMenu(surface_id + 999, .{
        .editor_epoch = 1,
        .x = 0,
        .y = 0,
        .target = .text,
        .has_selection = false,
        .href = "",
    }));
}

// [§2.6] 본문 메뉴가 떠 있는 동안 **웹뷰가 포커스를 지킨다**. 안 그러면 WebKit이 선택을 안 그려 사용자가 방금
// 겨냥한 블록이 우클릭하는 순간 사라진다. 다른 모달이 함께 열리면 그쪽이 이겨야 한다(키가 Zig로 가야 동작한다).
test "파일 본문 메뉴는 웹뷰 포커스를 뺏지 않는다(다른 모달은 그대로 뺏는다)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 평소 컨텍스트 메뉴(터미널 본문)는 그대로 터미널이 입력을 가져간다.
    session.chrome_host.context_menu.show(10, 10, 2);
    session.terminal_context_menu = true;
    try std.testing.expect(session.terminalOwnsInput());
    session.closeContextMenu();

    // 파일 본문 메뉴는 예외다.
    session.file_content_menu = .{ .surface_id = 7, .editor_epoch = 1, .len = 2 };
    session.chrome_host.context_menu.show(10, 10, 2);
    try std.testing.expect(!session.terminalOwnsInput());

    // 다른 모달이 함께 열리면 그쪽이 이긴다.
    session.chrome_host.palette.open = true;
    try std.testing.expect(session.terminalOwnsInput());
    session.chrome_host.palette.open = false;
    session.closeContextMenu();
    try std.testing.expect(!session.terminalOwnsInput()); // 메뉴가 닫혔고 다른 것도 없다
}

test "SessionDock published tree dispatches hover/down/up once and rejects a reconciled stale up" {
    const entries = [_]chrome.ui.tree.RectEntry{.{
        .id = 0x5344_1000,
        .parent_index = null,
        .kind = .card,
        .rect = .{ .x = 10, .y = 20, .width = 80, .height = 40 },
        .effective_clip = .{ .x = 10, .y = 20, .width = 80, .height = 40 },
        .action = .{ .id = 6 },
        .visual = .{ .card = .{ .variant = .surface, .paint = .{} } },
    }};
    const actions = [_]chrome.components.session_dock.ids.Entry{.{
        .action_id = 6,
        .snapshot_generation = 9,
        .intent = .{ .select_card = 42 },
    }};
    var state = chrome.ui.interaction.InteractionState{};

    const hover = AppSession.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .move,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 1,
    }).?;
    try std.testing.expect(hover.intent == null);
    try std.testing.expect(hover.visual_changed);
    try std.testing.expectEqual(@as(?chrome.ui.tree.UiId, entries[0].id), state.hovered);

    const down = AppSession.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .down,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 2,
    }).?;
    try std.testing.expect(down.intent == null); // press alone never opens an inline disclosure
    try std.testing.expect(state.capture != null);

    // Capture deliberately owns the matching up even outside the card, while the same published
    // action table still maps it to the original archive identity.
    const up = AppSession.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .up,
        .x_px = 900,
        .y_px = 900,
        .timestamp_ns = 3,
    }).?;
    try std.testing.expectEqual(@as(?chrome.components.session_dock.ids.Intent, .{ .select_card = 42 }), up.intent);
    try std.testing.expect(state.capture == null);

    _ = AppSession.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .down,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 4,
    }).?;
    _ = try chrome.ui.interaction.reconcile(&state, .{ .entries = &entries }, .{ .entries = &entries });
    const stale_up = AppSession.dispatchAgentSessionDockPointer(&state, &entries, &actions, 9, .{
        .phase = .up,
        .x_px = 20,
        .y_px = 30,
        .timestamp_ns = 5,
    }).?;
    try std.testing.expect(stale_up.intent == null);

    const changed_actions = [_]chrome.components.session_dock.ids.Entry{.{
        .action_id = 6,
        .snapshot_generation = 9,
        .intent = .{ .select_card = 99 },
    }};
    try std.testing.expect(AppSession.agentSessionDockFrameEql(&entries, &actions, &entries, &actions));
    try std.testing.expect(!AppSession.agentSessionDockFrameEql(&entries, &actions, &entries, &changed_actions));
}

test "archive smoke probe returns only the pointer-hittable clipped capability rect" {
    const entry = chrome.ui.tree.RectEntry{
        .id = 1,
        .parent_index = null,
        .kind = .card,
        .rect = .{ .x = 10, .y = 20, .width = 80, .height = 40 },
        .effective_clip = .{ .x = 30, .y = 25, .width = 25, .height = 20 },
        .action = .{ .id = 1 },
        .visual = .{ .card = .{ .variant = .surface, .paint = .{} } },
    };
    try std.testing.expectEqual(chrome.ui.layout.UiRect{ .x = 30, .y = 25, .width = 25, .height = 20 }, AppSession.smokeProbeVisibleRect(entry).?);

    var hidden = entry;
    hidden.effective_clip = .{ .x = 100, .y = 100, .width = 1, .height = 1 };
    try std.testing.expect(AppSession.smokeProbeVisibleRect(hidden) == null);
}

// ── 진행 중 pointer gesture vs 에이전트 세션 도크 분기 ──────────────────────────────────────────
// `mouse()`의 도크 분기는 rect 판정만으로 move/up을 소비하고 return한다. 그 분기가 모든
// `pointerGestureIs(...)` 분기보다 위에 있어, 도크가 열린 채로 divider·탭·pane·사이드바 카드·
// 스크롤바를 끌다 포인터가 도크 content 위로 들어가면 그 gesture가 이벤트를 잃었다(끌던 것이 멈추고,
// up도 도크가 먹어 owner가 armed로 남았다). 아래 5개는 다섯 gesture 각각에서 "도크 위를 지나도
// 소유권이 유지되고 up이 owner를 푼다"를 고정한다 — 옛 동작이면 전부 red다.
// 단일 출처: docs/chrome-interaction-migration.md §2.

/// 아카이브 worker를 띄우지 않고 오른쪽 에이전트 세션 도크만 연다(레이아웃/라우팅 격리 —
/// `automatic agent sessions dock width` 테스트와 같은 규율).
fn openAgentSessionsDockForRouting(session: *AppSession, side: dock_panel.Side) void {
    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = side;
    session.dock.size = 0;
    session.agent_session_archive_initialized = false;
    session.setDockView(.agent_sessions);
    session.agent_session_archive_initialized = true;
    for (session.tabs.items) |tab| session.resizeTabPanes(tab);
    session.recomputeActivePaneRect();
}

fn initDockedRoutingSession(allocator: std.mem.Allocator, side: dock_panel.Side) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    errdefer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(1600, 900, 1000);
    openAgentSessionsDockForRouting(session, side);
    return session;
}

/// 도크 content 중앙 — 진행 중 gesture가 지나가더라도 도크로 새면 안 되는 좌표.
fn dockContentCenter(session: *AppSession) struct { x: f64, y: f64 } {
    const content = session.dockGeometry().tree_content;
    return .{
        .x = @floatFromInt(content.x + content.w / 2),
        .y = @floatFromInt(content.y + content.h / 2),
    };
}

test "divider capture는 split이 사라지면 carry verdict가 취소한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 3 pane: split{P0, split{P1, P2}}. 안쪽 divider를 잡고 그 split을 없앤다.
    try session.splitActivePane(.horizontal);
    try session.splitActivePane(.horizontal);
    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try session.layoutActiveTabDividers(&segs);
    try std.testing.expectEqual(@as(usize, 2), segs.items.len);

    // 활성 pane(P2)이 속한 안쪽 split의 divider를 찾는다.
    var inner_index: usize = 0;
    for (segs.items, 0..) |seg, i| {
        if (seg.split != switch (session.activeTab().tree) {
            .split => |sp| sp,
            .leaf => return error.TestExpectedSplit,
        }) inner_index = i;
    }
    const inner = segs.items[inner_index];
    const div_x: f64 = @floatFromInt(inner.pos);
    const div_y: f64 = @floatFromInt(inner.bounds.y + inner.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(session.dividerCaptureActive());
    try std.testing.expect(session.divider_capture_split == inner.split);

    // 드래그 중에 그 split이 collapse된다(단축키 close 등 외부 구조 변경).
    session.closeActivePane();
    try std.testing.expect(!session.dividerCaptureActive());

    // 이후 move는 아무 것도 끌지 않는다 — 사라진 대상 위에서 resize가 계속되면 안 된다.
    session.mouse(2, div_x - 100, div_y, 0, 0);
    _ = try session.tick();
    try std.testing.expect(!session.dividerCaptureActive());
}

test "드래그 중 탭이 바뀌면 carry verdict가 divider capture를 끊는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try session.splitActivePane(.horizontal);

    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try session.layoutActiveTabDividers(&segs);
    const seg = segs.items[0];
    const split = seg.split;
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(session.dividerCaptureActive());
    const ratio_at_capture = split.ratio;

    // 드래그 도중 키보드로 다른 탭을 연다. split은 그대로 살아 있으므로 구조 무효화 경로는 아무
    // 일도 하지 않는다 — 이 경우를 잡는 것은 §5 carry verdict의 owner epoch뿐이다.
    _ = try session.newTab();
    try std.testing.expect(session.tabs.items.len == 2);

    session.mouse(2, div_x - 200, div_y, 0, 0);
    _ = try session.tick();

    // capture가 끊기고, 보이지도 않는 탭의 split이 조용히 resize되지 않는다.
    try std.testing.expect(!session.dividerCaptureActive());
    try std.testing.expectEqual(ratio_at_capture, split.ratio);
}

test "divider probe는 move 수가 아니라 tick 수만큼 resize했음을 드러낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try session.splitActivePane(.horizontal);

    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try session.layoutActiveTabDividers(&segs);
    const seg = segs.items[0];
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    // 발행된 밴드는 실제로 잡히는 자리와 같다 — probe가 렌더와 다른 rect를 내면 E2E가 헛좌표를 누른다.
    const before = session.dividerSmokeProbe();
    try std.testing.expect(before.present);
    try std.testing.expect(!before.capture_active);
    try std.testing.expect(div_x >= @as(f64, @floatFromInt(before.x_px)));
    try std.testing.expect(div_x < @as(f64, @floatFromInt(before.x_px)) + @as(f64, @floatFromInt(before.width_px)));

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(session.dividerSmokeProbe().capture_active);

    // 한 프레임 안에서 move 다섯 번. tick은 한 번.
    var step: f64 = 0;
    while (step < 5) : (step += 1) session.mouse(2, div_x - 40 - step * 20, div_y, 0, 0);
    _ = try session.tick();

    const after = session.dividerSmokeProbe();
    try std.testing.expectEqual(@as(u64, 5), after.move_events);
    // 계약 §4.3의 상한이 move 수가 아니라는 것을 이 부등식 하나가 증명한다. ratio 값만 보는
    // fixture는 다섯 번 적용됐는지 한 번 적용됐는지 구분하지 못한다.
    try std.testing.expectEqual(@as(u64, 1), after.resize_applications);
    try std.testing.expect(after.ratio_milli != before.ratio_milli);

    session.mouse(3, div_x - 140, div_y, 0, 0);
    try std.testing.expect(!session.dividerSmokeProbe().capture_active);
}

test "divider capture와 PointerGestureOwner는 같은 stream에 공존하지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    try session.splitActivePane(.horizontal);

    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try session.layoutActiveTabDividers(&segs);
    const seg = segs.items[0];
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(session.dividerCaptureActive());
    // divider가 capture를 들고 있는 동안 owner union은 비어 있어야 한다. 두 권위가 겹치면
    // 어느 쪽이 이 stream을 소유하는지 이벤트마다 달라진다(이관 계약 §4.3).
    try std.testing.expect(session.pointerGestureIs(.none));

    // 반대 방향: 다른 gesture가 시작되면 divider capture가 끝난다.
    session.beginPointerGesture(.{ .scrollbar = .{ .grab = 0 } });
    try std.testing.expect(!session.dividerCaptureActive());
    try std.testing.expect(session.divider_capture_split == null);
}

test "라이브 divider 드래그는 도크 위를 지나도 ratio를 계속 추적하고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();
    try std.testing.expect(session.dockVisible());

    try session.splitActivePane(.horizontal);
    var segs: std.ArrayList(PaneTree.DividerSeg) = .empty;
    defer segs.deinit(allocator);
    try session.layoutActiveTabDividers(&segs);
    const seg = segs.items[0];
    const split = seg.split;
    const div_x: f64 = @floatFromInt(seg.pos);
    const div_y: f64 = @floatFromInt(seg.bounds.y + seg.bounds.h / 2);

    session.mouse(1, div_x, div_y, 0, 0);
    try std.testing.expect(session.dividerCaptureActive());
    session.mouse(2, div_x - 200, div_y, 0, 0);
    _ = try session.tick();
    const ratio_outside = split.ratio;

    // 도크 content 위로 이동 — clamp가 아니라 이벤트 미도달로 얼어붙던 자리다. divider bounds가 도크
    // 왼쪽에서 끝나므로 ratio는 상한으로 가야 하고, 직전 값 그대로면 도크가 move를 가로챈 것이다.
    const dock_center = dockContentCenter(session);
    session.mouse(2, dock_center.x, dock_center.y, 0, 0);
    _ = try session.tick();
    try std.testing.expect(split.ratio != ratio_outside);
    try std.testing.expect(session.dividerCaptureActive());
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!session.dividerCaptureActive());
    _ = try session.tick();
}

test "라이브 Term 탭 드래그는 도크 위를 지나도 좌표를 계속 받고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    try session.newTermInActivePane(); // 탭 2개 — 탭 세그먼트가 생긴다
    var lr: std.ArrayList(PaneTree.LeafRect) = .empty;
    defer lr.deinit(allocator);
    try session.activeTabLeafRects(allocator, session.termRect(), &lr);
    const pb = session.paneBar(lr.items[0].rect, lr.items[0].leaf).?;
    const tab_x: f64 = @floatFromInt(pb.tabs.x + 2);
    const tab_y: f64 = @floatFromInt(pb.full.y + 1);

    session.mouse(1, tab_x, tab_y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.terminal_tab));

    // drag(2)는 owner의 마지막 좌표를 갱신한다. 도크가 가로채면 그 값이 down 좌표에 머문다.
    const dock_center = dockContentCenter(session);
    session.mouse(2, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.terminal_tab));
    try std.testing.expectEqual(dock_center.x, session.pointer_gesture_owner.terminal_tab.x);
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.terminal_tab));
    _ = try session.tick();
}

test "라이브 pane 드래그는 도크 위를 지나도 좌표를 계속 받고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
