    try std.testing.expectEqual(dock_center.y, session.pointer_gesture_owner.pane.y);
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.pane));
    _ = try session.tick();
}

/// 픽스처 그룹 한 건. `entries`에 `.group`만 넣고 이 배열을 비워 두면 `buildAgentSessionDockItems`가
/// 그 항목을 건너뛰어 스크롤 좌표(그룹을 예약)와 발행 tree(그리지 않음)의 index가 어긋난다. 제품
/// 경로는 둘을 같은 재투영에서 함께 만들지만, 테스트가 한쪽만 채우면 없는 결함을 만들어 낸다.
fn appendFixtureArchiveGroup(session: *AppSession, allocator: std.mem.Allocator, count: usize) !void {
    const key = try allocator.dupe(u8, "/workspace/fixture");
    errdefer allocator.free(key);
    try session.agent_session_archive_projection.groups.append(allocator, .{
        .key = key,
        .label = key,
        .count = count,
        .collapsed = false,
    });
}

/// 픽스처 archive record 한 건 — 문자열은 session이 소유(deinit이 해제)한다.
fn appendFixtureArchiveRecord(session: *AppSession, allocator: std.mem.Allocator) !void {
    try appendFixtureArchiveRecordN(session, allocator, 0);
}

/// 서로 다른 신원의 픽스처 record. 도크의 펼침은 `{provider, session_id, device, inode}` 신원으로
/// 매칭되므로, 같은 record를 두 항목이 가리키면 발행 tree가 **둘 다** 펼쳐 그린다. 실제 재투영은
/// record 하나를 한 번만 내보내니, 신원을 index로 갈라 두어야 테스트가 없는 상태를 만들지 않는다.
fn appendFixtureArchiveRecordN(session: *AppSession, allocator: std.mem.Allocator, index: usize) !void {
    try session.agent_session_archive_records.append(allocator, .{
        .parsed = .{
            .provider = .claude,
            .session_id = try std.fmt.allocPrint(allocator, "fixture-session-{d}", .{index}),
            .title = try allocator.dupe(u8, "fixture"),
            .summary = try allocator.dupe(u8, "summary"),
            .cwd = try allocator.dupe(u8, "/tmp"),
            .cwd_canonical = true,
            .model = try allocator.dupe(u8, "claude-fixture"),
            .message_count = 1,
            .verified_user = true,
        },
        .source_path = try std.fmt.allocPrint(allocator, "/tmp/maru-archive-fixture-{d}-does-not-exist.jsonl", .{index}),
        .mtime_ns = 0,
        .inode = 1 + index,
        .device = 1,
    });
}

// 도크 휠 경로에는 판정자가 하나도 없었다. 방향을 뒤집어도, 포인터가 터미널 위인데 도크가 먹어도,
// 분수 residue를 소비하고도 안 빼서 같은 픽셀을 반복해도 전체 스위트가 초록이었다(이름에 "wheel"이
// 든 기존 테스트는 파일 트리 것이다). §2가 residue를 ScrollArea 소유로 적었으므로 SV1c가 이 코드를
// 옮기는데, 판정자 없이 옮기면 옮기다 깨져도 아무도 모른다.
fn dockWheelFixture(allocator: std.mem.Allocator) !*AppSession {
    const session = try initDockedRoutingSession(allocator, .right);
    errdefer allocator.destroy(session);
    errdefer session.deinit();
    const card_count = 20;
    for (0..card_count) |index| try appendFixtureArchiveRecordN(session, allocator, index);
    try appendFixtureArchiveGroup(session, allocator, card_count);
    try session.agent_session_archive_projection.entries.append(allocator, .{ .group = 0 });
    for (0..card_count) |index| try session.agent_session_archive_projection.entries.append(allocator, .{ .card = index });
    return session;
}

/// 실제 발행 경로로 도크 tree를 publish해 스크롤바 기하가 생기게 한다. 기존 드래그 테스트는
/// `agent_session_dock_scroll_drag`를 직접 세팅해 `beginAgentSessionDockScrollDrag`를 건너뛰었고,
/// 그래서 down 시점의 계약(track 안인가·thumb인가·잡은 지점·점프 뒤 기하)이 전부 무판정이었다.
fn publishDockFrameForDrag(session: *AppSession, allocator: std.mem.Allocator) !void {
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const projection = session.agentSessionDockScrollProjection();
    const items = try session.buildAgentSessionDockItems(arena, projection);
    const sizes = chrome.components.session_dock.build.bufferSizes(items);
    const content = session.dockGeometry().tree_content;
    const frame = try chrome.components.session_dock.build.build(session.agentSessionDockProps(content, projection, items), .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.session_dock.ids.Entry, sizes.actions),
    });
    session.publishAgentSessionDockFrame(frame, session.agent_session_dock_snapshot_generation);
}

test "스크롤바 down은 track 안에서만, thumb을 잡은 지점을 유지한 채 시작한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try dockWheelFixture(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    try publishDockFrameForDrag(session, allocator);
    const bar = session.agentSessionDockScrollbarGeometry() orelse return error.TestUnexpectedResult;
    try std.testing.expect(bar.max_offset_px > 0);
    try std.testing.expect(bar.thumb_h < bar.track_h);

    // ① track **밖** down은 드래그가 아니다. 이 판정이 없으면 gutter 바깥 클릭이 스크롤로 샌다.
    session.beginAgentSessionDockScrollDrag(@as(f64, bar.track_x) - 20, @as(f64, bar.track_y) + 10);
    try std.testing.expect(session.agent_session_dock_scroll_drag == null);

    // ② thumb 위 down은 **잡기**다 — 점프가 아니다. 목록이 그 자리에서 움직이면 안 되고, 잡은
    //    지점(grab_dy)이 유지돼야 thumb이 커서로 튀지 않는다.
    //    thumb **중앙**을 누르면 잡기와 점프가 같은 답을 내므로(중앙에 중앙을 놓는 것) 구분이 안 된다.
    //    가장자리를 눌러야 둘이 갈린다 — 잡기는 grab_dy가 거의 0이고 목록이 그대로지만, 점프면
    //    grab_dy가 thumb 절반이고 목록이 그 지점으로 옮겨간다.
    const before = session.agent_session_archive_scroll.offset_y_px;
    const grab_y = @as(f64, bar.thumb_y) + 1;
    session.beginAgentSessionDockScrollDrag(@as(f64, bar.track_x) + 1, grab_y);
    const thumb_drag = session.agent_session_dock_scroll_drag orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(before, session.agent_session_archive_scroll.offset_y_px);
    try std.testing.expectApproxEqAbs(@as(f32, 1), thumb_drag.grab_dy, 0.01);
    try std.testing.expect(thumb_drag.grab_dy < bar.thumb_h / 4);
    session.endAgentSessionDockScrollDrag();

    // ③ thumb **바깥** track down은 그 자리로 점프하고, 이어지는 드래그는 옮긴 뒤의 기하를 쓴다.
    //    옛 기하를 그대로 들면 손을 떼지 않고 끌기 시작하는 순간 thumb이 한 번 튄다.
    const far_y = @as(f64, bar.track_y) + @as(f64, bar.track_h) - 2;
    session.beginAgentSessionDockScrollDrag(@as(f64, bar.track_x) + 1, far_y);
    const track_drag = session.agent_session_dock_scroll_drag orelse return error.TestUnexpectedResult;
    try std.testing.expect(session.agent_session_archive_scroll.offset_y_px > before);
    const expected = bar.withOffset(session.agent_session_archive_scroll.offset_y_px);
    try std.testing.expectApproxEqAbs(expected.thumb_y, track_drag.geometry.thumb_y, 0.01);
    // 점프한 경우 thumb 중앙을 잡은 것으로 둔다 — 그래야 이어지는 이동이 커서를 그대로 따라간다.
    try std.testing.expectApproxEqAbs(bar.thumb_h / 2, track_drag.grab_dy, 0.01);
    session.endAgentSessionDockScrollDrag();
}

test "도크 키보드 스크롤은 한 항목을 남기고, 끝으로 가고, 휠 잔여를 비운다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try dockWheelFixture(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 도크가 키보드를 가져야 이 키들이 도크 것이 된다(터미널에서 친 Page/Home이 새면 안 된다).
    session.agent_session_dock_key_focus = true;
    try std.testing.expect(session.agentSessionDockOwnsKeys());

    const projection = session.agentSessionDockScrollProjection();
    const viewport = session.agentSessionDockContentViewportHeightPx();
    const card_h = session.agentSessionDockScrollItems().card_h_px;
    try std.testing.expect(projection.max_offset_px > 0);
    try std.testing.expect(viewport > card_h);

    // PageDown은 **카드 하나를 화면에 남긴다** — 한 화면을 통째로 넘기면 읽던 맥락이 끊긴다.
    try std.testing.expect(session.handleAgentSessionDockScrollKey(.{ .key = .page_down, .modifiers = .{} }));
    try std.testing.expectEqual(viewport - card_h, session.agent_session_archive_scroll.offset_y_px);

    // End는 정확히 상한이다(그 너머는 빈 공간이라 갈 곳이 없다).
    try std.testing.expect(session.handleAgentSessionDockScrollKey(.{ .key = .end, .modifiers = .{} }));
    try std.testing.expectEqual(projection.max_offset_px, session.agent_session_archive_scroll.offset_y_px);

    // Home은 맨 위. PageUp도 같은 걸음으로 되돌아온다.
    try std.testing.expect(session.handleAgentSessionDockScrollKey(.{ .key = .home, .modifiers = .{} }));
    try std.testing.expectEqual(@as(u32, 0), session.agent_session_archive_scroll.offset_y_px);

    // 키가 위치를 확정했으므로 휠 잔여는 버린다 — 남기면 다음 휠 틱이 옛 방향에서 시작한다.
    session.agent_session_archive_wheel_residue_px = 3;
    try std.testing.expect(session.handleAgentSessionDockScrollKey(.{ .key = .page_down, .modifiers = .{} }));
    try std.testing.expectEqual(@as(f64, 0), session.agent_session_archive_wheel_residue_px);

    // 도크가 키보드를 놓으면 같은 키가 더 이상 도크 것이 아니다.
    session.agent_session_dock_key_focus = false;
    try std.testing.expect(!session.handleAgentSessionDockScrollKey(.{ .key = .home, .modifiers = .{} }));
}

test "재투영은 스냅샷 세대를 올려 진행 중인 스크롤바 드래그를 놓게 한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try dockWheelFixture(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    // 이 세대가 carry 판정의 **유일한** 근거다. 목록이 새로 스캔돼 길이 자체가 달라졌는데 세대가
    // 그대로면, 진행 중인 드래그가 없어진 목록 기준으로 계속 스크롤한다. 그 판정을 generation
    // 비교 하나에 위임했으므로 "재투영은 세대를 올린다"가 지켜져야 나머지가 성립한다.
    const before = session.agent_session_dock_snapshot_generation;
    session.rebuildAgentSessionArchiveProjection();
    try std.testing.expect(session.agent_session_dock_snapshot_generation != before);

    // 0은 "세대를 쓰지 않는 소비자"라는 뜻이라 wrap 시에도 건너뛴다 — 안 그러면 그 프레임만
    // 세대 검사가 통째로 꺼진다.
    session.agent_session_dock_snapshot_generation = std.math.maxInt(u64);
    session.rebuildAgentSessionArchiveProjection();
    try std.testing.expect(session.agent_session_dock_snapshot_generation != 0);
}

test "스크롤바 드래그는 자기 payload만 먹고 놓기 직전 좌표를 잃지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try dockWheelFixture(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    try publishDockFrameForDrag(session, allocator);
    const bar = session.agentSessionDockScrollbarGeometry() orelse return error.TestUnexpectedResult;
    const payload = chrome.components.session_dock.build.scroll_drag_payload;

    session.beginAgentSessionDockScrollDrag(@as(f64, bar.track_x) + 1, @as(f64, bar.thumb_y) + 1);
    try std.testing.expect(session.agent_session_dock_scroll_drag != null);
    const start = session.agent_session_archive_scroll.offset_y_px;

    // ① 다른 제스처(탭 드래그 등)의 좌표를 스크롤로 먹으면 안 된다.
    session.absorbAgentSessionDockScrollDrag(.{ .moved = .{
        .payload = payload +% 1,
        .x_px = @as(f64, bar.track_x),
        .y_px = @as(f64, bar.track_y) + @as(f64, bar.track_h),
    } });
    session.applyAgentSessionDockScrollDrag();
    try std.testing.expectEqual(start, session.agent_session_archive_scroll.offset_y_px);

    // ② 자기 payload는 흡수하되 **적용은 tick이 한다**. move만으로 움직이면 한 프레임에 같은 일을
    //    여러 번 하게 된다.
    const bottom_y = @as(f64, bar.track_y) + @as(f64, bar.track_h) - 1;
    session.absorbAgentSessionDockScrollDrag(.{ .moved = .{ .payload = payload, .x_px = @as(f64, bar.track_x), .y_px = bottom_y } });
    try std.testing.expectEqual(start, session.agent_session_archive_scroll.offset_y_px);
    session.applyAgentSessionDockScrollDrag();
    const after_move = session.agent_session_archive_scroll.offset_y_px;
    try std.testing.expect(after_move > start);

    // ③ 같은 좌표를 다시 흡수해도 값이 그대로면 아무 일도 하지 않는다(track 끝에 닿은 채 미는 동안).
    session.agent_session_archive_wheel_residue_px = 7;
    session.absorbAgentSessionDockScrollDrag(.{ .moved = .{ .payload = payload, .x_px = @as(f64, bar.track_x), .y_px = bottom_y } });
    session.applyAgentSessionDockScrollDrag();
    try std.testing.expectEqual(after_move, session.agent_session_archive_scroll.offset_y_px);
    // 위치가 안 바뀌었으므로 다른 상태도 건드리지 않았다.
    try std.testing.expectEqual(@as(f64, 7), session.agent_session_archive_wheel_residue_px);

    // ④ 위치가 **실제로 바뀌면** 휠 잔여는 버린다. 잔여는 그 위치로 가는 도중의 상태라, 다른 입구가
    //    위치를 확정한 뒤에는 의미가 없다(남기면 다음 휠 틱이 엉뚱한 곳에서 시작한다).
    session.agent_session_archive_wheel_residue_px = 5;
    const up_y = @as(f64, bar.track_y) + 1;
    session.absorbAgentSessionDockScrollDrag(.{ .dropped = .{ .payload = payload, .x_px = @as(f64, bar.track_x), .y_px = up_y } });
    try std.testing.expect(session.agent_session_archive_scroll.offset_y_px < after_move);
    try std.testing.expectEqual(@as(f64, 0), session.agent_session_archive_wheel_residue_px);
    // drop이 드래그를 끝낸다.
    try std.testing.expect(session.agent_session_dock_scroll_drag == null);
}

test "도크 휠은 포인터가 도크 위일 때만, 목록 방향으로, 상한 안에서 움직인다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try dockWheelFixture(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const content = session.dockGeometry().tree_content;
    const inside_x: f64 = @floatFromInt(content.x + content.w / 2);
    const inside_y: f64 = @floatFromInt(content.y + content.h / 2);
    const max_offset = session.agentSessionDockScrollProjection().max_offset_px;
    try std.testing.expect(max_offset > 0);

    // ① 아래로 굴리면 목록이 아래로 간다. 부호가 뒤집히면 맨 위에서 아무 일도 일어나지 않는다.
    session.scrollWheel(-3, 0, false, inside_x, inside_y);
    const after_down = session.agent_session_archive_scroll.offset_y_px;
    try std.testing.expect(after_down > 0);

    // ② 포인터가 도크 밖이면 도크는 움직이지 않는다. 이 판정이 빠지면 터미널 위에서 굴려도 도크가 먹는다.
    //
    // 잔여가 **실제로 남아 있는 상태**에서 나가야 그것이 지워지는지 볼 수 있다. non-precise 델타는
    // 카드 높이 단위라 잔여를 남기지 않으므로, precise 틱으로 1픽셀 미만을 먼저 쌓는다.
    session.scrollWheel(-0.3, 0, true, inside_x, inside_y);
    try std.testing.expect(session.agent_session_archive_wheel_residue_px != 0);
    const before_outside = session.agent_session_archive_scroll.offset_y_px;

    const outside_x: f64 = @floatFromInt(content.x / 2);
    session.scrollWheel(-3, 0, false, outside_x, inside_y);
    try std.testing.expectEqual(before_outside, session.agent_session_archive_scroll.offset_y_px);
    // 도크를 떠났으므로 분수 잔여도 남기지 않는다 — 남기면 다시 들어왔을 때 첫 틱이 엉뚱하게 튄다.
    try std.testing.expectEqual(@as(f64, 0), session.agent_session_archive_wheel_residue_px);

    // ③ 위로 되돌리면 원래 자리로 돌아온다(②에서 쌓은 1픽셀 미만은 offset을 안 움직였다).
    try std.testing.expectEqual(after_down, before_outside);
    session.scrollWheel(3, 0, false, inside_x, inside_y);
    try std.testing.expectEqual(@as(u32, 0), session.agent_session_archive_scroll.offset_y_px);

    // ④ 끝까지 굴려도 상한을 넘지 않는다.
    for (0..200) |_| session.scrollWheel(-10, 0, false, inside_x, inside_y);
    try std.testing.expectEqual(max_offset, session.agent_session_archive_scroll.offset_y_px);
}

test "도크 휠의 분수 잔여는 한 번만 소비되고 방향이 바뀌면 버려진다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try dockWheelFixture(allocator);
    defer allocator.destroy(session);
    defer session.deinit();

    const content = session.dockGeometry().tree_content;
    const inside_x: f64 = @floatFromInt(content.x + content.w / 2);
    const inside_y: f64 = @floatFromInt(content.y + content.h / 2);

    // precise(트랙패드) 델타는 1픽셀보다 작을 수 있다. 정수 픽셀이 찰 때까지는 움직이지 않고
    // 잔여로만 쌓인다 — 그러지 않으면 미세한 손가락 움직임이 한 픽셀씩 튄다.
    session.scrollWheel(-0.6, 0, true, inside_x, inside_y);
    try std.testing.expectEqual(@as(u32, 0), session.agent_session_archive_scroll.offset_y_px);
    try std.testing.expect(session.agent_session_archive_wheel_residue_px != 0);

    // 두 번째로 1픽셀을 넘긴다(0.6 + 0.6 = 1.2).
    session.scrollWheel(-0.6, 0, true, inside_x, inside_y);
    const moved = session.agent_session_archive_scroll.offset_y_px;
    // 두 번 합쳐 1픽셀을 넘겼으니 이제 움직인다.
    try std.testing.expect(moved > 0);
    // **소비한 정수부는 잔여에서 빠져야 한다.** 안 빼면 같은 픽셀을 계속 다시 쓰면서 가속한다.
    try std.testing.expect(@abs(session.agent_session_archive_wheel_residue_px) < 1);

    // 방향을 뒤집으면 이전 방향의 잔여를 버린다 — 남겨 두면 첫 반대 틱이 상쇄돼 굼뜨게 느껴진다.
    session.scrollWheel(0.1, 0, true, inside_x, inside_y);
    try std.testing.expect(session.agent_session_archive_wheel_residue_px > 0);
}

// 스크롤 좌표계를 `chrome/ui/scroll_area.zig`로 옮긴 뒤, 그 모듈은 촘촘한데 **도크가 그 모듈에 넘기는
// 값**에는 판정자가 거의 없다는 것이 변이 검증에서 드러났다. `ArchiveScrollItems`의 다섯 가지를 하나씩
// 틀리게 만들어도(펼침 예약 없음, gap 0, 항목 수 -1, 펼침 index null, 카드 높이에 펼침 높이) 전체
// 스위트가 초록이었다. 모듈이 옳아도 입력이 틀리면 결과는 같이 틀린다.
test "도크가 스크롤 모듈에 넘기는 항목 높이·간격·개수가 도크 metrics와 일치한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    const m = chrome.components.session_dock.types.DockMetrics.resolve(session.agentSessionDockScaleMilli());
    try appendFixtureArchiveGroup(session, allocator, 3);
    try session.agent_session_archive_projection.entries.append(allocator, .{ .group = 0 });
    for (0..3) |index| try session.agent_session_archive_projection.entries.append(allocator, .{ .card = index });

    const items = session.agentSessionDockScrollItems();
    // 높이는 도크가 그리는 것과 같은 값이어야 한다. 카드 높이에 펼침 detail이 섞이면 스크롤 좌표가
    // 실제 그림보다 길어져, 목록 끝에서 빈 공간이 남는다.
    try std.testing.expectEqual(m.card_h, items.card_h_px);
    try std.testing.expectEqual(m.group_h, items.group_h_px);
    try std.testing.expectEqual(m.item_gap, items.gap_px);
    // 그룹 헤더와 카드는 높이가 다르다 — 같아지면 §3의 walk가 의미를 잃는다.
    try std.testing.expect(items.group_h_px != items.card_h_px);
    try std.testing.expectEqual(m.group_h, items.heightPx(0));
    try std.testing.expectEqual(m.card_h, items.heightPx(1));

    // 창을 정하는 extent가 항목을 하나라도 빠뜨리면 마지막 카드가 아예 안 그려진다.
    const extent = items.extent(400);
    try std.testing.expectEqual(session.agent_session_archive_projection.entries.items.len, extent.count);
    try std.testing.expectEqual(@as(u32, 400), extent.viewport_h_px);
    // 도크는 카드 사이를 여백이 아니라 divider로 구분하므로 gap이 0이다. 이 값을 `m.item_gap`과
    // 비교하면 양쪽이 0이라 아무것도 판정하지 못한다(실제로 gap을 0으로 바꾸는 변이가 그 단언을
    // 통과했다). 그래서 0임을 직접 못박고, gap 산술 자체는 `scroll_area`의 단위 테스트가 본다.
    try std.testing.expectEqual(@as(u32, 0), extent.gap_px);

    // 전체 content 높이는 항목 높이의 합이다(gap이 0이므로 사이 여백이 더해지지 않는다).
    const projection = session.agentSessionDockScrollProjection();
    try std.testing.expectEqual(m.group_h + m.card_h * 3, projection.content_height_px);
}

/// 스크롤 좌표가 예약한 높이와 **컴포넌트가 실제로 그린 rect**를 대조한다. 앞의 테스트는 host가
/// metrics에서 값을 옳게 옮겼는지만 보는데, 그것만으로는 두 출처가 같은 답을 낸다는 보장이 없다 —
/// 스크롤이 카드 하나를 72px로 예약해도 발행 tree가 80px로 그리면 목록 끝에서 어긋난다.
const DockTreeItemRect = struct { y: f32, height: u32 };

fn dockTreeItemRects(
    session: *AppSession,
    allocator: std.mem.Allocator,
    projection: chrome.ui.scroll_area.Projection,
    out: *std.ArrayList(DockTreeItemRect),
) !void {
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const dock_items = try session.buildAgentSessionDockItems(arena, projection);
    const sizes = chrome.components.session_dock.build.bufferSizes(dock_items);
    const content = session.dockGeometry().tree_content;
    // **제품이 쓰는 그 함수**로 props를 만든다. 여기서 리터럴을 다시 쓰면 host의 구성이 틀려도
    // 테스트는 자기 복제본만 보게 된다.
    const frame = try chrome.components.session_dock.build.build(session.agentSessionDockProps(content, projection, dock_items), .{
        .nodes = try arena.alloc(chrome.ui.tree.UiNode, sizes.nodes),
        .entries = try arena.alloc(chrome.ui.tree.RectEntry, sizes.entries),
        .layout_items = try arena.alloc(chrome.ui.layout.Item, sizes.layout_items),
        .flex_scratch = try arena.alloc(chrome.ui.layout.FlexScratch, sizes.flex_scratch),
        .child_rects = try arena.alloc(chrome.ui.layout.UiRect, sizes.child_rects),
        .actions = try arena.alloc(chrome.components.session_dock.ids.Entry, sizes.actions),
    });

    // scroll-area의 published rect를 기준으로 삼는다. 도크 위치가 바뀌어도 상대 좌표는 계약이다.
    const content_index = frame.tree.find(chrome.components.session_dock.build.NodeIds.content) orelse
        return error.TestUnexpectedResult;
    const content_y = frame.tree.entries[content_index].rect.y;

    // host는 스크롤 영역 높이를 `content.h - fixedChromeHeight()`로 **예측**하고 build는 flex로 **실제**
    // 값을 만든다. 같은 수의 출처가 둘이라 갈릴 수 있는데, 갈리면 창 계산과 clip 경계가 어긋난다.
    // docs/scroll-area.md §4.2가 SV1c에서 이 예측식을 없애겠다고 한 자리이므로, 없앤 뒤에도 같은 값인지
    // 이 단언이 지킨다(예측식이 되살아나도 여기서 갈라진다).
    try std.testing.expectEqual(
        session.agentSessionDockContentViewportHeightPx(),
        @as(u32, @intFromFloat(@round(frame.tree.entries[content_index].rect.height))),
    );

    // thumb 길이는 "보이는 비율"이다. host가 스크롤바에 넘기는 목록 전체 높이가 틀리면 이 비율만
    // 어긋나고 카드 rect는 멀쩡하므로, 항목 대조만으로는 잡히지 않는다(실제로 그 변이가 통과했다).
    if (frame.tree.find(chrome.components.session_dock.build.NodeIds.scroll_thumb)) |thumb_index| {
        const track_index = frame.tree.find(chrome.components.session_dock.build.NodeIds.scroll_track).?;
        const track_h = frame.tree.entries[track_index].rect.height;
        const thumb_h = frame.tree.entries[thumb_index].rect.height;
        const visible_ratio = track_h / @as(f32, @floatFromInt(projection.content_height_px));
        // 최소 두께에 걸리지 않는 목록에서만 비율이 그대로 드러난다.
        if (thumb_h > @as(f32, @floatFromInt(session.agentSessionDockScrollbarMinThumbPx())))
            try std.testing.expectApproxEqAbs(visible_ratio, thumb_h / track_h, 0.01);
    }

    out.clearRetainingCapacity();
    for (0..dock_items.len) |index| {
        const node_id = chrome.components.session_dock.build.NodeIds.item(index);
        const entry_index = frame.tree.find(node_id) orelse return error.TestUnexpectedResult;
        const rect = frame.tree.entries[entry_index].rect;
        try out.append(allocator, .{
            .y = rect.y - content_y,
            .height = @intFromFloat(@round(rect.height)),
        });
    }
}

test "스크롤이 예약한 높이가 발행 tree의 카드 rect와 정확히 같다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    // 스크롤이 성립해야 "부분적으로 보이는 첫 항목"을 만들 수 있다. 어떤 도크 높이에서도 넘치도록
    // 넉넉히 넣는다.
    const card_count = 20;
    for (0..card_count) |index| try appendFixtureArchiveRecordN(session, allocator, index);
    try appendFixtureArchiveGroup(session, allocator, card_count);
    try session.agent_session_archive_projection.entries.append(allocator, .{ .group = 0 });
    for (0..card_count) |index| try session.agent_session_archive_projection.entries.append(allocator, .{ .card = index });

    var rects: std.ArrayList(DockTreeItemRect) = .empty;
    defer rects.deinit(allocator);

    // 맨 위에서는 첫 항목이 scroll-area 꼭대기에 정확히 붙는다.
    try expectDockTreeMatchesScroll(session, allocator, &rects);
    try std.testing.expectEqual(@as(f32, 0), rects.items[0].y);

    // 목록을 반쯤 스크롤해 첫 항목이 **잘린** 상태를 만든다. 이때 그 항목은 음수 y에서 시작해야
    // 한다 — 0이면 부분적으로 보여야 할 카드가 통째로 위에 붙어, 스크롤해도 첫 줄이 안 잘린다.
    const half = session.agentSessionDockScrollProjection().max_offset_px / 2;
    try std.testing.expect(half > 0);
    _ = session.agent_session_archive_scroll.setOffsetPx(@intCast(half), std.math.maxInt(u32));
    {
        const projection = session.agentSessionDockScrollProjection();
        try std.testing.expect(projection.first_origin_y_px < 0);
        try expectDockTreeMatchesScroll(session, allocator, &rects);
        try std.testing.expectEqual(@as(f32, @floatFromInt(projection.first_origin_y_px)), rects.items[0].y);
    }
    session.agent_session_archive_scroll.reset();

    // 펼침도 같은 대조를 통과해야 한다. 예약과 그림이 갈리는 것이 사용자가 보고한 "펼침메뉴 누르면
    // 뒤로 보인다"의 정확한 형태다(예약은 카드 높이인데 그림은 detail+action까지 차지한다).
    try session.openAgentSessionInlineDetail(&session.agent_session_archive_records.items[0]);
    session.agent_session_archive_selected = 0;
    {
        const items = session.agentSessionDockScrollItems();
        try std.testing.expect(items.expanded_index != null);
        try expectDockTreeMatchesScroll(session, allocator, &rects);
        // 펼친 항목은 실제로 다른 항목보다 크다 — 전부 같은 높이면 위 비교가 통과해도 무의미하다.
        const expanded_offset = items.expanded_index.? - session.agentSessionDockScrollProjection().first_index;
        for (rects.items, 0..) |rect, offset| {
            if (offset == expanded_offset) continue;
            try std.testing.expect(rect.height < rects.items[expanded_offset].height);
        }
    }
}

/// 스크롤 좌표계가 예약한 것과 발행 tree가 그린 것을 항목마다 대조한다. 높이뿐 아니라 **시작 y**도
/// 본다 — 높이만 보면 첫 항목의 음수 원점(부분적으로 보이는 카드)이 사라져도 통과한다.
fn expectDockTreeMatchesScroll(
    session: *AppSession,
    allocator: std.mem.Allocator,
    rects: *std.ArrayList(DockTreeItemRect),
) !void {
    const projection = session.agentSessionDockScrollProjection();
    const items = session.agentSessionDockScrollItems();
    try dockTreeItemRects(session, allocator, projection, rects);
    try std.testing.expect(rects.items.len > 0);

    var expected_y: f32 = @floatFromInt(projection.first_origin_y_px);
    for (rects.items, 0..) |rect, offset| {
        const reserved = items.heightPx(projection.first_index + offset);
        try std.testing.expectEqual(reserved, rect.height);
        // 예약 높이를 누적한 자리에 그 항목이 실제로 놓여야 한다. 하나라도 어긋나면 그 아래 전부가
        // 밀린다 — 카드가 겹치거나 목록 끝에 빈 띠가 생기는 것이 그 결과다.
        try std.testing.expectEqual(expected_y, rect.y);
        expected_y += @floatFromInt(reserved + items.gap_px);
    }
}

test "펼친 카드는 스크롤 좌표에서도 펼친 높이를 예약한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    try appendFixtureArchiveRecordN(session, allocator, 0);
    try appendFixtureArchiveRecordN(session, allocator, 1);
    try session.agent_session_archive_projection.entries.append(allocator, .{ .card = 0 });
    try session.agent_session_archive_projection.entries.append(allocator, .{ .card = 1 });

    const collapsed = session.agentSessionDockScrollProjection().content_height_px;
    try std.testing.expect(session.agentSessionDockScrollItems().expanded_index == null);

    // 펼침을 열면 그 항목만 detail+action 높이를 더 쓴다. 이 예약이 빠지면 아래 카드들이 펼친 카드
    // 위로 겹쳐 그려진다 — 사용자가 "펼침메뉴 누르면 뒤로 보인다"고 보고했던 바로 그 상태다.
    try session.openAgentSessionInlineDetail(&session.agent_session_archive_records.items[0]);
    const items = session.agentSessionDockScrollItems();
    try std.testing.expectEqual(@as(?usize, 0), items.expanded_index);

    const m = chrome.components.session_dock.types.DockMetrics.resolve(session.agentSessionDockScaleMilli());
    const reserved = m.card_h + m.expanded_detail_h + m.expanded_actions_h;
    try std.testing.expectEqual(reserved, items.heightPx(0));
    // 다른 record를 가리키는 두 번째 항목은 펼쳐지지 않았다(펼침은 하나다).
    try std.testing.expectEqual(m.card_h, items.heightPx(1));
    try std.testing.expectEqual(collapsed + reserved - m.card_h, session.agentSessionDockScrollProjection().content_height_px);
}

// 사용자 보고 회귀: "Agent 세션 기록 탭이 열려 있으면 Enter가 오른쪽 도크 동작을 할 때가 있다".
// 카드를 한 번 누르면 selection이 남는데, Enter 활성화 게이트가 "도크가 보이는가"만 봐서 그 뒤로는
// 터미널에서 친 Enter가 셸로 가지 않고 그 카드를 계속 접었다 폈다 했다. 터미널에서 왜 중요한가:
// Enter는 명령 실행 그 자체라, 삼켜지면 사용자는 아무 반응 없는 프롬프트를 보게 된다.
test "도크 키보드 포커스가 없으면 Enter가 세션 카드가 아니라 터미널로 간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    try appendFixtureArchiveRecord(session, allocator);
    session.agent_session_archive_selected = 0;
    // 카드 클릭이 없었으므로 도크는 키보드를 갖고 있지 않다.
    try std.testing.expect(!session.agentSessionDockOwnsKeys());

    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail == null); // 도크가 Enter를 가져가지 않았다
    // 같은 게이트를 쓰는 `/`도 이때는 터미널 입력이다(경로·정규식 타이핑이 도크 검색으로 사라지지 않는다).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '/' }, .modifiers = .{} });
    try std.testing.expect(!session.agent_session_archive_search_active);

    // 대조군: **제품 경로**로 도크 안을 누르면 같은 Enter가 카드를 연다(게이트가 vacuous하지 않다).
    const dock_center = dockContentCenter(session);
    session.mouse(1, dock_center.x, dock_center.y, 0, 0);
    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(session.agentSessionDockOwnsKeys());
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail != null);

    // 회귀 가드: 카드를 여는 그 순간 `invalidateAgentSessionDockFrame`이 component-local focus를
    // 지운다. 소유권을 그 node id로 판정하면 여기서 도크가 키보드를 잃어 Enter로 다시 접을 수 없다.
    try std.testing.expect(session.agent_session_dock_interaction.focused == null);
    try std.testing.expect(session.agentSessionDockOwnsKeys());
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail == null); // 같은 카드 Enter = 닫기

    // 소유권이 있으면 `/`도 제품 경로대로 도크 검색을 연다.
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '/' }, .modifiers = .{} });
    try std.testing.expect(session.agent_session_archive_search_active);

    // 검색이 활성이면 그쪽이 먼저다 — 같은 소유권에서도 카드 활성화 게이트는 닫힌다.
    try std.testing.expect(!session.agentSessionDockOwnsKeys());
    for ("ab") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqualStrings("ab", session.agent_session_archive_search.query.items);

    // 터미널 본문 클릭은 도크의 keyboard 소유권을 놓는다. `focus_owner`는 도크를 눌러도
    // `.workspace` 그대로라, 이 해제가 없으면 위 게이트가 계속 참으로 남는다.
    const term_rect = session.active_pane_rect;
    session.mouse(1, @floatFromInt(term_rect.x + term_rect.w / 2), @floatFromInt(term_rect.y + term_rect.h / 2), 0, 0);
    try std.testing.expect(!session.agentSessionDockOwnsKeys());
    // 도크 검색도 함께 blur된다(사이드바 `blurSidebarSearch`와 같은 규율 — 검색어는 보존). 이게 없으면
    // `handleAgentSessionArchiveSearchKey`가 터미널로 돌아온 뒤의 모든 키를 계속 삼킨다.
    try std.testing.expect(!session.agent_session_archive_search_active);
    try std.testing.expectEqualStrings("ab", session.agent_session_archive_search.query.items);
    for ("cd") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expectEqualStrings("ab", session.agent_session_archive_search.query.items); // 터미널로 갔다

    // Escape도 같은 게이트다: 카드를 펼쳐 둔 채 터미널에 있으면 vim의 Esc가 도크로 새면 안 된다.
    // 검색어가 남으면 그때 selection이 지워졌으므로(숨은 identity를 선택된 채 두지 않는다) 다시 세운다.
    session.agent_session_archive_search.clear();
    session.rebuildAgentSessionArchiveFilter();
    session.agent_session_archive_selected = 0;
    session.mouse(1, dock_center.x, dock_center.y, 0, 0);
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail != null);
    session.mouse(1, @floatFromInt(term_rect.x + term_rect.w / 2), @floatFromInt(term_rect.y + term_rect.h / 2), 0, 0);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail != null); // Esc는 터미널 것
    // 대조군: 도크가 키보드를 가지면 같은 Esc가 expansion을 닫는다.
    session.mouse(1, dock_center.x, dock_center.y, 0, 0);
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail == null);

    // 뷰를 떠났다 돌아와도 클릭 없이는 소유권이 되살아나지 않는다.
    session.mouse(1, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(session.agentSessionDockOwnsKeys());
    session.setDockView(.explorer);
    session.setDockView(.agent_sessions);
    try std.testing.expect(!session.agentSessionDockOwnsKeys());
    _ = try session.tick();
}

// 적대적 검증 회귀: `⌘↵`/`⌘L`은 chord 모양만 맞으면 published ready expansion이 없어도 키를 삼켰다.
// AppKit 메뉴 keyEquivalent가 있는 액션은 애초에 여기 오지 않지만(그건 메뉴가 먼저 실행), 메뉴 항목이
// 없는 액션 바인딩과 터미널 매크로(`keybind = Cmd+L = text:…`)는 이 블록에서 죽었다. 소비는 실행의
// 결과여야 한다 — 실행할 게 없으면 keybind resolver로 흘려보낸다.
test "도크 ⌘ 단축키는 실제로 실행할 때만 키를 소비한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    // 사용자 keybind 주입: 도크 단축키와 같은 chord에 앱 액션을 묶는다(빈 resolver였다면 Cmd는 ignored).
    var user_binds = [_]config_mod.AppBinding{
        .{ .chord = try config_mod.KeyChord.parse("Cmd+L"), .action = .new_term },
    };
    session.loaded_config.keybindings = &user_binds;

    // 펼친 카드가 없다 = 도크가 실행할 것이 없다 → 사용자 바인딩이 살아 있어야 한다.
    try std.testing.expect(session.agent_session_inline_detail == null);
    const before = session.activePane().terms.items.len;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(before + 1, session.activePane().terms.items.len);

    // 대조군: ready expansion이 있으면 도크가 먼저 가져간다(문서화된 `⌘L` = 로그 보기). 이때는 사용자
    // 바인딩이 실행되지 않아야 한다 — 게이트가 vacuous하지 않다는 뜻이다.
    try appendFixtureArchiveRecord(session, allocator);
    session.agent_session_archive_selected = 0;
    const dock_center = dockContentCenter(session);
    session.mouse(1, dock_center.x, dock_center.y, 0, 0);
    _ = try session.handleKeyEvent(.{ .key = .enter, .modifiers = .{} });
    try std.testing.expect(session.agent_session_inline_detail != null);
    // loading 상태는 아직 ready가 아니므로 이 시점의 ⌘L도 여전히 사용자 바인딩으로 흘러야 한다.
    try std.testing.expect(session.agent_session_inline_detail.?.state != .ready);
    const before_loading = session.activePane().terms.items.len;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'l' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(before_loading + 1, session.activePane().terms.items.len);
    _ = try session.tick();
}

test "라이브 사이드바 카드 드래그는 도크 위를 지나도 소유권을 지키고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .right);
    defer allocator.destroy(session);
    defer session.deinit();

    _ = try session.newTab(); // 카드 2장
    session.recomputeVisibleTabs();
    const card_x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const card_top = chrome.components.sidebar.rowTop(session.sidebar_rows.items, 0, session.sidebar_header_height_px, session.sidebarMetrics(), 0);
    const card_y: f64 = @floatFromInt(card_top + @as(i64, @intCast(chrome.components.sidebar.rowHeight(session.sidebar_rows.items[0], session.sidebarMetrics()) / 2)));

    session.mouse(1, card_x, card_y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    const origin = session.pointer_gesture_owner.sidebar_tab.index;

    const dock_center = dockContentCenter(session);
    session.mouse(2, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.sidebar_tab));
    try std.testing.expectEqual(origin, session.pointer_gesture_owner.sidebar_tab.index);
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.sidebar_tab));
    _ = try session.tick();
}

// 우측 도크는 경계 divider zone이 우측 스크롤바 위를 덮어 down 자체가 `dock_outer_divider`로 간다(별개 축).
// 스크롤바 라우팅만 격리하려고 도크를 아래에 연다.
test "라이브 스크롤바 thumb 드래그는 도크 위를 지나도 소유권을 지키고 up에서 풀린다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try initDockedRoutingSession(allocator, .bottom);
    defer allocator.destroy(session);
    defer session.deinit();

    // 스크롤바는 스크롤백이 있어야 존재한다.
    for (0..200) |i| {
        var buf: [32]u8 = undefined;
        const line = try std.fmt.bufPrint(&buf, "line {d}\r\n", .{i});
        try session.activeSurface().core.write(line);
    }
    const rect = session.active_pane_rect;
    const grab_x: f64 = @floatFromInt(rect.x + rect.w - 2);
    const grab_y: f64 = @floatFromInt(rect.y + rect.h / 2);
    try std.testing.expect(session.scrollbarGrabAt(grab_x, grab_y) != null);

    session.mouse(1, grab_x, grab_y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.scrollbar));

    // 다른 네 gesture와 달리 이동 지표(offset 변화)는 쓰지 않는다. 우측 도크는 경계 divider zone이 스크롤바
    // 위를 덮어 down 자체가 안 되고, 하단 도크는 content가 트랙의 세로 범위 밖이라 clamp 결과가 down이 만든
    // 값과 같아질 수 있다. 소유권 유지와 **up 해제**만으로 도크 가로채기를 고정한다 — 가로채이면 up이 도크로
    // 가서 owner가 armed로 남는다.
    const dock_center = dockContentCenter(session);
    session.mouse(2, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(session.pointerGestureIs(.scrollbar));
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);

    session.mouse(3, dock_center.x, dock_center.y, 0, 0);
    try std.testing.expect(!session.pointerGestureIs(.scrollbar));
    _ = try session.tick();
}

// Session Dock 검색은 사이드바 검색과 같은 성격의 chrome 텍스트 입력이다. `InputFocus`에만 넣고
// `terminalOwnsInput`에서 빠지면 Zig는 키를 도크로 라우팅하는데 `reconcileWebFocus`는 override 없이
// 활성 web term의 WKWebView를 firstResponder로 되돌려(매 renderTick self-heal) 검색 키가 웹뷰로 샌다.
// 두 검색이 같은 답을 내는지 대칭으로 고정하고, 게이트(도크 가시성·뷰 종류)도 함께 검증한다.
test "Session Dock 검색은 사이드바 검색과 같은 입력 소유 판정을 낸다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(1600, 900, 1000);

    session.dock.presented = true;
    session.dock.collapsed = false;
    session.dock.side = .right;
    session.agent_session_archive_initialized = false;
    session.setDockView(.agent_sessions);
    session.agent_session_archive_initialized = true;
    try std.testing.expect(session.dockVisible());
    try std.testing.expect(!session.terminalOwnsInput());
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // 도크가 키보드를 갖기 전의 `/`는 터미널 입력이다 — 도크 검색을 열지 않는다(경로·정규식 타이핑 보호).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '/' }, .modifiers = .{} });
    try std.testing.expect(!session.agent_session_archive_search_active);
    try std.testing.expect(!session.terminalOwnsInput());

    // 제품에서는 도크 안 primary down이 이 소유권을 준다(`takeAgentSessionDockKeyFocus`). 이 테스트는
    // 입력 소유 판정만 보므로 그 결과 상태만 세우고 같은 `/` 제품 키 경로로 검색을 연다.
    session.agent_session_dock_key_focus = true;
    _ = try session.handleKeyEvent(.{ .key = .{ .char = '/' }, .modifiers = .{} });
    try std.testing.expect(session.agent_session_archive_search_active);
    try std.testing.expect(session.terminalOwnsInput());
    try std.testing.expectEqual(AppSession.InputFocus.agent_session_search, session.inputFocus());

    // 타이핑도 같은 경로로 들어가고, override는 유지된다.
    for ("maru") |c| _ = try session.handleKeyEvent(.{ .key = .{ .char = c }, .modifiers = .{} });
    try std.testing.expect(session.terminalOwnsInput());

    // Escape로 닫으면 override도 함께 풀린다.
    _ = try session.handleKeyEvent(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.agent_session_archive_search_active);
    try std.testing.expect(!session.terminalOwnsInput());
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // 사이드바 검색과 대칭.
    session.sidebar_search_active = true;
    try std.testing.expect(session.terminalOwnsInput());
    try std.testing.expectEqual(AppSession.InputFocus.sidebar_search, session.inputFocus());
    session.sidebar_search_active = false;
    try std.testing.expect(!session.terminalOwnsInput());

    // 게이트: 플래그가 남아 있어도 도크가 안 보이거나 다른 뷰면 입력을 요구하지 않는다. 이 방어는
    // 아래 blur가 플래그를 실제로 지우게 된 뒤에도 유지한다(두 겹 — 상태와 게이트).
    session.agent_session_archive_search_active = true;
    session.dock.collapsed = true;
    try std.testing.expect(!session.dockVisible());
    try std.testing.expect(!session.terminalOwnsInput());
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    session.dock.collapsed = false;
    session.setDockView(.explorer);
    try std.testing.expect(!session.terminalOwnsInput());
    // view 전환은 도크 검색을 blur한다 — 돌아왔을 때 클릭 없이 키를 삼키지 않게(사이드바와 같은 규율).
    try std.testing.expect(!session.agent_session_archive_search_active);

    session.setDockView(.agent_sessions);
    try std.testing.expect(!session.terminalOwnsInput());
    session.agent_session_archive_search_active = true;
    try std.testing.expect(session.terminalOwnsInput());
    _ = try session.tick();
}

// ── 입력 소유 두 축의 parity 가드 ────────────────────────────────────────────────────────────────
// keyboard 소유는 두 축이 나눠 갖는다: `terminalOwnsInput`(host가 first responder를 터미널 뷰에 둘지 —
// Swift `reconcileWebFocus`의 override 단일 출처)과 `InputFocus`(Zig 안에서 키/확정 텍스트를 어느 chrome
// 소비자에게 보낼지). 한쪽에만 소비자를 추가하면 Zig는 키를 라우팅하는데 host는 first responder를
// 되돌려 입력이 어긋난다 — Session Dock 검색이 실제로 그랬다(`f22be41e`).
//
// **두 축을 하나로 합치지는 않는다.** 집합이 다르고(`context_menu`·`notifications`는 `terminalOwnsInput`에만
// 있다 — 텍스트를 안 받으니 `InputFocus` 값이 아니다), 동시 활성일 때 답도 달라야 한다(rename 편집 중
// 토스트가 뜨면 `inputFocus`는 `.notice`지만 rename이 살아 있으므로 override는 참이어야 한다). 우선순위
// 체인에서 파생시키면 그 조합에서 틀린 답을 낸다.
//
// 그래서 구조 대신 **기대표**로 강제한다. `InputFocus`에 값이 늘면 이미 제품 switch 네 곳(preedit 대상·
// 조합 여부·caret rect·확정 처리)이 컴파일을 멈춘다. 그런데 `terminalOwnsInput`은 switch가 아니라 or
// 체인이라 그 멈춤 목록에 없었고, 실제로 도크 검색이 그 틈으로 빠졌다. 아래 두 switch가 그 목록에
// **host override 기대값**을 더해, 새 값을 채울 때 "이 소비자는 first responder를 요구하는가"를 반드시
// 답하게 한다. 반대 방향(모달을 `anyModalOverlayOpen`에만 더하는 경우)은 이 가드의 범위 밖이다.

/// `InputFocus` 값이 단독으로 활성일 때 host override(`terminalOwnsInput`)가 참이어야 하는가.
fn expectedTerminalResponder(focus: AppSession.InputFocus) bool {
    return switch (focus) {
        // 터미널이 키를 갖는 기본 상태.
        .terminal => false,
        // 지나가는 토스트는 텍스트/IME를 받지 않으므로 웹 포커스를 뺏지 않는다(14차 리뷰 [3]).
        .notice => false,
        .confirm,
        .settings,
        .rename,
        .sidebar_search,
        .agent_session_search,
        .find,
        .palette,
        .addr_edit,
        .file_tree,
        .dock_pending,
        => true,
    };
}

/// 그 focus 하나만 활성인 상태를 만든다. 만들 수 없으면 false(사유를 여기 남긴다).
fn activateSoleFocus(session: *AppSession, focus: AppSession.InputFocus) bool {
    switch (focus) {
        .terminal => {},
        .confirm => session.chrome_host.confirm.open = true,
        .notice => session.chrome_host.notice.open = true,
        .settings => session.chrome_host.settings.open = true,
        .find => session.chrome_host.find.open = true,
        .palette => session.chrome_host.palette.open = true,
        .rename => session.startRename(.{ .workspace = session.tabs.items[0] }),
        .sidebar_search => session.sidebar_search_active = true,
        .addr_edit => session.addr_edit = 1,
        .file_tree => session.focus_owner = .{ .file_tree = .{ .restore_surface = null } },
        .agent_session_search => {
            session.dock.presented = true;
            session.dock.collapsed = false;
            session.dock.side = .right;
            session.agent_session_archive_initialized = false;
            session.setDockView(.agent_sessions);
            session.agent_session_archive_initialized = true;
            session.agent_session_archive_search_active = true;
        },
        // pending dock focus는 live entry + async epoch가 맞아야 참이 된다(`pendingDockEntryOwnsInput`).
        // 그 조합은 파일 패널 fixture가 소유하므로 여기서는 만들지 않는다 — 기대표에는 남아 있어
        // `InputFocus`가 늘어날 때의 컴파일 강제는 그대로다.
        .dock_pending => return false,
    }
    return true;
}

test "InputFocus의 모든 값이 terminalOwnsInput 기대와 일치한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    inline for (std.meta.fields(AppSession.InputFocus)) |field| {
        const focus: AppSession.InputFocus = @enumFromInt(field.value);
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        session.window_padding_px = .{};
        _ = try session.resize(1600, 900, 1000);

        if (activateSoleFocus(session, focus)) {
            try std.testing.expectEqual(focus, session.inputFocus());
            try std.testing.expectEqual(expectedTerminalResponder(focus), session.terminalOwnsInput());
        }
        _ = try session.tick();
    }
}

// 위 parity 가드는 각 `InputFocus` 값을 **단독으로** 켠다. 그것만으로는 `terminalOwnsInput`이 합집합인지
// 우선순위 파생인지 구별되지 않는다 — 단독 활성에서는 두 방식의 답이 같기 때문이다. 이 테스트가 그
// 구별을 고정한다.
//
// rename 편집 중 토스트가 뜨는 조합은 실제로 만들어진다. `showNotice`의 `dismissMessageOverlays`는
// notice·find·palette·context_menu·settings를 닫지만 rename은 닫지 않고, `startRename`도 find·palette만
// 닫는다. 그래서 두 순서 모두 공존 상태가 된다.
//
// 그 상태에서 `inputFocus`는 우선순위상 `.notice`(override 불필요)지만 host override는 **참**이어야 한다.
// 토스트는 아무 입력으로나 닫히므로 첫 키가 notice를 닫고 rename 편집이 이어져야 하는데, 그 사이 host가
// 웹뷰로 포커스를 넘기면 그 첫 키조차 웹뷰로 가서 notice도 안 닫히고 rename도 진행되지 않는다.
// 따라서 `terminalOwnsInput`을 `inputFocus()`에서 파생시키면 이 조합에서 틀린 답을 낸다.
test "동시 활성일 때 host override는 우선순위 파생이 아니라 합집합이다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // (1) rename 먼저, 그 위에 토스트.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        session.window_padding_px = .{};
        _ = try session.resize(1600, 900, 1000);

        session.startRename(.{ .workspace = session.tabs.items[0] });
        try std.testing.expect(session.rename != null);
        session.showNotice("작업공간 경로 분석을 시작하지 못했습니다.");

        // 토스트가 rename을 닫지 않아 둘 다 살아 있다.
        try std.testing.expect(session.chrome_host.notice.open);
        try std.testing.expect(session.rename != null);
        // 우선순위는 notice지만(그 값 단독이면 override 불필요),
        try std.testing.expectEqual(AppSession.InputFocus.notice, session.inputFocus());
        try std.testing.expect(!expectedTerminalResponder(session.inputFocus()));
        // 합집합이라 rename 때문에 참이어야 한다.
        try std.testing.expect(session.terminalOwnsInput());
        _ = try session.tick();
    }

    // (2) 토스트 먼저, 그 위에 rename — `startRename`도 notice를 닫지 않는다.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 20,
            .rows = 5,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        session.window_padding_px = .{};
        _ = try session.resize(1600, 900, 1000);

        session.showNotice("현재 터미널의 로컬 git 프로젝트를 찾을 수 없습니다.");
        session.startRename(.{ .workspace = session.tabs.items[0] });
        try std.testing.expect(session.chrome_host.notice.open);
        try std.testing.expect(session.rename != null);
        try std.testing.expectEqual(AppSession.InputFocus.notice, session.inputFocus());
        try std.testing.expect(session.terminalOwnsInput());
        _ = try session.tick();
    }
}

// ── 반대 방향 가드: chrome_host 컴포넌트 ↔ 입력 소유 두 축 ──────────────────────────────────────
// 앞의 두 가드는 `InputFocus`에서 출발한다. 반대 방향 — **새 오버레이를 `chrome_host`에 추가하면서
// `InputFocus`에 넣지 않는 것** — 은 잡지 못했다. `ChromeHost`는 평범한 struct라 필드를 늘려도 컴파일이
// 멈추지 않기 때문이다. 그 방향의 사고는 실제로 있었다: `c822b336` 이전에는 settings가
// `anyOverlayOpen`에는 있는데 `inputFocus`에 없어, 세팅 검색어가 뒤 터미널로 샜다.
//
// 여기서는 `ChromeHost`의 필드를 `FieldEnum`으로 뽑아 각 컴포넌트의 역할을 exhaustive switch로 못 박는다.
// 필드를 추가하면 이 switch가 컴파일을 멈추고, 역할을 `routes_text`나 `transient_toast`로 적으면 아래
// comptime 검사가 **같은 이름의 `InputFocus` 값**을 요구한다. 두 축 중 하나만 갱신하고 지나갈 수 없다.
//
// 두 집합을 같게 만들려는 게 아니다. `context_menu`·`notifications`는 입력을 막지만 텍스트를 받지 않아
// `InputFocus` 값이 없고, `notice`는 값이 있지만 override는 안 건다 — 그 차이를 지우지 않고 **역할로
// 분류해 등재**한다.

test "chrome_host 오버레이는 역할대로 입력 소유 두 축에 반영된다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    @setEvalBranchQuota(10_000);
    inline for (std.meta.fields(ChromeHostField)) |field| {
        const role = comptime modalInputRole(@as(ChromeHostField, @enumFromInt(field.value)));
        if (comptime role != .not_an_overlay) {
            const session = try allocator.create(AppSession);
            defer allocator.destroy(session);
            try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
                .abi_version = abi_version,
                .cols = 20,
                .rows = 5,
                .queue_capacity = 16,
                .command_kind = @intFromEnum(CommandKind.controlled_smoke),
            });
            defer session.deinit();
            session.window_padding_px = .{};
            _ = try session.resize(1600, 900, 1000);
            try std.testing.expect(!session.terminalOwnsInput());

            @field(session.chrome_host, field.name).open = true;
            switch (comptime role) {
                .routes_text => |focus| {
                    // 텍스트를 받는 오버레이는 키가 Zig 경로여야 하므로 host override가 참이고,
                    // `inputFocus`도 등재된 그 값을 가리켜야 한다(매핑이 틀리면 여기서 깨진다).
                    try std.testing.expect(session.terminalOwnsInput());
                    try std.testing.expectEqual(focus, session.inputFocus());
                },
                .blocks_without_text => {
                    // 입력을 막으므로 override는 참이지만 텍스트 소비자가 아니라 `InputFocus` 값은 없다.
                    try std.testing.expect(session.terminalOwnsInput());
                },
                .transient_toast => |focus| {
                    // 토스트는 웹 포커스를 뺏지 않는다. `InputFocus`는 등재된 값을 가리킨다.
                    try std.testing.expect(!session.terminalOwnsInput());
                    try std.testing.expectEqual(focus, session.inputFocus());
                },
                .not_an_overlay => unreachable,
            }
            _ = try session.tick();
        }
    }
}

// 이 테스트가 증명하는 것: Session Dock 스크롤바 드래그의 **소비 지점이 tick**이고, 그 한 번이
// coalescing된 마지막 좌표만 적용한다.
//
// 왜 중요한가 — pointer move는 tick보다 훨씬 자주 온다. 매 move마다 offset을 적용하면 한 프레임
// 안에서 같은 재투영을 여러 번 하고, 반대로 tick에서 소비하지 않으면 손을 뗄 때까지 목록이 안 움직여
// "놓아야 스크롤되는" 스크롤바가 된다(파일 탐색기에서 실제로 겪은 회귀 — 9ec9520e).
test "세션 도크 스크롤바 드래그는 move 수가 아니라 tick 수만큼 스크롤한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 스크롤할 것이 있어야 스크롤바가 성립한다. 카드 서른 장이면 어떤 도크 높이에서도 넘친다.
    for (0..30) |index| {
        try session.agent_session_archive_projection.entries.append(allocator, .{ .card = index });
    }
    const projection = session.agentSessionDockScrollProjection();
    try std.testing.expect(projection.max_offset_px > 0);

    // down 시점의 기하를 직접 만든다. 실제 경로에서는 published tree에서 되읽지만, 이 테스트가 고정하려는
    // 것은 그 기하가 아니라 **소비 지점**이다.
    const geometry = chrome.ui.scroll_area.ScrollbarGeometry{
        .track_x = 100,
        .track_y = 0,
        .track_w = 16,
        .track_h = 400,
        .thumb_y = 0,
        .thumb_h = 40,
        .max_offset_px = projection.max_offset_px,
    };
    session.agent_session_dock_scroll_drag = .{ .grab_dy = 0, .geometry = geometry };

    // 한 프레임 안에서 move 다섯 번.
    var step: f64 = 1;
    while (step <= 5) : (step += 1) session.agent_session_dock_scroll_coalescer.absorb(100, step * 20);

    // tick 전에는 아직 아무것도 적용되지 않았다 — move가 직접 스크롤을 옮기면 이 단언이 깨진다.
    try std.testing.expectEqual(@as(u32, 0), session.agent_session_archive_scroll.offset_y_px);

    session.applyAgentSessionDockScrollDrag();
    const after_first_tick = session.agent_session_archive_scroll.offset_y_px;
    // 마지막 좌표(y=100) 하나만 적용된다.
    try std.testing.expectEqual(geometry.offsetForPointer(100, 0), after_first_tick);
    try std.testing.expect(after_first_tick > 0);

    // 남은 좌표가 없으면 다음 tick은 아무 일도 하지 않는다(같은 값을 다시 적용하지 않는다).
    session.applyAgentSessionDockScrollDrag();
    try std.testing.expectEqual(after_first_tick, session.agent_session_archive_scroll.offset_y_px);

    // 트랙 끝에 닿은 채 계속 밀어도 clamp 결과가 같으면 effect가 반복되지 않는다.
    session.agent_session_dock_scroll_coalescer.absorb(100, 100_000);
    session.applyAgentSessionDockScrollDrag();
    const at_end = session.agent_session_archive_scroll.offset_y_px;
    try std.testing.expectEqual(projection.max_offset_px, at_end);
    session.agent_session_dock_scroll_coalescer.absorb(100, 200_000);
    session.applyAgentSessionDockScrollDrag();
    try std.testing.expectEqual(at_end, session.agent_session_archive_scroll.offset_y_px);

    // 드래그가 끝나면 남은 좌표가 다음 드래그로 새지 않는다.
    session.agent_session_dock_scroll_coalescer.absorb(100, 7);
    session.endAgentSessionDockScrollDrag();
    try std.testing.expect(session.agent_session_dock_scroll_drag == null);
    session.applyAgentSessionDockScrollDrag();
    try std.testing.expectEqual(at_end, session.agent_session_archive_scroll.offset_y_px);
}

// 이 테스트가 증명하는 것: 스크롤바 thumb을 끄는 동안 도크 tree가 매 프레임 새로 발행돼도 capture가
// 살아남고, 반대로 archive snapshot이 교체되면 끊긴다.
//
// 왜 중요한가 — thumb을 끌면 thumb rect가 바뀌므로 tree는 **반드시** 매 프레임 새로 발행된다. 도크의
// 기본 `reconcile`은 tree 교체에서 언제나 capture를 취소하므로(그것이 click의 안전한 기본값이다),
// 그 경로 위에서는 드래그가 첫 move에 죽어 "눌러도 끌리지 않는" 스크롤바가 된다(사용자 보고).
test "세션 도크 스크롤바 드래그는 매 프레임 tree 재발행을 견딘다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const dock_build = chrome.components.session_dock.build;
    const Ids = chrome.components.session_dock.ids;

    // thumb 하나만 있는 최소 tree. 이 테스트가 고정하려는 것은 carry 판정이지 도크 layout이 아니다.
    const thumb_action_id: u64 = 1;
    var actions: [1]Ids.Entry = undefined;
    var table = Ids.Table.init(&actions);
    const published_action = try table.append(7, .scroll_thumb, true);

    const thumbEntry = struct {
        fn make(action: chrome.ui.tree.UiAction, y: f32) chrome.ui.tree.RectEntry {
            return .{
                .id = dock_build.NodeIds.scroll_thumb,
                .parent_index = null,
                .kind = .card,
                .rect = .{ .x = 100, .y = y, .width = 16, .height = 40 },
                .effective_clip = null,
                .action = action,
                .drag = .{ .payload = dock_build.scroll_drag_payload, .axis = .vertical, .threshold_px = 0 },
                .visual = .{ .card = .{ .variant = .surface, .paint = .{} } },
            };
        }
    }.make;
    _ = thumb_action_id;

    var first = [_]chrome.ui.tree.RectEntry{thumbEntry(published_action, 0)};
    session.publishAgentSessionDockFrame(.{ .tree = .{ .entries = &first }, .actions = table.slice() }, 7);
    try std.testing.expectEqual(@as(usize, 1), session.agent_session_dock_entries.items.len);

    // thumb을 누른 상태를 만든다(실제 경로에서는 pointer down이 세운다).
    session.agent_session_dock_interaction.capture = .{
        .id = dock_build.NodeIds.scroll_thumb,
        .action_id = published_action.id,
        .drag = .{
            .payload = dock_build.scroll_drag_payload,
            .axis = .vertical,
            .threshold_px = 0,
            .origin_x_px = 100,
            .origin_y_px = 10,
            .last_x_px = 100,
            .last_y_px = 10,
            .started = true,
        },
    };

    // 끌면 thumb이 내려간다 = 새 tree. 같은 generation이면 capture가 살아남아야 한다.
    var moved = [_]chrome.ui.tree.RectEntry{thumbEntry(published_action, 120)};
    session.publishAgentSessionDockFrame(.{ .tree = .{ .entries = &moved }, .actions = table.slice() }, 7);
    try std.testing.expect(session.agent_session_dock_interaction.capture != null);
    try std.testing.expectEqual(@as(f32, 120), session.agent_session_dock_entries.items[0].rect.y);

    // archive snapshot이 교체되면(generation 변경) 목록 길이 자체가 달라지므로 이어갈 근거가 없다.
    // 이때는 capture를 끊고 host의 drag 상태도 함께 정리해야 다음 down이 grab 지점을 새로 잡는다.
    session.agent_session_dock_scroll_drag = .{
        .grab_dy = 10,
        .geometry = .{ .track_x = 100, .track_y = 0, .track_w = 16, .track_h = 400, .thumb_y = 120, .thumb_h = 40, .max_offset_px = 500 },
    };
    var replaced = [_]chrome.ui.tree.RectEntry{thumbEntry(published_action, 200)};
    session.publishAgentSessionDockFrame(.{ .tree = .{ .entries = &replaced }, .actions = table.slice() }, 8);
    try std.testing.expect(session.agent_session_dock_interaction.capture == null);
    try std.testing.expect(session.agent_session_dock_scroll_drag == null);
}

// 이 테스트가 증명하는 것: 도크 view bar의 높이와 그 아래 content 시작선이 **도크 뷰와 터미널 폰트에
// 모두 무관**하다.
//
// 왜 터미널에서 중요한가 — view bar는 도크가 소유한 chrome이다. 예전에는 explorer/source-control만
// terminal pane tab bar와 높이를 맞췄고(셀 높이 + padding), 그 결과 같은 아이콘 세 개가 AI 세션으로
// 바꿀 때마다 위아래로 뛰었다(사용자 보고: 실측 53px ↔ 80px). 더 나쁜 것은 그 식에 terminal cell이
// 들어 있어 **폰트 크기를 바꾸면 도크 아이콘 줄이 따라 움직였다**는 점이다 —
// docs/layering-and-portability.md가 막으려는 방향이다.
test "도크 view bar와 시작선은 뷰와 무관하고 터미널 셀에서 나오지 않는다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 80,
        .rows = 24,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.resize(1920, 1200, 2000);
    session.dock_initialized = true;
    session.dock.presented = true;

    const expected_h = chrome.components.session_dock.types.DockMetrics.resolve(session.agentSessionDockScaleMilli()).view_switcher_h;

    session.dock.view = .explorer;
    const explorer = session.dockGeometry();
    session.dock.view = .agent_sessions;
    const agent = session.dockGeometry();

    try std.testing.expect(expected_h > 0);
    try std.testing.expectEqual(expected_h, explorer.view_bar.h);
    try std.testing.expectEqual(expected_h, agent.view_bar.h);
    // 아이콘 줄과 그 아래 본문 시작선이 뷰 전환에서 한 픽셀도 움직이지 않는다.
    try std.testing.expectEqual(explorer.view_bar.y, agent.view_bar.y);
    try std.testing.expectEqual(explorer.view_bar.h, agent.view_bar.h);
    try std.testing.expectEqual(explorer.tree.y, agent.tree.y);

    // 그리고 그 값은 terminal pane tab bar가 아니다 — 옛 explorer 경로가 쓰던 식이 살아 있으면 여기서
    // 걸린다(기본 설정에서 80px vs 53px).
    try std.testing.expect(expected_h != session.paneBarHeightPx());

    // `Cmd`+`+`/`-`의 명시적 zoom은 **의도적으로** 도크 전체를 함께 확대한다(docs/agent-session-list.md
    // §2.1.1의 `SessionDockUiZoom`). 그러므로 여기서 고정할 것은 "안 변한다"가 아니라 **두 뷰가 같은
    // Chrome metric을 계속 따라간다**는 쪽이다.
    const cell_before = session.cell_height_px;
    session.setFontSize(session.appearance.font.size + 8);
    try std.testing.expect(session.cell_height_px != cell_before);
    const zoomed_h = chrome.components.session_dock.types.DockMetrics.resolve(session.agentSessionDockScaleMilli()).view_switcher_h;
    try std.testing.expect(zoomed_h != expected_h); // zoom이 실제로 걸렸다(단언이 공허하지 않다)
    session.dock.view = .explorer;
    const zoomed_explorer = session.dockGeometry();
    session.dock.view = .agent_sessions;
    const zoomed_agent = session.dockGeometry();
    try std.testing.expectEqual(zoomed_h, zoomed_explorer.view_bar.h);
    try std.testing.expectEqual(zoomed_h, zoomed_agent.view_bar.h);
    try std.testing.expectEqual(zoomed_explorer.tree.y, zoomed_agent.tree.y);
}
